/**
 * The factions' missions (docs/factions.html): a repeatable job for each faction, posted at its hall once the
 * player is its Friend, and each faction's Oath — five steps, posted one at a time once the bar stands at
 * 9,999, every one begun in the faction's Honoured vehicle at the hall (the first objective is getting
 * there in it), and one of the five worked against a faction it opposes or contests. The fifth step makes
 * the player Sworn (game/factions/reputation.ts oathStep, from the mission's end in factions/wire.ts).
 */
import type { Site } from '../cargo';
import { cargoById } from '../cargoTypes';
import { FACTIONS, OATH_AT, RUNG, type FactionId } from '../factions/factions';
import { reputation } from '../factions/reputation';
import type { MissionCtx, Missions } from './missions';
import type { Arc, Giver, HeroSpec, Obj, Reward } from './model';
import { carry, findSpot, meet, siteAt, siteNear, the, type Spot } from './story/kit';
import { siteRef, townRef, type Draft, type Template } from './templates';

type Pt = { x: number; z: number };

/** What a faction's people are called on a card. */
export const GIVER: Record<FactionId, { who: string; name: string }> = {
  police: { who: 'police', name: 'Detective Sergeant Rourke' },
  family: { who: 'smuggler', name: 'Mr. Benedetti' },
  ministry: { who: 'ministry', name: 'The Permanent Secretary' },
  visitors: { who: 'visitors', name: 'The Envoy' },
  unions: { who: 'unions', name: 'Shop Steward Mags Doyle' },
  post: { who: 'post', name: 'Postmaster Ivy Penhallow' },
  army: { who: 'army', name: 'Quartermaster Sgt. Okafor' },
  studios: { who: 'studio', name: 'Producer Dash Delano' },
  guild: { who: 'harbour', name: 'Harbourmaster Brennock' },
  press: { who: 'reporter', name: 'Editor Cass Marlow' },
};

const crate = (colour: number): HeroSpec => ({ kind: 'crate', colour });
export const hero = (f: FactionId, s: Spot | null): HeroSpec =>
  s?.b ? { kind: 'building', b: s.b.kind, arch: s.b.style ?? s.town?.style ?? 'classic', w: s.b.w, d: s.b.d, floors: s.b.floors } : crate(FACTIONS[f].colour);
const here = (c: MissionCtx): Pt => ({ x: c.at.x, z: c.at.z });
const name = (k: string) => the(k);

/** The faction's hall nearest the player: where its giver waits. */
export function hall(c: MissionCtx, f: FactionId, max = 260): Spot | null {
  return findSpot(c, FACTIONS[f].hall, here(c), max, name);
}

export const giverAt = (f: FactionId, s: Spot): Giver => ({ who: GIVER[f].who, name: GIVER[f].name, at: s.at, town: s.town ? townRef(s.w, s.town) : null });
const giverSite = (f: FactionId, s: Site): Giver => ({ who: GIVER[f].who, name: GIVER[f].name, at: siteRef(s), town: null });

/** A delivery of a faction's load from the nearest of `from` to one of `to` a fair drive on. */
export function job(c: MissionCtx, cargo: string, from: string[], to: string[], n = 1, near?: Pt): Obj | null {
  const a = siteNear(c, from, near ?? here(c), 0, 180);
  const b = a && siteNear(c, to, a, 18, 260, [a]);
  return a && b ? carry(cargo, a, b, n) : null;
}

const cash = (n: number): Reward => ({ r: 'cash', n });

