/** Three of a faction's places after dark, a few minutes at each. */
function nightRound(c: MissionCtx, s: Spot, kinds: string[]): (Obj | null)[] {
  const out: Spot[] = [];
  for (let k = 0; k < 3; k++) {
    const p = findSpot(c, kinds, out[k - 1] ?? s, 260, name, [s, ...out]);
    if (!p) break;
    out.push(p);
  }
  if (out.length < 2) return [null];
  return out.map((p, k) => meet(p, ['Visit the station after dark', 'Visit the next station', 'Visit the last station'][k], '🚓', { when: 'night', hold: 6 }));
}

const arcId = (f: FactionId) => `oath-${f}`;
const oathTpl = (f: FactionId, i: number) => `oath:${f}:${i + 1}`;

/** The Oath's step a template id is, or null. */
export function oathOf(tpl: string): { f: FactionId; i: number } | null {
  const m = /^oath:([a-z]+):(\d)$/.exec(tpl);
  return m && m[1] in FACTIONS ? { f: m[1] as FactionId, i: Number(m[2]) - 1 } : null;
}

/** How far off an Oath's hall may be: it is the one mission a faction offers at 9,999, so worth a drive. */
const OATH_REACH = 1200;

/** The faction's halls of each kind nearest the player, out to OATH_REACH, nearest first. */
function oathHalls(c: MissionCtx, f: FactionId): Spot[] {
  const out: Spot[] = [];
  for (const k of FACTIONS[f].hall) {
    const s = findSpot(c, [k], here(c), OATH_REACH, name);
    if (s) out.push(s);
  }
  return out.sort((a, b) => Math.hypot(a.at.x - c.at.x, a.at.z - c.at.z) - Math.hypot(b.at.x - c.at.x, b.at.z - c.at.z));
}

function oathStep(f: FactionId, i: number): Template {
  const d = FACTIONS[f];
  const ride = d.unlocks[1].model;
  const rideName = d.unlocks[1].name;
  return {
    id: oathTpl(f, i), thread: 'town', kind: 'job', arc: arcId(f),
    gate(c: MissionCtx, ms: Missions) {
      if ((ms.arcs?.get(arcId(f)) ?? 0) !== i) return 'not its turn';
      if (reputation.sworn(f)) return 'sworn already';
      if (!reputation.oathOpen(f)) return `${d.name} must count you Honoured to ${OATH_AT.toLocaleString('en-GB')}`;
      if (!c.units.some((u) => u.model === ride)) return `needs the ${rideName}`;
      return null;
    },
    bind(c: MissionCtx): Draft | null {
      // the nearest hall where this step can happen, out to OATH_REACH: not only the nearest hall (one with no bus
      // station or crash site in reach left the Army's Oath never posted); failing every hall, one of the faction's
      // own jobs from there stands in for the step, so an Oath is never stuck on a county's geography
      const step = OATHS[f][i];
      let s: Spot | null = null, objs: (Obj | null)[] = [];
      const halls = oathHalls(c, f);
      for (const h of halls) {
        objs = step.build(c, h);
        if (objs.every((o) => !!o)) { s = h; break; }
      }
      if (!s) {
        for (const h of halls) {
          const o = JOBS[f].map((j) => job(c, j.cargo, j.from, j.to, 1, h)).find((x) => !!x);
          if (o) { s = h; objs = [o]; break; }
        }
      }
      if (!s) return null;
      const start: Obj = { t: 'reach', label: `Bring the ${rideName}`.slice(0, 28), icon: d.icon, at: s.at, r: 6, ride: { ids: [ride], label: `the ${rideName}` } };
      return {
        title: `${step.title}`, why: step.why,
        details: `The Oath of ${d.name}, step ${i + 1} of 5, begun at their hall in the ${rideName}. ${i === 4 ? 'The last step: done, and they count you Sworn.' : 'Each step done moves you on to the next.'}`,
        giver: giverAt(f, s), hero: { kind: 'vehicle', model: ride }, caption: `${d.icon} The Oath · ${i + 1} of 5`,
        objs: [start, ...(objs as Obj[])], reward: [cash(400 + 200 * i)], hours: 24,
      };
    },
  };
}

export const FACTION_TEMPLATES: Template[] = (Object.keys(FACTIONS) as FactionId[]).flatMap((f) => [factionJob(f), ...[0, 1, 2, 3, 4].map((i) => oathStep(f, i))]);

export const OATH_ARCS: Arc[] = (Object.keys(FACTIONS) as FactionId[]).map((f) => ({
  id: arcId(f), title: `The Oath of ${FACTIONS[f].name}`, thread: 'town', who: GIVER[f].name, tpls: [0, 1, 2, 3, 4].map((i) => oathTpl(f, i)),
}));

void siteAt;
