import * as THREE from 'three';
import { N, STEP, type World } from '../../world/tiles';
import { stadiumPlanOf, stadiumToIsland } from '../../world/stadiums';
import { VEHICLES, halfSize, type AirDef, type LandDef } from '../vehicles';
import { BALLOON_PATTERNS } from '../../render/vehicleMeshes';
import { landRoute } from '../traffic';
import { KIND_OF, type EventKind } from './kinds';
import type { Happening } from './calendar';
import { mid, type Place, type Pt } from './venues';
import { Bulbs, Crowd, Rig, Way, beam, block, dressed, flat } from './props';
import { Closure, HOUR_S, Show, clamp01, lineStreet, toWorld, u01, type ShowCtx } from './shows';

/**
 * Phase 4 (docs/events.html), on the road and on foot: runs from town to town (a vintage rally, a cycle race, a
 * tractor run), processions down a town's streets (a wedding, a royal carriage, Mardi Gras, the Lunar New Year's
 * dragon, a marathon, a march, a market), gatherings on a town's lots (food trucks, a circus, a concert, a harvest
 * fair, balloons, lanterns, a carnival) and the things that happen at a building's front door (an opening, a
 * premiere, a picket line). Each from the world clock.
 */

const CLASSIC = [0xf3e9d2, 0x0b3d2e, 0xc8102e, 0x7fb3d5, 0x111111, 0xf2c14e, 0x6b3a2a, 0xd9d2b0];
const MARDI = [0x6a2c91, 0x1f8a4c, 0xf2b632];
const BRIGHT = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0x8e5cc7, 0xf28c38, 0x2bb3a3, 0xf49ab5];

const hourOf = (h: number) => ((h % 24) + 24) % 24;

// ---- town to town ---------------------------------------------------------------------------------------------------

interface RunSpec {
  /** The vehicles, front to back. */
  units: { id: string; colour?: number }[];
  /** A peloton of this many riders ahead of the vehicles, in these colours. */
  riders?: { n: number; colours: number[] };
  /** Hay carts behind each vehicle. */
  carts?: boolean;
  /** Share of the event spent on the road, the rest gathered at the finish. */
  drive: number;
}
const RUNS: Partial<Record<EventKind, RunSpec>> = {
  vintageRally: { units: ['tomato', 'bramble', 'sunny', 'cab', 'pip', 'limo', 'mule', 'zippy', 'sunny', 'tomato', 'bramble', 'cab'].map((id, i) => ({ id, colour: CLASSIC[i % CLASSIC.length] })), drive: 0.75 },
  cycleRace: { riders: { n: 34, colours: BRIGHT }, units: [{ id: 'cab', colour: 0xf2c14e }, { id: 'cab', colour: 0x2f7fb5 }, { id: 'ambulance' }], drive: 0.8 },
  tractorRun: { units: Array.from({ length: 12 }, (_, i) => ({ id: 'clod', colour: i % 3 ? 0x3f9b4a : 0xc8102e })), carts: true, drive: 0.8 },
};

/**
 * A run from one town's square to another's along the county's roads, crowds at both ends: old cars tooting in
 * their best paint, a peloton with its team cars, a merry line of tractors pulling hay carts.
 */
class RunShow extends Show {
  private spec: RunSpec;
  private way: Way | null = null;
  private rigs: { rig: Rig; off: number }[] = [];
  private riders: Crowd | null = null;
  private bikes: THREE.InstancedMesh | null = null;
  private carts: THREE.InstancedMesh | null = null;
  private crowd: Crowd;
  private lead = 0;
  private m = new THREE.Matrix4();
  private q = new THREE.Quaternion();
  private s = new THREE.Vector3(1, 1, 1);
  private v = new THREE.Vector3();
  private up = new THREE.Vector3(0, 1, 0);

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    this.spec = RUNS[e.kind]!;
    let off = 0;
    if (this.spec.riders) {
      const n = this.spec.riders.n;
      this.riders = new Crowd(this.g, ctx.ground, 0, this.spec.riders.colours);
      this.riders.manual = true;
      for (let i = 0; i < n; i++) this.riders.add(0, 0);
      this.bikes = new THREE.InstancedMesh(new THREE.BoxGeometry(0.02, 0.05, 0.14), flat(0x222428), n);
      this.bikes.frustumCulled = false;
      this.g.add(this.bikes);
      off = Math.ceil(n / 5) * 0.2 + 0.8;
      this.lead = off;
    }
    for (const u of this.spec.units) {
      const def = dressed(u.id, u.colour);
      const half = halfSize(def)[0];
      off += half;
      this.rigs.push({ rig: new Rig(this.g, def), off });
      off += half + (this.spec.carts ? 0.9 : 0.55);
    }
    if (this.spec.carts) {
      this.carts = new THREE.InstancedMesh(new THREE.BoxGeometry(0.3, 0.16, 0.4), flat(0xe8c766), this.rigs.length);
      this.carts.frustumCulled = false;
      this.g.add(this.carts);
    }
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    const a = toWorld(w, place.from!), b = toWorld(w, place.to!);
    for (let i = 0; i < 44; i++) {
      const at = i % 2 ? a : b, ang = u01(e.h, 100 + i) * Math.PI * 2, r = 0.7 + u01(e.h, 200 + i) * 1.4;
      this.crowd.add(at.x + Math.cos(ang) * r, at.z + Math.sin(ang) * r);
    }
  }

  centre(): Pt | null { return this.way?.at(this.way.length / 2) ?? toWorld(this.w, this.place.from!); }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF[e.kind];
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    if (!this.way) {
      const f = this.place.from!, t = this.place.to!;
      const def = (this.rigs[0]?.rig.def ?? dressed('tomato')) as LandDef;
      const pts = landRoute(this.w, def, f.x, f.z, t.x, t.z, new Set(), false, 60000);
      this.way = new Way((pts && pts.length > 1 ? [f, ...pts] : [f, t]).map((p) => toWorld(this.w, p)));
    }
    const way = this.way, L = way.length, drive = spec.dur * this.spec.drive;
    const total = this.rigs.length ? this.rigs[this.rigs.length - 1].off + 0.6 : this.lead;
    const run = (now - e.start) / drive;
    const lead = total + clamp01(run) * Math.max(0, L - total);
    const v = run > 0 && run < 1 ? (L - total) / (drive * HOUR_S) : 0;
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / spec.lead) * (1 - clamp01((now - (e.end - 0.3)) / 0.3));
    this.crowd.cheer = run > -0.05 && run < 0.05 || run > 0.95 && run < 1.1 ? 1 : 0.2;
    this.crowd.update(dt);
    let k = 0;
    for (const { rig, off } of this.rigs) {
      const p = way.at(lead - off);
      rig.place(this.ctx.worldAt, p.x, p.z, p.heading, v, dt);
      if (rig.w) this.ctx.obstacles.push({ state: rig.local, def: rig.def, w: rig.w });
      if (this.carts) {
        const c = way.at(lead - off - halfSize(rig.def)[0] - 0.3);
        this.q.setFromAxisAngle(this.up, c.heading);
        this.v.set(c.x, this.ctx.ground(c.x, c.z) + 0.12, c.z);
        this.m.compose(this.v, this.q, this.s);
        this.carts.setMatrixAt(k++, this.m);
      }
    }
    if (this.carts) { this.carts.count = k; this.carts.instanceMatrix.needsUpdate = true; }
    if (this.riders && this.bikes) {
      // the peloton: five abreast, strung out a little, each rider weaving in the bunch
      const t = performance.now() / 1000;
      this.riders.shown = this.riders.size;
      for (let i = 0; i < this.riders.size; i++) {
        const row = Math.floor(i / 5), col = i % 5;
        const p = way.at(lead - row * 0.2 - (u01(e.h, i) - 0.5) * 0.1);
        const side = (col - 2) * 0.09 + Math.sin(t * 0.7 + i) * 0.02, nx = Math.cos(p.heading), nz = -Math.sin(p.heading);
        const x = p.x + nx * side, z = p.z + nz * side;
        this.riders.setAt(i, x, z, dt);
        this.q.setFromAxisAngle(this.up, p.heading);
        this.v.set(x, this.ctx.ground(x, z) + 0.025, z);
        this.m.compose(this.v, this.q, this.s);
        this.bikes.setMatrixAt(i, this.m);
      }
      this.bikes.count = this.riders.size;
      this.bikes.instanceMatrix.needsUpdate = true;
      this.riders.update(dt);
    }
  }

  dispose(): void {
    for (const r of this.rigs) r.rig.dispose();
    this.riders?.dispose();
    this.crowd.dispose();
    super.dispose();
  }
}

// ---- processions down a town's streets ---------------------------------------------------------------------------------------------------

/** A gilded carriage behind four white horses. */
function carriage(parent: THREE.Object3D): THREE.Group {
  const g = new THREE.Group();
  const body = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.2, 0.36), flat(0xd9b34a, 0.15));
  body.position.set(0, 0.22, -0.2);
  const roof = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.04, 0.38), flat(0x8e1b2b));
  roof.position.set(0, 0.34, -0.2);
  const crown = new THREE.Mesh(new THREE.OctahedronGeometry(0.05), flat(0xf2c14e, 0.4));
  crown.position.set(0, 0.4, -0.2);
  g.add(body, roof, crown);
  for (const [x, z] of [[-0.14, -0.06], [0.14, -0.06], [-0.14, -0.34], [0.14, -0.34]]) {
    const wh = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 0.02, 10), flat(0x8e1b2b));
    wh.rotation.z = Math.PI / 2;
    wh.position.set(x, 0.08, z);
    g.add(wh);
  }
  for (const [x, z] of [[-0.07, 0.22], [0.07, 0.22], [-0.07, 0.48], [0.07, 0.48]]) g.add(horse(0xf4f2ec, x, z));
  parent.add(g);
  return g;
}
/** A horse (and, `rider`, a guardsman up on it): a body, a neck and a head, legs. */
function horse(colour: number, x = 0, z = 0, rider?: number): THREE.Group {
  const g = new THREE.Group();
  const body = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.07, 0.2), flat(colour));
  body.position.y = 0.13;
  const neck = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.1, 0.05), flat(colour));
  neck.position.set(0, 0.19, 0.1);
  neck.rotation.x = 0.4;
  g.add(body, neck);
  for (const [lx, lz] of [[-0.025, 0.07], [0.025, 0.07], [-0.025, -0.07], [0.025, -0.07]]) {
    const leg = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.1, 0.02), flat(colour));
    leg.position.set(lx, 0.05, lz);
    g.add(leg);
  }
  if (rider !== undefined) {
    const coat = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.09, 0.04), flat(rider));
    coat.position.set(0, 0.22, 0);
    const hat = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.025, 0.06, 6), flat(0x111111));
    hat.position.set(0, 0.3, 0);
    g.add(coat, hat);
  }
  g.position.set(x, 0, z);
  return g;
}

interface MarchSpec {
  units: { id: string; colour?: number; livery?: number; riders?: number }[];
  /** Marching column ahead of (`front`) or behind the vehicles. */
  column?: { n: number; colours: number[]; front: boolean; gap: number };
  /** The kerbs lined by this many people. */
  kerbs: number;
  drive: number;
}
const MARCHES: Partial<Record<EventKind, MarchSpec>> = {
  weddingConvoy: { units: [{ id: 'limo', colour: 0xf8f6ee }, { id: 'sunny', colour: 0xf3e9d2 }, { id: 'tomato' }, { id: 'pip' }, { id: 'bramble' }], kerbs: 18, drive: 0.75 },
  royalProcession: { units: [], column: { n: 24, colours: [0xc8102e, 0xc8102e, 0x111111], front: true, gap: 0.18 }, kerbs: 56, drive: 0.8 },
  mardiGras: { units: [{ id: 'bus', colour: MARDI[0], livery: MARDI[2], riders: 8 }, { id: 'liveTruck', colour: MARDI[1] }, { id: 'bus', colour: MARDI[2], livery: MARDI[0], riders: 8 }, { id: 'dump', colour: MARDI[0] }], column: { n: 20, colours: [0xf2b632, 0xd9b34a], front: false, gap: 0.18 }, kerbs: 44, drive: 0.6 },
  lunarNewYear: { units: [], column: { n: 16, colours: [0xd52b1e, 0xf2b632], front: true, gap: 0.2 }, kerbs: 48, drive: 0.7 },
  climateMarch: { units: [], column: { n: 48, colours: [0x3f9b4a, 0x2bb3a3, 0xf2c14e, 0x6fb8e0], front: true, gap: 0.16 }, kerbs: 16, drive: 0.85 },
  marathon: { units: [{ id: 'cab', colour: 0xf2c14e }], kerbs: 30, drive: 0.85 },
  streetMarket: { units: [], kerbs: 0, drive: 0 },
};

/**
 * A procession down a town's closed streets with the kerbs lined: a wedding party from the church door, a gilded
 * carriage with its mounted guards, Mardi Gras floats and a brass band, the Lunar New Year's dragon, a marathon's
 * runners, a climate march. A market day is the street itself, stalls down both sides and people browsing.
 */
class MarchShow extends Show {
  private spec: MarchSpec;
  private way: Way;
  private rigs: { rig: Rig; off: number }[] = [];
  private column: Crowd | null = null;
  private colLen = 0;
  private kerbs: Crowd;
  private closure: Closure;
  private coach: THREE.Group | null = null;
  private guards: THREE.Group[] = [];
  private dragon: THREE.Mesh[] = [];
  private lanterns: Bulbs | null = null;
  private runners: { pace: number; side: number }[] = [];
  private lead = 0;

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    this.spec = MARCHES[e.kind]!;
    const P = place.path!;
    this.way = new Way(P.map((p) => toWorld(w, p)));
    let off = 0;
    const col = this.spec.column;
    if (e.kind === 'marathon') {
      this.column = new Crowd(this.g, ctx.ground, 0, BRIGHT);
      this.column.manual = true;
      for (let i = 0; i < 56; i++) { this.column.add(this.way.pts[0].x, this.way.pts[0].z); this.runners.push({ pace: 0.75 + u01(e.h, i) * 0.45, side: (u01(e.h, i + 90) - 0.5) * 0.6 }); }
    } else if (col) {
      this.column = new Crowd(this.g, ctx.ground, 0, col.colours);
      this.column.manual = true;
      for (let i = 0; i < col.n; i++) this.column.add(this.way.pts[0].x, this.way.pts[0].z);
      this.colLen = Math.ceil(col.n / 4) * col.gap + 0.5;
      if (col.front) off = this.colLen;
    }
    if (e.kind === 'royalProcession') {
      this.coach = carriage(this.g);
      for (let i = 0; i < 4; i++) { const h = horse(0x3a2a1e, 0, 0, 0xc8102e); this.g.add(h); this.guards.push(h); }
      off += 1.6;
    }
    if (e.kind === 'lunarNewYear') {
      // the dragon: a head and a dozen segments of body, carried along the street
      for (let i = 0; i < 13; i++) {
        const m = new THREE.Mesh(i === 0 ? new THREE.BoxGeometry(0.16, 0.12, 0.18) : new THREE.BoxGeometry(0.11, 0.08, 0.16), flat(i === 0 ? 0xf2b632 : i % 2 ? 0xd52b1e : 0xf2b632, 0.2));
        this.g.add(m);
        this.dragon.push(m);
      }
      this.lanterns = new Bulbs(this.g, 60, [0xff2a1a, 0xff4a2a], 0.045);
    }
    for (const u of this.spec.units) {
      const def = dressed(u.id, u.colour, u.livery);
      const half = halfSize(def)[0];
      off += half;
      this.rigs.push({ rig: new Rig(this.g, def, u.riders ?? 0), off });
      off += half + 0.6;
    }
    this.lead = off + (col && !col.front ? this.colLen : 0);
    this.kerbs = new Crowd(this.g, ctx.ground, e.h % 12);
    if (this.spec.kerbs) lineStreet(this.kerbs, w, P, e.h, this.spec.kerbs);
    this.closure = new Closure(w, P.map((p) => Math.floor(p.x) + Math.floor(p.z) * N));
    if (e.kind === 'streetMarket') this.stalls(P);
    if (e.kind === 'royalProcession') this.bunting(P, [0xc8102e, 0xffffff, 0x1f4e9e]);
    if (e.kind === 'mardiGras') this.bunting(P, MARDI);
  }

  /** The market: a striped stall every tile down both sides of the street, browsers along it. */
  private stalls(P: Pt[]): void {
    for (let k = 1; k < P.length - 1; k++) {
      const a = P[k - 1], b = P[k + 1], d = Math.hypot(b.x - a.x, b.z - a.z) || 1, yaw = Math.atan2(b.x - a.x, b.z - a.z);
      const nx = -(b.z - a.z) / d, nz = (b.x - a.x) / d;
      for (const side of [1, -1]) {
        if (u01(this.e.h, k * 3 + side) < 0.25) continue;
        const x = this.w.ox + P[k].x + nx * side * 0.32, z = this.w.oz + P[k].z + nz * side * 0.32, y = this.ctx.ground(x, z);
        block(this.g, x, y, z, 0.24, 0.12, 0.3, 0xd9c7a0, yaw);
        const c = BRIGHT[(k + (side > 0 ? 0 : 3)) % BRIGHT.length];
        for (let s = 0; s < 3; s++) block(this.g, x + Math.sin(yaw) * (s - 1) * 0.1, y + 0.24, z + Math.cos(yaw) * (s - 1) * 0.1, 0.3, 0.02, 0.1, s % 2 ? 0xffffff : c, yaw);
      }
    }
    this.column = new Crowd(this.g, this.ctx.ground, this.e.h % 12);
    this.column.manual = true;
    for (let i = 0; i < 50; i++) { this.column.add(this.way.pts[0].x, this.way.pts[0].z); this.runners.push({ pace: u01(this.e.h, i) * 6.28, side: (u01(this.e.h, i + 7) - 0.5) * 0.36 }); }
  }

  /** Flags strung along the kerbs in these colours. */
  private bunting(P: Pt[], colours: number[]): void {
    for (let k = 2; k < P.length - 1; k += 2) {
      const a = P[k - 1], b = P[k + 1], d = Math.hypot(b.x - a.x, b.z - a.z) || 1;
      const nx = -(b.z - a.z) / d, nz = (b.x - a.x) / d;
      for (const side of [1, -1]) {
        const x = this.w.ox + P[k].x + nx * side * 0.47, z = this.w.oz + P[k].z + nz * side * 0.47, y = this.ctx.ground(x, z);
        block(this.g, x, y, z, 0.012, 0.36, 0.012, 0xdddddd);
        block(this.g, x, y + 0.31, z, 0.1, 0.06, 0.008, colours[(k / 2 + (side > 0 ? 0 : 1)) % colours.length], Math.atan2(b.x - a.x, b.z - a.z));
      }
    }
  }

  centre(): Pt | null { return this.way.at(this.way.length / 2); }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF[e.kind];
    const out = now >= e.start - spec.lead && now < e.end;
    this.closure.set(out);
    this.g.visible = out;
    if (!out) return;
    const L = this.way.length, drive = spec.dur * this.spec.drive;
    const run = drive > 0 ? (now - e.start) / drive : 0;
    const lead = this.lead + clamp01(run) * Math.max(0, L - this.lead);
    const v = run > 0 && run < 1 ? (L - this.lead) / (drive * HOUR_S) : 0;
    const t = performance.now() / 1000;
    this.kerbs.shown = this.kerbs.size * clamp01((now - (e.start - spec.lead)) / spec.lead) * (1 - clamp01((now - (e.end - 0.3)) / 0.3));
    this.kerbs.cheer = run > 0 && run < 1 ? 0.8 : 0.1;
    this.kerbs.update(dt);
    for (const { rig, off } of this.rigs) {
      const p = this.way.at(lead - off);
      rig.place(this.ctx.worldAt, p.x, p.z, p.heading, v, dt);
      if (rig.w) this.ctx.obstacles.push({ state: rig.local, def: rig.def, w: rig.w });
    }
    const col = this.column;
    if (col) {
      col.shown = col.size;
      if (e.kind === 'marathon') {
        // the runners strung out by their pace, each on their own line across the street
        const r = clamp01((now - e.start) / drive);
        this.runners.forEach((q, i) => {
          const p = this.way.at(Math.min(L, r * q.pace * L * 1.05));
          const nx = Math.cos(p.heading), nz = -Math.sin(p.heading);
          col.setAt(i, p.x + nx * q.side, p.z + nz * q.side, dt);
        });
        col.shown = now >= e.start - 0.2 && now < e.end - 0.15 ? col.size : 0;
      } else if (e.kind === 'streetMarket') {
        // browsing: wandering up and down the street, a stall at a time
        this.runners.forEach((q, i) => {
          const p = this.way.at((0.5 + 0.48 * Math.sin(t * 0.05 + q.pace)) * L);
          const nx = Math.cos(p.heading), nz = -Math.sin(p.heading);
          col.setAt(i, p.x + nx * q.side, p.z + nz * q.side, dt);
        });
        col.shown = col.size * clamp01((now - e.start) / 0.5) * (1 - clamp01((now - (e.end - 0.5)) / 0.5));
      } else {
        const c = this.spec.column!;
        const s = c.front ? lead : lead - (this.rigs.length ? this.rigs[this.rigs.length - 1].off + 0.8 : 0);
        for (let k = 0; k < col.size; k++) {
          const row = Math.floor(k / 4), cc = k % 4;
          const p = this.way.at(s - row * c.gap);
          const side = (cc - 1.5) * 0.11, nx = Math.cos(p.heading), nz = -Math.sin(p.heading);
          col.setAt(k, p.x + nx * side, p.z + nz * side, dt);
        }
        col.cheer = e.kind === 'mardiGras' && run > 0 && run < 1 ? 0.6 : 0;
      }
      col.update(dt);
    }
    if (this.coach) {
      const p = this.way.at(lead - (this.spec.column ? this.colLen : 0) - 0.6);
      this.coach.position.set(p.x, this.ctx.ground(p.x, p.z), p.z);
      this.coach.rotation.y = p.heading;
      this.guards.forEach((g, i) => {
        const q = this.way.at(lead - (this.spec.column ? this.colLen : 0) - 0.2 - (i < 2 ? 0 : 1.1));
        const nx = Math.cos(q.heading), nz = -Math.sin(q.heading), side = i % 2 ? 0.22 : -0.22;
        g.position.set(q.x + nx * side, this.ctx.ground(q.x, q.z), q.z + nz * side);
        g.rotation.y = q.heading;
      });
    }
    if (this.dragon.length) {
      // the dragon weaves, each segment a step behind the one before, rising and falling on its poles
      this.dragon.forEach((m, i) => {
        const p = this.way.at(lead - i * 0.13);
        const nx = Math.cos(p.heading), nz = -Math.sin(p.heading), wv = Math.sin(t * 3 - i * 0.7) * 0.1;
        m.position.set(p.x + nx * wv, this.ctx.ground(p.x, p.z) + 0.2 + Math.max(0, Math.sin(t * 4 - i * 0.6)) * 0.08, p.z + nz * wv);
        m.rotation.y = p.heading;
      });
      // red lanterns over the kerbs, and firecrackers going off
      if (this.lanterns) {
        this.lanterns.begin();
        const P = this.way.pts;
        for (let k = 1; k < P.length - 1 && k < 30; k++) {
          const a = P[k - 1], b = P[k + 1], d = Math.hypot(b.x - a.x, b.z - a.z) || 1, nx = -(b.z - a.z) / d, nz = (b.x - a.x) / d;
          for (const side of [1, -1]) this.lanterns.at(P[k].x + nx * side * 0.45, this.ctx.ground(P[k].x, P[k].z) + 0.45 + Math.sin(t + k) * 0.01, P[k].z + nz * side * 0.45);
        }
        this.lanterns.end();
      }
      if (run > 0 && run < 1 && Math.random() < dt * 4) {
        const p = this.way.at(Math.random() * L), y = this.ctx.ground(p.x, p.z);
        for (let k = 0; k < 10; k++) this.ctx.particles.spark({ x: p.x, y: y + 0.05, z: p.z, vx: (Math.random() - 0.5) * 1.2, vy: 0.6 + Math.random() * 0.8, vz: (Math.random() - 0.5) * 1.2, life: 0.4, colour: k % 2 ? 0xffd166 : 0xff3b3b, size: 0.07, gravity: 2 });
      }
    }
    // the wedding's petals at the church door, Mardi Gras's beads off the floats
    if (e.kind === 'weddingConvoy' && now > e.start - 0.3 && now < e.start + 0.1 && Math.random() < dt * 30) {
      const p = this.way.at(0.3);
      this.ctx.particles.slip({ x: p.x + (Math.random() - 0.5) * 0.8, y: this.ctx.ground(p.x, p.z) + 0.6, z: p.z + (Math.random() - 0.5) * 0.8, vx: 0, vy: 0, vz: 0, life: 5, colour: Math.random() < 0.5 ? 0xf7c5d4 : 0xffffff, size: 0.05 });
    }
    if (e.kind === 'mardiGras' && run > 0 && run < 1 && Math.random() < dt * 25) {
      const r = this.rigs[Math.floor(Math.random() * this.rigs.length)].rig.state;
      this.ctx.particles.spark({ x: r.x, y: r.y + 0.5, z: r.z, vx: (Math.random() - 0.5) * 1.6, vy: 1.2, vz: (Math.random() - 0.5) * 1.6, life: 0.9, colour: MARDI[Math.floor(Math.random() * 3)], size: 0.06, gravity: 3 });
    }
  }

  dispose(): void {
    this.closure.set(false);
    for (const r of this.rigs) r.rig.dispose();
    this.column?.dispose();
    this.kerbs.dispose();
    super.dispose();
  }
}

// ---- gatherings on a lot ---------------------------------------------------------------------------------------------------

/** The colours a festival's envelopes are painted in: brights, and a white, a navy and a black to set them off. */
const ENVELOPE = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0x8e5cc7, 0xf28c38, 0x2bb3a3, 0xf49ab5, 0xf4f2ec, 0x1d2a5c, 0x22252a, 0xd52b1e, 0x6fc3e8, 0xb5d334];
const BALLOON_DEFS = new Map<string, AirDef>();
/** The real hot air balloon (the dealer's Sunrise) in an envelope of its own: a pattern and three or more colours from the hash. */
function festivalBalloon(h: number, k: number): AirDef {
  const base = VEHICLES.find((d) => d.id === 'balloon') as AirDef;
  // a seed of its own first: the hash's neighbouring keys run together too much to paint neighbours apart
  const hb = Math.floor(u01(Math.floor(u01(h, 1300 + k) * 4294967296), 7) * 4294967296);
  const p = Math.floor(u01(hb, 1) * BALLOON_PATTERNS);
  const n = p === 1 ? 4 + Math.floor(u01(hb, 2) * 3) : 3;
  const c: number[] = [];
  for (let j = 0; c.length < n && j < 40; j++) {
    const col = ENVELOPE[Math.floor(u01(Math.floor(u01(hb, 10 + j) * 4294967296), 3) * ENVELOPE.length)];
    if (!c.includes(col)) c.push(col);
  }
  const key = `${p}|${c.join(',')}`;
  let d = BALLOON_DEFS.get(key);
  if (!d) BALLOON_DEFS.set(key, (d = { ...base, color: c[0], envelope: { p, c } }));
  return d;
}

/** A festival balloon's day, in game hours from the start: laid out and filling, up, drifting, down, packed away. */
interface FestBalloon {
  rig: Rig;
  /** Its launch spot, world tiles. */
  x: number; z: number;
  /** Game hours after the start that it begins to fill, how long it flies, its height over the ground, its drift (tiles a game hour) and the line it drifts on. */
  fill: number; flight: number; alt: number; drift: number; dir: number;
  /** The model's own scale, so it can be shown filling. */
  scale: number;
  /** Until its next burn. */
  burn: number;
  /** Its basket's height now (world units), eased up over whatever stands in its way; NaN until it lifts off. */
  y: number;
}
/** Game hours: filling, climbing to its height, coming down, and packing the envelope away. */
const FILL = 0.35, CLIMB = 0.3, DESCEND = 0.25, PACK = 0.25;

/**
 * A gathering on a town's lot: food trucks round a square, a circus's big top, a stage or a screen in a park, a
 * harvest fair's tractors and pumpkins, balloons filling at dawn, lanterns strung through the blossom, a carnival's
 * masked crowds. The ground is the lot; people wander it, or sit.
 */
class LotShow extends Show {
  private lot: NonNullable<Place['lot']>;
  private crowd: Crowd;
  private rigs: Rig[] = [];
  private props = new THREE.Group();
  private balloons: FestBalloon[] = [];
  private bulbs: Bulbs | null = null;
  private screen: THREE.Mesh | null = null;
  private c: Pt;
  private wind: number;

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    this.lot = place.lot!;
    const lot = this.lot;
    this.c = toWorld(w, mid(lot));
    this.wind = u01(e.h, 77) * Math.PI * 2;
    const rect = { x0: w.ox + lot.x + 0.2, z0: w.oz + lot.z + 0.2, x1: w.ox + lot.x + lot.w - 0.2, z1: w.oz + lot.z + lot.d - 0.2 };
    const palette = e.kind === 'veniceCarnival' ? [0xd52b1e, 0xf2b632, 0x6a2c91, 0x1f8a4c, 0xffffff, 0x111111] : undefined;
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12, palette);
    const sit = e.kind === 'parkConcert' || e.kind === 'lanternFestival';
    if (!sit) this.crowd.roam = rect;
    for (let i = 0; i < 52; i++) this.crowd.add(rect.x0 + u01(e.h, 500 + i) * (rect.x1 - rect.x0), rect.z0 + u01(e.h, 600 + i) * (rect.z1 - rect.z0));
    this.g.add(this.props);
    const gy = ctx.ground(this.c.x, this.c.z);
    const edge = (u: number, inset = 0.4): Pt & { yaw: number } => {
      // a point round the lot's edge, a fraction u of the way round, facing in
      const per = 2 * (lot.w + lot.d), s = u * per;
      const x = s < lot.w ? lot.x + s : s < lot.w + lot.d ? lot.x + lot.w : s < 2 * lot.w + lot.d ? lot.x + lot.w - (s - lot.w - lot.d) : lot.x;
      const z = s < lot.w ? lot.z : s < lot.w + lot.d ? lot.z + (s - lot.w) : s < 2 * lot.w + lot.d ? lot.z + lot.d : lot.z + lot.d - (s - 2 * lot.w - lot.d);
      const px = w.ox + Math.min(lot.x + lot.w - inset, Math.max(lot.x + inset, x)), pz = w.oz + Math.min(lot.z + lot.d - inset, Math.max(lot.z + inset, z));
      return { x: px, z: pz, yaw: Math.atan2(this.c.x - px, this.c.z - pz) };
    };
    switch (e.kind) {
      case 'foodTrucks': {
        ['sundae', 'mule', 'postal', 'tomato', 'sundae', 'mule', 'bramble', 'postal'].forEach((id, i) => {
          const p = edge(i / 8 + 0.03, 0.55);
          const r = new Rig(this.g, dressed(id, BRIGHT[i]));
          r.place(ctx.worldAt, p.x, p.z, p.yaw + Math.PI / 2, 0, 0);
          this.rigs.push(r);
        });
        for (let k = 0; k < 4; k++) block(this.props, this.c.x + (k % 2 - 0.5) * 0.9, gy, this.c.z + (Math.floor(k / 2) - 0.5) * 0.7, 0.4, 0.08, 0.2, 0x8a5a2b);
        break;
      }
      case 'circusCaravan': {
        // the big top: striped walls, a peaked roof, a flag; the trucks parked round the edge
        const R = Math.max(0.9, Math.min(lot.w, lot.d) / 2 - 1.2);
        for (let k = 0; k < 16; k++) {
          const a = (k / 16) * Math.PI * 2;
          block(this.props, this.c.x + Math.cos(a) * R, gy, this.c.z + Math.sin(a) * R, 0.38 * R, 0.5, 0.04, k % 2 ? 0xffffff : 0xd52b1e, -a + Math.PI / 2);
        }
        const roof = new THREE.Mesh(new THREE.ConeGeometry(R * 1.15, 0.7, 16), flat(0xd52b1e));
        roof.position.set(this.c.x, gy + 0.85, this.c.z);
        roof.castShadow = true;
        this.props.add(roof);
        block(this.props, this.c.x, gy + 1.2, this.c.z, 0.02, 0.3, 0.02, 0xdddddd);
        block(this.props, this.c.x + 0.06, gy + 1.42, this.c.z, 0.12, 0.07, 0.01, 0xf2b632);
        ['dump', 'mixer', 'postal', 'mule'].forEach((id, i) => {
          const p = edge(i / 4 + 0.1, 0.5);
          const r = new Rig(this.g, dressed(id, [0xd52b1e, 0xf2b632, 0x1f4e9e, 0x1f8a4c][i], 0xffffff));
          r.place(ctx.worldAt, p.x, p.z, p.yaw + Math.PI / 2, 0, 0);
          this.rigs.push(r);
        });
        this.bulbs = new Bulbs(this.g, 48, [0xffd166, 0xff3b3b, 0x5ad1ff, 0x3dff8a]);
        break;
      }
      case 'parkConcert': {
        const p = edge(0.12, 0.6);
        if (u01(e.h, 5) < 0.5) {
          // a stage, a backdrop and a lighting rig
          block(this.props, p.x, this.ctx.ground(p.x, p.z), p.z, 1.2, 0.1, 0.6, 0x3a3f45, p.yaw);
          block(this.props, p.x - Math.sin(p.yaw) * 0.3, this.ctx.ground(p.x, p.z) + 0.1, p.z - Math.cos(p.yaw) * 0.3, 1.2, 0.6, 0.04, 0x15161a, p.yaw);
          block(this.props, p.x, this.ctx.ground(p.x, p.z) + 0.7, p.z, 1.25, 0.04, 0.04, 0xfff2c4, p.yaw, 2.5);
        } else {
          // an outdoor film: a big white screen on its frame, glowing once it is dark
          this.screen = new THREE.Mesh(new THREE.PlaneGeometry(1.4, 0.7), new THREE.MeshStandardMaterial({ color: 0xf4f2ec, emissive: 0x9fc8e8, emissiveIntensity: 0, side: THREE.DoubleSide }));
          this.screen.position.set(p.x, this.ctx.ground(p.x, p.z) + 0.6, p.z);
          this.screen.rotation.y = p.yaw;
          this.props.add(this.screen);
        }
        // blankets on the grass
        for (let k = 0; k < 12; k++) block(this.props, rect.x0 + u01(e.h, 700 + k) * (rect.x1 - rect.x0), this.ctx.ground(this.c.x, this.c.z), rect.z0 + u01(e.h, 800 + k) * (rect.z1 - rect.z0), 0.3, 0.01, 0.22, BRIGHT[k % BRIGHT.length], u01(e.h, k));
        break;
      }
      case 'harvestFair': {
        ['clod', 'clod', 'clod'].forEach((id, i) => {
          const p = edge(i / 3 + 0.05, 0.5);
          const r = new Rig(this.g, dressed(id, [0x3f9b4a, 0xc8102e, 0x1f4e9e][i]));
          r.place(ctx.worldAt, p.x, p.z, p.yaw, 0, 0);
          this.rigs.push(r);
        });
        // pumpkins in piles, and the livestock ring's fence
        const pumpkin = new THREE.InstancedMesh(new THREE.SphereGeometry(0.05, 7, 5).scale(1, 0.8, 1), flat(0xf28c1e), 30);
        const m = new THREE.Matrix4();
        for (let k = 0; k < 30; k++) { const a = u01(e.h, 900 + k) * 6.28, r = u01(e.h, 950 + k) * 0.35; m.makeTranslation(this.c.x + 0.8 + Math.cos(a) * r, gy + 0.04, this.c.z + Math.sin(a) * r); pumpkin.setMatrixAt(k, m); }
        this.props.add(pumpkin);
        for (let k = 0; k < 14; k++) { const a = (k / 14) * Math.PI * 2; block(this.props, this.c.x - 0.6 + Math.cos(a) * 0.7, gy, this.c.z + Math.sin(a) * 0.7, 0.025, 0.12, 0.025, 0x8a5a2b); }
        break;
      }
      case 'balloonFestival': {
        // a mass ascension: launch spots across the lot a balloon's width and a bit apart, and each spot sends up
        // a wave of balloons one after another (the next laid out as the last lifts off), so a small field still
        // puts two or three dozen into the sky
        const gap = 1.7, spots: Pt[] = [];
        for (let z = rect.z0 + gap / 2; z <= rect.z1 - gap / 2 + 1e-6; z += gap) for (let x = rect.x0 + gap / 2; x <= rect.x1 - gap / 2 + 1e-6; x += gap) spots.push({ x, z });
        if (!spots.length) spots.push({ ...this.c });
        const n = Math.min(32, spots.length * 6, Math.max(22, spots.length * 4));
        const waves = Math.ceil(n / spots.length);
        // a wave every 25 game minutes or so: the last of a spot's balloons is well up before the next is laid out
        // there, and even a small field's six waves are all away inside two hours and a quarter
        const every = waves > 1 ? Math.max(0.42, Math.min(0.5, 2.1 / (waves - 1))) : 0;
        for (let k = 0; k < n; k++) {
          const s = spots[k % spots.length], wave = Math.floor(k / spots.length);
          const rig = new Rig(this.g, festivalBalloon(e.h, k));
          rig.hide();
          this.balloons.push({
            rig, x: s.x + (u01(e.h, 300 + k) - 0.5) * 0.3, z: s.z + (u01(e.h, 400 + k) - 0.5) * 0.3,
            fill: wave * every + u01(e.h, 450 + k) * 0.12,
            flight: 1.0 + u01(e.h, 470 + k) * 0.8,
            alt: 4 + u01(e.h, 490 + k) * 9,
            drift: 8 + u01(e.h, 510 + k) * 6,
            // each at its own height, so each on a slightly different line downwind
            dir: this.wind + (u01(e.h, 530 + k) - 0.5) * 0.5,
            scale: rig.mesh.root.scale.x,
            burn: u01(e.h, 550 + k) * 4,
            y: NaN,
          });
        }
        // the chase crews' pickups along the edge, to follow them downwind and bring them home
        ['mule', 'bramble', 'mule', 'bertha'].forEach((id, i) => {
          const p = edge(i / 4 + 0.08, 0.5);
          const r = new Rig(this.g, dressed(id, BRIGHT[(i * 3) % BRIGHT.length]));
          r.place(ctx.worldAt, p.x, p.z, p.yaw + Math.PI / 2, 0, 0);
          this.rigs.push(r);
        });
        break;
      }
      case 'lanternFestival': case 'veniceCarnival': {
        this.bulbs = new Bulbs(this.g, 72, e.kind === 'lanternFestival' ? [0xff4a2a, 0xffb347, 0xffd166] : [0xff6ad5, 0xffd166, 0x5ad1ff]);
        break;
      }
    }
  }

  centre(): Pt | null { return this.c; }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF[e.kind];
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    const night = this.ctx.night(), t = performance.now() / 1000;
    // the people: out through the day of it, most of them in the evening at a concert
    const open = clamp01((now - (e.start - spec.lead)) / (spec.lead + 0.3)) * (1 - clamp01((now - (e.end - 0.4)) / 0.4));
    this.crowd.shown = this.crowd.size * open * (e.kind === 'circusCaravan' ? 0.4 + 0.6 * Math.max(night, hourOf(now) > 12 && hourOf(now) < 21 ? 1 : 0) : 1);
    this.crowd.cheer = e.kind === 'parkConcert' && now > e.start ? 0.35 : e.kind === 'veniceCarnival' ? 0.4 : 0;
    this.crowd.update(dt);
    if (this.screen) (this.screen.material as THREE.MeshStandardMaterial).emissiveIntensity = now > e.start ? 0.4 + night * 1.2 + Math.sin(t * 3) * 0.1 : 0;
    // strings of bulbs: round the big top, over the lot in sagging rows
    if (this.bulbs) {
      this.bulbs.begin();
      const lot = this.lot, gy = this.ctx.ground(this.c.x, this.c.z);
      if (e.kind === 'circusCaravan') {
        const R = Math.max(0.9, Math.min(lot.w, lot.d) / 2 - 1.2);
        for (let k = 0; k < 48; k++) { const a = (k / 48) * Math.PI * 2; this.bulbs.at(this.c.x + Math.cos(a) * R * 1.12, gy + 0.55, this.c.z + Math.sin(a) * R * 1.12); }
      } else {
        for (let row = 0; row < 4; row++) for (let k = 0; k < 18; k++) {
          const u = k / 17, x = this.w.ox + lot.x + 0.3 + u * (lot.w - 0.6), z = this.w.oz + lot.z + 0.4 + (row / 3) * (lot.d - 0.8);
          this.bulbs.at(x, gy + 0.75 - Math.sin(u * Math.PI) * 0.18 + Math.sin(t * 1.5 + k) * 0.01, z);
        }
      }
      this.bulbs.end();
      this.bulbs.mesh.visible = night > 0.2 || e.kind === 'lanternFestival';
    }
    // confetti over a carnival, petals over the lantern festival
    if ((e.kind === 'veniceCarnival' || e.kind === 'lanternFestival') && now > e.start && Math.random() < dt * 12) {
      const l = this.lot;
      this.ctx.particles.slip({ x: this.w.ox + l.x + Math.random() * l.w, y: this.ctx.ground(this.c.x, this.c.z) + 1.2, z: this.w.oz + l.z + Math.random() * l.d, vx: 0, vy: 0, vz: 0, life: 6, colour: e.kind === 'lanternFestival' ? 0xf7c5d4 : BRIGHT[Math.floor(Math.random() * BRIGHT.length)], size: 0.05 });
    }
    // the balloons: laid out on their sides and filling, standing up, lifting off, drifting downwind at their own
    // heights, then down in a field somewhere and the envelope packed away
    for (const b of this.balloons) this.balloon(b, now - e.start, dt);
  }

  private balloon(b: FestBalloon, t: number, dt: number): void {
    const t0 = t - b.fill;
    const up = t0 - FILL, end = b.flight + DESCEND;
    if (t0 < 0 || up > end + PACK) { b.rig.hide(); b.y = NaN; return; }
    const root = b.rig.mesh.root;
    // how far it has drifted (slowly while low, at its full rate once up), and the ground there
    const flown = Math.max(0, Math.min(up, end));
    const lift = Math.min(1, flown / CLIMB);
    const along = b.drift * Math.max(0, flown - CLIMB * 0.5 * lift);
    const x = b.x + Math.sin(b.dir) * along, z = b.z + Math.cos(b.dir) * along;
    const gy = this.ctx.ground(x, z);
    const wall = performance.now() / 1000;
    if (up < 0) {
      b.y = NaN;
      // filling: on its side with the crown downwind, swelling, then standing up as the hot air goes in
      const f = clamp01(t0 / FILL);
      const stand = clamp01((f - 0.55) / 0.45);
      root.scale.setScalar(b.scale * (0.55 + 0.45 * Math.min(1, f / 0.6)));
      b.rig.fly(x, gy, z, b.dir, (1 - stand) * 0.95, 0, dt);
      this.burner(b, dt, f > 0.4 ? 5 : 0);
      return;
    }
    root.scale.setScalar(b.scale);
    if (up <= end) {
      // up, along and (at the last) down: a gentle bob all the way, the burner now and then
      const down = clamp01((up - b.flight) / DESCEND);
      const h = b.alt * Math.min(lift, 1 - down) + Math.sin(wall * 0.6 + b.x) * 0.12 * (1 - down);
      // over the town it climbs clear of the roofs under it and just downwind, quickly, and settles back slowly
      const want = Math.max(gy + h, this.roofs(x, z, b.dir) + 0.5);
      b.y = Number.isNaN(b.y) ? want : want > b.y ? b.y + Math.min(want - b.y, dt * 6) : b.y + Math.max(want - b.y, -dt * 0.8);
      b.rig.fly(x, b.y, z, b.dir + Math.sin(wall * 0.05 + b.z) * 0.3, 0, 0, dt);
      this.burner(b, dt, down > 0 && down < 0.9 ? 0.6 : 0.35);
      return;
    }
    // landed: the envelope goes down on its side and is packed away (on a flat roof, the odd time it comes down in town)
    const p = clamp01((up - end) / PACK);
    root.scale.setScalar(b.scale * (1 - 0.6 * p));
    b.rig.fly(x, Math.max(gy, this.roofs(x, z, b.dir, 0)), z, b.dir, Math.min(1, p * 3) * 1.2, 0, dt);
  }

  /** The highest ground or roof under an envelope at (x, z), and (with `ahead`) as far downwind along `dir`. */
  private roofs(x: number, z: number, dir: number, ahead = 4): number {
    let top = -Infinity;
    for (let a = 0; a <= ahead; a += 1) for (const [ox, oz] of [[0, 0], [0.6, 0], [-0.6, 0], [0, 0.6], [0, -0.6]]) {
      const px = x + Math.sin(dir) * a + ox, pz = z + Math.cos(dir) * a + oz;
      const w = this.ctx.worldAt(Math.floor(px / N), Math.floor(pz / N));
      const g = this.ctx.ground(px, pz);
      if (!w) { top = Math.max(top, g); continue; }
      const lx = Math.floor(px - w.ox), lz = Math.floor(pz - w.oz);
      top = Math.max(top, g, lx >= 0 && lz >= 0 && lx < N && lz < N ? w.roof[lx + lz * N] : g);
    }
    return top;
  }

  /** The burner: a flame and a puff of heat up into the envelope, about `rate` times a second. */
  private burner(b: FestBalloon, dt: number, rate: number): void {
    b.burn -= dt * rate;
    if (b.burn > 0) return;
    b.burn = 1 + Math.random();
    const p = b.rig.mesh.root.position, s = b.rig.mesh.root.scale.x;
    this.ctx.particles.spark({ x: p.x, y: p.y + 0.38 * s, z: p.z, vx: 0, vy: 0.8, vz: 0, life: 0.35, colour: 0xffa040, size: 0.1, gravity: 0 });
  }

  dispose(): void { for (const r of this.rigs) r.dispose(); for (const b of this.balloons) b.rig.dispose(); this.crowd.dispose(); super.dispose(); }
}

// ---- at a building's front door ---------------------------------------------------------------------------------------------------

/**
 * Things at a building's door: a grand opening's ribbon and balloons, a premiere's red carpet with the limousines
 * pulling up and the searchlights crossing, a picket line at a works' gates with its braziers.
 */
class FrontShow extends Show {
  private crowd: Crowd;
  private door: Pt;
  private beams: THREE.Group[] = [];
  private limos: Rig[] = [];
  private balloons: THREE.Mesh[] = [];
  private braziers: Pt[] = [];
  private yaw: number;

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    const b = place.tower!;
    this.door = toWorld(w, place.from!);
    const c = toWorld(w, mid(b));
    this.yaw = Math.atan2(c.x - this.door.x, c.z - this.door.z);
    const fx = Math.sin(this.yaw), fz = Math.cos(this.yaw), sx = Math.cos(this.yaw), sz = -Math.sin(this.yaw);
    const gy = ctx.ground(this.door.x, this.door.z);
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12, e.kind === 'strikePickets' ? [0x3a3f45, 0x2f7fb5, 0xc9463d, 0x6b3a2a] : undefined);
    if (e.kind === 'premiereNight') {
      // the red carpet from the kerb to the door, the crowd behind ropes either side, three limousines at the kerb
      block(this.g, this.door.x + fx * 0.5, gy + 0.005, this.door.z + fz * 0.5, 0.3, 0.01, 1.1, 0xb3122a, this.yaw);
      for (let i = 0; i < 40; i++) { const side = i % 2 ? 1 : -1, along = (Math.floor(i / 2) / 20) * 1.1; this.crowd.add(this.door.x + fx * along + sx * side * (0.28 + (i % 4 > 1 ? 0.09 : 0)), this.door.z + fz * along + sz * side * (0.28 + (i % 4 > 1 ? 0.09 : 0))); }
      for (let k = 0; k < 3; k++) {
        const r = new Rig(this.g, dressed('limo', k === 1 ? 0xf8f6ee : 0x111111));
        r.place(ctx.worldAt, this.door.x - fx * 0.15 + sx * (k - 1) * 2.7, this.door.z - fz * 0.15 + sz * (k - 1) * 2.7, this.yaw + Math.PI / 2, 0, 0);
        this.limos.push(r);
      }
      for (let k = 0; k < 2; k++) this.beams.push(beam(this.g));
    } else if (e.kind === 'grandOpening') {
      // a ribbon across the door, balloons tied either side, a crowd waiting
      block(this.g, this.door.x + fx * 0.35, gy + 0.18, this.door.z + fz * 0.35, 0.9, 0.04, 0.01, 0xd52b1e, this.yaw + Math.PI / 2);
      for (let k = 0; k < 8; k++) {
        const m = new THREE.Mesh(new THREE.SphereGeometry(0.07, 8, 6), flat(BRIGHT[k % BRIGHT.length]));
        this.g.add(m);
        this.balloons.push(m);
      }
      for (let i = 0; i < 40; i++) this.crowd.add(this.door.x - fx * (0.2 + u01(e.h, i) * 0.9) + sx * (u01(e.h, i + 50) - 0.5) * 1.6, this.door.z - fz * (0.2 + u01(e.h, i) * 0.9) + sz * (u01(e.h, i + 50) - 0.5) * 1.6);
      for (let k = 0; k < 2; k++) this.beams.push(beam(this.g));
    } else {
      // the picket line across the gate, two braziers, placards up
      for (let i = 0; i < 14; i++) this.crowd.add(this.door.x + sx * (i - 6.5) * 0.12 - fx * 0.15, this.door.z + sz * (i - 6.5) * 0.12 - fz * 0.15);
      for (const s of [-1, 1]) {
        const p = { x: this.door.x + sx * s * 0.95, z: this.door.z + sz * s * 0.95 };
        block(this.g, p.x, gy, p.z, 0.08, 0.1, 0.08, 0x2b2f36);
        this.braziers.push(p);
      }
      for (let i = 0; i < 6; i++) block(this.g, this.door.x + sx * (i * 2 - 5.5) * 0.12 - fx * 0.15, gy + 0.13, this.door.z + sz * (i * 2 - 5.5) * 0.12 - fz * 0.15, 0.09, 0.06, 0.01, [0xf4f2ec, 0xf2c14e, 0xf49ab5][i % 3], this.yaw + Math.PI / 2);
    }
  }

  centre(): Pt | null { return this.door; }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF[e.kind];
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    const night = this.ctx.night(), t = performance.now() / 1000;
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / (spec.lead + 0.2)) * (1 - clamp01((now - (e.end - 0.3)) / 0.3));
    this.crowd.cheer = e.kind === 'strikePickets' ? 0.15 : now > e.start && now < e.start + 0.3 ? 1 : 0.3;
    this.crowd.update(dt);
    const gy = this.ctx.ground(this.door.x, this.door.z);
    this.beams.forEach((g, i) => {
      const s = i ? 1 : -1, sx = Math.cos(this.yaw), sz = -Math.sin(this.yaw);
      g.position.set(this.door.x + sx * s * 1.3, gy, this.door.z + sz * s * 1.3);
      g.rotation.set(0.45 + 0.15 * Math.sin(t * 0.8 + i), t * 0.5 * s + i * 2, 0, 'YXZ');
      g.visible = night > 0.2;
    });
    this.balloons.forEach((m, i) => {
      const s = i % 2 ? 1 : -1, sx = Math.cos(this.yaw), sz = -Math.sin(this.yaw);
      m.position.set(this.door.x + sx * s * (0.5 + (i >> 1) * 0.07), gy + 0.45 + (i >> 1) * 0.08 + Math.sin(t * 1.3 + i) * 0.02, this.door.z + sz * s * (0.5 + (i >> 1) * 0.07));
    });
    for (const b of this.braziers) {
      if (Math.random() < dt * 20) this.ctx.particles.spark({ x: b.x + (Math.random() - 0.5) * 0.05, y: gy + 0.12, z: b.z + (Math.random() - 0.5) * 0.05, vx: 0, vy: 0.5 + Math.random() * 0.3, vz: 0, life: 0.5, colour: Math.random() < 0.5 ? 0xff7a1a : 0xffd166, size: 0.06, gravity: 0, drag: 1 });
    }
  }

  dispose(): void { for (const r of this.limos) r.dispose(); this.crowd.dispose(); super.dispose(); }
}

// ---- the stadium ---------------------------------------------------------------------------------------------------

/**
 * A stadium's big night: monster trucks taking turns to jump the row of wrecks in the middle of the field and
 * circling round it, the stands full; or, for any stadium, the sponsor's blimp circling slowly overhead.
 */
class StadiumShow extends Show {
  private trucks: Rig[] = [];
  private wrecks: Rig[] = [];
  private blimp: Rig | null = null;
  private crowd: Crowd;
  private b: NonNullable<Place['lot']>;
  private field: { cx: number; cz: number; len: number; wid: number; axis: 'x' | 'z' };

  constructor(e: Happening, ctx: ShowCtx, private w: World, place: Place) {
    super(e, ctx);
    this.b = place.lot!;
    const plan = stadiumPlanOf(this.b);
    this.field = plan.field;
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    if (e.kind === 'sponsorBlimp') {
      this.blimp = new Rig(this.g, dressed('marshmallow', 0xf4f2ec));
      return;
    }
    // the stands: people in seats all round
    for (let k = 0; k < 400 && this.crowd.size < 64; k++) {
      const x = (u01(e.h, k * 2) - 0.5) * plan.W, z = (u01(e.h, k * 2 + 1) - 0.5) * plan.D;
      const sy = plan.seatY(x, z);
      if (sy === null) continue;
      const q = stadiumToIsland(this.b, x, z);
      this.crowd.add(w.ox + q.x, w.oz + q.z, this.b.level * STEP + sy + 0.05);
    }
    for (let i = 0; i < 3; i++) this.trucks.push(new Rig(this.g, dressed('stomper', [0x3f9b4a, 0xe2412f, 0x2f7fb5][i])));
    for (let i = 0; i < 5; i++) {
      const r = new Rig(this.g, dressed(['tomato', 'pip', 'bramble', 'zippy', 'tomato'][i], [0x6b3a2a, 0x7a5c3a, 0x5a4a3a, 0x8a5a3a, 0x6b4a2a][i]));
      r.mesh.root.scale.set(1, 0.6, 1);
      this.wrecks.push(r);
    }
  }

  /** A point on the field, in field units (u along its length, v across), in world tiles. */
  private fieldPt(u: number, v: number): Pt {
    const f = this.field;
    const lx = f.cx + (f.axis === 'x' ? u : v), lz = f.cz + (f.axis === 'x' ? v : u);
    const q = stadiumToIsland(this.b, lx, lz);
    return { x: this.w.ox + q.x, z: this.w.oz + q.z };
  }

  centre(): Pt | null { return this.fieldPt(0, 0); }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF[e.kind];
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    const t = performance.now() / 1000;
    if (this.blimp) {
      const c = this.fieldPt(0, 0), a = t * 0.12, r = 7;
      const x = c.x + Math.cos(a) * r, z = c.z + Math.sin(a) * r;
      this.blimp.fly(x, this.ctx.ground(c.x, c.z) + 7.5, z, a + Math.PI, 0, 0, dt);
      return;
    }
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / spec.lead) * (1 - clamp01((now - (e.end - 0.2)) / 0.2));
    const f = this.field, run = now >= e.start && now < e.end - 0.2;
    // the wrecks in a row across the middle
    this.wrecks.forEach((r, i) => {
      const p = this.fieldPt(0, ((i - 2) / 4) * f.wid * 0.6);
      r.place(this.ctx.worldAt, p.x, p.z, f.axis === 'x' ? 0 : Math.PI / 2, 0, dt);
    });
    let flying = false;
    this.trucks.forEach((r, i) => {
      // round the field, and every few seconds one of them takes the jump down the middle
      const cycle = 9, ph = (t + i * 3) % (cycle * 3);
      const jumping = run && ph < 2.2;
      if (jumping) {
        const u = (ph / 2.2 - 0.5) * f.len * 0.85;
        const p = this.fieldPt(u, 0), y = this.ctx.ground(p.x, p.z) + Math.max(0, 1 - (u / (f.len * 0.3)) ** 2) * 1.2;
        r.fly(p.x, y, p.z, f.axis === 'x' ? Math.PI / 2 : 0, -0.4 * (u / (f.len * 0.42)), 0, dt);
        flying = flying || Math.abs(u) < f.len * 0.3;
      } else {
        const a = (run ? t * 0.6 : 0) + (i / 3) * Math.PI * 2;
        const p = this.fieldPt(Math.cos(a) * f.len * 0.42, Math.sin(a) * f.wid * 0.38);
        const q = this.fieldPt(Math.cos(a + 0.05) * f.len * 0.42, Math.sin(a + 0.05) * f.wid * 0.38);
        r.place(this.ctx.worldAt, p.x, p.z, Math.atan2(q.x - p.x, q.z - p.z), run ? 2 : 0, dt);
      }
    });
    this.crowd.cheer = flying ? 1 : run ? 0.3 : 0;
    this.crowd.update(dt);
  }

  dispose(): void { for (const r of [...this.trucks, ...this.wrecks]) r.dispose(); this.blimp?.dispose(); this.crowd.dispose(); super.dispose(); }
}

/** Which phase 4 show a kind is put on as (shows5.ts has the rest). */
export function phase4Show(e: Happening, ctx: ShowCtx, w: World, p: Place): Show | null {
  if (RUNS[e.kind]) return new RunShow(e, ctx, w, p);
  if (MARCHES[e.kind]) return new MarchShow(e, ctx, w, p);
  switch (e.kind) {
    case 'foodTrucks': case 'circusCaravan': case 'parkConcert': case 'harvestFair': case 'balloonFestival': case 'lanternFestival': case 'veniceCarnival':
      return new LotShow(e, ctx, w, p);
    case 'grandOpening': case 'premiereNight': case 'strikePickets': return new FrontShow(e, ctx, w, p);
    case 'monsterTrucks': case 'sponsorBlimp': return new StadiumShow(e, ctx, w, p);
    default: return null;
  }
}

