import type { Arch, Building, BuildingKind, Town, World } from '../world/tiles';
import { erectProblem, townOfLot, type ErectSpec } from '../world/erect';
import { builtShare } from '../render/townMesh';
import { ERECT_GRACE_S, ERECT_MAX_SIDE, erectHours } from '../../shared/erect';
import { OWNED_OUTRIGHT } from './factions/factions';
import { STATION_KINDS, deeds } from './deeds';
import { builtStat } from './toppers';
import { WONDER_KINDS } from './sights';
import { kindLabel } from './lobby';
import { money } from '../util/format';

/**
 * Blueprints (docs/blueprints.html): own a building and you hold its plans. The book keeps every copy the fleet has
 * bought (or been granted, or bought off a rival) as a variant — its kind, lot, storeys, style and model seed — and
 * the builder's Buildings side lets the fleet pay to put one up again: outside every town's lines, or inside a town
 * the fleet holds. The copy stands at once under hoarding and cranes (an `erect` edit, world/erect.ts), is the
 * fleet's by deed from the first spade, and trades once the site is done. Cancelling the build pays everything back
 * within the first ten seconds, half after, nothing once it stands (sell it instead).
 */

export interface Blueprint {
  /** `kind|w×d|floors|style`: one entry per distinct copy, so a roman house and a hobbit one sit side by side. */
  id: string;
  kind: BuildingKind;
  /** The copy's lot at facing 0, its storeys, and the seed its model was drawn with. */
  w: number; d: number; floors: number; seed: number;
  /** The copy's style when bought: its own imported one, else its town's. */
  style: Arch;
  solid: boolean;
  /** The game day it entered the book, and the town (or county) it was bought in. */
  day: number; from: string;
}

/**
 * The styles a copy may go up in at a place (the user, 5 Nov 2026: owning a house lets you build a house anywhere,
 * in the cultures already there): inside a town's lines its own style and every one it is Influenced by
 * (`influenced`, game/culture.ts styles); in open country those of every town of the county; a county with no towns,
 * the plain style.
 */
export function stylesAt(w: World, town: Town | null, influenced: (t: Town) => Arch[]): Arch[] {
  const of = (t: Town): Arch[] => [t.style, ...influenced(t)];
  const list = town ? of(town) : w.towns.flatMap(of);
  return list.length ? [...new Set(list)] : ['classic'];
}

/** The style a copy goes up in: the one picked if it may, else its own if it may, else the place's first. */
export function buildStyle(list: Arch[], own: Arch, pick: string | null): Arch {
  if (pick && list.includes(pick as Arch)) return pick as Arch;
  return list.includes(own) ? own : list[0];
}

/** Saved: [kind, w, d, floors, seed, style, solid, day, from]. */
export type SavedBlueprint = [string, number, number, number, number, string, 0 | 1, number, string];

export const blueprintId = (kind: string, w: number, d: number, floors: number, style: string): string => `${kind}|${w}x${d}|${floors}|${style}`;

/** What a variant is called beside its kind: "2×2 · 2 storeys · roman". */
export function variantLabel(bp: Blueprint, own = true): string {
  const parts = [`${bp.w}×${bp.d}`, bp.floors > 1 ? `${bp.floors} storeys` : '1 storey'];
  if (own) parts.push(bp.style);
  return parts.join(' · ');
}

/** Kinds that are never plans: they are leagues, meetings, lines or the world's one-offs, not buildings to copy. */
const NEVER = new Set<string>(['stadium', 'arena', 'raceCircuit', 'landmark', 'triumphalArch', 'field', 'parking', ...STATION_KINDS]);

interface BlueprintHost {
  hours(): number;
  worlds(): World[];
  /** The style a building is drawn in, as the mesher reads it: its own, else its town's. */
  styleOf(w: World, b: Building): Arch;
  /** What putting this copy up costs here (estate.buildPrice): the equivalent purchase and half again. */
  price(w: World, bp: Blueprint, town: Town | null): number;
  /** Does the fleet hold this town, with nobody contesting it? */
  holds(w: World, t: Town): boolean;
  /**
   * The culture gate (docs/culturegate.html): why a copy in `style` may not stand inside this town's lines, or with
   * no town in this county's open country; null when the style is native there (the town's own, or one it is
   * Influenced by; in the country, either for any town of the county).
   */
  native(w: World, town: Town | null, style: Arch): string | null;
  /** The fleet's deed for a building, if it has one, and the deed book's standing buildings (for the backfill). */
  owns(w: World, b: Building): boolean;
  owned(): { w: World; b: Building }[];
  /** The deed on the click (estate.grantBuilt). */
  grant(w: World, b: Building, paid: number): void;
  /** Money back (a cancelled site, or ground taken before the crew arrived). */
  refund(amount: number, why: string): void;
  announce(title: string, body: string): void;
  /** The teaching missions: a copy has been put up. */
  made(): void;
  /** Online: this player's id, so a construction that lands can be told from another fleet's. */
  me(): string | null;
}

/** A click paid for and sent: until its edit lands (at once offline; on the server's echo online) it is pending. */
interface Pending { cell: string; x: number; z: number; kind: string; price: number; since: number }

/** A site of the fleet's own under construction, for refunds: what it cost and when ground was broken (real ms). */
/** A site of the fleet's own going up: what it cost, when, and its style (counted for the culture toppers when it stands). */
interface OwnSite { price: number; since: number; st?: string }

/** Real seconds before a pending click whose edit never landed is paid back. */
const LOST_S = 20;

export class Blueprints {
  private book = new Map<string, Blueprint>();
  /** The book changed: the builder redraws its squares. */
  onChange: (() => void) | null = null;
  private pending: Pending[] = [];
  private sites = new Map<string, OwnSite>();
  private sweepT = 0;
  /** Prices are worked out once per lot judged, not every frame: by cell, variant, town and the island's revision. */
  private priceCache = new Map<string, number>();

  constructor(private host: BlueprintHost) {}

  // ---- the book ----

  /** Why a building's plans can't be held, or null when they can. */
  eligible(w: World, b: Building): string | null {
    if (NEVER.has(b.kind) || WONDER_KINDS.has(b.kind)) return 'one of a kind';
    if (OWNED_OUTRIGHT.has(b.kind)) return 'a faction’s own';
    if (b.storefront) return 'its ring is the county’s';
    if (w.ports.some((p) => p.buildings.includes(b))) return 'a harbour’s';
    if (w.works.some((g) => g.buildings.includes(b))) return 'part of the works';
    if (w.stations.some((s) => s.building === b)) return 'a station';
    const lot = this.lotOf(b);
    if (lot.w > ERECT_MAX_SIDE || lot.d > ERECT_MAX_SIDE) return 'too big to copy';
    return null;
  }

  /** The copy's lot as it was built, in the facing-0 frame. */
  private lotOf(b: Pick<Building, 'w' | 'd' | 'facing'>): { w: number; d: number } {
    return b.facing % 2 ? { w: b.d, d: b.w } : { w: b.w, d: b.d };
  }

  /** The fleet has come to own this building: its plans go in the book, if they aren't there. Returns the entry, or null. */
  learn(w: World, b: Building, quiet = false): Blueprint | null {
    if (this.eligible(w, b)) return null;
    const { w: lw, d: ld } = this.lotOf(b);
    const style = this.host.styleOf(w, b);
    const id = blueprintId(b.kind, lw, ld, b.floors, style);
    const have = this.book.get(id);
    if (have) return have;
    const t = w.towns.find((q) => q.buildings.includes(b));
    const bp: Blueprint = { id, kind: b.kind, w: lw, d: ld, floors: Math.max(1, b.floors), seed: b.seed >>> 0, style, solid: b.solid, day: Math.floor(this.host.hours() / 24), from: t?.name ?? w.name };
    this.book.set(id, bp);
    deeds.best('blueprints', this.book.size);
    if (!quiet) this.host.announce('Blueprint', `${kindLabel(b.kind)} · ${variantLabel(bp)} · build it again from the builder’s Buildings side`);
    this.onChange?.();
    return bp;
  }

  get size(): number { return this.book.size; }
  has(id: string): boolean { return this.book.has(id); }
  get(id: string): Blueprint | null { return this.book.get(id) ?? null; }

  /** Every entry, by kind then size. */
  list(): Blueprint[] {
    return [...this.book.values()].sort((a, b) => kindLabel(a.kind).localeCompare(kindLabel(b.kind)) || a.w * a.d - b.w * b.d || a.floors - b.floors || a.style.localeCompare(b.style));
  }

  /** The kinds held, each with its variants: what the Buildings side shows as squares and bubbles. */
  kinds(): { kind: BuildingKind; label: string; variants: Blueprint[] }[] {
    const by = new Map<BuildingKind, Blueprint[]>();
    for (const bp of this.list()) { const l = by.get(bp.kind) ?? []; l.push(bp); by.set(bp.kind, l); }
    return [...by.entries()].map(([kind, variants]) => ({ kind, label: kindLabel(kind), variants }));
  }

  // ---- placing ----

  hours(bp: Blueprint): number { return erectHours(bp.w, bp.d, bp.floors); }

  /** The lot a variant takes turned `turn` quarter-turns, its corner tile under a point of the ground. */
  lotAt(bp: Blueprint, turn: number, x: number, z: number): { x: number; z: number; w: number; d: number; f: number } {
    const f = turn & 3;
    const w = f % 2 ? bp.d : bp.w, d = f % 2 ? bp.w : bp.d;
    return { x: Math.round(x - w / 2), z: Math.round(z - d / 2), w, d, f };
  }

  /** The edit a variant makes at a lot, in `style` (one native there: main.ts buildStyle), else its own. */
  spec(bp: Blueprint, lot: { x: number; z: number; w: number; d: number; f: number }, style: Arch = bp.style): ErectSpec {
    return { kind: bp.kind, x: lot.x, z: lot.z, w: lot.w, d: lot.d, f: lot.f, fl: bp.floors, seed: bp.seed, st: style, solid: bp.solid ? 1 : 0, hrs: this.hours(bp) };
  }

  /**
   * Why the copy can't stand at this lot, or null. The facing is the lot's; where the street is behind rather than in
   * front, the lot is turned about (the same tiles) before it is refused for want of a door. Its style never refuses
   * it (the user, 5 Nov 2026): a copy goes up in a style native where it stands (the town's own or one it is
   * Influenced by; in open country any town of the county's), its own only where that is one of them.
   */
  problem(w: World, bp: Blueprint, lot: { x: number; z: number; w: number; d: number; f: number }): { why: string | null; f: number } {
    const holder = (t: Town) => this.host.holds(w, t);
    const first = erectProblem(w, this.spec(bp, lot), holder);
    if (!first) return { why: null, f: lot.f };
    if (!first.startsWith('No road at the door')) return { why: first, f: lot.f };
    // the same tiles facing the other way, and for a square lot either side too: wherever the street is
    const others = lot.w === lot.d ? [1, 2, 3] : [2];
    for (const turn of others) {
      const about = { ...lot, f: (lot.f + turn) & 3 };
      if (!erectProblem(w, this.spec(bp, about), holder)) return { why: null, f: about.f };
    }
    return { why: first, f: lot.f };
  }

  /** Is a variant's style native anywhere in this county's open country (the Buildings side's chips)? */
  nativeHere(w: World, bp: Blueprint): boolean { return this.host.native(w, null, bp.style) === null; }

  /** What the copy costs at a lot: inside a town's lines at the town's rate, else the county's. */
  price(w: World, bp: Blueprint, town: Town | null): number {
    const key = `${w.cx},${w.cz}|${bp.id}|${town?.id ?? -1}|${w.revision}`;
    let p = this.priceCache.get(key);
    if (p === undefined) {
      if (this.priceCache.size > 400) this.priceCache.clear();
      p = this.host.price(w, bp, town);
      this.priceCache.set(key, p);
    }
    return p;
  }


  /** Paid and sent: remember the click until its building stands. */
  broke(w: World, s: ErectSpec, price: number): void {
    this.pending.push({ cell: `${w.cx},${w.cz}`, x: s.x, z: s.z, kind: s.kind, price, since: performance.now() });
  }

  /**
   * A construction has been stood on an island (world/erect.ts): if it is a click of this fleet's that was waiting
   * to land, the deed is granted and the clock on refunds starts. Another fleet's, or a replay on load, is nobody's
   * business here.
   */
  erected(w: World, b: Building, e: ErectSpec & { by?: string; at?: number }): void {
    const cell = `${w.cx},${w.cz}`;
    const k = this.pending.findIndex((p) => p.cell === cell && p.x === e.x && p.z === e.z && p.kind === e.kind);
    if (k < 0) return;
    const me = this.host.me();
    if (e.by && me && e.by !== me) return;
    const [p] = this.pending.splice(k, 1);
    this.host.grant(w, b, p.price);
    this.sites.set(this.keyOf(w, b), { price: p.price, since: p.since, ...(e.st ? { st: e.st } : {}) });
    deeds.add('erected');
    this.host.made();
    this.host.announce('Breaking ground', `${kindLabel(b.kind)} · ${money(p.price)} · about ${this.hoursWord(e.hrs)} to build`);
  }

  private hoursWord(h: number): string {
    const s = Math.round(h * 25);
    return s < 90 ? `${s} s` : `${Math.round(s / 60)} min`;
  }

  private keyOf(w: World, b: Building): string { return `${w.cx},${w.cz}#b${b.uid}`; }

  // ---- refunds ----

  /**
   * What cancelling a site of the fleet's own would pay back now: everything within the first ten seconds, half
   * while it is still going up, nothing once it stands. Null for anything that isn't the fleet's site.
   */
  refund(w: World, b: Building): { share: 1 | 0.5; amount: number } | null {
    if (!b.erected || b.gone || !this.host.owns(w, b) || builtShare(b) >= 1) return null;
    const site = this.sites.get(this.keyOf(w, b));
    // what it cost: the click's price, or after a reload what the deed was booked at
    const price = site?.price ?? this.paidFor(w, b);
    if (price === null) return null;
    const share: 1 | 0.5 = site && (performance.now() - site.since) / 1000 <= ERECT_GRACE_S ? 1 : 0.5;
    return { share, amount: Math.round(price * share) };
  }

  /** The deed book's figure for a site, set by the game (estate.owns(w, b)?.paid). */
  paidFor: (w: World, b: Building) => number | null = () => null;

  /** The site is being cleared: pay the refund back, if any, and forget it. Returns what was paid back. */
  cancelled(w: World, b: Building): number {
    const r = this.refund(w, b);
    this.sites.delete(this.keyOf(w, b));
    if (!r || r.amount <= 0) return 0;
    this.host.refund(r.amount, r.share === 1 ? 'cancelled in time' : 'cancelled half-built');
    return r.amount;
  }

  // ---- time ----

  update(dt: number): void {
    this.sweepT -= dt;
    if (this.sweepT > 0) return;
    this.sweepT = 2;
    // a click whose building never came (online, ground taken first): the money comes back
    const now = performance.now();
    for (const p of [...this.pending]) {
      if ((now - p.since) / 1000 < LOST_S) continue;
      this.pending.splice(this.pending.indexOf(p), 1);
      this.host.refund(p.price, 'ground taken');
      this.host.announce('Nothing built', `The ground at ${p.x},${p.z} was taken before your crew arrived · ${money(p.price)} refunded`);
    }
    // the backfill: every building the fleet owns and can see has its plans in the book (a save from before the
    // book, a fleet-mate's purchase in a shared fleet, a deed granted some other way)
    for (const { w, b } of this.host.owned()) if (!b.gone) this.learn(w, b, true);
    // sites finished or gone are no longer refundable
    for (const [key, s] of [...this.sites]) {
      const m = /^(-?\d+),(-?\d+)#b(\d+)$/.exec(key);
      const w = m ? this.host.worlds().find((q) => q.cx === Number(m[1]) && q.cz === Number(m[2])) : undefined;
      const b = w && m ? w.allBuildings[Number(m[3])] : undefined;
      if (w && (!b || b.gone || builtShare(b) >= 1)) {
        // a copy of the fleet's own finished (not cancelled, not cleared): one more of its style (docs/toppers.html phase 3)
        if (b && !b.gone && s.st) deeds.add(builtStat(s.st));
        this.sites.delete(key);
      }
    }
  }

  // ---- saving ----

  toSave(): SavedBlueprint[] {
    return this.list().map((bp) => [bp.kind, bp.w, bp.d, bp.floors, bp.seed, bp.style, bp.solid ? 1 : 0, bp.day, bp.from]);
  }

  fromSave(saved: SavedBlueprint[] | undefined): void {
    this.book.clear();
    this.pending = [];
    this.sites.clear();
    this.priceCache.clear();
    this.adopt(saved);
  }

  /** Plans from a save (this one, or a fleet-mate's in a shared fleet): added to the book, never taken from it. */
  adopt(saved: SavedBlueprint[] | undefined): void {
    let added = 0;
    for (const t of saved ?? []) {
      if (!Array.isArray(t) || t.length < 9 || typeof t[0] !== 'string' || typeof t[5] !== 'string') continue;
      const [kind, w, d, floors, seed, style, solid, day, from] = t;
      if (!(w >= 1 && w <= ERECT_MAX_SIDE && d >= 1 && d <= ERECT_MAX_SIDE && floors >= 1)) continue;
      const id = blueprintId(kind, w, d, floors, style);
      if (this.book.has(id)) continue;
      this.book.set(id, { id, kind: kind as BuildingKind, w, d, floors, seed: Number(seed) >>> 0, style: style as Arch, solid: solid === 1, day: Number(day) || 0, from: String(from ?? '') });
      added++;
    }
    if (added) { deeds.best('blueprints', this.book.size); this.onChange?.(); }
  }

  // ---- the console: pr.blueprints ----

  console(find: (w: World, x: number, z: number) => Building | null) {
    return {
      /** Every plan held. */
      list: () => this.list().map((bp) => `${bp.id} · from ${bp.from} day ${bp.day}`),
      /** Learn the plans of the building on tile (x, z) of the island in memory at cell (cx, cz), paying nothing. */
      learn: (cx: number, cz: number, x: number, z: number) => {
        const w = this.host.worlds().find((q) => q.cx === cx && q.cz === cz);
        const b = w ? find(w, x, z) : null;
        if (!w || !b) return 'no building there';
        const why = this.eligible(w, b);
        return why ? `not eligible: ${why}` : this.learn(w, b)?.id ?? 'already held';
      },
      pending: () => this.pending.map((p) => `${p.cell} ${p.kind} at ${p.x},${p.z} · ${money(p.price)} · ${Math.round((performance.now() - p.since) / 1000)} s`),
      sites: () => [...this.sites.entries()].map(([k, s]) => `${k} · ${money(s.price)} · ${Math.round((performance.now() - s.since) / 1000)} s ago`),
    };
  }
}
