/**
 * The out-of-date check. As the game opens, it asks the online server what it runs (online.json: the world's
 * GEN, the protocol and the release version) and compares that with its own (GEN_VERSION, PROTOCOL and the
 * build.json scripts/package.py writes beside index.html). A copy that can no longer play online (a new
 * world, a new protocol) gets a card at once saying how to update, written for where it is running: a
 * downloaded copy (the launchers serve it on localhost:47615) is pointed at the new zip for its system, a
 * page is told to reload, and anything else (itch.io) to reload or play in the browser at the server. A copy
 * that is only a release behind gets a smaller card, and only when it was downloaded: a page is always the
 * newest when it loads. "Later" hides that one until the next release.
 */
import { GEN_VERSION } from '../world/generate';
import { PROTOCOL } from '../../shared/protocol';

interface ServerInfo { tinyfleet?: boolean; gen?: number; protocol?: number; version?: string; get?: { windows?: string; mac?: string } }

const LATER_KEY = 'tinyfleet-update-later';
/** The port both launchers serve a downloaded copy on (launcher/PocketRoads.cs, launcher/mac/TinyFleet). */
const LAUNCHER_PORT = '47615';
const BUILT_FOR = String(import.meta.env.VITE_ONLINE_URL ?? '').replace(/\/+$/, '');

/** Ask the server, and show the card if this copy is behind. Never throws; quiet when offline. */
export async function updateCheck(): Promise<void> {
  // ?updatecard=hard|soft shows the card on any copy, to see it
  const force = new URLSearchParams(location.search).get('updatecard');
  if (!force && (navigator.webdriver || /HeadlessChrome/.test(navigator.userAgent))) return;
  const base = await serverBase();
  if (!base) return;
  const [info, mine] = await Promise.all([getJson<ServerInfo>(`${base}/online.json`), getJson<{ version?: string }>(new URL('build.json', location.href).toString())]);
  const theirs = typeof info?.version === 'string' ? info.version : '';
  const ours = typeof mine?.version === 'string' ? mine.version : '';
  if (force) { show(force === 'soft' ? 'soft' : 'hard', base, info ?? {}, ours || '0.6.7', theirs || '0.7.0'); return; }
  if (!info?.tinyfleet) return;
  // a server whose world is older than this copy is a developer's: nothing to say
  const hard = (typeof info.gen === 'number' && info.gen > GEN_VERSION) || (typeof info.protocol === 'number' && info.protocol > PROTOCOL);
  const soft = !hard && !!ours && !!theirs && newer(theirs, ours) && where(base) === 'download';
  if (!hard && !soft) return;
  if (soft) try { if (localStorage.getItem(LATER_KEY) === theirs) return; } catch { /* storage blocked: ask again */ }
  show(hard ? 'hard' : 'soft', base, info, ours, theirs);
}

/** The server this copy plays on: the one serving it, else the one it was built for. */
async function serverBase(): Promise<string> {
  if (/^https?:$/.test(location.protocol) && location.port !== LAUNCHER_PORT) {
    const here = await getJson<ServerInfo>(new URL('online.json', location.href).toString());
    if (here?.tinyfleet) return location.origin + location.pathname.replace(/\/play\/.*$|\/[^/]*$/, '');
  }
  // a dev game plays on the server beside it (net/online.ts defaultServer)
  return BUILT_FOR || (import.meta.env.DEV ? 'http://localhost:8787' : '');
}

async function getJson<T>(url: string): Promise<T | null> {
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), 6000);
  try {
    const r = await fetch(url, { cache: 'no-store', signal: ctl.signal });
    return r.ok && /json/.test(r.headers.get('content-type') ?? '') ? await r.json() as T : null;
  } catch { return null; } finally { clearTimeout(timer); }
}

/** "0.7.0" after "0.6.7"? */
function newer(a: string, b: string): boolean {
  const pa = a.split('.').map(Number), pb = b.split('.').map(Number);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) if ((pa[i] ?? 0) !== (pb[i] ?? 0)) return (pa[i] ?? 0) > (pb[i] ?? 0);
  return false;
}

/** A downloaded copy, a page the server itself serves, or somewhere else (itch.io's embed). */
function where(base: string): 'download' | 'page' | 'elsewhere' {
  if (/^(localhost|127\.0\.0\.1)$/.test(location.hostname) && location.port === LAUNCHER_PORT) return 'download';
  return base && location.origin === new URL(base).origin ? 'page' : 'elsewhere';
}

const esc = (s: string): string => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));

function show(kind: 'hard' | 'soft', base: string, info: ServerInfo, ours: string, theirs: string): void {
  if (document.getElementById('update-card')) return;
  const at = where(base);
  const mac = /Mac/i.test(navigator.platform || navigator.userAgent);
  const file = (f: string | undefined, fallback: string): string => `${base}/${(f ?? fallback).replace(/^\/+/, '')}`;
  const win = file(info.get?.windows, 'downloads/TinyFleet-Windows.zip'), macZip = file(info.get?.mac, 'downloads/TinyFleet-Mac.zip');
  const host = base.replace(/^https?:\/\//, '');
  const nums = ours && theirs ? ` This copy is <b>${esc(ours)}</b>; the newest is <b>${esc(theirs)}</b>.` : '';
  const title = kind === 'hard' ? 'TinyFleet has been updated' : 'A new version of TinyFleet is out';
  // a new GEN starts the online world again: say so, and that the career comes along (net/online.ts carry)
  const fresh = kind === 'hard' && typeof info.gen === 'number' && info.gen > GEN_VERSION
    ? '<br><br><b>The world has started again with this release.</b> Your fleet, money, Passport stamps and deeds come with you into the new one.'
    : '';
  const lead = kind === 'hard'
    ? `The online world now runs a newer version, so this copy can’t join it until it’s updated.${nums}${fresh}`
    : `Your copy still works, but the new one has fixes and new things to find.${nums}`;
  let how = '', buttons = '';
  if (at === 'download') {
    how = `<ol><li>Download the new copy for ${mac ? 'Mac' : 'Windows'}.</li><li>Unzip it and open TinyFleet${mac ? '' : '.exe'} from the new folder. You can delete the old folder: your fleet is kept online, and settings carry over.</li></ol>`;
    buttons = `<a class="uc-go" href="${esc(mac ? macZip : win)}" target="_blank" rel="noopener">Download for ${mac ? 'Mac' : 'Windows'}</a>
      <a class="uc-link" href="${esc(mac ? win : macZip)}" target="_blank" rel="noopener">${mac ? 'Windows' : 'Mac'} version</a>
      <a class="uc-link" href="${esc(base)}/play/" target="_blank" rel="noopener">Play in your browser instead</a>`;
  } else if (at === 'page') {
    how = '<p>Reloading the page fetches the new version.</p>';
    buttons = '<button type="button" class="uc-go" data-act="reload">Reload now</button>';
  } else {
    // somewhere else (itch.io's player): this copy only changes once the new one is uploaded there, so reloading
    // may well bring this card back; the server's own page always has the newest
    how = `<p>The newest version is always at <b>${esc(host)}</b>. This copy updates once the new version reaches this page: reload later to check.</p>`;
    buttons = `<a class="uc-go" href="${esc(base)}/play/" target="_blank" rel="noopener">Play at ${esc(host)}</a>
      <button type="button" class="uc-link" data-act="reload">Reload</button>`;
  }
  const el = document.createElement('div');
  el.id = 'update-card';
  el.setAttribute('role', 'alertdialog');
  el.setAttribute('aria-labelledby', 'uc-title');
  el.innerHTML = `<style>
    #update-card { position: fixed; inset: 0; z-index: 2147483646; display: flex; align-items: center; justify-content: center; padding: 16px; box-sizing: border-box; background: rgba(20,28,34,.55); backdrop-filter: blur(6px); font-family: "IBM Plex Sans", "Segoe UI", system-ui, sans-serif; color: #1f2b33; }
    body.dark-ui > #update-card { filter: none !important; }
    #update-card .uc { width: min(520px, 100%); max-height: calc(100vh - 32px); overflow: auto; background: #f4f7f1; border-radius: 16px; padding: 24px 26px; box-shadow: 0 20px 60px rgba(0,0,0,.35); }
    #update-card .uc-ic { font-size: 34px; line-height: 1; margin-bottom: 8px; }
    #update-card h2 { font-family: "Fredoka", "Segoe UI", sans-serif; font-size: 22px; margin: 0 0 8px; }
    #update-card p, #update-card ol { font-size: 15px; line-height: 1.5; color: #4c5a63; margin: 0 0 12px; }
    #update-card ol { padding-left: 22px; }
    #update-card .uc-row { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; margin-top: 6px; }
    #update-card .uc-go { font: inherit; font-size: 15px; padding: 9px 16px; border-radius: 8px; border: 0; background: #e2412f; color: #fff; cursor: pointer; text-decoration: none; }
    #update-card .uc-link, #update-card .uc-later { font: inherit; font-size: 13px; background: none; border: 0; padding: 0; color: #7d8a92; text-decoration: underline; cursor: pointer; }
  </style>
  <div class="uc">
    <div class="uc-ic">${kind === 'hard' ? '🚚' : '✨'}</div>
    <h2 id="uc-title">${title}</h2>
    <p>${lead}</p>
    ${how}
    <div class="uc-row">${buttons}<button type="button" class="uc-later" data-act="later">${kind === 'hard' ? 'Not now' : 'Later'}</button></div>
  </div>`;
  el.addEventListener('click', (e) => {
    const act = (e.target as HTMLElement).closest('[data-act]')?.getAttribute('data-act');
    if (act === 'reload') location.reload();
    else if (act === 'later') {
      if (kind === 'soft' && theirs) try { localStorage.setItem(LATER_KEY, theirs); } catch { /* asked again next time */ }
      el.remove();
    }
  });
  document.body.appendChild(el);
}
