import { hex, scale, type RGB } from '../../../world/biomes';
import type { RegionBuildingKind } from '../../../world/tiles';
import { DARK, GLASS, TAU, WARM_GLOW, WHITE, win, type Draw, type Kit, type P3 } from '../kit';

/**
 * The Green: stilt houses, the canopy walkway, rope bridges, the plantation's drying shed, the
 * trading post, and the wonder, the lost temple, a moss-grown stepped pyramid in the trees.
 */

const TIMBER = hex(0x7a5534), TIMBER_DK = hex(0x5a3d26), THATCH = hex(0xc2a15a), ROPE = hex(0xb89c6a);
const CANOPY = [0x2f6b34, 0x3d7a3a, 0x357238].map(hex), CANOPY_TOP = hex(0x4a8a3f), BARK = hex(0x6a5a48);
const FIRE = hex(0xff8a3a);

/** A rainforest tree: a tall bare trunk and a wide flat crown. */
function canopyTree(k: Kit, x: number, y: number, z: number, h: number, R: number, seed: number): void {
  k.box(x, y, z, 0.07, h, 0.07, BARK);
  k.bar([x, y + h * 0.7, z], [x + R * 0.5, y + h * 0.9, z + R * 0.2], 0.02, BARK);
  k.cyl(x, y + h - 0.04, z, R, 0.12, CANOPY[seed % 3], 7);
  k.dome(x + R * 0.2, y + h + 0.08, z - R * 0.15, R * 0.62, CANOPY_TOP, 6, 2);
}

/** A point along a sagging span from a to b, t in 0..1. */
const sag = (a: P3, b: P3, t: number, drop: number): P3 =>
  [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t - drop * 4 * t * (1 - t), a[2] + (b[2] - a[2]) * t];

/** A rope-and-plank walk slung between two points: a deck, two handropes and a few hangers. */
function ropeWalk(k: Kit, a: P3, b: P3, drop: number, half: number, n: number, rail = 0.16): void {
  const dx = b[0] - a[0], dz = b[2] - a[2], len = Math.hypot(dx, dz) || 1;
  const px = (-dz / len) * half, pz = (dx / len) * half;
  for (let i = 0; i < n; i++) {
    const p = sag(a, b, i / n, drop), q = sag(a, b, (i + 1) / n, drop);
    k.quad([p[0] - px, p[1], p[2] - pz], [p[0] + px, p[1], p[2] + pz], [q[0] + px, q[1], q[2] + pz], [q[0] - px, q[1], q[2] - pz], i % 2 ? TIMBER : scale(TIMBER, 1.15), [(p[0] + q[0]) / 2, p[1] - 0.2, (p[2] + q[2]) / 2]);
  }
  const m = Math.max(2, Math.round(n / 2));
  for (const s of [-1, 1]) {
    for (let i = 0; i < m; i++) {
      const p = sag(a, b, i / m, drop * 0.7), q = sag(a, b, (i + 1) / m, drop * 0.7);
      k.bar([p[0] + s * px, p[1] + rail, p[2] + s * pz], [q[0] + s * px, q[1] + rail, q[2] + s * pz], 0.007, ROPE);
      if (i > 0 && i % 2 === 0) {
        const d = sag(a, b, i / m, drop);
        k.bar([d[0] + s * px, d[1], d[2] + s * pz], [p[0] + s * px, p[1] + rail, p[2] + s * pz], 0.005, ROPE);
      }
    }
  }
}

// ---- 1. stilt house ----------------------------------------------------------------------------

const stiltHouse: Draw = (k, _W, _D, b, r) => {
  const deck = 0.32, tin = r() < 0.5, wall = r() < 0.5 ? hex(0x9a6e44) : hex(0xb08a5a);
  // posts down into the water or the mud, with a cross brace
  for (const sx of [-0.36, 0, 0.36]) for (const sz of [-0.34, 0.34]) k.box(sx, -0.6, sz, 0.045, 0.6 + deck, 0.045, TIMBER_DK);
  for (const sz of [-0.34, 0.34]) k.bar([-0.36, -0.3, sz], [0.36, deck - 0.04, sz], 0.012, TIMBER_DK);
  k.box(0, deck, 0, 0.84, 0.04, 0.8, TIMBER, scale(TIMBER, 1.12));
  // the room, a shade back from the veranda
  k.box(0, deck + 0.04, -0.1, 0.62, 0.26, 0.48, wall);
  const ry = deck + 0.3;
  if (tin) {
    k.gable(0, ry, -0.02, 0.8, 0.16, 0.72, r() < 0.5 ? hex(0xa8402f) : hex(0x6b7a72), wall);
  } else {
    k.hip(0, ry, -0.02, 0.86, 0.24, 0.76, THATCH);
    k.hip(0, ry + 0.02, -0.02, 0.62, 0.24, 0.54, scale(THATCH, 0.9));
  }
  k.box(0.1, deck + 0.04, 0.145, 0.12, 0.18, 0.02, TIMBER_DK);
  win(k, b, r, -0.16, deck + 0.14, 0.14, 0.12, 0.08, 1, GLASS);
  win(k, b, r, 0.31, deck + 0.14, -0.1, 0.12, 0.08, 0, GLASS);
  // veranda posts and rail
  for (const sx of [-0.4, 0.4]) k.box(sx, deck + 0.04, 0.37, 0.03, 0.26, 0.03, TIMBER_DK);
  k.box(-0.18, deck + 0.14, 0.38, 0.44, 0.02, 0.02, TIMBER_DK);
  // the ladder down the front
  for (const sx of [0.2, 0.32]) k.bar([sx, deck, 0.4], [sx, -0.2, 0.62], 0.012, TIMBER_DK);
  for (let i = 0; i < 4; i++) {
    const t = (i + 0.5) / 4;
    k.bar([0.2, deck - t * (deck + 0.2), 0.4 + t * 0.22], [0.32, deck - t * (deck + 0.2), 0.4 + t * 0.22], 0.008, TIMBER);
  }
  // a dugout tied up underneath and a water jar
  k.box(-0.15, -0.08, 0.1, 0.12, 0.05, 0.62, TIMBER_DK);
  k.cyl(-0.3, deck + 0.04, 0.3, 0.04, 0.08, hex(0xb4623a), 6);
};

// ---- 2. canopy walkway -------------------------------------------------------------------------

const canopyWalkway: Draw = (k, W, D, b, r) => {
  const towers: [number, number, number][] = [[-1.3, -1.25, 1.5], [1.25, -1.1, 1.75], [1.15, 1.05, 1.4], [-1.05, 1.2, 1.6]];
  towers.forEach(([x, z, h], i) => {
    // the tree the platform hugs
    canopyTree(k, x + 0.12, 0, z - 0.12, h + 0.55, 0.6, i);
    for (const sx of [-0.2, 0.2]) for (const sz of [-0.2, 0.2]) k.box(x + sx, 0, z + sz, 0.04, h, 0.04, TIMBER_DK);
    for (const lv of [0.5]) {
      k.bar([x - 0.2, lv * h - 0.25, z + 0.2], [x + 0.2, lv * h + 0.05, z + 0.2], 0.01, TIMBER);
      k.bar([x - 0.2, lv * h - 0.25, z - 0.2], [x - 0.2, lv * h + 0.05, z + 0.2], 0.01, TIMBER);
    }
    k.box(x, h, z, 0.56, 0.04, 0.56, TIMBER, scale(TIMBER, 1.15));
    for (const [sx, sz, w, d] of [[0, 0.27, 0.56, 0.02], [0, -0.27, 0.56, 0.02], [0.27, 0, 0.02, 0.56], [-0.27, 0, 0.02, 0.56]]) {
      k.box(x + sx, h + 0.14, z + sz, w, 0.02, d, ROPE);
    }
  });
  // a thatched lookout on the tallest
  const [tx, tz, th] = towers[1];
  for (const sx of [-0.24, 0.24]) for (const sz of [-0.24, 0.24]) k.box(tx + sx, th + 0.04, tz + sz, 0.025, 0.3, 0.025, TIMBER_DK);
  k.hip(tx, th + 0.34, tz, 0.7, 0.22, 0.7, THATCH);
  // the rope walks, deck to deck
  for (let i = 0; i < 3; i++) {
    const [ax, az, ah] = towers[i], [bx, bz, bh] = towers[i + 1];
    const dx = bx - ax, dz = bz - az, l = Math.hypot(dx, dz), ux = dx / l, uz = dz / l;
    ropeWalk(k, [ax + ux * 0.28, ah + 0.04, az + uz * 0.28], [bx - ux * 0.28, bh + 0.04, bz - uz * 0.28], 0.28, 0.07, 8);
  }
  // a ladder up the first tower
  const [lx, lz, lh] = towers[0];
  for (const sx of [-0.08, 0.08]) k.bar([lx + sx, 0, lz + 0.42], [lx + sx, lh, lz + 0.22], 0.01, TIMBER_DK);
  for (let i = 1; i < 7; i++) k.box(lx, (i / 7) * lh, lz + 0.42 - (i / 7) * 0.2, 0.16, 0.012, 0.012, TIMBER);
  // the ranger hut at the foot, with its sign and a lamp
  const hx = 0.15, hz = 0.05, wall = hex(0x8a6a44);
  k.box(hx, 0, hz, 0.6, 0.28, 0.46, wall);
  k.gable(hx, 0.28, hz, 0.72, 0.18, 0.58, hex(0x3f7a4a), wall);
  k.box(hx, 0, hz + 0.24, 0.12, 0.18, 0.02, TIMBER_DK);
  win(k, b, r, hx - 0.18, 0.12, hz + 0.23, 0.12, 0.08, 1);
  win(k, b, r, hx + 0.3, 0.12, hz, 0.14, 0.08, 0);
  k.box(hx + 0.45, 0, hz + 0.45, 0.02, 0.22, 0.02, TIMBER_DK);
  k.box(hx + 0.45, 0.2, hz + 0.45, 0.24, 0.1, 0.02, hex(0xe8d27a));
  k.glowBox(hx - 0.1, 0.24, hz + 0.26, 0.04, 0.04, 0.04, WHITE, [18, 22, 1.4], WARM_GLOW);
  // ferns and saplings on the floor
  for (let i = 0; i < 9; i++) {
    const a = r() * TAU, d = 0.6 + r() * 1.1, x = Math.cos(a) * d, z = Math.sin(a) * d;
    if (Math.abs(x) > W / 2 - 0.2 || Math.abs(z) > D / 2 - 0.2) continue;
    k.dome(x, 0, z, 0.08 + r() * 0.08, CANOPY[i % 3], 5, 1);
  }
};

// ---- 3. rope bridge ----------------------------------------------------------------------------

const ropeBridge: Draw = (k, _W, D) => {
  const e = D / 2 - 0.12;
  // the deck sags into the gorge
  ropeWalk(k, [0, 0.02, -e], [0, 0.02, e], 0.62, 0.18, 18, 0.24);
  for (const sz of [-1, 1]) {
    for (const sx of [-0.24, 0.24]) {
      k.box(sx, -0.1, sz * (e + 0.02), 0.06, 0.46, 0.06, TIMBER_DK);
      k.box(sx, 0.36, sz * (e + 0.02), 0.08, 0.03, 0.08, TIMBER);
      // the main cables, from the post tops to stakes behind
      k.bar([sx, 0.3, sz * (e + 0.02)], [sx * 1.3, 0, sz * (e + 0.12)], 0.008, ROPE);
    }
    k.box(0, 0, sz * (e + 0.02), 0.44, 0.03, 0.14, TIMBER);
  }
};

// ---- 4. plantation drying shed -----------------------------------------------------------------

const plantation: Draw = (k, W, D, _b, r) => {
  const sz = -D / 2 + 0.5, roof = r() < 0.5 ? hex(0x9a5a3a) : hex(0x6b7a72);
  // the open-sided barn
  for (let i = 0; i < 5; i++) for (const zz of [-0.36, 0.36]) k.box(-0.86 + i * 0.43, 0, sz + zz, 0.04, 0.38, 0.04, TIMBER_DK);
  k.gable(0, 0.38, sz, W - 0.1, 0.24, 0.9, roof, TIMBER);
  // tiered drying racks: coffee cherries red, beans green-gold
  const beans = [hex(0x8a3a2a), hex(0xa89a48), hex(0x6a4a2e)];
  for (let i = 0; i < 3; i++) {
    const x = -0.56 + i * 0.56;
    for (const sx of [-0.2, 0.2]) k.box(x + sx, 0, sz, 0.025, 0.3, 0.025, TIMBER);
    for (let s = 0; s < 3; s++) k.box(x, 0.08 + s * 0.08, sz, 0.44, 0.015, 0.5, beans[(i + s) % 3]);
  }
  // the drying patio out front, raked into rows
  const pz = D / 2 - 0.5;
  k.box(-0.25, 0, pz, 1.2, 0.02, 0.8, hex(0xcfc6b0));
  for (let i = 0; i < 5; i++) k.box(-0.25, 0.02, pz - 0.3 + i * 0.15, 1.06, 0.008, 0.09, i % 2 ? beans[0] : beans[2]);
  // sacks by the shed and a cart
  const sack = hex(0xc8b088);
  for (let i = 0; i < 6; i++) {
    const x = 0.55 + (i % 3) * 0.13, y = i < 3 ? 0 : 0.08, z = sz + 0.52 + (i < 3 ? 0 : 0.03);
    k.box(x, y, z, 0.11, 0.08, 0.14, i === 4 ? scale(sack, 0.9) : sack);
  }
  k.box(0.72, 0.06, pz + 0.12, 0.3, 0.06, 0.22, TIMBER);
  for (const sx of [-1, 1]) k.cyl(0.72 + sx * 0.16, 0.06, pz + 0.12, 0.06, 0.012, TIMBER_DK, 6);
  // banana plants at the corner
  const leaf = hex(0x5fa03a);
  for (let p = 0; p < 3; p++) {
    const x = W / 2 - 0.2 - p * 0.18, z = D / 2 - 0.15 - (p % 2) * 0.2;
    k.cyl(x, 0, z, 0.03, 0.3, hex(0x7a8a4a), 5);
    for (let l = 0; l < 5; l++) {
      const a = (l / 5) * TAU + p, c = Math.cos(a), s = Math.sin(a);
      k.quad([x, 0.3, z], [x + c * 0.1 - s * 0.05, 0.36, z + s * 0.1 + c * 0.05], [x + c * 0.24, 0.24, z + s * 0.24], [x + c * 0.1 + s * 0.05, 0.36, z + s * 0.1 - c * 0.05], leaf, [x + c * 0.1, 0.1, z + s * 0.1]);
    }
  }
};

// ---- 5. trading post ---------------------------------------------------------------------------

const tradingPost: Draw = (k, W, D, b, r) => {
  const wall = hex(0x9a6a3e), trim = hex(0xf1e4c8), roof = r() < 0.5 ? hex(0xa8402f) : hex(0x3f7a4a);
  const bz = -D / 2 + 0.3, bd = 0.52, h = 0.36;
  k.box(0, 0, bz, W - 0.3, h, bd, wall);
  k.gable(0, h, bz, W - 0.2, 0.2, bd + 0.12, roof, wall);
  // the false front with its painted sign
  const fz = bz + bd / 2 + 0.01;
  k.box(0, h - 0.02, fz, 1.0, 0.2, 0.03, trim);
  k.box(0, h + 0.03, fz + 0.02, 0.86, 0.11, 0.01, pick2(b.seed));
  for (let i = 0; i < 5; i++) k.box(-0.3 + i * 0.15, h + 0.07, fz + 0.03, 0.09, 0.03, 0.005, trim);
  // doors, windows and shutters
  k.box(0, 0, fz, 0.18, 0.24, 0.02, TIMBER_DK);
  for (const sx of [-1, 1]) {
    win(k, b, r, sx * 0.45, 0.1, fz, 0.2, 0.14, 1);
    for (const so of [-0.13, 0.13]) k.box(sx * 0.45 + so, 0.1, fz + 0.01, 0.05, 0.14, 0.01, roof);
  }
  // the deep veranda
  const vz = fz + 0.2;
  k.box(0, 0, vz, W - 0.1, 0.05, 0.4, TIMBER, scale(TIMBER, 1.15));
  for (let i = 0; i < 5; i++) k.box(-(W - 0.2) / 2 + (i * (W - 0.2)) / 4, 0.05, vz + 0.17, 0.035, 0.24, 0.035, trim);
  const y0 = h - 0.04, y1 = 0.3, z0 = fz, z1 = vz + 0.22, x0 = -(W - 0.1) / 2, x1 = (W - 0.1) / 2;
  k.quad([x0, y0, z0], [x1, y0, z0], [x1, y1, z1], [x0, y1, z1], roof, [0, 0, z0]);
  k.quad([x0, y0 - 0.02, z0], [x1, y0 - 0.02, z0], [x1, y1 - 0.02, z1], [x0, y1 - 0.02, z1], scale(roof, 0.7), [0, 1, z0]);
  // goods out front: crates, sacks, barrels, a lantern
  for (let i = 0; i < 3; i++) k.box(-0.8 + i * 0.13, 0.05, vz + (i % 2) * 0.05, 0.11, 0.1, 0.11, i === 1 ? scale(TIMBER, 1.2) : TIMBER);
  k.box(-0.74, 0.15, vz + 0.02, 0.1, 0.09, 0.1, TIMBER);
  for (let i = 0; i < 2; i++) k.cyl(0.62 + i * 0.14, 0.05, vz + 0.05, 0.05, 0.13, TIMBER_DK, 7, scale(TIMBER, 0.9));
  k.box(0.36, 0.05, vz + 0.06, 0.12, 0.07, 0.1, hex(0xc8b088));
  k.box(0.36, 0.12, vz + 0.06, 0.08, 0.04, 0.06, hex(0xe8d24a));
  k.glowBox(-0.3, 0.24, vz + 0.12, 0.04, 0.05, 0.04, DARK, [17.5, 23, 1.6], WARM_GLOW);
};

const pick2 = (seed: number): RGB => hex([0x2f6b8a, 0x8a2f2f, 0x2f6b3a, 0x6a3a7a][seed % 4]);

// ---- 6. the lost temple (wonder) ---------------------------------------------------------------

const lostTemple: Draw = (k, _W, D, _b, r) => {
  const stone = hex(0x8c9482), dark = hex(0x6a7462), moss = hex(0x5f7a48), light = hex(0xa8ae98);
  const z0 = -1.5, tiers = 6, th = 0.5, base = 7, inset = 0.5;
  // the stepped pyramid, each tier with a moss-grown ledge and a moulding
  for (let i = 0; i < tiers; i++) {
    const s = base - i * inset * 2, c = scale(stone, 0.94 + ((i * 7) % 3) * 0.04);
    k.box(0, i * th, z0, s, th, s, c, moss);
    k.box(0, i * th + th * 0.62, z0, s + 0.06, 0.07, s + 0.06, light, moss);
    // a recessed panel band on each face (the stair covers the front one)
    for (const f of [0, 2, 3]) {
      const ox = f === 0 ? s / 2 + 0.01 : f === 2 ? -s / 2 - 0.01 : 0, oz = f === 3 ? -s / 2 - 0.01 : 0;
      k.box(ox, i * th + 0.08, z0 + oz, f === 3 ? s * 0.7 : 0.02, 0.2, f === 3 ? 0.02 : s * 0.7, dark);
    }
  }
  const top = tiers * th, ts = base - tiers * inset * 2 + inset * 2;
  // the stair up the front face, with its balustrades and serpent heads at the foot
  const front = z0 + base / 2 + 1.2, back = z0 + ts / 2 - inset + 0.3, steps = 24, rise = top / steps, run = (front - back) / steps;
  for (let i = 0; i < steps; i++) {
    const zf = front - i * run, d = zf - z0;
    k.box(0, i * rise, zf - d / 2, 1.8, rise, d, i % 2 ? light : scale(light, 0.94), i % 6 === 3 ? moss : scale(light, 1.08));
  }
  k.box(0, top, back - 0.15, 1.8, 0.02, 0.5, light, scale(light, 1.08));
  for (const sx of [-1, 1]) {
    k.bar([sx * 1.02, 0.14, front + 0.02], [sx * 1.02, top + 0.14, back], 0.13, dark);
    k.box(sx * 1.02, 0, front + 0.2, 0.3, 0.26, 0.36, stone);
    k.box(sx * 1.02, 0.08, front + 0.4, 0.22, 0.13, 0.1, dark);
  }
  // the shrine on top: dark doorway, roof comb, and a fire that burns at night
  const sz0 = z0 - 0.05;
  k.box(0, top, sz0, 1.6, 0.7, 1.3, stone, moss);
  k.box(0, top + 0.7, sz0, 1.76, 0.1, 1.46, light, moss);
  k.box(0, top + 0.8, sz0 - 0.3, 1.1, 0.5, 0.18, dark, moss);
  for (let i = 0; i < 3; i++) k.box(-0.35 + i * 0.35, top + 0.9, sz0 - 0.2, 0.14, 0.24, 0.02, scale(dark, 0.7));
  k.box(0, top, sz0 + 0.655, 0.44, 0.5, 0.02, hex(0x1e2218));
  for (const sx of [-0.45, 0.45]) k.box(sx, top, sz0 + 0.68, 0.14, 0.62, 0.08, light);
  k.glowBox(0, top + 0.02, sz0 + 0.672, 0.3, 0.24, 0.02, hex(0x2a2a22), [18.5, 29.5, 1.8], FIRE);
  for (const sx of [-0.8, 0.8]) {
    k.cyl(sx, top, back + 0.25, 0.08, 0.14, dark, 6);
    k.glowBox(sx, top + 0.14, back + 0.25, 0.08, 0.05, 0.08, hex(0x3a3a30), [18.5, 29.5, 1.6], FIRE);
  }
  // the flanking platforms, each with a broken colonnade
  for (const sx of [-1, 1]) {
    const px = sx * 4.8, pz = 1.1;
    k.box(px, 0, pz, 2.2, 0.45, 3.2, stone, moss);
    k.box(px, 0.45, pz - 0.2, 1.6, 0.4, 2.4, scale(stone, 0.95), moss);
    for (let i = 0; i < 5; i++) k.box(px, i * 0.17, pz + 1.6 + 0.3 - i * 0.07, 0.7, 0.17, 0.6 - i * 0.07 * 2 + 0.14, light, i === 4 ? moss : light);
    for (let i = 0; i < 6; i++) {
      const cx = px + (i % 2 ? 0.55 : -0.55), cz = pz - 1.0 + Math.floor(i / 2) * 0.8;
      const h = 0.2 + ((i * 5 + (sx > 0 ? 3 : 0)) % 4) * 0.12;
      k.cyl(cx, 0.85, cz, 0.1, h, light, 6, moss);
    }
    // a fallen drum
    k.bar([px - 0.3, 0.95, pz + 0.7], [px + 0.2, 0.95, pz + 0.95], 0.09, light);
  }
  // the causeway, with stelae along it
  const cz0 = front + 0.35, cz1 = D / 2;
  k.box(0, 0, (cz0 + cz1) / 2, 1.6, 0.06, cz1 - cz0, light);
  for (const sx of [-0.86, 0.86]) k.box(sx, 0, (cz0 + cz1) / 2, 0.14, 0.14, cz1 - cz0, stone, moss);
  for (let i = 0; i < 6; i++) k.box(0, 0.06, cz0 + 0.3 + i * 0.6, 1.5, 0.006, 0.03, dark);
  for (const [sx, zz, tilt] of [[-1.25, cz0 + 0.8, 0], [1.25, cz0 + 0.8, 0], [-1.25, cz0 + 2.6, 0], [1.25, cz0 + 2.6, 1]]) {
    if (tilt) k.bar([sx, 0.08, zz], [sx + 0.55, 0.12, zz + 0.4], 0.08, stone);
    else {
      k.box(sx, 0, zz, 0.2, 0.62, 0.12, stone, moss);
      k.box(sx, 0.2, zz + 0.065, 0.14, 0.3, 0.01, dark);
    }
  }
  // trees rooted in the steps, vines down the faces
  for (let i = 0; i < 16; i++) {
    const tier = Math.floor(r() * (tiers - 1)), s = base - tier * inset * 2, side = Math.floor(r() * 4), u = (r() - 0.5) * (s - 0.6);
    const edge = s / 2 - inset / 2 - 0.02;
    const [x, z] = side === 0 ? [edge, u] : side === 1 ? [-edge, u] : side === 2 ? [u, -edge] : [u > 0 ? Math.max(u, 0.95) : Math.min(u, -0.95), edge];
    const y = (tier + 1) * th;
    if (i % 3 === 0) canopyTree(k, x, y, z0 + z, 0.7 + r() * 0.5, 0.35 + r() * 0.15, i);
    else k.dome(x, y, z0 + z, 0.14 + r() * 0.1, CANOPY[i % 3], 6, 2);
  }
  const vine = hex(0x3a6a2e);
  for (let i = 0; i < 22; i++) {
    const tier = 1 + Math.floor(r() * (tiers - 1)), s = base - tier * inset * 2, side = Math.floor(r() * 3), u = (r() - 0.5) * s * 0.9;
    const y1 = tier * th + th, len = th * (1 + Math.floor(r() * 3)), out = s / 2 + 0.03;
    const [x, z] = side === 0 ? [out, u] : side === 1 ? [-out, u] : [u, -out];
    const bx = side === 0 ? x + inset * (len / th - 1) : side === 1 ? x - inset * (len / th - 1) : x;
    const bz = side === 2 ? z - inset * (len / th - 1) : z;
    k.bar([x, y1, z0 + z], [bx, Math.max(0.05, y1 - len), z0 + bz], 0.018, vine);
  }
  // the forest crowding in behind and at the corners
  for (const [x, z, h] of [[-5, -5, 2.6], [4.8, -4.9, 3.0], [-5.3, -2.4, 2.2], [5.2, -2.2, 2.4], [-2.8, 5.2, 2.0], [3.0, 5.1, 2.3], [0.6, -5.5, 2.8]]) {
    canopyTree(k, x, 0, z, h, 0.75, Math.round(h * 10));
  }
  for (let i = 0; i < 14; i++) {
    const x = (r() - 0.5) * 11, z = -5.6 + r() * 1.2;
    if (Math.abs(x) < 3.6 && z > -5) continue;
    k.dome(x, 0, z, 0.2 + r() * 0.2, CANOPY[i % 3], 6, 2);
  }
  // fallen blocks at the foot
  for (let i = 0; i < 8; i++) {
    const x = (r() < 0.5 ? -1 : 1) * (1.2 + r() * 2.2), z = front + 0.2 + r() * 0.5;
    k.box(x, 0, z, 0.2 + r() * 0.15, 0.14, 0.2, i % 2 ? stone : light, moss);
  }
  void WHITE;
};

export const GREEN_DRAW: Partial<Record<RegionBuildingKind, Draw>> = {
  stiltHouse, canopyWalkway, ropeBridge, plantation, tradingPost, lostTemple,
};
