/**
 * What a vehicle is keen on (the cuts in game/cargoTypes.ts).
 *
 * A model's affinity for a kind of work is one number. It never decides what a vehicle *can* carry —
 * that is `canHaul` in game/cargo.ts, and nothing here overrules it — it decides what turns up and who
 * goes for it first:
 *
 *  - the player: their vehicle's keen work turns up sooner and its dull work later (CargoSystem.update),
 *    so a limousine's island fills with prom nights and weddings and a tipper's with gravel;
 *  - hired drivers and rival firms: it weighs the board they pick from (game/orders.ts, pickJobs), so a
 *    rival's limousine takes the wedding and its bus takes the school trip, off screen and unwatched;
 *  - the island's own traffic: it picks which model is sent out for a waiting load (game/traffic.ts).
 *
 * Work with a `veh` list is meant for those models: they are twice as keen on it, and everything else
 * is half-hearted about it (it can still be taken, and a load nobody ever takes would just rot).
 */
import type { CargoType } from './cargoTypes';
import { ALL_VEHICLES, type VehicleDef } from './vehicles';

/** The model this work was written for, and anyone else. */
const MEANT = 2.6, NOT_MEANT = 0.45;
/** A knack that suits the load (a full bus, a limousine's fares, a tipper's bulk, a siren on a clock). */
const KNACK = 1.5;
/** The most and least keen a vehicle can be, so nothing ever starves and nothing ever swamps the island. */
const LOW = 0.3, HIGH = 3;

/**
 * How keen this model is on this kind of work: 1 is even, above 1 is its own sort of job, below 1 is
 * somebody else's. Cheap enough to call per load, per frame.
 */
export function affinity(def: VehicleDef, t: CargoType): number {
  if (t.veh) return t.veh.includes(def.id) ? MEANT : NOT_MEANT;
  // a faction's vehicle is meant for its own faction's work (docs/factions.html)
  if (def.bonus?.ids.includes(t.id)) return MEANT;
  let a = 1;
  // the working vehicles' knacks (docs/rides.html): the job a knack pays for is the job it wants
  if (t.cls === 'people' && def.fareBox && t.units >= 3) a *= KNACK;
  if (t.cls === 'people' && def.vip) a *= KNACK;
  if (t.cls === 'bulk' && def.tipper) a *= KNACK;
  if (t.cls === 'parcel' && def.postal) a *= KNACK;
  if (def.siren && (t.cls === 'people' || t.cls === 'parcel') && (t.urgency ?? []).includes('urgent')) a *= KNACK;
  if (t.cls === 'people' && def.convertible) a *= 1.25;
  // a hold with one class in it is a specialist: the taxi and the coach want people, the tanker bulk
  if (def.holds.length === 1 && def.holds[0] === t.cls) a *= 1.2;
  // a big hold is wasted on a single fare, and a small one is never going to shift a container
  if (def.capacity >= 10 && t.units <= 1) a *= 0.7;
  return Math.max(LOW, Math.min(HIGH, a));
}

const BY_ID = new Map(ALL_VEHICLES.map((d) => [d.id, d]));

/**
 * How keen the keenest model out on the island is on this work, of the ones named in `models` (the
 * player's own included). What turns up leans on the whole fleet's shape, not only the car in the
 * player's hands: run buses and the island fills with school trips, whoever is at the wheel.
 */
export function keenestOf(models: Iterable<string>, t: CargoType): number {
  let best = 0;
  for (const id of models) {
    const d = BY_ID.get(id);
    if (d) best = Math.max(best, affinity(d, t));
  }
  return best || 1;
}
