import type { Building, World } from '../world/tiles';
import { SPORT_NAME, type Sport, type Team } from '../world/stadiums';
import {
  RESULT_LAG, fixtureKey, fixtures, history, ordinal, recordText, results, seasonAt, seasonLabel, seasonStart, table,
  type League, type Played,
} from './leagues';
import { hashString } from '../world/rng';
import { actJob } from './missions/actBoard';
import { stadiumKey, stadiumsNow, type Stadiums } from './stadiums';
import { clockOf, dayHour, tourRigOf, type Tour } from './tours';
import { esc } from './cargoHud';
import { speedText } from './units';
import type { Agent } from './traffic';

/**
 * The stadium's sections of the inspector card (docs/stadiums.html covers the stadiums themselves): three tabs under
 * the "Home of" row — the home club's season (record, place, the league table, results, next game), its
 * history (every finished season since the league was founded), and the act on tour here or nearest (its
 * tour so far and its career). And the card for one of a tour's convoy vehicles.
 */

type Tab = 'season' | 'history' | 'tour';
let tab: Tab = 'season';
let tabFor = '';

const SCORE_WORD: Record<Sport, string> = { soccer: 'Goals', football: 'Points', baseball: 'Runs' };
const hex = (c: number): string => `#${c.toString(16).padStart(6, '0')}`;
const swatch = (t: Team): string => `<i class="sp-sw" style="background:${hex(t.colour)};border-color:${hex(t.alt)}"></i>`;

/** An act's ride for the fleet beside its fixture or tour (missions/actTemplates.ts): on offer at its diamond, or under way. */
function jobLine(q: { tour?: number; fix?: number }): string {
  const j = actJob(q);
  if (!j) return '';
  const what = j.m.state === 'active' ? 'your fleet is taking them' : `work for your fleet ${j.form}`;
  return `<p class="sp-next sp-job">◆ ${what} · to ${esc(j.to)} by ${dayHour(j.by)}</p>`;
}

/** A pressed tab (main's inspector hands every press on the card's body here first): true when it was one. */
export function stadiumPress(target: HTMLElement): boolean {
  const b = target.closest('[data-stab]') as HTMLElement | null;
  if (!b) return false;
  tab = b.dataset.stab as Tab;
  return true;
}

/** Big numbers short: 1.2M, 48k. */
function short(n: number): string {
  if (n >= 1e6) return `${(n / 1e6).toFixed(n >= 1e7 ? 0 : 1)}M`;
  if (n >= 1e4) return `${Math.round(n / 1e3)}k`;
  return n.toLocaleString('en-US');
}
const tile = (k: string, v: string, sub: string, cls = '') => `<div class="tile ${cls}"><small>${k}</small><b>${v}</b><span>${sub}</span></div>`;
const dl = (rows: [string, string][]) => `<dl>${rows.map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`;

/** The stadium's tabs and the one open, as HTML for the card's body. */
export function stadiumSection(w: World, b: Building): string {
  const S = stadiumsNow();
  if (!S) return '';
  const key = stadiumKey(w, b);
  const { L, slot, team } = S.leagueOf(w, b);
  const tour = S.tours.at(key);
  if (tabFor !== key) { tabFor = key; tab = tour ? 'tour' : 'season'; }
  const tabs = (['season', 'history', 'tour'] as const).map((t) =>
    `<button type="button" data-stab="${t}" class="${t === tab ? 'on' : ''}">${t === 'season' ? 'Season' : t === 'history' ? 'History' : tour ? 'On tour ♪' : 'Tours'}</button>`).join('');
  const body = slot < 0 ? '<p class="note">This club plays in no league.</p>'
    : tab === 'season' ? seasonPane(S, L, slot, team) : tab === 'history' ? historyPane(S, L, slot) : tourPane(S, key, w, b);
  return `<div class="sp"><div class="sp-tabs" role="tablist">${tabs}</div>${body}</div>`;
}

// ---- the season ----------------------------------------------------------------------------------

function seasonPane(S: Stadiums, L: League, slot: number, team: Team): string {
  const now = S.hours(), sport = L.sport;
  const s = seasonAt(sport, now);
  const played = results(L, s.k, now, S.overrides, S.liveKeys);
  const rows = table(L, played, s.k);
  const pos = rows.findIndex((r) => r.club === slot);
  const me = rows[pos];
  // a club founded after the last season ended (out of season): nothing to show until its first
  if (!me) return `<p class="sp-sub"><b>${esc(L.name)}</b></p><p class="note">The ${esc(team.name)} are a brand new team: ${founded(L, slot)}. Their first season starts ${dayHour(seasonStart(sport, s.k + 1))}.</p>`;
  const all = fixtures(L, s.k);
  const rounds = all.length ? all[all.length - 1].round + 1 : 0;
  const done = new Set(played.map((p) => p.round));
  const over = !s.inSeason || (played.length >= all.length && all.length > 0);
  const live = all.find((f) => (f.home === slot || f.away === slot) && S.liveKeys.has(`${L.id}|${s.k}|${f.round}|${f.home}`));
  const nextStart = seasonStart(sport, s.k + 1);
  const status = !s.inSeason
    ? `final · next season starts ${dayHour(nextStart)}`
    : over ? 'final' : `round ${Math.min(rounds, done.size + 1)} of ${rounds}${live ? ' · <em class="sp-live">live now</em>' : ''}`;
  const head = `<p class="sp-sub"><b>${esc(L.name)}</b><br>Season ${seasonLabel(L, s.k)} · ${status}</p>`;

  const pct = (r: typeof me) => (r.p ? (r.pts / r.p).toFixed(3).replace(/^0/, '') : '.000');
  const tiles = `<div class="tiles">`
    + tile('Record', me.p ? recordText(sport, me) : '—', sport === 'soccer' ? 'won–drawn–lost' : 'won–lost', me.p ? '' : 'dim')
    + tile(over ? 'Finished' : 'Place', me.p ? ordinal(pos + 1) : '—', `of ${rows.length}${over && pos === 0 && me.p ? ' · champions' : ''}`, over && pos === 0 && me.p ? 'earn' : '')
    + tile(SCORE_WORD[sport], `${me.pf}–${me.pa}`, sport === 'soccer' ? `${me.pts} pts` : `${pct(me)} pct`)
    + `</div>`;

  // the table: the club highlighted, soccer's points, the others' winning percentage
  const tr = rows.map((r, i) => {
    const t = S.clubTeam(L, r.club);
    return `<tr class="${r.club === slot ? 'me' : ''}"><td>${i + 1}</td><td class="c">${swatch(t)}${esc(t.town)}</td><td>${r.p}</td><td>${recordText(sport, r)}</td><td>${sport === 'soccer' ? r.pts : pct(r)}</td></tr>`;
  }).join('');
  const tbl = `<table class="sp-table"><thead><tr><th></th><th class="c">Club</th><th>P</th><th>${sport === 'soccer' ? 'W–D–L' : 'W–L'}</th><th>${sport === 'soccer' ? 'Pts' : 'Pct'}</th></tr></thead><tbody>${tr}</tbody></table>`;

  // this club's games so far, the latest first, and the next
  const mine = played.filter((p) => p.home === slot || p.away === slot).sort((a, b) => b.at - a.at).slice(0, 5);
  const res = mine.length ? `<ul class="sp-res">${mine.map((g) => resultLine(S, L, slot, g)).join('')}</ul>` : '<p class="note">No games played yet this season.</p>';
  const next = all.find((f) => (f.home === slot || f.away === slot) && f.at + RESULT_LAG > now && !S.liveKeys.has(`${L.id}|${s.k}|${f.round}|${f.home}`));
  const nextLine = next
    ? `<p class="sp-next">Next: ${next.home === slot ? 'v' : 'at'} ${swatch(S.clubTeam(L, next.home === slot ? next.away : next.home))}${esc(S.clubTeam(L, next.home === slot ? next.away : next.home).name)} · ${next.at <= now ? 'kicking off' : dayHour(next.at)}${next.home === slot ? ' · here' : ''}</p>`
    : !s.inSeason || over ? `<p class="sp-next">${SPORT_NAME[sport]} is back ${dayHour(nextStart)}.</p>` : '';
  const job = next ? jobLine({ fix: hashString(fixtureKey(L, s.k, next)) }) : '';
  return head + tiles + tbl + `<p class="sp-h">${esc(team.nick)} results</p>` + res + nextLine + job;
}

function resultLine(S: Stadiums, L: League, slot: number, g: Played): string {
  const home = g.home === slot;
  const us = home ? g.hs : g.as, them = home ? g.as : g.hs;
  const opp = S.clubTeam(L, home ? g.away : g.home);
  const wl = us > them ? 'W' : us < them ? 'L' : 'D';
  return `<li><i class="r-${wl.toLowerCase()}">${wl}</i><b>${us}–${them}</b> ${home ? 'v' : 'at'} ${esc(opp.name)}${g.live ? ' <span class="sp-seen" title="You watched this one">👁</span>' : ''}</li>`;
}

/** "founded on day 12, when the stadium opened". */
function founded(L: League, slot: number): string {
  const s = L.clubs[slot]?.since;
  return s === undefined ? 'founded long ago' : `founded on day ${Math.floor(s / 24) + 1}, when the stadium opened`;
}

// ---- the history ---------------------------------------------------------------------------------

function historyPane(S: Stadiums, L: League, slot: number): string {
  const now = S.hours(), sport = L.sport;
  const s = seasonAt(sport, now);
  const over = !s.inSeason;
  const h = history(L, slot, over ? s.k + 1 : s.k, S.overrides);
  const isNew = L.clubs[slot]?.since !== undefined;
  if (!h.seasons) return isNew
    ? `<p class="note">A brand new team: ${founded(L, slot)}. Their history starts with their first full season.</p>`
    : '<p class="note">The league has not finished a season yet.</p>';
  const tiles = `<div class="tiles">`
    + tile('Seasons', `${h.seasons}`, isNew ? `since Season ${h.first} · founded day ${Math.floor(L.clubs[slot].since! / 24) + 1}` : `since Season ${h.first || 1}`)
    + tile('Titles', `${h.titles}`, h.won.length ? `last: Season ${h.won[0]}` : 'never won it', h.titles ? 'earn' : 'dim')
    + tile('Best', h.best ? ordinal(h.best.pos) : '—', h.best ? `Season ${h.best.label} · ${recordText(sport, h.best.row)}` : '')
    + `</div>`;
  const games = h.w + h.d + h.l;
  const rows: [string, string][] = [
    ['All-time', `${recordText(sport, h)} <small>${games ? `${Math.round(((h.w + h.d / 2) / games) * 100)}% won` : ''}</small>`],
    [SCORE_WORD[sport], `${h.pf.toLocaleString('en-US')} for · ${h.pa.toLocaleString('en-US')} against`],
  ];
  if (h.won.length) rows.push(['Champions', `${h.won.slice(0, 8).map((n) => `S${n}`).join(', ')}${h.won.length > 8 ? ` +${h.won.length - 8} more` : ''}`]);
  const recent = h.recent.map((r) => `<li><span>S${r.label}</span><b class="${r.pos === 1 ? 'gold' : ''}">${ordinal(r.pos)}</b><span>${recordText(sport, r.row)}</span><small>${r.pos === 1 ? 'champions' : `won by ${esc(S.clubTeam(L, r.champion).town)}`}</small></li>`).join('');
  return tiles + dl(rows) + `<p class="sp-h">Recent seasons</p><ul class="sp-hist">${recent}</ul>`;
}

// ---- the tour ------------------------------------------------------------------------------------

function tourPane(S: Stadiums, key: string, w: World, b: Building): string {
  const T = S.tours;
  const here = T.at(key);
  let out = '';
  const last = S.gigs.get(key);
  if (here) out += actBlock(S, here, key);
  else {
    const c = { x: w.ox + b.x + b.w / 2, z: w.oz + b.z + b.d / 2 };
    const near = T.nearest(c.x, c.z);
    out += '<p class="note">No tour is booked here yet: the next town over gets each one as it comes through.</p>';
    if (near) out += `<p class="sp-h">Nearest on tour · ${Math.round(near.tiles)} tiles off</p>` + actBlock(S, near.tour, key);
  }
  if (last) out += `<p class="sp-next">Last gig here: ${esc(T.act(last[0]).name)} · day ${last[1]}</p>`;
  return out;
}

function actBlock(S: Stadiums, t: Tour, key: string): string {
  const T = S.tours, act = T.act(t.act), life = T.lifetime(t.act);
  const now = S.hours();
  const toHere = t.next?.key === key || t.booked?.key === key, atHere = t.at.key === key;
  const status = t.phase === 'road'
    ? `On the road from ${esc(t.at.town)} to ${esc(t.next!.town)} · in ≈ ${Math.max(1, Math.round(T.eta(t)))} h · show ${dayHour(t.next!.show)}`
    : t.phase === 'setup' ? `${atHere ? 'Here' : `At ${esc(t.at.venue)}`} · setting up · show ${dayHour(t.at.show)}${t.at.show <= now ? ' (starting)' : ''}`
      : t.phase === 'show' ? `${atHere ? 'On stage here now' : `On stage at ${esc(t.at.venue)}`}`
        : t.phase === 'packing' ? `Packing up at ${esc(t.at.venue)} · the convoy pulls out at ${clockOf(t.until)}${t.booked ? ` for ${esc(t.booked.town)} · show ${dayHour(t.booked.show)}` : ''}`
          : 'The tour is over: the convoy is heading home';
  const tag = toHere ? '<span class="sp-tag">coming here next</span>' : atHere ? '<span class="sp-tag">here</span>' : '';
  const crowd = t.played.reduce((a, p) => a + p.crowd, 0), gross = t.played.reduce((a, p) => a + p.gross, 0);
  const towns = new Set(t.played.map((p) => p.town)).size;
  const head = `<div class="sp-act" style="--ac:${hex(act.colour)};--aa:${hex(act.alt)}"><b>${esc(act.name)}</b>${tag}<small>${esc(act.genre)} · from ${esc(act.from)}</small><small><em>${esc(t.name)}</em> · tour no. ${t.n}</small></div>`;
  const tiles = `<div class="tiles">`
    + tile('Shows', `${t.played.length}<small>/${t.length}</small>`, 'this tour')
    + tile('Crowds', short(crowd), `${towns} town${towns === 1 ? '' : 's'}`)
    + tile('Takings', `$${short(gross)}`, `tickets $${Math.round(35 + 60 * act.draw)}`, gross ? 'earn' : 'dim')
    + `</div>`;
  const stops = t.played.length
    ? `<ul class="sp-stops">${t.played.slice(-6).reverse().map((p) => `<li><span>day ${p.day}</span><b>${esc(p.town)}</b><small>${short(p.crowd)}${p.live ? ' · 👁' : ''}</small></li>`).join('')}</ul>`
    : '';
  const career: [string, string][] = [
    ['Career', `${life.shows.toLocaleString('en-US')} shows · ${life.tours} tours`],
    ['Tickets', `${short(life.crowd)} sold · $${short(life.gross)}`],
  ];
  if (life.towns) career.push(['Here', `${life.towns} town${life.towns === 1 ? '' : 's'} played in this world`]);
  return head + `<p class="sp-status">${status}</p>` + jobLine({ tour: t.id }) + tiles + stops + dl(career);
}

// ---- a convoy vehicle ------------------------------------------------------------------------------

/** The card for one of a tour's buses or trucks, or null when the vehicle is not one. */
export function tourAgentCard(a: Agent): [string, string] | null {
  const r = tourRigOf(a);
  if (!r) return null;
  const { act, tour, role } = r;
  const head = `<span class="ic">${role === 'Tour bus' ? '🚌' : '🚚'}</span><b>${esc(act.name)}</b><small>${esc(role)} · ${esc(tour.name)}</small>`;
  const rows: [string, string][] = [];
  rows.push(['Act', `${esc(act.name)} <small>${esc(act.genre)}</small>`]);
  rows.push(['Tour', `${esc(tour.name)} · show ${Math.min(tour.length, tour.played.length + (tour.phase === 'road' ? 1 : 0))} of ${tour.length}`]);
  if (tour.phase === 'road' && tour.next) {
    rows.push(['From', esc(tour.at.venue)]);
    rows.push(['To', `${esc(tour.next.venue)} <small>${esc(tour.next.town)}</small>`]);
    rows.push(['Next show', dayHour(tour.next.show)]);
  } else if (tour.phase === 'home') {
    rows.push(['From', esc(tour.at.venue)]);
    rows.push(['To', `home to ${esc(act.from)}`]);
  } else {
    rows.push(['At', `${esc(tour.at.venue)} <small>${esc(tour.at.town)}</small>`]);
    rows.push(['Show', dayHour(tour.at.show)]);
  }
  rows.push(['Doing', esc(r.doing)]);
  rows.push(['Speed', speedText(Math.abs(a.state.v) * 12)]);
  return [head, dl(rows)];
}
