import { N } from '../../world/tiles';
import { airportsOf } from '../../world/airportTowns';
import { cap, dl, esc, farNote, farText, plural, pretty, type TabCtx } from './common';

/**
 * Tab 5, Getting there (docs/townregister.html): how the town joins the rest of the world, and how far it is.
 * `tolls` is the number of the player's toll-bridge tiles in town (the card counts them from its shape).
 */
export function transportTab(c: TabCtx, tolls: number): string {
  const rows: [string, string][] = [];
  const d = c.digest;
  const mid = d ? { x: d.at[0] * N + d.at[2], z: d.at[1] * N + d.at[3] } : null;
  if (mid && c.player) rows.push(['From you', farText(Math.hypot(mid.x - c.player.x, mid.z - c.player.z))]);
  if (mid && c.hq) rows.push(['From your HQ', farText(Math.hypot(mid.x - c.hq.x, mid.z - c.hq.z))]);

  const { w, t } = c;
  if (w && t) {
    const roads = [...new Set(w.links.filter((l) => l.built && (l.from === t.name || l.to === t.name)).map((l) => (l.from === t.name ? l.to : l.from)))];
    const links = roads.map((n) => { const o = w.towns.find((q) => q.name === n); return o ? c.link(`${w.cx},${w.cz}#${o.id}`, o.name) : esc(n); });
    rows.push(['Roads to', links.length ? links.join(', ') : '<span class="none">no built road to another town</span>']);
    const ports = w.ports.filter((q) => q.town === t.id);
    if (ports.length) rows.push(['Harbours', grouped(ports.map((q) => `${esc(q.name)}${q.major ? ' <small>major</small>' : ''}`))]);
    const stations = w.stations.filter((st) => st.town === t.id);
    if (stations.length) {
      rows.push(['Stations', grouped(stations.map((st) => {
        const kind = cap(pretty(st.kind));
        // "Osprey Terminus" needs no "Terminus" after it
        return st.name.toLowerCase().endsWith(kind.toLowerCase()) ? esc(st.name) : `${esc(st.name)} <small>${esc(kind)}</small>`;
      }))]);
    }
    const airs = airportsOf(w, t);
    if (airs.length) rows.push(['Airports', airs.map((g) => `${esc(g.name)}${g.major ? ' <small>international</small>' : ''}`).join(', ')]);
    if (tolls) rows.push(['Tolls', `${plural(tolls, 'tile')} of your toll bridges in town`]);
    if (!ports.length && !stations.length && !airs.length) rows.push(['By sea, rail, air', '<span class="none">no harbour, station or airport: roads only</span>']);
    return dl(rows);
  }
  if (!d) return farNote();
  rows.push(['Roads to', d.roadsTo ? plural(d.roadsTo, 'town') : '<span class="none">none built</span>']);
  if (d.ports) rows.push(['Harbours', `${d.ports}${d.majorPort ? ' · one major' : ''}`]);
  if (d.stations) rows.push(['Stations', String(d.stations)]);
  if (d.airports) rows.push(['Airports', String(d.airports)]);
  return farNote() + dl(rows);
}

/** Names in a list, the same one twice said once with a count: "Port of Celestine ×2". */
function grouped(names: string[]): string {
  const n = new Map<string, number>();
  for (const s of names) n.set(s, (n.get(s) ?? 0) + 1);
  return [...n].map(([s, k]) => (k > 1 ? `${s} ×${k}` : s)).join(', ');
}
