/**
 * The ground under a towed load (docs/missions.html, Tows), read off one island: how much it drags
 * (a road least, sand and marsh most), how high it is, and what stops the load outright — a bridge deck,
 * water, a wall, the edge of the county. Shared by the tow in the game and `npm run tow`.
 */
import { STEP, Surface, RoadType, idx, inB, heightAt, waterDepth, type World } from '../../world/tiles';
import type { Ground } from './physics';

export function groundOf(world: () => World | null): Ground {
  const at = (x: number, z: number) => {
    const w = world();
    if (!w) return null;
    const lx = x - w.ox, lz = z - w.oz;
    const tx = Math.floor(lx), tz = Math.floor(lz);
    return inB(tx, tz) ? { w, i: idx(tx, tz), lx, lz } : null;
  };
  return {
    drag: (x, z) => {
      const q = at(x, z);
      if (!q) return Infinity;
      const road = q.w.road[q.i] as RoadType;
      if (road) return road === RoadType.Dirt || road === RoadType.Gravel ? 1.12 : road === RoadType.Cobble || road === RoadType.Brick ? 1.05 : 1;
      const s = q.w.surface[q.i] as Surface;
      return s === Surface.Sand ? 1.8 : s === Surface.Marsh ? 2 : s === Surface.Ice ? 0.8 : s === Surface.Rock || s === Surface.Basalt ? 1.45 : s === Surface.Salt ? 1 : 1.25;
    },
    height: (x, z) => {
      const q = at(x, z);
      return q ? heightAt(q.w, q.lx, q.lz) / STEP : 0;
    },
    wall: (x, z) => {
      const q = at(x, z);
      if (!q) return 'The edge of the county';
      if (q.w.deckAxis[q.i]) return 'Too heavy for the bridge';
      if (waterDepth(q.w, q.i) > 0) return 'It won’t float';
      if (q.w.blocked[q.i]) return 'Something’s in the way';
      return null;
    },
  };
}
