import * as THREE from 'three';

/**
 * `renderer.compileAsync`, safe against materials disposed while their programs build.
 *
 * three's own (r170) compiles, then polls `properties.get(material).currentProgram.isReady()` on a timer
 * until every program is done. A material disposed in between has its properties wiped, so the poll reads
 * `currentProgram` as undefined and throws from inside the timer, out of reach of any caller's try/catch:
 * "can't access property isReady, currentProgram is undefined". The game disposes warmed materials in that
 * window all the time: a chunk dropped while it compiled (stream.ts), an island the title reel let go, a
 * hero model the stage's cache evicted. Here a material whose program is gone is simply done.
 */
export function compileReady(renderer: THREE.WebGLRenderer, scene: THREE.Object3D, camera: THREE.Camera, target: THREE.Scene | null = null): Promise<THREE.Object3D> {
  const materials = renderer.compile(scene, camera, target);
  return new Promise((resolve) => {
    const check = (): void => {
      for (const m of materials) {
        // has() first: get() on a disposed material would quietly make it a fresh, empty entry
        const program = renderer.properties.has(m) ? (renderer.properties.get(m) as { currentProgram?: { isReady(): boolean } }).currentProgram : undefined;
        if (!program || program.isReady()) materials.delete(m);
      }
      if (materials.size === 0) { resolve(scene); return; }
      setTimeout(check, 10);
    };
    // with the extension the status can be asked without blocking; without it, give the driver a moment first
    if (renderer.extensions.get('KHR_parallel_shader_compile') !== null) check();
    else setTimeout(check, 10);
  });
}
