/**
 * Medal times for delivery missions (the user, 27 Oct 2026): a mission that is only deliveries (or a ride to
 * fetch, then deliveries) is timed from the moment its first load is aboard to its last drop. Beating the
 * bronze, silver or gold time pays on top of the mission's own rewards; finishing slower pays just what it
 * always did. The times are set at that first pickup, from the route and the top speed of what picked it up,
 * so every vehicle can medal and a quicker one makes gold easier.
 */
import { N, type World } from '../../world/tiles';
import type { VehicleDef } from '../vehicles';
import { roadRoute } from '../firstStart';
import type { Mission, Obj } from './model';

export type Medal = 0 | 1 | 2 | 3;
export const MEDAL_NAME = ['No medal', 'Bronze', 'Silver', 'Gold'] as const;
export const MEDAL_ICON = ['', '🥉', '🥈', '🥇'] as const;

/**
 * Each medal's time: the route at this share of the vehicle's top speed, plus a few seconds' grace. The
 * ambulance dash (0.55 + 6 s) is just made by the play bot's careful driving, so bronze is a steady drive,
 * silver a brisk one with no wrong turns, and gold flat out on the shortcuts with nitrous.
 */
export const MEDAL_PACE: Record<1 | 2 | 3, { share: number; grace: number }> = {
  1: { share: 0.45, grace: 10 },
  2: { share: 0.6, grace: 6 },
  3: { share: 0.75, grace: 4 },
};
/** What each medal adds to the mission's pay (its cash and its loads' value), and gold's diamond. */
export const MEDAL_PAY: Record<Medal, number> = { 0: 0, 1: 0.15, 2: 0.35, 3: 0.6 };
export const GOLD_GEMS = 1;
/** No medal time under this; each one at least this much over the one above it. */
export const MEDAL_MIN = 20, MEDAL_STEP = 5;
/** Seconds for each pickup and drop after the first pair: pulling in and loading. */
const STOP_SECS = 3;
/** Where no road route is known (across a border, at sea, in the air): the straight line, stretched this much. */
const WANDER = 1.3;

/**
 * Does this mission get medal times? Every step a delivery (no clock of its own, no convoy behind it), or a
 * ride to fetch before them; never the tutorial's or the getting-started track's.
 */
export function medalled(m: Pick<Mission, 'tpl' | 'objs'>): boolean {
  if (m.tpl.startsWith('first:') || m.tpl.startsWith('keys:')) return false;
  let deliveries = 0;
  for (const o of m.objs) {
    if (o.t === 'deliver') {
      if (o.clock || (o as { with?: number }).with) return false;
      deliveries++;
    } else if (o.t === 'reach') {
      if (!o.ride || o.with || o.hold || o.after !== undefined || o.dived || o.door) return false;
    } else return false;
  }
  return deliveries > 0;
}

type Spot = { x: number; z: number; cell: [number, number] };

/** Tiles from one place to another for this vehicle: the road route on one island for a road vehicle, else the line. */
function legTiles(def: VehicleDef, worlds: World[], a: Spot, b: Spot): number {
  const line = Math.hypot(b.x - a.x, b.z - a.z);
  if (def.kind === 'land' && a.cell[0] === b.cell[0] && a.cell[1] === b.cell[1]) {
    const w = worlds.find((q) => q.cx === a.cell[0] && q.cz === a.cell[1]);
    if (w) {
      const lx = (x: number) => Math.min(N - 1, Math.max(0, Math.floor(x)));
      const r = roadRoute(w, lx(a.x - w.ox), lx(a.z - w.oz), lx(b.x - w.ox), lx(b.z - w.oz));
      if (r && r.length > 1) return Math.max(line, r.length);
    }
  }
  return line * (def.kind === 'air' ? 1 : WANDER);
}

/** The run a mission's medals time: every load from its pickup to its drop, and the drives between, in tiles; and its stops. */
export function medalRun(m: Pick<Mission, 'objs'>, def: VehicleDef, worlds: World[]): { tiles: number; stops: number } {
  let tiles = 0, stops = 0;
  let end: Spot | null = null;
  for (const o of m.objs) {
    if (o.t !== 'deliver') continue;
    for (let k = 0; k < Math.max(1, o.n); k++) {
      if (end) tiles += legTiles(def, worlds, end, o.from);
      tiles += legTiles(def, worlds, o.from, o.to);
      end = o.to;
      stops += 2;
    }
  }
  return { tiles, stops: Math.max(0, stops - 2) };
}

/** The three times, seconds: bronze, silver, gold. */
export function medalTimes(tiles: number, stops: number, top: number): { b: number; s: number; g: number } {
  const at = (k: 1 | 2 | 3) => Math.round(tiles / (Math.max(0.2, top) * MEDAL_PACE[k].share) + MEDAL_PACE[k].grace + stops * STOP_SECS);
  const g = Math.max(MEDAL_MIN, at(3));
  const s = Math.max(g + MEDAL_STEP, at(2));
  const b = Math.max(s + MEDAL_STEP, at(1));
  return { b, s, g };
}

/** The medal a time earns against a mission's times (kept in its notes: mB, mS, mG). */
export function medalFor(secs: number, n: Record<string, number>): Medal {
  return secs <= n.mG ? 3 : secs <= n.mS ? 2 : secs <= n.mB ? 1 : 0;
}

/** The next time still to beat, or null once even bronze has gone. */
export function nextMedal(secs: number, n: Record<string, number>): { medal: 1 | 2 | 3; left: number } | null {
  for (const [medal, key] of [[3, 'mG'], [2, 'mS'], [1, 'mB']] as const) if (secs <= n[key]) return { medal, left: n[key] - secs };
  return null;
}

/** What a medal adds: cash on the mission's pay and its loads' value, and gold's diamond. */
export function medalBonus(m: Pick<Mission, 'reward' | 'objs'>, medal: Medal): { cash: number; gems: number } {
  let base = 0;
  for (const r of m.reward) if (r.r === 'cash') base += r.n;
  for (const o of m.objs as Obj[]) if (o.t === 'deliver') base += o.value * Math.max(1, o.n);
  return { cash: Math.round((base * MEDAL_PAY[medal]) / 5) * 5, gems: medal === 3 ? GOLD_GEMS : 0 };
}
