/** A cone of alternating panels in a frame, closed underneath: a carousel's roof. */
function stripedCone(k: Kit, f: Xf, R: number, h: number, seg: number, a: RGB, b: RGB, under: RGB): void {
  const apex = f([0, h, 0]), I = f([0, h * 0.3, 0]), c = f([0, 0, 0]), below = f([0, 0.05, 0]);
  for (let i = 0; i < seg; i++) {
    const a0 = (i / seg) * TAU, a1 = ((i + 1) / seg) * TAU;
    const p0 = f([Math.cos(a0) * R, 0, Math.sin(a0) * R]), p1 = f([Math.cos(a1) * R, 0, Math.sin(a1) * R]);
    k.tri(p0, p1, apex, i % 2 ? a : b, I);
    k.tri(p0, p1, c, under, below);
  }
}

