import type { CellDoc, ClientMsg, ServerMsg, Welcome } from '../../shared/protocol';
import type { OnlineExtra } from './online';
import { toppers } from '../game/toppers';

/**
 * The crowns' online side (docs/toppers.html phase 2, server/crowns.ts): asks which crowns this fleet holds when the
 * world is up, hears again whenever they change (the server sends them), and asks for every podium while the HQ
 * window's Toppers tab is open (`want`), at most every ASK_S seconds. What it hears goes to game/toppers.ts.
 */

const ASK_S = 15;

export interface CrownsNetHost { online(): boolean; post(m: ClientMsg): void }

export class CrownsNet implements OnlineExtra {
  private asked = -1e9;
  /** Data came in: the Rack redraws. */
  onData: () => void = () => {};

  constructor(private host: CrownsNetHost) {}

  welcome(_w: Welcome): void { toppers.resetCrowns(); this.asked = -1e9; }
  cell(_k: string, _doc: CellDoc): void { /* nothing per cell */ }
  got(m: ServerMsg): boolean {
    if (m.t !== 'crowns') return false;
    toppers.setCrowns(m.held, m.roll, m.rows, m.more ?? [], m.boards);
    this.onData();
    return true;
  }
  ready(): void { if (this.host.online()) this.host.post({ t: 'crowns' }); }
  /** Rush pennants, challenge flags and range trophies change hands with no save of ours: asked again every two minutes. */
  private again = 120;
  frame(dt: number): void {
    if (!this.host.online() || (this.again -= dt) > 0) return;
    this.again = 120;
    this.host.post({ t: 'crowns' });
  }
  forget(): void { /* nothing per cell */ }
  reset(): void { toppers.resetCrowns(); }

  /** The Toppers tab is open: every podium, now and then (or now, `force`). */
  want(force = false): void {
    if (!this.host.online()) return;
    const now = performance.now();
    if (!force && now - this.asked < ASK_S * 1000) return;
    this.asked = now;
    this.host.post({ t: 'crowns', all: true });
  }
}
