/** A harbour's site and the town it trades for. */
function harboursNear(c: MissionCtx, hi: number, major = false): Site[] {
  return c.sites(major ? ['majorPort'] : ['minorPort', 'majorPort']).filter((s) => !s.quay && near(c)(s) < hi).sort((a, b) => near(c)(a) - near(c)(b));
}

/**
 * The water a boat can reach from a harbour, by flood: every tile (of that harbour's county) at least `depth` steps
 * deep and joined to the pier's water, with how many tiles of water it is from there. A boat climbs a river a
 * step of water level at a time, never more (game/boat.ts), so the flood does too.
 */
function reachableWater(port: Site, depth: number, h: number): Map<number, number> {
  const w = port.w, p = w.ports.find((q) => q.id === port.port);
  const out = new Map<number, number>();
  if (!p) return out;
  const start = offshore(w, p.root, p.dir, h, 2, 8);
  if (!start) return out;
  const s0 = idx(Math.floor(start.lx), Math.floor(start.lz));
  const ok = (i: number) => w.water[i] >= 0 && waterDepth(w, i) >= depth;
  if (!ok(s0)) return out;
  out.set(s0, 0);
  const q = [s0];
  for (let k = 0; k < q.length && out.size < 12000; k++) {
    const i = q[k], x = i % N, z = (i - x) / N, d = out.get(i)!;
    for (const [dx, dz] of DIRS) {
      const nx = x + dx, nz = z + dz;
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if (out.has(j) || !ok(j) || Math.abs(w.water[j] - w.water[i]) > 1) continue;
      out.set(j, d + 1);
      q.push(j);
    }
  }
  return out;
}

/** `n` tiles of `pool` at least `apart` tiles from each other and from the start, picked by the hash; null if too few. */
function spread(w: World, pool: number[], n: number, apart: number, from: { x: number; z: number }, h: number): PlaceRef[] | null {
  const out: { x: number; z: number }[] = [];
  for (let k = 0; k < pool.length && out.length < n; k++) {
    const i = pool[(h + k * 7919) % pool.length];
    const x = w.ox + (i % N) + 0.5, z = w.oz + Math.floor(i / N) + 0.5;
    if (Math.hypot(x - from.x, z - from.z) < apart || out.some((p) => Math.hypot(p.x - x, p.z - z) < apart)) continue;
    out.push({ x, z });
  }
  return out.length < n ? null : out.map((p) => ({ x: p.x, z: p.z, cell: [w.cx, w.cz] as [number, number], name: 'the water' }));
}

/** Cash, and a step of standing with the town when there is one. */
const payAnd = (n: number, w: World, town: Town | null): Reward[] => [{ r: 'cash', n: r10(n) }, ...(town ? [{ r: 'standing', town: townRef(w, town), n: 1 } as Reward] : [])];

/** A harbour as a giver and a place to meet at. */
const dockOf = (s: Site): PlaceRef => { const p = s.w.ports.find((q) => q.id === s.port); return { x: s.x, z: s.z, cell: [s.w.cx, s.w.cz], name: p?.name ?? 'the harbour' }; };
const harbourTown = (s: Site): Town | null => { const p = s.w.ports.find((q) => q.id === s.port); return s.w.towns.find((t) => t.id === p?.town) ?? townAt(s); };

/** The Marshmallow's TV coverage: the blimp held over a stadium through a match, the cameras rolling. */
const coverage: Template = {
  id: 'work:coverage', thread: 'car', kind: 'job', cooldown: 6,
  gate: inA(RIDE_BLIMP),
  bind(c, h) {
    if (!RIDE_BLIMP.ids.includes(c.def.id)) return null;
    const venues = c.sites(['stadium', 'arena']).filter((s) => near(c)(s) < 220).sort((a, b) => near(c)(a) - near(c)(b));
    const v = venues[h % Math.min(3, venues.length)];
    if (!v) return null;
    const town = townAt(v);
    const name = shortSite(String(v.kind)).toLowerCase();
    return {
      title: pick(h >>> 3, ['Eye on the Game', 'Blimp Cam', 'Live Coverage']),
      why: `The sports channel wants the big match from the air. Hold the Marshmallow over the ${name} while the cameras roll.`,
      details: 'Forty seconds over the ground, low and steady, between noon and ten at night while the crowd is in.',
      giver: { who: 'tv', name: 'The sports channel', at: { x: v.x, z: v.z, cell: [v.w.cx, v.w.cz], name: `the ${name}` }, town: town ? townRef(v.w, town) : null },
      hero: { kind: 'vehicle', model: 'marshmallow' }, caption: 'The best seat in the house',
      objs: [{ t: 'reach', label: 'Cover the big match', icon: '🎥', at: { x: v.x, z: v.z, cell: [v.w.cx, v.w.cz], name: `the ${name}` }, r: 10, stop: true, hold: 40, after: 12, before: 22, ride: RIDE_BLIMP }],
      reward: payAnd(420 + near(c)(v) * 0.8, v.w, town),
    };
  },
};

/** The Gator's swamp tour: from a harbour out through marsh and mangrove water and back, for a boatful of sightseers. */
const SWAMP = new Set<number>([Biome.Marsh, Biome.Mangrove, Biome.Lagoon]);
const swampTour: Template = {
  id: 'work:swamp', thread: 'town', kind: 'job', cooldown: 4,
  gate: inA(RIDE_GATOR),
  bind(c, h) {
    if (!RIDE_GATOR.ids.includes(c.def.id)) return null;
    for (const port of harboursNear(c, 220).slice(0, 4)) {
      const water = reachableWater(port, 1, h);
      const swamp = [...water.keys()].filter((i) => SWAMP.has(port.w.biome[i]));
      const pts = spread(port.w, swamp, 2, 10, port, h);
      if (!pts) continue;
      const dock = dockOf(port), town = harbourTown(port);
      const objs: Obj[] = [
        { t: 'reach', label: 'Meet the tour party', icon: '📸', at: dock, r: 3, stop: true, ride: RIDE_GATOR },
        { t: 'reach', label: 'Spot the herons', icon: '🪶', at: { ...pts[0], name: 'the reed beds' }, r: 4, ride: RIDE_GATOR },
        { t: 'reach', label: 'Spot the gators', icon: '🐊', at: { ...pts[1], name: 'the mangroves' }, r: 4, ride: RIDE_GATOR },
        { t: 'reach', label: 'Bring them back', icon: '⚓', at: dock, r: 3, stop: true, ride: RIDE_GATOR },
      ];
      return {
        title: pick(h >>> 3, ['Swamp Tour', 'Into the Reeds', 'Gator Spotting']),
        why: 'A party of sightseers wants the swamp: out through the reeds and mangroves in the Gator, and back before dark.',
        details: 'The airboat skims where nothing else floats. Keep the fan down near the herons.',
        giver: { who: 'tours', name: 'The swamp tours hut', at: dock, town: town ? townRef(port.w, town) : null },
        hero: { kind: 'vehicle', model: 'airboat' }, caption: 'Into the swamp',
        objs, reward: payAnd(300, port.w, town),
      };
    }
    return null;
  },
};

/** The Serenade's charter: a wedding party from one harbour to another along the coast, in style. */
const charter: Template = {
  id: 'work:charter', thread: 'car', kind: 'job', cooldown: 6,
  gate: inA(RIDE_YACHT),
  bind(c, h) {
    if (!RIDE_YACHT.ids.includes(c.def.id)) return null;
    const type = cargoById('wedding');
    if (!type) return null;
    const ports = harboursNear(c, 300).filter((s) => s.major || !(c.def.kind === 'water' && c.def.halfLen > BIG_SHIP));
    for (const from of ports.slice(0, 3)) {
      const tos = ports.filter((s) => s !== from && Math.hypot(s.x - from.x, s.z - from.z) >= 60 && Math.hypot(s.x - from.x, s.z - from.z) <= 260);
      const to = tos[h % Math.max(1, tos.length)];
      if (!to) continue;
      const fit = offerable(c.def, c.at, from, to, type, true);
      if (!fit.ok && fit.why !== 'far') continue;
      const value = valueOf(type, fit.dist, 'timely', fit.seconds);
      const town = harbourTown(to);
      return {
        title: pick(h >>> 3, ['Wedding Cruise', 'Just Married', 'The Happy Couple']),
        why: `A wedding party wants to sail to ${dockOf(to).name} in style. Bring them aboard the Serenade and along the coast.`,
        details: 'Champagne on the foredeck, the band in the saloon. Keep it smooth: no cutting across the swell.',
        giver: { who: 'harbour', name: 'The wedding planner', at: dockOf(from), town: harbourTown(from) ? townRef(from.w, harbourTown(from)!) : null },
        hero: { kind: 'vehicle', model: 'yacht' }, caption: 'Just married',
        objs: [{ t: 'deliver', label: 'Bring the wedding party', icon: type.icon, cargo: type.id, from: siteRef(from), to: siteRef(to), n: 1, value, ride: RIDE_YACHT }],
        reward: payAnd(value * 0.8 + 250, to.w, town),
      };
    }
    return null;
  },
};

