/** The Defender's night patrol: the moorings, the breakwater and the outer buoys of a harbour checked after dark. */
const nightPatrol: Template = {
  id: 'work:patrol', thread: 'town', kind: 'job', cooldown: 6,
  gate: inA(RIDE_COAST),
  bind(c, h) {
    if (!RIDE_COAST.ids.includes(c.def.id)) return null;
    for (const port of harboursNear(c, 220).slice(0, 4)) {
      const p = port.w.ports.find((q) => q.id === port.port);
      if (!p) continue;
      const spots = [offshore(port.w, p.root, p.dir, h, 8, 18), offshore(port.w, p.root, p.dir, h + 5, 18, 32), offshore(port.w, p.root, p.dir, h + 11, 30, 50)];
      if (spots.some((s) => !s)) continue;
      const pts = spots.map((s) => placeOf(port.w, s!.lx, s!.lz, 'the water'));
      if (pts.some((a, i) => pts.some((b, j) => i < j && Math.hypot(a.x - b.x, a.z - b.z) < 7))) continue;
      const dock = dockOf(port), town = harbourTown(port);
      const names = ['the moorings', 'the breakwater', 'the outer buoys'];
      const labels = ['Search the moorings', 'Search the breakwater', 'Search the outer buoys'];
      const objs: Obj[] = pts.map((at, k): Obj => ({ t: 'reach', label: labels[k], icon: '🔦', at: { ...at, name: names[k] }, r: 5, stop: true, hold: 5, after: 21, before: 4, ride: RIDE_COAST }));
      objs.push({ t: 'reach', label: 'Bring the report in', icon: '📋', at: dock, r: 3, stop: true, ride: RIDE_COAST });
      return {
        title: pick(h >>> 3, ['Night Patrol', 'Coastguard Watch', 'Lights Out']),
        why: 'Night runners have been landing goods round the harbour. Search three spots after dark in the Defender, then report in.',
        details: 'Five seconds stopped at each, between nine at night and four in the morning, eyes on the water.',
        giver: { who: 'coastguard', name: 'The coastguard', at: dock, town: town ? townRef(port.w, town) : null },
        hero: { kind: 'vehicle', model: 'defender' }, caption: 'Eyes on the water',
        objs, reward: payAnd(380, port.w, town),
      };
    }
    return null;
  },
};

/** The Barnstormer's crop dusting: low over three farms' fields, then down at the airfield. */
const cropDust: Template = {
  id: 'work:dust', thread: 'car', kind: 'job', cooldown: 4,
  gate: inA(RIDE_BIPLANE),
  bind(c, h) {
    if (!RIDE_BIPLANE.ids.includes(c.def.id)) return null;
    const farms = c.sites(['farmhouse', 'barn', 'croft']).filter((s) => near(c)(s) < 170);
    const fields: Site[] = [];
    for (let k = 0; k < farms.length && fields.length < 3; k++) {
      const s = farms[(h + k * 7919) % farms.length];
      if (fields.every((q) => Math.hypot(q.x - s.x, q.z - s.z) >= 20)) fields.push(s);
    }
    if (fields.length < 3) return null;
    const strip = c.sites(['airport']).filter((s) => Math.hypot(s.x - fields[2].x, s.z - fields[2].z) < 260)
      .sort((a, b) => Math.hypot(a.x - fields[2].x, a.z - fields[2].z) - Math.hypot(b.x - fields[2].x, b.z - fields[2].z))[0];
    const words = ['first', 'second', 'third'];
    const objs: Obj[] = fields.map((s, k): Obj => ({ t: 'reach', label: `Dust the ${words[k]} field`, icon: '🌾', at: { x: s.x, z: s.z, cell: [s.w.cx, s.w.cz], name: `the ${words[k]} field` }, r: 7, ride: RIDE_BIPLANE }));
    if (strip) objs.push({ t: 'reach', label: 'Land at the airfield', icon: '🛬', at: { x: strip.x, z: strip.z, cell: [strip.w.cx, strip.w.cz], name: 'the airfield' }, r: 4, stop: true, ride: RIDE_BIPLANE });
    const town = townAt(fields[0]) ?? townAt(fields[1]);
    return {
      title: pick(h >>> 3, ['Crop Duster', 'Low and Slow', 'Spraying Season']),
      why: `Three farms need their fields sprayed before the rain. Fly low over each in the Barnstormer${strip ? ', then land at the airfield' : ''}.`,
      details: 'Fly over the middle of each farm low enough to see the furrows. The farmers will wave.',
      giver: { who: 'farm', name: 'The farmers’ co-op', at: { x: fields[0].x, z: fields[0].z, cell: [fields[0].w.cx, fields[0].w.cz], name: 'the first farm' }, town: town ? townRef(fields[0].w, town) : null },
      hero: { kind: 'vehicle', model: 'barnstormer' }, caption: 'Low over the fields',
      objs, reward: [{ r: 'cash', n: r10(320) }],
    };
  },
};

/** The Mountain Goat's excursion: walkers from the rack railway's valley stop up to the village on the mountain. */
const excursion: Template = {
  id: 'work:excursion', thread: 'town', kind: 'job', cooldown: 6,
  gate: inA(RIDE_GOAT),
  bind(c, h) {
    if (!RIDE_GOAT.ids.includes(c.def.id)) return null;
    for (const w of c.worlds) {
      const line = w.rails.find((r) => r.key.startsWith('rack:'));
      if (!line) continue;
      // the line's two ends (world/railPlan.ts planRack): the higher is the village's
      const n = line.xz.length / 2 - 1;
      const [lo, hi] = line.y[0] <= line.y[n] ? [0, n] : [n, 0];
      const bottom = placeOf(w, line.xz[lo * 2], line.xz[lo * 2 + 1], 'the valley stop');
      const top = placeOf(w, line.xz[hi * 2], line.xz[hi * 2 + 1], 'the top station');
      if (Math.hypot(bottom.x - c.at.x, bottom.z - c.at.z) > 260) continue;
      const up = w.towns.filter((t) => t.perch).sort((a, b) => Math.hypot(w.ox + a.x0 + a.size / 2 - top.x, w.oz + a.z0 + a.size / 2 - top.z) - Math.hypot(w.ox + b.x0 + b.size / 2 - top.x, w.oz + b.z0 + b.size / 2 - top.z))[0];
      return {
        title: pick(h >>> 3, ['Up the Mountain', 'The Rack Line', 'High Village']),
        why: `A party of walkers wants ${up ? up.name : 'the village on the mountain'}. Take them up the rack railway in the Mountain Goat.`,
        details: 'The cog line climbs where nothing else can. Stop at the valley end for them, then all the way up to the buffers at the top.',
        giver: { who: 'tours', name: 'The walking club', at: bottom, town: up ? townRef(w, up) : null },
        hero: { kind: 'vehicle', model: 'cog' }, caption: 'Up the rack line',
        objs: [
          { t: 'reach', label: 'Meet the walkers', icon: '🥾', at: bottom, r: 8, stop: true, ride: RIDE_GOAT },
          { t: 'reach', label: 'Take them up the mountain', icon: '⛰️', at: top, r: 8, stop: true, ride: RIDE_GOAT },
        ],
        reward: payAnd(360 + line.length * 1.5, w, up ?? null),
      };
    }
    return null;
  },
};

