/**
 * The night ops' missions (docs/nightops.html): helicopter work done with the searchlight, offered only
 * while the player flies a helicopter after dark. Each binds to real places — a hospital and a stretch of
 * open hillside, a harbour and the water off it, a police station and a road out of town, a news station
 * and a street, a cinema and a run through the town, a farm and the road past it — and hands them to the
 * op (nightops/ops.ts) as one objective.
 */
import { N, SEA, STEP, idx, inB, heightAt, type World, type Building, type Town } from '../../world/tiles';
import { isHelicopter, type LandDef } from '../vehicles';
import { isNight } from '../nightRules';
import { touchSpot } from '../air';
import { padOf } from '../../world/helipads';
import { reachAmong } from '../race/route';
import { personName } from '../mayor';
import { defOf } from '../fleet';
import type { MissionCtx } from './missions';
import type { Giver, OpKind, PlaceRef, Reward } from './model';
import { plainTown } from './text';
import { townRef, squareOf, roadNear, type Template, type Draft } from './templates';

/** The gate every night op shares. */
function nightGate(c: MissionCtx): string | null {
  if (!isHelicopter(c.def)) return 'helicopters only';
  return isNight(((c.hours % 24) + 24) % 24) ? null : 'after dark only';
}

const at = (w: World, lx: number, lz: number, name: string): PlaceRef => ({ x: w.ox + lx, z: w.oz + lz, cell: [w.cx, w.cz], name });
const roadPt = (w: World, lx: number, lz: number, name: string, r = 10): PlaceRef | null => {
  const i = roadNear(w, lx, lz, r);
  return i < 0 ? null : at(w, (i % N) + 0.5, Math.floor(i / N) + 0.5, name);
};
const mid = (b: Building) => ({ x: b.x + b.w / 2, z: b.z + b.d / 2 });
const townOf = (w: World, b: Building): Town | null => w.towns.find((t) => t.buildings.includes(b)) ?? null;
const worldAtOf = (c: MissionCtx) => (cx: number, cz: number) => c.worlds.find((w) => w.cx === cx && w.cz === cz) ?? null;

/** Buildings of these kinds in memory, nearest the player first, within `max` tiles. */
function buildingsNear(c: MissionCtx, kinds: string[], max = 220): { w: World; b: Building; d: number }[] {
  const out: { w: World; b: Building; d: number }[] = [];
  for (const w of c.worlds) {
    for (const b of w.allBuildings) {
      if (b.gone || b.derelict || !kinds.includes(b.kind)) continue;
      const m = mid(b);
      const d = Math.hypot(w.ox + m.x - c.at.x, w.oz + m.z - c.at.z);
      if (d <= max) out.push({ w, b, d });
    }
  }
  return out.sort((a, b) => a.d - b.d);
}

/** A little hash stream from a seed, for picking among candidates. */
export function picker(h: number): (n: number) => number {
  let s = h >>> 0 || 1;
  return (n: number) => { s = (Math.imul(s ^ (s >>> 15), 0x2c1b3c6d) + 0x9e3779b9) >>> 0; return n > 0 ? s % n : 0; };
}

/** Open, flat, dry ground a helicopter could land on, outside any town. */
function openLand(w: World, x: number, z: number): boolean {
  if (!inB(x, z) || x < 4 || z < 4 || x > N - 5 || z > N - 5) return false;
  const i = idx(x, z);
  if (w.townId[i] >= 0 || w.road[i] || w.rail[i]) return false;
  return !!touchSpot(w, x + 0.5, z + 0.5);
}

/** Tiles on a ring round (x, z) in one island, `lo`–`hi` out, that pass a test, in hash order. */
function ringTiles(w: World, x: number, z: number, lo: number, hi: number, test: (tx: number, tz: number) => boolean, pick: (n: number) => number, want = 1, step = 3): { x: number; z: number }[] {
  const all: { x: number; z: number }[] = [];
  for (let dz = -hi; dz <= hi; dz += step) {
    for (let dx = -hi; dx <= hi; dx += step) {
      const d = Math.hypot(dx, dz);
      if (d < lo || d > hi) continue;
      const tx = Math.floor(x + dx), tz = Math.floor(z + dz);
      if (test(tx, tz)) all.push({ x: tx, z: tz });
    }
  }
  const out: { x: number; z: number }[] = [];
  while (all.length && out.length < want) out.push(all.splice(pick(all.length), 1)[0]);
  return out;
}

/** A place some way off that a car can drive to from `from`: another town's square, or a road far out. */
function runTo(c: MissionCtx, from: PlaceRef, lo: number, hi: number, def: LandDef, pick: (n: number) => number): PlaceRef | null {
  const cands: PlaceRef[] = [];
  for (const w of c.worlds) {
    for (const t of w.towns) {
      const sq = squareOf(w, t, plainTown(t.name));
      const d = Math.hypot(sq.x - from.x, sq.z - from.z);
      if (d >= lo && d <= hi) cands.push(sq);
    }
    // road tiles well out, so a town on its own still has somewhere to run to
    for (let k = 0; k < 40; k++) {
      const i = pick(N * N);
      if (!w.road[i] || w.blocked[i] || w.deckAxis[i]) continue;
      const p = at(w, (i % N) + 0.5, Math.floor(i / N) + 0.5, 'the edge of town');
      const d = Math.hypot(p.x - from.x, p.z - from.z);
      if (d >= lo && d <= hi) cands.push(p);
    }
  }
  if (!cands.length) return null;
  const top = cands.slice(0, 16);
  const ok = reachAmong(worldAtOf(c), def, from.x, from.z, top);
  const good = top.filter((_, k) => ok[k]);
  return good.length ? good[pick(good.length)] : null;
}

const OP_HOURS = undefined;
const op = (o: OpKind, label: string, icon: string, p: { at: PlaceRef; r: number; to?: PlaceRef; spots?: PlaceRef[]; what?: string }) =>
  ({ t: 'op' as const, label, icon, op: o, ...p });
const standing = (w: World, t: Town | null, n = 1): Reward[] => (t ? [{ r: 'standing', town: townRef(w, t), n }] : []);

function nightTemplate(id: string, kind: OpKind, bind: (c: MissionCtx, pick: (n: number) => number) => Draft | null, cooldown = 36): Template {
  return {
    id, thread: 'town', kind: 'op', side: true, cooldown,
    gate: (c) => nightGate(c),
    bind: (c, h) => { const d = bind(c, picker(h)); if (d) d.hours = OP_HOURS; return d; },
  };
  void kind;
}

// ---- 1. search and rescue: someone lost in the hills --------------------------------------------

const lostHiker = nightTemplate('night:search', 'search', (c, pick) => {
  for (const { w, b } of buildingsNear(c, ['hospital'], 200).slice(0, 3)) {
    const pad = padOf(b);
    if (!pad) continue;
    const m = mid(b);
    const centre = ringTiles(w, m.x, m.z, 30, 80, (x, z) => openLand(w, x, z), pick, 1, 4)[0];
    if (!centre) continue;
    const spot = ringTiles(w, centre.x, centre.z, 3, 8, (x, z) => openLand(w, x, z), pick, 1, 1)[0];
    if (!spot) continue;
    const t = townOf(w, b);
    const roll = pick(8);
    const what = roll < 2 ? 'dog' : roll < 4 && w.fieldId[idx(spot.x, spot.z)] >= 0 ? 'child' : 'hiker';
    const hosp = at(w, pad.x, pad.z, 'the hospital pad');
    const area = at(w, centre.x + 0.5, centre.z + 0.5, 'the search area');
    const giver: Giver = what === 'dog'
      ? { who: 'owner', name: personName(`dog|${w.cx},${w.cz}|${spot.x},${spot.z}`), at: area, town: t ? townRef(w, t) : null }
      : { who: 'rescue', name: 'Mountain Rescue', at: hosp, town: t ? townRef(w, t) : null };
    const text = {
      hiker: { title: 'Lost on the Hill', why: 'A walker never came down off the hill. Find them with your searchlight, land beside them and fly them to the hospital.', label: 'Find the lost hiker' },
      child: { title: 'Missing Child', why: 'A child wandered into the fields at dusk. Sweep them with your searchlight, pick the child up and fly to the hospital.', label: 'Find the missing child' },
      dog: { title: 'Lost Dog', why: 'Their dog bolted at the fireworks and hasn’t come home. Sweep the fields with your searchlight until you find it.', label: 'Find the lost dog' },
    }[what]!;
    return {
      title: text.title, why: text.why, giver,
      hero: { kind: 'vehicle', model: 'dragonfly' }, caption: 'Searchlight work',
      objs: [op('search', text.label, what === 'dog' ? '🐕' : '🔦', { at: area, r: 12, to: hosp, spots: [at(w, spot.x + 0.5, spot.z + 0.5, 'the lost')], what })],
      reward: [{ r: 'cash', n: what === 'dog' ? 350 : 750 }, ...standing(w, t)],
    };
  }
  return null;
});

// ---- 2. man overboard -------------------------------------------------------------------------------

const manOverboard = nightTemplate('night:overboard', 'overboard', (c, pick) => {
  const ports = c.worlds.flatMap((w) => w.ports.map((p) => ({ w, p })))
    .map((q) => ({ ...q, d: Math.hypot(q.w.ox + (q.p.root % N) - c.at.x, q.w.oz + Math.floor(q.p.root / N) - c.at.z) }))
    .filter((q) => q.d < 240).sort((a, b) => a.d - b.d);
  for (const { w, p } of ports.slice(0, 4)) {
    const rx = p.root % N, rz = Math.floor(p.root / N);
    const deep = (x: number, z: number) => inB(x, z) && x > 3 && z > 3 && x < N - 4 && z < N - 4 && w.water[idx(x, z)] === SEA && heightAt(w, x + 0.5, z + 0.5) < SEA * STEP - 0.4;
    const off = [[1, 0], [0, 1], [-1, 0], [0, -1]][p.dir];
    let bx = rx, bz = rz;
    for (let k = 0; k < 14 && !deep(bx, bz); k++) { bx += off[0]; bz += off[1]; }
    if (!deep(bx, bz)) continue;
    const swim = ringTiles(w, bx, bz, 12, 26, deep, pick, 1, 2)[0];
    if (!swim) continue;
    const t = p.town >= 0 ? w.towns[p.town] ?? null : null;
    const cx = swim.x + (pick(9) - 4), cz = swim.z + (pick(9) - 4);
    return {
      title: 'Man Overboard', why: 'Someone went over the side off the harbour. Find the swimmer with your searchlight and light the lifeboat’s way to them.',
      giver: { who: 'coastguard', name: 'The coastguard', at: at(w, rx + 0.5, rz + 0.5, p.name), town: t ? townRef(w, t) : null },
      hero: { kind: 'vehicle', model: 'splash' }, caption: 'The lifeboat',
      objs: [op('overboard', 'Find the swimmer', '🛟', { at: at(w, cx + 0.5, cz + 0.5, 'the water'), r: 9, to: at(w, bx + 0.5, bz + 0.5, 'the lifeboat station'), spots: [at(w, swim.x + 0.5, swim.z + 0.5, 'the swimmer')] })],
      reward: [{ r: 'cash', n: 800 }, ...standing(w, t)],
    };
  }
  return null;
});

// ---- 3 & 4. pursuits ------------------------------------------------------------------------------

function policeGiver(w: World, b: Building, where: PlaceRef): Giver {
  const t = townOf(w, b);
  return { who: 'police', name: `Sergeant ${personName(`sgt|${w.cx},${w.cz}|${b.uid}`).split(' ')[1]}`, at: where, town: t ? townRef(w, t) : null };
}

const hotPursuit = nightTemplate('night:pursuit', 'pursuit', (c, pick) => {
  const def = defOf('pip') as LandDef;
  for (const { w, b } of buildingsNear(c, ['police'], 220).slice(0, 3)) {
    const m = mid(b);
    const start = roadPt(w, m.x, m.z, 'the police station');
    if (!start) continue;
    const to = runTo(c, start, 90, 220, def, pick);
    if (!to) continue;
    return {
      title: 'Hot Pursuit', why: 'A getaway driver is about to run. Keep his car in your searchlight while the patrol chases. Lose him in the dark and he’s gone.',
      giver: policeGiver(w, b, start),
      hero: { kind: 'vehicle', model: 'patrol' }, caption: 'Police air support',
      objs: [op('pursuit', 'Light the getaway car', '🚨', { at: start, r: 0, to })],
      reward: [{ r: 'cash', n: 900 }, ...standing(w, townOf(w, b))],
    };
  }
  return null;
}, 30);

const stolenCar = nightTemplate('night:sweep', 'sweep', (c, pick) => {
  const def = defOf('sunny') as LandDef;
  for (const { w, b } of buildingsNear(c, ['police'], 220).slice(0, 3)) {
    const t = townOf(w, b);
    if (!t || t.size < 14) continue;
    const sq = squareOf(w, t, 'the streets');
    const lx = sq.x - w.ox, lz = sq.z - w.oz;
    const r = Math.min(20, t.size / 2 + 3);
    const road = ringTiles(w, lx, lz, 5, r - 1, (x, z) => inB(x, z) && !!w.road[idx(x, z)] && !w.blocked[idx(x, z)] && !w.deckAxis[idx(x, z)], pick, 1, 1)[0];
    if (!road) continue;
    const car = at(w, road.x + 0.5, road.z + 0.5, 'the stolen car');
    const to = runTo(c, car, 90, 220, def, pick);
    if (!to) continue;
    return {
      title: 'Stolen Car', why: 'A stolen car is hiding in the streets with its lights off. Find it with your searchlight, then keep it lit when it runs.',
      giver: policeGiver(w, b, roadPt(w, mid(b).x, mid(b).z, 'the police station') ?? sq),
      hero: { kind: 'vehicle', model: 'sunny' }, caption: 'The stolen car',
      objs: [op('sweep', 'Find the stolen car', '🔦', { at: sq, r, to, spots: [car] })],
      reward: [{ r: 'cash', n: 1000 }, ...standing(w, t)],
    };
  }
  return null;
}, 30);

// ---- 5. live at eleven ------------------------------------------------------------------------------

const liveNews = nightTemplate('night:live', 'live', (c, pick) => {
  for (const { w, b } of buildingsNear(c, ['newsStation'], 240).slice(0, 2)) {
    const t = townOf(w, b);
    if (!t) continue;
    const m = mid(b);
    const road = ringTiles(w, m.x, m.z, 12, Math.max(16, t.size / 2), (x, z) => inB(x, z) && !!w.road[idx(x, z)] && !w.blocked[idx(x, z)] && !w.deckAxis[idx(x, z)], pick, 1, 1)[0];
    if (!road) continue;
    const scene = at(w, road.x + 0.5, road.z + 0.5, 'the story');
    return {
      title: 'Live at Eleven', why: 'A lorry has jack-knifed and the eleven o’clock news wants pictures. Hold the story in your beam for a minute on air.',
      giver: { who: 'news', name: 'Channel 6 News', at: roadPt(w, m.x, m.z, 'the news station') ?? scene, town: townRef(w, t) },
      hero: { kind: 'vehicle', model: 'dump' }, caption: 'Tonight’s story',
      objs: [op('live', 'Light the story on air', '📺', { at: scene, r: 0 })],
      reward: [{ r: 'cash', n: 700 }, ...standing(w, t)],
    };
  }
  return null;
});

// ---- 6. the night shoot -----------------------------------------------------------------------------

const nightShoot = nightTemplate('night:shoot', 'shoot', (c, pick) => {
  const def = defOf('wasabi') as LandDef;
  for (const { w, b } of buildingsNear(c, ['cinema', 'theatre', 'stadium', 'concertHall'], 240).slice(0, 3)) {
    const t = townOf(w, b);
    const m = mid(b);
    const start = roadPt(w, m.x, m.z, 'the set');
    if (!start) continue;
    const to = runTo(c, start, 45, 100, def, pick);
    if (!to) continue;
    return {
      title: 'The Night Shoot', why: 'A film crew needs a helicopter light for its big car stunt. Follow the car, hit the mark and nail the reveal.',
      giver: { who: 'studio', name: 'Starlight Pictures', at: start, town: t ? townRef(w, t) : null },
      hero: { kind: 'vehicle', model: 'wasabi' }, caption: 'The stunt car',
      objs: [op('shoot', 'Light the stunt for camera', '🎬', { at: start, r: 0, to })],
      reward: [{ r: 'cash', n: 1100 }, ...standing(w, t)],
    };
  }
  return null;
}, 48);

// ---- 7. blackout ------------------------------------------------------------------------------------

/** The blackout op's places and its card, for the night op and for Still Waters' Blackout in a helicopter (story/deep.ts). */
export const bindBlackout = (c: MissionCtx, pick: (n: number) => number): Draft | null => {
  const def = defOf('ambulance') as LandDef;
  for (const { w, b } of buildingsNear(c, ['hospital'], 220).slice(0, 3)) {
    const m = mid(b);
    const door = roadPt(w, m.x, m.z, 'the hospital');
    if (!door) continue;
    const t = townOf(w, b);
    const lx = door.x - w.ox, lz = door.z - w.oz;
    const cands = ringTiles(w, lx, lz, 25, 70, (x, z) => inB(x, z) && !!w.road[idx(x, z)] && !w.blocked[idx(x, z)] && !w.deckAxis[idx(x, z)] && w.townId[idx(x, z)] >= 0, pick, 6, 2)
      .map((q) => at(w, q.x + 0.5, q.z + 0.5, 'the accident'));
    if (!cands.length) continue;
    const ok = reachAmong(worldAtOf(c), def, door.x, door.z, cands);
    const crash = cands.find((_, k) => ok[k]);
    if (!crash) continue;
    return {
      title: 'Blackout', why: 'The power is out across town and an ambulance is crawling in the dark. Light the road ahead of it all the way to the hospital.',
      giver: { who: 'hospital', name: 'The hospital', at: door, town: t ? townRef(w, t) : null },
      hero: { kind: 'vehicle', model: 'ambulance' }, caption: 'The ambulance',
      objs: [op('blackout', 'Light the ambulance’s way', '🚑', { at: crash, r: 0, to: door })],
      reward: [{ r: 'cash', n: 800 }, ...standing(w, t)],
    };
  }
  return null;
};
const blackout = nightTemplate('night:blackout', 'blackout', bindBlackout);

// ---- 8. loose livestock -----------------------------------------------------------------------------

const looseStock = nightTemplate('night:livestock', 'livestock', (c, pick) => {
  for (const { w, b } of buildingsNear(c, ['barn', 'farmhouse'], 200).slice(0, 5)) {
    const m = mid(b);
    const farm = roadPt(w, m.x, m.z, 'the farm', 12);
    if (!farm) continue;
    const lx = farm.x - w.ox, lz = farm.z - w.oz;
    const road = (x: number, z: number) => inB(x, z) && !!w.road[idx(x, z)] && !w.blocked[idx(x, z)] && !w.deckAxis[idx(x, z)];
    const n = 4 + pick(2);
    const strays = ringTiles(w, lx, lz, 5, 18, road, pick, n, 2).map((q) => at(w, q.x + 0.5, q.z + 0.5, 'a stray'));
    if (strays.length < 4) continue;
    const t = townOf(w, b) ?? w.towns.slice().sort((a, q) => Math.hypot(a.x0 - m.x, a.z0 - m.z) - Math.hypot(q.x0 - m.x, q.z0 - m.z))[0] ?? null;
    const what = pick(3) === 0 ? 'sheep' : 'cow';
    return {
      title: 'Loose Stock', why: `The ${what === 'sheep' ? 'sheep are' : 'cows are'} through the fence and out on the road. Light each stray so the rancher can round it up before a car hits it.`,
      giver: { who: 'farmer', name: personName(`farm|${w.cx},${w.cz}|${b.uid}`), at: farm, town: t ? townRef(w, t) : null },
      hero: { kind: 'vehicle', model: 'mule' }, caption: 'The rancher’s pickup',
      objs: [op('livestock', 'Light each stray', what === 'sheep' ? '🐑' : '🐄', { at: strays[0], r: 0, to: farm, spots: strays, what })],
      reward: [{ r: 'cash', n: 600 }, ...standing(w, t)],
    };
  }
  return null;
});

// ---- 9. drop spotter --------------------------------------------------------------------------------

const dropSpotter = nightTemplate('night:drops', 'drops', (c, pick) => {
  for (const { w, b } of buildingsNear(c, ['police'], 220).slice(0, 3)) {
    const m = mid(b);
    const station = roadPt(w, m.x, m.z, 'the police station');
    if (!station) continue;
    const quiet = (x: number, z: number) => inB(x, z) && x > 3 && z > 3 && x < N - 4 && z < N - 4 && !w.blocked[idx(x, z)] && w.water[idx(x, z)] < 0 && heightAt(w, x + 0.5, z + 0.5) > SEA * STEP;
    const centre = ringTiles(w, m.x, m.z, 25, 60, (x, z) => quiet(x, z) && w.townId[idx(x, z)] < 0, pick, 1, 4)[0];
    if (!centre) continue;
    // three contacts spread about the area, a good way apart
    const spots: { x: number; z: number }[] = [];
    for (const q of ringTiles(w, centre.x, centre.z, 4, 22, quiet, pick, 40, 2)) {
      if (spots.every((s) => Math.hypot(s.x - q.x, s.z - q.z) >= 9)) spots.push(q);
      if (spots.length === 3) break;
    }
    if (spots.length < 3) continue;
    const t = townOf(w, b);
    return {
      title: 'Drop Spotter', why: 'Smugglers are meeting tonight. Sweep the area with your searchlight for their lanterns and tag each contact for the police.',
      giver: policeGiver(w, b, station),
      hero: { kind: 'vehicle', model: 'patrol' }, caption: 'Police air support',
      objs: [op('drops', 'Tag three contacts', '🟣', { at: at(w, centre.x + 0.5, centre.z + 0.5, 'the drop area'), r: 24, to: station, spots: spots.map((s) => at(w, s.x + 0.5, s.z + 0.5, 'a contact')) })],
      reward: [{ r: 'cash', n: 850 }, ...standing(w, t)],
    };
  }
  return null;
});

export const NIGHT_TEMPLATES: Template[] = [lostHiker, manOverboard, hotPursuit, stolenCar, liveNews, nightShoot, blackout, looseStock, dropSpotter];
