import { STEP, SEA, N, World, heightAt, tileAt, owner } from '../world/tiles';
import { padUnder, type Helipad } from '../world/helipads';
import { airfieldTile, fitsRunway, frameOf, jetRunways, onStrip, type Runway } from '../world/runways';
import { ARREST, CATAPULT, DECKS, deckFloor, deckLocal, deckUnder, deckWorld } from '../world/decks';
import { wheelsOf, type AirDef, type Controls, type JetStats, type VehicleState } from './vehicles';
import { heightText } from './units';
import { clamp } from '../util/math';

const wrap = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));

/** Ground, rooftop or sea surface, whichever is highest (a carrier's flight deck too). Reads whichever island is underneath. */
export function groundY(w: World, x: number, z: number): number {
  const at = tileAt(w, Math.floor(x), Math.floor(z));
  const g = Math.max(heightAt(w, x, z), SEA * STEP - 0.035, at.w.roof[at.i]);
  if (!DECKS.length) return g;
  const d = deckUnder(w.ox + x, w.oz + z);
  return d ? Math.max(g, d.y) : g;
}

/** Below this speed a helicopter over somewhere it can put down may descend all the way and touch down. */
const SETTLE_SPEED = 1.5;
/** How long Space must be held to lift a landed helicopter off: a shorter tap is the cargo key. */
const LIFT_OFF_HOLD = 0.25;

/**
 * Where a helicopter at (x, z) could put down: the painted pad it is over, at the pad's height (a pad
 * building's tiles record its tallest point, which stands above the paint), or flat open ground with
 * nothing built on it and no water. Null anywhere else, and there it keeps its usual clearance.
 */
export function touchSpot(w: World, x: number, z: number): { y: number; pad: Helipad | null } | null {
  // a carrier's flight deck, clear of its island, is as good as a pad
  if (DECKS.length) {
    const d = deckFloor(w.ox + x, w.oz + z);
    if (d) return { y: d.y, pad: null };
  }
  const o = owner(w, x, z);
  const pad = padUnder(o.w, o.x, o.z);
  if (pad) return { y: pad.y, pad };
  const i = Math.floor(o.z) * N + Math.floor(o.x);
  if (o.w.blocked[i] || o.w.roof[i] > 0 || o.w.water[i] >= 0) return null;
  const g = heightAt(w, x, z);
  if (g <= SEA * STEP) return null;
  let lo = g, hi = g;
  for (const [dx, dz] of [[0.35, 0], [-0.35, 0], [0, 0.35], [0, -0.35]]) {
    const h = heightAt(w, x + dx, z + dz);
    lo = Math.min(lo, h); hi = Math.max(hi, h);
  }
  return hi - lo < 0.15 ? { y: groundY(w, x, z), pad: null } : null;
}

/** How far out (tiles before the threshold) the landing aid offers itself, and how square the approach must be. */
export const APPROACH_RANGE = 40;
const APPROACH_ANGLE = 25 * Math.PI / 180;
/** The glide slope: world units of height per tile out from the threshold. */
export const GLIDE = 1 / 8;

/** A runway end a jet could land on: the threshold it touches down past, and which way it rolls. */
export interface Approach {
  r: Runway;
  /** 1 lands from A toward B, -1 from B toward A. */
  dir: 1 | -1;
  /** Tiles still to go to the threshold (positive before it), and how far off the centreline. */
  out: number; off: number;
}

/** The end of a runway `gx, gz` (world tiles) flying `heading` is lined up on, if any. */
export function approachFor(need: number, gx: number, gz: number, heading: number, range = APPROACH_RANGE): Approach | null {
  let best: Approach | null = null;
  for (const r of jetRunways()) {
    if (!fitsRunway(need, r)) continue;
    const f = frameOf(r, gx, gz);
    for (const dir of [1, -1] as const) {
      const out = dir === 1 ? -f.along : f.along - r.len;
      // a carrier's short deck gives the wheels longer to find it: the wires catch it all the same
      if (out < -r.len * (r.deck ? 0.6 : 0.35) || out > range) continue;
      if (Math.abs(f.across) > 3 + Math.max(0, out) * 0.3) continue;
      const rh = dir === 1 ? r.heading : wrap(r.heading + Math.PI);
      if (Math.abs(wrap(heading - rh)) > APPROACH_ANGLE) continue;
      if (!best || out < best.out) best = { r, dir, out, off: f.across * dir };
    }
  }
  return best;
}

/** How far out the approach guide shows itself, and how wide its funnel is either side of the centreline. */
export const GUIDE_RANGE = 70;
const GUIDE_SIDE = 10, GUIDE_FLARE = 0.35;

/**
 * The runway end whose extended centreline (either end's) the plane at (gx, gz) is anywhere near, in a
 * funnel that widens away from the threshold, whichever way it is heading: the guide shows it the line to
 * get onto. The nearest to the centreline wins.
 */
function nearApproach(need: number, gx: number, gz: number): Approach | null {
  let best: Approach | null = null, bestScore = Infinity;
  for (const r of jetRunways()) {
    if (!fitsRunway(need, r)) continue;
    const f = frameOf(r, gx, gz);
    for (const dir of [1, -1] as const) {
      const out = dir === 1 ? -f.along : f.along - r.len;
      if (out < 1 || out > GUIDE_RANGE) continue;
      if (Math.abs(f.across) > GUIDE_SIDE + out * GUIDE_FLARE) continue;
      const score = Math.abs(f.across) + out * 0.05;
      if (score < bestScore) { bestScore = score; best = { r, dir, out, off: f.across * dir }; }
    }
  }
  return best;
}

/** The heading that flies a plane at (gx, gz) onto this approach's centreline and down it, as the aid steers. */
export function interceptHeading(ap: Approach, gx: number, gz: number): number {
  const rh = ap.dir === 1 ? ap.r.heading : wrap(ap.r.heading + Math.PI);
  const off = (gx - ap.r.ax) * Math.cos(rh) - (gz - ap.r.az) * Math.sin(rh);
  return wrap(rh - clamp(off * 0.12, -0.9, 0.9));
}

const PAD_NAME: Record<Helipad['kind'], string> = {
  padHospital: 'hospital pad', padPolice: 'police pad', padTower: 'rooftop pad', padNews: 'news pad', padRadio: 'radio pad', padAirport: 'airport pad',
};
const padName = (p: Helipad) => PAD_NAME[p.kind];

export class AirState implements VehicleState {
  v: number;
  vy = 0;
  pitch = 0;
  roll = 0;
  bob = 0;
  lean = 0;
  wheelSpin = 0;
  steerVis = 0;
  power = 0;
  blocked = 0;
  trailerHeading = 0;
  sailAngle = 0;
  surfaceY = NaN;
  clear: number;
  /** A jet on its wheels: taxiing, rolling for take-off, or rolling out after landing. */
  grounded = false;
  /** A helicopter sitting on its skids, on a pad or open ground: Space or the throttle lifts it off. */
  landed = false;
  /** The pad a helicopter is over or sitting on (for the HUD), and whether it could put down right here. */
  pad: Helipad | null = null;
  canSettle = false;
  private liftHeld = 0;
  /** 1 with the undercarriage down, 0 up (drawn by the mesh). */
  gear = 1;
  /** The runway end the landing aid could take the jet to right now (for the HUD), and the one it is flying. */
  offer: Approach | null = null;
  landing: Approach | null = null;
  /** A runway's extended centreline the plane is near but not yet lined up on (for the approach guide). */
  near: Approach | null = null;
  /** Events for main.ts to read and clear: a take-off, and a touchdown with where on the runway it was. */
  tookOff = false;
  touchedDown: { along: number; len: number; runway: Runway; goArounds: number } | null = null;
  private goArounds = 0;
  private airT = 0;
  private yawRate = 0;
  private bank = 0;
  private t = 0;
  private agl = 0;
  /** After touchdown the brakes come on by themselves until it's down to taxi speed. */
  private autoBrake = false;
  /** Its wheels for a runway (a jet's, or the Barnstormer's gear); null for helicopters and blimps. */
  private readonly wheels: JetStats | null;
  /** The flight deck it is sitting on (world/decks.ts), and where that deck was last step, to move with it. */
  deck: string | null = null;
  private deckPose: { x: number; z: number; h: number; y: number } | null = null;

  constructor(public def: AirDef, public x: number, public z: number, public heading: number, public y: number, w?: World) {
    this.v = def.minSpeed;
    this.clear = def.cruiseClear;
    this.wheels = wheelsOf(def);
    // a jet put down on an airfield stands on its wheels; anywhere else it starts in the air
    if (this.wheels && w && this.onField(w) && y <= groundY(w, x, z) + 0.3) {
      this.grounded = true;
      this.v = 0;
      this.y = groundY(w, x, z);
    } else if (def.jet) this.gear = 0;
  }

  private onField(w: World, x = this.x, z = this.z): boolean {
    if (DECKS.length && deckFloor(w.ox + x, w.oz + z)) return true;
    const o = owner(w, x, z);
    return airfieldTile(o.w, o.x + (x - Math.floor(x)), o.z + (z - Math.floor(z)));
  }

  step(w: World, c: Controls, dt: number): void {
    this.t += dt;
    this.carry(w);
    if (this.grounded) this.stepGround(w, c, dt);
    else this.stepAir(w, c, dt);
    // the undercarriage: down on the ground and on approach, up once climbing clear
    const want = this.grounded || this.landing || (this.def.jet && this.agl < 3) ? 1 : this.def.jet ? 0 : 1;
    this.gear += clamp(want - this.gear, -dt, dt);
  }

  /**
   * Sitting on a carrier's flight deck (on the wheels, or a helicopter on its skids): move with the deck
   * from where it was last step to where it is now, so a carrier under way carries what is on it.
   */
  private carry(w: World): void {
    if (!DECKS.length || !(this.grounded || this.landed)) { this.deck = null; this.deckPose = null; return; }
    const gx = w.ox + this.x, gz = w.oz + this.z;
    const d = deckUnder(gx, gz);
    if (!d) { this.deck = null; this.deckPose = null; return; }
    const p = this.deckPose;
    if (this.deck === d.key && p && (p.x !== d.x || p.z !== d.z || p.h !== d.heading || p.y !== d.y)) {
      const f = deckLocal({ x: p.x, z: p.z, heading: p.h }, gx, gz);
      const n = deckWorld(d, f.along, f.across);
      this.x += n.x - gx;
      this.z += n.z - gz;
      this.heading += wrap(d.heading - p.h);
      this.y += d.y - p.y;
    }
    this.deck = d.key;
    this.deckPose = { x: d.x, z: d.z, h: d.heading, y: d.y };
  }

  /** On the wheels: taxi about the airfield, roll down a runway to rotate speed, lift off. */
  private stepGround(w: World, c: Controls, dt: number): void {
    const s = this.def, j0 = this.wheels!;
    const gx = w.ox + this.x, gz = w.oz + this.z;
    const strip = jetRunways().find((r) => onStrip(r, gx, gz)) ?? null;
    // on a carrier's deck the catapult throws it off and the wires stop it
    const j = strip?.deck ? { ...j0, groundAccel: Math.max(j0.groundAccel, CATAPULT), groundBrake: Math.max(j0.groundBrake, ARREST) } : j0;
    const cap = strip ? j.rotate + 0.6 : j.taxi;
    let a: number;
    if (this.autoBrake) {
      a = -j.groundBrake;
      if (this.v <= j.taxi) this.autoBrake = false;
    } else a = c.throttle > 0 ? j.groundAccel * (this.v < j.taxi ? 1.6 : 1) : c.throttle < 0 ? -j.groundBrake : -0.35;
    // off the strip it can't go faster than a taxi: the brakes come on
    if (this.v > cap) a = Math.min(a, -j.groundBrake);
    this.v = clamp(this.v + a * dt, 0, cap + 0.4);
    // nose-wheel steering: a slow pivot when crawling, a gentle correction on the roll
    const turn = this.v > j.taxi + 0.3 ? 0.18 : 0.45 + 0.4 * Math.min(1, this.v / Math.max(0.3, j.taxi));
    const want = c.steer * turn;
    this.yawRate += (want - this.yawRate) * Math.min(1, dt * 4);
    this.heading += this.yawRate * dt;
    this.steerVis = c.steer;
    this.bank *= Math.max(0, 1 - dt * 4);

    const fx = Math.sin(this.heading), fz = Math.cos(this.heading);
    const nx = this.x + fx * this.v * dt, nz = this.z + fz * this.v * dt;
    // the airfield's edge is a wall: a jet can't taxi onto a road
    const nose = (this.def.halfLen * 0.8) * (this.v >= 0 ? 1 : -1);
    if (!this.onField(w, nx + fx * nose, nz + fz * nose)) {
      this.v = 0;
      this.blocked = 0.4;
    } else { this.x = nx; this.z = nz; }
    this.blocked = Math.max(0, this.blocked - dt);
    this.y = groundY(w, this.x, this.z);
    this.vy = 0;
    this.agl = 0;
    this.wheelSpin += this.v * dt * 6;

    // rotate: on the strip, at speed, with the throttle held, the nose comes up and it flies
    const rot = strip ? clamp((this.v - j.rotate * 0.85) / (j.rotate * 0.15), 0, 1) : 0;
    this.pitch += (-0.09 * rot - this.pitch) * Math.min(1, dt * 4);
    this.roll = 0;
    this.bob = 0;
    if (strip && c.throttle > 0 && this.v >= j.rotate) {
      this.grounded = false;
      this.airT = 0;
      this.clear = Math.max(s.minClear, s.cruiseClear);
      this.vy = s.climbRate * 0.4;
      this.tookOff = true;
      this.goArounds = 0;
    }
    this.power = 0.35 + 0.65 * clamp(c.throttle, 0, 1);
  }

  private stepAir(w: World, c: Controls, dt: number): void {
    const s = this.def;
    this.airT += dt;
    // a helicopter on its skids stays put, rotors idling, until Space held (a tap loads cargo) or the
    // throttle lifts it off
    if (this.landed) {
      this.liftHeld = c.lift > 0 ? this.liftHeld + dt : 0;
      if (this.liftHeld > LIFT_OFF_HOLD || c.throttle !== 0) {
        this.landed = false;
        this.clear = Math.max(this.clear, s.minClear);
      } else {
        this.v = 0; this.vy = 0; this.yawRate = 0; this.agl = 0; this.steerVis = 0;
        this.bank *= Math.max(0, 1 - dt * 4);
        this.pitch *= Math.max(0, 1 - dt * 4);
        this.roll = 0; this.bob = 0;
        this.power += (0.3 - this.power) * Math.min(1, dt);
        return;
      }
    }
    const gx = w.ox + this.x, gz = w.oz + this.z;

    // the landing aid: offered while lined up with a runway that fits; flown while Shift is held
    const wh = this.wheels;
    if (wh) {
      this.offer = approachFor(wh.runway, gx, gz, this.heading);
      this.near = this.offer ? null : nearApproach(wh.runway, gx, gz);
      if (this.landing) {
        const keep = c.lift < 0 && c.throttle <= 0.5 ? approachFor(wh.runway, gx, gz, this.heading, APPROACH_RANGE + 10) : null;
        if (keep && keep.r === this.landing.r && keep.dir === this.landing.dir) this.landing = keep;
        else {
          // a go-around: climb back out to cruise
          this.landing = null;
          this.clear = s.cruiseClear;
          this.goArounds++;
        }
      } else if (this.offer && c.lift < 0 && c.throttle <= 0.5) this.landing = this.offer;
    }
    const ap = this.landing;

    // airspeed; a jet just off the ground is let climb out below its stall floor, and the aid slows it
    let a = c.throttle > 0 ? s.accel : c.throttle < 0 ? -s.brake : -Math.sign(this.v) * s.coast;
    if (c.throttle === 0 && Math.abs(this.v) < s.coast * dt) { a = 0; this.v = 0; }
    let lo = s.minSpeed > 0 ? s.minSpeed : -s.reverseCap;
    if (wh && this.airT < 4) lo = Math.min(lo, this.v);
    if (ap) {
      const target = wh!.approach;
      a = clamp((target - this.v) * 1.2, -s.brake, s.accel);
      lo = Math.min(lo, target);
    }
    this.v = clamp(this.v + a * dt, lo, s.topSpeed);
    const speedFrac = Math.abs(this.v) / s.topSpeed;

    // turning: planes bank to turn, rotorcraft and blimps yaw directly; the aid steers onto the centreline
    let steer = c.steer;
    if (ap) {
      // turning up the heading swings the nose toward (cos h, −sin h): steer against the offset that way
      const rh = ap.dir === 1 ? ap.r.heading : wrap(ap.r.heading + Math.PI);
      const off = (gx - ap.r.ax) * Math.cos(rh) - (gz - ap.r.az) * Math.sin(rh);
      const want = wrap(rh - clamp(off * 0.12, -0.45, 0.45));
      steer = clamp(wrap(want - this.heading) * 2.5, -1, 1);
    }
    let targetYaw: number;
    if (s.bankToTurn) {
      this.bank += (steer * s.bank - this.bank) * Math.min(1, dt * 2.5);
      targetYaw = s.steerRate * (this.bank / s.bank);
    } else {
      targetYaw = s.steerRate * steer;
      this.bank += (steer * s.bank * Math.min(1, speedFrac * 1.5) - this.bank) * Math.min(1, dt * 3);
    }
    this.yawRate += (targetYaw - this.yawRate) * Math.min(1, dt / s.yawLag);
    this.heading += this.yawRate * dt;
    this.steerVis = steer;

    // fly on: the world goes as far as anyone cares to
    const fx = Math.sin(this.heading), fz = Math.cos(this.heading);
    const px = this.x, pz = this.z;
    // coming down to touch down, a helicopter creeps
    if (s.rotor && this.clear < s.minClear) this.v = clamp(this.v, -SETTLE_SPEED, SETTLE_SPEED);
    this.x += fx * this.v * dt;
    this.z += fz * this.v * dt;
    this.blocked = Math.max(0, this.blocked - dt);
    // down on a pad below the building's top, or low over open ground beside a wall, it can't fly into
    // the building: it has to climb clear first
    if (s.rotor && this.canSettle && this.y < groundY(w, this.x, this.z) - 0.02) {
      const at = touchSpot(w, this.x, this.z);
      if (!at || at.y > this.y + 0.05) { this.x = px; this.z = pz; this.v = 0; this.blocked = 0.3; }
    }

    const gHere = groundY(w, this.x, this.z);
    // what the helicopter measures its height from: the pad or open ground it could put down on, when
    // slow enough to, and otherwise the highest thing under it
    let base = gHere;
    if (ap) {
      // down the glide slope to the threshold, then flare onto the strip
      const out = Math.max(0, ap.out);
      const target = ap.r.y + out * GLIDE;
      const vyWant = clamp((target - this.y) * 1.6, -s.climbRate * 1.2, s.climbRate);
      this.vy += (vyWant - this.vy) * Math.min(1, dt * 3);
      this.y += this.vy * dt;
      if (this.y < gHere) this.y = gHere;
      const gxNow = w.ox + this.x, gzNow = w.oz + this.z;
      if (this.y - gHere < (ap.r.deck ? 0.3 : 0.12) && onStrip(ap.r, gxNow, gzNow)) {
        // touchdown
        const f = frameOf(ap.r, gxNow, gzNow);
        const along = ap.dir === 1 ? f.along : ap.r.len - f.along;
        this.grounded = true;
        this.y = gHere;
        this.vy = 0;
        this.autoBrake = true;
        this.touchedDown = { along, len: ap.r.len, runway: ap.r, goArounds: this.goArounds };
        this.landing = null;
        this.offer = null;
        this.near = null;
      }
    } else {
      // altitude: hold a clearance over the highest ground just ahead; a slow helicopter over a pad or
      // open ground may let it right down to nothing, and there it touches down
      let minClear = s.minClear;
      this.pad = null;
      this.canSettle = false;
      if (s.rotor) {
        const at = touchSpot(w, this.x, this.z);
        this.pad = at?.pad ?? null;
        if (at && Math.abs(this.v) < SETTLE_SPEED) { base = at.y; minClear = 0; this.canSettle = true; }
      }
      this.clear = clamp(this.clear + c.lift * s.climbRate * dt, minClear, s.maxClear);
      let gMax = base;
      if (!this.canSettle) {
        const dir = this.v >= 0 ? 1 : -1;
        for (const d of [1, 2.5, 4.5, 7]) {
          const k = d * dir * Math.min(1, 0.3 + speedFrac);
          gMax = Math.max(gMax, groundY(w, this.x + fx * k, this.z + fz * k));
        }
      }
      const vyWant = clamp((gMax + this.clear - this.y) * 1.2, -s.climbRate, s.climbRate * 1.5);
      this.vy += (vyWant - this.vy) * Math.min(1, dt * 3);
      this.y += this.vy * dt;
      const floor = base + s.floor;
      if (this.y < floor) { this.y = floor; this.vy = Math.max(0, this.vy); }
      // touchdown: right down, and all but stopped
      if (this.canSettle && this.clear === 0 && this.y - base < 0.04 && Math.abs(this.v) < 0.6) {
        this.landed = true;
        this.y = base;
        this.v = 0;
        this.vy = 0;
      }
    }
    this.agl = this.y - base;

    // pose
    this.bob = Math.sin(this.t * s.bobFreq * 2) * s.bobAmp * Math.min(1, this.agl / 0.6);
    this.roll = -this.bank + Math.sin(this.t * 0.7) * s.bobAmp * 0.3;
    let targetPitch = -Math.atan2(this.vy, Math.max(1.5, Math.abs(this.v))) * (s.bankToTurn ? 0.9 : 0.25);
    // a jet holds its nose up on the approach, and flares just before the wheels touch
    if (ap) targetPitch = -0.05 - (this.agl < 1 ? 0.06 : 0);
    if (s.tilt > 0) targetPitch += s.tilt * (this.v / s.topSpeed) + c.throttle * s.tilt * 0.4;
    this.pitch += (targetPitch - this.pitch) * Math.min(1, dt * 3);

    this.power = s.bankToTurn ? 0.5 + 0.5 * speedFrac : s.tilt > 0 ? 1 : 0.25 + 0.75 * speedFrac;
  }

  status(): string {
    const j = this.wheels;
    if (this.grounded && j) {
      if (this.autoBrake) return `${this.deck ? '▼ caught the wire' : '▼ rolling out'} · ${this.v.toFixed(1)}`;
      if (this.v > j.taxi + 0.3) return `${this.deck ? '▶ catapult' : '▶ take-off roll'} · ${this.v.toFixed(1)} / ${j.rotate.toFixed(1)}`;
      if (this.deck) return this.v > 0.05 ? '▶ taxiing on the flight deck' : '■ on the flight deck';
      return this.v > 0.05 ? '▶ taxiing' : '■ on the apron';
    }
    if (this.landed) return this.pad ? `▣ on the ${padName(this.pad)} · hold Space to lift off` : '▣ landed · hold Space to lift off';
    if (this.canSettle && this.agl < 1.5) return this.pad ? `⇣ over the ${padName(this.pad)} · hold Shift to touch down` : '⇣ hold Shift to touch down';
    if (this.pad) return `⇣ over the ${padName(this.pad)} · slow down to land`;
    if (this.landing) return `▼ on approach · ${this.landing.r.name} · ${Math.max(0, Math.round(this.landing.out))} tiles`;
    if (this.offer) return `⇣ lined up · hold Shift to land · ${this.offer.r.name}`;
    if (this.near) return `⇢ ${this.near.r.name} runway · follow the lights to line up`;
    const m = heightText(this.agl * 3.3);
    if (this.vy > 0.6) return `▲ climbing · ${m}`;
    if (this.vy < -0.6) return `▼ descending · ${m}`;
    return `✈ ${m} up`;
  }
}
