import type { Fleet, Unit } from '../fleet';
import { runOf, type Agent, type Traffic } from '../traffic';
import { RUSH, fits, type RushKind } from './kinds';
import type { RushSite } from './sites';

/**
 * Your drivers in a rush (docs/rushes.html "On Work"): when the clock starts, the crewed vehicles on Work near A
 * whose hold takes the goods are taken off their work the way the formation takes a follower (the run let go at no
 * cost, `Unit.rushing` so the fleet gives them nothing else) and shuttle A ↔ B on their own, filling to the brim
 * at A and unloading at B like the player. What they deliver goes on the player's tally. At the bell, or when one
 * can't get on, it goes back to work as a follower set back to Work does.
 *
 * The vehicles following the player join too (the user, 2 Nov 2026: tailing the player round tight turns was too
 * clunky): for the run they leave the formation (game/formation.ts skips a unit `rushing`) and run the same A ↔ B
 * loop on their own, whatever the player does; at the bell they are still on Follow and fall in behind again.
 */

interface Hand {
  u: Unit;
  a: Agent;
  tr: Traffic;
  cap: number;
  aboard: number;
  to: 'a' | 'b';
  sent: boolean;
  /** It was following the player: at the bell it goes back to the formation, not to work. */
  follower: boolean;
  /** Seconds on this leg, and since it last made progress. */
  leg: number;
  still: number;
  lastD: number;
}

/** A leg this long, or this long without getting nearer, and the driver gives up and goes back to work. */
const LEG_MAX = 240, STILL_MAX = 25;

export class RushCrew {
  hands: Hand[] = [];
  /** Units delivered by the crew this run, and their names, for the result. */
  units = 0;

  constructor(private fleet: Fleet) {}

  /** The crewed vehicles on Work that would join this rush: in its county, near A, a hold that takes the goods, nothing aboard. */
  candidates(s: RushSite): Unit[] {
    return this.fleet.units.filter((u) => {
      const a = u.agent, tr = u.traffic;
      if (!u.driver || u.where !== 'working' || u.mode === 'follow' || u.rushing || !a || !tr || u.away) return false;
      if (u.cx !== s.cx || u.cz !== s.cz) return false;
      if (a.run?.aboard.length) return false;
      const w = tr.world;
      if (!w || Math.hypot(w.ox + a.state.x - s.a.x, w.oz + a.state.z - s.a.z) > RUSH.crewR) return false;
      return fits(s.kind, this.fleet.defFor(u));
    });
  }

  /** The vehicles following the player that would run the loop: out in A's county, near it, a hold that takes the goods. */
  followers(s: RushSite): Unit[] {
    return this.fleet.units.filter((u) => {
      const a = u.agent, tr = u.traffic;
      if (!u.driver || u.mode !== 'follow' || u.where !== 'working' || u.rushing || !a || !tr || u.away) return false;
      if (u.cx !== s.cx || u.cz !== s.cz) return false;
      const w = tr.world;
      if (!w || Math.hypot(w.ox + a.state.x - s.a.x, w.oz + a.state.z - s.a.z) > RUSH.crewR) return false;
      return fits(s.kind, this.fleet.defFor(u));
    });
  }

  /** The par weight of a vehicle's hold: its top speed against the family's par speed, so slow trucks count less. */
  static weight(k: RushKind, topSpeed: number): number {
    return Math.max(0.4, Math.min(1.5, topSpeed / RUSH.parSpeed[k.family]));
  }

  /** Take these units off Work (or out of the formation) for the rush. Returns the hold they bring, weighted for par. */
  take(s: RushSite, units: Unit[]): number {
    let hold = 0;
    for (const u of units) {
      const a = u.agent, tr = u.traffic;
      if (!a || !tr) continue;
      const def = this.fleet.defFor(u);
      const follower = u.mode === 'follow';
      // a follower's own run was put by when it fell in (formation.ts setMode): left as it is
      if (!follower && a.run) u.run = a.run.aboard.length ? runOf(a.run.aboard) : null;
      tr.stopForConvoy(a);
      a.escort = null;
      a.lead = null;
      u.rushing = true;
      this.hands.push({ u, a, tr, cap: def.capacity, aboard: 0, to: 'a', sent: false, follower, leg: 0, still: 0, lastD: Infinity });
      hold += def.capacity * RushCrew.weight(s.kind, def.topSpeed);
    }
    this.units = 0;
    this.fleet.onChange();
    return Math.round(hold);
  }

  /** Each frame of a run: drive each hand to its next end, fill or unload there. `drop` is told each delivery. */
  update(s: RushSite, dt: number, drop: (u: Unit, n: number) => void): void {
    const ring = RUSH.rings[s.kind.family];
    for (const h of [...this.hands]) {
      const { a, tr } = h;
      const w = tr.world;
      if (!w || h.u.agent !== a || !tr.agents.includes(a)) { this.let(h); continue; }
      const end = h.to === 'a' ? s.a : s.b;
      const tx = end.x - w.ox, tz = end.z - w.oz;
      if (!h.sent) {
        if (!tr.driveOwned(a, tx, tz)) { this.let(h); continue; }
        h.sent = true; h.leg = 0; h.still = 0; h.lastD = Infinity;
      }
      h.leg += dt;
      const d = Math.hypot(a.state.x - tx, a.state.z - tz);
      if (d < h.lastD - 0.5) { h.lastD = d; h.still = 0; } else h.still += dt;
      const there = d <= ring + 0.6 && (Math.abs(a.state.v) < 0.5 || a.phase === 'parked');
      if (there) {
        if (h.to === 'a') h.aboard = h.cap;
        else if (h.aboard) { this.units += h.aboard; drop(h.u, h.aboard); h.aboard = 0; }
        h.to = h.to === 'a' ? 'b' : 'a';
        h.sent = false;
        continue;
      }
      if (h.leg > LEG_MAX || h.still > STILL_MAX) this.let(h);
    }
  }

  /** Units aboard the crew now (lost at the bell). */
  aboard(): number { return this.hands.reduce((n, h) => n + h.aboard, 0); }

  /** The bell: everyone back to work. */
  release(): void {
    for (const h of [...this.hands]) this.let(h);
    this.fleet.onChange();
  }

  /** One hand back to work: what it had aboard before the rush is taken up again, else it asks for a load. */
  private let(h: Hand): void {
    this.hands = this.hands.filter((q) => q !== h);
    const u = h.u, a = u.agent;
    u.rushing = false;
    if (!a || !u.traffic) return;
    a.escort = null;
    a.lead = null;
    // a follower falls in behind the player again (formation.ts picks it up once it isn't `rushing`)
    if (h.follower) { u.traffic.stopForConvoy(a); return; }
    if (u.run) { u.traffic.resumeOwned(a, u.run); u.run = null; } else a.ask = 0.5;
  }
}
