import { N, RoadType, type Building, type World } from './tiles';

/**
 * A Las Vegas's Strip (world/towns.ts `vegas`): the interstate laid straight through the town. Everything bright in
 * a Las Vegas is on it: its casinos stand on lots fronting it (towns.ts STRIP_KINDS), and only a building that
 * fronts it wears the Strip's signs and lights (render/buildings/stripSigns.ts); the rest of the town is plain
 * stucco under the desert sun.
 */

/** Interstate tiles directly outside side d (0 +x, 1 +z, 2 -x, 3 -z) of a lot: how much of that side faces the Strip. */
export function stripContact(w: World, b: Pick<Building, 'x' | 'z' | 'w' | 'd'>, d: number): number {
  let n = 0;
  const on = (x: number, z: number) => x >= 0 && z >= 0 && x < N && z < N && w.road[z * N + x] === RoadType.Interstate;
  if (d === 0 || d === 2) {
    const col = d === 0 ? b.x + b.w : b.x - 1;
    for (let z = b.z; z < b.z + b.d; z++) if (on(col, z)) n++;
  } else {
    const row = d === 1 ? b.z + b.d : b.z - 1;
    for (let x = b.x; x < b.x + b.w; x++) if (on(x, row)) n++;
  }
  return n;
}

/** Does this building front the Strip: does any side of its lot open straight onto the interstate? */
export function frontsStrip(w: World, b: Pick<Building, 'x' | 'z' | 'w' | 'd'>): boolean {
  for (let d = 0; d < 4; d++) if (stripContact(w, b, d) > 0) return true;
  return false;
}
