  // the boom, a swept fin top and bottom, the tailplane with endplates, a dish aerial on the boom
  k.cyl(b, 0.075, 0.035, 0.82, 8, p, 0, 0.5, -0.72, 'z');
  k.box(b, 0.022, 0.28, 0.15, p, 0, 0.64, -1.1).rotation.x = -0.35;
  k.box(b, 0.022, 0.12, 0.1, p, 0, 0.42, -1.1).rotation.x = 0.3;
