  for (const sx of [-1, 1]) k.box(b, 0.015, 0.08, 0.07, WHITE, sx * 0.16, 0.5, -0.9);
  k.ball(b, 0.045, WHITE, 0, 0.57, -0.5, 1, 0.6, 1, 0);
  const tailRotor = k.group(b, -0.035, 0.68, -1.14);
  k.box(tailRotor, 0.01, 0.26, 0.03, DARK, 0, 0, 0);
  k.box(tailRotor, 0.01, 0.03, 0.26, DARK, 0, 0, 0);
  k.spin(tailRotor, 'x', 50);
  // the camera ball under the chin, its lens looking ahead
  k.box(b, 0.03, 0.06, 0.03, DARK, 0, 0.23, 0.3);
  k.ball(b, 0.068, k.mat(WHITE, 0.4, 0.2), 0, 0.15, 0.3);
  k.cyl(b, 0.032, 0.032, 0.03, 10, k.mat(0x1a2a4a, 0.1, 0.6), 0, 0.15, 0.37, 'z');
