import { STORY_MARKS } from './storyProps';
import * as THREE from 'three';
import { DIRS, type Building } from '../world/tiles';
import { hashString } from '../world/rng';
import { drawOf } from './townMesh';
import type { BoardSpot } from './buildings/neon';
import { BOARDS_OF, cinemaBoards } from './buildings/showbiz';
import { chicagoBoards } from './buildings/chicago';

/**
 * The letter boards on the marquees of the picture palaces and the playhouses (render/buildings/showbiz.ts,
 * chicago.ts): what is playing, in black capitals slid onto a lit cream board, the way a theatre's staff
 * change the letters every morning. The day's bill is picked from the game day and the building, so every
 * player sees the same one, and it changes once a day; each text is drawn once onto a small canvas and the
 * texture shared by every board showing it, freed when none does (game/screens.ts places the boards).
 */

/** Pictures: made up, every one. */
const FILMS = [
  'THE TIN CANARY', 'ROCKET GIRL', 'LAST BUS TO NOWHERE', 'MIDNIGHT TAXI', 'THE BIG HAUL', 'CARGO OF LOVE', 'SPEED TRAP',
  'ATTACK OF THE 50 FT FERRY', 'GHOST OF PIER 9', 'LOVE IN A LORRY', 'RETURN OF THE TOW TRUCK', 'THE ROUNDABOUT', 'TWO LANES WEST',
  'NITRO NIGHTS', 'THE LIGHTHOUSE KEEPER', 'DIAL M FOR MAYOR', 'THE GOLDEN DIAMOND', 'BRIDGE OVER THE CANAL', 'TOLL ROAD',
  'SMOKEY AND THE BLIMP', 'A FISTFUL OF FARES', 'THE COUNTY LINE', 'SUNSET BOULEVARD BYPASS', 'FLYING SAUCER SUMMER',
  'THE MAN FROM THE DEPOT', 'CROSSWINDS', 'GRAND PRIX OF THE HEART', 'THE NIGHT CONVOY', 'ISLAND OF LOST CARGO', 'WHEELS OF FIRE',
  'THE THIN MECHANIC', 'GONE WITH THE TIDE', 'DOUBLE PARKED', 'MONSTER FROM THE QUARRY', 'THE LONG HAUL HOME', 'HONK IF YOU LOVE ME',
  'ROBOT RODEO', 'THE SKYLARK AFFAIR', 'DRIVE-IN DRACULA', 'CASABLANCA EXPRESS', 'HIGH TIDE AT NOON', 'THE PINK GARAGE',
  'NORTH BY NORTH CARGO', 'BEACH PARTY A GO-GO', 'REVENGE OF THE ROAD CONE', 'THE MALTESE PARCEL', 'IT CAME FROM THE CANAL',
  'TOMATO CITY BLUES', 'ROAD TO RAINBOW BAY', 'THE CAPTAIN AND THE CRANE',
];
/** Shows: the playhouses' bills. */
export const SHOWS = [
  'HAULERS! THE MUSICAL', 'MADAME FERRY', 'A DOCK OF ONES OWN', 'THE PIRATES OF PORT LOW', 'NIGHTLY JAZZ REVUE', 'GUYS AND DOLLIES',
  'THE PHANTOM OF THE QUAY', 'SWAN LAKE ROAD', 'TWELFTH NIGHT SHIFT', 'THE NUTCRACKER SUITE', 'VAUDEVILLE TONIGHT', 'COMEDY HOUR',
  'MAGIC LANTERN SHOW', 'THE MERRY WIDOW', 'HAMLET ON WHEELS', 'BIG BAND BALL', 'TANGO TONIGHT', 'THE MIKADO', 'CABARET NIGHTS',
  'THE DANCING CRANES', 'OPERA GALA', 'A MIDSUMMER NIGHTS DRIVE', 'SINGING IN THE RAIN DELAY', 'THE BARBER OF SEVILLE', 'CAN-CAN CRAZY',
  'THE TOW TRUCK WALTZ', 'STARLIGHT EXPRESSWAY', 'BLUES BROTHERS BAND', 'MAGIC MARVO', 'THE GRAND OLD SHOW', 'BURLESQUE BONANZA',
  'CHORUS LINE-UP', 'TONIGHT ONLY: SINATRA SOUNDALIKE', 'ROMEO AND JULIET AT THE DEPOT', 'THE THREEPENNY RIDE',
];

/** One board's text and look, and where it stands. */
interface MarqueeBoard { spot: BoardSpot; text: string }

/** The boards on this building, with the day's bill on them; null if it has no marquee. */
export function marqueeBill(b: Building, cell: string, day: number): MarqueeBoard[] | null {
  const alongZ = b.facing % 2 === 1, W = alongZ ? b.w : b.d, D = alongZ ? b.d : b.w;
  let spots: BoardSpot[] | null = null, show = false;
  if (b.kind === 'cinema') {
    const f = BOARDS_OF.get(drawOf(b));
    spots = f ? f(W, D) : cinemaBoards(W, D);
  } else if (b.kind === 'theatre') {
    const f = BOARDS_OF.get(drawOf(b));
    spots = f ? f(W, D) : null;
    show = true;
  } else if (b.kind === 'chicagoTheatre') {
    spots = chicagoBoards(W, D);
    show = true;
  }
  if (!spots) return null;
  const pool = show ? SHOWS : FILMS;
  const h = hashString(`marquee|${cell}|${b.uid}|${day}`);
  const first = h % pool.length, second = (first + 1 + ((h >>> 8) % (pool.length - 1))) % pool.length;
  // a story's film (docs/storychains.html): once it has premiered, every picture house shows it on top
  const story = !show ? STORY_MARKS.titles[STORY_MARKS.titles.length - 1] : undefined;
  return spots.map((spot, i) => ({
    spot,
    // the front carries the main feature; the ends the second, and on a show night the time
    text: i === 0 ? story ?? pool[first] : show ? (i === 1 ? 'TONIGHT 8 PM' : 'MATINEE 2 PM') : (i === 1 ? (story ? pool[first] : pool[second]) : 'NOW SHOWING'),
  }));
}

/** Where a board's face stands in the island's frame: its middle and the way it faces. */
export function boardPlace(b: Building, s: BoardSpot): { x: number; z: number; yaw: number } {
  const yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]);
  const c = Math.cos(yaw), sn = Math.sin(yaw), ox = b.x + b.w / 2, oz = b.z + b.d / 2;
  const t = yaw + s.yaw, out = 0.004;
  return { x: ox + s.x * c + s.z * sn + Math.sin(t) * out, z: oz - s.x * sn + s.z * c + Math.cos(t) * out, yaw: t };
}

// ---- the textures ---------------------------------------------------------------------------------

interface Lettered { tex: THREE.CanvasTexture; mat: THREE.MeshBasicMaterial; refs: number }

/** Every board text drawn so far that some board still shows, by text and shape. */
export class MarqueeTextures {
  private cache = new Map<string, Lettered>();
  private night = -1;

  /** The material showing `text` on a board of this shape (w:h); take() it, and give() it back when done. */
  take(text: string, aspect: number): THREE.MeshBasicMaterial {
    const shape = aspect >= 7 ? 'long' : aspect >= 3.5 ? 'mid' : 'short';
    const key = `${shape}|${text}`;
    let e = this.cache.get(key);
    if (!e) {
      const tex = new THREE.CanvasTexture(letterBoard(text, shape));
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.anisotropy = 4;
      const mat = new THREE.MeshBasicMaterial({ map: tex, toneMapped: false, fog: false });
      mat.color.setScalar(this.night < 0 ? 1 : 0.82 + this.night * 0.18);
      mat.userData.marqueeKey = key;
      e = { tex, mat, refs: 0 };
      this.cache.set(key, e);
    }
    e.refs++;
    return e.mat;
  }

  give(mat: THREE.MeshBasicMaterial): void {
    const key = mat.userData.marqueeKey as string | undefined;
    const e = key ? this.cache.get(key) : undefined;
    if (!e || --e.refs > 0) return;
    e.tex.dispose();
    e.mat.dispose();
    this.cache.delete(key!);
  }

  /** How lit the boards look: a touch dim by day, full after dark (0..1). Cheap: a colour, no recompile. */
  light(night: number): void {
    const n = Math.round(night * 10) / 10;
    if (n === this.night) return;
    this.night = n;
    for (const e of this.cache.values()) e.mat.color.setScalar(0.82 + n * 0.18);
  }

  dispose(): void {
    for (const e of this.cache.values()) { e.tex.dispose(); e.mat.dispose(); }
    this.cache.clear();
  }
}

/** Board shapes and their canvases: a long thin front, a middling one, a short end. */
const SIZE: Record<string, [number, number]> = { long: [640, 64], mid: [384, 96], short: [192, 96] };

/** Black capitals on a lit cream board between two thin rails, a line or two, fitted to the width. */
function letterBoard(text: string, shape: string): HTMLCanvasElement {
  const [W, H] = SIZE[shape];
  const c = document.createElement('canvas');
  c.width = W; c.height = H;
  const g = c.getContext('2d')!;
  g.fillStyle = '#f6eed8';
  g.fillRect(0, 0, W, H);
  // the rails the letters hang on, and the faint gaps between letter tiles
  g.fillStyle = '#9a8a6a';
  const rail = Math.max(2, Math.round(H * 0.05));
  g.fillRect(0, 0, W, rail);
  g.fillRect(0, H - rail, W, rail);
  // one line on a long board; two on a short one when the words split
  const words = text.split(' ');
  let lines = [text];
  if (shape !== 'long' && words.length > 1) {
    let best = 1, diff = Infinity;
    for (let i = 1; i < words.length; i++) {
      const a = words.slice(0, i).join(' ').length, b = words.slice(i).join(' ').length;
      if (Math.abs(a - b) < diff) { diff = Math.abs(a - b); best = i; }
    }
    lines = [words.slice(0, best).join(' '), words.slice(best).join(' ')];
  }
  if (lines.length > 1) {
    g.fillRect(0, Math.round(H / 2 - rail / 2), W, rail);
  }
  const rowH = (H - rail * (lines.length + 1)) / lines.length;
  lines.forEach((line, i) => {
    let size = Math.floor(rowH * 0.86);
    g.font = `${size}px Impact, "Arial Narrow", "Arial Black", sans-serif`;
    const room = W * 0.94;
    const spaced = (s: string) => s.split('').join(String.fromCharCode(8202));
    let w = g.measureText(spaced(line)).width;
    if (w > room) { size = Math.max(8, Math.floor(size * room / w)); g.font = `${size}px Impact, "Arial Narrow", "Arial Black", sans-serif`; w = g.measureText(spaced(line)).width; }
    // red for a word that sells it, black for the rest
    g.fillStyle = /^(TONIGHT|MATINEE|NOW)/.test(line) ? '#b8262e' : '#1c1a18';
    g.textBaseline = 'middle';
    g.textAlign = 'center';
    g.fillText(spaced(line), W / 2, rail + rowH * (i + 0.5) + rail * i + size * 0.04);
  });
  return c;
}
