import * as THREE from 'three';
import type { VehicleDef } from '../game/vehicles';
import { JOBS } from '../game/factions/paintjobs';
import type { CarMesh } from './trainMeshes';
import type { EventParticles } from './eventParticles';
import { addWonderBall, sharedPiece, treatFx } from './wonderBall';
import { addTopper } from './toppers';

/** A topper's height against the Wonder Ball's radius: about two and a half times the ball and its mast, so it reads from the game's camera. */
const TOPPER_SIZE = 8;

/**
 * The Passport's treats on a vehicle's body (game/passportRewards.ts; set on the def by game/parts.ts applyParts):
 * `topper` the Wonder Ball (render/wonderBall.ts) or any other topper (render/toppers.ts, game/toppers.ts), `lantern` warm headlamps and a roof searchlight whose beam lights
 * the road ahead after dark, `gild` gold trim (1) or gold all over (2). Like the workshop's bolt-ons and the paintjobs
 * (render/boltOns.ts, render/paintjob.ts) nothing here knows a model: the built body is measured — the box each part
 * fills, how high it stands at a point, how low it hangs, where a rotor turns — and the treats are laid on that.
 * Runs before the parts are merged (render/vehicleMeshes.ts buildVehicleMesh), so the gold and the lamp housings
 * merge into the body; the ball turns and stays its own. A train's cars are built elsewhere (render/trainMeshes.ts),
 * so `dressTrainTreats` does the same for a train from its merged geometry.
 *
 * The materials are shared (gold) or, for the lamps that glow, one per vehicle as every model's own lamps are; none
 * is a new kind of shader, so a gilded fleet compiles nothing new.
 */

interface Part { mesh: THREE.Mesh; box: THREE.Box3 }

const CHROME = 0xd9dde2, HUB = 0xc9c9cd, DARK = 0x2a2a2e, GLASS = 0xa8d8f0;
/** The stock headlamp (render/vehicleMeshes.ts Kit.lamp, render/carMesh.ts). */
const LAMP = 0xfff2b0, LAMP_GLOW = 0xffe08a;
/** The lantern's: an amber lens, a warm orange glow. */
const LANTERN = 0xffb24a, LANTERN_GLOW = 0xff8a1c;

let gold: { trim: THREE.MeshStandardMaterial; body: THREE.MeshStandardMaterial; dark: THREE.MeshStandardMaterial } | null = null;
/**
 * The gold, shared by everything gilded. The scene has no reflections to show (render/boltOns.ts), so a fully metal
 * gold would be near black but for the sun's glint: these keep a share of their colour lit and a low roughness, so the
 * flat-shaded facets flash as the vehicle turns under the sun, which is the shimmer.
 */
export function goldMats(): NonNullable<typeof gold> {
  if (gold) return gold;
  const mk = (c: number, rough: number, metal: number): THREE.MeshStandardMaterial => {
    const m = new THREE.MeshStandardMaterial({ color: c, roughness: rough, metalness: metal, flatShading: true });
    m.userData.shared = true;
    return m;
  };
  gold = { trim: mk(0xffd248, 0.24, 0.42), body: mk(0xffd65a, 0.2, 0.38), dark: mk(DARK, 0.6, 0.1) };
  return gold;
}

/** Whether a definition wears any treat this file draws. */
export const hasTreats = (def: VehicleDef): boolean => !!(def.topper || def.lantern || def.gild);

/**
 * Dress a built body (`root` at the origin, unscaled) in its definition's treats. `moving` are the parts that move on
 * their own (the spinners: a rotor, a propeller), measured apart. Returns what must be kept out of the merge.
 */
export function dressTreats(root: THREE.Object3D, body: THREE.Group, def: VehicleDef, wheels: THREE.Object3D[], moving: THREE.Object3D[]): THREE.Object3D[] {
  if (!hasTreats(def) || def.kind === 'rail') return [];
  root.updateMatrixWorld(true);
  const inWheel = new Set<THREE.Object3D>();
  for (const w of wheels) w.traverse((o) => inWheel.add(o));
  const inMoving = new Set<THREE.Object3D>();
  for (const s of moving) s.traverse((o) => inMoving.add(o));
  const parts: Part[] = [];
  body.traverse((o) => {
    const m = o as THREE.Mesh;
    if (!m.isMesh || inWheel.has(m)) return;
    m.geometry.computeBoundingBox();
    parts.push({ mesh: m, box: m.geometry.boundingBox!.clone().applyMatrix4(m.matrixWorld) });
  });
  if (!parts.length) return [];
  const still = parts.filter((p) => !inMoving.has(p.mesh));
  const all = new THREE.Box3();
  for (const p of parts) all.union(p.box);
  const len = all.max.z - all.min.z, wid = all.max.x - all.min.x;
  const nose = all.max.z, tail = all.min.z, mid = (nose + tail) / 2;
  const size = Math.max(len, wid);
  const over = (b: THREE.Box3, x: number, z: number) => x >= b.min.x - 0.02 && x <= b.max.x + 0.02 && z >= b.min.z - 0.02 && z <= b.max.z + 0.02;
  /** The highest of the still parts over (x, z): what a thing stood there stands on. */
  const top = (x: number, z: number): number => {
    let y = -Infinity;
    for (const p of still) if (over(p.box, x, z)) y = Math.max(y, p.box.max.y);
    return y;
  };
  /** The lowest of the body under (x, z). */
  const bottom = (x: number, z: number): number => {
    let y = Infinity;
    for (const p of still) if (over(p.box, x, z)) y = Math.min(y, p.box.min.y);
    return Number.isFinite(y) ? y : all.min.y;
  };
  const keep: THREE.Object3D[] = [];

  // ---- the Wonder Ball: on the highest point near the middle, clear of any rotor ----
  if (def.topper) {
    const r = Math.max(0.04, Math.min(0.7, size * 0.06));
    // a rotor: a part turning about y, spread wider than half the body
    const rotors: { x: number; z: number; R: number }[] = [];
    const inRotor = new Set<THREE.Object3D>();
    for (const s of moving) {
      const b = new THREE.Box3().setFromObject(s);
      if (b.isEmpty()) continue;
      const span = Math.max(b.max.x - b.min.x, b.max.z - b.min.z);
      if (span > wid * 0.5 && b.max.y - b.min.y < span * 0.3) { rotors.push({ x: (b.min.x + b.max.x) / 2, z: (b.min.z + b.max.z) / 2, R: span / 2 }); s.traverse((o) => inRotor.add(o)); }
    }
    // anything else that turns in place (the Mixer's drum, a radar) is as good to stand on as the still parts: left
    // out, the Mixer's topper stood on the chassis inside its drum (the user, 6 Nov 2026)
    // and the top is the real surface, by rays dropped onto the triangles (three across, the middle hit, so an aerial
    // is not the roof), not a part's box: the drum's stripes swell its box, and the crown floated over it
    const standOn = parts.filter((p) => !inRotor.has(p.mesh)).map((p) => p.mesh);
    const ray = new THREE.Raycaster(), from = new THREE.Vector3(), down = new THREE.Vector3(0, -1, 0);
    const hit = (x: number, z: number): number => {
      ray.set(from.set(x, all.max.y + 1, z), down);
      const h = ray.intersectObjects(standOn, false)[0];
      return h ? h.point.y : NaN;
    };
    const top = (x: number, z: number): number => {
      // (a boat keeps the parts' boxes: rays into an open hull find its floor, under the gunwales)
      if (def.kind !== 'land') {
        let y = -Infinity;
        for (const p of parts) if (!inRotor.has(p.mesh) && over(p.box, x, z)) y = Math.max(y, p.box.max.y);
        return y;
      }
      const d = wid * 0.12;
      const ys = [hit(x - d, z), hit(x, z), hit(x + d, z)].filter(Number.isFinite).sort((a, b) => a - b);
      return ys.length === 3 ? ys[1] : ys.length ? ys[0] : -Infinity;
    };
    const clear = (z: number) => rotors.every((q) => Math.hypot(q.x, z - q.z) > q.R + r * 1.4);
    // nearest the middle first, so a level roof takes it at its middle
    const zs: number[] = [];
    const reach = rotors.length ? 0.5 : 0.22, n = rotors.length ? 24 : 12;
    for (let k = 0; k <= n; k++) zs.push(mid + (k / n - 0.5) * 2 * reach * len);
    zs.sort((a, b) => Math.abs(a - mid) - Math.abs(b - mid));
    let best: { z: number; y: number } | null = null;
    for (const z of zs) {
      if (!clear(z)) continue;
      const y = top(0, z);
      if (Number.isFinite(y) && (!best || y > best.y + 1e-3)) best = { z, y };
    }
    // a road vehicle's: the middle of the highest solid, level stretch along its top, a cab roof, a turret,
    // a drum, a canopy, so it stands centred on something real (the user, 6 Nov 2026: on the crane a cab, never the
    // boom; the bulldozer, the Puddle Duck and the tank off to one side). Solid is wide: rays a fifth of the width
    // either side of the middle land within a hair of the middle one, which a boom, a pole, an exhaust or a sign never do
    // (a boat keeps the highest point: an open hull's only level stretch is its floor)
    if (!rotors.length && def.kind === 'land') {
      const N = 48, d = wid * 0.2, tol = (all.max.y - all.min.y) * 0.05;
      const zAt = (k: number) => tail + len * (0.04 + (0.92 * k) / (N - 1));
      const level: number[] = [];
      for (let k = 0; k < N; k++) {
        const z = zAt(k), ys = [hit(-d, z), hit(0, z), hit(d, z)];
        level.push(ys.every(Number.isFinite) && Math.max(...ys) - Math.min(...ys) <= tol ? ys.sort((a, b) => a - b)[1] : NaN);
      }
      let run: { from: number; to: number; y: number } | null = null;
      for (let k = 0; k < N;) {
        if (!Number.isFinite(level[k])) { k++; continue; }
        let e = k, y = level[k];
        while (e + 1 < N && Number.isFinite(level[e + 1]) && Math.abs(level[e + 1] - level[k]) <= tol) { e++; y = Math.max(y, level[e]); }
        if (e - k >= 2 && (!run || y > run.y + tol || (Math.abs(y - run.y) <= tol && e - k > run.to - run.from))) run = { from: k, to: e, y };
        k = e + 1;
      }
      if (run) { const z = (zAt(run.from) + zAt(run.to)) / 2; best = { z, y: Math.max(run.y, top(0, z)) }; }
    }
    const ground = def.kind === 'air' ? null : root;
    // any other topper (render/toppers.ts) stands where the ball would, about as tall as the ball and its mast
    const ball = def.topper === 'wonder';
    const air = def.kind === 'air' ? airSpot(parts.map((p) => p.mesh), moving, all) : null;
    // an aircraft's stands a third of the craft's size (its length, span or height, the most) tall, so it reads from the game's camera (the user, 6 Nov 2026); the ball about 9.5 radii
    const tall = Math.max(size, all.max.y - all.min.y) / 3;
    if (air) keep.push(...(ball ? addWonderBall(body, 0, air.y, air.z, tall / 9.5, 1, null, 1) : addTopper(body, def.topper, 0, air.y, air.z, tall, 1)));
    else if (best) keep.push(...(ball ? addWonderBall(body, 0, best.y, best.z, r, 1, ground, Math.min(2.2, size * 1.3)) : addTopper(body, def.topper, 0, best.y, best.z, r * TOPPER_SIZE, 1, ground, Math.min(2.2, size * 1.3))));
    else {
      // every part of the top is under the rotor: hung under the nose instead
      const z = nose - len * 0.18;
      keep.push(...(ball ? addWonderBall(body, 0, bottom(0, z), z, r * 0.8, -1, ground, Math.min(2.2, size * 1.3)) : addTopper(body, def.topper, 0, bottom(0, z), z, r * TOPPER_SIZE * 0.8, -1)));
    }
  }

  // ---- the gold ----
  if (def.gild) {
    const g = goldMats();
    const job = def.job ? JOBS[def.job] : undefined;
    const looks = def.looks;
    const painted = new Set<number>([def.color]);
    if (looks && looks.paint >= 3) painted.add(looks.accent);
    if (job) { if (job.upper !== undefined) painted.add(job.upper); if (job.bonnet !== undefined) painted.add(job.bonnet); }
    const trim = new Set<number>([CHROME, HUB]);
    if (job?.pin !== undefined) trim.add(job.pin);
    const plain = (p: Part): THREE.MeshStandardMaterial | null => {
      const m = p.mesh.material as THREE.MeshStandardMaterial;
      return Array.isArray(p.mesh.material) || !m.isMeshStandardMaterial || m.transparent || m.map || m.emissive.getHex() !== 0 ? null : m;
    };
    // gold all over: and whatever colour covers most of it, where the model's own colour is only its trim (a Jumbo's
    // white fuselage, its colour a cheatline); glass, the dark parts and the trim aside
    if (def.gild === 2) {
      const area = new Map<number, number>();
      const sz = new THREE.Vector3();
      for (const p of parts) {
        const m = plain(p);
        if (!m) continue;
        const c = m.color.getHex(), l = m.color.getHSL({ h: 0, s: 0, l: 0 }).l;
        if (trim.has(c) || c === GLASS || l < 0.2) continue;
        p.box.getSize(sz);
        area.set(c, (area.get(c) ?? 0) + sz.x * sz.y + sz.y * sz.z + sz.x * sz.z);
      }
      let most = -1, best = 0;
      for (const [c, a] of area) if (a > best) { best = a; most = c; }
      if (most >= 0) painted.add(most);
    }
    const panels: Part[] = [];
    for (const p of parts) {
      const m = plain(p);
      if (!m) continue;
      const c = m.color.getHex();
      if (trim.has(c)) p.mesh.material = g.trim;
      else if (painted.has(c)) { panels.push(p); if (def.gild === 2) p.mesh.material = g.body; }
    }
    // the hubs, whatever colour the brakes made them
    for (const w of wheels) for (const c of w.children) if ((c as THREE.Mesh).isMesh) (c as THREE.Mesh).material = g.trim;
    // a gold line along both sides, unless the paintjob's own pinstripe has just been gilded
    if (def.gild === 1 && job?.pin === undefined && panels.length) {
      const pb = new THREE.Box3();
      for (const p of panels) pb.union(p.box);
      const y = pb.min.y + (pb.max.y - pb.min.y) * 0.56, h = Math.max(0.01, Math.min(0.02, size * 0.012));
      const side = (z: number): number => {
        let x = 0;
        for (const p of panels) if (y >= p.box.min.y - 0.01 && y <= p.box.max.y + 0.01 && z >= p.box.min.z - 0.01 && z <= p.box.max.z + 0.01) x = Math.max(x, p.box.max.x);
        return x;
      };
      const z0 = tail + len * 0.1, z1 = nose - len * 0.1, segs = 8;
      for (let k = 0; k < segs; k++) {
        const za = z0 + ((z1 - z0) * k) / segs, zb = z0 + ((z1 - z0) * (k + 1)) / segs, zc = (za + zb) / 2;
        const x = side(zc);
        if (x <= 0) continue;
        for (const sx of [-1, 1]) {
          const m = new THREE.Mesh(new THREE.BoxGeometry(0.006, h, zb - za + 0.002), g.trim);
          m.position.set(sx * (x + 0.004), y, zc);
          body.add(m);
        }
      }
    }
  }

  // ---- the lantern: amber headlamps, and a searchlight on the roof throwing its beam ahead ----
  if (def.lantern) {
    const lamp = lanternLamp();
    for (const p of parts) {
      const m = p.mesh.material as THREE.MeshStandardMaterial;
      if (!Array.isArray(p.mesh.material) && m.isMeshStandardMaterial && m.color.getHex() === LAMP && m.emissive.getHex() === LAMP_GLOW) p.mesh.material = lamp;
    }
    const u = Math.max(0.7, Math.min(9, size / 1.1));
    const air = def.kind === 'air';
    let lx: number, ly: number, lz: number, aim: THREE.Vector3, pool: boolean;
    if (air) {
      // under the nose, looking ahead and down
      lx = 0; lz = nose - len * 0.15; ly = bottom(0, lz) - 0.025 * u;
      aim = new THREE.Vector3(0, ly - 1.6 * u, lz + 1.8 * u);
      pool = false;
    } else {
      lx = def.kind === 'water' ? 0 : -wid * 0.22;
      lz = mid + len * (def.kind === 'water' ? 0.15 : 0.12);
      // on a roof, not up a mast: the highest part there that is a roof's width, not a pole or a sail
      let y = -Infinity;
      for (const p of still) if (over(p.box, lx, lz) && p.box.max.x - p.box.min.x > wid * 0.2 && p.box.max.z - p.box.min.z > len * 0.06) y = Math.max(y, p.box.max.y);
      if (!Number.isFinite(y)) y = top(lx, lz);
      if (!Number.isFinite(y)) y = all.max.y;
      ly = y + 0.03 * u;
      aim = new THREE.Vector3(lx * 0.4, 0.02, nose + len * (def.kind === 'water' ? 0.8 : 0.9) + 0.5 * u);
      pool = true;
    }
    const f = treatFx(), g = goldMats();
    // the lamp's housing, a drum along the car, and its lens
    const housing = new THREE.Mesh(new THREE.CylinderGeometry(0.032 * u, 0.032 * u, 0.06 * u, 12).rotateX(Math.PI / 2), g.dark);
    housing.position.set(lx, ly, lz);
    body.add(housing);
    const lens = new THREE.Mesh(new THREE.CylinderGeometry(0.026 * u, 0.026 * u, 0.008 * u, 12).rotateX(Math.PI / 2), lamp);
    lens.position.set(lx, ly, lz + 0.031 * u);
    body.add(lens);
    if (!air) {
      const post = new THREE.Mesh(new THREE.BoxGeometry(0.014 * u, 0.03 * u, 0.014 * u), g.dark);
      post.position.set(lx, ly - 0.025 * u, lz);
      body.add(post);
    }
    // the beam: a cone from the lens to the ground ahead, and its pool where it lands
    const from = new THREE.Vector3(lx, ly, lz + 0.035 * u);
    const d = aim.clone().sub(from), L = d.length(), spread = L * 0.17;
    const beam = sharedPiece(new THREE.Mesh(f.beam, f.beamMat));
    beam.position.copy(from);
    beam.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.normalize());
    beam.scale.set(spread, L, spread);
    beam.renderOrder = 5;
    body.add(beam);
    if (pool) {
      const spot = sharedPiece(new THREE.Mesh(f.pool, f.beamMat));
      spot.position.set(aim.x, 0.03, aim.z);
      spot.scale.set(spread * 1.3, 1, spread * 1.8);
      spot.renderOrder = 5;
      root.add(spot);
    }
  }
  return keep;
}

/** The lantern's lamp: one per vehicle, as every model's lamps are its own, so its glow at night is the vehicle's. */
function lanternLamp(vertexColors = false): THREE.MeshStandardMaterial {
  return new THREE.MeshStandardMaterial({ color: LANTERN, roughness: 0.4, metalness: 0, emissive: LANTERN_GLOW, emissiveIntensity: 0.85, flatShading: true, vertexColors });
}

// ---- trains ----

/**
 * Where a topper stands on an aircraft (the user, 6 Nov 2026: the trees on the planes and the blimp were
 * badly placed). Part boxes alone put it on whatever box reached highest near the middle: floating over a jet whose
 * fuselage tapers, up on a tail fin, under a helicopter's nose when its rotors covered the roof. Here the real surface is found by rays dropped straight down onto the body's triangles (all but the rotors), three
 * across the centreline (the middle of whatever they hit, so a beacon on the spine is not the top), and the topper
 * stands on it:
 * - a plane over its wing's middle (the highest wing: a biplane's top wing, a high wing's top, else the fuselage's
 *   spine over the wing root);
 * - a helicopter centred on top of its rotor's hub (the front rotor of two: the user, 6 Nov 2026);
 * - a saucer centred on top of its dome, and larger (the user, 6 Nov 2026);
 * - a blimp or a balloon at the top of its envelope, in the middle.
 * The caller sizes it: a third of the craft's size, so it reads from the game's camera. Null when no ray finds the body.
 */
function airSpot(meshes: THREE.Mesh[], moving: THREE.Object3D[], all: THREE.Box3): { y: number; z: number } | null {
  const len = all.max.z - all.min.z, wid = all.max.x - all.min.x, hgt = all.max.y - all.min.y;
  const mid = (all.max.z + all.min.z) / 2;
  // the rotors: parts turning about y, spread wider than half the body (as for the Wonder Ball above). Anything else
  // that turns (a saucer's hull, a propeller) is as good to stand on as the still parts.
  const rotors: { x: number; z: number; R: number; y: number }[] = [];
  const inRotor = new Set<THREE.Object3D>();
  for (const s of moving) {
    const b = new THREE.Box3().setFromObject(s);
    if (b.isEmpty()) continue;
    const span = Math.max(b.max.x - b.min.x, b.max.z - b.min.z);
    // (and with a hub at its middle: the saucer's turning ring of rim lights is no rotor)
    const own: THREE.Mesh[] = [];
    s.traverse((o) => { if ((o as THREE.Mesh).isMesh) own.push(o as THREE.Mesh); });
    const hubAt = new THREE.Raycaster(new THREE.Vector3((b.min.x + b.max.x) / 2, b.max.y + 1, (b.min.z + b.max.z) / 2), new THREE.Vector3(0, -1, 0));
    if (span > wid * 0.5 && b.max.y - b.min.y < span * 0.3 && hubAt.intersectObjects(own, false).length) {
      rotors.push({ x: (b.min.x + b.max.x) / 2, z: (b.min.z + b.max.z) / 2, R: span / 2, y: b.min.y });
      s.traverse((o) => inRotor.add(o));
    }
  }
  const rotorMeshes = meshes.filter((m) => inRotor.has(m));
  meshes = meshes.filter((m) => !inRotor.has(m));
  const ray = new THREE.Raycaster();
  const DOWN = new THREE.Vector3(0, -1, 0), UP = new THREE.Vector3(0, 1, 0), from = new THREE.Vector3();
  const cast = (x: number, z: number, dir: 1 | -1): number => {
    from.set(x, dir < 0 ? all.max.y + 1 : all.min.y - 1, z);
    ray.set(from, dir < 0 ? DOWN : UP);
    const h = ray.intersectObjects(meshes, false)[0];
    return h ? h.point.y : NaN;
  };
  const d = 0.03 * len;
  /** The top surface over (0, z): the middle of three rays across (or the lower of two, or the one). */
  const surface = (z: number): number => {
    const ys = [cast(-d, z, -1), cast(0, z, -1), cast(d, z, -1)].filter(Number.isFinite).sort((a, b) => a - b);
    return ys.length === 3 ? ys[1] : ys.length ? ys[0] : NaN;
  };

  if (rotors.length) {
    // a helicopter's stands on top of its rotor, centred on the hub (the front one of two);
    // it is the body's, so it stays put while the blades turn under it
    const q = rotors.reduce((p, o) => (o.z > p.z ? o : p));
    from.set(q.x, all.max.y + 1, q.z);
    ray.set(from, DOWN);
    const hub = ray.intersectObjects(rotorMeshes, false)[0];
    const y = hub ? hub.point.y : Math.max(...rotorMeshes.map((m) => new THREE.Box3().setFromObject(m).max.y));
    return { y, z: q.z };
  }
  // a saucer (as round as it is long and flat): on the top of its dome, at the middle
  if (Math.abs(len - wid) < len * 0.12 && hgt < len * 0.6) {
    const y = surface(mid);
    if (Number.isFinite(y)) return { y, z: mid };
  }
  // a plane's wing: a still part spanning most of the width and thin; the highest is the one on top
  let wing: THREE.Box3 | null = null;
  const b = new THREE.Box3();
  for (const m of meshes) {
    b.setFromObject(m);
    // (a blimp's tail fins are wide too, but at its end: a wing's middle is in the middle stretch of the body)
    if (b.max.x - b.min.x < wid * 0.6 || b.max.y - b.min.y > hgt * 0.3 || Math.abs((b.min.z + b.max.z) / 2 - mid) > len * 0.25) continue;
    if (!wing || b.max.y > wing.max.y) wing = b.clone();
  }
  const z = wing ? (wing.min.z + wing.max.z) / 2 : mid;
  const y = surface(z);
  if (!Number.isFinite(y)) return null;
  return { y, z };
}

/**
 * Where a topper stands on an engine: on its cab roof. The roof is found as the surface really is, by dropping
 * lines straight down onto the engine's triangles at points along its length (three across, the lowest kept, so a
 * horn, a whistle or a pantograph on the middle line is not the roof), and taken as flat stretches. A steam
 * engine's is the highest flat stretch at its back, and the topper stands in its middle; a diesel's or an
 * electric's is the highest one reaching the front half, and the topper stands at its front, a little in, just
 * behind the windscreen. (The engine's vertices alone, as it was, see a long roof only at its two ends: the
 * crowns stood on the noses of the Arrow and the Silver Comet and off the front of the steam cabs; the user,
 * 5 Nov 2026.) Null when no flat stretch is found.
 */
function roofSpot(meshes: THREE.Mesh[], L: number, halfW: number, steam: boolean): { y: number; z: number } | null {
  const N = 48, across = [-0.3, 0, 0.3].map((f) => f * halfW);
  const hit = across.map(() => new Array<number>(N).fill(-Infinity));
  const zAt = (k: number) => -L / 2 + ((k + 0.5) / N) * L;
  const a = new THREE.Vector3(), b = new THREE.Vector3(), c = new THREE.Vector3();
  for (const m of meshes) {
    m.updateMatrix();
    const pos = m.geometry.getAttribute('position'), index = m.geometry.getIndex();
    const tris = (index ? index.count : pos.count) / 3;
    const at = (i: number) => (index ? index.getX(i) : i);
    for (let t = 0; t < tris; t++) {
      a.fromBufferAttribute(pos, at(t * 3)).applyMatrix4(m.matrix);
      b.fromBufferAttribute(pos, at(t * 3 + 1)).applyMatrix4(m.matrix);
      c.fromBufferAttribute(pos, at(t * 3 + 2)).applyMatrix4(m.matrix);
      // the triangle seen from above: a wall (no area there) is no roof
      const d = (b.z - c.z) * (a.x - c.x) + (c.x - b.x) * (a.z - c.z);
      if (Math.abs(d) < 1e-9) continue;
      const k0 = Math.max(0, Math.ceil(((Math.min(a.z, b.z, c.z) + L / 2) / L) * N - 0.5));
      const k1 = Math.min(N - 1, Math.floor(((Math.max(a.z, b.z, c.z) + L / 2) / L) * N - 0.5));
      const x0 = Math.min(a.x, b.x, c.x), x1 = Math.max(a.x, b.x, c.x);
      for (let j = 0; j < across.length; j++) {
        const x = across[j];
        if (x < x0 || x > x1) continue;
        for (let k = k0; k <= k1; k++) {
          const z = zAt(k);
          const u = ((b.z - c.z) * (x - c.x) + (c.x - b.x) * (z - c.z)) / d;
          const v = ((c.z - a.z) * (x - c.x) + (a.x - c.x) * (z - c.z)) / d;
          if (u < -1e-6 || v < -1e-6 || u + v > 1 + 1e-6) continue;
          const y = u * a.y + v * b.y + (1 - u - v) * c.y;
          if (y > hit[j][k]) hit[j][k] = y;
        }
      }
    }
  }
  const roof = Array.from({ length: N }, (_, k) => Math.min(...hit.map((h) => h[k])));
  // flat stretches: runs of points within a hair of the run's first, two points long at least
  const tol = 0.02 * L;
  const runs: { from: number; to: number; y: number }[] = [];
  for (let k = 0; k < N;) {
    if (!Number.isFinite(roof[k])) { k++; continue; }
    let e = k, y = roof[k];
    while (e + 1 < N && Number.isFinite(roof[e + 1]) && Math.abs(roof[e + 1] - roof[k]) <= tol) { e++; y = Math.max(y, roof[e]); }
    if (e > k) runs.push({ from: k, to: e, y });
    k = e + 1;
  }
  // the cab end: a steam engine's back (−z), the front (+z) of anything else
  const fits = runs.filter((s) => (steam ? (s.from + s.to) / 2 < N * 0.6 : s.to >= N / 2));
  if (!fits.length) return null;
  const best = fits.reduce((p, s) => (s.y > p.y + 1e-3 || (Math.abs(s.y - p.y) <= 1e-3 && s.to - s.from > p.to - p.from) ? s : p));
  const len = (best.to - best.from + 1) * (L / N);
  const z = steam ? (zAt(best.from) + zAt(best.to)) / 2 : zAt(best.to) + L / N / 2 - Math.min(len / 2, 0.12 * L);
  return { y: best.y, z };
}

/**
 * A train's treats, from its cars as render/trainMeshes.ts built them (merged by finish, materials shared between
 * every car of an id): the gold on every car, the ball and the lantern on the engine's cab. The cars' materials are
 * swapped on these cars' own meshes, never on the shared ones.
 */
export function dressTrainTreats(cars: (CarMesh | null | undefined)[], def: VehicleDef): void {
  const live = cars.filter((c): c is CarMesh => !!c);
  // dressed before (a treat put on or taken off while it runs): back to the cars as built first
  for (const c of live) {
    for (const o of [...c.group.children]) if (o.userData.treat) c.group.remove(o);
    for (const o of c.group.children) if (o.userData.stockMat) { (o as THREE.Mesh).material = o.userData.stockMat; delete o.userData.stockMat; }
    const lit = stockLit.get(c);
    if (lit) { c.lit = lit; stockLit.delete(c); }
  }
  if (!hasTreats(def)) return;
  const g = goldMats();
  const swap = (m: THREE.Mesh, to: THREE.Material): void => { m.userData.stockMat ??= m.material; m.material = to; };
  const tag = <T extends THREE.Object3D>(o: T): T => { o.userData.treat = true; return o; };
  if (def.gild) {
    for (const c of live) {
      const wheels = new Set(c.wheels);
      for (const o of c.group.children) {
        const m = o as THREE.Mesh, mat = m.material as THREE.MeshStandardMaterial;
        if (!m.isMesh || !mat?.isMeshStandardMaterial || mat.emissive.getHex() !== 0) continue;
        // the finishes by their make (trainMeshes FINISH): paint 0.62/0.05, metal 0.38/0.3, gloss 0.12/0.25
        const metal = Math.abs(mat.roughness - 0.38) < 0.01 && Math.abs(mat.metalness - 0.3) < 0.01;
        const paint = (Math.abs(mat.roughness - 0.62) < 0.01 && Math.abs(mat.metalness - 0.05) < 0.01)
          || (Math.abs(mat.roughness - 0.12) < 0.01 && Math.abs(mat.metalness - 0.25) < 0.01);
        if (wheels.has(m) ? def.gild === 2 : metal) swap(m, g.trim);
        else if (paint && def.gild === 2) swap(m, g.body);
      }
    }
  }
  const eng = live[0];
  if (!eng || !(def.topper || def.lantern)) return;
  // the engine's height along its length, from its geometry: the cab is the highest stretch at its cab end
  const L = eng.length, bins = 24, high = new Array<number>(bins).fill(-Infinity);
  let maxX = 0;
  const v = new THREE.Vector3();
  const wheels = new Set(eng.wheels);
  const meshes = eng.group.children.filter((o): o is THREE.Mesh => (o as THREE.Mesh).isMesh && !wheels.has(o));
  const before = new Set(eng.group.children);
  for (const m of meshes) {
    const pos = m.geometry.getAttribute('position');
    for (let i = 0; i < pos.count; i++) maxX = Math.max(maxX, Math.abs(pos.getX(i)));
  }
  for (const m of meshes) {
    m.updateMatrix();
    const pos = m.geometry.getAttribute('position');
    for (let i = 0; i < pos.count; i++) {
      v.fromBufferAttribute(pos, i).applyMatrix4(m.matrix);
      if (Math.abs(v.x) > maxX * 0.5) continue;
      const k = Math.min(bins - 1, Math.max(0, Math.floor(((v.z + L / 2) / L) * bins)));
      high[k] = Math.max(high[k], v.y);
    }
  }
  const zOf = (k: number) => -L / 2 + ((k + 0.5) / bins) * L;
  // a steam engine's cab is at the back; a diesel's or an electric's at the front (+z)
  const steam = !!eng.smoke;
  const range = steam ? [0, Math.floor(bins * 0.45)] : [Math.ceil(bins * 0.62), bins];
  let cab = -1;
  for (let k = range[0]; k < range[1]; k++) if (Number.isFinite(high[k]) && (cab < 0 || high[k] > high[cab] + 1e-3)) cab = k;
  if (cab < 0) return;
  if (def.topper) {
    const r = Math.max(0.05, Math.min(0.14, L * 0.04));
    const spot = roofSpot(meshes, L, maxX, steam) ?? { y: high[cab], z: zOf(cab) };
    if (def.topper === 'wonder') addWonderBall(eng.group, 0, spot.y, spot.z, r, 1, eng.group, L * 0.6, 0.03);
    else addTopper(eng.group, def.topper, 0, spot.y, spot.z, r * TOPPER_SIZE, 1, eng.group, L * 0.6);
  }
  if (def.lantern) {
    const lamp = lanternLamp(true);
    for (const m of meshes) {
      const mat = m.material as THREE.MeshStandardMaterial;
      if (mat?.isMeshStandardMaterial && mat.emissive.getHex() === LAMP_GLOW) swap(m, lamp);
    }
    // its glow follows the night like the train's own lamps (game/trains.ts pose)
    stockLit.set(eng, eng.lit);
    eng.lit = [...eng.lit, lamp];
    let front = bins - 1;
    while (front > 0 && !Number.isFinite(high[front])) front--;
    const lz = zOf(Math.max(0, front - 2)), ly = high[Math.max(0, front - 2)] + 0.03, lx = -maxX * 0.3;
    const housing = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 0.06, 12).rotateX(Math.PI / 2), g.dark);
    housing.position.set(lx, ly, lz);
    housing.matrixAutoUpdate = true;
    eng.group.add(housing);
    const lensMat = new THREE.MeshStandardMaterial({ color: LANTERN, roughness: 0.4, metalness: 0, emissive: LANTERN_GLOW, emissiveIntensity: 0.85, flatShading: true });
    eng.lit = [...eng.lit, lensMat];
    const lens = new THREE.Mesh(new THREE.CylinderGeometry(0.024, 0.024, 0.008, 12).rotateX(Math.PI / 2), lensMat);
    lens.position.set(lx, ly, lz + 0.031);
    eng.group.add(lens);
    const f = treatFx();
    const from = new THREE.Vector3(lx, ly, lz + 0.035), aim = new THREE.Vector3(0, 0.02, L / 2 + Math.min(2.4, L * 0.9));
    const d = aim.clone().sub(from), dist = d.length(), spread = dist * 0.17;
    const beam = sharedPiece(new THREE.Mesh(f.beam, f.beamMat));
    beam.position.copy(from);
    beam.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.normalize());
    beam.scale.set(spread, dist, spread);
    beam.renderOrder = 5;
    eng.group.add(beam);
    const spot = sharedPiece(new THREE.Mesh(f.pool, f.beamMat));
    spot.position.copy(aim);
    spot.scale.set(spread * 1.2, 1, spread * 1.6);
    spot.renderOrder = 5;
    eng.group.add(spot);
  }
  for (const o of eng.group.children) if (!before.has(o)) tag(o);
}

/** A lantern engine's own list of glowing materials, before the lantern's were added to it. */
const stockLit = new WeakMap<CarMesh, THREE.MeshStandardMaterial[]>();

// ---- the confetti horn ----

const CONFETTI = [0xff4f8b, 0xffd23f, 0x3fd2ff, 0x7cff6b, 0xb06bff, 0xff8a3f, 0xffffff];

/** The confetti horn's burst (game/sfx.ts treatHorn 'confetti'): paper flung up out of the vehicle at (x, y, z), and a few sparks. */
export function confettiBurst(p: EventParticles | null, x: number, y: number, z: number, size = 1): void {
  if (!p) return;
  const n = Math.round(70 * Math.min(2, Math.max(0.6, size)));
  for (let i = 0; i < n; i++) {
    const a = Math.random() * Math.PI * 2, s = (0.6 + Math.random() * 1.4) * size;
    p.slip({ x, y, z, vx: Math.cos(a) * s, vy: (2.2 + Math.random() * 2.2) * size, vz: Math.sin(a) * s, life: 2.5 + Math.random() * 2, colour: CONFETTI[i % CONFETTI.length], size: 0.06 * Math.max(0.8, size), drag: 1.2 });
  }
  for (let i = 0; i < 16; i++) {
    const a = Math.random() * Math.PI * 2, s = 1.2 * size;
    p.spark({ x, y, z, vx: Math.cos(a) * s, vy: 2.4 * size, vz: Math.sin(a) * s, life: 0.6 + Math.random() * 0.4, colour: CONFETTI[i % CONFETTI.length], size: 0.12 });
  }
}
