import { hex, mix, scale, type RGB } from '../../world/biomes';
import type { Building, RailsideKind } from '../../world/tiles';
import type { Rng } from '../../world/rng';
import { Vis, type Sched } from '../nightLights';
import { BRICK, CARS, DARK, GLASS, METAL, ROOF_GREY, SHOP_GLOW, STONE, TAU, WARM_GLOW, WATER, WHITE, WOOD, pick, row, win, type Draw, type Kit, type P3 } from './kit';
import { clock } from './civic';
import { lorry } from './business';

/**
 * Works beside the railway (world/railside.ts; held for 0.8.0), making or taking goods by the trainload: a lumber
 * siding, a coal loader, a tank farm, a stockyard, a cement loadout, an inland container port, a mail depot, a
 * ballast pit, a produce shed and a brewery with its own dock.
 *
 * W runs along the line and the front (+z) faces it, as a station's does: each lot draws its own short siding along
 * the front edge (ballast, sleepers and rails like the track mesh's, a buffer stop at one end) with wagons standing at
 * whatever loads them, and the works behind it.
 */

const BALLAST = hex(0x8f8a82), SLEEPER = hex(0x5a4a3c), RAIL = hex(0x6d6f73), BUFFER = hex(0x6e2f2f);
const CONCRETE = hex(0xc4c0b8), STEEL = hex(0x9aa0a6), YELLOW = hex(0xf2b33b), RED = hex(0xe2412f);
const COAL = hex(0x2b2b2e), BOGIE = hex(0x2a2a2a), LAMP_DAY = hex(0xe8e4d0);
const CONTAINERS = [0xe2412f, 0x2bb3a3, 0xf2c14e, 0x4a6fa5, 0xf28c38, 0x8e5cc7, 0x6f9e6b, 0xb9bdc2, 0x2f5a96];

/** Yard lamps and lit signs: on at dusk, all night. */
const LAMP: Sched = [17, 30, 2.2];
const SIGN: Sched = [16.5, 30, 1.8];
const BEACON: Sched = [0, 24, 3];

// ---- shared pieces -----------------------------------------------------------------------------

/** The yard's own short track along x at z: ballast, sleepers, rails, and a buffer stop at the `stop` end (+1 or -1). */
function siding(k: Kit, x0: number, x1: number, z: number, stop: -1 | 0 | 1 = 1): void {
  const L = x1 - x0, mx = (x0 + x1) / 2;
  k.box(mx, 0, z, L, 0.04, 0.5, BALLAST);
  const n = Math.max(2, Math.round(L / 0.36));
  for (let i = 0; i < n; i++) k.box(x0 + (L * (i + 0.5)) / n, 0.04, z, 0.06, 0.015, 0.36, SLEEPER);
  for (const s of [-1, 1]) k.box(mx, 0.055, z + s * 0.11, L, 0.02, 0.02, RAIL);
  if (stop) {
    const bx = stop > 0 ? x1 - 0.08 : x0 + 0.08;
    k.box(bx, 0.04, z, 0.1, 0.14, 0.34, BUFFER);
    k.box(bx - stop * 0.06, 0.12, z, 0.02, 0.05, 0.3, RED);
  }
}

/**
 * A round body lying along x (or z), its axis at height y: a log, a barrel, a tank wagon's barrel, a pipe.
 * `ends` colours its two end faces (a log's sawn ends).
 */
function drum(k: Kit, x: number, y: number, z: number, r: number, len: number, col: RGB, seg = 8, ends: RGB = col, alongZ = false): void {
  const h = len / 2, I: P3 = [x, y, z];
  const at = (u: number, a: number): P3 =>
    alongZ ? [x + Math.cos(a) * r, y + Math.sin(a) * r, z + u] : [x + u, y + Math.sin(a) * r, z + Math.cos(a) * r];
  const c0: P3 = alongZ ? [x, y, z - h] : [x - h, y, z], c1: P3 = alongZ ? [x, y, z + h] : [x + h, y, z];
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
    k.quad(at(-h, a0), at(h, a0), at(h, a1), at(-h, a1), col, I);
    k.tri(at(-h, a0), at(-h, a1), c0, ends, I);
    k.tri(at(h, a0), at(h, a1), c1, ends, I);
  }
}

/** A wagon's underframe and its two bogies, on the siding's rails (rail top 0.075; the frame's top is 0.125). */
function chassis(k: Kit, x: number, z: number, len: number): void {
  k.box(x, 0.075, z, len, 0.05, 0.3, DARK);
  for (const s of [-1, 1]) k.box(x + s * (len / 2 - 0.16), 0.055, z, 0.14, 0.05, 0.28, BOGIE);
}

/** A flat wagon: its deck's top is at 0.155. */
function flatWagon(k: Kit, x: number, z: number, len: number, col: RGB): void {
  chassis(k, x, z, len);
  k.box(x, 0.125, z, len, 0.03, 0.32, col);
}

/** An open hopper wagon, heaped with `load` (or empty). */
function hopperWagon(k: Kit, x: number, z: number, col: RGB, load: RGB | null): void {
  chassis(k, x, z, 0.9);
  k.box(x, 0.125, z, 0.84, 0.26, 0.3, col, scale(col, 0.7));
  k.detail(() => {
    for (const s of [-1, 1]) for (const rx of [-0.21, 0.21]) k.box(x + rx, 0.13, z + s * 0.155, 0.03, 0.25, 0.01, scale(col, 0.8));
  });
  if (load) k.hip(x, 0.385, z, 0.78, 0.09, 0.26, load);
}

/** A covered van wagon: a box body and a shallow roof, a sliding door each side and, if asked, a band of colour. */
function vanWagon(k: Kit, x: number, z: number, col: RGB, roof: RGB, band: RGB | null = null): void {
  chassis(k, x, z, 0.9);
  k.box(x, 0.125, z, 0.86, 0.3, 0.3, col);
  k.gable(x, 0.425, z, 0.88, 0.05, 0.32, roof, col);
  for (const s of [-1, 1]) k.box(x, 0.16, z + s * 0.152, 0.26, 0.24, 0.01, scale(col, 0.8));
  if (band) k.detail(() => { for (const s of [-1, 1]) k.box(x, 0.36, z + s * 0.153, 0.86, 0.03, 0.008, band); });
}

/** A tank wagon: the barrel lying on its frame with a dome and a walkway. */
function tankWagon(k: Kit, x: number, z: number, col: RGB): void {
  chassis(k, x, z, 0.9);
  drum(k, x, 0.26, z, 0.13, 0.84, col, 8, scale(col, 0.85));
  k.cyl(x, 0.37, z, 0.05, 0.06, scale(col, 0.9), 6);
  k.box(x, 0.125, z, 0.9, 0.02, 0.34, scale(DARK, 1.3));
}

/** A floodlight on its mast, lit dusk to dawn. */
function mast(k: Kit, x: number, z: number, h: number): void {
  k.cyl(x, 0, z, 0.025, h, METAL, 5);
  k.box(x, h, z, 0.16, 0.05, 0.08, DARK);
  k.glowBox(x, h - 0.02, z, 0.13, 0.02, 0.06, LAMP_DAY, LAMP, WARM_GLOW);
}

/** A conveyor or covered gallery from a to b, on trestles wherever it runs high. */
function conveyor(k: Kit, a: P3, b: P3, r: number, col: RGB, legs: RGB = STEEL): void {
  k.bar(a, b, r, col);
  for (const t of [0.35, 0.7]) {
    const p: P3 = [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
    if (p[1] < 0.2) continue;
    for (const s of [-1, 1]) k.bar([p[0] + s * 0.06, 0, p[2]], [p[0] + s * 0.03, p[1] - r, p[2]], 0.014, legs);
  }
}

/** A small yard office: a box, a pitched roof, a lit window toward the line and a door. */
function office(k: Kit, b: Building, r: Rng, x: number, z: number, w: number, d: number, wall: RGB, roof: RGB): void {
  k.box(x, 0, z, w, 0.32, d, wall);
  k.gable(x, 0.32, z, w + 0.06, 0.12, d + 0.06, roof, wall);
  win(k, b, r, x - w * 0.18, 0.12, z + d / 2, w * 0.36, 0.12, 1);
  k.box(x + w * 0.25, 0, z + d / 2 + 0.004, 0.1, 0.22, 0.012, scale(wall, 0.6));
  k.glowBox(x + w * 0.25, 0.25, z + d / 2 + 0.03, 0.05, 0.03, 0.04, LAMP_DAY, LAMP, WARM_GLOW);
}

/** A container lying along x (or z): a box with its door end a shade darker. */
function container(k: Kit, x: number, y: number, z: number, len: number, col: RGB, doors = true): void {
  k.box(x, y, z, len, 0.26, 0.24, col, scale(col, 0.9));
  if (doors) k.detail(() => k.box(x + len / 2 + 0.004, y + 0.02, z, 0.008, 0.22, 0.2, scale(col, 0.75)));
}

// ---- lumber siding -----------------------------------------------------------------------------

/** A log deck of chained piles and banded packs of sawn timber, a log loader lifting onto a bolster wagon. */
const lumberSiding: Draw = (k, W, D, b, r) => {
  const F = D / 2, sz = F - 0.32;
  const bark = hex(0x6e5238), cut = hex(0xe0c08e), plank = hex(0xd8b27a);
  k.box(0, 0, 0, W - 0.06, 0.01, D - 0.06, hex(0xb3a58a));
  siding(k, -W / 2 + 0.08, W / 2 - 0.08, sz, 1);

  // the bolster wagon at the loader, its stanchions holding a load of logs
  const lx = -0.55;
  flatWagon(k, lx, sz, 1.0, hex(0x5a5048));
  for (const xs of [-0.38, 0, 0.38]) for (const s of [-1, 1]) k.box(lx + xs, 0.155, sz + s * 0.15, 0.02, 0.24, 0.02, DARK);
  const logOn = (x: number, y: number, z: number, len: number, rad = 0.06) =>
    drum(k, x, y, z, rad * (0.85 + r() * 0.3), len * (0.92 + r() * 0.08), scale(bark, 0.88 + r() * 0.24), 6, cut);
  for (const s of [-1, 1]) logOn(lx, 0.215, sz + s * 0.065, 0.95);
  logOn(lx, 0.315, sz, 0.95);
  if (r() < 0.6) for (const s of [-1, 1]) logOn(lx + 0.02, 0.4, sz + s * 0.065, 0.9, 0.05);
  // a flat beyond it with two packs of boards, strapped
  const fx = lx + 1.2;
  flatWagon(k, fx, sz, 1.0, hex(0x5a5048));
  for (const s of [-1, 1]) {
    k.box(fx + s * 0.24, 0.155, sz, 0.44, 0.15 + r() * 0.06, 0.26, scale(plank, 0.95 + r() * 0.08));
    k.detail(() => k.box(fx + s * 0.24, 0.155, sz, 0.02, 0.22, 0.27, DARK));
  }

  // the log deck at the back: two piles on bearers, staked at the ends
  const pile = (cx: number, cz: number, len: number, base: number, layers: number) => {
    const half = (base - 1) * 0.065 + 0.1;
    for (const s of [-1, 1]) k.box(cx + s * len * 0.3, 0, cz, 0.08, 0.04, half * 2, DARK);
    for (let j = 0; j < layers; j++) {
      const n = base - j;
      for (let i = 0; i < n; i++) logOn(cx + (r() - 0.5) * 0.08, 0.04 + 0.065 + j * 0.112, cz + (i - (n - 1) / 2) * 0.13, len, 0.065);
    }
    for (const s of [-1, 1]) k.box(cx + s * (len / 2 + 0.04), 0, cz + half - 0.05, 0.04, 0.12 + layers * 0.1, 0.04, WOOD);
  };
  pile(-1.0, -0.85, 1.6, 6, 2 + Math.floor(r() * 2));
  pile(-1.05, -0.05, 1.5, 4, 2 + Math.floor(r() * 2));

  // the log loader between deck and siding, its grapple swinging a log across to the wagon
  k.within(lx, 0.6, 0, () => {
    for (const sx of [-1, 1]) for (const s of [-1, 1]) k.box(sx * 0.12, 0, s * 0.13, 0.06, 0.12, 0.1, DARK);
    k.box(0, 0.06, 0, 0.2, 0.1, 0.42, YELLOW);
    k.box(0, 0.16, -0.15, 0.2, 0.1, 0.12, scale(YELLOW, 0.85));
    k.box(0.02, 0.16, 0.0, 0.16, 0.17, 0.15, YELLOW, DARK);
    k.box(0.02, 0.22, 0.077, 0.13, 0.08, 0.006, GLASS);
    for (const s of [-1, 1]) k.bar([s * 0.07, 0.16, 0.16], [s * 0.05, 0.72, 0.36], 0.022, YELLOW);
    k.bar([0, 0.3, 0.12], [0, 0.6, 0.3], 0.018, DARK);
    k.box(0, 0.7, 0.4, 0.14, 0.06, 0.08, DARK);
    for (const s of [-1, 1]) {
      k.bar([0, 0.7, 0.4 + s * 0.03], [0, 0.6, 0.4 + s * 0.09], 0.01, DARK);
      k.bar([0, 0.6, 0.4 + s * 0.09], [0, 0.53, 0.4 + s * 0.04], 0.01, DARK);
    }
  });
  logOn(lx, 0.6, 1.0, 0.85, 0.055);

  // sawn timber at the right: packs on bearers, the back row under an open shelter
  const pack = (x: number, z: number, n: number) => {
    for (const s of [-1, 1]) k.box(x + s * 0.2, 0, z, 0.06, 0.05, 0.52, DARK);
    for (let j = 0; j < n; j++) {
      const y = 0.05 + j * 0.135;
      k.box(x, y, z, 0.62, 0.11, 0.48, scale(plank, 1 - j * 0.03 - r() * 0.05));
      if (j < n - 1) for (const s of [-1, 1]) k.box(x + s * 0.2, y + 0.11, z, 0.04, 0.025, 0.5, scale(plank, 0.7));
    }
  };
  for (const px of [0.65, 1.45]) {
    pack(px, -1.0, 2 + Math.floor(r() * 3));
    pack(px, -0.3, 1 + Math.floor(r() * 3));
  }
  for (const sx of [0.28, 1.82]) for (const pz of [-1.33, -0.67]) k.box(sx, 0, pz, 0.05, 0.62, 0.05, WOOD);
  k.gable(1.05, 0.62, -1.0, 1.7, 0.12, 0.82, ROOF_GREY, WOOD);
  k.cone(0.05, 0, -1.2, 0.2, 0.14, hex(0x9a7a52), 7);

  // the weigh hut by the line and a floodlight over the deck
  office(k, b, r, 1.45, 0.5, 0.5, 0.34, WHITE, hex(0x3f5a73));
  mast(k, -1.85, 0.6, 1.0);
};

// ---- coal loader -------------------------------------------------------------------------------

/** A loading bunker on four legs straddling the track, fed by a covered conveyor from the coal heaps. */
const coalLoader: Draw = (k, W, D, b, r) => {
  const F = D / 2, sz = F - 0.32;
  const frame = pick(r, [0x3f4a52, 0x6b4a3a, 0x4f6b4a]), bin = pick(r, [0x7a7d82, 0x8a4f32, 0x5f6b73]), shed = hex(0xc9cdd0);
  k.box(0, 0, 0, W - 0.06, 0.01, D - 0.06, hex(0x6f6b64));
  siding(k, -W / 2 + 0.08, W / 2 - 0.08, sz, 1);

  // the bunker on its legs, braced along both sides, the chute down to the wagon under it
  const bx = 0.3, by = 0.78, bh = 0.5;
  for (const sx of [-1, 1]) for (const s of [-1, 1]) k.box(bx + sx * 0.3, 0, sz + s * 0.28, 0.07, by, 0.07, frame);
  for (const s of [-1, 1]) {
    k.bar([bx - 0.3, 0.08, sz + s * 0.28], [bx + 0.3, by - 0.06, sz + s * 0.28], 0.015, frame);
    k.box(bx, by - 0.08, sz + s * 0.28, 0.66, 0.06, 0.06, frame);
  }
  k.box(bx, by, sz, 0.72, bh, 0.6, bin, scale(bin, 0.9));
  k.detail(() => {
    for (const s of [-1, 1]) for (const rx of [-0.18, 0.18]) k.box(bx + rx, by, sz + s * 0.302, 0.03, bh, 0.01, scale(bin, 0.8));
  });
  k.hip(bx, by, sz, 0.72, -0.2, 0.6, scale(bin, 0.85));
  k.box(bx, by - 0.3, sz, 0.12, 0.14, 0.12, DARK);
  // the head house on top where the belt comes in, and the ladder up
  const hy = by + bh;
  k.box(bx, hy, sz - 0.08, 0.5, 0.26, 0.42, shed, ROOF_GREY);
  k.gable(bx, hy + 0.26, sz - 0.08, 0.54, 0.1, 0.46, ROOF_GREY, shed);
  win(k, b, r, bx + 0.25, hy + 0.08, sz - 0.04, 0.16, 0.1, 0);
  // a railed walkway round the bunker's top, and the ladder up a leg
  for (const s of [-1, 1]) {
    k.box(bx, hy + 0.11, sz + s * 0.29, 0.72, 0.015, 0.015, YELLOW);
    k.box(bx + s * 0.35, hy + 0.11, sz, 0.015, 0.015, 0.6, YELLOW);
    for (const s2 of [-1, 1]) k.box(bx + s * 0.35, hy, sz + s2 * 0.29, 0.015, 0.12, 0.015, YELLOW);
  }
  for (const lz of [sz - 0.04, sz + 0.04]) k.bar([bx + 0.42, 0, lz], [bx + 0.42, hy, lz], 0.008, YELLOW);
  for (let i = 1; i < 7; i++) k.box(bx + 0.42, (hy * i) / 7, sz, 0.01, 0.01, 0.08, YELLOW);
  k.tagged(Vis.Always, () => k.glowBox(bx, hy + 0.36, sz - 0.08, 0.05, 0.05, 0.05, hex(0xff3b30), BEACON, hex(0xff3b30)));

  // wagons: one under the chute, one waiting its turn
  hopperWagon(k, bx, sz, pick(r, [0x5a5048, 0x6d7176, 0x8a3a2a]), scale(COAL, 1.3));
  hopperWagon(k, bx - 1.05, sz, pick(r, [0x5a5048, 0x6d7176, 0x8a3a2a]), r() < 0.5 ? null : scale(COAL, 1.3));

  // the heaps at the back, the ground hopper the belt rises from, and a dozer pushing coal to it
  k.cone(-0.6, 0, -0.65, 0.62, 0.42, COAL, 10);
  k.cone(0.95, 0, -0.95, 0.42, 0.3, scale(COAL, 1.2), 9);
  k.cone(0.0, 0, -1.15, 0.25, 0.14, scale(COAL, 1.1), 7);
  k.box(bx, 0, -0.85, 0.44, 0.16, 0.44, STEEL, COAL);
  for (let i = 0; i < 6; i++) k.box(-1.25 + i * 0.5, 0, -F + 0.12, 0.46, 0.2 + (i % 2) * 0.04, 0.16, CONCRETE);
  lorry(k, 0.95, -0.32, true, pick(r, [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a]));
  conveyor(k, [bx, 0.14, -0.7], [bx, hy + 0.14, sz - 0.28], 0.055, shed, frame);
  k.within(-0.75, 0.35, 0.4 + r() * 0.8, () => {
    for (const s of [-1, 1]) k.box(s * 0.1, 0, 0, 0.06, 0.07, 0.3, DARK);
    k.box(0, 0.05, -0.02, 0.18, 0.1, 0.24, YELLOW);
    k.box(0, 0.15, -0.06, 0.13, 0.11, 0.12, YELLOW, DARK);
    k.box(0, 0.0, 0.19, 0.28, 0.1, 0.03, scale(YELLOW, 0.8));
  });

  // the control cabin by the line, and a floodlight
  office(k, b, r, 1.05, 0.42, 0.42, 0.32, WHITE, ROOF_GREY);
  mast(k, -1.35, 0.62, 1.1);
};

// ---- tank farm ---------------------------------------------------------------------------------

/** Round oil tanks in a bund with stairs wound up them, piped to a loading rack gantry over three tank wagons. */
const tankFarm: Draw = (k, W, D, b, r) => {
  const F = D / 2, sz = F - 0.32;
  const paint = pick(r, [0xe8e6df, 0xd8dcdf, 0xcfd2c8]), rack = pick(r, [0xf2b33b, 0x3f6f9a, 0xe2412f]);
  const pipe = hex(0x8a8f96), livery = pick(r, [0xe2412f, 0x2f5d8a, 0x3f9b4a, 0xf2a93b]);
  k.box(0, 0, 0, W - 0.06, 0.01, D - 0.06, hex(0xa9a59c));
  siding(k, -W / 2 + 0.08, W / 2 - 0.08, sz, 1);

  // the tanks, three or four, each in its own size, with a stair round and a rail at the rim
  const four = r() < 0.5;
  const tanks: [number, number, number, number][] = four
    ? [[-1.8, -0.95, 0.5, 0.6 + r() * 0.25], [-0.6, -0.95, 0.5, 0.6 + r() * 0.25], [0.6, -0.95, 0.5, 0.6 + r() * 0.25], [1.75, -1.15, 0.42, 0.45 + r() * 0.2]]
    : [[-1.55, -0.9, 0.62, 0.7 + r() * 0.25], [0.0, -0.9, 0.62, 0.6 + r() * 0.3], [1.55, -1.05, 0.5, 0.5 + r() * 0.25]];
  const bund = hex(0xb8b2a6);
  const bz0 = -F + 0.12, bz1 = 0.0;
  for (const z of [bz0, bz1]) k.box(0, 0, z, W - 0.24, 0.1, 0.06, bund);
  for (const s of [-1, 1]) k.box(s * (W / 2 - 0.15), 0, (bz0 + bz1) / 2, 0.06, 0.1, bz1 - bz0, bund);
  for (const [tx, tz, R, H] of tanks) {
    k.cyl(tx, 0, tz, R, H, paint, 14, scale(paint, 0.92));
    k.cone(tx, H, tz, R, 0.08, scale(paint, 0.88), 14);
    k.band(tx, tz, H, R + 0.01, H + 0.06, R + 0.01, 14, METAL, METAL);
    k.band(tx, tz, H * 0.62, R + 0.006, H * 0.74, R + 0.006, 14, livery);
    // the stair, wound a third of the way round
    const a0 = Math.PI * (0.35 + r() * 0.3), turns = 3;
    for (let i = 0; i < turns; i++) {
      const t0 = i / turns, t1 = (i + 1) / turns;
      const p = (t: number, lift = 0): P3 => {
        const a = a0 + t * 2.0;
        return [tx + Math.cos(a) * (R + 0.04), H * t + lift, tz + Math.sin(a) * (R + 0.04)];
      };
      k.bar(p(t0), p(t1), 0.018, rack);
      k.bar(p(t0, 0.08), p(t1, 0.08), 0.008, METAL);
    }
    // its pipe out through the bund to the header, with a red valve
    k.bar([tx, 0.06, tz + R], [tx, 0.06, 0.55], 0.022, pipe);
    k.box(tx, 0.03, tz + R + 0.12, 0.06, 0.08, 0.06, RED);
  }

  // the header along the rack, on its sleepers of concrete
  drum(k, -0.2, 0.08, 0.55, 0.035, W - 0.6, pipe, 6);
  for (let i = 0; i < 5; i++) k.box(-0.2 - (W - 0.8) / 2 + (i * (W - 0.8)) / 4, 0, 0.55, 0.06, 0.05, 0.14, CONCRETE);

  // the loading rack: a walkway on posts beside the track under a canopy, arms swung out over the wagons
  const rz = sz - 0.36, ry = 0.48, rx0 = -2.15, rx1 = 1.0, rw = rx1 - rx0, rcx = (rx0 + rx1) / 2;
  for (let i = 0; i < 5; i++) {
    const px = rx0 + (i * rw) / 4;
    k.box(px, 0, rz - 0.08, 0.05, 0.9, 0.05, rack);
    k.box(px, 0, rz + 0.08, 0.04, ry, 0.04, rack);
  }
  k.box(rcx, ry, rz, rw + 0.06, 0.04, 0.24, scale(rack, 0.8), DARK);
  k.box(rcx, ry + 0.04, rz + 0.11, rw, 0.12, 0.012, METAL);
  k.box(rcx, 0.9, rz + 0.05, rw + 0.2, 0.04, 0.5, ROOF_GREY, scale(ROOF_GREY, 1.1));
  k.wedge(rx0 - 0.15, 0, rz - 0.12, 0.18, ry, 0.5, scale(rack, 0.7));
  const wagonCols = [0x2f3338, 0xe8e6df, 0x9aa0a6, 0x3f4a52];
  for (let i = 0; i < 3; i++) {
    const wx = -1.6 + i * 1.0;
    tankWagon(k, wx, sz, hex(wagonCols[Math.floor(r() * wagonCols.length)]));
    k.bar([wx, ry + 0.1, rz + 0.1], [wx, ry + 0.02, sz - 0.05], 0.012, rack);
    k.bar([wx, ry + 0.02, sz - 0.05], [wx, 0.4, sz], 0.01, DARK);
    k.bar([wx, 0.08, 0.55], [wx, ry, rz - 0.06], 0.016, pipe);
  }
  k.glowBox(rcx, 0.875, rz + 0.05, rw * 0.8, 0.02, 0.06, LAMP_DAY, LAMP, WARM_GLOW);

  // the pump house at the end of the rack, and floodlights
  office(k, b, r, 1.85, 0.75, 0.6, 0.4, hex(0xd9dde0), hex(0x3f5a73));
  mast(k, -2.35, 0.6, 1.3);
  mast(k, 2.3, -0.2, 1.3);
};

// ---- stockyard ---------------------------------------------------------------------------------

/** One beast: four legs, a body, a head; some with a white saddle. */
function cow(k: Kit, x: number, z: number, yaw: number, hide: RGB, r: Rng): void {
  const head = r() < 0.4 ? WHITE : hide, legs = scale(hide, 0.75), u = 1.4;
  const part = (px: number, py: number, pz: number, w: number, h: number, d: number, col: RGB) => k.box(px * u, py * u, pz * u, w * u, h * u, d * u, col);
  k.within(x, z, yaw, () => {
    for (const sx of [-1, 1]) for (const s of [-1, 1]) part(sx * 0.032, 0, s * 0.07, 0.022, 0.07, 0.022, legs);
    part(0, 0.06, 0, 0.09, 0.075, 0.2, hide);
    if (r() < 0.35) part(0, 0.064, -0.02, 0.094, 0.06, 0.07, WHITE);
    part(0, 0.09, 0.125, 0.06, 0.06, 0.07, head);
    part(0, 0.09, 0.163, 0.04, 0.03, 0.01, hex(0xc9958a));
  });
}

/** A rail fence from (x0, z0) to (x1, z1) along x or z: posts and two rails. */
function rails(k: Kit, x0: number, z0: number, x1: number, z1: number, col: RGB): void {
  const L = Math.hypot(x1 - x0, z1 - z0), n = Math.max(1, Math.round(L / 0.55));
  for (let i = 0; i <= n; i++) k.box(x0 + ((x1 - x0) * i) / n, 0, z0 + ((z1 - z0) * i) / n, 0.035, 0.2, 0.035, scale(col, 0.85));
  const alongX = Math.abs(x1 - x0) > Math.abs(z1 - z0);
  for (const y of [0.08, 0.16]) k.box((x0 + x1) / 2, y, (z0 + z1) / 2, alongX ? L : 0.015, 0.025, alongX ? 0.015 : L, col);
}

/** Railed pens of cattle, a raised chute and ramp up to the cattle wagons, a trough or two and the yard office. */
const stockyard: Draw = (k, W, D, b, r) => {
  const F = D / 2, sz = F - 0.32;
  const fence = pick(r, [0xd8cfb8, 0x8d6d48, 0xb9bdc2]), mud = hex(0x8c7656);
  k.box(0, 0, 0, W - 0.06, 0.01, D - 0.06, hex(0xb3a283));
  const px0 = -W / 2 + 0.2, px1 = W / 2 - 0.2, pz0 = -F + 0.15, pz1 = 0.35;
  k.box((px0 + px1) / 2, 0, (pz0 + pz1) / 2, px1 - px0, 0.014, pz1 - pz0, mud);
  siding(k, -W / 2 + 0.08, W / 2 - 0.08, sz, 1);

  // the pens: three across, two deep, a gap in the front rail where the alley leads to the ramp
  const cols = [px0, -0.75, 0.8, px1], pzm = (pz0 + pz1) / 2;
  const chuteX = 0.6;
  rails(k, px0, pz0, px1, pz0, fence);
  rails(k, px0, pzm, px1, pzm, fence);
  rails(k, px0, pz1, chuteX - 0.18, pz1, fence);
  rails(k, chuteX + 0.18, pz1, px1, pz1, fence);
  for (const x of cols) rails(k, x, pz0, x, pz1, fence);
  // troughs and a hay rack
  for (const [tx, tz] of [[-1.5, pz0 + 0.2], [0.0, pz0 + 0.2], [1.6, pzm + 0.2]] as [number, number][]) {
    k.box(tx, 0, tz, 0.4, 0.07, 0.1, STEEL, WATER);
  }
  k.box(-1.5, 0, pzm + 0.25, 0.3, 0.14, 0.2, hex(0xd9b860));

  // the cattle, a few to a pen
  const hides = [0x6b4a32, 0x2a2624, 0xb07a4a, 0xe8e0d0, 0x8a3a24];
  const n = 9 + Math.floor(r() * 5);
  for (let i = 0; i < n; i++) {
    const c = i % 6, cx0 = cols[c % 3], cx1 = cols[(c % 3) + 1];
    const z0 = c < 3 ? pz0 : pzm, z1 = c < 3 ? pzm : pz1;
    const x = cx0 + 0.2 + r() * (cx1 - cx0 - 0.4), z = z0 + 0.2 + r() * (z1 - z0 - 0.4);
    cow(k, x, z, r() * TAU, hex(hides[Math.floor(r() * hides.length)]), r);
  }

  // the ramp up from the alley to the chute's platform, boarded both sides, at the cattle wagon's door
  const deck = 0.2, rampZ0 = pz1 + 0.02, rampZ1 = 1.0, platZ1 = sz - 0.24;
  k.wedge(chuteX, 0, (rampZ0 + rampZ1) / 2, 0.3, deck, rampZ1 - rampZ0, scale(WOOD, 0.9));
  k.box(chuteX, 0, (rampZ1 + platZ1) / 2, 0.36, deck, platZ1 - rampZ1, CONCRETE, scale(WOOD, 0.9));
  for (const s of [-1, 1]) {
    const x = chuteX + s * 0.17;
    k.bar([x, 0.24, rampZ0], [x, deck + 0.28, rampZ1], 0.012, WOOD);
    k.bar([x, 0.14, rampZ0], [x, deck + 0.16, rampZ1], 0.012, WOOD);
    k.box(x, deck, (rampZ1 + platZ1) / 2, 0.02, 0.28, platZ1 - rampZ1, WOOD);
    for (const z of [rampZ0, (rampZ0 + rampZ1) / 2, rampZ1]) {
      k.box(x, 0, z, 0.03, deck * ((z - rampZ0) / (rampZ1 - rampZ0)) + 0.28, 0.03, scale(WOOD, 0.8));
    }
  }
  // the cattle wagons, slatted vans, one at the chute
  const van = pick(r, [0x8a3a2a, 0x6d5a48, 0x5a6b4a]);
  for (const wx of [chuteX, chuteX - 1.05, chuteX + 1.05]) {
    if (wx !== chuteX && r() < 0.35) continue;
    vanWagon(k, wx, sz, van, ROOF_GREY);
    k.detail(() => { for (const s of [-1, 1]) for (const y of [0.2, 0.3]) k.box(wx, y, sz + s * 0.153, 0.84, 0.025, 0.008, DARK); });
  }

  // the yard office at the gate, and a lamp over the chute
  office(k, b, r, -1.85, 0.85, 0.6, 0.42, pick(r, [0xf1ede4, 0xe8d3b0, 0xdbe8c9]), hex(0x8a4a3a));
  k.box(chuteX + 0.32, 0, 0.8, 0.03, 0.75, 0.03, DARK);
  k.glowBox(chuteX + 0.24, 0.72, 0.8, 0.14, 0.03, 0.06, LAMP_DAY, LAMP, WARM_GLOW);

};

