/** Two or three tall cement silos with a house across their tops, an air slide down to a bin straddling the track. */
const cementLoadout: Draw = (k, W, D, b, r) => {
  const F = D / 2, sz = F - 0.32;
  const conc = hex(0xcfcac0), dust = hex(0xdcd8d0), frame = pick(r, [0x6d7176, 0x3f5a73, 0xf2b33b]);
  k.box(0, 0, 0, W - 0.06, 0.01, D - 0.06, hex(0xc2bdb2));
  siding(k, -W / 2 + 0.08, W / 2 - 0.08, sz, 1);

  // the silos in a row at the back, each on its plinth, with a fill pipe down the face
  const n = r() < 0.5 ? 2 : 3, R = n === 3 ? 0.3 : 0.36, H = 1.7 + r() * 0.35, gap = R * 2 + 0.06;
  const zs = -F + R + 0.22;
  const xs = Array.from({ length: n }, (_, i) => (i - (n - 1) / 2) * gap - 0.28);
  for (const x of xs) {
    k.cyl(x, 0, zs, R * 1.06, 0.14, scale(conc, 0.85), 12);
    k.cyl(x, 0.14, zs, R, H - 0.14, conc, 12, scale(conc, 1.04));
    k.box(x, 0.0, zs + R * 0.98, 0.14, 0.24, 0.04, DARK);
    k.bar([x + R * 0.5, 0.3, zs + R * 0.9], [x + R * 0.5, H, zs + R * 0.9], 0.012, STEEL);
  }
  // the house across the tops: windows lit, two dust filters and a beacon
  const span = xs[n - 1] - xs[0] + R * 2, hcx = (xs[0] + xs[n - 1]) / 2;
  k.box(hcx, H, zs, span, 0.26, R * 1.5, dust, ROOF_GREY);
  row(k, b, r, hcx, H + 0.07, zs + R * 0.75, span - 0.3, 0.12, n + 1, 1);
  for (const x of [xs[0] + 0.15, xs[n - 1] - 0.15]) k.cyl(x, H + 0.26, zs - 0.05, 0.07, 0.14, METAL, 6, DARK);
  k.tagged(Vis.Always, () => k.glowBox(hcx, H + 0.26, zs + 0.1, 0.05, 0.05, 0.05, hex(0xff3b30), BEACON, hex(0xff3b30)));

  // the stair tower beside them: four posts and flights zig-zagging up to the top house
  const tx = xs[n - 1] + R + 0.3, tz = zs + 0.05;
  for (const sx of [-1, 1]) for (const s of [-1, 1]) k.box(tx + sx * 0.13, 0, tz + s * 0.13, 0.03, H + 0.26, 0.03, frame);
  const flights = 4;
  for (let i = 0; i < flights; i++) {
    const y0 = (H * i) / flights, y1 = (H * (i + 1)) / flights, s = i % 2 ? 1 : -1;
    k.bar([tx - 0.1 * s, y0, tz - 0.06], [tx + 0.1 * s, y1, tz + 0.06], 0.014, frame);
    k.box(tx, y1, tz, 0.28, 0.02, 0.28, scale(frame, 0.8));
  }
  k.box((tx + xs[n - 1] + R) / 2 - 0.05, H, tz, tx - xs[n - 1] - R + 0.1, 0.03, 0.18, scale(frame, 0.8));

  // the bin over the track on its legs, its telescopic spout down to the wagon's hatch
  const bx = 0.35, by = 0.78, bh = 0.42;
  for (const sx of [-1, 1]) for (const s of [-1, 1]) k.box(bx + sx * 0.28, 0, sz + s * 0.275, 0.06, by, 0.06, frame);
  for (const s of [-1, 1]) k.bar([bx - 0.28, 0.1, sz + s * 0.275], [bx + 0.28, by - 0.05, sz + s * 0.275], 0.013, frame);
  k.box(bx, by, sz, 0.6, bh, 0.6, dust, scale(dust, 0.92));
  k.detail(() => {
    for (const s of [-1, 1]) for (const o of [-0.15, 0.15]) {
      k.box(bx + o, by, sz + s * 0.303, 0.025, bh, 0.008, scale(dust, 0.82));
      k.box(bx + s * 0.303, by, sz + o, 0.008, bh, 0.025, scale(dust, 0.82));
    }
  });
  for (const s of [-1, 1]) {
    k.box(bx, by + bh + 0.1, sz + s * 0.29, 0.6, 0.015, 0.015, frame);
    k.box(bx - 0.29, by + bh + 0.1, sz + s * 0.12, 0.015, 0.015, 0.36, frame);
    for (const o of [-0.29, 0.29]) k.box(bx + o, by + bh, sz + s * 0.29, 0.015, 0.11, 0.015, frame);
  }
  k.hip(bx, by, sz, 0.6, -0.18, 0.6, scale(dust, 0.85));
  k.cyl(bx, 0.52, sz, 0.06, 0.1, DARK, 6);
  k.cyl(bx, 0.42, sz, 0.045, 0.12, scale(DARK, 1.3), 6);
  k.box(bx + 0.15, by + bh, sz - 0.1, 0.18, 0.14, 0.18, METAL);
  // the air slide from the top house down to the bin, on one trestle
  conveyor(k, [bx, H + 0.06, zs + R * 0.7], [bx, by + bh + 0.06, sz - 0.22], 0.05, dust, frame);

  // the covered cement wagons: a round-topped hopper under the spout, another waiting
  const wag = pick(r, [0xb9bdc2, 0x9aa0a6, 0xd9d4c8]);
  for (const wx of [bx, bx - 1.05]) {
    chassis(k, wx, sz, 0.9);
    k.box(wx, 0.125, sz, 0.84, 0.16, 0.28, wag);
    drum(k, wx, 0.29, sz, 0.14, 0.84, wag, 8, scale(wag, 0.9));
    for (const s of [-1, 1]) k.cyl(wx + s * 0.2, 0.42, sz, 0.045, 0.03, scale(wag, 0.8), 6);
  }

  // a floodlight at the gate
  mast(k, -W / 2 + 0.2, 0.6, 1.2);
};

// ---- inland port -------------------------------------------------------------------------------

/** An inland container terminal: a rail-mounted gantry over the track and the stacks, wagons of boxes, a reach stacker. */
const inlandPort: Draw = (k, W, D, b, r) => {
  const F = D / 2, sz = F - 0.5;
  const crane = pick(r, [0xf2b33b, 0x2f7fb5, 0xe2412f, 0xf4f2ec]);
  const box = (): RGB => pick(r, CONTAINERS);
  k.box(0, 0, 0, W - 0.06, 0.01, D - 0.06, hex(0x9d9a93));
  siding(k, -W / 2 + 0.08, W / 2 - 0.08, sz, 1);
  // the crane rails along the lot, front and back
  const zf = F - 0.1, zb = -F + 0.12;
  for (const z of [zf, zb]) k.box(0, 0.01, z, W - 0.1, 0.02, 0.05, RAIL);

  // container flats along the siding: forties, pairs of twenties, or empty
  const cx = -0.4 + (r() - 0.5) * 1.2, overWagon = r() < 0.5;
  const trolleyZ = overWagon ? sz : -0.7;
  for (let i = 0; i < 4; i++) {
    const wx = -2.15 + i * 1.36;
    flatWagon(k, wx, sz, 1.3, hex(0x4a4f55));
    if (overWagon && Math.abs(wx - cx) < 0.7) continue; // the one the crane is loading
    const pick2 = r();
    if (pick2 < 0.45) container(k, wx, 0.155, sz, 1.25, box());
    else if (pick2 < 0.85) for (const s of [-1, 1]) container(k, wx + s * 0.315, 0.155, sz, 0.6, box(), s > 0);
  }

  // the stacking ground behind: four blocks of forties, five rows deep, up to three high
  const rowsZ = [-1.6, -1.3, -1.0, -0.7, -0.4];
  for (const bxp of [-2.25, -0.95, 0.35, 1.65]) {
    for (const z of rowsZ) {
      const under = !overWagon && Math.abs(z - trolleyZ) < 0.2 && Math.abs(bxp - cx) < 1.3;
      const hmax = under ? 2 : 3;
      const h = Math.min(hmax, Math.floor(r() * 4));
      for (let j = 0; j < h; j++) container(k, bxp, j * 0.27, z, 1.25, box(), j === h - 1);
    }
  }

  // the gantry: two portals running on the rails, girders across, the trolley and its cab, a box on the spreader
  const gH = 1.35, legX = 0.65;
  for (const zl of [zf, zb]) {
    k.box(cx, 0, zl, legX * 2 + 0.2, 0.07, 0.12, scale(crane, 0.75));
    for (const s of [-1, 1]) {
      k.box(cx + s * legX, 0.0, zl, 0.16, 0.06, 0.14, DARK);
      k.box(cx + s * legX, 0.07, zl, 0.08, gH - 0.21, 0.08, crane);
    }
    k.bar([cx - legX, 0.12, zl], [cx + legX, gH - 0.16, zl], 0.016, crane);
    k.box(cx, gH - 0.14, zl, legX * 2 + 0.12, 0.14, 0.12, crane);
  }
  for (const s of [-1, 1]) k.box(cx + s * 0.3, gH, (zf + zb) / 2, 0.09, 0.14, zf - zb + 0.12, crane, scale(crane, 0.9));
  k.box(cx, gH + 0.14, trolleyZ, 0.72, 0.12, 0.32, scale(crane, 0.9), DARK);
  k.box(cx + 0.46, gH - 0.24, trolleyZ, 0.2, 0.2, 0.22, WHITE, ROOF_GREY);
  k.box(cx + 0.46, gH - 0.16, trolleyZ + 0.113, 0.16, 0.09, 0.006, GLASS);
  const hy = overWagon ? 0.62 : 1.05;
  for (const sx of [-1, 1]) for (const s of [-1, 1]) k.box(cx + sx * 0.4, hy + 0.04, trolleyZ + s * 0.08, 0.008, gH + 0.14 - hy - 0.04, 0.008, DARK);
  k.box(cx, hy, trolleyZ, 1.22, 0.04, 0.26, YELLOW);
  container(k, cx, hy - 0.26, trolleyZ, 1.25, box());
  k.tagged(Vis.Always, () => k.glowBox(cx - legX, gH, zf, 0.05, 0.05, 0.05, hex(0xf2a93b), BEACON, hex(0xf2a93b)));

  // the reach stacker in the lane with a twenty held up, a lorry waiting, the gate booth
  k.within(1.35, 0.6, Math.PI, () => {
    for (const sx of [-1, 1]) for (const s of [-1, 1]) k.box(sx * 0.16, 0, s * 0.2, 0.06, 0.12, 0.12, DARK);
    k.box(0, 0.05, 0, 0.3, 0.12, 0.6, YELLOW);
    k.box(0, 0.06, -0.3, 0.3, 0.2, 0.1, scale(YELLOW, 0.8));
    k.box(0.08, 0.17, 0.06, 0.13, 0.16, 0.16, YELLOW, DARK);
    k.box(0.08, 0.23, 0.142, 0.11, 0.08, 0.006, GLASS);
    k.bar([-0.05, 0.26, -0.22], [-0.05, 0.78, 0.44], 0.04, scale(YELLOW, 0.9));
    k.box(0, 0.74, 0.5, 0.62, 0.04, 0.18, DARK);
    container(k, 0, 0.48, 0.5, 0.6, box());
  });
  lorry(k, -2.0, 0.55, true, hex(CARS[b.seed % CARS.length]));
  k.box(W / 2 - 0.3, 0, 0.7, 0.3, 0.32, 0.3, WHITE, ROOF_GREY);
  win(k, b, r, W / 2 - 0.3, 0.14, 0.85, 0.18, 0.1, 1);
  k.box(W / 2 - 0.3, 0.18, 0.3, 0.035, 0.035, 0.6, RED);
  mast(k, -W / 2 + 0.15, -0.1, 1.7);
  mast(k, W / 2 - 0.15, -1.0, 1.7);
};

