/** A long sorting shed with a dock and canopy along the track, a clock over the middle, red vans in the back yard. */
const mailDepot: Draw = (k, W, D, b, r) => {
  const F = D / 2, sz = F - 0.27;
  const wall = r() < 0.55 ? pick(r, BRICK) : pick(r, STONE), red = hex(0xd7261e), roof = ROOF_GREY, gold = hex(0xf2c14e);
  k.box(0, 0, 0, W - 0.06, 0.01, D - 0.06, hex(0xb8b2a6));
  siding(k, -W / 2 + 0.08, W / 2 - 0.08, sz, -1);

  // the shed, banded in red under the eaves, a ridge vent on the roof
  const front = 0.08, back = -0.72, sw = W - 0.3, sd = front - back, cz = (front + back) / 2, sh = 0.7;
  k.box(0, 0, cz, sw, sh, sd, wall);
  k.box(0, 0, cz, sw + 0.014, 0.06, sd + 0.014, scale(wall, 0.75));
  k.box(0, 0.62, cz, sw + 0.016, 0.07, sd + 0.016, red);
  k.gable(0, sh, cz, sw + 0.06, 0.16, sd + 0.06, roof, wall);
  k.box(0, sh + 0.13, cz, sw * 0.6, 0.05, 0.1, METAL);
  for (const x of [-sw / 3, sw / 3]) k.cyl(x, sh + 0.06, cz - 0.15, 0.04, 0.12, METAL, 6);

  // the dock: a platform to the track's edge, roller doors along it, a canopy over to the line on posts
  const edge = sz - 0.27;
  k.box(0, 0, (front + edge) / 2, sw, 0.15, edge - front, CONCRETE);
  k.box(0, 0.15, edge - 0.03, sw, 0.004, 0.04, gold);
  const doors = 4;
  for (let i = 0; i < doors; i++) {
    const dx = -sw / 2 + (sw / doors) * (i + 0.5);
    k.box(dx, 0.15, front + 0.006, 0.44, 0.34, 0.012, hex(0x8a9096));
    k.box(dx, 0.49, front + 0.02, 0.48, 0.04, 0.04, DARK);
  }
  const cy = 0.55, cz1 = edge + 0.06;
  k.box(0, cy, (front + cz1) / 2, sw, 0.04, cz1 - front, red, scale(roof, 1.05));
  for (let i = 0; i < 5; i++) k.box(-sw / 2 + 0.1 + (i * (sw - 0.2)) / 4, 0.15, edge - 0.08, 0.03, cy - 0.15, 0.03, DARK);
  k.glowBox(0, cy - 0.015, (front + edge) / 2, sw - 0.3, 0.015, 0.04, LAMP_DAY, LAMP, SHOP_GLOW);
  // mail cages and sacks on the dock
  for (let i = 0; i < 7; i++) {
    if (r() < 0.35) continue;
    const x = -sw / 2 + 0.25 + (i * (sw - 0.5)) / 6, z = front + 0.12 + r() * 0.1;
    if (r() < 0.5) k.box(x, 0.15, z, 0.1, 0.15, 0.1, METAL, scale(METAL, 0.8));
    else k.box(x, 0.15, z, 0.12, 0.07, 0.09, hex(0xb8a88a));
  }

  // the clock over the middle of the front, on a pediment above the canopy
  k.box(0, 0.6, front - 0.05, 0.6, 0.38, 0.12, wall);
  k.gable(0, 0.98, front - 0.05, 0.66, 0.1, 0.16, roof, wall);
  clock(k, 0, 0.8, front + 0.01, 0.1);

  // the back: the sorting hall's lit windows, a door, and red vans parked in the yard
  row(k, b, r, 0, 0.25, back, sw - 0.8, 0.2, 7, 3);
  k.box(sw / 2 - 0.25, 0, back - 0.006, 0.14, 0.26, 0.012, scale(wall, 0.6));
  k.glowBox(sw / 2 - 0.25, 0.3, back - 0.03, 0.05, 0.03, 0.04, LAMP_DAY, LAMP, WARM_GLOW);
  const vz = back - 0.16, nVans = 3 + (r() < 0.5 ? 1 : 0);
  for (let i = 0; i < nVans; i++) {
    const x = -1.4 + i * 0.75;
    k.box(x - 0.03, 0.04, vz, 0.32, 0.2, 0.2, red);
    k.box(x + 0.16, 0.04, vz, 0.1, 0.14, 0.2, red);
    k.box(x + 0.2, 0.11, vz, 0.012, 0.06, 0.16, GLASS);
    for (const sx of [-1, 1]) for (const s of [-1, 1]) k.box(x + sx * 0.12, 0, vz + s * 0.09, 0.08, 0.06, 0.03, DARK);
    k.detail(() => { for (const s of [-1, 1]) k.box(x - 0.03, 0.16, vz + s * 0.103, 0.3, 0.025, 0.006, gold); });
  }

  // the mail vans on the siding
  vanWagon(k, -0.9, sz, red, roof, gold);
  if (r() < 0.7) vanWagon(k, 0.15, sz, red, roof, gold);
};

// ---- ballast pit -------------------------------------------------------------------------------

/** A stepped pit dug into the hill with a digger on its floor, a screening plant, ballast heaps and a hopper over the line. */
const ballastPit: Draw = (k, W, D, b, r) => {
  const F = D / 2, sz = F - 0.32;
  const stone = hex(0x9c978e), earth = hex(0x8f7a5e), rock = hex(0xa8a092), frame = pick(r, [0x3f4a52, 0x6b4a3a, 0xf2b33b]);
  k.box(0, 0, 0, W - 0.06, 0.01, D - 0.06, hex(0xb0a690));
  siding(k, -W / 2 + 0.08, W / 2 - 0.08, sz, 1);

  // the pit: a bank round it and two benches stepping down to a wet floor
  const px0 = -1.85, px1 = 0.95, pz0 = -1.85, pz1 = 0.35, t = 0.18;
  const steps: [number, RGB, RGB][] = [[0.26, earth, hex(0x7f8a52)], [0.17, rock, scale(rock, 1.05)], [0.08, scale(rock, 0.9), scale(rock, 0.95)]];
  steps.forEach(([h, side, top], i) => {
    const x0 = px0 + i * t, x1 = px1 - i * t, z0 = pz0 + i * t, z1 = pz1 - i * t;
    k.box((x0 + x1) / 2, 0, z0 + t / 2, x1 - x0, h, t, side, top);
    k.box((x0 + x1) / 2, 0, z1 - t / 2, x1 - x0, h, t, side, top);
    for (const x of [x0 + t / 2, x1 - t / 2]) k.box(x, 0, (z0 + z1) / 2, t, h, z1 - z0 - 2 * t, side, top);
  });
  const fx0 = px0 + 3 * t, fx1 = px1 - 3 * t, fz0 = pz0 + 3 * t, fz1 = pz1 - 3 * t;
  k.box((fx0 + fx1) / 2, 0, (fz0 + fz1) / 2, fx1 - fx0, 0.014, fz1 - fz0, hex(0x8a8478));
  k.disc(fx0 + 0.4, 0.014, fz0 + 0.3, 0.26, WATER, 10, 0.18);
  k.wedge(0.55, 0, (pz1 - 0.6 + pz1) / 2, 0.24, 0.26, 0.6, scale(earth, 1.05));

  // the digger on the floor, its boom out to the face
  k.within(-0.5 + r() * 0.4, -0.9, 2.4 + r() * 0.8, () => {
    for (const s of [-1, 1]) k.box(s * 0.1, 0.014, 0, 0.07, 0.07, 0.32, DARK);
    k.box(0, 0.084, -0.03, 0.22, 0.1, 0.24, YELLOW);
    k.box(0.06, 0.184, 0.04, 0.09, 0.1, 0.09, YELLOW, DARK);
    k.bar([-0.03, 0.15, 0.08], [-0.03, 0.38, 0.32], 0.025, YELLOW);
    k.bar([-0.03, 0.38, 0.32], [-0.03, 0.1, 0.46], 0.02, YELLOW);
    k.box(-0.03, 0.03, 0.47, 0.12, 0.08, 0.08, STEEL);
  });

  // the screening plant beside the pit: legs, the screen house, a feed hopper and its own heap under it
  const sx = 1.45, szp = -0.7;
  for (const a of [-1, 1]) for (const c of [-1, 1]) k.box(sx + a * 0.22, 0, szp + c * 0.17, 0.05, 0.4, 0.05, frame);
  k.box(sx, 0.4, szp, 0.55, 0.28, 0.42, scale(frame, 1.1), ROOF_GREY);
  k.box(sx - 0.08, 0.68, szp - 0.05, 0.3, 0.12, 0.3, STEEL, stone);
  k.cone(sx, 0, szp, 0.3, 0.3, stone, 8);
  win(k, b, r, sx + 0.275, 0.48, szp, 0.14, 0.1, 0);
  conveyor(k, [sx - 0.3, 0.3, -1.6], [sx - 0.1, 0.72, szp - 0.2], 0.035, DARK, frame);

  // the heaps of graded ballast along the front, a stacker over one
  k.cone(-1.3, 0, 0.9, 0.42, 0.3, stone, 9);
  k.cone(-0.45, 0, 0.95, 0.36, 0.26, scale(stone, 1.06), 8);
  k.cone(1.5, 0, 0.5, 0.38, 0.3, scale(stone, 0.95), 8);
  k.bar([sx, 0.5, szp + 0.22], [1.5, 0.42, 0.42], 0.025, DARK);

  // the hopper over the track on its legs, the belt up to it from the plant, and the ballast wagons
  const bx = 0.3, by = 0.75, bh = 0.42;
  for (const a of [-1, 1]) for (const c of [-1, 1]) k.box(bx + a * 0.28, 0, sz + c * 0.275, 0.06, by, 0.06, frame);
  for (const c of [-1, 1]) k.bar([bx - 0.28, 0.1, sz + c * 0.275], [bx + 0.28, by - 0.05, sz + c * 0.275], 0.013, frame);
  k.box(bx, by, sz, 0.58, bh, 0.58, STEEL, stone);
  k.hip(bx, by, sz, 0.58, -0.18, 0.58, scale(STEEL, 0.85));
  k.box(bx, by - 0.28, sz, 0.1, 0.12, 0.1, DARK);
  conveyor(k, [sx - 0.1, 0.62, szp + 0.2], [bx + 0.1, by + bh + 0.04, sz - 0.12], 0.04, DARK, frame);
  const wag = pick(r, [0xf2b33b, 0x6d7176, 0x3f6f4a]);
  hopperWagon(k, bx, sz, wag, stone);
  hopperWagon(k, bx - 1.05, sz, wag, r() < 0.5 ? stone : null);

  // the heaps' bay walls, a dump truck on the pit floor, a loading shovel at the heaps
  for (const x of [-1.82, -0.87, -0.05]) k.box(x, 0, 0.92, 0.12, 0.22, 0.75, CONCRETE);
  const machine = (x: number, z: number, yaw: number, dumper: boolean) => k.within(x, z, yaw, () => {
    for (const sx of [-1, 1]) for (const s of [-1, 1]) k.box(sx * 0.11, 0.014, s * 0.12, 0.05, 0.09, 0.09, DARK);
    k.box(0, 0.06, 0, 0.2, 0.07, 0.4, YELLOW);
    if (dumper) {
      k.box(0, 0.13, 0.13, 0.2, 0.12, 0.12, YELLOW, DARK);
      k.box(0, 0.13, -0.07, 0.24, 0.12, 0.28, scale(YELLOW, 0.85));
      k.hip(0, 0.25, -0.07, 0.22, 0.06, 0.26, stone);
    } else {
      k.box(0, 0.13, -0.06, 0.15, 0.14, 0.14, YELLOW, DARK);
      for (const s of [-1, 1]) k.bar([s * 0.08, 0.14, 0.08], [s * 0.08, 0.2, 0.28], 0.015, YELLOW);
      k.box(0, 0.14, 0.31, 0.26, 0.09, 0.08, STEEL);
    }
  });
  machine(0.0, -0.5, Math.PI / 2, true);
  machine(0.85, 0.85, Math.PI / 2 + (r() - 0.5) * 0.6, false);

  // the site cabin and a floodlight
  k.box(1.55, 0, 1.15, 0.5, 0.24, 0.24, hex(0x6f9e6b), hex(0x8c8a84));
  win(k, b, r, 1.48, 0.08, 1.27, 0.18, 0.09, 1);
  mast(k, -1.9, 1.2, 1.1);
};

// ---- produce shed ------------------------------------------------------------------------------

/** A refrigerated packing shed of white panels with roller doors on its dock, pallets of crates, reefers on the roof and siding. */
const produceShed: Draw = (k, W, D, b, r) => {
  const F = D / 2, sz = F - 0.32;
  const panel = hex(0xeef0ee), seam = hex(0xd2d6d4), trim = pick(r, [0x3f9b4a, 0x2f7fb5, 0xe2412f, 0xf28c38]);
  const crate = hex(0xc49a62), pallet = hex(0xa88a5a);
  const produce = [0x5aa83a, 0xe2412f, 0xf28c38, 0xf2c14e, 0x8e5cc7, 0x9ccf5a];
  k.box(0, 0, 0, W - 0.06, 0.01, D - 0.06, hex(0xbab4a8));
  siding(k, -W / 2 + 0.08, W / 2 - 0.08, sz, 1);

  // the shed: white panels with their seams, a coloured parapet, a lit name band
  const sx0 = -W / 2 + 0.12, sx1 = W / 2 - 0.95, front = 0.42, back = -F + 0.15, sh = 0.75;
  const sw = sx1 - sx0, sd = front - back, cx = (sx0 + sx1) / 2, cz = (front + back) / 2;
  k.box(cx, 0, cz, sw, sh, sd, panel, hex(0xc9ccc9));
  for (const z of [front, back]) k.box(cx, sh, z, sw + 0.02, 0.05, 0.03, trim);
  for (const x of [sx0, sx1]) k.box(x, sh, cz, 0.03, 0.05, sd, trim);
  k.detail(() => {
    for (let x = sx0 + 0.32; x < sx1 - 0.1; x += 0.32) k.box(x, 0, back - 0.004, 0.012, sh, 0.008, seam);
    for (let z = back + 0.32; z < front - 0.1; z += 0.32) k.box(sx1 + 0.004, 0, z, 0.008, sh, 0.012, seam);
  });
  k.glowBox(cx, 0.63, front + 0.008, Math.min(1.6, sw * 0.6), 0.08, 0.012, mix(trim, WHITE, 0.5), SIGN, mix(trim, SHOP_GLOW, 0.5));

  // the dock: three roller doors with their seals, bumpers on the edge, a canopy on posts with lamps
  const edge = sz - 0.26;
  k.box(cx, 0, (front + edge) / 2, sw, 0.16, edge - front, CONCRETE);
  k.box(cx, 0.16, edge - 0.03, sw, 0.004, 0.04, YELLOW);
  for (let i = 0; i < 3; i++) {
    const dx = cx + (i - 1) * (sw / 3);
    k.box(dx, 0.16, front + 0.006, 0.48, 0.36, 0.012, hex(0xd9dcdf));
    k.detail(() => { for (let j = 1; j < 4; j++) k.box(dx, 0.16 + j * 0.09, front + 0.013, 0.48, 0.008, 0.004, seam); });
    for (const s of [-1, 1]) k.box(dx + s * 0.26, 0.16, front + 0.02, 0.04, 0.38, 0.04, DARK);
    k.box(dx, 0.52, front + 0.02, 0.56, 0.03, 0.04, DARK);
    for (const s of [-1, 1]) k.box(dx + s * 0.15, 0.05, edge + 0.005, 0.06, 0.08, 0.02, DARK);
  }
  const cy = 0.56;
  k.box(cx, cy, (front + edge + 0.02) / 2, sw, 0.04, edge + 0.02 - front, trim, scale(panel, 0.92));
  for (let i = 0; i < 4; i++) k.box(sx0 + 0.1 + (i * (sw - 0.2)) / 3, 0.16, edge - 0.08, 0.03, cy - 0.16, 0.03, METAL);
  k.glowBox(cx, cy - 0.015, (front + edge) / 2, sw - 0.3, 0.015, 0.04, LAMP_DAY, LAMP, SHOP_GLOW);

  // the office end's lit windows, and the condensers on the roof
  row(k, b, r, sx0 + 0.55, 0.32, back, 0.8, 0.18, 3, 3);
  win(k, b, r, sx0, 0.32, cz, 0.4, 0.18, 2);
  for (const x of [cx - sw / 4, cx + sw / 4]) {
    k.box(x, sh, cz - 0.1, 0.5, 0.14, 0.3, METAL);
    for (const s of [-1, 1]) k.disc(x + s * 0.12, sh + 0.14, cz - 0.1, 0.09, DARK, 10);
  }

  // the side yard: the reefer plant with its fans, pipes into the wall, pallets of crates
  const yx = (sx1 + W / 2) / 2;
  k.box(yx, 0, -1.0, 0.6, 0.4, 0.42, METAL, scale(METAL, 0.9));
  for (const s of [-1, 1]) k.face(yx + s * 0.14, 0.2, -1.0 + 0.212, 0.1, DARK, 10);
  for (const y of [0.25, 0.32]) k.bar([yx - 0.3, y, -1.05], [sx1, y, -1.05], 0.015, STEEL);
  const stack = (x: number, z: number, n: number) => {
    k.box(x, 0, z, 0.3, 0.04, 0.3, pallet);
    for (let j = 0; j < n; j++) k.box(x, 0.04 + j * 0.1, z, 0.28, 0.1, 0.28, scale(crate, 1 - j * 0.04), j === n - 1 ? pick(r, produce) : crate);
  };
  for (const [x, z] of [[yx - 0.18, -0.35], [yx + 0.18, -0.35], [yx - 0.18, 0.05], [yx + 0.18, 0.05], [yx, 0.5]] as [number, number][]) {
    if (r() < 0.2) continue;
    stack(x, z, 1 + Math.floor(r() * 3));
  }
  // crates on the dock, and a forklift among them
  for (let i = 0; i < 4; i++) {
    if (r() < 0.3) continue;
    const x = sx0 + 0.35 + i * ((sw - 0.7) / 3) + 0.25;
    k.box(x, 0.16, front + 0.22, 0.24, 0.035, 0.24, pallet);
    k.box(x, 0.195, front + 0.22, 0.22, 0.09 + r() * 0.1, 0.22, crate, pick(r, produce));
  }
  k.within(cx + 0.35, front + 0.25, Math.PI / 2, () => {
    k.box(0, 0.02, 0, 0.14, 0.1, 0.2, pick(r, [0xf28c38, 0xf2b33b, 0x3f9b4a]));
    k.box(0, 0.12, -0.05, 0.12, 0.004, 0.12, DARK);
    for (const s of [-1, 1]) k.box(s * 0.05, 0.12, -0.0, 0.01, 0.12, 0.01, DARK);
    for (const s of [-1, 1]) k.box(s * 0.045, 0.0, 0.12, 0.012, 0.22, 0.02, DARK);
    for (const s of [-1, 1]) k.box(s * 0.045, 0.02, 0.17, 0.02, 0.008, 0.1, METAL);
  });

  // the reefer vans on the siding, each with its unit at the end
  for (const wx of [-0.9, 0.15]) {
    vanWagon(k, wx, sz, WHITE, METAL, trim);
    k.box(wx + 0.41, 0.15, sz, 0.05, 0.22, 0.24, DARK);
  }
};

// ---- brewery -----------------------------------------------------------------------------------

/** A brick brewhouse with a louvred ridge vent, copper cowls through the roof and a tall chimney; barrels on the dock. */
const breweryRail: Draw = (k, W, D, b, r) => {
  const F = D / 2, sz = F - 0.32;
  const brick = pick(r, BRICK), roof = pick(r, [0x5a5f6b, 0x6b4a3a, 0x8a4a3a]), dressing = pick(r, STONE);
  const copper = hex(0xc8793e), verd = r() < 0.5 ? hex(0x6fae95) : copper, oak = hex(0x8a5a32);
  k.box(0, 0, 0, W - 0.06, 0.01, D - 0.06, hex(0xa8a196));
  siding(k, -W / 2 + 0.08, W / 2 - 0.08, sz, -1);

  // the brewhouse, two storeys of lit windows, a stone string course and a sign between
  const hx = -0.55, hz = -0.55, hw = 2.5, hd = 1.4, hh = 0.95, hf = hz + hd / 2;
  k.box(hx, 0, hz, hw, hh, hd, brick);
  k.box(hx, 0, hz, hw + 0.02, 0.08, hd + 0.02, scale(brick, 0.8));
  k.box(hx, 0.5, hz, hw + 0.016, 0.03, hd + 0.016, dressing);
  k.gable(hx, hh, hz, hw + 0.08, 0.38, hd + 0.08, roof, brick);
  row(k, b, r, hx, 0.17, hf, hw - 0.5, 0.22, 5, 1);
  row(k, b, r, hx, 0.6, hf, hw - 0.5, 0.24, 5, 1);
  row(k, b, r, hx, 0.6, hz - hd / 2, hw - 0.5, 0.24, 5, 3);
  k.box(hx, 0.4, hf + 0.006, 1.1, 0.08, 0.012, hex(0x2f4a3a));
  k.glowBox(hx, 0.415, hf + 0.016, 1.0, 0.05, 0.006, hex(0xf2d8a0), SIGN, WARM_GLOW);
  // the louvred lantern along the ridge, and the copper cowls through the roof
  k.box(hx - 0.35, hh + 0.28, hz, 0.7, 0.16, 0.24, hex(0xe8e2d4));
  k.detail(() => { for (const s of [-1, 1]) for (const y of [0.32, 0.37, 0.42]) k.box(hx - 0.35, hh + y, hz + s * 0.122, 0.66, 0.012, 0.006, DARK); });
  k.gable(hx - 0.35, hh + 0.44, hz, 0.78, 0.1, 0.32, roof, roof);
  for (const vx of [hx + 0.55, hx + 0.95]) {
    k.cyl(vx, hh + 0.1, hz + 0.18, 0.09, 0.42, copper, 8);
    k.dome(vx, hh + 0.52, hz + 0.18, 0.09, verd, 8, 3);
    k.cyl(vx, hh + 0.6, hz + 0.18, 0.02, 0.08, verd, 5);
  }

  // the boiler house and its tall chimney at the back corner
  const cx = 1.3, czc = -1.0;
  k.box(cx, 0, -0.45, 0.6, 0.5, 0.5, brick);
  k.gable(cx, 0.5, -0.45, 0.64, 0.18, 0.54, roof, brick, true);
  win(k, b, r, cx + 0.3, 0.2, -0.45, 0.16, 0.14, 0);
  k.box(cx, 0, czc, 0.36, 0.3, 0.36, scale(brick, 0.9), dressing);
  k.band(cx, czc, 0.3, 0.15, 2.05, 0.1, 8, brick);
  k.cyl(cx, 1.6, czc, 0.13, 0.05, dressing, 8);
  k.cyl(cx, 2.05, czc, 0.12, 0.07, scale(brick, 0.7), 8, COAL);

  // the dock along the track: barrels stacked on their sides, kegs, a jib crane at the edge
  const edge = sz - 0.26, dz = (hf + 0.02 + edge) / 2;
  k.box(0, 0, dz, W - 0.2, 0.15, edge - hf - 0.02, scale(brick, 0.85), hex(0xb8b0a0));
  const barrels = (x: number, z: number, base: number) => {
    for (let j = 0; j < base; j++) {
      const n = base - j;
      for (let i = 0; i < n; i++) {
        drum(k, x + (i - (n - 1) / 2) * 0.13, 0.15 + 0.06 + j * 0.105, z, 0.06, 0.13, scale(oak, 0.92 + r() * 0.16), 8, scale(oak, 0.75), true);
      }
    }
  };
  barrels(-1.35, dz - 0.05, 3 + Math.floor(r() * 2));
  barrels(0.15, dz + 0.02, 2 + Math.floor(r() * 2));
  for (let i = 0; i < 6; i++) k.cyl(0.85 + (i % 3) * 0.1, 0.15, dz - 0.08 + Math.floor(i / 3) * 0.11, 0.045, 0.1, METAL, 6, scale(METAL, 0.85));
  k.box(-0.55, 0.15, edge - 0.08, 0.04, 0.6, 0.04, DARK);
  k.bar([-0.55, 0.72, edge - 0.08], [-0.55, 0.68, edge + 0.2], 0.014, DARK);
  k.box(-0.55, 0.45, edge + 0.19, 0.005, 0.23, 0.005, DARK);
  for (const lx of [hx - 0.8, hx + 0.8]) k.glowBox(lx, 0.36, hf + 0.04, 0.05, 0.05, 0.05, LAMP_DAY, LAMP, WARM_GLOW);

  // a van of the brewery's own colours on the siding, and a flat of barrels
  vanWagon(k, 1.15, sz, pick(r, [0xe8dcc0, 0x2f4a3a, 0x6e2f2f]), roof, hex(0xc9a24a));
  flatWagon(k, 0.1, sz, 0.9, hex(0x5a5048));
  for (let i = 0; i < 3; i++) drum(k, 0.1 + (i - 1) * 0.26, 0.215, sz, 0.06, 0.13, oak, 8, scale(oak, 0.75), true);

};

