import { DIRS } from '../../world/tiles';
import { hashString } from '../../world/rng';
import { cellKind, cellName, landBorder, straitAt } from '../../world/macro';
import { DAYS_PER_YEAR } from '../../render/season';
import type { Sport, Team } from '../../world/stadiums';
import { SPAN, leagueFor, results, slotOf, table, type League } from '../leagues';
import { KINDS, KIND_INDEX, KIND_OF, MARKETS, rankOf, type EventKind, type KindSpec } from './kinds';
import { NEXT_WORLD } from '../../world/nextWorld';

/**
 * The events calendar (docs/events.html): what's on in a county on a day, worked out from the world's seed and
 * the day alone. Nothing is stored and nothing is synced, so every player online sees the same parade at the
 * same corner, and a county nobody has visited has its calendar all the same.
 *
 * The 40-day rule is kept by slots, not luck. Each kind has a period of at least MIN_GAP days and every county
 * its own offset for it; the kind can only happen in that county on its slot days, so it cannot come back
 * sooner than a period. A kind tied to the year (New Year's Eve) goes by a rotation of years instead, one in
 * eleven per county, which is 44 days. A title parade has a short window on each slot and goes on the first
 * evening in it after its club wins, so two windows' parades are still more than 40 days apart.
 *
 * On a county's slot day the kind goes ahead if its gate hash passes and the county could hold it (the cheap
 * test from the seed, kinds.ts `could`). One a county a day: when two land on the same day, the rarer goes
 * ahead and the other simply waits for its next slot. At most MAJORS major events in each BLOCK × BLOCK block
 * of counties a day, the rarest first.
 *
 * A motorcade crosses counties. Its routes are the pairs of megalopolises in a REGION × REGION region with a road
 * between them across the county lattice; each route has its day of a cycle, and two routes through the same
 * county are kept at least MIN_GAP days apart on it, so no county sees one sooner either.
 *
 * Whether the event then really happens is the stage's business (stage.ts): it looks for its place in the
 * generated county (a town big enough, a square, a stadium) and stays quiet if there is none.
 */

/** The fewest game days before a kind can come back to a county (the user's rule, Oct 2026). */
export const MIN_GAP = 40;
/** Counties a side of a block, for the cap on major events. */
export const BLOCK = 3;
/** Most major events in a block on one day. */
export const MAJORS = 2;
/** Counties a side of a region, for the routes of moving events. */
export const REGION = 9;
/** A route's furthest end, in counties (Chebyshev), and its nearest. */
const ROUTE_MAX = 4, ROUTE_MIN = 2;
/** The most counties a route may cross, so it is over by evening. */
const ROUTE_CELLS = 5;

/** One event: a kind, on a day, in a county (and, moving, along a route of counties). */
export interface Happening {
  id: string;
  kind: EventKind;
  day: number;
  /** Its county; a moving event's first. */
  cx: number; cz: number;
  /** Game hours (days × 24 + hour) it starts and ends. */
  start: number; end: number;
  /** A hash of its own, for its choices: the route through the streets, the cars, the colours. */
  h: number;
  /** A moving event's counties, in order, first to last. */
  route?: [number, number][];
  /** A parade's champions: their sport, league and club. */
  club?: { sport: Sport; league: string; season: number; place: string; team: Team };
  /** A market's place among the county's that hold one that day: 0 the biggest town's, 1 the next (venues.ts). */
  site?: number;
}

// ---- hashing -------------------------------------------------------------------------------------------

function mix(...v: number[]): number {
  let h = 0x9e3779b9;
  for (const x of v) {
    h = Math.imul(h ^ (x | 0), 0x85ebca6b);
    h = (h << 13) | (h >>> 19);
    h = Math.imul(h, 0xc2b2ae35);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 0x7feb352d);
  h ^= h >>> 15;
  return h >>> 0;
}
const u01 = (h: number): number => h / 4294967296;

let seedFor = '', sh = 0;
/** The seed's hash, as the macro layer takes it. */
export function seedHash(seed: string): number {
  if (seed !== seedFor) { seedFor = seed; sh = hashString(seed); clearCaches(); }
  return sh;
}

/** A kind's offset in a county: which of its period's days are its slots there. */
function offsetOf(s: number, cx: number, cz: number, k: EventKind): number { return mix(s, cx, cz, KIND_INDEX[k], 0x51); }

// ---- one county --------------------------------------------------------------------------------------------

const EMPTY = new Map<string, [number, number]>();
/** Season k's champions of a league, from the played-out scores alone (a game someone watched live counts only for them). */
const CHAMPS = new Map<string, number>();
function champion(L: League, k: number): number {
  const key = `${L.id}|${k}|${L.clubs.length}`;
  let c = CHAMPS.get(key);
  if (c === undefined) {
    if (CHAMPS.size > 4000) CHAMPS.clear();
    const t = table(L, results(L, k, Infinity, EMPTY), k);
    CHAMPS.set(key, (c = t[0]?.club ?? -1));
  }
  return c;
}

const SPORTS: Sport[] = ['soccer', 'football', 'baseball'];
/** A title won by this county's club in a season whose final table came in at the start of `day`, if any. */
function titleOn(s: number, cx: number, cz: number, day: number): Happening['club'] | null {
  for (const sport of SPORTS) {
    const { off, len } = SPAN[sport];
    const k = (day - off - len) / DAYS_PER_YEAR;
    if (!Number.isInteger(k)) continue;
    const L = leagueFor(s, sport, cx, cz);
    const slot = slotOf(L, cx, cz);
    if (slot < 0 || champion(L, k) !== slot) continue;
    const c = L.clubs[slot];
    return { sport, league: L.name, season: k, place: c.place, team: c.team };
  }
  return null;
}

/** Is `day` a slot day for kind k in this county (and, for a title, the evening it goes on)? The club, for a title. */
function onSlot(s: number, cx: number, cz: number, k: KindSpec, day: number): { ok: boolean; club?: Happening['club'] } {
  const c = k.cadence;
  const off = offsetOf(s, cx, cz, k.id);
  if (c.k === 'slot') return { ok: (day + (off % c.period)) % c.period === 0 && (!k.seasons || k.seasons.includes(((day % DAYS_PER_YEAR) + DAYS_PER_YEAR) % DAYS_PER_YEAR)) };
  if (c.k === 'rotation') {
    if (((day % DAYS_PER_YEAR) + DAYS_PER_YEAR) % DAYS_PER_YEAR !== c.season) return { ok: false };
    const year = Math.floor(day / DAYS_PER_YEAR);
    return { ok: (year + (off % c.years)) % c.years === 0 };
  }
  if (c.k === 'title') {
    // in the window, and the first day in it with a title to celebrate
    const at = (day + (off % c.period)) % c.period;
    if (at >= c.win) return { ok: false };
    const club = titleOn(s, cx, cz, day);
    if (!club) return { ok: false };
    for (let d = day - at; d < day; d++) if (titleOn(s, cx, cz, d)) return { ok: false };
    return { ok: true, club };
  }
  return { ok: false };
}

/** The game hour a kind starts on its day in a county. */
function startHour(k: KindSpec, h: number): number {
  const [a, b] = k.hours;
  // to the quarter hour
  return a + Math.floor(u01(mix(h, 7)) * ((b - a) * 4 + 1)) / 4;
}

/** What one county would hold on a day before the block's cap: the rarest kind whose slot it is and whose gate passes. */
function countyPick(s: number, cx: number, cz: number, day: number): Happening | null {
  let best: Happening | null = null, bestP = -1;
  for (const k of KINDS) {
    // (could first: asking a sea county for its league would enrol it in one, and change the champions)
    if (k.cadence.k === 'route' || !k.could(s, cx, cz)) continue;
    const slot = onSlot(s, cx, cz, k, day);
    if (!slot.ok) continue;
    const h = mix(s, cx, cz, KIND_INDEX[k.id], day);
    if (u01(mix(h, 3)) >= k.gate) continue;
    const P = rankOf(k, DAYS_PER_YEAR);
    if (P < bestP || (P === bestP && best && h >= best.h)) continue;
    const start = day * 24 + startHour(k, h);
    best = { id: `${k.id}@${cx},${cz}#${day}`, kind: k.id, day, cx, cz, start, end: start + k.dur, h, ...(slot.club ? { club: slot.club } : {}) };
    bestP = P;
  }
  return best;
}

// ---- the block's cap -------------------------------------------------------------------------------------------

const BLOCKS = new Map<string, Happening[]>();
/** Everything on in a block of counties on a day, after the cap on major events. */
export function blockDay(seed: string, bx: number, bz: number, day: number): Happening[] {
  const s = seedHash(seed);
  const key = `${bx},${bz}#${day}`;
  let list = BLOCKS.get(key);
  if (list) return list;
  if (BLOCKS.size > 20000) BLOCKS.clear();
  const picks: Happening[] = [];
  for (let dz = 0; dz < BLOCK; dz++) for (let dx = 0; dx < BLOCK; dx++) {
    const p = countyPick(s, bx * BLOCK + dx, bz * BLOCK + dz, day);
    if (p) picks.push(p);
  }
  const P = (h: Happening) => rankOf(KIND_OF[h.kind], DAYS_PER_YEAR);
  const majors = picks.filter((h) => KIND_OF[h.kind].major).sort((a, b) => P(b) - P(a) || a.h - b.h).slice(0, MAJORS);
  list = picks.filter((h) => !KIND_OF[h.kind].major || majors.includes(h));
  BLOCKS.set(key, list);
  return list;
}

const fdiv = (a: number, b: number): number => Math.floor(a / b);

/** What's on in one county on a day (not counting a motorcade passing through). */
export function countyDay(seed: string, cx: number, cz: number, day: number): Happening | null {
  return blockDay(seed, fdiv(cx, BLOCK), fdiv(cz, BLOCK), day).find((h) => h.cx === cx && h.cz === cz) ?? null;
}

// ---- routes ----------------------------------------------------------------------------------------------------

interface Route { cells: [number, number][]; slot: number }
const ROUTES = new Map<string, Route[]>();

/** The first steps of a road from one county to another over land or a causeway, inside the region: the counties in order. */
function lattice(s: number, ax: number, az: number, bx: number, bz: number, rx0: number, rz0: number): [number, number][] | null {
  const key = (x: number, z: number) => (x - rx0) * REGION + (z - rz0);
  const back = new Map<number, number>([[key(ax, az), -1]]);
  const open: [number, number][] = [[ax, az]];
  for (let h = 0; h < open.length; h++) {
    const [cx, cz] = open[h];
    if (cx === bx && cz === bz) break;
    for (let d = 0; d < 4; d++) {
      const nx = cx + DIRS[d][0], nz = cz + DIRS[d][1];
      if (nx < rx0 || nz < rz0 || nx >= rx0 + REGION || nz >= rz0 + REGION || back.has(key(nx, nz))) continue;
      if (cellKind(s, nx, nz) === 'sea' || !(landBorder(s, cx, cz, d) || straitAt(s, cx, cz, d) >= 0)) continue;
      back.set(key(nx, nz), key(cx, cz));
      open.push([nx, nz]);
    }
  }
  if (!back.has(key(bx, bz))) return null;
  const out: [number, number][] = [];
  for (let k = key(bx, bz); k >= 0; k = back.get(k)!) out.push([rx0 + Math.floor(k / REGION), rz0 + (k % REGION)]);
  return out.reverse();
}

/** A region's routes for a moving kind, each with its day of the cycle, no two through a county within MIN_GAP days of each other. */
export function routesOf(seed: string, k: KindSpec, rx: number, rz: number): Route[] {
  const s = seedHash(seed);
  const key = `${k.id}|${rx},${rz}`;
  let list = ROUTES.get(key);
  if (list) return list;
  if (ROUTES.size > 2000) ROUTES.clear();
  const period = (k.cadence as { period: number }).period;
  const rx0 = rx * REGION, rz0 = rz * REGION;
  const ends: [number, number][] = [];
  for (let z = rz0; z < rz0 + REGION; z++) for (let x = rx0; x < rx0 + REGION; x++) if (k.could(s, x, z)) ends.push([x, z]);
  const cands: { cells: [number, number][]; h: number }[] = [];
  for (let i = 0; i < ends.length; i++) for (let j = i + 1; j < ends.length; j++) {
    const [ax, az] = ends[i], [bx, bz] = ends[j];
    const far = Math.max(Math.abs(ax - bx), Math.abs(az - bz));
    if (far < ROUTE_MIN || far > ROUTE_MAX) continue;
    const cells = lattice(s, ax, az, bx, bz, rx0, rz0);
    if (!cells || cells.length > ROUTE_CELLS) continue;
    cands.push({ cells, h: mix(s, ax, az, bx, bz, KIND_INDEX[k.id]) });
  }
  cands.sort((a, b) => a.h - b.h);
  list = [];
  const ring = (a: number, b: number) => { const d = Math.abs(a - b) % period; return Math.min(d, period - d); };
  for (const c of cands) {
    const shares = list.filter((r) => r.cells.some(([x, z]) => c.cells.some(([u, v]) => u === x && v === z)));
    for (let t = 0; t < period; t++) {
      const slot = (c.h + t) % period;
      if (shares.every((r) => ring(r.slot, slot) >= MIN_GAP)) { list.push({ cells: c.cells, slot }); break; }
    }
  }
  ROUTES.set(key, list);
  return list;
}

/** The moving events of a region on a day. */
export function regionDay(seed: string, rx: number, rz: number, day: number): Happening[] {
  const s = seedHash(seed);
  const out: Happening[] = [];
  for (const k of KINDS) {
    if (k.cadence.k !== 'route') continue;
    const period = k.cadence.period;
    const at = ((day % period) + period) % period;
    for (const r of routesOf(seed, k, rx, rz)) {
      if (r.slot !== at) continue;
      const h = mix(s, r.cells[0][0], r.cells[0][1], KIND_INDEX[k.id], day);
      if (u01(mix(h, 3)) >= k.gate) continue;
      // which way it runs, this time
      const cells = mix(h, 11) & 1 ? r.cells.slice().reverse() : r.cells.slice();
      const start = day * 24 + startHour(k, h);
      out.push({ id: `${k.id}@${cells[0][0]},${cells[0][1]}#${day}`, kind: k.id, day, cx: cells[0][0], cz: cells[0][1], start, end: start + routeHours(cells, k), h, route: cells });
    }
  }
  return out;
}

/** Game hours a moving event takes over its counties, and an hour parked at the end. */
function routeHours(cells: [number, number][], k?: KindSpec): number { return 1 + cells.length * (k?.perCounty ?? MOTORCADE_HOURS); }
/** Game hours a motorcade spends in each county it crosses: about four tiles a second on a county's roads. */
export const MOTORCADE_HOURS = 2.4;

// ---- the markets ------------------------------------------------------------------------------------------------------

/** Most markets a county holds on one day (its towns that keep one, biggest first: venues.ts marketPlace). */
const MARKET_SITES = 2;

/**
 * The markets of a county on a day (0.7.0, NEXT_WORLD): a farmers' market every Saturday morning but in winter, a
 * Christmas market all through every winter's day. They come round on a week or a season, not on the rare events'
 * slots, so they keep no 40-day gap and take nothing from the calendar above: nothing in KINDS knows of them. Which
 * towns keep one, and where in them, is the world's (venues.ts); here every county with towns has the day.
 */
export function marketsOn(seed: string, cx: number, cz: number, day: number): Happening[] {
  if (!NEXT_WORLD) return [];
  const s = seedHash(seed);
  const out: Happening[] = [];
  const dow = ((day % 7) + 7) % 7, season = ((day % DAYS_PER_YEAR) + DAYS_PER_YEAR) % DAYS_PER_YEAR;
  for (const k of MARKETS) {
    const c = k.cadence;
    if (c.k !== 'market' || !k.could(s, cx, cz)) continue;
    if (c.weekday !== undefined && (dow !== c.weekday || season === 3)) continue;
    if (c.season !== undefined && season !== c.season) continue;
    for (let site = 0; site < MARKET_SITES; site++) {
      const h = mix(s, cx, cz, 0x4d4b + MARKETS.indexOf(k), day, site);
      const start = day * 24 + startHour(k, h);
      out.push({ id: `${k.id}@${cx},${cz}#${day}.${site}`, kind: k.id, day, cx, cz, start, end: start + k.dur, h, site });
    }
  }
  return out;
}

/** Every market on near a county: the counties within `r` of (cx, cz), days `d0` to `d1`. */
export function marketsNear(seed: string, cx: number, cz: number, r: number, d0: number, d1: number): Happening[] {
  const out: Happening[] = [];
  if (!NEXT_WORLD) return out;
  for (let d = d0; d <= d1; d++) for (let z = cz - r; z <= cz + r; z++) for (let x = cx - r; x <= cx + r; x++) out.push(...marketsOn(seed, x, z, d));
  return out;
}

// ---- asking ------------------------------------------------------------------------------------------------------

/**
 * Everything on, or to come, near a county: the counties within `r` of (cx, cz), and the moving events whose
 * route passes within `r`, from day `d0` to day `d1`.
 */
export function eventsNear(seed: string, cx: number, cz: number, r: number, d0: number, d1: number): Happening[] {
  const out: Happening[] = [];
  const bx0 = fdiv(cx - r, BLOCK), bx1 = fdiv(cx + r, BLOCK), bz0 = fdiv(cz - r, BLOCK), bz1 = fdiv(cz + r, BLOCK);
  const rx0 = fdiv(cx - r, REGION), rx1 = fdiv(cx + r, REGION), rz0 = fdiv(cz - r, REGION), rz1 = fdiv(cz + r, REGION);
  for (let d = d0; d <= d1; d++) {
    for (let bz = bz0; bz <= bz1; bz++) for (let bx = bx0; bx <= bx1; bx++) {
      for (const h of blockDay(seed, bx, bz, d)) if (Math.abs(h.cx - cx) <= r && Math.abs(h.cz - cz) <= r) out.push(h);
    }
    for (let rz = rz0; rz <= rz1; rz++) for (let rx = rx0; rx <= rx1; rx++) {
      for (const h of regionDay(seed, rx, rz, d)) if (h.route!.some(([x, z]) => Math.abs(x - cx) <= r && Math.abs(z - cz) <= r)) out.push(h);
    }
  }
  return out;
}

/** A county's name as its people would say it, for the log: "Bramblereach". */
export function countyName(seed: string, cx: number, cz: number): string {
  const s = seedHash(seed);
  return cellName(s, cx, cz, cellKind(s, cx, cz));
}

function clearCaches(): void { BLOCKS.clear(); ROUTES.clear(); CHAMPS.clear(); }
