/**
 * A motor-racing circuit's model (world/circuits.ts has the plan it is drawn to): the asphalt and its
 * banking, the kerbs and the gravel, the walls and the catch fence, the chequered line and the painted
 * grid, the pit lane and its building, the grandstands, the gantry over the line and the gate. The crowd,
 * the cars, the lights and the trophy are live, and are drawn by game/circuits.ts.
 */
import { hex, scale, type RGB } from '../../world/biomes';
import type { CircuitKind } from '../../world/tiles';
import {
  DS, along, bankLift, circuitPlan, designOf, inOBox, standRows, yawFacing, zoneAt,
  type CircuitPlan, type Stand,
} from '../../world/circuits';
import { DARK, GLASS_LIGHT, METAL, WHITE, pick, type Draw, type Kit, type P3 } from './kit';

const ASPHALT = hex(0x45494e), ASPHALT_B = hex(0x4c5056), CONCRETE = hex(0xa3a49f), OLD_CONCRETE = hex(0xc4bdae);
const KERB_RED = hex(0xd8392b), GRAVEL = hex(0xd9c79a), TYRE = hex(0x26282b), SAFER = hex(0x2f5fb5);
const GOLD = hex(0xd9a441), SILVER = hex(0xc8ccd0), BRONZE = hex(0xb07a45);

/** How each design dresses: stand seats, stand body, roofs, the pit building and its trim. */
const DRESS: Record<ReturnType<typeof designOf>, { seats: number[]; body: RGB; roof: RGB; pit: RGB; trim: RGB; track: RGB }> = {
  speedway: { seats: [0xd8392b, 0xf4f2ec, 0x2f5fb5, 0xf2c14e], body: hex(0x9fa3a8), roof: hex(0xe7e9ea), pit: hex(0xeceae4), trim: hex(0xd8392b), track: ASPHALT },
  bullring: { seats: [0xf2c14e, 0x2f5fb5, 0xe2412f], body: hex(0x8f959b), roof: hex(0x2f3a48), pit: hex(0xdad6cc), trim: hex(0xf2c14e), track: ASPHALT_B },
  grandprix: { seats: [0xe2412f, 0x3f9b4a, 0xf2a93b, 0x2bb3a3, 0x8e5cc7], body: hex(0xb4b8bc), roof: hex(0xf4f2ec), pit: hex(0xf1f0ea), trim: hex(0x2bb3a3), track: ASPHALT },
  heritage: { seats: [0x2f5a3a, 0x3d6b48, 0xe8dcc0], body: hex(0x6b5a45), roof: hex(0x2f5a3a), pit: hex(0xeee4cc), trim: hex(0x2f5a3a), track: OLD_CONCRETE },
};

/** A point `u` right of the centreline at point i, lifted `y` above the track surface there. */
function P(p: CircuitPlan, i: number, u: number, y: number, surface = true): P3 {
  const j = ((i % p.n) + p.n) % p.n;
  const lift = surface ? bankLift(p, p.bank[j], Math.max(-p.half, Math.min(p.half, u))) : 0;
  return [p.px[j] + p.tz[j] * u, lift + y, p.pz[j] - p.tx[j] * u];
}

/** A flat strip across the track from u0 to u1 between points i and i+1, `y` over the surface. */
function strip(k: Kit, p: CircuitPlan, i: number, u0: number, u1: number, y: number, col: RGB, surface = true): void {
  const a = P(p, i, u0, y, surface), b = P(p, i, u1, y, surface), c = P(p, i + 1, u1, y, surface), d = P(p, i + 1, u0, y, surface);
  k.quad(a, b, c, d, col, [(a[0] + c[0]) / 2, Math.min(a[1], c[1]) - 1, (a[2] + c[2]) / 2]);
}

/** Draw in an OBox's own frame: (cx, cz) is its centre there, x along its length and +z to its front. */
function inBox(k: Kit, o: { x: number; z: number; a: number }, draw: (cx: number, cz: number) => void): void {
  const c = Math.cos(o.a), s = Math.sin(o.a);
  k.turned(o.a, () => draw(o.x * c - o.z * s, o.x * s + o.z * c));
}

/** Is the wall open here: the gap the entrance lane comes through? */
const atGate = (p: CircuitPlan, x: number, z: number) => Math.abs(x - p.gateX) < 1.5 && z > p.gateZ - p.half - 1.2;

function track(k: Kit, p: CircuitPlan): void {
  const d = DRESS[p.design], h = p.half, spec = p.spec;
  const lanes = [-h, -h / 2, 0, h / 2, h];
  for (let i = 0; i < p.n; i++) {
    // the surface in four strips across, so the banking bends it
    for (let l = 0; l < 4; l++) strip(k, p, i, lanes[l], lanes[l + 1], 0.012, l % 2 ? d.track : scale(d.track, 0.97));
    // the white lines along both edges
    strip(k, p, i, -h + 0.06, -h + 0.13, 0.016, WHITE);
    strip(k, p, i, h - 0.13, h - 0.06, 0.016, WHITE);
    // an oval's apron inside, with its line; a road circuit's kerbs on the corners
    if (p.outer) {
      strip(k, p, i, -h - 0.9, -h, 0.01, CONCRETE, false);
      if (spec.bank > 0.3) strip(k, p, i, -h + 0.18, -h + 0.26, 0.016, hex(0xf2c14e));
    } else if (p.corner[i] > 0.45) {
      const red = Math.floor(i / 1) % 2 === 0 ? KERB_RED : WHITE;
      strip(k, p, i, h, h + 0.32, 0.02, red, false);
      strip(k, p, i, -h - 0.32, -h, 0.02, red, false);
      // gravel on the outside of the corner, where a car runs wide
      const out = p.curv[i] > 0 ? -1 : 1;
      const [a, b] = out > 0 ? [h + 0.34, h + 1.5] : [-h - 1.5, -h - 0.34];
      const mid = P(p, i, (a + b) / 2, 0, false);
      if (zoneAt(p, mid[0], mid[2]) === 0) strip(k, p, i, a, b, 0.008, GRAVEL, false);
    }
  }
  // the chequered line
  const cells = 10, w = (2 * h) / cells;
  for (let c = 0; c < cells; c++) {
    for (let r = 0; r < 2; r++) {
      const u0 = -h + c * w, u1 = u0 + w;
      const col = (c + r) % 2 ? DARK : WHITE;
      const s0 = r * 0.3 - 0.3, s1 = s0 + 0.3;
      const pt = (s: number, u: number): P3 => {
        const f = s / DS, i = Math.floor(f), t = f - i;
        const A = P(p, i, u, 0.018), B = P(p, i + 1, u, 0.018);
        return [A[0] + (B[0] - A[0]) * t, A[1] + (B[1] - A[1]) * t, A[2] + (B[2] - A[2]) * t];
      };
      const a = pt(s0, u0), b = pt(s0, u1), cc = pt(s1, u1), dd = pt(s1, u0);
      k.quad(a, b, cc, dd, col, [a[0], a[1] - 1, a[2]]);
    }
  }
  // the grid: a white bracket at every slot
  for (const g of p.grid) {
    const fx = Math.sin(g.heading), fz = Math.cos(g.heading), rx = fz, rz = -fx;
    const y = bankLift(p, p.bank[Math.floor(g.s / DS) % p.n], g.u) + 0.018;
    const at = (f: number, r: number): P3 => [g.x + fx * f + rx * r, y, g.z + fz * f + rz * r];
    k.quad(at(0.62, -0.42), at(0.62, 0.42), at(0.52, 0.42), at(0.52, -0.42), WHITE, [g.x, y - 1, g.z]);
    k.quad(at(0.62, -0.42), at(0.62, -0.34), at(0.1, -0.34), at(0.1, -0.42), WHITE, [g.x, y - 1, g.z]);
  }
}

/** The wall round the outside, the SAFER stripe on its face and the catch fence over it. */
function walls(k: Kit, p: CircuitPlan): void {
  if (!p.spec.wall) return;
  const h = p.half, heritage = p.design === 'heritage';
  const face = heritage ? hex(0xd8d2c4) : WHITE;
  const u0 = h + 0.1, u1 = h + 0.45;
  for (let i = 0; i < p.n; i++) {
    const m = P(p, i, u0, 0, false);
    if (atGate(p, m[0], m[2]) || atGate(p, P(p, i + 1, u0, 0, false)[0], P(p, i + 1, u0, 0, false)[2])) continue;
    const b0 = p.bank[i], b1 = p.bank[(i + 1) % p.n];
    const top = 0.34;
    const q = (j: number, u: number, y: number): P3 => { const r = P(p, j, u, 0, false); return [r[0], y, r[2]]; };
    const inner: P3 = [...q(i, (u0 + u1) / 2, b0 / 2)] as P3;
    k.quad(q(i, u0, b0), q(i + 1, u0, b1), q(i + 1, u0, b1 + top), q(i, u0, b0 + top), face, inner);
    k.quad(q(i, u0, b0 + top), q(i + 1, u0, b1 + top), q(i + 1, u1, b1 + top), q(i, u1, b0 + top), scale(face, 0.9), inner);
    k.quad(q(i, u1, 0), q(i + 1, u1, 0), q(i + 1, u1, b1 + top), q(i, u1, b0 + top), scale(face, 0.82), inner);
    if (!heritage) k.quad(q(i, u0 - 0.004, b0 + 0.1), q(i + 1, u0 - 0.004, b1 + 0.1), q(i + 1, u0 - 0.004, b1 + 0.17), q(i, u0 - 0.004, b0 + 0.17), SAFER, inner);
    // the catch fence: posts every two tiles and two rails between them
    if (!heritage && i % 4 === 0) {
      const j = (i + 4) % p.n;
      const a = q(i, u1 - 0.1, b0 + top), b = q(j, u1 - 0.1, p.bank[j] + top);
      const blocked = atGate(p, b[0], b[2]);
      k.bar(a, [a[0], a[1] + 0.55, a[2]], 0.02, METAL);
      if (!blocked) for (const y of [0.28, 0.55]) k.bar([a[0], a[1] + y, a[2]], [b[0], b[1] + y, b[2]], 0.012, METAL);
    }
  }
}

/** The pit lane, its wall, its building, the tower and the podium. */
function pits(k: Kit, p: CircuitPlan, r: () => number): void {
  const d = DRESS[p.design], h = p.half;
  // the lane: wherever it has left the track
  for (let q = 0; q + 1 < p.pit.length; q++) {
    const a = p.pit[q], b = p.pit[q + 1];
    if (a.u > -h + 0.5 && b.u > -h + 0.5) continue;
    const ia = a.s / DS, ib = b.s / DS;
    const pt = (f: number, u: number): P3 => {
      const i = Math.floor(f), t = f - i;
      const A = P(p, i, u, 0.011, false), B = P(p, i + 1, u, 0.011, false);
      return [A[0] + (B[0] - A[0]) * t, 0.011, A[2] + (B[2] - A[2]) * t];
    };
    const A0 = pt(ia, a.u - 0.72), A1 = pt(ia, a.u + 0.72), B1 = pt(ib, b.u + 0.72), B0 = pt(ib, b.u - 0.72);
    k.quad(A0, A1, B1, B0, ASPHALT, [A0[0], -1, A0[2]]);
    const L0 = pt(ia, a.u + 0.62), L1 = pt(ib, b.u + 0.62), L2 = pt(ib, b.u + 0.68), L3 = pt(ia, a.u + 0.68);
    k.quad([L0[0], 0.015, L0[2]], [L3[0], 0.015, L3[2]], [L2[0], 0.015, L2[2]], [L1[0], 0.015, L1[2]], WHITE, [L0[0], -1, L0[2]]);
  }
  // the pit wall between the lane and the track
  const [f0, f1] = p.pitFull;
  for (let s = f0 + 0.3; s < f1 - 0.3 - 1e-6; s += DS) {
    const i = Math.floor(((s % p.len) + p.len) % p.len / DS);
    const a = P(p, i, -h - 0.35, 0, false), b = P(p, i + 1, -h - 0.35, 0, false), c = P(p, i + 1, -h - 0.62, 0, false), e = P(p, i, -h - 0.62, 0, false);
    const top = 0.22;
    const up = (v: P3, y: number): P3 => [v[0], y, v[2]];
    const mid: P3 = [(a[0] + c[0]) / 2, 0.1, (a[2] + c[2]) / 2];
    k.quad(up(a, 0), up(b, 0), up(b, top), up(a, top), CONCRETE, mid);
    k.quad(up(e, 0), up(c, 0), up(c, top), up(e, top), CONCRETE, mid);
    k.quad(up(a, top), up(b, top), up(c, top), up(e, top), d.trim, mid);
    if (i % 3 === 0) k.bar(up(a, top), up(a, top + 0.4), 0.015, METAL);
  }
  // the building: garages on the ground floor opening onto the lane, glass above, a terrace on the roof
  for (const o of p.pitBuilding) {
    inBox(k, o, (cx, cz) => {
      const H = 0.78;
      if (p.design === 'heritage') {
        k.box(cx, 0, cz, o.len, 0.55, o.dep, d.pit);
        k.gable(cx, 0.55, cz, o.len + 0.1, 0.35, o.dep + 0.12, d.roof, d.pit);
      } else {
        k.box(cx, 0, cz, o.len, H, o.dep, d.pit, scale(d.pit, 0.92));
        k.box(cx, H, cz, o.len + 0.04, 0.05, o.dep + 0.04, d.trim);
        // the upper floor's glass, and the hospitality terrace's rail
        k.box(cx, 0.46, cz + o.dep / 2 + 0.002, o.len - 0.1, 0.22, 0.02, GLASS_LIGHT);
        k.glowBox(cx, 0.47, cz + o.dep / 2 + 0.012, o.len - 0.2, 0.2, 0.005, GLASS_LIGHT, [18, 23.5, 1.8], hex(0xfff0c0));
        k.box(cx, H + 0.05, cz + o.dep / 2 - 0.05, o.len, 0.12, 0.02, METAL);
      }
      // the garage doors, each with its team's colour over it
      const n = Math.max(1, Math.floor(o.len / 0.75));
      for (let g = 0; g < n; g++) {
        const x = cx - o.len / 2 + (o.len * (g + 0.5)) / n;
        k.box(x, 0, cz + o.dep / 2 + 0.003, o.len / n - 0.14, 0.34, 0.02, DARK);
        k.box(x, 0.36, cz + o.dep / 2 + 0.006, o.len / n - 0.14, 0.05, 0.02, pick(r, [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0x8e5cc7, 0xf28c38]));
      }
    });
  }
  if (p.tower) {
    const { x, z } = p.tower;
    k.box(x, 0, z, 0.8, 1.7, 0.8, d.pit);
    k.box(x, 1.7, z, 1.05, 0.34, 1.05, GLASS_LIGHT);
    k.glowBox(x, 1.72, z, 1.0, 0.3, 1.0, GLASS_LIGHT, [18, 24, 1.6], hex(0xfff0c0));
    k.box(x, 2.04, z, 1.15, 0.06, 1.15, d.trim);
    k.bar([x + 0.3, 2.1, z], [x + 0.3, 2.7, z], 0.015, METAL);
  }
  if (p.podium) {
    inBox(k, p.podium, (cx, cz) => {
      k.box(cx, 0, cz - 0.3, 1.6, 0.8, 0.12, DARK);
      k.box(cx, 0.55, cz - 0.23, 1.3, 0.12, 0.02, d.trim);
      k.box(cx, 0, cz + 0.05, 0.42, 0.34, 0.4, GOLD);
      k.box(cx - 0.44, 0, cz + 0.05, 0.42, 0.24, 0.4, SILVER);
      k.box(cx + 0.44, 0, cz + 0.05, 0.42, 0.16, 0.4, BRONZE);
    });
  }
}

/** A grandstand: stepped rows of seats rising away from the track, walled at the back and ends, roofed if it's a main stand. */
function stand(k: Kit, p: CircuitPlan, s: Stand, r: () => number): void {
  const d = DRESS[p.design];
  const rows = standRows(p, s);
  const blocks = d.seats;
  inBox(k, s, (cx, cz) => {
    const back = -s.dep / 2;
    for (const [ri, row] of rows.entries()) {
      // the step, and the seats along its front edge in blocks of colour
      k.box(cx, 0, cz + row.z, s.len, row.y, row.d + 0.005, d.body, scale(d.body, 1.08));
      const n = Math.max(1, Math.round(s.len / 1.6));
      for (let b = 0; b < n; b++) {
        const w = s.len / n;
        const col = hex(blocks[(b + (ri > rows.length / 2 ? 1 : 0)) % blocks.length]);
        k.box(cx - s.len / 2 + w * (b + 0.5), row.y, cz + row.z + row.d * 0.15, w - 0.04, 0.05, row.d * 0.5, col);
      }
    }
    const top = rows[rows.length - 1].y;
    // back and end walls
    k.box(cx, 0, cz + back + 0.1, s.len, top + 0.18, 0.2, scale(d.body, 0.85));
    for (const e of [-1, 1]) k.box(cx + e * (s.len / 2 - 0.05), 0, cz, 0.1, top * 0.9, s.dep - 0.1, scale(d.body, 0.9));
    // a road circuit's tyre wall along the foot of the stand
    if (p.design === 'grandprix') {
      for (let x = -s.len / 2 + 0.15; x < s.len / 2 - 0.1; x += 0.24) k.cyl(cx + x, 0, cz + s.dep / 2 - 0.16, 0.11, 0.2, TYRE, 7);
      k.box(cx, 0.2, cz + s.dep / 2 - 0.16, s.len - 0.1, 0.03, 0.25, pick(r, [0xe2412f, 0x2f7fb5, 0xf4f2ec]));
    }
    // the roof on its columns, cantilevered out over the front rows, with the floodlights under its lip
    if (s.roof) {
      // over the back rows only, so the crowd in front can be seen from above
      const ry = top + 0.45, fz = cz + back + s.dep * 0.42;
      for (let x = -s.len / 2 + 0.2; x <= s.len / 2 - 0.19; x += Math.max(1.4, s.len / 4)) k.bar([cx + x, 0, cz + back + 0.12], [cx + x, ry + 0.3, cz + back + 0.12], 0.05, METAL);
      const A: P3 = [cx - s.len / 2, ry + 0.3, cz + back], B: P3 = [cx + s.len / 2, ry + 0.3, cz + back], C: P3 = [cx + s.len / 2, ry, fz], D: P3 = [cx - s.len / 2, ry, fz];
      k.quad(A, B, C, D, d.roof, [cx, ry - 1, cz]);
      k.quad(A, D, C, B, scale(d.roof, 0.7), [cx, ry + 2, cz]);
      k.box(cx, ry - 0.08, fz, s.len, 0.1, 0.06, d.trim);
      k.glowBox(cx, ry - 0.1, fz - 0.05, s.len - 0.2, 0.04, 0.04, WHITE, [18, 23.5, 2.6], hex(0xfff6dc));
      // the name board along the roof's lip
      if (p.design !== 'heritage') k.box(cx, ry - 0.3, fz + 0.02, s.len * 0.5, 0.18, 0.03, d.trim);
    }
  });
}

/** The gate: the lane in from the road, the arch over it with the chequered banner, and the ticket booths. */
function gate(k: Kit, p: CircuitPlan): void {
  const d = DRESS[p.design], D = p.D, x = p.gateX;
  const g = along(p, p.gateS);
  // flat from the road to where the gap in the wall begins, then up the last of the ramp onto the banking
  const edge = g.z + p.half, rampEnd = edge + 1.4, lift = bankLift(p, g.bank, p.half) + 0.012;
  const z0 = D / 2;
  k.quad([x - 1.1, 0.01, z0], [x + 1.1, 0.01, z0], [x + 1.1, 0.01, rampEnd], [x - 1.1, 0.01, rampEnd], ASPHALT, [x, -1, z0 - 1]);
  k.quad([x - 1.1, 0.01, rampEnd], [x + 1.1, 0.01, rampEnd], [x + 1.1, lift, edge], [x - 1.1, lift, edge], ASPHALT, [x, -1, rampEnd - 0.5]);
  const az = D / 2 - 0.45;
  for (const e of [-1, 1]) k.box(x + e * 1.35, 0, az, 0.2, 1.05, 0.2, d.trim);
  k.box(x, 0.95, az, 2.9, 0.3, 0.1, WHITE);
  for (let c = 0; c < 12; c++) for (let rr = 0; rr < 2; rr++) if ((c + rr) % 2) k.box(x - 1.32 + c * 0.24 + 0.12, 0.97 + rr * 0.13, az + 0.055, 0.24, 0.13, 0.01, DARK);
  k.glowBox(x, 0.9, az + 0.06, 2.6, 0.04, 0.02, WHITE, [18, 24, 2.2], hex(0xfff0c0));
}

/** The gantry over the line, with its light panel facing the grid (the lights themselves are the race's). */
function gantry(k: Kit, p: CircuitPlan): void {
  const [a, b] = p.gantry;
  for (const q of p.gantry) k.box(q.x, 0, q.z, 0.14, 1.35, 0.14, METAL);
  k.bar([a.x, 1.3, a.z], [b.x, 1.3, b.z], 0.06, METAL);
  k.bar([a.x, 1.12, a.z], [b.x, 1.12, b.z], 0.03, METAL);
  const g = along(p, 0);
  inBox(k, { x: (a.x + b.x) / 2, z: (a.z + b.z) / 2, a: yawFacing(-g.tx, -g.tz) }, (cx, cz) => {
    k.box(cx, 1.0, cz, 1.5, 0.28, 0.12, DARK);
    k.box(cx, 1.28, cz, 1.6, 0.1, 0.14, WHITE);
  });
}

/** The floodlight masts in the lot's corners, model frame: where a stand or the track isn't in the way. Their heads are at FLOOD_HEAD. */
export function floodMastsOf(p: CircuitPlan): { x: number; z: number; sx: number; sz: number }[] {
  const W = p.W, D = p.D, out: { x: number; z: number; sx: number; sz: number }[] = [];
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    const x = sx * (W / 2 - 0.9), z = sz * (D / 2 - 0.9);
    if (p.stands.some((s) => inOBox(s, x, z, 0.2)) || zoneAt(p, x, z) !== 0) continue;
    out.push({ x, z, sx, sz });
  }
  return out;
}
export const FLOOD_HEAD = 2.75;

/** Floodlight masts in the lot's corners, for the night races (game/circuits.ts lights the track from them). */
function floodlights(k: Kit, p: CircuitPlan): void {
  for (const { x, z, sx, sz } of floodMastsOf(p)) {
    k.box(x, 0, z, 0.12, 2.6, 0.12, METAL);
    k.box(x, 2.6, z, 0.6, 0.3, 0.1, DARK);
    k.glowBox(x - sx * 0.02, 2.62, z - sz * 0.06, 0.55, 0.26, 0.02, WHITE, [18, 24, 3], hex(0xfff6dc));
  }
}

/** The speedway's leaderboard pylon in the tri-oval. */
function pylon(k: Kit, p: CircuitPlan): void {
  if (!p.pylon) return;
  const { x, z } = p.pylon;
  k.box(x, 0, z, 0.5, 2.9, 0.5, DARK);
  for (let i = 0; i < 8; i++) k.glowBox(x, 0.6 + i * 0.26, z + 0.255, 0.4, 0.16, 0.01, hex(0x3a3f45), [0, 24, 1.6], hex([0xffe14f, 0xf4f2ec][i % 2]));
  k.box(x, 2.9, z, 0.7, 0.3, 0.7, KERB_RED);
}

/** Trucks in the paddock behind the pits. */
function paddock(k: Kit, p: CircuitPlan, r: () => number): void {
  for (const o of p.solids) {
    if (o.len !== 1.6 || o.dep !== 0.55) continue;
    inBox(k, o, (cx, cz) => {
      const col = pick(r, [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0x8e5cc7, 0xf4f2ec]);
      k.box(cx - 0.2, 0.06, cz, 1.2, 0.42, 0.5, col);
      k.box(cx + 0.6, 0.06, cz, 0.36, 0.34, 0.48, WHITE);
      k.box(cx + 0.72, 0.22, cz, 0.08, 0.14, 0.44, GLASS_LIGHT);
      for (const x of [-0.6, 0.1, 0.6]) for (const e of [-1, 1]) k.cyl(cx + x, 0, cz + e * 0.24, 0.07, 0.07, TYRE, 6);
    });
  }
}

export const raceCircuit: Draw = (k, W, D, b, r) => {
  const p = circuitPlan(designOf(W, D));
  track(k, p);
  walls(k, p);
  pits(k, p, r);
  for (const s of p.stands) stand(k, p, s, r);
  gate(k, p);
  gantry(k, p);
  // the fence round the lot is drawn with the field fences (world/fences.ts), so a car can knock it flat
  floodlights(k, p);
  pylon(k, p);
  paddock(k, p, r);
  void b;
};

export const CIRCUIT_DRAW: Record<CircuitKind, Draw> = { raceCircuit };
