import * as THREE from 'three';
import { N, STEP, heightAt, idx, inB, type World } from '../../world/tiles';
import type { CellDoc, ServerMsg, Welcome } from '../../../shared/protocol';
import {
  CHAL, CHAL_CLASS_NAME, CHAL_TAKES, ChalRun, VOID_TEXT, better, scoreText,
  type ChalBoard, type ChalNews, type ChalRow, type ChalSite, type ChalVoid,
} from '../../../shared/challenges';
import { decodeGhost, ghostAt, type GhostPt } from '../../../shared/marks';
import type { Online, OnlineExtra } from '../../net/online';
import { buildVehicleMesh, disposeVehicleMesh, type VehicleMesh } from '../../render/vehicleMeshes';
import { GroundRing, drapeMat, laidY } from '../../render/drape';
import { defOf } from '../fleet';
import type { VehicleDef } from '../vehicles';
import { esc } from '../cargoHud';
import { chip, css } from '../firmSpec';
import { sitesOf } from './sites';
import { payHeld } from './pay';
import { startPrompt } from '../startPrompt';
import { inScope, scopeMode } from '../../net/boardScope';

/**
 * PvP Challenges in the game (docs/challenges.html, 0.7.0, behind NEXT_WORLD): the chequered lines in the counties
 * in memory (game/challenges/sites.ts), the card at a line when the player stops on it in a vehicle it takes,
 * Space to start, the race countdown with the vehicle held, the run (a Sixty's clock and distance, a dash's
 * route arrows, the holder's ghost), and the result beside the player's best and the leader's.
 *
 * Online the server measures every run itself from the poses (server/challenges.ts) and keeps the boards; the
 * result shown is the server's. Each board the player holds pays ◆ 1 a game day, an hour at a time, on the
 * Diamonds tab's own line. A board taken from them is told when it happens, or at the next sign-in. Offline a
 * run counts against the player's own best on this device only.
 */

interface ChallengesHost {
  scene: THREE.Scene;
  /** Challenges are on: the next world, playing. */
  enabled(): boolean;
  /** hashString of the world's seed, as the server's. */
  seed(): number;
  worlds(): World[];
  worldAt(cx: number, cz: number): World | null;
  /** The player at the wheel, world tiles; null when not driving (a menu, the camera on something else). */
  player(): { x: number; z: number; y: number; heading: number; v: number; model: string; def: VehicleDef } | null;
  say(title: string, body: string): void;
  beep(final: boolean): void;
  /** ◆ for holding a board, on its own line of the account (`key` the board's id). */
  pay(n: number, what: string, key: string): void;
  /** Route arrows to a dash's finish (null takes them down). */
  route(to: { x: number; z: number; key: string; near: number } | null): void;
  modelName(m: string): string;
  me(): { name: string; primary: number; accent: number; logo: string };
  /** Something the Standings tab shows has changed. */
  refresh(): void;
}

type State = 'idle' | 'count' | 'run' | 'wait' | 'result';
/** How near (tiles) a line is asked about, the shortest wait between asks, and how long the server has to answer a run. */
const ASK_R = 60, ASK_EVERY = 6000, ANSWER_MS = 6000;
/** Lines drawn within this many tiles of the player. */
const DRAW_R = 170;
const LOCAL_KEY = 'tinyfleet-chal-best';

/** `held`: who the sign says holds the line (their name and look, '' for nobody), so it is painted again only when that changes. */
interface Marker { site: ChalSite; g: THREE.Group; label: THREE.Sprite; dest: THREE.Group | null; rings: GroundRing[]; held: string }

export class Challenges implements OnlineExtra {
  state: State = 'idle';
  /** Boards held now (server-told), by id. */
  held: string[] = [];
  private on: string[] = [];
  /** Boards as last sent, by id. */
  private boards = new Map<string, ChalBoard & { asked: number }>();
  private ghosts = new Map<string, { pts: GhostPt[]; by: string; s: number; m: string }>();
  private news: ChalNews[] = [];
  private local: Record<string, number> = {};
  private markers = new Map<string, Marker>();
  private root = new THREE.Group();
  private site: ChalSite | null = null;
  private run: ChalRun | null = null;
  private runT0 = 0;
  private lastCount = 0;
  private result: { at: number; title: string; body: string } | null = null;
  private waitUntil = 0;
  private serverRes: Extract<ServerMsg, { t: 'chalRes' }> | null = null;
  private ghost: { id: string; mesh: VehicleMesh; mats: THREE.Material[] } | null = null;
  private card = document.createElement('div');
  private strip = document.createElement('div');
  private count = document.createElement('div');
  private cardSig = '';
  private cardUp = false;
  private startable: { s: ChalSite; p: NonNullable<ReturnType<ChallengesHost['player']>> } | null = null;
  private model = '';
  private checker: THREE.CanvasTexture;

  constructor(private online: Online, private host: ChallengesHost) {
    this.root.name = 'challenges';
    host.scene.add(this.root);
    this.card.className = 'chal-card';
    this.strip.className = 'chal-strip';
    this.count.className = 'race-count';
    this.card.hidden = this.strip.hidden = this.count.hidden = true;
    document.body.append(this.card, this.strip, this.count);
    injectCss();
    const c = document.createElement('canvas');
    c.width = 64; c.height = 16;
    const x = c.getContext('2d')!;
    for (let i = 0; i < 16; i++) for (let j = 0; j < 4; j++) { x.fillStyle = (i + j) % 2 ? '#1f2b33' : '#ffffff'; x.fillRect(i * 4, j * 4, 4, 4); }
    this.checker = new THREE.CanvasTexture(c);
    this.checker.magFilter = THREE.NearestFilter;
    this.checker.colorSpace = THREE.SRGBColorSpace;
    try { this.local = JSON.parse(localStorage.getItem(LOCAL_KEY) ?? '{}') as Record<string, number>; } catch { this.local = {}; }
  }

  /** The vehicle is to be held still: the countdown. */
  get holding(): boolean { return this.state === 'count'; }

  // ---- the online session ----

  welcome(w: Welcome): void {
    this.held = w.chal?.held ?? [];
    this.on = w.chal?.on ?? [];
    this.news = w.chal?.news ?? [];
  }

  cell(_k: string, _doc: CellDoc): void { /* the boards are asked for at the line */ }

  ready(): void {
    if (!this.host.enabled()) return;
    this.online.post({ t: 'chalBoards', ids: [] });
    for (const n of this.news) this.lost(n, n.by);
    this.news = [];
  }

  frame(): void { /* driven by update() */ }

  forget(k: string): void {
    for (const [id, m] of this.markers) if (id.startsWith(`${k}:`)) this.dropMarker(id, m);
  }

  reset(): void {
    this.held = [];
    this.on = [];
    this.boards.clear();
    this.ghosts.clear();
    this.news = [];
    if (this.state !== 'idle') this.stop();
  }

  got(m: ServerMsg): boolean {
    switch (m.t) {
      case 'chalBoard': this.keep(m.b); return true;
      case 'chalBoards':
        for (const b of m.rows) this.keep(b);
        this.held = m.held;
        this.host.refresh();
        return true;
      case 'chalGhost': this.ghosts.set(m.id, { pts: decodeGhost(m.g), by: m.by, s: m.s, m: m.m }); return true;
      case 'chalGo': return true;
      case 'chalRes': if (this.site && m.id === this.site.id) this.serverRes = m; return true;
      case 'chalHeld': {
        const gained = m.held.filter((id) => !this.held.includes(id));
        this.held = m.held;
        for (const id of gained) { const b = this.boards.get(id); if (b && this.state !== 'wait') this.host.say('🏁 You hold a PvP board', `${b.site.name} · ◆ ${CHAL.perDay} a game day while it’s yours`); }
        this.host.refresh();
        return true;
      }
      case 'chalLost': this.lost(m.n, m.who?.brand?.name ?? m.who?.name ?? 'Another fleet'); return true;
      default: return false;
    }
  }

  private keep(b: ChalBoard): void {
    this.boards.set(b.id, { ...b, asked: performance.now() });
    if (b.you && !this.on.includes(b.id)) this.on.push(b.id);
    // the server's line is everyone's: a marker drawn from this game's own reading of the county moves to it
    const mk = this.markers.get(b.id);
    if (mk && (Math.abs(mk.site.x - b.site.x) > 0.2 || Math.abs(mk.site.z - b.site.z) > 0.2 || mk.site.to?.x !== b.site.to?.x)) this.dropMarker(b.id, mk);
    this.host.refresh();
  }

  private lost(n: ChalNews, by: string): void {
    const name = typeof by === 'string' && by.startsWith('p:') ? (this.online.people.get(by)?.brand?.name ?? this.online.people.get(by)?.name ?? 'Another fleet') : by;
    this.host.say('🏁 PvP board taken', `${name} beat your ${scoreText(n.kind, n.was)} at ${n.name} with ${scoreText(n.kind, n.s)} · win it back to earn its ◆ again`);
  }

  // ---- diamonds ----

  /** A game hour: every board held pays its share of ◆ 1 a day. */
  hourly(): void {
    if (!this.host.enabled() || !this.online.active) return;
    payHeld(this.held, (id) => this.boards.get(id)?.site.name ?? id, (n, what, key) => this.host.pay(n, what, key));
  }

  /** Boards held, for the Diamonds tab: name and ◆ a day. */
  paying(): { name: string; perDay: number }[] {
    return this.online.active ? this.held.map((id) => ({ name: this.boards.get(id)?.site.name ?? id, perDay: CHAL.perDay })) : [];
  }

  // ---- the lines ----

  /** Every line in the counties in memory, the server's where it has one. */
  private sites(): ChalSite[] {
    const out: ChalSite[] = [];
    const seed = this.host.seed();
    for (const w of this.host.worlds()) for (const s of sitesOf(w, seed)) out.push(this.boards.get(s.id)?.site ?? s);
    return out;
  }

  private dropMarker(id: string, m: Marker): void {
    m.g.removeFromParent();
    m.dest?.removeFromParent();
    m.g.traverse((o) => { const x = o as THREE.Mesh; if (x.isMesh) x.geometry.dispose(); });
    m.dest?.traverse((o) => { const x = o as THREE.Mesh; if (x.isMesh) x.geometry.dispose(); });
    for (const r of m.rings) (r.mesh.material as THREE.Material).dispose();
    (m.label.material as THREE.SpriteMaterial).map?.dispose();
    m.label.material.dispose();
    this.markers.delete(id);
  }

  private ground(x: number, z: number, cls: string): number {
    const w = this.host.worldAt(Math.floor(x / N), Math.floor(z / N));
    if (!w) return 0;
    const lx = x - w.ox, lz = z - w.oz;
    if (cls === 'S') { const tx = Math.floor(lx), tz = Math.floor(lz); if (inB(tx, tz) && w.water[idx(tx, tz)] >= 0) return w.water[idx(tx, tz)] * STEP; }
    // the top of the road (or runway) the line is painted on, not the ground under it: a road stands a few
    // hundredths over the ground, so a line laid on the ground sat in the road or flickered through it
    return laidY(w, lx, lz);
  }

  /** What is under a point of a marker standing at (s.x, y, s.z) turned to s.h, `lx` across its line and `lz` along. */
  private under(s: ChalSite, y: number, lx: number, lz: number): number {
    const ch = Math.cos(s.h), sh = Math.sin(s.h);
    return this.ground(s.x + lx * ch + lz * sh, s.z - lx * sh + lz * ch, s.cls) - y;
  }

  private makeMarker(s: ChalSite): Marker {
    const g = new THREE.Group();
    const y = this.ground(s.x, s.z, s.cls);
    g.position.set(s.x, y, s.z);
    g.rotation.y = s.h;
    const w = s.half * 2 + 0.4;
    const tex = this.checker.clone();
    tex.wrapS = THREE.RepeatWrapping;
    tex.repeat.set(w / 2, 1);
    tex.needsUpdate = true;
    // the chequered line, in quarter-tile steps each laid on the road's (or the water's) top under it, so a
    // crowned, banked or sloping road never shows through it; drawn over the surface it lies on, so it can't
    // flicker against it from far off
    const deep = s.cls === 'S' ? 0.25 : 0.5;
    const geo = new THREE.PlaneGeometry(w, deep, Math.max(2, Math.ceil(w / 0.25)), 2).rotateX(-Math.PI / 2);
    const pos = geo.getAttribute('position');
    const lift = s.cls === 'S' ? 0.05 : 0.03;
    for (let k = 0; k < pos.count; k++) pos.setY(k, this.under(s, y, pos.getX(k), pos.getZ(k)) + lift);
    geo.computeBoundingSphere();
    const strip = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({
      map: tex, transparent: true, opacity: s.cls === 'S' ? 0.9 : 1, depthWrite: false,
      polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -4,
    }));
    strip.renderOrder = 2;
    g.add(strip);
    for (const side of [-1, 1]) {
      const at = side * (s.half + 0.25);
      // the posts, cones and buoys stand on what is under each of them, not at the line's middle
      const foot = (lx: number) => this.under(s, y, lx, 0);
      if (s.cls === 'S') {
        // the buoys: red and white, riding the water, a chequered flag on a mast
        const b = new THREE.Mesh(new THREE.SphereGeometry(0.2, 12, 8), new THREE.MeshLambertMaterial({ color: side < 0 ? 0xe2412f : 0xffffff }));
        const f = foot(at);
        b.position.set(at, f + 0.08, 0);
        const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 0.7, 6), new THREE.MeshLambertMaterial({ color: 0x1f2b33 }));
        mast.position.set(at, f + 0.45, 0);
        g.add(b, mast, this.flag(at, f + 0.68));
      } else if (s.cls === 'A') {
        // low on a runway: cones a wing goes over; and off the strip, an air race's tall chequered pylons
        const cone = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.36, 10), new THREE.MeshLambertMaterial({ color: 0xff7a1a }));
        cone.position.set(at + side * 0.4, foot(at + side * 0.4) + 0.18, 0);
        g.add(cone);
        const pylon = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.2, 1.8, 10, 1, false), new THREE.MeshBasicMaterial({ map: this.checker }));
        pylon.position.set(at + side * 2.4, foot(at + side * 2.4) + 0.9, 0);
        g.add(pylon);
      } else {
        const post = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.9, 6), new THREE.MeshLambertMaterial({ color: 0xf4f1ea }));
        const f = foot(at);
        post.position.set(at, f + 0.45, 0);
        g.add(post, this.flag(at, f + 0.8));
      }
    }
    // over a road line, the start gantry: a chequered banner on a beam between the two posts
    if (s.cls === 'L') {
      // level, at the height of the higher post's foot; each post reaches down to its own
      const feet = [-1, 1].map((side) => this.under(s, y, side * (s.half + 0.28), 0));
      const top = Math.max(...feet);
      const beam = new THREE.Mesh(new THREE.BoxGeometry(s.half * 2 + 0.56, 0.05, 0.05), new THREE.MeshLambertMaterial({ color: 0x1f2b33 }));
      beam.position.set(0, top + 1.12, 0);
      const banner = new THREE.Mesh(new THREE.PlaneGeometry(s.half * 2 + 0.3, 0.22), new THREE.MeshBasicMaterial({ map: tex, side: THREE.DoubleSide }));
      banner.position.set(0, top + 0.98, 0);
      g.add(beam, banner);
      [-1, 1].forEach((side, k) => {
        const h = top + 1.12 - feet[k];
        const post = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, h, 6), new THREE.MeshLambertMaterial({ color: 0x1f2b33 }));
        post.position.set(side * (s.half + 0.28), feet[k] + h / 2, 0);
        g.add(post);
      });
    }
    const label = textSprite(signTitle(s));
    label.position.set(0, 2.1, 0);
    g.add(label);
    this.root.add(g);
    let dest: THREE.Group | null = null;
    const rings: GroundRing[] = [];
    if (s.to) {
      // the finish: a white ring round a dark one, lying on the ground (render/drape.ts), and a beam over it.
      // The group stays at the origin (the rings hold world points); placeDest lays them once the ground is in memory
      dest = new THREE.Group();
      const r = s.cls === 'A' ? CHAL.finishAirR : CHAL.finishR;
      rings.push(new GroundRing(r, 0.24, drapeMat(0xffffff, 0.95)), new GroundRing(r - 0.3, 0.2, drapeMat(0x1f2b33, 0.9)));
      const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.5, 60, 12, 1, true), new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.22, depthWrite: false }));
      dest.add(rings[0].mesh, rings[1].mesh, beam);
      dest.visible = false;
      this.root.add(dest);
    }
    const m: Marker = { site: s, g, label, dest, rings, held: '' };
    this.placeDest(m);
    return m;
  }

  /** Lay a dash's finish rings on the ground at its end and stand its beam there (again once that ground has loaded). */
  private placeDest(m: Marker): void {
    const to = m.site.to;
    if (!to || !m.dest) return;
    const cls = m.site.cls;
    const ground = (x: number, z: number): number | null => (this.host.worldAt(Math.floor(x / N), Math.floor(z / N)) ? this.ground(x, z, cls) : null);
    for (const r of m.rings) r.place(to.x, to.z, ground);
    m.dest.children[2].position.set(to.x, (ground(to.x, to.z) ?? 0) + 30, to.z);
  }

  private flag(x: number, y: number): THREE.Mesh {
    const f = new THREE.Mesh(new THREE.PlaneGeometry(0.34, 0.2), new THREE.MeshBasicMaterial({ map: this.checker, side: THREE.DoubleSide }));
    f.position.set(x + 0.17, y, 0);
    return f;
  }

  // ---- each frame ----

  /** Space, with the card up in a vehicle the line takes: the countdown starts. Whether it was this one's. */
  space(): boolean {
    const r = this.startable;
    if (!r || !this.host.enabled()) return false;
    this.begin(r.s, r.p, performance.now());
    return true;
  }

  /** `free`: nothing else is up (a menu, a tool, the camera mode), so the card may show and Space may start. */
  update(dt: number, free = true): void {
    void dt;
    this.startable = null;
    if (!this.host.enabled()) { if (this.state !== 'idle') this.stop(); this.root.visible = false; this.card.hidden = this.strip.hidden = this.count.hidden = true; return; }
    this.root.visible = true;
    const p = this.host.player();
    const now = performance.now();
    this.cardUp = false;
    this.draw(p, now);
    switch (this.state) {
      case 'idle': case 'result': if (free) this.atLine(p, now); break;
      case 'count': case 'run': this.running(p, now); break;
      case 'wait': this.waiting(now); break;
    }
    if (this.state === 'result' && this.result && now - this.result.at > 9000) { this.state = 'idle'; this.result = null; }
    // stopped on a line the vehicle fits: the start prompt (game/startPrompt.ts), at the foot of the card
    // (set by atLine above, which the narrowing from the reset at the top can't see)
    const r = this.startable as Challenges['startable'];
    if (r) startPrompt.show('chal', { key: 'Space', title: 'On the line', action: 'start the countdown', dock: this.card });
    else startPrompt.hide('chal');
    this.render(p, now);
  }

  /** The lines near the player drawn, and asked about online. */
  private draw(p: ReturnType<ChallengesHost['player']>, now: number): void {
    const near = new Set<string>();
    for (const s of this.sites()) {
      if (p && Math.hypot(s.x - p.x, s.z - p.z) > DRAW_R) continue;
      near.add(s.id);
      if (!this.markers.has(s.id)) this.markers.set(s.id, this.makeMarker(s));
      const b = this.boards.get(s.id);
      if (p && this.online.active && Math.hypot(s.x - p.x, s.z - p.z) < ASK_R && (!b || now - b.asked > ASK_EVERY * 5) && !(b && now - b.asked < ASK_EVERY)) {
        this.boards.set(s.id, { ...(b ?? { id: s.id, site: s, rows: [], you: null, n: 0 }), asked: now });
        this.online.post({ t: 'chalSite', site: s });
      }
    }
    for (const [id, m] of this.markers) {
      if (!near.has(id) && this.site?.id !== id) { this.dropMarker(id, m); continue; }
      m.label.visible = this.state === 'idle' || this.state === 'result';
      // the fleet in first place, under the title: "Held by" its logo in its colours and its name
      const top = this.boards.get(id)?.rows[0] ?? null;
      const held = top ? `${top.name}|${top.brand?.logo ?? ''}|${top.brand?.primary ?? ''}|${top.brand?.accent ?? ''}` : '';
      if (held !== m.held) { m.held = held; paintSign(m.label, signTitle(m.site), top); }
    }
  }

  /** Stopped on a line: the card; Space starts the countdown. */
  private atLine(p: ReturnType<ChallengesHost['player']>, now: number): void {
    let s: ChalSite | null = null;
    if (p) for (const m of this.markers.values()) if (Math.hypot(m.site.x - p.x, m.site.z - p.z) <= CHAL.startR) { s = m.site; break; }
    const stopped = !!p && Math.abs(p.v) < CHAL.stopped;
    this.site = s && stopped ? s : (this.state === 'result' ? this.site : null);
    if (!s || !stopped || !p) { if (this.state !== 'result') this.cardSig = ''; return; }
    if (this.state === 'result' && this.result && now - this.result.at < 1500) return;
    const fits = p.def.kind === CHAL_TAKES[s.cls];
    const b = this.boards.get(s.id);
    if (b?.ghost && b.rows[0] && b.rows[0].by !== this.online.me?.id && !this.ghosts.has(s.id) && this.online.active) {
      this.ghosts.set(s.id, { pts: [], by: '', s: 0, m: '' });
      this.online.post({ t: 'chalGhost', id: s.id });
    }
    this.showCard(s, fits);
    if (fits) this.startable = { s, p };
  }

  private begin(s: ChalSite, p: NonNullable<ReturnType<ChallengesHost['player']>>, now: number): void {
    this.site = s;
    this.model = p.model;
    this.run = new ChalRun(s, p.def.topSpeed, { x: p.x, z: p.z, t: now, v: p.v }, now);
    this.runT0 = now;
    this.serverRes = null;
    this.result = null;
    startPrompt.hide('chal');
    this.state = 'count';
    this.lastCount = 0;
    this.card.hidden = true;
    this.cardSig = '';
    this.online.post({ t: 'chalGo', site: s, at: Math.round(now) });
  }

  private running(p: ReturnType<ChallengesHost['player']>, now: number): void {
    const run = this.run!, s = this.site!;
    if (!p || p.model !== this.model) run.fail('vehicle');
    else run.feed({ x: p.x, z: p.z, t: now, v: p.v }, now, p.heading);
    if (this.state === 'count') {
      const left = Math.ceil((run.go - now) / 1000);
      if (left !== this.lastCount && left > 0) { this.lastCount = left; this.host.beep(false); }
      if (now >= run.go) { this.state = 'run'; this.host.beep(true); if (s.to) this.host.route({ x: s.to.x, z: s.to.z, key: `chal:${s.id}`, near: 2 }); }
    }
    if (run.over || (this.serverRes && this.state === 'run')) this.end(now);
  }

  private end(now: number): void {
    this.host.route(null);
    this.dropGhost();
    const run = this.run!;
    if (run.phase === 'void') this.online.post({ t: 'chalStop', id: this.site!.id });
    if (this.online.active && run.phase !== 'void') { this.state = 'wait'; this.waitUntil = now + ANSWER_MS; return; }
    this.conclude(now);
  }

  private waiting(now: number): void {
    if (this.serverRes || now > this.waitUntil) this.conclude(now);
  }

  /** The result as the player is told it: the server's online (it measured the run), the game's own offline. */
  private conclude(now: number): void {
    const s = this.site!, run = this.run!, r = this.serverRes;
    const kind = s.kind;
    let title: string, body: string;
    if (run.phase === 'void' || (r && !r.ok)) {
      const why = (r && !r.ok ? r.why : run.why) as ChalVoid;
      title = '🏁 Run not counted';
      body = VOID_TEXT[why] ?? String(why);
    } else if (r && r.ok && r.s !== undefined) {
      const top = r.top;
      title = r.rec ? (r.held ? `🏆 ${scoreText(kind, r.s)} · you hold it` : `🏁 ${scoreText(kind, r.s)} · a new best`) : `🏁 ${scoreText(kind, r.s)}`;
      body = `${s.name} · your best ${scoreText(kind, r.best ?? r.s)} · #${r.place} of ${r.n}`
        + (top && top.by !== this.online.me?.id ? ` · leader ${top.name} ${scoreText(kind, top.s)}` : '')
        + (r.held && r.rec ? ` · ◆ ${CHAL.perDay} a game day while it’s yours` : '');
    } else {
      const was = this.local[s.id];
      const rec = was === undefined || better(kind, run.score, was);
      if (rec) { this.local[s.id] = run.score; try { localStorage.setItem(LOCAL_KEY, JSON.stringify(this.local)); } catch { /* storage blocked */ } }
      title = `🏁 ${scoreText(kind, run.score)}${rec ? ' · a new best' : ''}`;
      body = `${s.name} · your best ${scoreText(kind, this.local[s.id])}${this.online.active ? ' · the server didn’t answer: not on the board' : ' · online, the best go on a board for everyone'}`;
    }
    this.host.say(title, body);
    this.result = { at: now, title, body };
    this.state = 'result';
    this.run = null;
    if (this.online.active) this.online.post({ t: 'chalSite', site: s });
  }

  /** Backspace in a countdown or a run: given up, and nothing posted. */
  giveUp(): boolean {
    if (this.state !== 'count' && this.state !== 'run') return false;
    const s = this.site;
    this.stop();
    if (s) this.host.say('🏁 Run given up', `${s.name} · stop on its line and press Space to try again`);
    return true;
  }

  /** Give up whatever is going (a menu, the world unloading). */
  stop(): void {
    if (this.site && (this.state === 'count' || this.state === 'run')) this.online.post({ t: 'chalStop', id: this.site.id });
    this.host.route(null);
    this.dropGhost();
    this.state = 'idle';
    this.run = null;
    this.site = null;
    this.result = null;
  }

  // ---- what is on screen ----

  private showCard(s: ChalSite, fits: boolean): void {
    const b = this.boards.get(s.id);
    const me = this.online.me?.id;
    const top = b?.rows[0];
    const mine = b?.you?.s ?? (this.online.active ? undefined : this.local[s.id]);
    const sig = `${s.id}|${fits}|${top?.by}|${top?.s}|${mine}|${b?.n}|${this.held.includes(s.id)}|${this.state}`;
    this.cardUp = true;
    if (sig === this.cardSig) return;
    this.cardSig = sig;
    const what = s.kind === 'far' ? 'How far from this line can you get in 60 seconds? Any direction counts: straight-line tiles at the 60th second.' : `From this line to ${esc(s.to?.name ?? 'the finish')}, against the clock. The arrows show the way.`;
    const lead = top ? `<div class="cl"><span>Leader</span><b>${chip([top.brand?.primary ?? 0x7d8a92, top.brand?.accent ?? 0xffffff], top.brand?.logo || undefined)} ${esc(top.name)}${top.by === me ? ' <small>you</small>' : ''}</b><em>${scoreText(s.kind, top.s)}</em></div>` : `<div class="cl"><span>Leader</span><b>nobody yet</b><em>—</em></div>`;
    const you = mine !== undefined ? `<div class="cl"><span>Your best</span><b>${b?.you ? `#${b.you.place} of ${b.n}` : 'on this device'}</b><em>${scoreText(s.kind, mine)}</em></div>` : '';
    this.card.innerHTML = `<h4>🏁 PvP Challenge · ${s.kind === 'far' ? 'Distance' : 'Dash'}</h4><p class="nm">${esc(s.name)}</p><p>${what}</p>
      ${lead}${you}
      <p class="pay">${this.held.includes(s.id) ? `You hold it · ◆ ${CHAL.perDay} a game day` : `The top spot pays ◆ ${CHAL.perDay} a game day while it’s held`}${this.online.active ? '' : ' (online)'}</p>
      ${fits ? '' : `<p class="go no">${esc(CHAL_CLASS_NAME[s.cls])}</p>`}`;
  }

  private render(p: ReturnType<ChallengesHost['player']>, now: number): void {
    this.card.hidden = !this.cardUp;
    // a dash's finish: shown with its card, and through the run
    for (const [id, m] of this.markers) {
      if (!m.dest) continue;
      m.dest.visible = this.site?.id === id && (this.cardUp || this.state === 'count' || this.state === 'run');
      if (m.dest.visible) this.placeDest(m);
      const b = m.dest.children[2];
      b.scale.x = b.scale.z = 1 + Math.sin(now / 500) * 0.12;
    }
    // the countdown, as a race's
    const run = this.run;
    let txt = '';
    if (this.state === 'count' && run) txt = String(Math.max(1, Math.ceil((run.go - now) / 1000)));
    else if (this.state === 'run' && run && now - run.go < 800) txt = 'GO';
    this.count.hidden = !txt;
    if (txt && this.count.textContent !== txt) { this.count.textContent = txt; this.count.classList.remove('pop'); void this.count.offsetWidth; this.count.classList.add('pop'); }
    // the run's strip and the ghost
    if ((this.state === 'run' || this.state === 'count') && run && this.site && p) {
      const s = this.site;
      const t = Math.max(0, (now - run.go) / 1000);
      const b = this.boards.get(s.id);
      const top = b?.rows[0];
      let line: string;
      if (s.kind === 'far') {
        const d = Math.hypot(p.x - s.x, p.z - s.z);
        line = `⏱ <b>${Math.max(0, CHAL.far - t).toFixed(1)} s</b> left · <b>${Math.round(d)}</b> tiles out${top ? ` · to beat: ${scoreText('far', top.s)}` : ''}`;
      } else {
        const d = s.to ? Math.hypot(p.x - s.to.x, p.z - s.to.z) : 0;
        line = `⏱ <b>${scoreText('dash', t)}</b> · <b>${Math.round(d)}</b> tiles to ${esc(s.to?.name ?? 'the finish')}${top ? ` · record ${scoreText('dash', top.s)}` : ''}`;
      }
      this.strip.innerHTML = `<span class="nm">${esc(s.name)}</span>${line}<span class="nm" style="margin:0 0 0 10px"><kbd>⌫</kbd> give up</span>`;
      this.strip.hidden = false;
      this.poseGhost(s, t, p);
    } else if (this.state === 'wait') {
      this.strip.innerHTML = '⏱ Checking with the server…';
      this.strip.hidden = false;
    } else this.strip.hidden = true;
  }

  private poseGhost(s: ChalSite, t: number, p: NonNullable<ReturnType<ChallengesHost['player']>>): void {
    const g = this.ghosts.get(s.id);
    if (!g || !g.pts.length || this.state !== 'run') { if (this.ghost) this.ghost.mesh.holder.visible = false; return; }
    if (!this.ghost || this.ghost.id !== s.id) this.makeGhost(s.id, g.m || p.model, g.by);
    const at = ghostAt(g.pts, t);
    if (!this.ghost || !at) return;
    const x = s.x + at[0], z = s.z + at[1];
    const y = s.cls === 'A' ? Math.max(this.ground(x, z, s.cls), p.y) : this.ground(x, z, s.cls);
    this.ghost.mesh.holder.visible = true;
    this.ghost.mesh.root.position.set(x, y, z);
    this.ghost.mesh.root.rotation.set(0, at[2], 0);
  }

  private makeGhost(id: string, model: string, by: string): void {
    this.dropGhost();
    let mesh: VehicleMesh;
    try { mesh = buildVehicleMesh(defOf(model)); } catch { return; }
    const who = this.online.people.get(by);
    const tint = new THREE.Color(who?.brand?.primary ?? 0x9ad0ff).lerp(new THREE.Color(0xffffff), 0.35);
    const mats: THREE.Material[] = [];
    mesh.holder.traverse((o) => {
      if (!(o instanceof THREE.Mesh)) return;
      const src = Array.isArray(o.material) ? o.material : [o.material];
      const out = src.map((m: THREE.Material) => {
        const base = 'color' in m && (m as THREE.MeshLambertMaterial).color ? (m as THREE.MeshLambertMaterial).color.clone() : new THREE.Color(0xffffff);
        const c = new THREE.MeshBasicMaterial({ color: base.lerp(tint, 0.6), transparent: true, opacity: 0.5, depthWrite: false, toneMapped: false, fog: false });
        mats.push(c);
        return c;
      });
      o.material = Array.isArray(o.material) ? out : out[0];
      o.castShadow = false;
      o.renderOrder = 5;
    });
    this.root.add(mesh.holder);
    this.ghost = { id, mesh, mats };
  }

  private dropGhost(): void {
    if (!this.ghost) return;
    this.ghost.mesh.holder.removeFromParent();
    for (const m of this.ghost.mats) m.dispose();
    disposeVehicleMesh(this.ghost.mesh);
    this.ghost = null;
  }

  // ---- the Standings tab ----

  opened(): void { this.ask(); }
  tick(): void { this.ask(); }
  private askedAt = 0;
  private ask(): void {
    const now = performance.now();
    if (!this.online.active || now - this.askedAt < 5000) return;
    this.askedAt = now;
    this.online.post({ t: 'chalBoards', ids: this.sites().map((s) => s.id) });
  }
  press(_target: HTMLElement): boolean { return false; }

  html(): string {
    const on = this.online.active;
    const me = this.online.me?.id;
    const near = new Set(this.sites().map((s) => s.id));
    const all = [...this.boards.values()].filter((b) => b.n || near.has(b.id));
    const held = all.filter((b) => this.held.includes(b.id));
    const mine = all.filter((b) => b.you && !this.held.includes(b.id));
    const rest = all.filter((b) => !b.you && !this.held.includes(b.id));
    const section = (title: string, list: typeof all) => (list.length ? `<h3 class="chal-h">${title}</h3>${list.map((b) => this.boardHtml(b, me)).join('')}` : '');
    const local = !on ? Object.entries(this.local).map(([id, s]) => `<li><span class="nm"><b>${esc(id)}</b></span><em>${s}</em></li>`).join('') : '';
    const lead = on
      ? `<div class="lead">${held.length ? `You hold <b>${held.length}</b> board${held.length === 1 ? '' : 's'} · <b>◆ ${held.length * CHAL.perDay}</b> a game day` : 'Hold the top spot on a board and it pays <b>◆ 1</b> a game day, as a town held as territory does.'}</div>`
      : '<div class="lead">Online, every PvP line has a board for every fleet. Offline, your own bests are kept on this device.</div>';
    return `${lead}${section('Held by you', held)}${section('Your entries', mine)}${section('Near you', rest)}${local ? `<ul class="ranking">${local}</ul>` : ''}
      <p class="foot">Lines are rare: a chequered strip across a road, a runway, or between two buoys on the water. Stop on one and press Space. The server times every run from your own driving; teleports, the garage and tows void it.</p>`;
  }

  private boardHtml(b: ChalBoard, me: string | undefined): string {
    const k = b.site.kind;
    const scoped = scopeMode() !== 'everyone';
    const rows: (ChalRow & { you?: boolean })[] = b.rows.filter((r) => r.by === me || inScope(r.by)).map((r) => ({ ...r, you: r.by === me }));
    if (b.you && !rows.some((r) => r.you)) rows.push({ ...b.you, you: true });
    // among friends or neighbours, places count within the scope; the board's own place shows beside it
    if (scoped) rows.sort((p, q) => (p.place ?? 1e9) - (q.place ?? 1e9));
    const best = Math.max(1, ...rows.map((r) => (k === 'far' ? r.s : 1 / Math.max(0.01, r.s))));
    return `<div class="chal-b"><p><b>${esc(b.site.name)}</b> <small>${k === 'far' ? 'Distance' : 'Dash'} · ${esc(CHAL_CLASS_NAME[b.site.cls].replace(' only', ''))} · ${b.n} fleet${b.n === 1 ? '' : 's'}</small></p>
      <ul class="ranking">${rows.map((r) => `<li class="${r.you ? 'you' : ''}"><span class="nm"><i>${scoped ? rows.indexOf(r) + 1 : r.place ?? ''}</i>${chip([r.brand?.primary ?? 0x7d8a92, r.brand?.accent ?? 0xffffff], r.brand?.logo || undefined)}<b${r.you ? '' : ` data-pid="${esc(r.by)}"`}>${esc(r.name)}</b>${r.you ? ' <small>you</small>' : ''}<span class="sub">${esc(this.host.modelName(r.m))}${scoped && r.place ? ` · #${r.place} overall` : ''}</span></span>
        <em>${scoreText(k, r.s)}</em><span class="bar"><i style="width:${Math.max(1.5, ((k === 'far' ? r.s : 1 / Math.max(0.01, r.s)) / best) * 100).toFixed(1)}%;background:${css(r.brand?.primary ?? 0x7d8a92)}"></i></span></li>`).join('') || '<li><span class="nm">No runs yet</span></li>'}</ul></div>`;
  }

  /** Pr console: the lines in memory, the boards, and a run's state. */
  console() {
    return {
      sites: () => this.sites(),
      boards: () => [...this.boards.values()],
      state: () => ({ state: this.state, site: this.site?.id ?? null, held: this.held, run: this.run ? { phase: this.run.phase, score: this.run.score, why: this.run.why } : null, result: this.result, ghost: !!this.ghost?.mesh.holder.visible }),
      start: () => { const p = this.host.player(); if (p && this.site) this.begin(this.site, p, performance.now()); return this.state; },
    };
  }
}

/** A line's sign: "PvP · DISTANCE" for a Sixty (how far in sixty seconds), "PvP DASH · ROAD" for a dash. */
function signTitle(s: ChalSite): string {
  return s.kind === 'far' ? '🏁 PvP · DISTANCE' : `🏁 PvP DASH · ${s.cls === 'L' ? 'ROAD' : s.cls === 'A' ? 'AIR' : 'SEA'}`;
}

function textSprite(text: string): THREE.Sprite {
  const c = document.createElement('canvas');
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, depthWrite: false, transparent: true }));
  s.renderOrder = 6;
  paintSign(s, text, null);
  return s;
}

const hex = (n: number): string => `#${(n & 0xffffff).toString(16).padStart(6, '0')}`;

/**
 * Paint a line's sign: its title, and under it, while a fleet holds first place, "Held by" with that fleet's
 * logo on a disc in its colours and its name. The sprite grows to two rows for it and keeps its pixel scale.
 */
function paintSign(s: THREE.Sprite, title: string, top: ChalRow | null): void {
  const tex = (s.material as THREE.SpriteMaterial).map as THREE.CanvasTexture;
  const c = tex.image as HTMLCanvasElement;
  const two = !!top;
  c.width = 512; c.height = two ? 168 : 96;
  const x = c.getContext('2d')!;
  x.clearRect(0, 0, c.width, c.height);
  x.fillStyle = 'rgba(31,43,51,0.82)';
  x.beginPath();
  x.roundRect(4, 8, 504, c.height - 16, 40);
  x.fill();
  x.textAlign = 'center';
  x.textBaseline = 'middle';
  x.font = '600 40px Fredoka, "Segoe UI", sans-serif';
  x.fillStyle = '#ffffff';
  x.fillText(title, 256, 50, 470);
  if (top) {
    const name = top.name;
    x.font = '500 30px Fredoka, "Segoe UI", sans-serif';
    const lead = 'Held by ';
    x.font = '600 30px Fredoka, "Segoe UI", sans-serif';
    const nameW = Math.min(300, x.measureText(name).width);
    x.font = '500 30px Fredoka, "Segoe UI", sans-serif';
    const leadW = x.measureText(lead).width;
    const disc = 34, gap = 10, total = leadW + disc + gap + nameW;
    let at = 256 - total / 2;
    const y = 118;
    x.textAlign = 'left';
    x.fillStyle = '#c9d3d8';
    x.fillText(lead, at, y);
    at += leadW;
    // the fleet's logo on a disc of its primary colour, ringed in its accent
    x.beginPath();
    x.arc(at + disc / 2, y, disc / 2, 0, Math.PI * 2);
    x.fillStyle = hex(top.brand?.primary ?? 0x7d8a92);
    x.fill();
    x.lineWidth = 3;
    x.strokeStyle = hex(top.brand?.accent ?? 0xffffff);
    x.stroke();
    if (top.brand?.logo) {
      x.textAlign = 'center';
      x.font = '600 22px "Segoe UI Symbol", "Segoe UI", sans-serif';
      x.fillStyle = hex(top.brand.accent ?? 0xffffff);
      x.fillText(top.brand.logo, at + disc / 2, y + 1);
    }
    at += disc + gap;
    x.textAlign = 'left';
    x.font = '600 30px Fredoka, "Segoe UI", sans-serif';
    x.fillStyle = '#ffd24a';
    x.fillText(name, at, y, 300);
  }
  tex.needsUpdate = true;
  // the same size per pixel either way: 3.4 world units across, as tall as the canvas is
  s.scale.set(3.4, 3.4 * (c.height / c.width), 1);
  s.position.y = 2.1 + (two ? 0.22 : 0);
}

