import { hex, scale, type RGB } from '../../world/biomes';
import type { Building } from '../../world/tiles';
import type { OnsenKind } from '../../world/onsenKinds';
import type { Rng } from '../../world/rng';
import { Vis } from '../nightLights';
import { DARK, LEAF, PINE, TRUNK, car, pick, type Draw, type Kit, type P3 } from './kit';
import { eastRoof, frustum, stoneLantern } from './regions/terraces';
import {
  GLASS, GRAVEL, HOT, INDIGO, KAWARA, KAWARA_DARK, LAMPS, LATE, PAPER, PAPER_GLOW, PLASTER, ROOMS, STONE, STONE_DARK,
  TIMBER, TIMBER_DARK, TIMBER_OLD, VERMILION, bather, gasLamp, irimoya, kanban, noren, rockRim, signboard, steam, yukata,
} from './onsenKit';
import { ONSEN_OPEN } from './onsenB';

/**
 * An onsen town's inns and its grand bath (GEN 53, world/onsen.ts): the four ryokan and Dōgo's Honkan.
 *
 *   ryokan        Ginzan: a tall timber inn of three or four storeys, each jettied out over the one below, white
 *                 plaster between dark posts, a balcony of turned rails along every upper floor, a lattice front, the
 *                 name on a tall board by the door, gas lamps either side; a lookout on the roof now and then
 *   fukuzumiro    Hakone's Fukuzumirō (1890): the three-storey Meiji timber front on a stone plinth, its upper floors
 *                 glazed bay to bay behind a balustrade, pent roofs between storeys, a hip-and-gable roof, a curved
 *                 karahafu porch over the door, a rear wing, and the wooded slope behind
 *   resortRyokan  a concrete resort hotel of five to eight floors: a balcony band at every floor, a glass lobby under a
 *                 porte-cochère, a kawara crown or a roof bath, and a bath wing with its rock pool to one side
 *   minshuku      a family inn: two storeys, a vending machine by the door, the sign on a post, futons airing
 *   dogoHonkan    Dōgo Onsen Honkan (1894): three storeys stepping back under layered roofs, karahafu entrances, the
 *                 Shinrō on top with its red glass and the white heron on its roof
 */

const CONCRETE = [0xe2ded6, 0xd8d4cc, 0xece8e0, 0xcfc9be];
const MAPLE = hex(0xc8442a), MAPLE2 = hex(0xe07a2e), MOSS_GREEN = hex(0x5f7a42);

/** A sloped strip of roof standing out of a wall: from the wall at y + drop out to the eave `out` in front at y. */
export function pent(k: Kit, x: number, y: number, z: number, w: number, out: number, col: RGB = KAWARA, drop = 0.07): void {
  const I: P3 = [x, y - 1, z];
  k.quad([x - w / 2, y, z + out], [x + w / 2, y, z + out], [x + w / 2, y + drop, z], [x - w / 2, y + drop, z], col, I);
  k.quad([x - w / 2, y - 0.012, z + out], [x - w / 2, y + drop - 0.012, z], [x + w / 2, y + drop - 0.012, z], [x + w / 2, y - 0.012, z + out], scale(TIMBER, 0.8), [x, y + 1, z]);
  k.box(x, y - 0.012, z + out - 0.01, w, 0.016, 0.02, scale(col, 0.75));
}

/** The same strip round all four sides of a w × d block centred on (x, z): an eave skirt between storeys. */
function skirt(k: Kit, x: number, y: number, z: number, w: number, d: number, out: number, col: RGB = KAWARA): void {
  eastRoof(k, x, y, z, w + out * 2, d + out * 2, 0.07, col, 0.03);
}

/**
 * A karahafu: the curved, bowed gable of a grand entrance, its ridge running back from the front, w across and d deep,
 * eaves at y, the bow rising h in the middle and flicking up again at each end.
 */
export function karahafu(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number, col: RGB = KAWARA): void {
  const n = 8, prof = (u: number) => h * (0.92 * Math.cos((u * Math.PI) / 2) ** 1.6 + 0.12 * u ** 6);
  const pts: [number, number][] = [];
  for (let i = 0; i <= n; i++) { const u = -1 + (2 * i) / n; pts.push([x + (u * w) / 2, y + prof(u)]); }
  for (let i = 0; i < n; i++) {
    const [x0, y0] = pts[i], [x1, y1] = pts[i + 1];
    k.quad([x0, y0, z + d / 2], [x1, y1, z + d / 2], [x1, y1, z - d / 2], [x0, y0, z - d / 2], col, [x, y - 1, z]);
    k.quad([x0, y0 - 0.015, z + d / 2], [x0, y0 - 0.015, z - d / 2], [x1, y1 - 0.015, z - d / 2], [x1, y1 - 0.015, z + d / 2], scale(TIMBER, 0.85), [x, y + 2, z]);
  }
  // the bow's face: a timber bargeboard following the curve, gold studs at its crown
  for (let i = 0; i < n; i++) k.bar([pts[i][0], pts[i][1] - 0.01, z + d / 2 + 0.01], [pts[i + 1][0], pts[i + 1][1] - 0.01, z + d / 2 + 0.01], 0.014, TIMBER_DARK);
  k.box(x, y + h - 0.03, z + d / 2 + 0.012, 0.05, 0.03, 0.012, hex(0xc9a040));
  // the gable's face under the bow: plaster with a timber frame
  k.quad([x - w / 2 + 0.03, y, z + d / 2 - 0.02], [x + w / 2 - 0.03, y, z + d / 2 - 0.02], [x + w * 0.2, y + h * 0.8, z + d / 2 - 0.02], [x - w * 0.2, y + h * 0.8, z + d / 2 - 0.02], PLASTER, [x, y, z]);
}

/** A balcony along the front of a storey: a deck and a rail of close-set turned balusters. */
function balcony(k: Kit, x: number, y: number, z: number, w: number, out: number, rail: RGB = TIMBER, n?: number): void {
  k.box(x, y, z + out / 2, w, 0.02, out, scale(TIMBER, 1.1));
  k.box(x, y + 0.075, z + out, w, 0.014, 0.016, rail);
  k.box(x, y + 0.02, z + out, w, 0.012, 0.012, rail);
  const m = n ?? Math.max(4, Math.round(w / 0.045));
  for (let i = 0; i <= m; i++) k.box(x - w / 2 + (w * i) / m, y + 0.02, z + out, 0.008, 0.055, 0.008, rail);
}

/** A front of lattice (koshi): close vertical slats over a lit room, from y up h, w across, on the face at z. */
export function koshi(k: Kit, x: number, y: number, z: number, w: number, h: number, b: Building, slat: RGB = TIMBER_DARK): void {
  k.pane(x, y, z - 0.004, w, h, 1, PAPER, b.seed % 3 ? ROOMS : LATE, PAPER_GLOW);
  const n = Math.max(6, Math.round(w / 0.035));
  for (let i = 0; i <= n; i++) k.box(x - w / 2 + (w * i) / n, y, z + 0.006, 0.01, h, 0.01, slat);
  k.box(x, y + h, z + 0.006, w, 0.014, 0.014, slat);
}

/** A row of paper windows across a storey's face at z (face 1 front, 3 back), its posts between. */
function screens(k: Kit, b: Building, r: Rng, x: number, y: number, z: number, w: number, h: number, face: 1 | 3, post: RGB = TIMBER): void {
  const n = Math.max(2, Math.round(w / 0.26)), bw = w / n, f = face === 1 ? 1 : -1;
  for (let i = 0; i < n; i++) {
    const cx = x - w / 2 + bw * (i + 0.5);
    k.pane(cx, y + 0.05, z, bw * 0.78, h - 0.1, face, PAPER, r() < 0.7 ? ROOMS : LATE, PAPER_GLOW);
  }
  for (let i = 0; i <= n; i++) k.box(x - w / 2 + bw * i, y, z + f * 0.008, 0.022, h, 0.016, post);
  void b;
}

/** The same down a side (face 0 is +x, 2 is -x). */
function sideScreens(k: Kit, r: Rng, x: number, y: number, z: number, d: number, h: number, face: 0 | 2, post: RGB = TIMBER): void {
  const n = Math.max(2, Math.round(d / 0.28)), bd = d / n, f = face === 0 ? 1 : -1;
  for (let i = 0; i < n; i++) k.pane(x, y + 0.05, z - d / 2 + bd * (i + 0.5), bd * 0.74, h - 0.1, face, PAPER, r() < 0.6 ? ROOMS : LATE, PAPER_GLOW);
  for (let i = 0; i <= n; i++) k.box(x + f * 0.008, y, z - d / 2 + bd * i, 0.016, h, 0.022, post);
}

/** A garden pine: a leaning trunk and flat cloud-pruned tiers. */
function pine(k: Kit, x: number, y: number, z: number, s: number): void {
  k.bar([x, y, z], [x + 0.08 * s, y + 0.34 * s, z + 0.03 * s], 0.022 * s, TRUNK);
  k.cyl(x + 0.08 * s, y + 0.3 * s, z + 0.03 * s, 0.2 * s, 0.06 * s, PINE, 7);
  k.cyl(x - 0.04 * s, y + 0.2 * s, z, 0.14 * s, 0.05 * s, scale(PINE, 1.1), 6);
  k.cyl(x + 0.12 * s, y + 0.42 * s, z + 0.02 * s, 0.11 * s, 0.05 * s, scale(PINE, 0.92), 6);
}

/** A maple: green through the summer, red and orange the rest of the year. */
function maple(k: Kit, x: number, y: number, z: number, s: number): void {
  k.bar([x, y, z], [x, y + 0.24 * s, z], 0.02 * s, TRUNK);
  k.tagged(Vis.Summer, () => { k.dome(x, y + 0.2 * s, z, 0.2 * s, LEAF, 7, 2); k.dome(x + 0.08 * s, y + 0.3 * s, z, 0.12 * s, scale(LEAF, 1.1), 6, 2); });
  k.tagged(Vis.NotSummer, () => { k.dome(x, y + 0.2 * s, z, 0.2 * s, MAPLE, 7, 2); k.dome(x + 0.08 * s, y + 0.3 * s, z, 0.12 * s, MAPLE2, 6, 2); });
}

/** A cedar on the slope behind: a tall dark cone. */
function cedar(k: Kit, x: number, y: number, z: number, s: number): void {
  k.cyl(x, y, z, 0.03 * s, 0.2 * s, TRUNK, 5);
  k.cone(x, y + 0.12 * s, z, 0.2 * s, 0.75 * s, hex(0x2f5a3a), 7);
  k.cone(x, y + 0.42 * s, z, 0.15 * s, 0.6 * s, hex(0x356a42), 7);
}

/** The ryokan names a Ginzan inn's board may carry. */
const INN_NAMES = ['能登屋', '藤屋', '松乃家', '旅館', '古山閣', '旅館'];

// ---- Ginzan's tall timber inn -------------------------------------------------------------------------

const ryokan: Draw = (k, W, D, b, r) => {
  const floors = Math.max(2, Math.min(4, b.floors || 3)), FH = 0.27;
  const bw = W - 0.26, bd = D - 0.62, cz = -0.12;
  const wall = pick(r, [0x5e4330, 0x4a3428, 0x6a4a34]);
  let fz = cz + bd / 2;
  // a low stone footing
  k.box(0, 0, cz, bw + 0.06, 0.04, bd + 0.06, STONE_DARK);
  for (let f = 0; f < floors; f++) {
    const y = 0.04 + f * FH, jut = f * 0.035, z0 = cz + jut / 2, d = bd + jut;
    fz = z0 + d / 2;
    if (f === 0) {
      // the street storey: dark timber, a lattice front and the doorway with its noren
      k.box(0, y, z0, bw, FH, d, wall);
      koshi(k, -bw * 0.27, y + 0.03, fz + 0.002, bw * 0.38, FH * 0.66, b);
      koshi(k, bw * 0.3, y + 0.03, fz + 0.002, bw * 0.3, FH * 0.66, b);
      k.box(0.03, y, fz + 0.001, 0.3, FH * 0.8, 0.012, DARK);
      k.glowBox(0.03, y + 0.01, fz + 0.008, 0.26, FH * 0.55, 0.006, hex(0x5a4a3a), ROOMS, PAPER_GLOW);
      noren(k, 0.03, y + FH * 0.78, fz + 0.012, 0.3, 0.11, pick(r, [0x2f3f6a, 0x6a2a26, 0x2e2e34]));
      kanban(k, -0.25, y + 0.02, fz + 0.04, INN_NAMES[b.seed % INN_NAMES.length], 0.07);
    } else {
      // the guest floors: plaster between dark posts and rails, paper windows, the balcony
      k.box(0, y, z0, bw, FH, d, PLASTER);
      k.box(0, y, z0, bw + 0.01, 0.025, d + 0.01, TIMBER_DARK);
      k.box(0, y + FH - 0.03, z0, bw + 0.01, 0.03, d + 0.01, TIMBER_DARK);
      screens(k, b, r, 0, y + 0.03, fz + 0.002, bw, FH - 0.06, 1, TIMBER_DARK);
      screens(k, b, r, 0, y + 0.03, z0 - d / 2 - 0.002, bw, FH - 0.06, 3, TIMBER_DARK);
      sideScreens(k, r, bw / 2 + 0.002, y + 0.03, z0, d, FH - 0.06, 0, TIMBER_DARK);
      sideScreens(k, r, -bw / 2 - 0.002, y + 0.03, z0, d, FH - 0.06, 2, TIMBER_DARK);
      balcony(k, 0, y + 0.01, fz, bw - 0.04, 0.09, TIMBER_DARK);
      // now and then a guest out on it in a yukata
      if (r() < 0.35) yukata(k, r, (r() - 0.5) * bw * 0.7, y + 0.03, fz + 0.05);
    }
    // the pent roof over each storey's front
    if (f < floors - 1) pent(k, 0, y + FH + 0.005, fz + 0.002, bw + 0.08, 0.14, KAWARA, 0.06);
  }
  const top = 0.04 + floors * FH;
  const ridge = irimoya(k, 0, top, cz + (floors - 1) * 0.0175, bw + 0.2, bd + (floors - 1) * 0.035 + 0.2, 0.3, pick(r, [0x4a4e54, 0x3a3e44, 0x555a60]), 0.05);
  // Notoya's lookout on the ridge
  if (r() < 0.4) {
    const lw = 0.42, ld = 0.36, ly = ridge - 0.12;
    k.box(0, ly, cz, lw, 0.22, ld, PLASTER);
    k.box(0, ly, cz, lw + 0.01, 0.025, ld + 0.01, TIMBER_DARK);
    for (const f of [1, 3] as const) k.pane(0, ly + 0.05, f === 1 ? cz + ld / 2 + 0.002 : cz - ld / 2 - 0.002, lw * 0.8, 0.12, f, GLASS, ROOMS, PAPER_GLOW);
    eastRoof(k, 0, ly + 0.22, cz, lw + 0.2, ld + 0.2, 0.16, KAWARA_DARK, 0.05);
  }
  // gas lamps either side of the door, out by the lane
  for (const sx of [-1, 1]) gasLamp(k, sx * (bw / 2 - 0.05), 0, D / 2 - 0.12, 0.36);
  // the bath's steam at the back, now and then
  if (r() < 0.5) steam(k, (r() - 0.5) * bw * 0.6, top + 0.1, cz - bd / 2, 0.8, 2, 0.6, b.seed);
};

// ---- Hakone's Fukuzumirō ----------------------------------------------------------------------------

const fukuzumiro: Draw = (k, W, D, b, r) => {
  const FH = 0.3, plinth = 0.1;
  const mw = Math.min(2.6, W - 0.3), md = 1.05, mz = D / 2 - 0.35 - md / 2;
  // the stone plinth it stands on, and the wooded slope behind it
  frustum(k, 0, 0, mz - 0.2, mw + 0.25, md + 0.75, mw + 0.15, md + 0.65, plinth, STONE_DARK, GRAVEL);
  const back = -D / 2 + 0.35;
  frustum(k, -0.3, 0, back, W - 0.2, 0.7, W - 0.6, 0.4, 0.35, hex(0x6a5a40), MOSS_GREEN);
  for (let i = 0; i < 6; i++) cedar(k, -W / 2 + 0.35 + i * ((W - 0.7) / 5), 0.3, back - 0.05 + (i % 2) * 0.12, 1.2 + (i % 3) * 0.2);
  maple(k, -W / 2 + 0.35, plinth, mz - md / 2 - 0.25, 1.4);
  pine(k, W / 2 - 0.35, plinth, mz - md / 2 - 0.35, 1.2);
  // the front block: three storeys
  let y = plinth;
  for (let f = 0; f < 3; f++) {
    const fz = mz + md / 2;
    if (f === 0) {
      k.box(0, y, mz, mw, FH, md, TIMBER_OLD);
      koshi(k, -mw * 0.22, y + 0.04, fz + 0.002, mw * 0.45, FH * 0.66, b);
      koshi(k, mw * 0.33, y + 0.04, fz + 0.002, mw * 0.25, FH * 0.66, b);
    } else {
      // Meiji glass: bay after bay of small panes in thin frames, a balustrade in front
      k.box(0, y, mz, mw, FH, md, PLASTER);
      k.box(0, y, mz, mw + 0.01, 0.03, md + 0.01, TIMBER_DARK);
      k.box(0, y + FH - 0.04, mz, mw + 0.01, 0.04, md + 0.01, TIMBER_DARK);
      const n = 9, bay = mw / n;
      for (let i = 0; i < n; i++) {
        const cx = -mw / 2 + bay * (i + 0.5);
        k.pane(cx, y + 0.05, fz + 0.003, bay * 0.86, FH - 0.11, 1, GLASS, (i + f) % 3 ? ROOMS : LATE, PAPER_GLOW);
        k.box(cx, y + 0.05 + (FH - 0.11) / 2, fz + 0.008, bay * 0.86, 0.008, 0.006, TIMBER_DARK);
      }
      for (let i = 0; i <= n; i++) k.box(-mw / 2 + bay * i, y + 0.03, fz + 0.006, 0.018, FH - 0.07, 0.014, TIMBER_DARK);
      sideScreens(k, r, mw / 2 + 0.002, y + 0.03, mz, md, FH - 0.07, 0, TIMBER_DARK);
      sideScreens(k, r, -mw / 2 - 0.002, y + 0.03, mz, md, FH - 0.07, 2, TIMBER_DARK);
      balcony(k, 0, y + 0.012, fz, mw + 0.02, 0.1, TIMBER_DARK);
    }
    // a pent roof all round between the storeys
    if (f < 2) skirt(k, 0, y + FH, mz, mw, md, 0.13);
    y += FH + (f < 2 ? 0.04 : 0);
  }
  irimoya(k, 0, y, mz, mw + 0.34, md + 0.34, 0.5, KAWARA, 0.08);
  // the rear wing, two storeys, running back at one side
  const wx = mw / 2 - 0.5, wd = 1.0, wz = mz - md / 2 - wd / 2 + 0.05;
  k.box(wx, plinth, wz, 0.85, FH, wd, TIMBER_OLD);
  k.box(wx, plinth + FH + 0.03, wz, 0.85, FH, wd, PLASTER);
  sideScreens(k, r, wx + 0.427, plinth + FH + 0.06, wz, wd, FH - 0.07, 0, TIMBER_DARK);
  sideScreens(k, r, wx - 0.427, plinth + FH + 0.06, wz, wd, FH - 0.07, 2, TIMBER_DARK);
  skirt(k, wx, plinth + FH, wz, 0.85, wd, 0.1);
  irimoya(k, wx, plinth + FH * 2 + 0.03, wz, 1.1, wd + 0.25, 0.38, KAWARA_DARK, 0.06);
  // the porch: a karahafu over the door at the front's left, the name over it, lanterns either side
  const px = -mw / 2 + 0.45, pz = mz + md / 2 + 0.2;
  for (const sx of [-1, 1]) k.box(px + sx * 0.2, plinth, pz + 0.15, 0.04, 0.3, 0.04, TIMBER_DARK);
  k.box(px, plinth, pz, 0.46, 0.012, 0.42, GRAVEL);
  karahafu(k, px, plinth + 0.3, pz + 0.03, 0.56, 0.5, 0.14);
  signboard(k, px, plinth + 0.47, pz + 0.3, '福住楼', 0.07);
  noren(k, px, plinth + 0.26, mz + md / 2 + 0.008, 0.3, 0.1, INDIGO);
  for (const sx of [-1, 1]) {
    k.box(px + sx * 0.2, plinth + 0.18, pz + 0.18, 0.006, 0.05, 0.006, DARK);
    k.glowBox(px + sx * 0.2, plinth + 0.1, pz + 0.18, 0.055, 0.08, 0.055, hex(0xf2ead8), LAMPS, hex(0xffe6b8));
  }
  stoneLantern(k, mw / 2 - 0.1, plinth, D / 2 - 0.2, 1.3);
  // the bath's steam rising from behind
  steam(k, wx, plinth + FH * 2 + 0.35, wz - 0.2, 1, 3, 0.7, b.seed);
};

// ---- a concrete resort ryokan -----------------------------------------------------------------------

const resortRyokan: Draw = (k, W, D, b, r) => {
  const floors = Math.max(4, Math.min(9, b.floors || 6)), FH = 0.25;
  const conc = pick(r, CONCRETE);
  const sw = Math.min(W - 1.0, 3.0), sd = 1.15, sx = -(W - sw) / 2 + 0.2, sz = -0.25;
  const fz = sz + sd / 2;
  // the slab: a balcony band at every floor, its rooms' windows behind
  k.box(sx, 0, sz, sw, floors * FH, sd, conc);
  for (let f = 1; f < floors; f++) {
    const y = f * FH;
    k.box(sx, y - 0.02, sz + 0.06, sw + 0.04, 0.035, sd + 0.12, scale(conc, 1.06));
    k.box(sx, y + 0.015, fz + 0.115, sw, 0.07, 0.01, scale(GLASS, 0.9));
    const n = Math.max(4, Math.round(sw / 0.32));
    for (let i = 0; i < n; i++) k.pane(sx - sw / 2 + (sw / n) * (i + 0.5), y + 0.03, fz + 0.002, (sw / n) * 0.82, FH - 0.07, 1, GLASS, (i * 7 + f * 3 + b.seed) % 4 ? ROOMS : LATE, PAPER_GLOW);
    for (const s of [1, -1] as const) {
      const m = Math.max(2, Math.round(sd / 0.36));
      for (let i = 0; i < m; i++) k.pane(sx + s * (sw / 2 + 0.002), y + 0.04, sz - sd / 2 + (sd / m) * (i + 0.5), (sd / m) * 0.6, FH - 0.09, s > 0 ? 0 : 2, GLASS, ROOMS, PAPER_GLOW);
    }
  }
  // the lobby: glass from wall to wall, the porte-cochère out over the drive
  k.pane(sx, 0.02, fz + 0.003, sw * 0.9, FH * 0.8, 1, hex(0xb8ccd2), LAMPS, PAPER_GLOW);
  k.box(sx, FH * 0.85, fz + 0.3, 0.9, 0.05, 0.6, scale(conc, 0.95));
  for (const s of [-1, 1]) k.box(sx + s * 0.4, 0, fz + 0.55, 0.04, FH * 0.85, 0.04, scale(conc, 0.8));
  noren(k, sx, FH * 0.78, fz + 0.012, 0.36, 0.1, INDIGO);
  signboard(k, sx, FH * 0.9, fz + 0.605, '旅館', 0.08);
  const roof = floors * FH;
  if (b.seed % 2) {
    // a kawara crown over the slab
    k.box(sx, roof, sz, sw + 0.02, 0.04, sd + 0.02, scale(conc, 0.9));
    eastRoof(k, sx, roof + 0.04, sz, sw + 0.3, sd + 0.3, 0.32, KAWARA, 0.06);
  } else {
    // a bath on the roof, behind a screen, steaming; the hotel's name standing over the front edge
    k.box(sx, roof, sz, sw + 0.02, 0.06, sd + 0.02, scale(conc, 0.9));
    k.box(sx + sw * 0.18, roof + 0.06, sz, sw * 0.5, 0.012, sd * 0.7, hex(0x8a7a62));
    k.disc(sx + sw * 0.18, roof + 0.075, sz, sd * 0.28, HOT, 12, sd * 0.24);
    rockRim(k, r, sx + sw * 0.18, roof + 0.075, sz, sd * 0.3, sd * 0.26, 10);
    for (let i = 0; i < 3; i++) bather(k, r, sx + sw * 0.18 + (i - 1) * 0.12, roof + 0.075, sz + (i % 2) * 0.08);
    steam(k, sx + sw * 0.18, roof + 0.1, sz, 1, 3, 0.6, b.seed);
    for (let i = 0; i < 8; i++) k.box(sx - sw / 2 + 0.1, roof + 0.06, sz - sd / 2 + 0.07 + i * (sd / 8), 0.02, 0.16, 0.02, hex(0xb8a060));
    kanban(k, sx - sw / 2 + 0.25, roof + 0.02, fz + 0.02, 'ホテル', 0.11, hex(0x8a2a22));
  }
  // the bath wing: one storey out to the side, its rock pool in a garden behind a bamboo fence
  const bx = sx + sw / 2 + 0.55, bwid = W / 2 - (sx + sw / 2) - 0.15;
  if (bwid > 0.5) {
    k.box(bx, 0, sz - 0.25, Math.min(bwid, 0.8), FH * 1.3, 0.6, TIMBER_OLD);
    eastRoof(k, bx, FH * 1.3, sz - 0.25, Math.min(bwid, 0.8) + 0.2, 0.8, 0.22, KAWARA_DARK, 0.05);
    const px = bx, pz = sz + 0.45;
    k.disc(px, 0.02, pz, 0.32, HOT, 12, 0.24);
    rockRim(k, r, px, 0.02, pz, 0.34, 0.26);
    for (let i = 0; i < 2; i++) bather(k, r, px - 0.08 + i * 0.16, 0.02, pz + (i ? 0.05 : -0.04));
    steam(k, px, 0.06, pz, 0.9, 2, 0.6, b.seed + 3);
    for (let i = 0; i < 10; i++) k.box(px - 0.42 + i * 0.09, 0, pz + 0.38, 0.025, 0.24, 0.025, hex(0xb8a060));
  }
  // the drive and a car or two waiting
  k.box(sx, 0, D / 2 - 0.3, 1.2, 0.006, 0.5, hex(0x6a6a6e));
  car(k, sx - 0.25, D / 2 - 0.3, true, hex(0x2a2a30), 'cabbie');
  if (r() < 0.6) car(k, sx + 0.35, D / 2 - 0.3, true, pick(r, [0xf4f2ec, 0x3a3f45, 0xb9bdc2]));
  pine(k, -W / 2 + 0.3, 0, D / 2 - 0.4, 1.3);
};

// ---- a family minshuku ------------------------------------------------------------------------------

const minshuku: Draw = (k, W, D, b, r) => {
  const FH = 0.25, hw = Math.min(W - 0.2, 1.6), hd = D - 0.38, hz = -0.1;
  const fz = hz + hd / 2;
  k.box(0, 0, hz, hw, FH, hd, pick(r, [0x6a4a34, 0x5e4330]));
  k.box(0, FH, hz, hw, FH, hd, pick(r, [0xf2eee4, 0xece4d4]));
  k.box(0, FH, hz, hw + 0.01, 0.02, hd + 0.01, TIMBER_DARK);
  // the sliding glass door and the noren
  k.pane(-hw * 0.12, 0.02, fz + 0.003, Math.min(0.32, hw * 0.4), FH * 0.75, 1, GLASS, LAMPS, PAPER_GLOW);
  noren(k, -hw * 0.12, FH * 0.8, fz + 0.01, Math.min(0.3, hw * 0.36), 0.09, pick(r, [0x2f3f6a, 0x7a2a26, 0x3a5a3a]), '民');
  screens(k, b, r, 0, FH + 0.03, fz + 0.002, hw * 0.9, FH - 0.07, 1, TIMBER_DARK);
  pent(k, 0, FH + 0.005, fz, hw + 0.06, 0.12, KAWARA, 0.05);
  eastRoof(k, 0, FH * 2, hz, hw + 0.14, hd + 0.14, 0.2, pick(r, [0x4a4e54, 0x3a3e44, 0x5a4a44]), 0.035);
  // futons airing over the rail on a fine day
  if (r() < 0.5) for (let i = 0; i < 2; i++) k.box(hw * (0.08 + i * 0.22), FH * 1.35, fz + 0.03, 0.18, 0.12, 0.012, pick(r, [0xf2ece0, 0xd8a8a0, 0xa8c0d8]));
  // the sign on its post, the vending machine lit by the door, a bicycle and pots
  kanban(k, hw / 2 + 0.02, 0.02, D / 2 - 0.12, '民宿', 0.075, hex(0xf2eee4));
  k.box(hw / 2 + 0.02, 0, D / 2 - 0.12, 0.02, 0.04, 0.02, TIMBER_DARK);
  const vx = hw * 0.3;
  k.box(vx, 0, fz + 0.06, 0.13, 0.22, 0.09, pick(r, [0xe8e8ec, 0xc8302a, 0x2a5aa8]));
  k.glowBox(vx, 0.1, fz + 0.106, 0.1, 0.08, 0.004, hex(0xd8e4ec), [17, 30, 1.3], hex(0xe8f4ff));
  if (r() < 0.6) {
    const bxp = -hw / 2 + 0.12;
    k.hoop(bxp - 0.05, 0.04, fz + 0.1, 0.035, 0.006, DARK, 8, 'zy');
    k.hoop(bxp + 0.05, 0.04, fz + 0.1, 0.035, 0.006, DARK, 8, 'zy');
    k.bar([bxp - 0.05, 0.04, fz + 0.1], [bxp + 0.05, 0.07, fz + 0.1], 0.006, hex(0x3a7a9a));
  }
  for (let i = 0; i < 3; i++) k.cyl(-hw / 2 + 0.3 + i * 0.07, 0, fz + 0.06, 0.025, 0.04, hex(0x9a5a3a), 6, hex(0x5a8a4a));
};

// ---- Dōgo Onsen Honkan ------------------------------------------------------------------------------

const dogoHonkan: Draw = (k, W, D, b, r) => {
  const FH = 0.3, cz = -0.1;
  const base = 0.08;
  k.box(0, 0, cz, W - 0.2, base, D - 0.5, STONE, scale(STONE, 1.05));
  // three storeys stepping back, a skirt of kawara between each
  const tiers: [number, number][] = [[W - 0.5, D - 0.85], [W - 0.95, D - 1.2], [W - 1.45, D - 1.6]];
  let y = base;
  tiers.forEach(([w, d], f) => {
    const fz = cz + d / 2;
    k.box(0, y, cz, w, FH, d, f === 0 ? TIMBER_OLD : PLASTER);
    k.box(0, y, cz, w + 0.01, 0.025, d + 0.01, TIMBER_DARK);
    k.box(0, y + FH - 0.03, cz, w + 0.01, 0.03, d + 0.01, TIMBER_DARK);
    if (f === 0) {
      koshi(k, -w * 0.28, y + 0.04, fz + 0.002, w * 0.3, FH * 0.62, b);
      koshi(k, w * 0.28, y + 0.04, fz + 0.002, w * 0.3, FH * 0.62, b);
      koshi(k, 0, y + 0.04, cz - d / 2 - 0.004, w * 0.6, FH * 0.62, b);
    } else {
      screens(k, b, r, 0, y + 0.03, fz + 0.002, w, FH - 0.06, 1, TIMBER_DARK);
      screens(k, b, r, 0, y + 0.03, cz - d / 2 - 0.002, w, FH - 0.06, 3, TIMBER_DARK);
    }
    sideScreens(k, r, w / 2 + 0.002, y + 0.03, cz, d, FH - 0.06, 0, TIMBER_DARK);
    sideScreens(k, r, -w / 2 - 0.002, y + 0.03, cz, d, FH - 0.06, 2, TIMBER_DARK);
    // the top storey's open gallery: bathers in yukata cooling off at the rail
    if (f === 2) {
      balcony(k, 0, y + 0.01, fz, w, 0.12, VERMILION);
      for (let i = 0; i < 3; i++) yukata(k, r, -w / 2 + 0.2 + i * (w - 0.4) / 2, y + 0.03, fz + 0.07);
    }
    y += FH;
    if (f < 2) skirt(k, 0, y, cz, w, d, 0.16, KAWARA);
    y += 0.04;
  });
  const [tw, td] = tiers[2];
  const ridge = irimoya(k, 0, y - 0.04, cz, tw + 0.4, td + 0.4, 0.46, KAWARA, 0.08);
  // the Shinrō: its red glass lit after dark, the white heron on its roof
  const sy = ridge - 0.1, s = 0.36;
  k.box(0, sy, cz, s + 0.04, 0.03, s + 0.04, TIMBER_DARK);
  for (const f of [0, 1, 2, 3] as const) {
    const [px, pz] = f === 0 ? [s / 2 + 0.002, cz] : f === 1 ? [0, cz + s / 2 + 0.002] : f === 2 ? [-s / 2 - 0.002, cz] : [0, cz - s / 2 - 0.002];
    k.pane(px, sy + 0.05, pz, s * 0.8, 0.16, f, hex(0xb83a2a), [17, 30, 1.6], hex(0xff5a3a));
  }
  k.box(0, sy + 0.03, cz, s, 0.2, s, hex(0x9a2e22));
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * s / 2, sy + 0.03, cz + sz * s / 2, 0.025, 0.2, 0.025, TIMBER_DARK);
  const hy = eastRoof(k, 0, sy + 0.23, cz, s + 0.2, s + 0.2, 0.16, KAWARA_DARK, 0.04);
  // the heron: a white body, a long neck and a beak, wings half spread
  k.box(0, hy, cz, 0.06, 0.04, 0.03, PLASTER);
  k.bar([0.02, hy + 0.03, cz], [0.04, hy + 0.1, cz], 0.008, PLASTER);
  k.box(0.05, hy + 0.1, cz, 0.03, 0.012, 0.01, hex(0xd8a040));
  for (const sz of [-1, 1]) k.quad([-0.02, hy + 0.03, cz], [0.02, hy + 0.03, cz], [0.0, hy + 0.06, cz + sz * 0.07], [-0.04, hy + 0.06, cz + sz * 0.06], PLASTER, [0, hy - 1, cz]);
  // the entrance: a karahafu porch, the name over it and the ゆ noren
  const ez = cz + tiers[0][1] / 2;
  for (const sx of [-1, 1]) k.box(sx * 0.24, base, ez + 0.3, 0.045, 0.32, 0.045, TIMBER_DARK);
  karahafu(k, 0, base + 0.32, ez + 0.18, 0.66, 0.46, 0.16);
  signboard(k, 0, base + 0.5, ez + 0.42, '道後温泉', 0.07);
  noren(k, 0, base + 0.27, ez + 0.008, 0.34, 0.12, INDIGO, 'ゆ');
  for (const sx of [-1, 1]) {
    k.box(sx * 0.24, base + 0.21, ez + 0.36, 0.006, 0.04, 0.006, DARK);
    k.glowBox(sx * 0.24, base + 0.12, ez + 0.36, 0.06, 0.09, 0.06, hex(0xd8402e), LAMPS, hex(0xff7a5a));
  }
  // a second karahafu over the side door
  karahafu(k, -tiers[0][0] / 2 - 0.12, base + 0.3, cz - 0.3, 0.46, 0.3, 0.12, KAWARA_DARK);
  // guests on the square, a lantern, the boiler's steam
  for (let i = 0; i < 4; i++) yukata(k, r, (r() - 0.5) * (W - 0.6), 0, D / 2 - 0.2 - r() * 0.15);
  stoneLantern(k, -W / 2 + 0.25, 0, D / 2 - 0.25, 1.3);
  stoneLantern(k, W / 2 - 0.25, 0, D / 2 - 0.25, 1.3);
  steam(k, tiers[0][0] / 2 - 0.2, base + FH * 2 + 0.2, cz - tiers[0][1] / 2 + 0.15, 1, 3, 0.8, b.seed);
};

/** Every onsen kind's model (world/onsenKinds.ts), spread into townMesh's table. */
export const ONSEN_DRAW: Record<OnsenKind, Draw> = { ryokan, fukuzumiro, resortRyokan, minshuku, dogoHonkan, ...ONSEN_OPEN };
