/**
 * Neighbours (docs/social.html, "The dealings ledger"): the fleets you have most to do with, and what each of you
 * has done toward the other. Three parts:
 *
 * - The tab of the social window: every fleet in your ledger on the left, strongest first, with its two or three
 *   biggest reasons ("$4,200 paid at your doors · 61 crossings of your works"), under Lately, All time and Owed
 *   thanks (the fleets that give you more than you give them); the picked fleet on the right, both directions
 *   side by side as paired bars, the towns you both carry for, and where each of you leads on the standings.
 * - The pair store the fleet card reads for its "You and them" (net/fleetCard.ts).
 * - The game's two reports to the ledger: a minute driven within ten tiles of another player's vehicle, both
 *   moving (`beside`), and a door of another fleet's passed within six tiles, once a door a game day (`call`).
 *   Everything else the ledger counts the server already hears (server/social.ts).
 */
import { esc, money } from '../game/cargoHud';
import { chip, css } from '../game/firmSpec';
import { METRICS } from '../game/metrics';
import { badgeUrl } from '../render/fleetBadges';
import type { SocialTabBody } from '../game/socialWindow';
import type { OnlineExtra } from './online';
import type { BoardRow, CellDoc, ClientMsg, ServerMsg, Welcome } from '../../shared/protocol';
import { COUNTERS, COUNTER_LABEL, pairScore, pairWhy, type Counter, type Counts, type NeighbourRow } from '../../shared/social';

/** A pair as the server last told it. */
export interface PairView { o: Counts; i: Counts; lo: Counts; li: Counts; towns: string[]; at: number }

type View = 'lately' | 'all' | 'owed';
const VIEW_LABEL: Record<View, string> = { lately: 'Lately', all: 'All time', owed: 'Owed thanks' };

/** Tiles within which two vehicles are "beside" each other, and a door is called at. */
const BESIDE_TILES = 10, CALL_TILES = 6;
/** Seconds between asks for the ranking, and for one pair. */
const ASK_ROWS_S = 15, ASK_PAIR_S = 10;

export interface NeighboursHost {
  online(): boolean;
  me(): string | null;
  /** My shared fleet's other players: nothing between us is counted. */
  mates(): Set<string>;
  post(m: ClientMsg): void;
  /** Where I am, in world tiles, and whether I'm moving; null while not driving. */
  myPos(): { x: number; z: number; moving: boolean } | null;
  /** Other players' vehicles drawn near me: whose, where (world tiles), moving or not. */
  remotes(): { pid: string; x: number; z: number; moving: boolean }[];
  /** Other fleets' doors within r tiles of a point: their lot keys. */
  doorsNear(x: number, z: number, r: number): string[];
  /** The game day, for one call a door a day. */
  day(): number;
  /** The board's lines, and my own numbers, for the standings comparison. */
  rows(): BoardRow[];
  myV(): Record<string, number>;
  myLivery(): [number, number];
  /** A town's name from its key, if it is known. */
  townName(key: string): string | null;
  /** The neighbour ids changed (the boards' Neighbours scope reads them). */
  changed(rows: NeighbourRow[]): void;
  /** A fleet's card (net/fleetCard.ts), in the Fleets tab. */
  openCard(pid: string): void;
  /** Phase 4: the player whose vehicle the camera is following, if it is another player's (their Most Followed). */
  following(): string | null;
}

export class Neighbours implements OnlineExtra, SocialTabBody {
  onlineOnly = true;
  private rows: NeighbourRow[] = [];
  private heard = false;
  private pairs = new Map<string, PairView>();
  private askedRows = -1e9;
  private askedPair = new Map<string, number>();
  private view: View = 'lately';
  private pick: string | null = null;
  // the reports
  private secs = new Map<string, number>();
  private called = new Map<string, number>();
  private reportT = 0;
  private callT = 0;
  /** Seconds the camera has followed each player's vehicles since the last minute reported. */
  private watching = new Map<string, number>();
  /** The window redraws when an answer comes in. */
  onData: () => void = () => {};

  constructor(private host: NeighboursHost) {}

  // ---- the online session ----
  welcome(_w: Welcome): void { this.reset(); }
  cell(_k: string, _doc: CellDoc): void { /* nothing per cell */ }
  got(m: ServerMsg): boolean {
    if (m.t === 'neighbours') {
      this.rows = m.rows;
      this.heard = true;
      this.host.changed(m.rows);
      this.onData();
      return true;
    }
    if (m.t === 'pair') {
      this.pairs.set(m.id, { o: m.o, i: m.i, lo: m.lo, li: m.li, towns: m.towns, at: performance.now() });
      this.onData();
      return true;
    }
    return false;
  }
  ready(): void { this.ask(true); }
  forget(): void { /* nothing per cell */ }
  reset(): void {
    this.rows = []; this.heard = false; this.pairs.clear(); this.askedPair.clear(); this.askedRows = -1e9;
    this.secs.clear(); this.called.clear(); this.pick = null;
  }

  /** Every frame: once a second, the minutes beside other players; every two, the doors passed. */
  frame(dt: number): void {
    if (!this.host.online()) return;
    this.reportT += dt;
    this.callT += dt;
    if (this.reportT >= 1) {
      const step = this.reportT;
      this.reportT = 0;
      // a minute of my camera on another player's vehicle: toward their Most Followed
      const f = this.host.following();
      if (f && f !== this.host.me() && !this.host.mates().has(f)) {
        const s = (this.watching.get(f) ?? 0) + step;
        if (s >= 60) { this.host.post({ t: 'watched', id: f }); this.watching.set(f, s - 60); } else this.watching.set(f, s);
      }
      const me = this.host.myPos();
      if (me?.moving) {
        const mates = this.host.mates(), mine = this.host.me();
        const near = new Set<string>();
        for (const r of this.host.remotes()) {
          if (!r.moving || r.pid === mine || mates.has(r.pid) || near.has(r.pid)) continue;
          if (Math.hypot(r.x - me.x, r.z - me.z) <= BESIDE_TILES) near.add(r.pid);
        }
        for (const pid of near) {
          const s = (this.secs.get(pid) ?? 0) + step;
          if (s >= 60) { this.host.post({ t: 'beside', id: pid }); this.secs.set(pid, s - 60); } else this.secs.set(pid, s);
        }
      }
    }
    if (this.callT >= 2) {
      this.callT = 0;
      const me = this.host.myPos();
      if (me) {
        const day = this.host.day();
        for (const k of this.host.doorsNear(me.x, me.z, CALL_TILES)) {
          if (this.called.get(k) === day) continue;
          this.called.set(k, day);
          this.host.post({ t: 'call', k });
        }
      }
    }
  }

  /** The ranking, asked for again at most every ASK_ROWS_S seconds. */
  private ask(force = false): void {
    if (!this.host.online()) return;
    const now = performance.now();
    if (!force && now - this.askedRows < ASK_ROWS_S * 1000) return;
    this.askedRows = now;
    this.host.post({ t: 'neighbours' });
  }

  /** The pair for one player, as last told; asked for when it is old. The fleet card reads it too. */
  pairOf(pid: string): PairView | null {
    const had = this.pairs.get(pid) ?? null;
    const now = performance.now();
    if (this.host.online() && (!had || now - had.at > ASK_PAIR_S * 1000) && now - (this.askedPair.get(pid) ?? -1e9) > ASK_PAIR_S * 1000) {
      this.askedPair.set(pid, now);
      this.host.post({ t: 'pair', id: pid });
    }
    return had;
  }

  /** The fleets I have most dealings with: every player in them (for the boards' Neighbours scope). */
  nearIds(n = 20): string[] { return this.rows.slice(0, n).flatMap((r) => r.ids); }

  // ---- the tab ----
  opened(): void { this.ask(true); }
  tick(): void { this.ask(); }

  /** Open the tab on one fleet (Compare on a card). */
  show(pid: string): void { this.pick = pid; }

  press(target: HTMLElement): boolean {
    const v = target.closest('[data-nview]') as HTMLElement | null;
    if (v) { this.view = v.dataset.nview as View; return true; }
    const p = target.closest('[data-npick]') as HTMLElement | null;
    if (p) { this.pick = p.dataset.npick!; return true; }
    const c = target.closest('[data-ncard]') as HTMLElement | null;
    if (c) { this.host.openCard(c.dataset.ncard!); return true; }
    return false;
  }

  private counts(r: { o: Counts; i: Counts; lo: Counts; li: Counts }): { o: Counts; i: Counts } {
    return this.view === 'lately' ? { o: r.lo, i: r.li } : { o: r.o, i: r.i };
  }

  /** The rows under the view in force: lately or all time by score; owed thanks where they give more than you. */
  private listed(): { r: NeighbourRow; score: number; o: Counts; i: Counts }[] {
    const all = this.rows.map((r) => {
      const c = this.view === 'owed' ? { o: r.o, i: r.i } : this.counts(r);
      return { r, ...c, score: pairScore(c.o, c.i) };
    });
    if (this.view === 'owed') {
      return all.map((x) => ({ ...x, score: pairScore({}, x.i) - pairScore(x.o, {}) })).filter((x) => x.score > 0.5).sort((a, b) => b.score - a.score);
    }
    return all.filter((x) => x.score > 0).sort((a, b) => b.score - a.score);
  }

  html(): { left: string; right: string } {
    const chips = `<div class="scope">${(Object.keys(VIEW_LABEL) as View[]).map((v) => `<button type="button" data-nview="${v}" class="${this.view === v ? 'on' : ''}">${VIEW_LABEL[v]}</button>`).join('')}</div>`;
    const list = this.listed();
    const top = Math.max(1, ...list.map((x) => x.score));
    if (this.pick === null && list.length) this.pick = list[0].r.id;
    const rows = list.map(({ r, o, i, score }) => {
      const why = pairWhy(o, i, money);
      const livery: [number, number] = [r.brand?.primary ?? 0x7d8a92, r.brand?.accent ?? 0xffffff];
      return `<li class="${this.pick === r.id ? 'on' : ''}"><button type="button" class="pick" data-npick="${esc(r.id)}">${chip(livery, r.brand?.logo || undefined)}<span class="what"><b>${esc(r.name)}</b>`
        + `${why.map((w) => `<small>${esc(w)}</small>`).join('')}<span class="nbar"><i style="width:${Math.max(3, (score / top) * 100).toFixed(1)}%;background:${css(livery[0])}"></i></span></span></button></li>`;
    }).join('');
    const lead = this.view === 'owed'
      ? 'Fleets that have done more for you than you for them: rent at your doors, crossings of your works, hearts. A visit or a heart back goes a long way.'
      : this.view === 'lately' ? 'The fleets you have had most to do with over the last two to four weeks, both ways.' : 'Everyone you have had dealings with in this world, both ways.';
    const empty = !this.heard ? 'Asking the server…' : this.view === 'owed' ? 'Nobody owes you thanks, and you owe nobody: square with everyone.'
      : 'No dealings yet. Rent at another fleet’s doors, a crossing of a bridge they built, a heart, a whisper or a few minutes driving beside them all count here.';
    const left = `${chips}<p class="lead">${lead}</p><ul class="fleets neighbours">${rows || `<li class="none">${empty}</li>`}</ul>
      <p class="foot">Counted by the server from what it already sees: rent paid at doors, crossings of works, days calling at a fleet’s doors, hearts and thumbs-up, whispers, records taken, and minutes driven beside each other. A shared fleet counts as one.</p>`;
    const row = this.rows.find((r) => r.id === this.pick) ?? null;
    return { left, right: row ? this.pairHtml(row) : '<p class="none">Pick a fleet to see what you have done for each other.</p>' };
  }

  /** The two-sided bars: what you did toward them on the left in your colour, they toward you on the right in theirs. */
  bars(o: Counts, i: Counts, mine: number, theirs: number): string {
    const lines = COUNTERS.filter((k) => (o[k] ?? 0) > 0 || (i[k] ?? 0) > 0);
    if (!lines.length) return '<p class="none">Nothing between you in this window yet.</p>';
    const val = (k: Counter, n: number) => (COUNTER_LABEL[k].money ? money(n) : n.toLocaleString('en-US'));
    return `<div class="pairbars"><div class="ph"><span>You → them</span><span></span><span>Them → you</span></div>${lines.map((k) => {
      const a = o[k] ?? 0, b = i[k] ?? 0, top = Math.max(1, a, b);
      return `<div class="pr"><span class="l"><em>${val(k, a)}</em><i style="width:${((a / top) * 100).toFixed(1)}%;background:${css(mine)}"></i></span>`
        + `<b>${esc(COUNTER_LABEL[k].name)}</b><span class="r"><i style="width:${((b / top) * 100).toFixed(1)}%;background:${css(theirs)}"></i><em>${val(k, b)}</em></span></div>`;
    }).join('')}</div>`;
  }

  /** Where each of you leads on the eighteen standings metrics, from their board line and your own numbers. */
  scorecard(pid: string): string {
    const row = this.host.rows().find((r) => r.id === pid);
    if (!row?.v) return '';
    const mine = this.host.myV();
    const theirs = { ...row.v, worth: row.worth, units: row.units, held: row.towns } as Record<string, number>;
    let lead = 0, trail = 0;
    const cells = METRICS.map((m) => {
      const a = mine[m.key], b = theirs[m.key];
      if (a === undefined || b === undefined || a === b) return `<span class="eq" title="${esc(m.hint)}">${esc(m.label)}</span>`;
      const ahead = m.low ? a < b : a > b;
      if (ahead) lead++; else trail++;
      return `<span class="${ahead ? 'win' : 'lose'}" title="${esc(m.label)}: you ${m.money ? money(a) : a} · them ${m.money ? money(b) : b}">${ahead ? '▲' : '▼'} ${esc(m.label)}</span>`;
    }).join('');
    return `<section class="fc-sec"><h4>Head to head <small>you lead ${lead} of ${METRICS.length}${trail ? `, they lead ${trail}` : ''}</small></h4><div class="h2h">${cells}</div></section>`;
  }

  /** The towns you both carry for, by name where the game knows it. */
  townsHtml(towns: string[]): string {
    if (!towns.length) return '';
    const names = towns.map((k) => this.host.townName(k) ?? `a town at ${k.split('#')[0]}`);
    return `<section class="fc-sec"><h4>Towns you both carry for <small>${towns.length}</small></h4><p>${names.map(esc).join(' · ')}</p></section>`;
  }

  private pairHtml(r: NeighbourRow): string {
    const p = this.pairOf(r.id);
    const livery: [number, number] = [r.brand?.primary ?? 0x7d8a92, r.brand?.accent ?? 0xffffff];
    const shield = `<img class="shield" src="${badgeUrl({ logo: r.brand?.logo ?? '', primary: livery[0], accent: livery[1] }, 'shield')}" alt="">`;
    const c = this.counts(p ?? r);
    const all = pairScore(r.o, r.i), late = pairScore(r.lo, r.li);
    const head = `<header class="fc-head">${shield}<div><h3>${esc(r.name)}</h3><div class="fc-who">${r.ids.length > 1 ? `a shared fleet of ${r.ids.length}` : 'a fleet of one'} · score ${all.toFixed(1)} all time, ${late.toFixed(1)} lately</div></div></header>`;
    const acts = `<div class="fc-acts"><button type="button" class="fc-btn" data-ncard="${esc(r.id)}">Open their card</button></div>`;
    const view = this.view === 'lately' ? 'Lately' : 'All time';
    return `<div class="fcard pair">${head}${acts}<section class="fc-sec"><h4>What you have done for each other <small>${view}</small></h4>${this.bars(c.o, c.i, this.host.myLivery()[0], livery[0])}</section>`
      + `${this.townsHtml(p?.towns ?? [])}${this.scorecard(r.id)}</div>`;
  }
}
