import * as THREE from 'three';
import { N, STEP, type World } from '../world/tiles';
import { MAP_PIX, TILES_PER_PIX, type Atlas } from '../world/atlas';
import { MUNI, MUNI_PER } from '../world/municipality';
import { YOU } from '../game/carriage';

/**
 * The territory layer (docs/territory.html, "On the maps"; docs/standing.html): each county's municipalities
 * filled in the holder's colour, bright for weak and deeper for strong, striped with the out-owning fleet's
 * colour where it is contested, with one solid outline where the holder changes,
 * so two neighbouring towns of one fleet read as a single region; nobody's municipalities are left bare.
 * A town of the player's is painted even where its ground is still unseen, so a town just won is always
 * on the map. One painter makes a cell's picture (MUNI × MUNI RGBA) for all three maps: the world map
 * draws it over its pixels, the region map mixes it into each county's ground, and the overview lays it
 * over the islands in memory. Unseen ground stays unpainted.
 */

/** Fill strength for weak and strong territory, and the outline's: bright, like a selected town. */
const WEAK_A = 0.55, STRONG_A = 0.8, EDGE_A = 1;

const KEY = 'tinyfleet-map-territory';
let shown = false;
try { shown = localStorage.getItem(KEY) === '1'; } catch { /* storage blocked */ }
const listeners = new Set<() => void>();

/** Whether the maps show territory: one setting for all three, remembered on this device. */
export function territoryShown(): boolean { return shown; }
export function setTerritoryShown(v: boolean): void {
  if (v === shown) return;
  shown = v;
  try { localStorage.setItem(KEY, v ? '1' : '0'); } catch { /* storage blocked */ }
  for (const f of listeners) f();
}
export function onTerritoryShown(f: () => void): void { listeners.add(f); }

/** A toggle button for a map's header, kept in step with the setting wherever it was changed. */
export function territoryButton(className = 'names'): HTMLButtonElement {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = className;
  const sync = () => { b.textContent = shown ? 'Hide territory' : 'Show territory'; b.classList.toggle('on', shown); };
  b.addEventListener('click', (e) => { e.stopPropagation(); setTerritoryShown(!shown); });
  onTerritoryShown(sync);
  sync();
  return b;
}

interface TerritorySource {
  /** Who holds a town ('' for nobody), whether strong, and who contests it ('' for nobody). */
  status(key: string): { who: string; strong: boolean; contested: string };
  /** A carrier's colour. */
  colour(who: string): number;
  /** Changes whenever any town changes hands or strength, or a carrier's colour changes. */
  version(): number | string;
  /** A carrier's name, for the legend and the labels over its land. */
  name(who: string): string;
  /** Every town the game knows the standing of, for the legend. */
  keys(): Iterable<string>;
}

/** One stretch of a fleet's land, unbroken pixel to pixel: its size in municipality pixels and where to write its name. */
export interface Blob { who: string; pixels: number; gx: number; gz: number }

/** A stretch this many municipality pixels (16 tiles each) or bigger has room for its fleet's name. */
export const BLOB_MIN = 120;
/** And its name keeps this many municipality pixels (4 tiles each) from the middle of any town in it. */
const TOWN_CLEAR = 6;

export class TerritoryPaint {
  private cache = new Map<string, { v: string; px: Uint8ClampedArray }>();

  constructor(private atlas: Atlas, private src: TerritorySource) {}
  get source(): TerritorySource { return this.src; }

  /** A stamp of everything a cell's picture depends on. */
  private stamp(cx: number, cz: number): string {
    return `${this.src.version()}|${this.atlas.version}|${this.atlas.muni(cx, cz) ? 1 : 0}|${this.atlas.muni(cx + 1, cz) ? 1 : 0}|${this.atlas.muni(cx - 1, cz) ? 1 : 0}|${this.atlas.muni(cx, cz + 1) ? 1 : 0}|${this.atlas.muni(cx, cz - 1) ? 1 : 0}`;
  }

  /** The holder of a municipality pixel, reaching into the next cell at the edges: '' nobody, null no land. */
  private holderAt(cx: number, cz: number, px: number, pz: number): { id: string; who: string; strong: boolean; contested: string } | null {
    if (px < 0) { cx--; px += MUNI; } else if (px >= MUNI) { cx++; px -= MUNI; }
    if (pz < 0) { cz--; pz += MUNI; } else if (pz >= MUNI) { cz++; pz -= MUNI; }
    const m = this.atlas.muni(cx, cz);
    if (!m) return null;
    const t = m[pz * MUNI + px];
    if (t < 0) return null;
    const key = `${cx},${cz}#${t}`;
    return { id: key, ...this.src.status(key) };
  }

  /**
   * Every stretch of land one fleet holds across these cells, pixel joined to pixel, counting only what
   * the maps paint (seen ground, and the player's own towns). Biggest first; `slot` names the map asking.
   */
  blobs(cells: [number, number][], slot = ''): Blob[] {
    const v = `${cells.map(([x, z]) => `${x},${z}:${this.stamp(x, z)}`).join(';')}`;
    const have = this.blobCache.get(slot);
    if (have && have.v === v) return have.out;
    const ratio = TILES_PER_PIX / MUNI_PER;
    // who holds each painted pixel, by global municipality pixel (packed into one number)
    const OFF = 1 << 20, pack = (x: number, z: number) => (x + OFF) * 2 ** 21 + (z + OFF);
    const who = new Map<number, string>();
    const townOf = new Map<number, string>();
    for (const [cx, cz] of cells) {
      const m = this.atlas.muni(cx, cz);
      if (!m) continue;
      const seen = this.atlas.revealed(cx, cz);
      const holder = new Map<number, string>();
      for (let z = 0; z < MUNI; z++) {
        for (let x = 0; x < MUNI; x++) {
          const t = m[z * MUNI + x];
          if (t < 0) continue;
          let h = holder.get(t);
          if (h === undefined) { h = this.src.status(`${cx},${cz}#${t}`).who; holder.set(t, h); }
          if (!h) continue;
          const mp = Math.floor(z / ratio) * MAP_PIX + Math.floor(x / ratio);
          if ((!seen || !seen[mp]) && h !== YOU) continue;
          const k = pack(cx * MUNI + x, cz * MUNI + z);
          who.set(k, h);
          townOf.set(k, `${cx},${cz}#${t}`);
        }
      }
    }
    const done = new Set<number>();
    const out: Blob[] = [];
    for (const [k, w] of who) {
      if (done.has(k)) continue;
      const px: [number, number][] = [];
      const towns = new Set<string>();
      const stack: [number, number][] = [[Math.floor(k / 2 ** 21) - OFF, (k % 2 ** 21) - OFF]];
      done.add(k);
      while (stack.length) {
        const [x, z] = stack.pop()!;
        px.push([x, z]);
        towns.add(townOf.get(pack(x, z))!);
        for (const [nx, nz] of [[x - 1, z], [x + 1, z], [x, z - 1], [x, z + 1]]) {
          const nk = pack(nx, nz);
          if (done.has(nk) || who.get(nk) !== w) continue;
          done.add(nk);
          stack.push([nx, nz]);
        }
      }
      // the name goes on the pixel of the stretch nearest its middle, so a crescent's name sits on its
      // land, but clear of its towns' middles, where their own names are written
      let mx = 0, mz = 0;
      for (const [x, z] of px) { mx += x; mz += z; }
      mx /= px.length; mz /= px.length;
      const middles: [number, number][] = [];
      for (const tk of towns) {
        const pl = this.atlas.place(tk);
        if (pl) middles.push([(pl.cx * N + pl.x) / MUNI_PER, (pl.cz * N + pl.z) / MUNI_PER]);
      }
      const clear = (p: [number, number]) => middles.every((m) => (p[0] - m[0]) ** 2 + (p[1] - m[1]) ** 2 >= TOWN_CLEAR ** 2);
      let best = px[0], bd = Infinity;
      for (const pass of [true, false]) {
        for (const p of px) {
          if (pass && !clear(p)) continue;
          const d = (p[0] - mx) ** 2 + (p[1] - mz) ** 2;
          if (d < bd) { bd = d; best = p; }
        }
        if (bd < Infinity) break;
      }
      out.push({ who: w, pixels: px.length, gx: (best[0] + 0.5) * MUNI_PER, gz: (best[1] + 0.5) * MUNI_PER });
    }
    out.sort((a, b) => b.pixels - a.pixels);
    this.blobCache.set(slot, { v, out });
    return out;
  }
  /** One per map (`slot`), so the three don't push each other's out. */
  private blobCache = new Map<string, { v: string; out: Blob[] }>();

  /** The cell's picture, MUNI × MUNI RGBA, or null when nothing of it is known. */
  cell(cx: number, cz: number): Uint8ClampedArray | null {
    const m = this.atlas.muni(cx, cz);
    if (!m) return null;
    const k = `${cx},${cz}`, v = this.stamp(cx, cz);
    const have = this.cache.get(k);
    if (have && have.v === v) return have.px;
    const px = new Uint8ClampedArray(MUNI * MUNI * 4);
    const seen = this.atlas.revealed(cx, cz);
    const ratio = TILES_PER_PIX / MUNI_PER;
    const at = (x: number, z: number) => this.holderAt(cx, cz, x, z);
    for (let z = 0; z < MUNI; z++) {
      for (let x = 0; x < MUNI; x++) {
        const mp = Math.floor(z / ratio) * MAP_PIX + Math.floor(x / ratio);
        const h = at(x, z);
        if (!h || !h.who) continue;
        // unseen ground stays hidden, but a town of the player's own is known to be there
        if ((!seen || !seen[mp]) && h.who !== YOU) continue;
        const o = (z * MUNI + x) * 4;
        const n = [at(x - 1, z), at(x + 1, z), at(x, z - 1), at(x, z + 1)];
        // the outline runs only where the holder changes: one fleet's neighbouring towns are one region;
        // a contested town's fill is striped with the colour of the fleet that out-owns the holder
        const edge = n.some((q) => !q || q.who !== h.who);
        const c = this.src.colour(!edge && h.contested && ((x + z) & 2) ? h.contested : h.who);
        px[o] = (c >> 16) & 255; px[o + 1] = (c >> 8) & 255; px[o + 2] = c & 255;
        px[o + 3] = Math.round(255 * (edge ? EDGE_A : h.strong ? STRONG_A : WEAK_A));
      }
    }
    this.cache.set(k, { v, px });
    return px;
  }

  /** Holders with towns anywhere the atlas knows, for a legend: carrier → towns, strong and contested among them. */
  legend(keys: string[]): { who: string; towns: number; strong: number; contested: number }[] {
    const by = new Map<string, { who: string; towns: number; strong: number; contested: number }>();
    for (const k of keys) {
      const s = this.src.status(k);
      if (!s.who) continue;
      const e = by.get(s.who) ?? { who: s.who, towns: 0, strong: 0, contested: 0 };
      e.towns++;
      if (s.strong) e.strong++;
      if (s.contested) e.contested++;
      by.set(s.who, e);
    }
    return [...by.values()].sort((a, b) => b.towns - a.towns);
  }
}

/**
 * The overview's layer (M): each island in memory gets a sheet over its ground at 4 tiles a vertex,
 * carrying its cell's picture, drawn over everything so it reads as the map it is. Only in the overview.
 */
export class TerritoryCover {
  readonly root = new THREE.Group();
  private built = new Map<World, { mesh: THREE.Mesh; tex: THREE.DataTexture; px: Uint8ClampedArray | null }>();

  /** The fleets' names over their bigger stretches of land, as tags pinned to the ground. */
  private labelRoot = document.createElement('div');
  private labels: { el: HTMLElement; pos: THREE.Vector3 }[] = [];
  private labelKey = '';
  private worlds: World[] = [];
  private v = new THREE.Vector3();
  private fwd = new THREE.Vector3();
  private rel = new THREE.Vector3();

  constructor(private paint: TerritoryPaint) {
    this.root.name = 'territory';
    this.root.visible = false;
    this.labelRoot.id = 'terr-labels';
    this.labelRoot.className = 'hud';
    this.labelRoot.hidden = true;
    document.body.append(this.labelRoot);
  }

  /** Lay the names over the overview: each stretch big enough, in its fleet's colour, where the camera sees it. */
  place(camera: THREE.Camera, on: boolean): void {
    this.labelRoot.hidden = !on;
    if (!on) return;
    const blobs = this.paint.blobs(this.worlds.map((w) => [w.cx, w.cz]), 'overview').filter((b) => b.pixels >= BLOB_MIN);
    const key = blobs.map((b) => `${b.who}@${b.gx},${b.gz}`).join(';') + `|${this.paint.source.version()}`;
    if (key !== this.labelKey) {
      this.labelKey = key;
      this.labelRoot.replaceChildren();
      const src = this.paint.source;
      this.labels = blobs.map((b) => {
        const el = document.createElement('div');
        const c = src.colour(b.who);
        el.className = 'terr-label';
        el.textContent = src.name(b.who);
        el.style.color = hex(c);
        el.style.setProperty('--halo', haloFor(c));
        this.labelRoot.append(el);
        const w = this.worlds.find((q) => q.cx === Math.floor(b.gx / N) && q.cz === Math.floor(b.gz / N));
        const x = Math.min(N - 1, Math.max(0, Math.floor(b.gx - (w?.cx ?? 0) * N))), z = Math.min(N - 1, Math.max(0, Math.floor(b.gz - (w?.cz ?? 0) * N)));
        const y = w ? Math.max(w.corners[(z * N + x) * 4] * STEP, w.water[z * N + x] >= 0 ? w.water[z * N + x] * STEP : -Infinity) : 0;
        return { el, pos: new THREE.Vector3(b.gx, y + 2, b.gz) };
      });
    }
    camera.getWorldDirection(this.fwd);
    const W = window.innerWidth, H = window.innerHeight;
    // the town names (game/hud.ts) were here first: a fleet's name that would cover one drops below it
    const towns = Array.from(document.querySelectorAll<HTMLElement>('#town-labels .tlabel')).filter((e) => !e.hidden).map((e) => e.getBoundingClientRect());
    for (const l of this.labels) {
      this.rel.copy(l.pos).sub(camera.position);
      if (this.rel.dot(this.fwd) <= 0.5) { l.el.hidden = true; continue; }
      this.v.copy(l.pos).project(camera);
      const x = ((this.v.x + 1) / 2) * W;
      let y = ((1 - this.v.y) / 2) * H;
      l.el.hidden = this.v.z > 1 || x < 40 || y < 30 || x > W - 40 || y > H - 30;
      if (l.el.hidden) continue;
      const w = l.el.offsetWidth, h = l.el.offsetHeight;
      for (let tries = 0; tries < 3; tries++) {
        const hit = towns.find((r) => x - w / 2 < r.right + 4 && x + w / 2 > r.left - 4 && y - h / 2 < r.bottom + 2 && y + h / 2 > r.top - 2);
        if (!hit) break;
        y = hit.bottom + 4 + h / 2;
      }
      l.el.style.transform = `translate(${Math.round(x)}px, ${Math.round(y)}px) translate(-50%, -50%)`;
    }
  }

  update(worlds: World[], on: boolean): void {
    this.root.visible = on;
    this.worlds = worlds;
    if (!on) return;
    const live = new Set(worlds);
    for (const [w, b] of this.built) {
      if (live.has(w)) continue;
      this.dispose(w, b);
    }
    for (const w of worlds) {
      const px = this.paint.cell(w.cx, w.cz);
      const have = this.built.get(w);
      if (have && have.px === px) continue;
      if (have) this.dispose(w, have);
      if (!px) continue;
      const tex = new THREE.DataTexture(Uint8Array.from(px), MUNI, MUNI, THREE.RGBAFormat);
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.magFilter = THREE.NearestFilter;
      tex.minFilter = THREE.NearestFilter;
      tex.needsUpdate = true;
      const mesh = new THREE.Mesh(this.sheet(w), new THREE.MeshBasicMaterial({ map: tex, transparent: true, depthTest: false, depthWrite: false }));
      mesh.renderOrder = 5;
      mesh.frustumCulled = false;
      this.root.add(mesh);
      this.built.set(w, { mesh, tex, px });
    }
  }

  private dispose(w: World, b: { mesh: THREE.Mesh; tex: THREE.DataTexture }): void {
    this.root.remove(b.mesh);
    b.mesh.geometry.dispose();
    (b.mesh.material as THREE.Material).dispose();
    b.tex.dispose();
    this.built.delete(w);
  }

  /** A grid over the island's ground (or water) at MUNI_PER tiles, lifted a little. */
  private sheet(w: World): THREE.BufferGeometry {
    const G = MUNI + 1;
    const pos = new Float32Array(G * G * 3), uv = new Float32Array(G * G * 2);
    for (let j = 0; j < G; j++) {
      for (let i = 0; i < G; i++) {
        const x = Math.min(N - 1, i * MUNI_PER), z = Math.min(N - 1, j * MUNI_PER);
        const t = z * N + x;
        const ground = Math.max(w.corners[t * 4] * STEP, w.water[t] >= 0 ? w.water[t] * STEP : -Infinity);
        const k = j * G + i;
        pos[k * 3] = w.ox + i * MUNI_PER;
        pos[k * 3 + 1] = ground + 0.3;
        pos[k * 3 + 2] = w.oz + j * MUNI_PER;
        uv[k * 2] = i / MUNI;
        uv[k * 2 + 1] = j / MUNI;
      }
    }
    const index: number[] = [];
    for (let j = 0; j < G - 1; j++) {
      for (let i = 0; i < G - 1; i++) {
        const a = j * G + i, b = a + 1, c = a + G, d = c + 1;
        index.push(a, c, b, b, c, d);
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
    geo.setIndex(index);
    return geo;
  }
}

/** Draw one cell's picture onto a 2D canvas at (x, y), `size` pixels square, pixels kept square. */
const scratch = typeof document !== 'undefined' ? document.createElement('canvas') : null;
export function drawCell(ctx: CanvasRenderingContext2D, px: Uint8ClampedArray, x: number, y: number, size: number): void {
  if (!scratch) return;
  if (scratch.width !== MUNI) { scratch.width = MUNI; scratch.height = MUNI; }
  const sctx = scratch.getContext('2d')!;
  sctx.putImageData(new ImageData(new Uint8ClampedArray(px), MUNI, MUNI), 0, 0);
  const smooth = ctx.imageSmoothingEnabled;
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(scratch, x, y, size, size);
  ctx.imageSmoothingEnabled = smooth;
}

/** Text in a fleet's colour stays readable on any map: a dark colour gets a light halo, a light one a dark halo. */
export function haloFor(colour: number): string {
  const r = (colour >> 16) & 255, g = (colour >> 8) & 255, b = colour & 255;
  return 0.2126 * r + 0.7152 * g + 0.0722 * b < 120 ? 'rgba(255, 255, 255, 0.92)' : 'rgba(10, 13, 17, 0.8)';
}
export const hex = (c: number): string => `#${c.toString(16).padStart(6, '0')}`;

const LEGEND_ROWS = 8;

/**
 * The key to the territory colours: a swatch, the fleet's name and its towns for every fleet holding
 * any, biggest first, and a line on what the deeper fill and the stripes mean. One per map; it shows
 * only while territory does.
 */
export class TerritoryLegend {
  readonly el = document.createElement('div');
  private v = '';

  constructor(private paint: TerritoryPaint, className = '') {
    this.el.className = `terr-legend${className ? ` ${className}` : ''}`;
    this.el.hidden = true;
  }

  update(on: boolean): void {
    this.el.hidden = !on;
    if (!on) return;
    const src = this.paint.source;
    const keys = [...src.keys()];
    const v = `${src.version()}|${keys.length}`;
    if (v === this.v) return;
    this.v = v;
    const rows = this.paint.legend(keys);
    const esc = (t: string) => t.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));
    const line = (r: (typeof rows)[number]) => `<div class="tl-row${r.who === YOU ? ' you' : ''}"><i style="background:${hex(src.colour(r.who))}"></i><b${r.who.startsWith('p:') ? ` data-pid="${esc(r.who)}"` : ''}>${esc(src.name(r.who))}</b><span>${r.towns}</span></div>`;
    this.el.innerHTML = `<div class="tl-head">Territory<span>towns</span></div>`
      + (rows.length ? rows.slice(0, LEGEND_ROWS).map(line).join('') : '<div class="tl-none">Nobody holds a town yet</div>')
      + (rows.length > LEGEND_ROWS ? `<div class="tl-more">+ ${rows.length - LEGEND_ROWS} more</div>` : '')
      + (rows.length ? '<div class="tl-key">deeper · strong &nbsp;·&nbsp; striped · contested</div>' : '');
  }
}
