/**
 * Missions (docs/missions.html): the shapes everything else in this folder shares.
 *
 * A template is code that looks at the world and the player's company and either finds what it needs
 * (a town, a site, a rival's start line, a load to tow) or declines. What it finds is a Mission: plain
 * data that points at the world by tile and cell, never by object, so it can be written to the save and
 * read back against the same world. Objectives run in order; each is a small state machine in
 * objectives.ts fed by the events on the bus.
 */
import type { SlotId, Parts } from '../parts';
import type { Arch, BuildingKind, RegionKind } from '../../world/tiles';

/** What a mission moves for the player: their car, their fleet, what they own, or where they stand with a town. */
export type Thread = 'car' | 'fleet' | 'hold' | 'town';
export const THREADS: Thread[] = ['car', 'fleet', 'hold', 'town'];
export const THREAD_LABEL: Record<Thread, string> = { car: 'Car', fleet: 'Fleet', hold: 'Holdings', town: 'Towns' };
export const THREAD_COLOUR: Record<Thread, number> = { car: 0xe2412f, fleet: 0x3f8fd0, hold: 0xd9b34a, town: 0x5fa84a };

/** The kind of thing to be done, shown on the card's header beside the thread. */
export type Kind = 'job' | 'race' | 'tow' | 'trip' | 'op' | 'tail';
export const KIND_LABEL: Record<Kind, string> = { job: 'Job', race: 'Race', tow: 'Tow', trip: 'Trip', op: 'Night op', tail: 'Tail' };

/**
 * A tail (game/tail): somebody wants a car — or a train — followed to wherever it is going, unseen. What it
 * does on the way: `go` drives on; `check` pulls over a few seconds to look in its mirror; `wait` parks
 * up somewhere quiet for a good while; `back` doubles back on itself once there; `dash` puts its foot
 * down for one stretch to shake anybody behind; `swap` goes into a garage and comes out in another car.
 */
export type TailAct = 'go' | 'check' | 'wait' | 'back' | 'dash' | 'swap';
export type TailLeg = PlaceRef & { act: TailAct };
/** The car being followed: its model, its paint, and what the player is told to look for ("the red Sunny"). */
export interface TailCar { model: string; colour: number; name: string }
/** Where a tail ends, for the card and the ending line. */
export type TailEnd = 'hideout' | 'depot' | 'venue' | 'motel' | 'station' | 'stash' | 'yard';

/**
 * A night op (docs/nightops.html): helicopter work after dark that is done with the searchlight.
 * search: find someone lost (and fly them to a hospital pad); overboard: find a swimmer and guide the
 * lifeboat in; pursuit: keep a fleeing car in the beam; sweep: find a stolen car, then pursuit; live: hold
 * a news story in the beam on air; shoot: light a stunt driver for a film; blackout: light an ambulance's
 * way through a town with its power out; livestock: light strays for the rancher's truck; drops: find and
 * tag smugglers' contacts for the police.
 */
export type OpKind = 'search' | 'overboard' | 'pursuit' | 'sweep' | 'live' | 'shoot' | 'blackout' | 'livestock' | 'drops';

/** A town, by cell and index: enough to find it again in the same world, and its plain name for the card. */
export interface TownRef { cell: [number, number]; id: number; name: string }
/** A point in world tiles, with the cell it lies in and a short name ("the square", "Castle Greywater"). */
export interface PlaceRef { x: number; z: number; cell: [number, number]; name: string }
/** A cargo site, found again by kind within a tile or two of where it was. */
export interface SiteRef extends PlaceRef { kind: string }
/** A building, by cell and uid. */
export interface BuildingRef { cell: [number, number]; uid: number; kind: BuildingKind; name: string }

/**
 * A building as it stands in the world, so the plinth draws that one and not a stand-in: its seed picks
 * the variant, its facing turns it, its own style, boarded up or not, and its cell and uid let the
 * livery the player painted on it come through (render/liveryPaint.ts). The HQ window's Home uses it.
 */
interface RealBuilding { cx: number; cz: number; uid: number; seed: number; facing: number; style?: Arch; derelict?: boolean }

/** What turns on the card's plinth. */
export type HeroSpec =
  | { kind: 'vehicle'; model: string; parts?: Parts; job?: string }
  | { kind: 'part'; slot: SlotId; tier: number }
  | { kind: 'building'; b: BuildingKind; arch: Arch; w: number; d: number; floors: number; real?: RealBuilding }
  | { kind: 'load'; load: HaulKind }
  | { kind: 'trophy' }
  | { kind: 'crate'; colour: number }
  | { kind: 'ferry' }
  | { kind: 'stamp'; region?: RegionKind };

/** The heavy things a tow drags. */
export type HaulKind = 'bell' | 'boiler' | 'propeller' | 'statue' | 'yacht' | 'wreck' | 'loco' | 'dish' | 'sphere';

/** One thing to be done. `label` is the card's line: a verb, an object, a place; 28 characters at most. */
/** What a teaching mission's `make` step counts (game/coach.ts). */
export type MakeKind = 'road' | 'unlock' | 'erect' | 'bridge' | 'level' | 'rail' | 'railParallel';

export type Obj = { label: string; icon: string } & (
  /** `door`: the goods go in through the shop's door, stopped in its entrance ring with Space, not by stopping in a green ring. */
  /** `prop`: a vehicle model drawn waiting at the pickup (a stranded boat), until the load is aboard. */
  /**
   * `clock`: seconds to get it there once it is aboard, run on the HUD (an ambulance's dash); `ride`: it can
   * only be carried in one of these models; `with`: a convoy's (missions/convoyTemplates.ts), set down only
   * with that many of the player's vehicles formed up behind them in Follow mode (Missions.heldBack).
   * `also`: a second load put out beside the first at the same time (the first drive's A Helping Hand: one
   * fills the player's car, the other needs the hand's), counted as one of the `n`, and paid its own value.
   */
  | { t: 'deliver'; cargo: string; from: SiteRef; to: SiteRef; n: number; value: number; door?: boolean; prop?: string; clock?: number; ride?: { ids: string[]; label: string }; with?: number; also?: { cargo: string; value: number } }
  /**
   * Knock a building down by driving into it head on at `kmh` (as the HUD reads it) or faster, in one of the
   * `ride` models (the mayor's knock-down for the Dozer). `at` is the building's middle.
   */
  | { t: 'ram'; at: PlaceRef; b: BuildingRef; kmh: number; ride: { ids: string[]; label: string } }
  | { t: 'loads'; town: TownRef; n: number }
  /**
   * `door`: arriving is stopping in the place's entrance ring and pressing Space, not coming within `r`.
   * `hidden`: the place is not shown (no beam, no arrow, no distance) until the player is within this many
   * tiles of it, when a drop-off ring shows there (a tavern's rumour, game/tavern). `stop`: arriving is
   * stopping inside `r`. `ride`: arriving only counts in one of these models (a tow truck, say).
   */
  | {
    t: 'reach'; at: PlaceRef; r: number; door?: boolean; hidden?: number; stop?: boolean; ride?: { ids: string[]; label: string };
    /**
     * The story chains' meetings (docs/storychains.html): `after`–`before` is the game hours it counts in
     * (wrapping past midnight, 21 to 4 is the night); `hold` is seconds to stay stopped inside `r` once
     * there (a count, a watch); `with` is how many of the player's own vehicles must be in formation
     * behind them (Follow mode) when they arrive.
     */
    after?: number; before?: number; hold?: number; with?: number;
    /**
     * Under the waves (docs/underwater.html): arriving counts only in a submarine sounded (gone down to the
     * bottom) inside `r`; with `hold`, held down there that long.
     */
    dived?: boolean;
  }
  | { t: 'visit'; what: 'biome' | 'arch' | 'wonder' | 'town'; key: string; at: PlaceRef | null }
  /** `at` is the harbour slip the ferry sails from; missing in saves from before it was recorded. */
  | { t: 'ferry'; at?: PlaceRef }
  | { t: 'race'; rival: string; tier: 1 | 2 | 3; from: PlaceRef; to: PlaceRef }
  | { t: 'tow'; load: HaulKind; from: PlaceRef; to: PlaceRef; min: number; need: number }
  | { t: 'own'; n: number }
  /**
   * Make something with the player's own tools (the teaching missions, game/coach.ts): lay `n` tiles of road
   * with the builder, unlock `n` vehicles on the tech trees, or put `n` building asks to towns (lobby); bridge
   * water with a road, or level the ground in `at`'s ring with the terrain tool. `at` (and `r`) puts a ring
   * where it is wanted.
   */
  | { t: 'make'; what: MakeKind; n: number; at?: PlaceRef; r?: number }
  /** Own an HQ that opens at least this many fleet slots (the getting-started track, game/fleetTrack.ts). */
  | { t: 'hq'; slots: number }
  /** Have this many of your vehicles out on the road with a hired driver at the wheel. */
  | { t: 'driving'; n: number }
  | { t: 'fit'; slot: SlotId | null }
  | { t: 'crew'; n: number }
  /** Reach this speed (km/h, as the HUD reads it) in whatever is being driven. */
  | { t: 'speed'; kmh: number }
  /** Slide the tail round a corner on the handbrake, turning this way. */
  | { t: 'drift'; dir: 'left' | 'right' }
  /**
   * Be this many tiles from home on an honest drive (game/range.ts credit, docs/exploration.html), in anything or
   * in a vehicle of this kind or this model (`mname` its name for the line). It has no place: the arrow points
   * away from home.
   */
  | { t: 'range'; tiles: number; kind?: 'land' | 'water' | 'air'; model?: string; mname?: string }
  /** Set foot in this many cells the fleet has never been in, counted from when the step comes up. */
  | { t: 'discover'; n: number }
  /**
   * A night op. `at` is where it happens (the search area's middle, the chase's start, the scene); `r` the
   * search area's radius; `to` where it ends (a hospital pad, the chase's end, the farm, the police
   * station); `spots` what is hidden or set out (the lost, the stolen car, the strays, the contacts);
   * `what` the look of the lost (hiker, child, dog, swimmer).
   */
  | { t: 'op'; op: OpKind; at: PlaceRef; r: number; to?: PlaceRef; spots?: PlaceRef[]; what?: string }
  /** A clean lap of a circuit (docs/circuits.html; `key` its cell and uid) in under `secs` seconds. */
  | { t: 'lap'; at: PlaceRef; key: string; secs: number }
  /** A grid slot at a circuit's next race meeting, and a finish in the top `top`. */
  | { t: 'grid'; at: PlaceRef; key: string; top: number }
  /**
   * A tail: the target waits at `at` until the player comes near, then drives `legs` in order and ends at
   * `to`. `swap` is what it comes out of the garage in. A `train` tail meets a freight at the station `at`
   * and ends wherever it next calls (`to` is then only the yard it is thought to be bound for, for the card).
   */
  | { t: 'tail'; at: PlaceRef; to: PlaceRef; legs: TailLeg[]; car: TailCar; swap?: TailCar; train?: boolean; end: TailEnd }
);

/** What finishing gives. Each goes through the same door the shop uses, less the price. */
export type Reward =
  | { r: 'cash'; n: number }
  /** Diamonds, paid in as a bonus (the convoys). */
  | { r: 'gems'; n: number }
  | { r: 'part'; slot: SlotId; tier: number; all?: boolean }
  | { r: 'vehicle'; model: string; parts?: Parts; name?: string }
  | { r: 'building'; at: BuildingRef }
  | { r: 'standing'; town: TownRef; n: number }
  | { r: 'effect'; town: TownRef; effect: 'credit' | 'mend' | 'civic' | 'levy' | 'graduate'; line: string }
  | { r: 'driver' }
  /**
   * Someone who joined the fleet when the mission was taken (the first drive's helping hand, in her own car)
   * says she is staying on: told on the done card, nothing more to give.
   */
  | { r: 'crew'; name: string; model: string }
  | { r: 'livery'; colour: number; name: string }
  /** A tip about something hidden: `line` is what the player is told, and kept in the tavern's notebook. */
  | { r: 'clue'; line: string }
  /**
   * What a tail turned up (game/tail): a rival firm's depot (`key` its firm id) lit by its beacon, a hidden
   * vehicle's spot, a smuggling contact who calls after dark, or a hideout; `line` goes in the notebook too.
   */
  | { r: 'reveal'; what: 'depot' | 'stash' | 'contact' | 'hideout'; at: PlaceRef; line: string; key?: string };

export type State = 'offered' | 'active' | 'done' | 'failed' | 'rejected';

/** Who is asking: a mayor, a rival, the mechanic, the harbourmaster, an old haulier, a baker. */
export interface Giver { who: string; name: string; at: PlaceRef; town: TownRef | null }

export interface Mission {
  id: number;
  tpl: string;
  /** The hash it was rolled from: binding again from it finds the same things. */
  seed: number;
  thread: Thread;
  also?: Thread;
  kind: Kind;
  title: string;
  /** What to do and why, in up to three lines on the card: 130 characters at most. */
  why: string;
  /** The longer story behind "More details" on the card, before the how-to the card adds itself. */
  details?: string;
  giver: Giver;
  hero: HeroSpec;
  /** The hero's caption, under the plinth: what it is. */
  caption: string;
  objs: Obj[];
  /** The objective being run, and how many of its `n` are done. */
  step: number;
  count: number;
  reward: Reward[];
  state: State;
  posted: number;
  /** Game hours it must be done by, if it has a deadline at all. */
  due: number | null;
  arc?: { id: string; i: number; of: number };
  /** Bound in a story step's helicopter or boat form: its diamond shows, and it can be taken, only in one. */
  form?: 'heli' | 'boat' | 'sub';
  /** Shown once as a card already (it waits in the journal after that). */
  shown?: boolean;
  /** An offer waiting at its giver's diamond (isPosted): the player has been told where it is. */
  marked?: boolean;
  /** How it ended, for the Done list: "Won by 4 s", "Rope snapped twice". */
  outcome?: string;
  /** The game hour it ended. */
  ended?: number;
  /** Tracked on the HUD chip. */
  tracked?: boolean;
  /** A tow's rope snaps and scrapes, a race's margin, for the outcome line. */
  notes?: Record<string, number>;
}

/** An arc: named missions in one thread that run in order and end in a capstone. */
export interface Arc {
  id: string; title: string; thread: Thread; who: string; tpls: string[];
  /** A long arc's acts (docs/storychains.html), four steps each: the journal shows one act's dots at a time. */
  acts?: string[];
}
