import { REGION_KINDS, type Arch, type BuildingKind, type TownKind } from '../world/tiles';
import { LANDFORM_LABEL } from '../world/landforms';
import { REGIONS } from '../world/regions';
import { ISLAND_WONDERS } from '../world/wonders';
import { ANCIENT_KINDS, ANCIENT_STAMP } from '../world/ancientKinds';
import { NEXT_WORLD } from '../world/nextWorld';
import { KIND_SPEC } from '../world/townKinds';
import { TOWN_INFO, signatureKinds } from '../world/towns';
import { SITE_LABEL, type SiteKind } from './cargoTypes';
import { ARCHES, ARCH_LABEL } from './missions/passport';
import { LOBBY } from './lobby';
import { deeds, type Stat } from './deeds';
import { KINDS, KIND_OF, MARKETS, type EventKind } from './events/kinds';

/**
 * The Passport's sights pages (docs/passport.html): one stamp for each kind of thing the player has seen — a
 * biome, a town style, a town size, a wonder, a landform, a kind of building — with where and when it was
 * first seen, so a stamp can be found again on the map. They belong to the player, beside the deeds, and
 * feed the deeds' own sets, so the diamonds are paid by the machinery already there.
 */

export type SightPage = 'biome' | 'arch' | 'size' | 'wonder' | 'landform' | 'kind' | 'event';
export const SIGHT_PAGES: SightPage[] = ['arch', 'biome', 'size', 'wonder', 'landform', 'kind', 'event'];
export const PAGE_LABEL: Record<SightPage, string> = {
  arch: 'Town styles', biome: 'Biomes', size: 'Town sizes', wonder: 'Wonders', landform: 'Landforms', kind: 'Buildings', event: 'Events',
};
export const PAGE_ICON: Record<SightPage, string> = { arch: '🏘️', biome: '🧭', size: '🏙️', wonder: '🗿', landform: '🗻', kind: '🏠', event: '🎪' };
/** The deed set each page fills. */
const PAGE_STAT: Record<SightPage, Stat> = { arch: 'styles', biome: 'biomes', size: 'sizes', wonder: 'wonders', landform: 'landforms', kind: 'kinds', event: 'events' };

/** Where a thing was first seen: the cell, the spot in it in tiles, when, and what the place is called. */
export interface Seen { cx: number; cz: number; x: number; z: number; t: number; name: string }
type Row = [number, number, number, number, number, string] | 0;
interface Stored { v: 1; p: Partial<Record<SightPage, Record<string, Row>>> }

const pretty = (kind: string): string => {
  const words = kind.replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase();
  return words[0].toUpperCase() + words.slice(1);
};
export const kindName = (kind: string): string => SITE_LABEL[kind as SiteKind] ?? pretty(kind);

const SIZES: TownKind[] = ['rural', 'suburb', 'city', 'metro', 'mega'];
// the ancient wonders come with the next world (world/nextWorld.ts): until then there are none to stamp
const WONDERS: string[] = [...new Set([...REGION_KINDS.map((r) => REGIONS[r].wonder.kind as string), ...ISLAND_WONDERS.map((w) => w.wonder.kind as string), ...(NEXT_WORLD ? ANCIENT_KINDS : [])])];
const ORDINARY = new Set<string>(LOBBY.map((r) => r.kind));

/** Each style's signature buildings: what its swaps put up that no ordinary town asks for. */
export const SIGNATURES: Map<Arch, BuildingKind[]> = (() => {
  const out = new Map<Arch, BuildingKind[]>();
  for (const [style, kinds] of signatureKinds()) {
    const own = kinds.filter((k) => !ORDINARY.has(k));
    if (own.length) out.set(style, own);
  }
  return out;
})();
/** A signature building's style, the first that builds it. */
export const SIGNATURE_STYLE = new Map<BuildingKind, Arch>();
for (const [style, kinds] of SIGNATURES) for (const k of kinds) if (!SIGNATURE_STYLE.has(k)) SIGNATURE_STYLE.set(k, style);

/** Every stamp a page has room for, in the order it is drawn; the building page lists what a town can build. */
export function pageKeys(page: SightPage): string[] {
  switch (page) {
    case 'arch': return ARCHES.slice();
    case 'biome': return REGION_KINDS.slice();
    case 'size': return SIZES.slice();
    case 'wonder': return WONDERS.slice();
    case 'landform': return Object.keys(LANDFORM_LABEL);
    // the events (docs/events.html): one a kind, being there while it was on
    case 'event': return [...KINDS, ...(NEXT_WORLD ? MARKETS : [])].map((k) => k.id);
    case 'kind': return [...new Set([...LOBBY.map((r) => r.kind as string), ...Object.keys(KIND_SPEC)])].filter((k) => !WONDER_KINDS.has(k));
  }
}

/** Wonders' own names on their stamps: three are castles and two are temples, which their buildings' labels don't tell apart. */
const WONDER_LABEL: Record<string, string> = {
  pyramid: 'Great pyramid', castle: 'Highland castle', hilltopCastle: 'Hilltop castle', moatedCastle: 'Moated castle',
  capeTemple: 'Cape temple', lostTemple: 'Lost temple', cloudTemple: 'Cloud temple', goldenTemple: 'Golden temple',
  lavenderAbbey: 'Lavender abbey', khanStatue: 'Horseman statue', monumentButtes: 'Monument buttes', mission: 'Old mission',
  ...ANCIENT_STAMP,
};
/** The wonders' kinds: stamped on the Wonders page, never as a building. */
export const WONDER_KINDS: ReadonlySet<string> = new Set(WONDERS);

export function stampLabel(page: SightPage, key: string): string {
  switch (page) {
    case 'wonder': return WONDER_LABEL[key] ?? kindName(key);
    case 'arch': return ARCH_LABEL[key as Arch] ?? pretty(key);
    case 'biome': return (REGIONS[key as keyof typeof REGIONS]?.title ?? key).replace(/^the /, '');
    case 'size': return TOWN_INFO[key as TownKind]?.label ?? key;
    case 'landform': return LANDFORM_LABEL[key as keyof typeof LANDFORM_LABEL] ?? pretty(key);
    case 'event': return KIND_OF[key as EventKind]?.name ?? pretty(key);
    default: return kindName(key);
  }
}

const KEY = 'tinyfleet-passport';
const keyOf = (player: string): string => `${KEY}:${player}`;

function read(player: string): Stored | null {
  try {
    const r = JSON.parse(localStorage.getItem(keyOf(player)) ?? 'null') as Partial<Stored> | null;
    return r && r.v === 1 ? { v: 1, p: r.p ?? {} } : null;
  } catch { return null; }
}

export class Sights {
  private player = '';
  private rec: Stored = { v: 1, p: {} };
  private unsaved = false;
  /** Bumped at every new stamp, for the book. */
  revision = 0;
  /** A new stamp: the card, and anything that wants to know a thing was seen for the first time. */
  onStamp: ((page: SightPage, key: string, seen: Seen | null) => void) | null = null;

  /**
   * The player the book is for. What the deeds already hold (biomes, wonders and landforms were counted
   * before there were places to go with them) is taken in as stamps with no place.
   */
  load(player: string): void {
    if (player === this.player) return;
    this.flush();
    this.player = player;
    this.rec = read(player) ?? { v: 1, p: {} };
    for (const page of SIGHT_PAGES) for (const k of deeds.keys(PAGE_STAT[page])) this.adopt(page, k);
    this.revision++;
  }

  /** Take a stamp in without a place or a card: one the deeds or an old save's journal already had. */
  adopt(page: SightPage, key: string): void {
    const p = (this.rec.p[page] ??= {});
    if (key in p) return;
    p[key] = 0;
    this.unsaved = true;
    this.revision++;
  }

  has(page: SightPage, key: string): boolean { return !!this.rec.p[page] && key in this.rec.p[page]!; }
  count(page: SightPage): number { return Object.keys(this.rec.p[page] ?? {}).length; }
  total(): number { return SIGHT_PAGES.reduce((s, p) => s + this.count(p), 0); }
  keys(page: SightPage): string[] { return Object.keys(this.rec.p[page] ?? {}); }

  /** Where a stamp was first seen, if it was stamped since places were kept. */
  where(page: SightPage, key: string): Seen | null {
    const r = this.rec.p[page]?.[key];
    return r ? { cx: r[0], cz: r[1], x: r[2], z: r[3], t: r[4], name: r[5] } : null;
  }

  /**
   * A thing has been seen. True when it is new: it is stamped with the place, its deed's set takes it, and
   * `onStamp` hears of it. Only a game in play stamps (the deeds' own rule).
   */
  stamp(page: SightPage, key: string, at: { cx: number; cz: number; x: number; z: number; name: string } | null): boolean {
    if (!deeds.active || !key) return false;
    const p = (this.rec.p[page] ??= {});
    if (key in p) {
      // a stamp from before places were kept gains one the next time the thing is seen
      if (p[key] === 0 && at) { p[key] = [at.cx, at.cz, Math.round(at.x), Math.round(at.z), Date.now(), at.name]; this.unsaved = true; }
      return false;
    }
    p[key] = at ? [at.cx, at.cz, Math.round(at.x), Math.round(at.z), Date.now(), at.name] : 0;
    // the deed whose set this is (named outright, so `npm run deeds` finds its caller)
    switch (page) {
      case 'arch': deeds.mark('styles', key); break;
      case 'size': deeds.mark('sizes', key); break;
      case 'kind': deeds.mark('kinds', key); break;
      case 'biome': deeds.mark('biomes', key); break;
      case 'wonder': deeds.mark('wonders', key); break;
      case 'event': deeds.mark('events', key); break;
      default: deeds.mark('landforms', key);
    }
    this.unsaved = true;
    this.revision++;
    this.onStamp?.(page, key, this.where(page, key));
    return true;
  }

  /** The book as it stands, kept with an online career too (see Deeds.snapshot). */
  snapshot(): unknown { return JSON.parse(JSON.stringify(this.rec)); }

  /** A book kept with the online career, merged into this player's: every stamp, a place kept over none. */
  absorb(s: unknown): void {
    const r = s as Partial<Stored> | null;
    if (!this.player || !r || r.v !== 1 || !r.p) return;
    for (const page of SIGHT_PAGES) {
      const mine = (this.rec.p[page] ??= {});
      for (const [k, row] of Object.entries(r.p[page] ?? {})) if (!(k in mine) || (mine[k] === 0 && row)) mine[k] = row;
    }
    this.unsaved = true;
    this.flush();
    this.revision++;
  }

  flush(): void {
    if (!this.player || !this.unsaved) return;
    // another tab may have played this player: keep whatever it stamped
    const disk = read(this.player);
    if (disk) {
      for (const page of SIGHT_PAGES) {
        const mine = (this.rec.p[page] ??= {});
        for (const [k, r] of Object.entries(disk.p[page] ?? {})) if (!(k in mine) || (mine[k] === 0 && r)) mine[k] = r;
      }
    }
    try { localStorage.setItem(keyOf(this.player), JSON.stringify(this.rec)); } catch { /* kept in memory only */ }
    this.unsaved = false;
  }
}

/** The one book of sights: the current player's. */
export const sights = new Sights();

/** Remove a player's stamps with the player. */
function forgetSights(player: string): void {
  try { localStorage.removeItem(keyOf(player)); } catch { /* nothing to remove */ }
}
