/**
 * The title's taglines (src/title/menu.ts): the line under the logo, one at random, a new one every few
 * seconds. These are the defaults, short cuts of the itch.io and Steam listings (itch/ab, steam/): the
 * control, Empire, Wander and Full Send sets. The developer can replace the list from /dev (Taglines), kept
 * on the server and fetched by every game at start (GET /api/taglines).
 *
 * Each must fit on one line under the logo: TAGLINE_MAX characters at most.
 */

export const DEFAULT_TAGLINES: string[] = [
  // the control listing
  'Drive. Haul. Grow a fleet.',
  'Road, sea and sky. One tiny fleet.',
  'A tiny world with a fleet in your wake.',
  // Empire: the tycoons
  'Start with one car. Build an empire.',
  'A transport tycoon you drive yourself.',
  'Beat the rival firms at their own game.',
  // Wander: the explorers
  'A cozy world that never ends.',
  'See what’s over the next hill.',
  // Full Send: the drivers
  'Grab a jet and send it.',
];

/** Characters a tagline may have: about what fits on one line under the logo. */
export const TAGLINE_MAX = 44;
/** Taglines a list may hold. */
export const TAGLINES_MAX = 40;

/** A list as typed on /dev, tidied: one tagline each, trimmed, blanks and repeats dropped. Or what is wrong with it. */
export function cleanTaglines(v: unknown): string[] | string {
  if (!Array.isArray(v)) return 'Send a list of taglines.';
  const out: string[] = [];
  for (const raw of v) {
    if (typeof raw !== 'string') return 'Every tagline must be text.';
    const t = raw.replace(/\s+/g, ' ').trim();
    if (!t) continue;
    if (t.length > TAGLINE_MAX) return `“${t}” is ${t.length} characters: ${TAGLINE_MAX} at most, so it fits on one line.`;
    if (/[<>]/.test(t)) return `“${t}” has a < or >: leave those out.`;
    if (!out.includes(t)) out.push(t);
  }
  if (!out.length) return 'Keep at least one tagline (or restore the defaults).';
  if (out.length > TAGLINES_MAX) return `${out.length} taglines: ${TAGLINES_MAX} at most.`;
  return out;
}
