import * as THREE from 'three';
import { hashString } from '../world/rng';
import { isWomanName } from './mayor';
import { Kit } from '../render/vehicleMeshes';

/**
 * A crew member's portrait (the user, 6 Nov 2026): the game's own little person, the rider who sits in the Sunny and
 * every other open seat (render/vehicleMeshes.ts Kit.rider: a box for a body, a faceted ball for a head), in a shirt
 * colour of their own and with hair: one of twelve hairdos for a man or twelve for a woman, by their name (the book's
 * given names say which: game/mayor.ts isWomanName). The same name always draws the same person, so a candidate looks
 * the same once hired. Drawn once on a small shared renderer and kept as a picture, so a list of cards costs nothing.
 */

const HAIR = [0x1f1b19, 0x3b2a1e, 0x5c3b22, 0x8a4a24, 0xc98b3c, 0xe3c069, 0xb8b4ad, 0xe8e2d3];
const SHIRT = [0xe2412f, 0x2f7fb5, 0x3f9b4a, 0xf2a93b, 0x8e5cc7, 0x1d2a5c, 0x2bb3a3, 0xd0477a, 0x5a6470, 0xb0703a, 0xf4f2ec, 0x6d8a2e];

/** The rider's head (Kit.rider): its middle and radius, in the rider's frame (front is +z). */
const HX = 0, HY = 0.27, HZ = 0.01, HR = 0.075;

/** Builds hair on a rider: the kit, the rider's group and the hair's material. */
type Hair = (k: Kit, g: THREE.Group, m: THREE.Material) => void;
interface Hairdo { name: string; make: Hair }

/** A cap of hair over the crown: part of a sphere round the head, `theta` degrees down from the top, tipped back. */
function cap(g: THREE.Group, m: THREE.Material, scale = 1.06, theta = 70, tilt = -25, sy = 1): THREE.Mesh {
  const geo = new THREE.SphereGeometry(HR * scale, 9, 6, 0, Math.PI * 2, 0, THREE.MathUtils.degToRad(theta));
  const mesh = new THREE.Mesh(geo, m);
  mesh.position.set(HX, HY, HZ);
  mesh.rotation.x = THREE.MathUtils.degToRad(tilt);
  mesh.scale.y = sy;
  g.add(mesh);
  return mesh;
}
const ball = (k: Kit, g: THREE.Group, m: THREE.Material, r: number, x: number, y: number, z: number, sx = 1, sy = 1, sz = 1) => k.ball(g, r, m, x, y, z, sx, sy, sz, 0);
function box(k: Kit, g: THREE.Group, m: THREE.Material, w: number, h: number, d: number, x: number, y: number, z: number, rx = 0, rz = 0): THREE.Mesh {
  const b = k.box(g, w, h, d, m, x, y, z);
  b.rotation.set(rx, 0, rz);
  return b;
}

