export interface Look { woman: boolean; hairdo: Hairdo; hair: number; shirt: number }

/** Who someone looks like, from their name (and, for a name the book doesn't know, its hash for which they are). */
export function lookOf(name: string): Look {
  const h = hashString(`face|${name}`);
  const woman = isWomanName(name) ?? (h & 1) === 0;
  const set = woman ? WOMEN : MEN;
  // grey and platinum hair a little rarer
  const hair = HAIR[(h >>> 4) % ((h >>> 20) % 4 === 0 ? HAIR.length : HAIR.length - 2)];
  return { woman, hairdo: set[(h >>> 8) % set.length], hair, shirt: SHIRT[(h >>> 16) % SHIRT.length] };
}

// ---- the stage: one small renderer for every portrait, its pictures kept by look ----

const PX = 112;
let stage: { renderer: THREE.WebGLRenderer; scene: THREE.Scene; cam: THREE.PerspectiveCamera } | null | false = null;
const pictures = new Map<string, string>();

function getStage(): typeof stage {
  if (stage !== null) return stage;
  try {
    const canvas = document.createElement('canvas');
    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true, preserveDrawingBuffer: true });
    renderer.setPixelRatio(1);
    renderer.setSize(PX, PX, false);
    renderer.toneMapping = THREE.NeutralToneMapping;
    renderer.toneMappingExposure = 1.05;
    const scene = new THREE.Scene();
    scene.add(new THREE.HemisphereLight(0xd8ecff, 0x8fb37a, 1.15));
    const sun = new THREE.DirectionalLight(0xfff1d6, 2.4);
    sun.position.set(2, 4, 4);
    scene.add(sun);
    // head and shoulders, a little from above and to one side, as the Sunny's riders are seen
    const cam = new THREE.PerspectiveCamera(24, 1, 0.05, 10);
    cam.position.set(0.15, 0.38, 0.62);
    cam.lookAt(0, 0.255, 0);
    stage = { renderer, scene, cam };
  } catch {
    stage = false;
  }
  return stage;
}

/** The picture of a look, as a data URL; '' where WebGL can't be had. */
function picture(l: Look): string {
  const key = `${l.woman ? 'w' : 'm'}|${l.hairdo.name}|${l.hair}|${l.shirt}`;
  const have = pictures.get(key);
  if (have !== undefined) return have;
  const s = getStage();
  if (!s) { pictures.set(key, ''); return ''; }
  const k = new Kit();
  const root = new THREE.Group();
  const g = k.rider(root, 0, 0, 0, l.shirt);
  const hair = new THREE.MeshStandardMaterial({ color: l.hair, roughness: 0.75, metalness: 0, flatShading: true });
  l.hairdo.make(k, g, hair);
  s.scene.add(root);
  s.renderer.render(s.scene, s.cam);
  const url = s.renderer.domElement.toDataURL('image/png');
  s.scene.remove(root);
  root.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) { m.geometry.dispose(); (m.material as THREE.Material).dispose(); } });
  pictures.set(key, url);
  return url;
}

/** The portrait as an image, `size` pixels square; `as` overrides the look (a gallery of every hairdo, say). */
export function portraitImg(name: string, size = 44, as?: Partial<Look>): string {
  const url = picture({ ...lookOf(name), ...as });
  return url ? `<img class="crew-face" src="${url}" width="${size}" height="${size}" alt="" draggable="false">` : '';
}
