/**
 * The Visitors' goods (game/meteorites.ts): what a meteor shower leaves on the ground. No town sends them; and the
 * consignment that makes a town Influenced by or Infatuated with the Visitors is a meteorite's main mass, too heavy for one vehicle.
 */
export const VISITOR_GOODS: Good[] = [['Meteorites', '☄️'], ['Iron meteorites', '🪨'], ['Pallasites', '💎']];
export const METEORITE_MASS = { name: 'Meteorite main mass', icon: '☄️', color: 0x6a3fb5 };

/** A cultural good's colour on the ground, by the sort of thing it is. */
const TINTS = [0xd98a3a, 0xb05ab8, 0x3f9ad6, 0xd4545a, 0x4fae6a];

/** The good a sighting sends home: one of its style's (or a meteorite, the Visitors'), the same one every time for the same key. */
export function goodOf(style: Arch | 'visitor', key: string): { name: string; icon: string; color: number } {
  const list = style === 'visitor' ? VISITOR_GOODS : GOODS[style] ?? GOODS.classic;
  const h = hashString(`${style}|${key}`) >>> 0;
  const [name, icon] = list[h % list.length];
  return { name, icon, color: TINTS[(h >>> 4) % TINTS.length] };
}

/**
 * The good as a cargo type the hold understands: never put out by the cargo system itself (missionOnly), a
 * parcel any vehicle may carry, filling `units` of the hold like any load of that size.
 */
export function goodType(id: number, good: { name: string; icon: string; color: number }, units: number): CargoType {
  return {
    id: `culture:${id}`, name: good.name, icon: good.icon, color: good.color, cls: 'parcel', units,
    from: [], to: [], base: 0, perTile: 0, ttl: [1e9, 1e9], every: [1e9, 1e9], max: 0, missionOnly: true,
    blurb: `${good.name}, made where they are known for them.`,
  };
}
