import { N, CHUNK, CHUNKS, Biome, type World } from './tiles';
import { overlayOf } from './land';

/**
 * The earthworks overlay in a save (docs/terrain.html): per 16×16 chunk, five planes of whole-step
 * differences from the generated island — the four corners of every tile, then its water level —
 * zero-run coded and in base64. Keyed by chunk index, 0–255. A corner put back where the generator
 * left it encodes as nothing, so a hillside reworked forty times costs what it cost once.
 */
export type LandBlock = Record<number, string>;

const PLANE = CHUNK * CHUNK;
const RAW = PLANE * 5;

function chunkTiles(k: number): number[] {
  const cx = k % CHUNKS, cz = (k - cx) / CHUNKS;
  const out: number[] = [];
  for (let z = 0; z < CHUNK; z++) for (let x = 0; x < CHUNK; x++) out.push((cz * CHUNK + z) * N + cx * CHUNK + x);
  return out;
}

function toBase64(bytes: number[]): string {
  let s = '';
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s);
}

function fromBase64(s: string): number[] {
  const bin = atob(s);
  const out: number[] = new Array(bin.length);
  for (let k = 0; k < bin.length; k++) out[k] = bin.charCodeAt(k);
  return out;
}

/** An island's overlay as a save block, or undefined when nothing differs from the generator's. */
export function encodeLand(w: World): LandBlock | undefined {
  const o = overlayOf(w);
  if (!o) return undefined;
  const out: LandBlock = {};
  let any = false;
  for (const k of [...o.chunks].sort((a, b) => a - b)) {
    const tiles = chunkTiles(k);
    const raw: number[] = [];
    for (let q = 0; q < 4; q++) for (const i of tiles) raw.push(o.c[i * 4 + q]);
    for (const i of tiles) raw.push(o.wt[i]);
    if (raw.every((v) => v === 0)) { o.chunks.delete(k); continue; }
    // zero runs as 0, count (1–255); anything else as its own byte
    const bytes: number[] = [];
    for (let p = 0; p < raw.length;) {
      if (raw[p] === 0) {
        let n = 0;
        while (p < raw.length && raw[p] === 0 && n < 255) { n++; p++; }
        bytes.push(0, n);
      } else {
        bytes.push(raw[p] & 255);
        p++;
      }
    }
    out[k] = toBase64(bytes);
    any = true;
  }
  return any ? out : undefined;
}

/** One chunk's five planes out of its base64. */
/** One chunk's five planes of differences, decoded: four corner planes then water, 256 each. */
function decodeChunk(s: string | undefined): Int8Array {
  const raw = new Int8Array(RAW);
  if (!s) return raw;
  let bytes: number[];
  try { bytes = fromBase64(s); } catch { return raw; }
  let p = 0;
  for (let b = 0; b < bytes.length && p < RAW; b++) {
    if (bytes[b] === 0) { p += bytes[++b] ?? 0; continue; }
    raw[p++] = bytes[b] > 127 ? bytes[b] - 256 : bytes[b];
  }
  return raw;
}

/**
 * Online: another player has reshaped chunks of an island that is already in memory. Each chunk goes from
 * how this game had it (`was`, as saved) to how it now stands (`now`; null is the generator's own ground).
 * Returns the tiles whose ground or water moved.
 */
export function applyLandChange(w: World, was: LandBlock | undefined, now: Record<string, string | null>): number[] {
  const o = overlayOf(w, true)!;
  const out: number[] = [];
  for (const key of Object.keys(now)) {
    const k = Number(key);
    if (!(k >= 0 && k < CHUNKS * CHUNKS)) continue;
    const a = decodeChunk(was?.[k]), b = decodeChunk(now[key] ?? undefined);
    const tiles = chunkTiles(k);
    for (let t = 0; t < PLANE; t++) {
      let moved = false;
      for (let q = 0; q < 4; q++) {
        const d = b[q * PLANE + t] - a[q * PLANE + t];
        if (!d) continue;
        const c = tiles[t] * 4 + q;
        w.corners[c] += d;
        o.c[c] += d;
        moved = true;
      }
      const d = b[4 * PLANE + t] - a[4 * PLANE + t];
      const i = tiles[t];
      if (d) {
        w.water[i] += d;
        o.wt[i] += d;
        moved = true;
        if (w.water[i] < 0 && w.biome[i] === Biome.Ocean) { w.biome[i] = Biome.Beach; o.sea.add(i); }
      }
      if (moved) out.push(i);
    }
    o.chunks.add(k);
  }
  return out;
}

/**
 * Lay a save's overlay over a freshly generated island, before any of its edits replay. Then the
 * derived pass: sea bed the player brought above the water is beach, as it was when they did it.
 */
export function applyLand(w: World, block: LandBlock | undefined): void {
  if (!block) return;
  const o = overlayOf(w, true)!;
  for (const key of Object.keys(block)) {
    const k = Number(key);
    if (!(k >= 0 && k < CHUNKS * CHUNKS)) continue;
    let bytes: number[];
    try { bytes = fromBase64(block[k]); } catch { continue; }
    const raw = new Int8Array(RAW);
    let p = 0;
    for (let b = 0; b < bytes.length && p < RAW; b++) {
      if (bytes[b] === 0) { p += bytes[++b] ?? 0; continue; }
      raw[p++] = bytes[b] > 127 ? bytes[b] - 256 : bytes[b];
    }
    const tiles = chunkTiles(k);
    for (let q = 0; q < 4; q++) {
      for (let t = 0; t < PLANE; t++) {
        const d = raw[q * PLANE + t];
        if (!d) continue;
        const c = tiles[t] * 4 + q;
        w.corners[c] += d;
        o.c[c] += d;
      }
    }
    for (let t = 0; t < PLANE; t++) {
      const d = raw[4 * PLANE + t];
      const i = tiles[t];
      if (d) { w.water[i] += d; o.wt[i] += d; }
      if (d && w.water[i] < 0 && w.biome[i] === Biome.Ocean) { w.biome[i] = Biome.Beach; o.sea.add(i); }
    }
    o.chunks.add(k);
  }
}
