/**
 * A building in a county that isn't loaded, for a picture of it (the user, 5 Nov 2026: most fleets' cards in the
 * social window showed "far away: its county isn't loaded" in place of their HQ). The county is generated once off
 * the main thread (world/genWorker.ts `hero`), the building's shape and style read from it, and the world thrown
 * away; what came back is kept for the session, so a card asks once.
 *
 * As generated: a building the county's edits added (one put up from blueprints) is not in it, and is null, so the
 * card keeps its words for that one. A loaded county is always asked first (main.ts buildingSpec).
 */
import type { HeroSpec } from '../game/missions/model';
import type { GenReply, GenRequest, HeroBits } from './genWorker';

let worker: Worker | null = null;
let nextId = 1;
const done = new Map<string, HeroSpec | null>();
const asked = new Set<string>();

/** The spec for building `uid` of county (cx, cz) in `seed`'s world: undefined while it is being worked out (onReady is called once it is). */
export function farHero(seed: string, cx: number, cz: number, uid: number, onReady: () => void): HeroSpec | null | undefined {
  const key = `${seed}|${cx},${cz}#${uid}`;
  if (done.has(key)) return done.get(key)!;
  if (asked.has(key)) return undefined;
  asked.add(key);
  try { worker ??= new Worker(new URL('./genWorker.ts', import.meta.url), { type: 'module' }); } catch { done.set(key, null); return null; }
  const id = nextId++;
  const w = worker;
  const on = (e: MessageEvent<GenReply>): void => {
    if (e.data.id !== id) return;
    w.removeEventListener('message', on);
    const h = e.data.hero;
    done.set(key, h ? specOf(h, cx, cz, uid) : null);
    onReady();
  };
  w.addEventListener('message', on);
  w.postMessage({ id, seed, cx, cz, hero: uid } satisfies GenRequest);
  return undefined;
}

/** As game/hqHome.ts hqHero makes one from a loaded building. */
function specOf(h: HeroBits, cx: number, cz: number, uid: number): HeroSpec {
  return {
    kind: 'building', b: h.kind as never, arch: h.arch as never, w: h.w, d: h.d, floors: h.floors,
    real: { cx, cz, uid, seed: h.seed, facing: h.facing as never, ...(h.style ? { style: h.style as never } : {}), ...(h.derelict ? { derelict: true } : {}) },
  };
}
