import * as THREE from 'three';
import type { BuildingKind } from '../world/tiles';
import { KIND_SPEC } from '../world/townKinds';
import { follyId, follyLot, setFollySizer, type FollySize } from '../world/scenery';
import { GHOST_OK, buildGhost } from '../render/ghost';
import { LOBBY, kindLabel } from './lobby';
import { buildingIconInto } from './passportStamps';
import { pageKeys, sights } from './sights';

/**
 * The Folly collection (the Passport's Buildings seal, game/passportRewards.ts): any kind of building the player
 * has stamped, put up from the builder's Scenery side as decoration. No cargo, no deed, no work: only its model on the
 * ground, drawn by the town mesher in the style of the town it stands in (render/townMesh.ts). It is a scenery piece
 * like a tree (world/scenery.ts), saved and shared the same way, its id the kind behind `bp`.
 *
 * Only the kinds a town would build on a lot up to three tiles a side are offered (358 of the 494 stamps when this was
 * written): a stadium as an ornament would be a stadium, not scenery. Each stands at its smallest size and storeys.
 */

const MAX_SIDE = 3;
const lobby = new Map(LOBBY.map((r) => [r.kind as string, r]));
const least = (v: number | [number, number] | undefined): number | undefined => (v === undefined ? undefined : typeof v === 'number' ? v : v[0]);

const sizes = new Map<string, FollySize | null>();
/** A kind's folly: its lot (x by z at facing 0) and storeys; null for one too big or not known. */
export function follySize(kind: string): FollySize | null {
  if (sizes.has(kind)) return sizes.get(kind)!;
  const s = lobby.get(kind)?.spec ?? KIND_SPEC[kind as BuildingKind];
  let out: FollySize | null = null;
  if (s) {
    const w = least(s.w) ?? 1, d = least(s.d) ?? 1;
    if (w <= MAX_SIDE && d <= MAX_SIDE && kind.length <= 18) out = { w, d, floors: Math.max(1, least(s.floors) ?? 1), solid: s.solid !== false };
  }
  sizes.set(kind, out);
  return out;
}
setFollySizer(follySize);

/** What a folly costs to put up: a little, by its ground. */
export const follyPrice = (kind: string): number => {
  const z = follySize(kind);
  return z ? 150 * z.w * z.d : 0;
};

/** The kinds this player may put up: stamped, and small enough. In the Passport's order. */
export function follyKinds(): string[] {
  return pageKeys('kind').filter((k) => sights.has('kind', k) && follySize(k));
}

/**
 * The builder's side of it (game/roadBuilder.ts scenery hooks): the kinds on offer while `sealed()` (the Buildings
 * seal is in), their names, prices and menu pictures, and a ghost of the model turned to a facing, with a material
 * of its own the builder may tint.
 */
export function follyHooks(sealed: () => boolean): {
  follies(): string[];
  folly(kind: string): { label: string; price: number };
  follyIcon(img: HTMLImageElement, kind: string): void;
  follyGhost(kind: string, facing: number): THREE.Object3D | null;
} {
  return {
    follies: () => (sealed() ? follyKinds() : []),
    folly: (kind) => ({ label: kindLabel(kind), price: follyPrice(kind) }),
    follyIcon: (img, kind) => {
      const z = follySize(kind);
      if (z) buildingIconInto(img, kind as BuildingKind, 'classic', { w: z.w, d: z.d, floors: z.floors });
    },
    follyGhost: (kind, facing) => {
      const lot = follyLot({ x: 0, z: 0, p: follyId(kind), r: (facing & 3) * 2 });
      if (!lot) return null;
      const g = buildGhost({ kind: kind as BuildingKind, wx: lot.w, wz: lot.d, facing: lot.facing, floors: lot.size.floors, seed: 1, style: 'classic' }, GHOST_OK, null);
      const mat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.5, depthWrite: false });
      g.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) { m.material = mat; m.renderOrder = 8; } });
      g.userData.own = true;
      return g;
    },
  };
}
