import { hex, scale, type RGB } from '../../world/biomes';
import type { Building } from '../../world/tiles';
import { dockPlan, padPlan } from '../../world/spacePlans';
import { Vis, type Sched } from '../nightLights';
import { buildStage, storyStep } from '../storyProps';
import {
  DARK, METAL, ROOF_GREY, TAU, WHITE, pennant, row, win, type Draw, type Kit, type P3,
} from './kit';

/**
 * The story chains' two great structures (docs/storychains.html), drawn bigger than anything round them:
 *
 * - the spaceport's launch complex: a rocket on its mound inside a red umbilical tower, lightning masts,
 *   floodlights, the propellant spheres and the water tower, the vehicle assembly building and launch
 *   control by the gate, a crawler on the crawlerway, a press stand and the countdown clock. On the pad
 *   the chain Stargazers is bound to, the commercial rocket gives way over its last four missions to a
 *   moon rocket stacked a stage at a time, and the Army's tanks, the observatory's dish and the fans'
 *   tents arrive as the story does;
 * - the naval dry dock: a walled basin open to the sea behind a caisson gate, goliath cranes over it on
 *   their rails, a hammerhead crane, the fabrication hall and the pump house. In the dock the chain Still
 *   Waters is bound to, a submarine is built over its last four missions and the dock floods at the end.
 *
 * Layouts are in world/spacePlans.ts, shared with the footprints.
 */

const RED = hex(0xc8442f), CONC = hex(0xcbc6bb), PAD = hex(0x9c978e), STEEL = hex(0x9aa0a6), YELLOW = hex(0xf2b33b);
const BLACK = hex(0x2a2c30), NAVY = hex(0x2c3036), OLIVE = hex(0x5f6b3a), WATER_IN = hex(0x3f7f9a), RUST = hex(0x8a4f32);
const FLOOD: Sched = [18, 30.5, 2.4], BEACON: Sched = [0, 24, 3];

// ---- shapes the kit doesn't have ----------------------------------------------------------------

/** A round frustum lying along z from z0 (radius r0) to z1 (radius r1), its axis at (x, y); capped at both ends. */
function tube(k: Kit, x: number, y: number, z0: number, z1: number, r0: number, r1: number, col: RGB, seg = 14): void {
  const I: P3 = [x, y, (z0 + z1) / 2];
  const at = (a: number, r: number, z: number): P3 => [x + Math.cos(a) * r, y + Math.sin(a) * r, z];
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
    k.quad(at(a0, r0, z0), at(a1, r0, z0), at(a1, r1, z1), at(a0, r1, z1), col, I);
    if (r0 > 1e-3) k.tri([x, y, z0], at(a1, r0, z0), at(a0, r0, z0), col, [x, y, z0 + (z1 - z0) * 0.25]);
    if (r1 > 1e-3) k.tri([x, y, z1], at(a0, r1, z1), at(a1, r1, z1), col, [x, y, z1 - (z1 - z0) * 0.25]);
  }
}

/** A ball, as a stack of bands. */
function sphere(k: Kit, x: number, y: number, z: number, r: number, col: RGB, seg = 14, rings = 7): void {
  for (let j = 0; j < rings; j++) {
    const a0 = -Math.PI / 2 + (j / rings) * Math.PI, a1 = -Math.PI / 2 + ((j + 1) / rings) * Math.PI;
    k.band(x, z, y + Math.sin(a0) * r, Math.cos(a0) * r, y + Math.sin(a1) * r, Math.cos(a1) * r, seg, col);
  }
}

/** A square lattice tower: four posts, a frame and a cross-brace every bay. */
function truss(k: Kit, x: number, z: number, y0: number, y1: number, half: number, col: RGB, bay: number, r: number): void {
  const c: [number, number][] = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
  for (const [sx, sz] of c) k.bar([x + sx * half, y0, z + sz * half], [x + sx * half, y1, z + sz * half], r, col);
  const n = Math.max(1, Math.round((y1 - y0) / bay));
  for (let i = 0; i < n; i++) {
    const ya = y0 + ((y1 - y0) * i) / n, yb = y0 + ((y1 - y0) * (i + 1)) / n;
    for (let q = 0; q < 4; q++) {
      const [ax, az] = c[q], [bx, bz] = c[(q + 1) % 4];
      k.bar([x + ax * half, yb, z + az * half], [x + bx * half, yb, z + bz * half], r * 0.6, col);
      k.bar([x + ax * half, ya, z + az * half], [x + bx * half, yb, z + bz * half], r * 0.45, col);
    }
  }
}

/** Letters across a face looking +z, centred on x, standing on y. */
function letters(k: Kit, text: string, x: number, y: number, z: number, cell: number, col: RGB = WHITE): void {
  if (k.mode === 'derelict') return;
  const chars = [...text], w0 = -(chars.length * cell) / 2;
  chars.forEach((ch, i) => {
    if (ch === ' ') return;
    const xa = x + w0 + i * cell + cell * 0.05, xb = xa + cell * 0.9;
    k.glyph(ch, [xa, y, z], [xb, y, z], [xb, y + cell * 0.9, z], [xa, y + cell * 0.9, z], col);
  });
}

/** A floodlight mast: a pole and a lamp head that lights after dark. */
function floodMast(k: Kit, x: number, z: number, h: number, s: number): void {
  k.cyl(x, 0, z, 0.05 * s, h, STEEL, 6);
  k.box(x, h, z, 0.34 * s, 0.14 * s, 0.1 * s, DARK);
  k.tagged(Vis.Always, () => k.glowBox(x, h + 0.02 * s, z, 0.3 * s, 0.1 * s, 0.11 * s, hex(0xf4f2ec), FLOOD, hex(0xfff3d6)));
}

/** A toy tank parked on the hardstand: hull, turret and gun. */
function parkedTank(k: Kit, x: number, z: number, s: number, toward: number): void {
  k.box(x, 0, z, 0.55 * s, 0.16 * s, 0.34 * s, OLIVE);
  k.box(x, 0, z, 0.6 * s, 0.07 * s, 0.38 * s, DARK);
  k.box(x, 0.16 * s, z, 0.28 * s, 0.11 * s, 0.24 * s, scale(OLIVE, 0.9));
  k.bar([x, 0.22 * s, z], [x + toward * 0.42 * s, 0.24 * s, z], 0.02 * s, DARK);
}

// ---- the rockets -------------------------------------------------------------------------------

/**
 * The commercial launcher the pad flies every day: a white stick with a black interstage, grid fins and
 * folded legs, nine engines and a fat fairing on top. Returns its radius.
 */
function dailyRocket(k: Kit, y: number, z: number, s: number): number {
  const R = 0.3 * s, H1 = 4.2 * s, H2 = 1.2 * s;
  for (let i = 0; i < 9; i++) {
    const a = (i / 8) * TAU, rr = i === 8 ? 0 : R * 0.6;
    k.cone(Math.cos(a) * rr, y, z + Math.sin(a) * rr, 0.07 * s, 0.18 * s, DARK, 6);
  }
  const y1 = y + 0.12 * s;
  k.cyl(0, y1, z, R, H1, WHITE, 14);
  k.cyl(0, y1 + H1 * 0.12, z, R + 0.004, 0.12 * s, BLACK, 14);
  // the legs folded up the sides, and the grid fins near the top of the booster
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * TAU + TAU / 8, cx = Math.cos(a), sz = Math.sin(a);
    k.bar([cx * (R + 0.02), y1, z + sz * (R + 0.02)], [cx * (R + 0.02), y1 + 1.0 * s, z + sz * (R + 0.02)], 0.035 * s, BLACK);
    k.box(Math.cos(i * TAU / 4) * (R + 0.08 * s), y1 + H1 - 0.25 * s, z + Math.sin(i * TAU / 4) * (R + 0.08 * s), 0.14 * s, 0.14 * s, 0.14 * s, DARK);
  }
  // the interstage, the second stage and the fairing
  k.cyl(0, y1 + H1, z, R, 0.35 * s, BLACK, 14);
  k.cyl(0, y1 + H1 + 0.35 * s, z, R, H2, WHITE, 14);
  const fy = y1 + H1 + 0.35 * s + H2;
  k.band(0, z, fy, R, fy + 0.2 * s, R * 1.3, 14, WHITE);
  k.cyl(0, fy + 0.2 * s, z, R * 1.3, 0.8 * s, WHITE, 14);
  k.band(0, z, fy + 1.0 * s, R * 1.3, fy + 1.55 * s, R * 0.25, 14, WHITE);
  k.cone(0, fy + 1.55 * s, z, R * 0.25, 0.12 * s, WHITE, 10);
  return R;
}

/**
 * The moon rocket, stacked a stage at a time: 1 the first stage on its five engines and fins; 2 the second
 * and third stages under a temporary nose; 3 the adapter, the crew capsule and the escape tower on top;
 * 4 the same, fuelled and venting. Returns its radius.
 */
function moonRocket(k: Kit, y: number, z: number, s: number, stage: number): number {
  const R = 0.5 * s;
  // five big engines under a flared skirt, and the four fins
  for (let i = 0; i < 5; i++) {
    const a = (i / 4) * TAU, rr = i === 4 ? 0 : R * 0.55;
    k.cone(Math.cos(a) * rr, y, z + Math.sin(a) * rr, 0.16 * s, 0.32 * s, DARK, 8);
  }
  const y1 = y + 0.3 * s, H1 = 2.9 * s;
  k.band(0, z, y1, R * 1.15, y1 + 0.3 * s, R, 16, WHITE);
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * TAU + TAU / 8, cx = Math.cos(a), sz = Math.sin(a);
    k.quad([cx * R, y1, z + sz * R], [cx * (R + 0.42 * s), y1 - 0.05 * s, z + sz * (R + 0.42 * s)], [cx * (R + 0.3 * s), y1 + 0.55 * s, z + sz * (R + 0.3 * s)], [cx * R, y1 + 0.75 * s, z + sz * R], WHITE, [0, y1 + 0.3 * s, z]);
    k.quad([cx * R, y1, z + sz * R], [cx * R, y1 + 0.75 * s, z + sz * R], [cx * (R + 0.3 * s), y1 + 0.55 * s, z + sz * (R + 0.3 * s)], [cx * (R + 0.42 * s), y1 - 0.05 * s, z + sz * (R + 0.42 * s)], WHITE, [cx * (R + 2), y1, z + sz * (R + 2)]);
  }
  k.cyl(0, y1 + 0.3 * s, z, R, H1 - 0.3 * s, WHITE, 16);
  // the roll pattern: black quarters at the foot and the head of the first stage
  for (const [yy, hh] of [[y1 + 0.3 * s, 0.7 * s], [y1 + H1 - 0.5 * s, 0.5 * s]] as [number, number][]) {
    for (let q = 0; q < 2; q++) {
      const a = q * Math.PI;
      k.box(Math.cos(a) * R * 0.72, yy, z + Math.sin(a) * R * 0.72, R * 0.62, hh, R * 1.05, BLACK);
    }
  }
  let top = y1 + H1;
  k.cyl(0, top - 0.05 * s, z, R + 0.006, 0.1 * s, BLACK, 16);
  if (stage >= 2) {
    // the second stage, its black interstage ring, and the third on its tapering adapter
    k.cyl(0, top, z, R, 2.0 * s, WHITE, 16);
    k.cyl(0, top, z, R + 0.006, 0.18 * s, scale(WHITE, 0.82), 16);
    top += 2.0 * s;
    k.band(0, z, top, R, top + 0.35 * s, R * 0.74, 16, WHITE);
    top += 0.35 * s;
    k.cyl(0, top, z, R * 0.74, 1.25 * s, WHITE, 16);
    k.box(R * 0.5, top + 0.2 * s, z, R * 0.5, 0.5 * s, R * 0.9, BLACK);
    top += 1.25 * s;
    if (stage === 2) {
      // a plain nose over the open top until the capsule comes
      k.band(0, z, top, R * 0.74, top + 0.6 * s, R * 0.2, 16, WHITE);
      top += 0.6 * s;
    } else {
      // the adapter, the service module and the cone of the capsule, and the escape tower over it
      k.band(0, z, top, R * 0.74, top + 0.6 * s, R * 0.52, 16, WHITE);
      top += 0.6 * s;
      k.cyl(0, top, z, R * 0.52, 0.4 * s, hex(0xd9dde2), 16);
      top += 0.4 * s;
      k.band(0, z, top, R * 0.52, top + 0.42 * s, R * 0.12, 16, hex(0xe6e9ec));
      top += 0.42 * s;
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * TAU;
        k.bar([Math.cos(a) * R * 0.14, top, z + Math.sin(a) * R * 0.14], [0, top + 0.35 * s, z], 0.012 * s, DARK);
      }
      k.cyl(0, top + 0.35 * s, z, 0.06 * s, 0.35 * s, hex(0xd8d8d8), 8);
      k.cone(0, top + 0.7 * s, z, 0.06 * s, 0.14 * s, RED, 8);
      top += 0.84 * s;
    }
  }
  if (stage >= 4) {
    // fuelled: frost venting off the cold stages, and the spotlights on it after dark
    for (const [yy, ox] of [[y1 + 1.4 * s, 1], [y1 + H1 + 1.2 * s, -1], [y1 + H1 + 2.6 * s, 1]] as [number, number][]) {
      k.dome(ox * (R + 0.1 * s), yy, z, 0.16 * s, hex(0xf2f4f6), 8, 2);
      k.dome(ox * (R + 0.28 * s), yy + 0.06 * s, z + 0.05 * s, 0.12 * s, hex(0xf7f8f9), 8, 2);
    }
    for (const ox of [-1, 1]) k.dome(ox * 0.9 * s, y - 0.25 * s, z - 0.4 * s, 0.45 * s, hex(0xeef0f2), 10, 3);
  }
  return R;
}

// ---- the launch complex ------------------------------------------------------------------------

export const launchPad: Draw = (k, W, D, b, r) => {
  const p = padPlan(W, D), s = p.s, cz = p.cz;
  const steps = storyStep('moon', k.world, b), stage = buildStage(steps);
  // the hardstand round the mound, the mound, and the flame trench out of the back of it
  k.disc(0, 0.004, cz, p.stand, CONC, 28);
  const mh = 0.3 * s;
  k.cyl(0, 0, cz, p.mound, mh, PAD, 24, scale(PAD, 1.05));
  k.box(0, mh, cz - p.mound * 0.5, 0.8 * s, 0.006, p.mound * 1.0, DARK);
  for (const sx of [-1, 1]) k.box(sx * 0.5 * s, 0, cz - p.mound - 0.7 * s, 0.16 * s, 0.36 * s, 1.4 * s, CONC);
  k.box(0, 0.006, cz - p.mound - 0.7 * s, 0.84 * s, 0.006, 1.4 * s, DARK);
  // the launcher platform the rocket stands on, its hold-down posts and the tail service masts
  const base = mh + 0.22 * s;
  k.box(0, mh, cz, 1.7 * s, 0.22 * s, 1.7 * s, hex(0x6b6f75), hex(0x8a8f96));
  // the rocket of the day, or the moon rocket as Stargazers stacks it
  const R = stage > 0 ? moonRocket(k, base, cz, s, stage) : dailyRocket(k, base, cz, s);
  // the launch umbilical tower, its hammerhead crane, and its swing arms to the rocket (swung back at T-minus)
  const t = p.tower, ty = base + t.h;
  truss(k, t.x, t.z, base, ty, t.half, RED, 0.55 * s, 0.035 * s);
  k.box(t.x, ty, t.z, t.half * 2 + 0.12 * s, 0.12 * s, t.half * 2 + 0.12 * s, RED);
  k.box(t.x + 0.35 * s, ty + 0.12 * s, t.z, 1.6 * s, 0.1 * s, 0.12 * s, YELLOW);
  k.box(t.x - 0.25 * s, ty + 0.12 * s, t.z, 0.3 * s, 0.24 * s, 0.24 * s, scale(YELLOW, 0.85));
  k.bar([t.x + 1.1 * s, ty + 0.12 * s, t.z], [t.x + 1.1 * s, ty - 0.9 * s, t.z], 0.008, DARK);
  k.cyl(t.x, ty + 0.12 * s, t.z, 0.03 * s, 1.1 * s, hex(0xe6e6e6), 6);
  k.tagged(Vis.Always, () => k.glowBox(t.x, ty + 1.22 * s, t.z, 0.06 * s, 0.06 * s, 0.06 * s, RED, BEACON, hex(0xff3b30)));
  const rocketTop = stage > 0 ? (stage >= 2 ? 9.0 : 3.6) * s : 7.2 * s;
  const armYs = (stage > 0 ? [2.1, 3.5, 5.2, 6.4, 7.6] : [1.4, 2.6, 3.9, 5.1, 6.4]).map((y) => y * s).filter((y) => y < rocketTop - 0.2 * s);
  const tx1 = t.x + t.half, rx = -R - 0.02 * s;
  for (const y of armYs) {
    if (stage >= 4) {
      // swung back against the tower, out of the rocket's way
      k.box(tx1 + 0.06 * s, base + y, t.z + t.half + 0.45 * s, 0.1 * s, 0.1 * s, 0.9 * s, RED);
    } else {
      k.box((tx1 + rx) / 2, base + y, t.z, rx - tx1, 0.1 * s, 0.14 * s, RED);
      k.box(rx - 0.04 * s, base + y - 0.04 * s, t.z, 0.08 * s, 0.18 * s, 0.22 * s, hex(0xe6e6e6));
    }
  }
  // the lightning masts either side, wired together over the rocket, a beacon on each
  const mh2 = 10.4 * s, mz = cz + 0.9 * s;
  for (const sx of [-1, 1]) {
    k.cyl(sx * 3.0 * s, 0, mz, 0.08 * s, mh2, hex(0xdedede), 8);
    k.tagged(Vis.Always, () => k.glowBox(sx * 3.0 * s, mh2, mz, 0.08 * s, 0.08 * s, 0.08 * s, RED, BEACON, hex(0xff3b30)));
  }
  k.bar([-3.0 * s, mh2, mz], [0, mh2 - 0.5 * s, mz], 0.008, DARK);
  k.bar([0, mh2 - 0.5 * s, mz], [3.0 * s, mh2, mz], 0.008, DARK);
  // floodlights at the hardstand's corners, lit after dark
  const fl = p.stand * 0.78;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) floodMast(k, sx * fl, cz + sz * fl, 2.7 * s, s);
  // the propellant spheres on their skirts, piped to the pad
  for (const sp of [p.lox, p.lh2]) {
    k.cyl(sp.x, 0, sp.z, sp.r * 0.6, sp.r * 0.6, CONC, 12);
    sphere(k, sp.x, sp.r * 1.25, sp.z, sp.r, WHITE);
    k.cyl(sp.x, sp.r * 2.25, sp.z, 0.06 * s, 0.25 * s, STEEL, 6);
    const toward = Math.sign(-sp.x);
    k.bar([sp.x + toward * sp.r * 0.6, 0.18 * s, sp.z], [toward * -p.mound * 0.9, 0.18 * s, cz], 0.04 * s, STEEL);
  }
  // the water tower that floods the pad as it lights
  const wt = p.water;
  for (const [sx, sz] of [[-1, -1], [1, -1], [1, 1], [-1, 1]] as [number, number][]) {
    k.bar([wt.x + sx * wt.r * 0.9, 0, wt.z + sz * wt.r * 0.9], [wt.x + sx * wt.r * 0.45, wt.h, wt.z + sz * wt.r * 0.45], 0.04 * s, STEEL);
  }
  k.bar([wt.x - wt.r * 0.7, wt.h * 0.45, wt.z], [wt.x + wt.r * 0.7, wt.h * 0.45, wt.z], 0.025 * s, STEEL);
  k.bar([wt.x, wt.h * 0.45, wt.z - wt.r * 0.7], [wt.x, wt.h * 0.45, wt.z + wt.r * 0.7], 0.025 * s, STEEL);
  sphere(k, wt.x, wt.h + wt.r * 0.7, wt.z, wt.r, hex(0xe8ecee));
  k.bar([wt.x, 0.15 * s, wt.z], [0.5 * s, 0.15 * s, cz - p.mound], 0.05 * s, STEEL);
  // the vehicle assembly building: its high bay door toward the pad, the flag and the name toward the gate
  const v = p.vab;
  k.box(v.x, 0, v.z, v.w, v.h, v.d, hex(0xe1e3e4), hex(0xb9bdc2));
  k.box(v.x + v.w / 2 + 0.4 * s, 0, v.z + 0.4 * s, 0.8 * s, 1.2 * s, v.d * 0.7, hex(0xd6d9dc), ROOF_GREY);
  k.box(v.x, 0, v.z - v.d / 2 - 0.012, 1.3 * s, v.h * 0.86, 0.03, hex(0x9aa3ab));
  for (let i = 1; i < 6; i++) k.box(v.x, (v.h * 0.86 * i) / 6, v.z - v.d / 2 - 0.03, 1.3 * s, 0.02 * s, 0.01, scale(hex(0x9aa3ab), 0.8));
  const fz = v.z + v.d / 2 + 0.012, fx = v.x - v.w * 0.18, fyy = v.h * 0.42;
  for (let i = 0; i < 7; i++) k.box(fx, fyy + i * 0.17 * s, fz, 1.6 * s, 0.17 * s, 0.02, i % 2 ? WHITE : hex(0xc23a32));
  k.box(fx - 0.45 * s, fyy + 0.68 * s, fz + 0.004, 0.7 * s, 0.52 * s, 0.02, hex(0x2f4d8a));
  k.face(v.x + v.w * 0.3, v.h * 0.55, fz + 0.01, 0.55 * s, hex(0x2f4d8a), 16);
  k.face(v.x + v.w * 0.3, v.h * 0.55, fz + 0.014, 0.38 * s, WHITE, 16);
  k.face(v.x + v.w * 0.3, v.h * 0.55, fz + 0.018, 0.22 * s, RED, 12);
  letters(k, 'SPACEPORT', v.x, v.h - 0.55 * s, fz + 0.02, 0.36 * s, hex(0x2f4d8a));
  // the crawlerway from the high bay out to the pad, and the crawler waiting on it
  const cw = hex(0xd8cfb4);
  k.box(v.x, 0.004, (v.z - v.d / 2 + 0.4 * s) / 2, 1.4 * s, 0.006, Math.abs(v.z - v.d / 2 - 0.4 * s), cw);
  k.box((v.x - p.mound * 0.4) / 2, 0.004, 0.4 * s, Math.abs(v.x + p.mound * 0.4) + 1.4 * s, 0.006, 1.4 * s, cw);
  const cx2 = v.x, cz2 = v.z - v.d / 2 - 1.6 * s;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(cx2 + sx * 0.45 * s, 0, cz2 + sz * 0.4 * s, 0.3 * s, 0.18 * s, 0.34 * s, DARK);
  k.box(cx2, 0.18 * s, cz2, 1.3 * s, 0.14 * s, 1.2 * s, hex(0x8a8f96), hex(0x6b6f75));
  k.box(cx2 - 0.5 * s, 0.32 * s, cz2 - 0.45 * s, 0.24 * s, 0.16 * s, 0.2 * s, WHITE);
  // launch control, its windows on the pad and a dish on its roof
  const c = p.lcc;
  k.box(c.x, 0, c.z, c.w, c.h, c.d, hex(0xdcd6c8), ROOF_GREY);
  row(k, b, r, c.x, c.h * 0.42, c.z - c.d / 2, c.w * 0.86, 0.32 * s, 7, 3);
  row(k, b, r, c.x, c.h * 0.42, c.z + c.d / 2, c.w * 0.86, 0.32 * s, 7, 1);
  k.cyl(c.x + c.w * 0.3, c.h, c.z, 0.05 * s, 0.3 * s, STEEL, 6);
  k.band(c.x + c.w * 0.3, c.z, c.h + 0.3 * s, 0.04 * s, c.h + 0.5 * s, 0.38 * s, 12, hex(0xeef0f2), hex(0xd6dade));
  // the press stand by the gate, and the countdown clock
  k.wedge(W / 2 - 2.0 * s, 0, D / 2 - 3.2 * s, 2.2 * s, 0.5 * s, 0.9 * s, hex(0xb9bdc2));
  for (let i = 0; i < 6; i++) k.box(W / 2 - 3.0 * s + i * 0.38 * s, 0.25 * s + (i % 2) * 0.02, D / 2 - 3.05 * s, 0.07 * s, 0.1 * s, 0.06 * s, [hex(0xe2412f), hex(0x2f7fb5), hex(0xf2c14e)][i % 3]);
  const kx = -1.9 * s, kz = D / 2 - 0.9 * s;
  for (const sx of [-1, 1]) k.box(kx + sx * 0.7 * s, 0, kz, 0.06 * s, 0.5 * s, 0.06 * s, DARK);
  k.box(kx, 0.5 * s, kz, 1.7 * s, 0.5 * s, 0.1 * s, BLACK);
  const count = stage >= 4 ? 'T-10' : stage > 0 ? `T-${20 - steps}D` : 'T-72H';
  k.tagged(Vis.Always, () => letters(k, count, kx, 0.58 * s, kz + 0.055 * s, 0.32 * s, hex(0xffb030)));
  pennant(k, kx + 1.2 * s, 0, kz, 1.4 * s, hex(0x2f4d8a));
  // ---- what the story brings to this pad ----
  if (steps >= 12) {
    // the Army's tanks at the hardstand's corners
    parkedTank(k, -p.stand - 0.2 * s, cz + p.stand * 0.6, s, 1);
    parkedTank(k, p.stand + 0.2 * s, cz + p.stand * 0.6, s, -1);
    parkedTank(k, -p.stand - 0.2 * s, cz - p.stand * 0.5, s, 1);
  }
  if (steps >= 13) {
    // the observatory's big dish, towed in and standing beside the pad
    const dx = -W / 2 + 1.6 * s, dz = -D / 2 + 1.4 * s;
    k.cyl(dx, 0, dz, 0.18 * s, 0.8 * s, CONC, 8);
    k.band(dx, dz, 0.8 * s, 0.1 * s, 1.3 * s, 1.0 * s, 16, hex(0xeef0f2), hex(0xd9dde2));
    for (let i = 0; i < 3; i++) {
      const a = (i / 3) * TAU;
      k.bar([dx + Math.cos(a) * 0.9 * s, 1.27 * s, dz + Math.sin(a) * 0.9 * s], [dx, 1.95 * s, dz], 0.012 * s, DARK);
    }
    k.box(dx, 1.95 * s, dz, 0.1 * s, 0.1 * s, 0.1 * s, DARK);
  }
  if (steps >= 15) {
    // the fans' camp outside the gate
    const cols = [hex(0xe2412f), hex(0xf2c14e), hex(0x3f9b4a), hex(0x2f7fb5), hex(0x8e5cc7), hex(0xf28c38)];
    for (let i = 0; i < 6; i++) {
      const x = 0.9 * s + (i % 3) * 0.55 * s, z = D / 2 - 0.5 * s - Math.floor(i / 3) * 0.55 * s;
      k.gable(x, 0, z, 0.36 * s, 0.24 * s, 0.4 * s, cols[i], scale(cols[i], 0.85));
    }
  }
  if (stage >= 4) {
    // T-minus: searchlights stood round the pad on the rocket
    for (const sx of [-1, 1]) {
      k.tagged(Vis.Always, () => k.glowBox(sx * 1.4 * s, mh + 0.02, cz + 1.4 * s, 0.14 * s, 0.14 * s, 0.14 * s, hex(0xf4f2ec), FLOOD, hex(0xe6eeff)));
    }
  }
};

// ---- the submarines in the dock ----------------------------------------------------------------

/**
 * The submarine in the bound dock, at its stage: 1 the pressure hull in frames with plating going on
 * over the bow half; 2 plated all over, and the pressure sphere hanging from the crane over the open
 * hatch; 3 the sail with its planes and masts, the tail and the screw; 4 the same afloat.
 */
function dockSub(k: Kit, y: number, z0: number, z1: number, stage: number): void {
  const R = 0.42, mid = (z0 + z1) / 2, cy = y + R;
  const bow = z1 - 0.7, stern = z0 + 1.1;
  if (stage === 1) {
    // the frames from stern to bow, the keel, and the plates on the bow half
    for (let z = stern; z <= bow; z += 0.32) k.hoop(0, cy, z, R, 0.025, RUST, 14, 'xy');
    k.box(0, y, mid, 0.08, 0.06, bow - stern, RUST);
    tube(k, 0, cy, mid + 0.4, bow, R, R, NAVY);
    tube(k, 0, cy, bow, z1 - 0.1, R, 0.12, NAVY);
    // scaffold along one side
    for (let z = stern; z < bow; z += 0.9) k.bar([R + 0.18, y, z], [R + 0.18, cy + R + 0.2, z], 0.015, YELLOW);
    k.bar([R + 0.18, cy + R + 0.2, stern], [R + 0.18, cy + R + 0.2, bow], 0.015, YELLOW);
    k.bar([R + 0.18, cy, stern], [R + 0.18, cy, bow], 0.015, YELLOW);
    return;
  }
  // plated: the long hull, the rounded bow and the tapering stern
  tube(k, 0, cy, stern, bow, R, R, NAVY);
  tube(k, 0, cy, bow, z1 - 0.05, R, 0.1, NAVY);
  tube(k, 0, cy, z0 + 0.1, stern, 0.06, R, NAVY);
  k.box(0, cy + R - 0.02, mid + 0.2, 0.26, 0.05, bow - stern - 0.6, hex(0x3a3f45));
  if (stage === 2) {
    // the hatch left open for the sphere, which hangs from the crane over it
    k.box(0, cy + R + 0.02, mid, 0.5, 0.03, 0.7, BLACK);
    return;
  }
  // the sail, its planes and masts; the tail planes and the shrouded screw
  const sz = mid + 0.9;
  k.box(0, cy + R - 0.05, sz, 0.22, 0.75, 1.0, NAVY);
  k.box(0, cy + R + 0.45, sz + 0.05, 1.0, 0.04, 0.24, NAVY);
  k.box(0, cy + R + 0.7, sz, 0.24, 0.02, 0.9, hex(0x3a3f45));
  k.cyl(0.03, cy + R + 0.7, sz + 0.2, 0.025, 0.45, DARK, 6);
  k.cyl(-0.03, cy + R + 0.7, sz - 0.1, 0.02, 0.32, DARK, 6);
  k.box(0, cy - R - 0.2, z0 + 0.6, 0.04, R * 2 + 0.4, 0.4, NAVY);
  k.box(0, cy, z0 + 0.6, R * 2 + 0.5, 0.04, 0.4, NAVY);
  tube(k, 0, cy, z0 - 0.12, z0 + 0.12, 0.2, 0.2, BLACK);
  // a red waterline band
  tube(k, 0, cy - 0.02, stern + 0.2, bow - 0.2, R + 0.006, R + 0.006, scale(hex(0x8a2f2a), 1), 14);
  tube(k, 0, cy + 0.04, stern + 0.2, bow - 0.2, R + 0.012, R + 0.012, NAVY, 14);
}

// ---- the naval dry dock ------------------------------------------------------------------------

export const navalDock: Draw = (k, W, D, b, r) => {
  const p = dockPlan(W, D), half = p.bw / 2, T = p.thick, H = p.wall;
  const steps = storyStep('deep', k.world, b), stage = buildStage(steps);
  const flooded = stage >= 4;
  const quay = hex(0xc9c2b2), floor = hex(0x6d6a64);
  const len = p.front - p.back;
  // the basin floor with its drain and keel blocks, the stepped altars down the sides, the walls and copings
  k.box(0, 0.004, (p.back + p.front) / 2, p.bw, 0.006, len, floor);
  k.box(0, 0.008, (p.back + p.front) / 2, 0.16, 0.006, len, scale(floor, 0.75));
  for (const sx of [-1, 1]) {
    for (let i = 0; i < 3; i++) {
      k.box(sx * (half - 0.08 - i * 0.12), 0, (p.back + p.front) / 2, 0.14, H * (0.75 - i * 0.22), len, scale(quay, 0.86 + i * 0.03));
    }
    k.box(sx * (half + T / 2), 0, (p.back + p.front) / 2 - T / 2, T, H, len + T, quay);
    k.box(sx * (half + T / 2), H, (p.back + p.front) / 2 - T / 2, T + 0.04, 0.05, len + T, scale(quay, 1.08));
    // bollards along the copings
    for (let z = p.back + 0.6; z < p.front - 0.2; z += 1.1) k.cyl(sx * (half + T + 0.12), 0, z, 0.06, 0.14, DARK, 8);
    // the crane rails along the aprons
    k.box(sx * (half + T + 0.55), 0.006, (p.back + p.front) / 2, 0.06, 0.012, len, DARK);
  }
  k.box(0, 0, p.back - T / 2, p.bw + T * 2, H, T, quay);
  k.box(0, H, p.back - T / 2, p.bw + T * 2, 0.05, T + 0.04, scale(quay, 1.08));
  // what is in the dock: the story's submarine, or a cargo ship on the blocks for an ordinary refit
  const blocksY = 0.08;
  for (let z = p.back + 0.9; z < p.front - 0.8; z += 0.7) k.box(0, 0, z, 0.36, blocksY, 0.2, hex(0x8d6d48));
  if (flooded) {
    // flooded and afloat: the water up the walls, the sub riding high, the gate floated aside
    k.box(0, 0, (p.back + p.front) / 2, p.bw, H * 0.82, len, WATER_IN, WATER_IN);
    dockSub(k, H * 0.82 - 0.55, p.back + 0.4, p.front - 0.3, 3);
  } else if (stage > 0) {
    dockSub(k, blocksY, p.back + 0.4, p.front - 0.3, stage);
  } else {
    // a cargo ship in for a refit: red below the line, a black hull, a white house aft
    const hl = len - 1.4, hz = (p.back + p.front) / 2 - 0.1;
    k.box(0, blocksY, hz, p.bw * 0.6, 0.45, hl, hex(0x8a3f36), hex(0x8a3f36));
    k.box(0, blocksY + 0.45, hz, p.bw * 0.62, 0.42, hl, hex(0x2f3a44), hex(0x7a7f86));
    k.wedge(0, blocksY, hz + hl / 2 + 0.3, p.bw * 0.6, 0.87, 0.6, hex(0x2f3a44));
    k.box(0, blocksY + 0.87, hz - hl / 2 + 0.6, p.bw * 0.5, 0.6, 0.9, WHITE, hex(0xd9dde2));
    win(k, b, r, 0, blocksY + 1.2, hz - hl / 2 + 1.05, 0.9, 0.12, 1);
    k.cyl(0, blocksY + 1.47, hz - hl / 2 + 0.4, 0.12, 0.4, hex(0xe2412f), 8);
    for (let i = 0; i < 4; i++) k.box(0, blocksY + 0.87, hz - hl / 2 + 1.6 + i * 0.7, p.bw * 0.5, 0.3, 0.6, [hex(0xe2412f), hex(0x2f7fb5), hex(0xf2c14e), hex(0x3f9b4a)][i]);
  }
  // the caisson gate across the sea end: closed, or floated round against the wall once the dock floods
  if (flooded) k.box(half + T + 0.25, 0, p.front - 0.3, 0.4, H + 0.1, 1.1, RUST, hex(0x6b6f75));
  else {
    k.box(0, 0, p.front - 0.2, p.bw + 0.1, H + 0.1, 0.4, RUST, hex(0x6b6f75));
    k.box(0, H * 0.55, p.front - 0.2 + 0.205, p.bw + 0.1, 0.07, 0.01, WHITE);
  }
  // the goliath cranes: legs on the rails either side, a girder over the basin, a trolley and a hook
  const gh = 2.6, cranes = [p.back + len * 0.32, p.back + len * 0.72];
  cranes.forEach((gz, ci) => {
    for (const sx of [-1, 1]) {
      const lx = sx * (half + T + 0.55);
      k.bar([lx, 0, gz - 0.35], [lx, gh, gz], 0.06, YELLOW);
      k.bar([lx, 0, gz + 0.35], [lx, gh, gz], 0.06, YELLOW);
      k.box(lx, 0, gz, 0.2, 0.12, 0.9, DARK);
    }
    k.box(0, gh, gz, 2 * (half + T + 0.7), 0.24, 0.32, YELLOW, scale(YELLOW, 1.05));
    k.box(0, gh + 0.24, gz, 0.4, 0.2, 0.4, scale(YELLOW, 0.88));
    // the first crane lowers the pressure sphere into the hull while Still Waters is at that stage
    if (ci === 0 && stage === 2) {
      const sy = blocksY + 0.42 * 2 + 0.9;
      k.bar([0, gh, gz], [0, sy + 0.5, gz], 0.012, DARK);
      sphere(k, 0, sy, gz, 0.42, hex(0xb9bdc2), 14, 7);
      k.hoop(0, sy, gz, 0.43, 0.02, DARK, 14, 'xz');
    } else k.bar([0, gh, gz], [0, gh - 0.8, gz], 0.01, DARK);
  });
  // the hammerhead crane on the seaward corner of the left apron
  const hx = -(half + T + 0.95), hz2 = p.front - 1.0;
  if (W / 2 - Math.abs(hx) > 0.15) {
    k.cyl(hx, 0, hz2, 0.22, 0.12, CONC, 8);
    k.box(hx, 0.1, hz2, 0.22, 3.6, 0.22, hex(0xe8e8e8));
    for (let y = 0.6; y < 3.6; y += 0.6) k.box(hx, y, hz2, 0.26, 0.08, 0.26, RED);
    k.box(hx + 0.8, 3.7, hz2, 2.6, 0.14, 0.16, RED);
    k.box(hx - 0.25, 3.84, hz2, 0.36, 0.2, 0.3, hex(0xe8e8e8));
    k.bar([hx + 1.8, 3.7, hz2], [hx + 1.8, 2.4, hz2], 0.008, DARK);
    k.tagged(Vis.Always, () => k.glowBox(hx + 2.05, 3.86, hz2, 0.05, 0.05, 0.05, RED, BEACON, hex(0xff3b30)));
  }
  // the fabrication hall: sawtooth roof, a big door on the dock, lit windows down its side
  const hl2 = p.hall;
  k.box(hl2.x, 0, hl2.z, hl2.w, hl2.h, hl2.d, hex(0xb9c2c8), ROOF_GREY);
  for (let i = 0; i < 3; i++) {
    const zz = hl2.z - hl2.d / 2 + (i + 0.5) * (hl2.d / 3);
    k.wedge(hl2.x, hl2.h, zz, hl2.w, 0.3, hl2.d / 3, ROOF_GREY);
  }
  k.box(hl2.x + 0.3, 0, hl2.z + hl2.d / 2 + 0.01, 1.2, 1.15, 0.02, hex(0x6b7680));
  row(k, b, r, hl2.x, 0.9, hl2.z - hl2.d / 2, hl2.w * 0.8, 0.24, 5, 3);
  letters(k, 'NAVAL DOCK', hl2.x, hl2.h - 0.42, hl2.z + hl2.d / 2 + 0.03, 0.26, hex(0x2f4d7a));
  // the pump house that floods and empties the dock, with its stack
  const pu = p.pump;
  k.box(pu.x, 0, pu.z, pu.w, pu.h, pu.d, hex(0xa4583f), ROOF_GREY);
  k.gable(pu.x, pu.h, pu.z, pu.w, 0.2, pu.d, ROOF_GREY, hex(0xa4583f), true);
  k.cyl(pu.x, 0, pu.z - pu.d / 2 + 0.12, 0.07, 1.4, hex(0x8a8a8a), 8);
  win(k, b, r, pu.x - pu.w / 2, 0.25, pu.z, 0.3, 0.16, 2);
  // the yard at the back right: a guard hut, a navy flag, stacked hull plates and a parked truck
  const yx = W / 2 - 1.2, yz = -D / 2 + 0.7;
  k.box(yx, 0, yz, 0.45, 0.4, 0.4, WHITE, hex(0x2f4d7a));
  win(k, b, r, yx, 0.18, yz + 0.2, 0.25, 0.12, 1);
  pennant(k, yx + 0.45, 0, yz + 0.1, 1.5, hex(0x2f4d8a));
  for (let i = 0; i < 4; i++) k.box(yx - 0.9, i * 0.05, yz + 0.75, 0.8, 0.05, 0.5, scale(STEEL, 0.9 + (i % 2) * 0.08));
  k.box(yx - 0.2, 0, yz + 1.35, 0.3, 0.18, 0.62, hex(0x5f6b3a));
  // floodlight masts on the aprons
  for (const sx of [-1, 1]) floodMast(k, sx * (W / 2 - 0.25), p.back + len * 0.52, 2.2, 1);
  void METAL;
};

/** The story's submarine in a harbour's little dry dock, when no naval dock was near enough to bind. */
export function smallDockSub(k: Kit, b: Building, dw: number, dd: number): boolean {
  const steps = storyStep('deep', k.world, b), stage = buildStage(steps);
  if (stage <= 0) return false;
  const sc = Math.min(1, dw / 2.8);
  k.turned(0, () => {
    // drawn at the little dock's own scale, in the cut of its floor
    const R = 0.42 * sc;
    if (stage >= 4) k.box(0, -0.42, 0, dw, 0.6, dd, WATER_IN, WATER_IN);
    const y = stage >= 4 ? -0.1 : -0.42 + 0.06;
    tube(k, 0, y + R, -dd / 2 + 0.3, dd / 2 - 0.4, R, R, NAVY);
    tube(k, 0, y + R, dd / 2 - 0.4, dd / 2 - 0.1, R, 0.08, NAVY);
    if (stage >= 3) {
      k.box(0, y + R * 2 - 0.04, 0.2, 0.14 * sc, 0.45 * sc, 0.6 * sc, NAVY);
      k.box(0, y + R * 2 + 0.25 * sc, 0.22, 0.6 * sc, 0.03, 0.16 * sc, NAVY);
    }
  });
  return true;
}
