/**
 * The diamond (docs/territory.html): a little faceted gem, drawn in 3D by hand on a 2D canvas (six-sided,
 * a short crown over a long pavilion, like the plumbob over a Sim's head), turning slowly wherever the
 * game shows diamonds. The chip beside the cash holds one; every whole diamond earned sets off a burst
 * there: the gem spins up and swells, a bigger one swoops in and lands on it, sparks fly, a ring goes out
 * and the count ticks up under a rising "+1". No WebGL: a dozen triangles, flat-shaded, sorted back to front.
 */

type RGB = [number, number, number];

/** The gem's own colour: ice blue, bright enough to read on the white chip and on the dark maps. */
const GEM: RGB = [54, 196, 232];
const SIDES = 6;
const CROWN = 0.72, PAVILION = 1.38;
/** Light from the upper left, towards the viewer. */
const L = norm([-0.45, 0.8, 0.55]);
const H = norm([L[0], L[1], L[2] + 1]);

function norm(v: [number, number, number]): [number, number, number] {
  const l = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / l, v[1] / l, v[2] / l];
}

const hexRgb = (css: string | undefined): RGB | null => {
  const m = css ? /^#?([0-9a-f]{6})$/i.exec(css.trim()) : null;
  if (!m) return null;
  const n = parseInt(m[1], 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
};

/**
 * One gem, its middle at (x, y), `size` pixels from tip to tip, turned `yaw` about its long axis and
 * tipped `tilt` towards the viewer. `glow` (0–1) puts a soft halo behind it.
 */
function drawGem(ctx: CanvasRenderingContext2D, x: number, y: number, size: number, yaw: number, tilt = 0.32, glow = 0, colour: RGB = GEM): void {
  const s = size / (CROWN + PAVILION);
  const cy = y - ((CROWN - PAVILION) / 2) * s;
  const ct = Math.cos(tilt), st = Math.sin(tilt);
  // model space: y up, z towards the viewer; then tipped about x
  const P = (px: number, py: number, pz: number): [number, number, number] => [px, py * ct - pz * st, py * st + pz * ct];
  const top = P(0, CROWN, 0), bottom = P(0, -PAVILION, 0);
  const ring: [number, number, number][] = [];
  for (let i = 0; i < SIDES; i++) {
    const a = yaw + (i * Math.PI * 2) / SIDES;
    ring.push(P(Math.cos(a), 0, Math.sin(a)));
  }
  const faces: { v: [number, number, number][]; z: number; shade: number }[] = [];
  const face = (a: [number, number, number], b: [number, number, number], c: [number, number, number], alt: number) => {
    const u = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], w = [c[0] - a[0], c[1] - a[1], c[2] - a[2]];
    const n = norm([u[1] * w[2] - u[2] * w[1], u[2] * w[0] - u[0] * w[2], u[0] * w[1] - u[1] * w[0]]);
    if (n[2] <= 0) return;
    const lam = Math.max(0, n[0] * L[0] + n[1] * L[1] + n[2] * L[2]);
    const spec = Math.pow(Math.max(0, n[0] * H[0] + n[1] * H[1] + n[2] * H[2]), 28);
    faces.push({ v: [a, b, c], z: (a[2] + b[2] + c[2]) / 3, shade: (0.38 + 0.78 * lam) * alt + spec * 1.6 });
  };
  for (let i = 0; i < SIDES; i++) {
    const a = ring[i], b = ring[(i + 1) % SIDES], alt = i % 2 ? 1 : 0.88;
    face(top, b, a, alt);
    face(bottom, a, b, alt * 0.92);
  }
  faces.sort((p, q) => p.z - q.z);
  if (glow > 0) {
    const g = ctx.createRadialGradient(x, y, 0, x, y, size * 0.95);
    g.addColorStop(0, `rgba(${colour[0]}, ${colour[1]}, ${colour[2]}, ${(0.55 * glow).toFixed(3)})`);
    g.addColorStop(1, `rgba(${colour[0]}, ${colour[1]}, ${colour[2]}, 0)`);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, size * 0.95, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.lineJoin = 'round';
  ctx.lineWidth = Math.max(0.5, size / 40);
  for (const f of faces) {
    const k = f.shade;
    const r = Math.min(255, colour[0] * k + (k > 1 ? (k - 1) * 200 : 0));
    const g = Math.min(255, colour[1] * k + (k > 1 ? (k - 1) * 200 : 0));
    const b = Math.min(255, colour[2] * k + (k > 1 ? (k - 1) * 200 : 0));
    ctx.fillStyle = `rgb(${r | 0}, ${g | 0}, ${b | 0})`;
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.45)';
    ctx.beginPath();
    ctx.moveTo(x + f.v[0][0] * s, cy - f.v[0][1] * s);
    ctx.lineTo(x + f.v[1][0] * s, cy - f.v[1][1] * s);
    ctx.lineTo(x + f.v[2][0] * s, cy - f.v[2][1] * s);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  }
}

/** A canvas sized for crisp drawing at the screen's pixel ratio; returns its 2D context scaled to CSS pixels. */
function fit(c: HTMLCanvasElement, w: number, h: number): CanvasRenderingContext2D {
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  if (c.width !== Math.round(w * dpr) || c.height !== Math.round(h * dpr)) {
    c.width = Math.round(w * dpr);
    c.height = Math.round(h * dpr);
    c.style.width = `${w}px`;
    c.style.height = `${h}px`;
  }
  const ctx = c.getContext('2d')!;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return ctx;
}

/** Slowly turning gems anywhere on the page (the tech window's purse, the town card): canvases with class `gem-spin`. */
const spinners = new Set<HTMLCanvasElement>();
export function spinGem(c: HTMLCanvasElement): void { spinners.add(c); }

interface Spark { a: number; v: number; r: number; life: number; hue: RGB; twinkle: number }

/**
 * The chip beside the cash: the turning gem and the count, and the burst when diamonds come in.
 */
export class GemChip {
  private icon = document.createElement('canvas');
  private num = document.createElement('span');
  private fx = document.createElement('canvas');
  private yaw = 0;
  private spin = 0.9;
  private pop = 0;
  private shown = 0;
  private target = 0;
  private burst: { t: number; n: number; hue: RGB; sparks: Spark[] } | null = null;
  private last = 0;
  /** Played once per burst. */
  onChime: ((n: number) => void) | null = null;

  constructor(private el: HTMLElement) {
    el.textContent = '';
    this.icon.className = 'gem-ico';
    this.num.className = 'gem-n';
    this.num.textContent = '0';
    el.append(this.icon, this.num);
    this.fx.className = 'gem-fx';
    document.body.append(this.fx);
    const loop = (now: number) => {
      requestAnimationFrame(loop);
      this.frame(now);
    };
    requestAnimationFrame(loop);
  }

  /** The balance, whole diamonds: set quietly (a load, a spend). */
  set(value: number): void {
    this.target = Math.floor(value);
    if (!this.burst) this.shown = this.target;
    this.num.textContent = String(this.shown);
  }

  /** `n` whole diamonds have come in: the burst, in `colour` (the fleet's for a town, a tier's for a deed). */
  earn(n: number, value: number, colour?: string): void {
    this.target = Math.floor(value);
    const hue = hexRgb(colour) ?? GEM;
    const count = Math.min(26, 10 + n * 3);
    const sparks: Spark[] = [];
    for (let k = 0; k < count; k++) {
      sparks.push({ a: (k / count) * Math.PI * 2 + Math.random() * 0.4, v: 60 + Math.random() * 70, r: 1.6 + Math.random() * 2.4, life: 0.6 + Math.random() * 0.5, hue: Math.random() < 0.5 ? hue : GEM, twinkle: Math.random() * 6 });
    }
    this.burst = { t: 0, n, hue, sparks };
    this.spin = 16;
    this.pop = 1;
    this.el.classList.remove('bump');
    void this.el.offsetWidth;
    this.el.classList.add('bump');
    this.onChime?.(n);
  }

  private frame(now: number): void {
    const dt = this.last ? Math.min(0.05, (now - this.last) / 1000) : 0;
    this.last = now;
    // the chip's gem: a slow turn, spun up by a burst and easing back
    this.spin += (0.9 - this.spin) * Math.min(1, dt * 2.2);
    this.yaw += this.spin * dt;
    this.pop = Math.max(0, this.pop - dt * 1.6);
    const scale = 1 + 0.55 * Math.sin(Math.min(1, this.pop) * Math.PI) * this.pop;
    const W = 20, Hh = 24;
    const ctx = fit(this.icon, W, Hh);
    ctx.clearRect(0, 0, W, Hh);
    drawGem(ctx, W / 2, Hh / 2, 17 * scale, this.yaw, 0.32, this.pop * 0.9);
    for (const c of spinners) {
      if (!c.isConnected) { spinners.delete(c); continue; }
      const w = c.clientWidth || 18, h = c.clientHeight || 22;
      const g = fit(c, w, h);
      g.clearRect(0, 0, w, h);
      drawGem(g, w / 2, h / 2, Math.min(w, h) * 0.8, this.yaw * 0.8 + w, 0.32);
    }
    this.drawBurst(dt);
  }

  private drawBurst(dt: number): void {
    const b = this.burst;
    if (!b) { if (this.fx.style.display !== 'none') this.fx.style.display = 'none'; return; }
    b.t += dt;
    const T = 1.35;
    if (b.t >= T) {
      this.burst = null;
      this.shown = this.target;
      this.num.textContent = String(this.shown);
      return;
    }
    // the count ticks up as the gem lands
    const land = 0.42;
    if (b.t > land) {
      const k = Math.min(1, (b.t - land) / 0.35);
      const from = this.target - b.n;
      const v = Math.round(from + (this.target - from) * k);
      if (v !== this.shown) { this.shown = v; this.num.textContent = String(v); }
    }
    const r = this.icon.getBoundingClientRect();
    if (!r.width) return;
    const W = 220, Hh = 190, cx = W / 2, cy = Hh / 2;
    this.fx.style.display = 'block';
    this.fx.style.left = `${r.left + r.width / 2 - cx}px`;
    this.fx.style.top = `${r.top + r.height / 2 - cy}px`;
    const ctx = fit(this.fx, W, Hh);
    ctx.clearRect(0, 0, W, Hh);
    const t = b.t;
    // a bigger gem swoops down onto the chip from below and to the left, spinning, and shrinks into it
    if (t < land) {
      const k = t / land, e = 1 - (1 - k) * (1 - k);
      const gx = cx - 70 * (1 - e), gy = cy + 60 * (1 - e) - Math.sin(e * Math.PI) * 26;
      drawGem(ctx, gx, gy, 44 - 26 * e, this.yaw * 3, 0.3, 1 - k * 0.4);
    }
    if (t >= land) {
      const k = (t - land) / (T - land);
      // the ring
      ctx.strokeStyle = `rgba(${b.hue[0]}, ${b.hue[1]}, ${b.hue[2]}, ${(0.75 * (1 - k)).toFixed(3)})`;
      ctx.lineWidth = 3 * (1 - k) + 0.5;
      ctx.beginPath();
      ctx.arc(cx, cy, 8 + 62 * Math.sqrt(k), 0, Math.PI * 2);
      ctx.stroke();
      // the sparks: four-pointed twinkles flying out and slowing
      for (const s of b.sparks) {
        const age = t - land;
        if (age > s.life) continue;
        const f = age / s.life, d = s.v * age * (1 - 0.45 * f);
        const x = cx + Math.cos(s.a) * d, y = cy + Math.sin(s.a) * d * 0.8 - 14 * f;
        const a = (1 - f) * (0.65 + 0.35 * Math.sin(age * 30 + s.twinkle));
        star(ctx, x, y, s.r * (1.4 - f * 0.6), s.hue, a);
      }
      // "+1", rising and fading
      const a = k < 0.7 ? 1 : 1 - (k - 0.7) / 0.3;
      ctx.font = '700 17px "Fredoka", "Segoe UI", sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.lineWidth = 4;
      ctx.strokeStyle = `rgba(255, 255, 255, ${(a * 0.95).toFixed(3)})`;
      const ty = cy + 26 - 38 * Math.min(1, k * 1.4);
      ctx.strokeText(`+${b.n} ◆`, cx, ty);
      ctx.fillStyle = `rgba(31, 127, 156, ${a.toFixed(3)})`;
      ctx.fillText(`+${b.n} ◆`, cx, ty);
    }
  }
}

/** A four-pointed twinkle. */
function star(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, c: RGB, a: number): void {
  if (a <= 0.01) return;
  ctx.fillStyle = `rgba(${Math.min(255, c[0] + 90)}, ${Math.min(255, c[1] + 90)}, ${Math.min(255, c[2] + 90)}, ${a.toFixed(3)})`;
  ctx.beginPath();
  ctx.moveTo(x, y - r * 2.2);
  ctx.quadraticCurveTo(x, y, x + r * 2.2, y);
  ctx.quadraticCurveTo(x, y, x, y + r * 2.2);
  ctx.quadraticCurveTo(x, y, x - r * 2.2, y);
  ctx.quadraticCurveTo(x, y, x, y - r * 2.2);
  ctx.fill();
}
