/**
 * The rival's line (docs/missions.html, Races): the fastest way from the start to the finish for this
 * car, over whatever ground is quickest — a road where the road is quicker, straight across a salt pan
 * or a meadow where that is, never where the car can't go.
 *
 * It is an A* over world tiles across every cell in memory between the two ends, costed in seconds: a
 * tile costs its length over the speed this car makes on it (the road, the landform, the car's own
 * surface table and the weather, exactly as car.ts reads them), slowed by the climb. Off the road it
 * may cut corners diagonally, so a field is crossed on the diagonal rather than as a staircase; on and
 * off bridge decks it moves only along them, as the traffic router does. The car's curb, wade and grade
 * limits are the same `canCross` the car itself answers to.
 */
import { N, DIRS, idx, inB, tileMean, waterDepth, type World } from '../../world/tiles';
import { canCross } from '../../world/graph';
import { deckMove } from '../../world/roads';
import { surfaceMul } from '../car';
import { fenceAcross } from '../../world/fences';
import type { LandDef } from '../vehicles';

interface RoutePt { x: number; z: number; t: number }
export interface Route {
  /** World tiles, with the seconds the planner expects to reach each point. */
  pts: RoutePt[];
  seconds: number;
  tiles: number;
  /** Share of the length on a road. */
  roadShare: number;
}

/** How much quicker than its flat top speed a car may go anywhere (a salt pan, a downhill), for the heuristic. */
const FASTEST = 1.1;
/** Weighted A*: how much more the distance still to go counts than the time spent. A line a few per cent off the best, found fast. */
const GREED = 1.6;
/** A tile a car can hardly move on is costed as if at this share of its top speed, so it is still a way through. */
const SLOWEST = 0.12;
/** Cornering: the planner adds this many seconds for each change of direction, so it prefers a clean line. */
const TURN_SECONDS = 0.06;
/** Seconds added to a tile off the road that touches a building. */
const CLEARANCE = 0.35;
/** The share of the planner's ideal a real car holds (it brakes for corners, it wanders): for the off-screen runner. */
export const HOLD = 0.82;
const MAX_EXPAND = 2_500_000;

/**
 * The fastest route, or null when there is none through the cells in memory. `worldAt` answers for a
 * cell, null when it isn't in memory (it is then impassable).
 */
export function fastRoute(worldAt: (cx: number, cz: number) => World | null, def: LandDef, ax: number, az: number, bx: number, bz: number): Route | null {
  // the cells the two ends are in and the ones between first; round by a cell either side only if that fails
  return plan(worldAt, def, ax, az, bx, bz, 0) ?? plan(worldAt, def, ax, az, bx, bz, 1);
}

function plan(worldAt: (cx: number, cz: number) => World | null, def: LandDef, ax: number, az: number, bx: number, bz: number, margin: number): Route | null {
  const c0x = Math.min(Math.floor(ax / N), Math.floor(bx / N)) - margin, c1x = Math.max(Math.floor(ax / N), Math.floor(bx / N)) + margin;
  const c0z = Math.min(Math.floor(az / N), Math.floor(bz / N)) - margin, c1z = Math.max(Math.floor(az / N), Math.floor(bz / N)) + margin;
  const W = (c1x - c0x + 1) * N, H = (c1z - c0z + 1) * N;
  const X0 = c0x * N, Z0 = c0z * N;
  const worlds: (World | null)[] = [];
  for (let cz = c0z; cz <= c1z; cz++) for (let cx = c0x; cx <= c1x; cx++) worlds.push(worldAt(cx, cz));
  const worldOf = (gx: number, gz: number): World | null => {
    const cx = Math.floor((gx + X0) / N) - c0x, cz = Math.floor((gz + Z0) / N) - c0z;
    return cx < 0 || cz < 0 || cx > c1x - c0x || cz > c1z - c0z ? null : worlds[cz * (c1x - c0x + 1) + cx];
  };
  const local = (g: number) => ((g % N) + N) % N;
  const S = W * H * 2;
  const g = new Float32Array(S).fill(Infinity);
  const prev = new Int32Array(S).fill(-1);
  // weighted A* without reopening: each state is expanded once
  const closed = new Uint8Array(S);
  const heap = new Heap();
  const start = (Math.floor(az) - Z0) * W + (Math.floor(ax) - X0);
  const gxT = Math.floor(bx) - X0, gzT = Math.floor(bz) - Z0;
  const goal = gzT * W + gxT;
  const w0 = worldOf(Math.floor(ax) - X0, Math.floor(az) - Z0);
  if (!w0 || !worldOf(gxT, gzT)) return null;
  const top = def.topSpeed;
  // a little greedy (weighted A*): a line within a few per cent of the best, found in a fraction of the time
  const h = (gx: number, gz: number) => (Math.hypot(gx - gxT, gz - gzT) / (top * FASTEST)) * GREED;
  /** Seconds to cross one tile of this world at i, for this car, heading from a to b (for the climb). */
  const tileSecs = (w: World, i: number, climb: number): number => {
    let v = top * surfaceMul(w, i, def);
    // wading: the car holds half its speed and drags besides, and the shallows are where it snags on the shore
    if (!def.swimSpeed && waterDepth(w, i) > 0 && !w.deckAxis[i]) v *= 0.3;
    // and in a town it keeps to the streets: the yards between houses are gardens, fences and walls
    else if (!w.road[i] && w.townId[i] >= 0) v *= 0.25;
    if (climb > 0) v *= Math.max(0.3, 1 - def.uphillPenalty * climb);
    else v *= 1 + Math.min(0.3, (def.downhillBonus / top) * -climb * 0.5);
    return 1 / Math.max(top * SLOWEST, v);
  };

  g[start * 2] = 0;
  heap.push(h(start % W, Math.floor(start / W)), start * 2);
  let found = -1, expanded = 0;
  while (heap.size) {
    const s = heap.pop();
    const a = s >> 1, deck = s & 1;
    if (a === goal) { found = s; break; }
    if (closed[s]) continue;
    closed[s] = 1;
    if (++expanded > MAX_EXPAND) break;
    const agx = a % W, agz = (a - agx) / W;
    const wa = worldOf(agx, agz);
    if (!wa) continue;
    const ai = idx(local(agx + X0), local(agz + Z0));
    const ha = tileMean(wa, ai);
    const pa = prev[s] >= 0 ? prev[s] >> 1 : -1;
    const lastDx = pa >= 0 ? agx - (pa % W) : 0, lastDz = pa >= 0 ? agz - Math.floor(pa / W) : 0;
    for (let d = 0; d < 8; d++) {
      const diag = d >= 4;
      const dx = diag ? (d === 4 || d === 7 ? 1 : -1) : DIRS[d][0];
      const dz = diag ? (d === 4 || d === 5 ? 1 : -1) : DIRS[d][1];
      const bgx = agx + dx, bgz = agz + dz;
      if (bgx < 0 || bgz < 0 || bgx >= W || bgz >= H) continue;
      const wb = worldOf(bgx, bgz);
      if (!wb) continue;
      const bi = idx(local(bgx + X0), local(bgz + Z0));
      const b = bgz * W + bgx;
      let next = -1;
      if (!diag) {
        const same = wa === wb;
        // on and off decks as the car's own physics does it (world/roads.ts deckMove); a deck never crosses a border
        const dm = same ? deckMove(wa, ai, bi, d, deck === 1) : deck ? -1 : -2;
        if (dm >= 0) next = b * 2 + dm;
        else if (dm === -2 && canCross(wa, ai, d, def) && (same ? !fenceAcross(wa, ai, d) : true)) {
          // (a fence holds a car that isn't going flat out: the line goes round by the gate)
          next = b * 2;
        }
      } else {
        // a diagonal off the road: both ways round the corner must be open, and neither end a deck
        if (deck || wa.deckAxis[ai] || wb.deckAxis[bi] || wa.road[ai] || wb.road[bi]) continue;
        const dX = dx > 0 ? 0 : 2, dZ = dz > 0 ? 1 : 3;
        const sx = worldOf(agx + dx, agz), sz = worldOf(agx, agz + dz);
        if (!sx || !sz) continue;
        const ix = idx(local(agx + dx + X0), local(agz + Z0)), iz = idx(local(agx + X0), local(agz + dz + Z0));
        const okA = canCross(wa, ai, dX, def) && canCross(sx, ix, dZ, def) && (wa !== sx || !fenceAcross(wa, ai, dX)) && (sx !== wb || !fenceAcross(sx, ix, dZ));
        const okB = canCross(wa, ai, dZ, def) && canCross(sz, iz, dX, def) && (wa !== sz || !fenceAcross(wa, ai, dZ)) && (sz !== wb || !fenceAcross(sz, iz, dX));
        if (!okA || !okB) continue;
        next = b * 2;
      }
      if (next < 0 || closed[next]) continue;
      const climb = (tileMean(wb, bi) - ha) / (diag ? Math.SQRT2 : 1);
      let step = tileSecs(wb, bi, climb) * (diag ? Math.SQRT2 : 1);
      if (pa >= 0 && (dx !== lastDx || dz !== lastDz)) step += TURN_SECONDS;
      // off the road, give buildings a berth: a line that shaves a wall is one a car ends up wedged against
      if (!wb.road[bi]) {
        const bx = local(bgx + X0), bz = local(bgz + Z0);
        for (const [ox, oz] of DIRS) { const x2 = bx + ox, z2 = bz + oz; if (inB(x2, z2) && wb.blocked[idx(x2, z2)]) { step += CLEARANCE; break; } }
      }
      const ng = g[s] + step;
      if (ng < g[next]) {
        g[next] = ng;
        prev[next] = s;
        heap.push(ng + h(bgx, bgz), next);
      }
    }
  }
  if (found < 0) return null;
  const cells: number[] = [];
  for (let s = found; s >= 0; s = prev[s]) cells.push(s);
  cells.reverse();
  const pts: RoutePt[] = [];
  let tiles = 0, onRoad = 0;
  for (let k = 0; k < cells.length; k++) {
    const a = cells[k] >> 1;
    const gx = (a % W) + X0, gz = Math.floor(a / W) + Z0;
    const p = { x: gx + 0.5, z: gz + 0.5, t: g[cells[k]] / HOLD };
    if (pts.length) {
      const q = pts[pts.length - 1];
      tiles += Math.hypot(p.x - q.x, p.z - q.z);
      const w = worldOf(gx - X0, gz - Z0);
      if (w && w.road[idx(local(gx), local(gz))]) onRoad++;
    }
    pts.push(p);
  }
  pts[0] = { x: ax, z: az, t: 0 };
  pts[pts.length - 1] = { x: bx, z: bz, t: pts[pts.length - 1].t };
  return { pts: simplify(pts), seconds: g[found] / HOLD, tiles, roadShare: cells.length > 1 ? onRoad / (cells.length - 1) : 1 };
}

/**
 * Which of these targets a car at (ax, az) can drive to at all, through the cells in memory: one flood
 * over the window that holds them all, decks and borders as the planner takes them, no costs. Cheap
 * enough to ask when a race is being offered; the full planner runs only at the start line.
 */
export function reachAmong(worldAt: (cx: number, cz: number) => World | null, def: LandDef, ax: number, az: number, targets: { x: number; z: number }[]): boolean[] {
  const xs = [ax, ...targets.map((t) => t.x)], zs = [az, ...targets.map((t) => t.z)];
  const c0x = Math.floor(Math.min(...xs) / N), c1x = Math.floor(Math.max(...xs) / N);
  const c0z = Math.floor(Math.min(...zs) / N), c1z = Math.floor(Math.max(...zs) / N);
  const W = (c1x - c0x + 1) * N, H = (c1z - c0z + 1) * N, X0 = c0x * N, Z0 = c0z * N;
  const cw = c1x - c0x + 1;
  const worlds: (World | null)[] = [];
  for (let cz = c0z; cz <= c1z; cz++) for (let cx = c0x; cx <= c1x; cx++) worlds.push(worldAt(cx, cz));
  const worldOf = (gx: number, gz: number) => (gx < 0 || gz < 0 || gx >= W || gz >= H ? null : worlds[Math.floor(gz / N) * cw + Math.floor(gx / N)]);
  const local = (g: number) => ((g % N) + N) % N;
  const seen = new Uint8Array(W * H * 2);
  const queue = new Int32Array(W * H * 2);
  const out = targets.map(() => false);
  const want = new Map<number, number[]>();
  targets.forEach((t, k) => {
    const g = (Math.floor(t.z) - Z0) * W + (Math.floor(t.x) - X0);
    want.set(g, [...(want.get(g) ?? []), k]);
  });
  const start = (Math.floor(az) - Z0) * W + (Math.floor(ax) - X0);
  if (!worldOf(start % W, Math.floor(start / W))) return out;
  let head = 0, tail = 0, left = targets.length;
  seen[start * 2] = 1;
  queue[tail++] = start * 2;
  while (head < tail && left > 0) {
    const s = queue[head++];
    const a = s >> 1, deck = s & 1;
    const hit = want.get(a);
    if (hit) { for (const k of hit) if (!out[k]) { out[k] = true; left--; } want.delete(a); }
    const agx = a % W, agz = (a - agx) / W;
    const wa = worldOf(agx, agz)!;
    const ai = idx(local(agx + X0), local(agz + Z0));
    for (let d = 0; d < 4; d++) {
      const bgx = agx + DIRS[d][0], bgz = agz + DIRS[d][1];
      const wb = worldOf(bgx, bgz);
      if (!wb) continue;
      const bi = idx(local(bgx + X0), local(bgz + Z0));
      const b = bgz * W + bgx;
      const same = wa === wb;
      let next = -1;
      const dm = same ? deckMove(wa, ai, bi, d, deck === 1) : deck ? -1 : -2;
      if (dm >= 0) next = b * 2 + dm;
      else if (dm === -2 && canCross(wa, ai, d, def)) next = b * 2;
      if (next < 0 || seen[next]) continue;
      seen[next] = 1;
      queue[tail++] = next;
    }
  }
  return out;
}

/** Drop points that lie on the straight line between their neighbours, so the driver's look-ahead runs smooth. */
function simplify(pts: RoutePt[]): RoutePt[] {
  if (pts.length < 3) return pts;
  const out = [pts[0]];
  for (let k = 1; k < pts.length - 1; k++) {
    const a = out[out.length - 1], b = pts[k], c = pts[k + 1];
    const cross = (b.x - a.x) * (c.z - a.z) - (b.z - a.z) * (c.x - a.x);
    if (Math.abs(cross) > 1e-6 || Math.hypot(b.x - a.x, b.z - a.z) > 6) out.push(b);
  }
  out.push(pts[pts.length - 1]);
  return out;
}

/** The point `dist` tiles along the route from the nearest point to (x, z) at or after index `i`. */
export function along(pts: RoutePt[], i: number, x: number, z: number, dist: number): { x: number; z: number } {
  let px = x, pz = z, rem = dist;
  for (let k = i; k < pts.length; k++) {
    const q = pts[k], seg = Math.hypot(q.x - px, q.z - pz);
    if (seg >= rem) { const t = rem / (seg || 1); return { x: px + (q.x - px) * t, z: pz + (q.z - pz) * t }; }
    rem -= seg;
    px = q.x; pz = q.z;
  }
  const last = pts[pts.length - 1];
  return { x: last.x, z: last.z };
}

/** Tiles of route left from index i, starting at (x, z). */
export function remaining(pts: RoutePt[], i: number, x: number, z: number): number {
  if (i >= pts.length) return 0;
  let d = Math.hypot(pts[i].x - x, pts[i].z - z);
  for (let k = i; k < pts.length - 1; k++) d += Math.hypot(pts[k + 1].x - pts[k].x, pts[k + 1].z - pts[k].z);
  return d;
}

class Heap {
  private k: number[] = [];
  private v: number[] = [];
  get size(): number { return this.k.length; }
  push(key: number, val: number): void {
    const k = this.k, v = this.v;
    let i = k.length;
    k.push(key); v.push(val);
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (k[p] <= key) break;
      k[i] = k[p]; v[i] = v[p];
      i = p;
    }
    k[i] = key; v[i] = val;
  }
  pop(): number {
    const k = this.k, v = this.v;
    const top = v[0];
    const lk = k.pop()!, lv = v.pop()!;
    const n = k.length;
    if (n > 0) {
      let i = 0;
      for (;;) {
        let c = 2 * i + 1;
        if (c >= n) break;
        if (c + 1 < n && k[c + 1] < k[c]) c++;
        if (k[c] >= lk) break;
        k[i] = k[c]; v[i] = v[c];
        i = c;
      }
      k[i] = lk; v[i] = lv;
    }
    return top;
  }
}

