import { Flag, Surface, type World } from './tiles';
import { decodePasses, stageOf, tileOfChunk, type PathStage } from '../../shared/community';

/**
 * Worn paths (docs/community.html): open ground that many fleets have driven over, as the server counts it.
 * A cell's paths travel with its delta as chunk → [passes, fleets that wore the chunk]; laying them puts
 * the two lasting stages into the world itself. A worn tile (stage 2) loses its trees and bushes for good,
 * as a bulldozed one does; a beaten track (stage 3) is a dirt track (Flag.Track): it draws as one, drives
 * as one and takes tyre tracks. The faint stage, and the ruts of a worn one, are only drawn over the ground
 * (net/community.ts). A road, a building, water or a town's ground always wins over a path.
 */
export type PathBlock = Record<string, [string, number]>;

/** Ground a path can't be on, whatever the counts say. */
export function pathBarred(w: World, i: number): boolean {
  if (w.road[i] || w.blocked[i] || w.water[i] >= 0 || w.townId[i] >= 0 || w.deckAxis[i]) return true;
  if (w.flags[i] & (Flag.Poi | Flag.Ramp)) return true;
  const s = w.surface[i] as Surface;
  return s === Surface.Ice || s === Surface.Rock || s === Surface.Lava || s === Surface.Basalt || s === Surface.Cave || s === Surface.Salt;
}

/** Each tile's stage in some chunks of a block, by tile index; tiles at stage 0 are left out. */
export function pathStages(block: PathBlock, only?: Iterable<string>): Map<number, PathStage> {
  const out = new Map<number, PathStage>();
  for (const k of only ?? Object.keys(block)) {
    const e = block[k];
    if (!e) continue;
    const p = decodePasses(e[0]);
    for (let t = 0; t < p.length; t++) {
      const s = stageOf(p[t], e[1]);
      if (s) out.set(tileOfChunk(Number(k), t), s);
    }
  }
  return out;
}

/** Lay worn and beaten tiles into the world. Returns the tiles that changed (for a redraw). */
export function applyPaths(w: World, block: PathBlock | undefined, only?: Iterable<string>): number[] {
  if (!block) return [];
  const out: number[] = [];
  for (const [i, s] of pathStages(block, only)) {
    if (s < 2 || pathBarred(w, i)) continue;
    let changed = false;
    if (!w.cleared[i]) { w.cleared[i] = 1; changed = true; }
    if (s === 3 && !(w.flags[i] & Flag.Track)) { w.flags[i] |= Flag.Track; changed = true; }
    if (changed) out.push(i);
  }
  return out;
}
