/**
 * Light or dark UI (Settings → Appearance). Dark turns every panel, card and chip dark — the 3D world is
 * left as it is — by one class on the body (index.html, `body.dark-ui`). Remembered per device.
 */
export type Theme = 'light' | 'dark';

const KEY = 'tinyfleet-theme';

export function theme(): Theme {
  try { return localStorage.getItem(KEY) === 'dark' ? 'dark' : 'light'; } catch { return 'light'; }
}

export function setTheme(t: Theme): void {
  try { localStorage.setItem(KEY, t); } catch { /* not remembered */ }
  applyTheme();
}

/** Put the remembered theme on the page (once at startup, and on every change). */
export function applyTheme(): void {
  document.body.classList.toggle('dark-ui', theme() === 'dark');
}
