/**
 * The giant trees of the rare groves (world/groves.ts), in the style of the ordinary trees: merged,
 * vertex-coloured, `aLeaf`-tagged geometries drawn instanced with propMaterial, so they cost no shader
 * of their own. An ordinary tree is about one tile tall; the Big Timber's redwoods about three.
 *
 *   giant redwood  ~6 tall (7.8 for a grove's named tree), a red pillar bare for its lower half
 *   great oak      ~2.6 tall and ~3.6 across, a low dome on a massive trunk; bare in winter
 *   giant baobab   ~3.4 tall, a bottle trunk 1.3 across under a crown of stubby limbs
 *   banyan         ~2.6 tall and ~5 across, a flat evergreen canopy on a cloister of aerial roots
 */
import * as THREE from 'three';
import { paint, merge, boughs } from './regionProps';
import type { GiantKind } from '../world/groves';

const UP = new THREE.Vector3(0, 1, 0);
/** A tapered cylinder from a to b. */
function limb(a: [number, number, number], b: [number, number, number], r0: number, r1: number, radial = 5, open = true): THREE.BufferGeometry {
  const va = new THREE.Vector3(...a), vb = new THREE.Vector3(...b);
  const d = vb.clone().sub(va);
  const len = d.length();
  const g = new THREE.CylinderGeometry(r1, r0, len, radial, 1, open);
  g.translate(0, len / 2, 0);
  g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(UP, d.normalize()));
  g.translate(va.x, va.y, va.z);
  return g;
}
function lathe(profile: [number, number][], radial: number): THREE.BufferGeometry {
  return new THREE.LatheGeometry(profile.map(([r, y]) => new THREE.Vector2(r, y)), radial);
}

/** A coast redwood of the old growth: a fluted red column, bare for half its height, under drooping dark tiers. */
function giantRedwoodGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [
    paint(lathe([[0.46, -0.2], [0.42, 0.05], [0.3, 0.45], [0.27, 1.4], [0.22, 2.8], [0.16, 4.2], [0.08, 5.6], [0, 6.05]], 8), 0x9a5236),
    // the buttressed, burned-hollow foot: dark ribs round the base
  ];
  for (let k = 0; k < 5; k++) {
    const a = (k / 5) * Math.PI * 2 + 0.3;
    parts.push(paint(limb([Math.cos(a) * 0.42, -0.15, Math.sin(a) * 0.42], [Math.cos(a) * 0.2, 0.75, Math.sin(a) * 0.2], 0.12, 0.04, 4), 0x7a4028));
  }
  // short branches where the crown starts, so its foot is not a clean cut
  for (let k = 0; k < 4; k++) {
    const a = (k / 4) * Math.PI * 2 + 0.8, y = 2.7 + k * 0.18;
    parts.push(paint(limb([0, y, 0], [Math.cos(a) * 0.6, y - 0.12, Math.sin(a) * 0.6], 0.05, 0.02, 3), 0x6e3a24));
  }
  const tiers: [number, number, number][] = [
    [2.75, 0.78, 0.62], [3.15, 0.72, 0.6], [3.55, 0.64, 0.58], [3.95, 0.55, 0.55], [4.35, 0.46, 0.52], [4.75, 0.36, 0.5], [5.15, 0.27, 0.48], [5.5, 0.17, 0.55],
  ];
  tiers.forEach(([y, r, h], k) => {
    const off = k % 2 ? 0.05 : -0.05;
    parts.push(paint(new THREE.ConeGeometry(r, h, 7).rotateY(k * 0.6).translate(off, y + h / 2, -off), k % 2 ? 0x2c5a36 : 0x234a2e, 1));
  });
  return merge(parts);
}

/** A great oak centuries old: a short massive bole, limbs flung wide, a broad low dome that turns and drops. */
function greatOakGeometry(): THREE.BufferGeometry {
  const bark = 0x5c4632;
  const parts: THREE.BufferGeometry[] = [
    paint(lathe([[0.42, -0.15], [0.36, 0.08], [0.27, 0.3], [0.24, 0.75], [0.2, 0.98], [0, 1.02]], 8), bark),
  ];
  // the great limbs, always there, carrying the dome
  for (let k = 0; k < 5; k++) {
    const a = (k / 5) * Math.PI * 2 + 0.2;
    const r = 0.95 + (k % 2) * 0.2;
    parts.push(paint(limb([Math.cos(a) * 0.08, 0.85, Math.sin(a) * 0.08], [Math.cos(a) * r, 1.35 + (k % 3) * 0.12, Math.sin(a) * r], 0.13, 0.06, 5), bark));
  }
  parts.push(...boughs([0, 1.0, 0], 2.3, 1.45, 0.7, bark, 7));
  // the dome: a broad crown with lobes all round its rim
  parts.push(paint(new THREE.IcosahedronGeometry(0.95, 0).scale(1.35, 0.62, 1.3).translate(0, 1.85, 0), 0x497f3a, 2));
  for (let k = 0; k < 6; k++) {
    const a = (k / 6) * Math.PI * 2 + 0.5;
    const r = 1.05 + (k % 2) * 0.12;
    const s = 0.5 + (k % 3) * 0.06;
    parts.push(paint(new THREE.IcosahedronGeometry(s, 0).scale(1.3, 0.78, 1.25).translate(Math.cos(a) * r, 1.62 + (k % 2) * 0.16, Math.sin(a) * r), k % 2 ? 0x548c42 : 0x447636, 2));
  }
  parts.push(paint(new THREE.IcosahedronGeometry(0.55, 0).scale(1.3, 0.7, 1.2).translate(0.15, 2.3, -0.1), 0x5a9446, 2));
  return merge(parts);
}

/** A giant baobab: a vast grey bottle of a trunk and a crown of stubby forked limbs with thin leaf. */
function giantBaobabGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [
    paint(lathe([[0.62, -0.2], [0.68, 0.3], [0.66, 0.9], [0.58, 1.5], [0.46, 2.0], [0.3, 2.35], [0.18, 2.55], [0, 2.6]], 9), 0xa08c7a),
  ];
  for (let k = 0; k < 7; k++) {
    const a = (k / 7) * Math.PI * 2 + 0.2;
    const r = 0.85 + (k % 3) * 0.15, y = 2.85 + (k % 2) * 0.22;
    const ex = Math.cos(a) * r, ez = Math.sin(a) * r;
    parts.push(paint(limb([Math.cos(a) * 0.15, 2.35, Math.sin(a) * 0.15], [ex, y, ez], 0.12, 0.06, 4), 0x8e7c6a));
    // each limb forks once
    const b = a + (k % 2 ? 0.5 : -0.5);
    parts.push(paint(limb([ex, y, ez], [ex + Math.cos(b) * 0.3, y + 0.28, ez + Math.sin(b) * 0.3], 0.05, 0.02, 3), 0x8e7c6a));
    parts.push(paint(new THREE.IcosahedronGeometry(0.26, 0).scale(1.3, 0.55, 1.3).translate(ex + Math.cos(b) * 0.25, y + 0.32, ez + Math.sin(b) * 0.25), k % 2 ? 0x6f9a44 : 0x648c3c, 2));
  }
  return merge(parts);
}

/** A banyan: fused trunks under a flat spreading canopy held up by a ring of aerial roots grown into pillars. */
function banyanGeometry(): THREE.BufferGeometry {
  const bark = 0x8a7c66, root = 0x9a8c74;
  const parts: THREE.BufferGeometry[] = [];
  // the fused trunk: four stems from a wide foot, leaning in
  for (let k = 0; k < 4; k++) {
    const a = (k / 4) * Math.PI * 2 + 0.4;
    parts.push(paint(limb([Math.cos(a) * 0.3, -0.15, Math.sin(a) * 0.3], [Math.cos(a) * 0.1, 1.55, Math.sin(a) * 0.1], 0.17, 0.1, 5), bark));
  }
  // the great boughs, spreading level
  for (let k = 0; k < 6; k++) {
    const a = (k / 6) * Math.PI * 2 + 0.1;
    parts.push(paint(limb([0, 1.45, 0], [Math.cos(a) * 1.75, 1.75 + (k % 2) * 0.1, Math.sin(a) * 1.75], 0.11, 0.05, 4), bark));
  }
  // aerial roots come down from the boughs as pillars, in two rings
  for (let k = 0; k < 11; k++) {
    const a = (k / 11) * Math.PI * 2 + (k % 2) * 0.2;
    const r = k % 2 ? 1.0 : 1.6;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    parts.push(paint(limb([x, -0.3, z], [x * 1.04, 1.78, z * 1.04], 0.07 + (k % 3) * 0.015, 0.035, 4), root));
  }
  // the canopy: flat, wide and evergreen
  parts.push(paint(new THREE.DodecahedronGeometry(1.15, 0).scale(1.45, 0.4, 1.45).translate(0, 2.2, 0), 0x2f6a34, 1));
  for (let k = 0; k < 7; k++) {
    const a = (k / 7) * Math.PI * 2 + 0.25;
    const r = 1.55 + (k % 2) * 0.2;
    parts.push(paint(new THREE.DodecahedronGeometry(0.68, 0).scale(1.3, 0.5, 1.3).translate(Math.cos(a) * r, 1.98 + (k % 3) * 0.1, Math.sin(a) * r), k % 2 ? 0x3a7a3c : 0x2a6230, 1));
  }
  return merge(parts);
}

export type GiantTreeGeometries = Record<GiantKind, THREE.BufferGeometry>;
export function createGiantTreeGeometries(): GiantTreeGeometries {
  return { giantRedwood: giantRedwoodGeometry(), greatOak: greatOakGeometry(), giantBaobab: giantBaobabGeometry(), banyan: banyanGeometry() };
}
