import * as THREE from 'three';
import { NIGHT } from './nightLights';
import { fadingCone, softPoolTexture } from './softLight';

/**
 * Floodlights for a venue hosting an event after dark (game/circuits.ts, game/stadiums.ts): a soft pool of
 * light over the field or the track, and a faint beam down from each mast. Additive meshes, not lights,
 * so switching them on and off never recompiles a shader (the lag spikes, docs: lag-spikes-fix). They fade
 * in with nightfall and with the event, and out again after it.
 */

/** How bright the pool and the beams are at full night. */
// BAND was 0.3: additive over a circuit's pale track it washed the surface out to flat white at night (19 Oct 2026)
const POOL = 0.26, BEAM = 0.07, BAND = 0.14;
/** Seconds to come fully on, or go off. */
const FADE = 2.5;
/** Night under this, the lights stay off: dusk enough to need them. */
const DUSK = 0.12;

const additive = (opacity: number, map?: THREE.Texture, fade = false) => new THREE.MeshBasicMaterial({
  color: 0xfff1d2, map: map ?? null, vertexColors: fade, transparent: true, opacity, depthWrite: false, blending: THREE.AdditiveBlending,
  polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2, side: THREE.DoubleSide, fog: false,
});

interface FloodPlan {
  /** Mast heads, in the venue's own frame (the group's), and where each is aimed (default: part way to the pool's middle). */
  masts: { x: number; y: number; z: number; at?: { x: number; y: number; z: number } }[];
  /** The lit area: its middle, its size along x and z, and the ground height there; `dim` scales it (1 = full). */
  pool: { x: number; z: number; w: number; d: number; y: number; dim?: number };
  /**
   * A band of light along a track, brightest where the cars run: a closed loop of cross-sections, each a row
   * of points across the track (x, y over the venue frame, z) with how lit each is (0–1).
   */
  ribbon?: { x: number; y: number; z: number; a: number }[][];
}

/** The track's band of light: quads between neighbouring cross-sections, round the loop, lit by vertex alpha. */
function ribbonGeometry(rows: { x: number; y: number; z: number; a: number }[][]): THREE.BufferGeometry {
  const m = rows[0].length, n = rows.length;
  const pos = new Float32Array(n * m * 3), col = new Float32Array(n * m * 4);
  rows.forEach((row, i) => row.forEach((q, j) => {
    const k = i * m + j;
    pos.set([q.x, q.y, q.z], k * 3);
    col.set([1, 1, 1, q.a], k * 4);
  }));
  const index: number[] = [];
  for (let i = 0; i < n; i++) {
    const i2 = (i + 1) % n;
    for (let j = 0; j < m - 1; j++) {
      const a = i * m + j, b = i * m + j + 1, c = i2 * m + j, d = i2 * m + j + 1;
      index.push(a, c, b, b, c, d);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.BufferAttribute(col, 4));
  g.setIndex(index);
  return g;
}

export class Floodlights {
  readonly group = new THREE.Group();
  private poolMat: THREE.MeshBasicMaterial;
  private beamMat: THREE.MeshBasicMaterial;
  private bandMat: THREE.MeshBasicMaterial | null = null;
  private poolDim: number;
  private level = 0;

  constructor(plan: FloodPlan) {
    this.group.name = 'floodlights';
    this.group.visible = false;
    this.poolMat = additive(0, softPoolTexture());
    this.beamMat = additive(0, undefined, true);
    const cone = fadingCone(16, 0.3);
    const { pool } = plan;
    this.poolDim = pool.dim ?? 1;
    if (plan.ribbon && plan.ribbon.length > 2) {
      this.bandMat = additive(0, undefined, true);
      const band = new THREE.Mesh(ribbonGeometry(plan.ribbon), this.bandMat);
      band.renderOrder = 3;
      this.group.add(band);
    }
    // the pool a little larger than the field, so its soft edge falls on the stands' feet
    const pg = new THREE.PlaneGeometry(pool.w * 1.25, pool.d * 1.25).rotateX(-Math.PI / 2);
    const pm = new THREE.Mesh(pg, this.poolMat);
    pm.position.set(pool.x, pool.y + 0.04, pool.z);
    pm.renderOrder = 3;
    this.group.add(pm);
    // a cone from each mast head down onto the field, aimed part way to its middle
    const up = new THREE.Vector3(0, 1, 0);
    for (const m of plan.masts) {
      const tx = m.at?.x ?? m.x + (pool.x - m.x) * 0.55, tz = m.at?.z ?? m.z + (pool.z - m.z) * 0.55;
      const head = new THREE.Vector3(m.x, m.y, m.z), foot = new THREE.Vector3(tx, m.at?.y ?? pool.y, tz);
      const len = head.distanceTo(foot);
      if (len < 0.2) continue;
      const mesh = new THREE.Mesh(cone, this.beamMat);
      const r = Math.min(2.4, Math.max(0.6, len * 0.35));
      mesh.scale.set(r, len, r);
      mesh.position.copy(head);
      mesh.quaternion.setFromUnitVectors(up.clone().negate(), foot.clone().sub(head).normalize());
      mesh.renderOrder = 4;
      this.group.add(mesh);
    }
  }

  /** Each frame: `on` while the venue is hosting something. Fades toward on × how dark it is. */
  update(dt: number, on: boolean): void {
    const night = NIGHT.uNight.value;
    const want = on && night > DUSK ? Math.min(1, (night - DUSK) / (1 - DUSK) * 1.6) : 0;
    const step = dt / FADE;
    this.level = want > this.level ? Math.min(want, this.level + step) : Math.max(want, this.level - step);
    const shown = this.level > 0.005;
    if (this.group.visible !== shown) this.group.visible = shown;
    if (!shown) return;
    this.poolMat.opacity = POOL * this.level * this.poolDim;
    if (this.bandMat) this.bandMat.opacity = BAND * this.level;
    this.beamMat.opacity = BEAM * this.level;
  }

  dispose(): void {
    this.group.removeFromParent();
    for (const g of new Set(this.group.children.map((o) => (o as THREE.Mesh).geometry))) g.dispose();
    this.poolMat.dispose();
    this.beamMat.dispose();
    this.bandMat?.dispose();
  }
}
