import type { BuildingKind } from '../../../world/tiles';
import { hex, scale, type RGB } from '../../../world/biomes';
import { DARK, GLASS_LIGHT, METAL, STONE, TAU, WARM_GLOW, WHITE, WOOD, car, pick, tree, win, type Draw, type Kit, type P3 } from '../kit';
import { palm } from '../venues';
import { flag } from '../civic';

/**
 * Golf in many layouts, the way the great parks come in their themes: the resort course by the beach
 * is the kind's own model (regions/shallows.ts), and here are the links among the dunes, the parkland
 * course round its lake, desert target golf, the mountain course on its terraces and the clubhouse
 * with its driving range. Every hole has its tee, fairway, green and flag, its bunkers, and a cart path
 * to get round by; by day a pair of golfers plays the holes in turn and a cart runs the path.
 *
 * Mini golf gets four themed courses besides its own mixed one: the Dutch windmill, the pirate cove,
 * the dinosaur valley and the castle.
 *
 * Flat things lie in layers a few thousandths apart so no two fight: the ground, patches, water's
 * edge, fairways, cart paths, water, greens, bunkers, cups.
 */

type Rng = () => number;
type Pt = [number, number];

const Y_BASE = 0.003, Y_PATCH = 0.005, Y_SHORE = 0.007, Y_FAIR = 0.009, Y_PATH = 0.011, Y_WATER = 0.012;
const Y_GREEN = 0.014, Y_RIM = 0.016, Y_SAND = 0.018, Y_CUP = 0.02;

const SAND = hex(0xeedcaa), WATER = hex(0x4f9fc8), SKIN = [0xf1c8a0, 0xd9a273, 0x9a6a44, 0x6e4a30];
const SHIRTS = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0xf4f2ec, 0x3f9b4a, 0xf49ab5, 0x8e5cc7, 0x2bb3a3];
const TROUSERS = [0x3a3f45, 0xe8e0cc, 0x2f4d7a, 0x8a8a82];

/** A flat polygon at height y, as a fan from its middle (star-shaped round that middle). */
function fan(k: Kit, pts: Pt[], y: number, col: RGB): void {
  let cx = 0, cz = 0;
  for (const [x, z] of pts) { cx += x; cz += z; }
  cx /= pts.length; cz /= pts.length;
  const I: P3 = [cx, y - 1, cz];
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i], b = pts[(i + 1) % pts.length];
    k.tri([cx, y, cz], [a[0], y, a[1]], [b[0], y, b[1]], col, I);
  }
}

/** An irregular oval round (cx, cz), turned by rot: a green, a bunker, a lake. */
function blob(cx: number, cz: number, rx: number, rz: number, r: Rng, n = 12, wob = 0.16, rot = 0): Pt[] {
  const p1 = r() * TAU, p2 = r() * TAU, c = Math.cos(rot), s = Math.sin(rot);
  return Array.from({ length: n }, (_, i) => {
    const a = (i / n) * TAU, f = 1 + wob * (0.6 * Math.sin(2 * a + p1) + 0.4 * Math.sin(3 * a + p2));
    const x = Math.cos(a) * rx * f, z = Math.sin(a) * rz * f;
    return [cx + x * c - z * s, cz + x * s + z * c] as Pt;
  });
}

/** A low irregular mound, its top at h over (cx, cz): a dune. */
function mound(k: Kit, cx: number, cz: number, rx: number, rz: number, h: number, col: RGB, r: Rng, n = 10): void {
  const pts = blob(cx, cz, rx, rz, r, n, 0.2), top: P3 = [cx, h, cz], I: P3 = [cx, -1, cz];
  for (let i = 0; i < n; i++) {
    const a = pts[i], b = pts[(i + 1) % n];
    k.tri(top, [b[0], 0, b[1]], [a[0], 0, a[1]], col, I);
  }
}

/** A flat round spot: a cup, a target, a pot bunker. */
const spot = (k: Kit, x: number, y: number, z: number, R: number, col: RGB, n = 8): void =>
  fan(k, Array.from({ length: n }, (_, i) => [x + Math.cos((i / n) * TAU) * R, z + Math.sin((i / n) * TAU) * R] as Pt), y, col);

/** A strip along a run of points (each at its own height, lifted by dy), mitred at the joints and rounded where it turns. */
function ribbon(k: Kit, pts: P3[], w: number, dy: number, col: RGB, round = true): void {
  if (pts.length < 2) return;
  const off: Pt[] = pts.map((_, i) => {
    const a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)];
    const dx = b[0] - a[0], dz = b[2] - a[2], L = Math.hypot(dx, dz) || 1;
    return [(-dz / L) * w / 2, (dx / L) * w / 2];
  });
  for (let i = 1; i < pts.length; i++) {
    const a = pts[i - 1], b = pts[i], oa = off[i - 1], ob = off[i];
    const ya = a[1] + dy, yb = b[1] + dy;
    k.quad([a[0] + oa[0], ya, a[2] + oa[1]], [b[0] + ob[0], yb, b[2] + ob[1]], [b[0] - ob[0], yb, b[2] - ob[1]], [a[0] - oa[0], ya, a[2] - oa[1]], col,
      [(a[0] + b[0]) / 2, (ya + yb) / 2 - 1, (a[2] + b[2]) / 2]);
  }
  if (round) for (let i = 1; i < pts.length - 1; i++) spot(k, pts[i][0], pts[i][1] + dy, pts[i][2], w / 2, col, 8);
}

// ---- the course ---------------------------------------------------------------------------------

/** How a course is dressed. */
interface Look { fairway: RGB | null; green: RGB; tee: RGB; flag: RGB; sand: RGB; pot: boolean; path: RGB }

/**
 * A hole: the tee, the fairway's run (it may start short of the tee, a carry over water or off a
 * terrace), the green, and its bunkers as [along, side, radius] from the green's middle, along being
 * the way the hole plays.
 */
interface Hole { tee: P3; fair: P3[]; green: P3; w: number; bunkers: [number, number, number][]; gr?: number }

function hole(k: Kit, h: Hole, L: Look, r: Rng): void {
  if (L.fairway && h.fair.length) ribbon(k, [...h.fair, h.green], h.w, Y_FAIR, L.fairway);
  if (L.fairway && h.fair.length) spot(k, h.fair[0][0], h.fair[0][1] + Y_FAIR, h.fair[0][2], h.w / 2, L.fairway, 8);
  const [tx, ty, tz] = h.tee, [gx, gy, gz] = h.green;
  k.box(tx, ty, tz, 0.24, 0.026, 0.24, scale(L.tee, 0.82), L.tee);
  k.box(tx - 0.07, ty + 0.026, tz, 0.025, 0.02, 0.025, WHITE);
  k.box(tx + 0.07, ty + 0.026, tz, 0.025, 0.02, 0.025, WHITE);
  const from = h.fair.length ? h.fair[h.fair.length - 1] : h.tee;
  const len = Math.hypot(gx - from[0], gz - from[2]) || 1, ux = (gx - from[0]) / len, uz = (gz - from[2]) / len;
  const R = h.gr ?? 0.34;
  fan(k, blob(gx, gz, R, R * 0.8, r, 12, 0.14, Math.atan2(uz, ux)), gy + Y_GREEN, L.green);
  for (const [along, side, br] of h.bunkers) {
    const bx = gx + ux * along - uz * side, bz = gz + uz * along + ux * side;
    if (L.pot) {
      spot(k, bx, gy + Y_RIM, bz, br * 1.25, hex(0x5f6a3a), 8);
      spot(k, bx, gy + Y_SAND, bz, br, L.sand, 8);
    } else fan(k, blob(bx, bz, br * 1.3, br * 0.8, r, 9, 0.22, Math.atan2(uz, ux) + 1.2), gy + Y_SAND, L.sand);
  }
  spot(k, gx, gy + Y_CUP, gz, 0.022, DARK, 5);
  k.cyl(gx, gy, gz, 0.006, 0.34, WHITE, 4);
  k.box(gx + 0.05, gy + 0.26, gz, 0.1, 0.07, 0.006, L.flag);
}

// ---- life on the course -------------------------------------------------------------------------

/** A golfer standing at the origin facing +z, club in hand. */
function golfer(k: Kit, shirt: RGB, legs: RGB, skin: RGB, cap: RGB): void {
  k.box(0, 0, 0, 0.034, 0.05, 0.022, legs);
  k.box(0, 0.05, 0, 0.044, 0.044, 0.028, shirt);
  k.box(0, 0.094, 0, 0.026, 0.026, 0.026, skin);
  k.box(0, 0.12, 0.004, 0.03, 0.008, 0.034, cap);
  k.bar([0.018, 0.068, 0.012], [0.03, 0.004, 0.05], 0.0035, METAL);
}

/** A golf cart at the origin facing +z, two aboard and a bag on the back. */
function cart(k: Kit, roof: RGB, a: RGB, b: RGB): void {
  k.box(0, 0.018, 0, 0.09, 0.045, 0.16, WHITE);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * 0.045, 0, sz * 0.05, 0.012, 0.026, 0.026, DARK);
  k.box(0, 0.063, -0.02, 0.08, 0.016, 0.05, DARK);
  k.box(-0.02, 0.079, -0.02, 0.028, 0.04, 0.022, a);
  k.box(0.02, 0.079, -0.02, 0.028, 0.04, 0.022, b);
  k.box(-0.02, 0.119, -0.02, 0.02, 0.02, 0.02, hex(SKIN[0]));
  k.box(0.02, 0.119, -0.02, 0.02, 0.02, 0.02, hex(SKIN[2]));
  k.box(0, 0.063, -0.075, 0.04, 0.06, 0.025, hex(0x6a3a2a));
  for (const sx of [-1, 1]) k.box(sx * 0.04, 0.063, 0.03, 0.008, 0.1, 0.008, METAL);
  k.box(0, 0.16, -0.005, 0.1, 0.012, 0.15, roof);
}

/** Where along a run of points a distance s falls: the point and the way it runs. */
function along(pts: P3[], lens: number[], s: number): [P3, number] {
  let i = 1;
  while (i < lens.length - 1 && lens[i] < s) i++;
  const a = pts[i - 1], b = pts[i], f = Math.min(1, Math.max(0, (s - lens[i - 1]) / Math.max(1e-6, lens[i] - lens[i - 1])));
  return [[a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f, a[2] + (b[2] - a[2]) * f], Math.atan2(b[0] - a[0], b[2] - a[2])];
}
const runLengths = (pts: P3[]): number[] => pts.reduce<number[]>((acc, p, i) => {
  acc.push(i ? acc[i - 1] + Math.hypot(p[0] - pts[i - 1][0], p[2] - pts[i - 1][2]) : 0);
  return acc;
}, []);

const daytime = (hour: number): boolean => hour >= 7 && hour < 19.5;

/**
 * A pair of golfers playing the holes in turn (a swing on the tee, a walk to the ball and on to the
 * green, a while putting, then the next tee), and a cart up and down the path, all by day only.
 */
function golfLife(k: Kit, holes: Hole[], path: P3[] | null, r: Rng, roof: RGB): void {
  interface Leg { a: P3; b: P3; t: number; swing: boolean }
  const legs: Leg[] = [];
  const stand = (p: P3, t: number, swing: boolean) => legs.push({ a: p, b: p, t, swing });
  const walk = (a: P3, b: P3) => legs.push({ a, b, t: Math.max(0.5, Math.hypot(b[0] - a[0], b[2] - a[2]) / 0.2), swing: false });
  holes.forEach((h, i) => {
    const mid = h.fair.length ? h.fair[Math.floor(h.fair.length / 2)] : h.green;
    stand(h.tee, 4, true);
    walk(h.tee, mid);
    stand(mid, 3, true);
    walk(mid, h.green);
    stand(h.green, 6, false);
    walk(h.green, holes[(i + 1) % holes.length].tee);
  });
  const total = legs.reduce((s, l) => s + l.t, 0);
  const shirt = (): RGB => pick(r, SHIRTS), legsCol = (): RGB => pick(r, TROUSERS), skin = (): RGB => pick(r, SKIN);
  const parts: ((s: Kit) => void)[] = [0, 1].map(() => { const c = [shirt(), legsCol(), skin(), pick(r, [0xf4f2ec, 0x2f4d7a, 0xe2412f])]; return (s: Kit) => golfer(s, ...c as [RGB, RGB, RGB, RGB]); });
  const lens = path ? runLengths(path) : [];
  const L = lens.length ? lens[lens.length - 1] : 0;
  if (path && L > 0.5) { const a = shirt(), b = shirt(); parts.push((s) => cart(s, roof, a, b)); }
  let clock = r() * total, ride = r() * L * 2;
  k.rig(0, 0, 0, parts, (objs, dt, hour) => {
    const day = daytime(hour);
    for (const o of objs) o.visible = day;
    if (!day) return;
    clock = (clock + dt) % total;
    let t = clock, li = 0;
    while (li < legs.length - 1 && t > legs[li].t) { t -= legs[li].t; li++; }
    const lg = legs[li], f = Math.min(1, t / lg.t);
    const next = lg.a === lg.b ? legs[(li + 1) % legs.length].b : lg.b;
    const yaw = Math.atan2(next[0] - lg.a[0], next[2] - lg.a[2]) || 0;
    const x = lg.a[0] + (lg.b[0] - lg.a[0]) * f, y = lg.a[1] + (lg.b[1] - lg.a[1]) * f, z = lg.a[2] + (lg.b[2] - lg.a[2]) * f;
    for (let i = 0; i < 2; i++) {
      const o = objs[i], side = i ? 0.07 : -0.07;
      // the one playing stands at the ball, the other a step to the side
      const sx = Math.cos(yaw) * side, sz = -Math.sin(yaw) * side;
      o.position.set(x + (lg.swing && i === 0 ? 0 : sx), y + Y_GREEN, z + (lg.swing && i === 0 ? 0 : sz));
      const swing = lg.swing && i === 0 && t > lg.t - 1.2 ? Math.sin(((lg.t - t) / 1.2) * Math.PI) * 1.4 : 0;
      o.rotation.y = yaw + (i === 0 && lg.swing ? Math.PI / 2 - swing : 0);
    }
    if (objs[2] && path) {
      ride = (ride + dt * 0.28) % (2 * L);
      const back = ride > L, [p, h] = along(path, lens, back ? 2 * L - ride : ride);
      objs[2].position.set(p[0], p[1] + Y_PATH, p[2]);
      objs[2].rotation.y = back ? h + Math.PI : h;
    }
  });
}

/** Golfers at the range's bays, each swinging away in turn, by day. */
function rangeLife(k: Kit, bays: P3[], r: Rng): void {
  const parts = bays.map(() => { const c: [RGB, RGB, RGB, RGB] = [pick(r, SHIRTS), pick(r, TROUSERS), pick(r, SKIN), pick(r, [0xf4f2ec, 0x2f4d7a])]; return (s: Kit) => golfer(s, ...c); });
  const phase = bays.map(() => r() * 6);
  let clock = 0;
  k.rig(0, 0, 0, parts, (objs, dt, hour) => {
    const day = daytime(hour);
    clock += dt;
    objs.forEach((o, i) => {
      o.visible = day;
      const p = bays[i];
      o.position.set(p[0], p[1], p[2]);
      const c = (clock + phase[i]) % 5;
      o.rotation.y = Math.PI / 2 - (c < 1 ? Math.sin(c * Math.PI) * 1.5 : 0);
    });
  });
}

/** A cart that runs up and down a run of points by day: the range's ball picker. */
function shuttle(k: Kit, pts: P3[], draw: (s: Kit) => void, speed: number): void {
  const lens = runLengths(pts), L = lens[lens.length - 1];
  let s = 0;
  k.rig(0, 0, 0, [draw], (objs, dt, hour) => {
    const o = objs[0];
    o.visible = daytime(hour);
    s = (s + dt * speed) % (2 * L);
    const back = s > L, [p, h] = along(pts, lens, back ? 2 * L - s : s);
    o.position.set(p[0], p[1], p[2]);
    o.rotation.y = back ? h + Math.PI : h;
  });
}

/** A striped parasol over a café table. */
function parasol(k: Kit, x: number, z: number, col: RGB): void {
  k.cyl(x, 0, z, 0.006, 0.26, WHITE, 4);
  k.cone(x, 0.22, z, 0.13, 0.06, col, 6);
  k.cyl(x, 0, z, 0.05, 0.07, WHITE, 6);
}

/** Lay a run of points across the lot: (u, v) in halves of the lot's width and depth, at height y. */
const at = (W: number, D: number) => (u: number, v: number, y = 0): P3 => [(u * W) / 2, y, (v * D) / 2];

// ---- 1. the links ------------------------------------------------------------------------------

/**
 * Links among the dunes: tawny fescue, pale fairways winding between gorse, deep pot bunkers, a burn
 * across the course under its old stone bridge, a ridge of marram dunes along the back, and the grey
 * stone clubhouse with its slate roof.
 */
const links: Draw = (k, W, D, b, r) => {
  const P = at(W, D);
  const L: Look = { fairway: hex(0x7cb84a), green: hex(0x62c84c), tee: hex(0x74bc4c), flag: hex(0xf2d23a), sand: hex(0xf0e2b6), pot: true, path: hex(0xcdbf98) };
  k.box(0, 0, 0, W, Y_BASE, D, hex(0xb3b46a));
  for (let i = 0; i < 6; i++) fan(k, blob(-W / 2 + 0.8 + r() * (W - 1.6), -D / 2 + 1 + r() * (D - 2), 0.5 + r() * 0.4, 0.3 + r() * 0.2, r, 9, 0.3, r() * TAU), Y_PATCH, i % 2 ? hex(0xc4b874) : hex(0x9fa65a));
  // the dunes along the back, sand showing through the marram
  for (let x = -W / 2 + 0.55, i = 0; x < W / 2 - 0.5; x += 0.8 + r() * 0.35, i++) {
    const h = 0.14 + r() * 0.12, z = -D / 2 + 0.34 + r() * 0.06;
    mound(k, x, z, 0.5, 0.32, h * 0.75, i % 2 ? hex(0xdccb98) : hex(0xcfc08a), r);
    mound(k, x + 0.1, z + 0.04, 0.4, 0.26, h, i % 2 ? hex(0x9ea25c) : hex(0xa9a866), r);
    k.cone(x - 0.2, h * 0.45, z + 0.15, 0.05, 0.08, hex(0x8f9a52), 4);
  }
  // the burn, and the old stone bridge over it by the first tee
  const burn: P3[] = [P(-0.99, 0.18), P(-0.6, 0.05), P(-0.2, 0.2), P(0.25, 0.08), P(0.65, 0.25), P(0.99, 0.12)];
  ribbon(k, burn, 0.22, Y_SHORE, hex(0x7c9a4c), false);
  ribbon(k, burn, 0.12, Y_WATER, WATER, false);
  const bx = burn[1][0] + 0.25, bz = 0.13 * D / 2;
  const stone = hex(0xb8b0a0);
  k.bar([bx, 0.01, bz - 0.2], [bx, 0.07, bz], 0.05, stone);
  k.bar([bx, 0.07, bz], [bx, 0.01, bz + 0.2], 0.05, stone);
  // the holes: doglegs out to the dunes and back, with pot bunkers in the way
  const holes: Hole[] = [
    { tee: P(-0.62, 0.62), fair: [P(-0.55, 0.3), P(-0.62, -0.1)], green: P(-0.78, -0.52), w: 0.42, bunkers: [[-0.5, 0.12, 0.07], [0.05, 0.36, 0.08], [-1.1, -0.2, 0.07]] },
    { tee: P(-0.5, -0.55), fair: [P(-0.25, -0.4), P(0.05, -0.58)], green: P(0.3, -0.5), w: 0.4, bunkers: [[-0.42, -0.08, 0.08], [0.3, 0.3, 0.07], [-0.9, 0.18, 0.09]] },
    { tee: P(0.5, -0.6), fair: [P(0.6, -0.25), P(0.72, 0.05)], green: P(0.8, 0.52), w: 0.42, bunkers: [[-0.45, -0.1, 0.07], [-0.4, 0.14, 0.07], [0.1, -0.36, 0.08]] },
    { tee: P(0.5, 0.7), fair: [P(0.3, 0.5), P(0.0, 0.42)], green: P(-0.2, 0.52), w: 0.4, bunkers: [[-0.38, 0.0, 0.1], [0.26, 0.28, 0.07]] },
  ];
  for (const h of holes) hole(k, h, L, r);
  // gorse in flower in the rough
  for (let i = 0; i < 9; i++) {
    const x = -W / 2 + 0.5 + r() * (W - 1), z = -D / 2 + 1.0 + r() * (D - 1.6);
    if (holes.some((h) => Math.hypot(h.green[0] - x, h.green[2] - z) < 0.6 || [h.tee, ...h.fair].some((p) => Math.hypot(p[0] - x, p[2] - z) < 0.4))) continue;
    k.hip(x, 0, z, 0.2, 0.1, 0.16, hex(0x5f7a34));
    k.hip(x + 0.02, 0.03, z, 0.13, 0.08, 0.1, hex(0xe6c83a));
  }
  // the path from the clubhouse, worn across the links
  const path: P3[] = [P(-0.72, 0.84), P(-0.42, 0.74), P(-0.1, 0.78), P(0.3, 0.82), P(0.66, 0.84)];
  ribbon(k, path, 0.08, Y_PATH, L.path);
  // the clubhouse: grey stone, slate, a big bay window over the eighteenth, a chimney at each end
  const cx = -W / 2 + 0.75, cz = D / 2 - 0.42, slate = hex(0x4a5058);
  k.box(cx, 0, cz, 1.0, 0.3, 0.46, hex(0xbcb5a6));
  k.gable(cx, 0.3, cz, 1.06, 0.2, 0.52, slate, hex(0xbcb5a6));
  for (const sx of [-1, 1]) k.box(cx + sx * 0.44, 0.3, cz, 0.08, 0.26, 0.1, hex(0xa9a292));
  k.box(cx + 0.18, 0, cz - 0.27, 0.32, 0.22, 0.08, hex(0xbcb5a6), slate);
  win(k, b, r, cx + 0.18, 0.08, cz - 0.31, 0.26, 0.12, 3, GLASS_LIGHT);
  for (let i = 0; i < 3; i++) win(k, b, r, cx - 0.34 + i * 0.2, 0.1, cz + 0.23, 0.12, 0.12, 1, GLASS_LIGHT);
  k.box(cx - 0.3, 0, cz - 0.231, 0.09, 0.18, 0.004, hex(0x2f4d3a));
  flag(k, cx + 0.62, 0, cz - 0.05, 0.7, hex(0x2f5fa8));
  // a dry stone wall along the front
  k.box(W / 2 - (W - 2.0) / 2 - 0.1, 0, D / 2 - 0.06, W - 2.2, 0.06, 0.06, hex(0xa49c8a));
  golfLife(k, holes, path, r, hex(0x2f5d3a));
};

// ---- 2. parkland -------------------------------------------------------------------------------

/**
 * Parkland: deep-mown stripes, avenues of old trees between the fairways, a lake in the middle with a
 * fountain and an island green over a footbridge, a grey cart path round it all, and the white manor
 * clubhouse with its portico and a terrace of parasols.
 */
const parkland: Draw = (k, W, D, b, r) => {
  const P = at(W, D);
  const L: Look = { fairway: hex(0x67b84a), green: hex(0x84d65c), tee: hex(0x74c252), flag: hex(0xe2412f), sand: SAND, pot: false, path: hex(0xc8c4b8) };
  const n = Math.round(W / 0.6), I: P3 = [0, -1, 0];
  for (let i = 0; i < n; i++) {
    const x0 = -W / 2 + (W * i) / n, x1 = -W / 2 + (W * (i + 1)) / n;
    k.quad([x0, Y_BASE, -D / 2], [x1, Y_BASE, -D / 2], [x1, Y_BASE, D / 2], [x0, Y_BASE, D / 2], i % 2 ? hex(0x3f8f3a) : hex(0x46993f), I);
  }
  // the lake, and its fountain
  const lx = 0.1 * W / 2, lz = -0.05 * D / 2;
  fan(k, blob(lx, lz, 1.12, 0.66, r, 14, 0.12, 0.1), Y_SHORE, hex(0x356f34));
  fan(k, blob(lx, lz, 1.04, 0.58, r, 14, 0.12, 0.1), Y_WATER, hex(0x4a98c4));
  k.cyl(lx - 0.45, 0, lz + 0.05, 0.012, 0.22, hex(0xe8f4fa), 4);
  k.cone(lx - 0.45, 0.12, lz + 0.05, 0.07, 0.1, hex(0xdcecf4), 6);
  // the island green and its footbridge
  const ig: P3 = [lx + 0.45, 0, lz];
  fan(k, blob(ig[0], ig[2], 0.3, 0.26, r, 10, 0.1), Y_GREEN - 0.001, hex(0x5f9a48));
  k.box(ig[0] + 0.3, 0.012, ig[2] + 0.12, 0.4, 0.025, 0.09, WOOD);
  for (const s of [-1, 1]) k.box(ig[0] + 0.3, 0.037, ig[2] + 0.12 + s * 0.04, 0.4, 0.04, 0.008, hex(0x6a5038));
  const holes: Hole[] = [
    { tee: P(-0.72, 0.66), fair: [P(-0.75, 0.3), P(-0.7, -0.05)], green: P(-0.66, -0.55), w: 0.5, bunkers: [[-0.3, 0.32, 0.1], [0.25, -0.34, 0.09]] },
    { tee: P(-0.4, -0.78), fair: [P(-0.15, -0.72), P(0.2, -0.74)], green: P(0.55, -0.62), w: 0.48, bunkers: [[-0.2, 0.34, 0.1], [0.1, -0.36, 0.09], [-0.9, 0.3, 0.12]] },
    { tee: P(0.82, -0.3), fair: [P(0.84, 0.05)], green: P(0.76, 0.56), w: 0.5, bunkers: [[-0.34, -0.3, 0.11], [0.0, 0.38, 0.09]] },
    // the signature hole: over the water to the island
    { tee: P(0.62, 0.42), fair: [], green: ig, w: 0.4, bunkers: [[0.12, 0.2, 0.06]], gr: 0.26 },
  ];
  for (const h of holes) hole(k, h, L, r);
  // the cart path round the lake
  const path: P3[] = [P(-0.6, 0.86), P(-0.5, 0.45), P(-0.45, 0.0), P(-0.4, -0.5), P(-0.05, -0.55), P(0.45, -0.42), P(0.62, 0.0), P(0.55, 0.62), P(0.2, 0.84)];
  ribbon(k, path, 0.09, Y_PATH, L.path);
  // avenues of trees: between the first fairway and the lake, along the back and down the right
  const trees: Pt[] = [];
  for (let i = 0; i < 5; i++) trees.push([P(-0.9, 0.5 - i * 0.3)[0] - 0.05, P(0, 0.5 - i * 0.3)[2]]);
  for (let i = 0; i < 5; i++) trees.push([P(-0.55 + i * 0.32, 0)[0], -D / 2 + 0.34]);
  for (let i = 0; i < 3; i++) trees.push([W / 2 - 0.34, P(0, -0.6 + i * 0.45)[2]]);
  for (const [x, z] of trees) tree(k, x + (r() - 0.5) * 0.08, 0, z + (r() - 0.5) * 0.08, 0.8 + r() * 0.2, r() < 0.2);
  // the manor clubhouse, its portico, its terrace
  const cx = W / 2 - 1.05, cz = D / 2 - 0.4;
  k.box(cx, 0, cz, 1.2, 0.36, 0.5, WHITE);
  k.hip(cx, 0.36, cz, 1.3, 0.2, 0.6, hex(0x3f5a4a));
  k.box(cx, 0, cz - 0.31, 0.44, 0.03, 0.12, hex(0xe3dccb));
  for (let i = 0; i < 4; i++) k.cyl(cx - 0.18 + i * 0.12, 0.03, cz - 0.34, 0.016, 0.3, WHITE, 5);
  k.gable(cx, 0.33, cz - 0.31, 0.46, 0.1, 0.14, WHITE, WHITE);
  for (let i = 0; i < 4; i++) win(k, b, r, cx - 0.45 + i * 0.3, 0.1, cz + 0.25, 0.14, 0.14, 1, GLASS_LIGHT);
  for (let i = 0; i < 2; i++) win(k, b, r, cx - 0.42 + i * 0.84, 0.12, cz - 0.25, 0.14, 0.14, 3, GLASS_LIGHT);
  for (let i = 0; i < 3; i++) parasol(k, cx - 0.95 + i * 0.28, cz - 0.08 + (i % 2) * 0.12, i % 2 ? WHITE : hex(0x2f5d3a));
  // carts parked by the door
  for (let i = 0; i < 3; i++) {
    k.box(cx + 0.72, 0.018, cz - 0.15 + i * 0.16, 0.16, 0.045, 0.09, WHITE);
    k.box(cx + 0.72, 0.16, cz - 0.15 + i * 0.16, 0.15, 0.012, 0.1, hex(0x2f5d3a));
  }
  golfLife(k, holes, path, r, hex(0x2f5d3a));
};

// ---- 3. desert target golf ---------------------------------------------------------------------

/** A saguaro, its arms up. */
function saguaro(k: Kit, x: number, z: number, h: number, r: Rng): void {
  const g = hex(0x5c8a48);
  k.cyl(x, 0, z, 0.028, h, g, 5);
  for (const s of r() < 0.5 ? [-1, 1] : [r() < 0.5 ? -1 : 1]) {
    const y = h * (0.35 + r() * 0.2);
    k.bar([x, y, z], [x + s * 0.08, y, z], 0.018, g);
    k.bar([x + s * 0.08, y - 0.01, z], [x + s * 0.08, y + h * 0.35, z], 0.018, g);
  }
}

/**
 * Desert target golf: green islands of tee, fairway and green laid over the sand and scrub, white-sand
 * bunkers, red rocks and a butte in the corner, saguaros, an oasis pond with palms, a pale concrete
 * cart path, and an adobe clubhouse with its beams poking through and a shady ramada.
 */
const desert: Draw = (k, W, D, b, r) => {
  const P = at(W, D);
  const L: Look = { fairway: null, green: hex(0x7fcf58), tee: hex(0x6cbf4c), flag: hex(0xf28c38), sand: hex(0xfbf4e2), pot: false, path: hex(0xd8cdb4) };
  k.box(0, 0, 0, W, Y_BASE, D, hex(0xe0c08a));
  for (let i = 0; i < 7; i++) fan(k, blob(-W / 2 + 0.6 + r() * (W - 1.2), -D / 2 + 0.6 + r() * (D - 1.2), 0.4 + r() * 0.3, 0.25 + r() * 0.2, r, 8, 0.3, r() * TAU), Y_PATCH, i % 2 ? hex(0xcdb07a) : hex(0xd8a878));
  const fw = hex(0x62b244);
  const holes: Hole[] = [
    { tee: P(-0.75, 0.62), fair: [P(-0.72, 0.15)], green: P(-0.72, -0.5), w: 0.5, bunkers: [[-0.3, 0.3, 0.1], [0.3, -0.25, 0.09]] },
    { tee: P(-0.42, -0.72), fair: [P(-0.05, -0.62)], green: P(0.35, -0.55), w: 0.5, bunkers: [[-0.32, -0.3, 0.1], [0.2, 0.35, 0.08]] },
    { tee: P(0.42, -0.1), fair: [P(0.6, 0.22)], green: P(0.82, 0.58), w: 0.5, bunkers: [[-0.3, 0.32, 0.11]] },
    { tee: P(0.3, 0.72), fair: [P(-0.05, 0.4)], green: P(-0.3, 0.12), w: 0.5, bunkers: [[0.0, -0.36, 0.1], [-0.36, 0.1, 0.08]] },
  ];
  // the target fairways: islands of green, the sand between them to carry
  for (const h of holes) for (const p of h.fair) {
    fan(k, blob(p[0], p[2], 0.48, 0.34, r, 11, 0.22, r() * TAU), Y_SHORE, hex(0x4f9a3c));
    fan(k, blob(p[0], p[2], 0.42, 0.28, r, 11, 0.2, r() * TAU), Y_FAIR, fw);
  }
  for (const h of holes) {
    fan(k, blob(h.green[0], h.green[2], 0.46, 0.4, r, 11, 0.15), Y_FAIR, fw);
    fan(k, blob(h.tee[0], h.tee[2], 0.22, 0.2, r, 8, 0.1), Y_FAIR, fw);
    hole(k, h, L, r);
  }
  // the oasis, its palms, and a little fall over the rocks into it
  const ox = P(0.0, 0)[0], oz = P(0, -0.12)[2];
  fan(k, blob(ox, oz, 0.5, 0.36, r, 12, 0.2), Y_SHORE, hex(0x7cb05a));
  fan(k, blob(ox, oz, 0.42, 0.28, r, 12, 0.2), Y_WATER, hex(0x3fb0c8));
  k.hip(ox - 0.35, 0, oz - 0.22, 0.32, 0.22, 0.24, hex(0xb5703f));
  k.quad([ox - 0.33, 0.16, oz - 0.12], [ox - 0.25, 0.16, oz - 0.12], [ox - 0.25, 0.012, oz - 0.06], [ox - 0.33, 0.012, oz - 0.06], hex(0xd8f0f8), [ox - 0.29, 0.1, oz - 0.3]);
  palm(k, ox + 0.38, oz - 0.2, 0.55);
  palm(k, ox + 0.46, oz + 0.12, 0.62);
  // red rocks, and a butte in the far corner
  const rock = hex(0xb5703f), band = hex(0xc98a52);
  const bx = W / 2 - 0.55, bz = -D / 2 + 0.45;
  k.box(bx, 0, bz, 0.7, 0.32, 0.5, rock, band);
  k.box(bx + 0.05, 0.32, bz, 0.5, 0.16, 0.36, band, hex(0xd29a62));
  k.hip(bx - 0.42, 0, bz + 0.1, 0.3, 0.16, 0.3, rock);
  for (let i = 0; i < 5; i++) k.hip(-W / 2 + 0.6 + r() * (W - 1.6), 0, -D / 2 + 0.6 + r() * (D - 1.4), 0.14 + r() * 0.1, 0.07 + r() * 0.06, 0.12 + r() * 0.08, i % 2 ? rock : hex(0xa0603a));
  // saguaros where the play isn't
  let made = 0;
  for (let tries = 0; tries < 30 && made < 8; tries++) {
    const x = -W / 2 + 0.3 + r() * (W - 0.6), z = -D / 2 + 0.3 + r() * (D - 0.9);
    if (holes.some((h) => [h.tee, h.green, ...h.fair].some((p) => Math.hypot(p[0] - x, p[2] - z) < 0.55))) continue;
    if (Math.hypot(ox - x, oz - z) < 0.6 || Math.hypot(bx - x, bz - z) < 0.6) continue;
    saguaro(k, x, z, 0.24 + r() * 0.16, r);
    made++;
  }
  const path: P3[] = [P(-0.55, 0.85), P(-0.5, 0.4), P(-0.5, -0.2), P(-0.3, -0.42), P(0.1, -0.35), P(0.25, 0.1), P(0.5, 0.4), P(0.62, 0.82)];
  ribbon(k, path, 0.09, Y_PATH, L.path);
  // the adobe clubhouse: flat roof behind its parapet, vigas through the wall, a ramada of poles
  const cx = -W / 2 + 0.8, cz = D / 2 - 0.4, adobe = hex(0xd9a877);
  k.box(cx, 0, cz, 0.9, 0.3, 0.5, adobe, hex(0xc99a6a));
  k.box(cx + 0.25, 0.3, cz + 0.05, 0.4, 0.12, 0.34, adobe, hex(0xc99a6a));
  for (let i = 0; i < 5; i++) k.box(cx - 0.36 + i * 0.18, 0.26, cz - 0.27, 0.025, 0.025, 0.06, WOOD);
  for (let i = 0; i < 3; i++) win(k, b, r, cx - 0.28 + i * 0.28, 0.1, cz - 0.25, 0.12, 0.12, 3, GLASS_LIGHT);
  const rx = cx + 0.82, rz = cz - 0.05;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(rx + sx * 0.25, 0, rz + sz * 0.16, 0.025, 0.26, 0.025, WOOD);
  for (let i = 0; i < 6; i++) k.box(rx - 0.27 + i * 0.108, 0.26, rz, 0.03, 0.02, 0.4, hex(0xa07a50));
  golfLife(k, holes, path, r, hex(0xc96a3a));
};

// ---- 4. the mountain course --------------------------------------------------------------------

/**
 * The mountain course: the lot rises in terraces behind rock retaining walls, the top tees teeing
 * off over the drop, a crag in the corner with snow on its top and a fall off it into a pond below,
 * pines on every ledge, a cart path zigzagging up, and a timber chalet clubhouse.
 */
const mountain: Draw = (k, W, D, b, r) => {
  const P = at(W, D);
  const L: Look = { fairway: hex(0x6cb84a), green: hex(0x88d462), tee: hex(0x78c456), flag: hex(0x2f7fb5), sand: SAND, pot: false, path: hex(0xb8a888) };
  const meadow = hex(0x5a9a44), rockFace = hex(0x8d8a80);
  k.box(0, 0, 0, W, Y_BASE, D, meadow);
  // the terraces: a top one along the back, a middle one in front of it, each a rock wall with turf on top
  const H1 = 0.12, H2 = 0.24;
  const box = (x0: number, x1: number, z0: number, z1: number) => ({ x0, x1, z0, z1, x: (x0 + x1) / 2, z: (z0 + z1) / 2, w: x1 - x0, d: z1 - z0 });
  const t2 = box(-W / 2 + 0.1, 0.15 * W / 2, -D / 2 + 0.1, -0.45 * D / 2);
  const t1 = box(-W / 2 + 0.1, 0.55 * W / 2, t2.z1 - 0.05, 0.25 * D / 2);
  k.box(t1.x, 0, t1.z, t1.w, H1, t1.d, rockFace, meadow);
  k.box(t2.x, 0, t2.z, t2.w, H2, t2.d, rockFace, meadow);
  // the crag, snow on its peaks, and the fall off it into the pond
  const cx = W / 2 - 0.85, cz = -D / 2 + 0.85;
  k.cone(cx, 0, cz, 0.8, 0.95, hex(0x7f7a72), 7);
  k.cone(cx + 0.28, 0, cz + 0.32, 0.5, 0.6, hex(0x8f8a80), 6);
  k.cone(cx, 0.72, cz, 0.22, 0.25, WHITE, 7);
  k.cone(cx + 0.28, 0.45, cz + 0.32, 0.13, 0.16, WHITE, 6);
  const fx = cx - 0.2, fz = cz + 0.45;
  k.quad([fx - 0.06, 0.5, fz - 0.12], [fx + 0.06, 0.5, fz - 0.12], [fx + 0.07, 0.01, fz + 0.12], [fx - 0.07, 0.01, fz + 0.12], hex(0xdaf0f8), [fx, 0.3, fz - 0.6]);
  const pond = P(0.62, 0.5);
  fan(k, blob(pond[0], pond[2], 0.5, 0.34, r, 12, 0.2), Y_SHORE, hex(0x8a8a7a));
  fan(k, blob(pond[0], pond[2], 0.44, 0.28, r, 12, 0.2), Y_WATER, hex(0x4a90b8));
  ribbon(k, [[fx, 0, fz + 0.1], [fx + 0.05, 0, (fz + pond[2]) / 2], [pond[0], 0, pond[2] - 0.2]], 0.1, Y_WATER, hex(0x4a90b8), false);
  // the holes: off the top terrace down onto the middle, back along the middle, off it to the green below, and home
  const lx = (f: number) => t1.x0 + (t1.x1 - t1.x0) * f;
  const holes: Hole[] = [
    { tee: [t2.x0 + 0.35, H2, t2.z], fair: [[lx(0.4), H1, t1.z0 + 0.35]], green: [t1.x1 - 0.45, H1, t1.z0 + 0.4], w: 0.42, bunkers: [[-0.35, 0.3, 0.08], [0.2, -0.32, 0.08]] },
    { tee: [t1.x1 - 0.45, H1, t1.z1 - 0.3], fair: [[lx(0.55), H1, t1.z1 - 0.32], [lx(0.3), H1, t1.z1 - 0.38]], green: [t1.x0 + 0.45, H1, t1.z + 0.05], w: 0.42, bunkers: [[-0.3, 0.3, 0.08]] },
    { tee: [lx(0.62), H1, t1.z1 - 0.2], fair: [], green: P(0.3, 0.72), w: 0.4, bunkers: [[0.2, -0.32, 0.08], [-0.3, 0.3, 0.07]], gr: 0.3 },
    { tee: P(0.05, 0.82), fair: [P(-0.3, 0.6)], green: P(-0.55, 0.45), w: 0.42, bunkers: [[0.3, 0.3, 0.08]] },
  ];
  for (const h of holes) hole(k, h, L, r);
  // the cart path: up from the chalet, a ramp onto the middle terrace, another onto the top
  const rx1 = lx(0.18), rx2 = t2.x0 + t2.w * 0.75, gravel = hex(0x9a8a6a);
  const ramp = (x: number, z0: number, z1: number, y0: number, y1: number) => {
    const w = 0.12, In: P3 = [x, y0, (z0 + z1) / 2];
    k.quad([x - w / 2, y0, z0], [x + w / 2, y0, z0], [x + w / 2, y1, z1], [x - w / 2, y1, z1], gravel, In);
    k.tri([x - w / 2, y0, z0], [x - w / 2, y1, z1], [x - w / 2, y0, z1], rockFace, [x, y0, z1]);
    k.tri([x + w / 2, y0, z0], [x + w / 2, y1, z1], [x + w / 2, y0, z1], rockFace, [x, y0, z1]);
  };
  ramp(rx1, t1.z1 + 0.5, t1.z1, 0, H1);
  ramp(rx2, t2.z1 + 0.5, t2.z1, H1, H2);
  const path: P3[] = [P(-0.62, 0.86), [rx1, 0, t1.z1 + 0.62], [rx1, 0, t1.z1 + 0.5], [rx1, H1, t1.z1], [rx1, H1, t1.z1 - 0.15],
    [rx2, H1, t2.z1 + 0.62], [rx2, H1, t2.z1 + 0.5], [rx2, H2, t2.z1], [rx2, H2, t2.z - 0.05], [t2.x0 + 0.6, H2, t2.z - 0.05]];
  ribbon(k, path, 0.09, Y_PATH, L.path);
  // pines on the ledges and round the crag, each on whatever level it stands on, none on the ramps
  const inside = (t: typeof t1, x: number, z: number) => x > t.x0 && x < t.x1 && z > t.z0 && z < t.z1;
  const level = (x: number, z: number) => inside(t2, x, z) ? H2 : inside(t1, x, z) ? H1 : 0;
  const pines: Pt[] = [];
  for (let i = 0; i < 4; i++) pines.push([t2.x0 + 0.2 + i * (t2.w - 0.4) / 3, t2.z0 + 0.12]);
  for (let i = 0; i < 3; i++) pines.push([cx - 0.9 - i * 0.3, -D / 2 + 0.25 + i * 0.05]);
  for (let i = 0; i < 4; i++) pines.push([t1.x0 + 0.6 + i * 0.85, t1.z1 - 0.06]);
  for (const [u, v] of [[0.95, 0.75], [0.85, -0.05], [-0.95, 0.2]]) pines.push([(u * W) / 2, (v * D) / 2]);
  for (const [x, z] of pines) {
    if (Math.abs(x - rx1) < 0.32 || Math.abs(x - rx2) < 0.32 && z > t2.z1 - 0.1 && z < t2.z1 + 0.6) continue;
    tree(k, x + (r() - 0.5) * 0.08, level(x, z), z, 0.7 + r() * 0.3, true);
  }
  // the chalet: dark timber, a steep roof deep over a balcony
  const hx = -W / 2 + 0.7, hz = D / 2 - 0.42, timber = hex(0x8a5a3a);
  k.box(hx, 0, hz, 0.8, 0.34, 0.46, timber);
  k.box(hx, 0.17, hz - 0.29, 0.8, 0.02, 0.12, hex(0x6a4428));
  for (let i = 0; i < 5; i++) k.box(hx - 0.38 + i * 0.19, 0.19, hz - 0.345, 0.012, 0.07, 0.012, WHITE);
  k.gable(hx, 0.34, hz - 0.03, 0.92, 0.3, 0.64, hex(0x5a3a2a), timber);
  for (let i = 0; i < 3; i++) win(k, b, r, hx - 0.25 + i * 0.25, 0.2, hz - 0.231, 0.12, 0.1, 3, GLASS_LIGHT);
  for (let i = 0; i < 3; i++) win(k, b, r, hx - 0.25 + i * 0.25, 0.08, hz - 0.231, 0.12, 0.08, 3, GLASS_LIGHT);
  golfLife(k, holes, path, r, hex(0x2f4d7a));
};

// ---- 5. the clubhouse and driving range --------------------------------------------------------

/**
 * A club with a driving range: a long two-storey bay building of mats under a roof, golfers hitting
 * away, yardage targets out on the striped range with their flags and boards, catch-net poles along
 * the back and the ball picker crawling up and down; beside it a big modern clubhouse, a car park, a
 * practice putting green and a little pitch-and-putt round a pond.
 */
const range: Draw = (k, W, D, b, r) => {
  const P = at(W, D);
  const L: Look = { fairway: hex(0x67b84a), green: hex(0x84d65c), tee: hex(0x74c252), flag: WHITE, sand: SAND, pot: false, path: hex(0xc8c4b8) };
  k.box(0, 0, 0, W, Y_BASE, D, hex(0x4c9a40));
  // the range: from x0 to the lot's right edge, hit from the front toward the back
  const x0 = -W / 2 + W * 0.45, x1 = W / 2 - 0.1, rw = x1 - x0, mx = (x0 + x1) / 2;
  const stripes = 8, I: P3 = [0, -1, 0];
  for (let i = 0; i < stripes; i++) {
    const z0 = -D / 2 + 0.1 + ((D - 1.0) * i) / stripes, z1 = -D / 2 + 0.1 + ((D - 1.0) * (i + 1)) / stripes;
    k.quad([x0, Y_PATCH, z0], [x1, Y_PATCH, z0], [x1, Y_PATCH, z1], [x0, Y_PATCH, z1], i % 2 ? hex(0x5aac44) : hex(0x62b64a), I);
  }
  const targets: [number, number, number, number][] = [[-0.25, 0.25, 0.26, 0xe2412f], [0.25, -0.05, 0.3, 0xf2c14e], [-0.1, -0.45, 0.34, 0xf4f2ec], [0.3, -0.7, 0.3, 0x2f7fb5]];
  for (const [u, v, R, c] of targets) {
    const x = mx + u * rw / 2, z = (v * D) / 2;
    fan(k, blob(x, z, R, R * 0.75, r, 12, 0.1), Y_GREEN, hex(0x7fd058));
    spot(k, x, Y_RIM, z, R * 0.3, hex(c), 8);
    k.cyl(x, 0, z, 0.006, 0.3, WHITE, 4);
    k.box(x + 0.05, 0.22, z, 0.1, 0.07, 0.006, hex(c));
    k.box(x0 + 0.12, 0, z, 0.03, 0.2, 0.03, WHITE);
    k.box(x0 + 0.12, 0.14, z, 0.012, 0.1, 0.16, hex(c));
  }
  // catch-net poles along the back and down the far side
  const net = hex(0x3a4a3a);
  for (let i = 0; i <= 5; i++) k.cyl(x0 + (rw * i) / 5, 0, -D / 2 + 0.08, 0.016, 0.7, METAL, 4);
  k.bar([x0, 0.7, -D / 2 + 0.08], [x1, 0.7, -D / 2 + 0.08], 0.006, net);
  k.bar([x0, 0.4, -D / 2 + 0.08], [x1, 0.4, -D / 2 + 0.08], 0.004, net);
  // the bay building along the front: two decks of mats under a long roof
  const bz = D / 2 - 0.42, bays = 6, bw = rw - 0.2, by = 0.2;
  k.box(mx, 0, bz + 0.12, bw, 0.03, 0.28, hex(0xc8c4b8));
  k.box(mx, by, bz + 0.12, bw, 0.025, 0.3, hex(0xd8d4c8), hex(0x9a9a92));
  k.box(mx, 0, bz + 0.28, bw, 0.1, 0.04, hex(0x2f5d3a));
  k.box(mx, 0.42, bz + 0.12, bw + 0.1, 0.03, 0.42, hex(0x2f5d3a), hex(0x3f6f4a));
  for (let i = 0; i <= bays; i++) k.box(mx - bw / 2 + (bw * i) / bays, 0, bz, 0.02, 0.42, 0.02, WHITE);
  const spots: P3[] = [];
  for (let i = 0; i < bays; i++) {
    const x = mx - bw / 2 + (bw * (i + 0.5)) / bays;
    k.box(x, 0.03, bz + 0.04, 0.12, 0.004, 0.1, hex(0x3f7a3a));
    if (i % 2 === 0) spots.push([x - 0.04, 0.03, bz + 0.07]);
    if (i % 2 === 1) spots.push([x - 0.04, by + 0.025, bz + 0.07]);
  }
  rangeLife(k, spots, r);
  // the ball picker
  const sweep: P3[] = [];
  for (let i = 0; i < 4; i++) {
    const z = -D / 2 + 0.5 + i * (D - 1.6) / 3;
    sweep.push(i % 2 ? [x1 - 0.3, 0.006, z] : [x0 + 0.35, 0.006, z]);
    sweep.push(i % 2 ? [x0 + 0.35, 0.006, z] : [x1 - 0.3, 0.006, z]);
  }
  shuttle(k, sweep, (s) => {
    s.box(0, 0.02, 0, 0.09, 0.05, 0.14, hex(0xf2c14e));
    s.box(0, 0.07, -0.02, 0.08, 0.06, 0.06, hex(0x2f5d3a));
    s.box(0, 0, -0.13, 0.22, 0.02, 0.06, METAL);
  }, 0.22);
  // the clubhouse: two storeys of glass under a deep flat roof
  const cx = -W / 2 + 1.05, cz = D / 2 - 0.55;
  k.box(cx, 0, cz, 1.5, 0.22, 0.6, hex(0xe8e4dc));
  k.box(cx + 0.1, 0.22, cz + 0.05, 1.2, 0.2, 0.5, hex(0xf4f2ec));
  k.box(cx + 0.1, 0.42, cz + 0.05, 1.5, 0.03, 0.72, hex(0x3a3f45));
  win(k, b, r, cx, 0.04, cz - 0.3, 1.3, 0.15, 3, GLASS_LIGHT);
  win(k, b, r, cx + 0.1, 0.25, cz - 0.2, 1.1, 0.13, 3, GLASS_LIGHT);
  k.glowBox(cx - 0.4, 0.36, cz - 0.21, 0.4, 0.05, 0.01, hex(0x2f5d3a), [17, 24, 2], WARM_GLOW);
  flag(k, cx + 0.85, 0, cz - 0.4, 0.75, hex(0x2f5d3a));
  // the car park beside it
  const px = cx, pz = cz - 0.75;
  k.box(px, 0, pz, 1.5, 0.008, 0.4, hex(0x6a6e72));
  for (let i = 0; i < 6; i++) {
    k.box(px - 0.65 + i * 0.26, 0.008, pz, 0.012, 0.002, 0.34, WHITE);
    if (r() < 0.7) car(k, px - 0.52 + i * 0.26, pz, false, pick(r, [0xe2412f, 0x2f7fb5, 0xf4f2ec, 0x3a3f45, 0xb9bdc2]));
  }
  // the practice green
  const pg = P(-0.55, -0.15);
  fan(k, blob(pg[0], pg[2], 0.5, 0.32, r, 12, 0.12), Y_GREEN, L.green);
  for (let i = 0; i < 4; i++) {
    const x = pg[0] - 0.3 + i * 0.2, z = pg[2] + (i % 2 ? 0.1 : -0.1);
    spot(k, x, Y_CUP, z, 0.018, DARK, 5);
    k.cyl(x, 0, z, 0.004, 0.16, WHITE, 4);
    k.box(x + 0.03, 0.12, z, 0.05, 0.035, 0.004, hex([0xe2412f, 0xf2c14e, 0x2f7fb5, 0xf28c38][i]));
  }
  // the pitch and putt round its pond at the back
  const pond = P(-0.62, -0.62);
  fan(k, blob(pond[0], pond[2], 0.32, 0.22, r, 10, 0.2), Y_WATER, WATER);
  const holes: Hole[] = [
    { tee: P(-0.95, -0.35), fair: [], green: P(-0.3, -0.75), w: 0.3, bunkers: [[0.15, 0.22, 0.06]], gr: 0.24 },
    { tee: P(-0.22, -0.5), fair: [], green: P(-0.92, -0.82), w: 0.3, bunkers: [[-0.2, -0.2, 0.06]], gr: 0.24 },
  ];
  for (const h of holes) hole(k, h, L, r);
  const path: P3[] = [P(-0.82, 0.25), P(-0.95, -0.1), P(-0.95, -0.5)];
  ribbon(k, path, 0.08, Y_PATH, L.path);
  tree(k, P(-0.2, -0.25)[0], 0, P(0, -0.25)[2], 0.8, false);
  tree(k, P(-0.98, 0.0)[0] + 0.1, 0, P(0, 0.0)[2] - 0.1, 0.8, false);
  golfLife(k, holes, null, r, hex(0x2f5d3a));
};

// ---- mini golf ---------------------------------------------------------------------------------

const FELT = hex(0x4fb04a), RED = hex(0xe2412f);

/** A mini-golf hole: an edged run of felt, straight from (x0, z0) to (x1, z1) or round a corner, its cup and little flag at the end. */
function lane(k: Kit, pts: Pt[], edge: RGB, felt = FELT, w = 0.2): void {
  for (let i = 1; i < pts.length; i++) {
    const [ax, az] = pts[i - 1], [bx, bz] = pts[i];
    k.box((ax + bx) / 2, 0, (az + bz) / 2, Math.abs(bx - ax) + w, 0.03, Math.abs(bz - az) + w, edge, felt);
  }
  const [ex, ez] = pts[pts.length - 1], [sx, sz] = pts[0];
  spot(k, ex, 0.032, ez, 0.02, DARK, 5);
  k.cyl(ex, 0.03, ez, 0.003, 0.1, WHITE, 3);
  k.box(ex + 0.02, 0.1, ez, 0.04, 0.025, 0.003, RED);
  k.box(sx, 0.03, sz, 0.06, 0.002, 0.06, hex(0x3a8a3a));
}

/** The kiosk at the gate, in the theme's colours. */
function kiosk(k: Kit, x: number, z: number, wall: RGB, roof: RGB, thatched = false): void {
  k.box(x, 0, z, 0.26, 0.22, 0.22, wall);
  if (thatched) k.hip(x, 0.22, z, 0.36, 0.14, 0.32, roof);
  else k.gable(x, 0.22, z, 0.3, 0.08, 0.26, roof, wall);
  k.box(x, 0.08, z + 0.112, 0.16, 0.08, 0.004, hex(0x3a3f45));
}

/** The Dutch windmill course: a big windmill with its sails turning over the lane through its door, tulip beds, a canal with a white lift bridge. */
const windmillGolf: Draw = (k, W, D, _b, r) => {
  const brick = hex(0xb5543f);
  // the canal across the back, and its bridge
  k.box(0, 0.003, -D / 2 + 0.14, W - 0.1, 0.004, 0.16, WATER);
  k.box(0.35, 0.03, -D / 2 + 0.14, 0.16, 0.02, 0.22, WHITE);
  for (const s of [-1, 1]) k.box(0.35 + s * 0.07, 0.05, -D / 2 + 0.14, 0.012, 0.12, 0.012, WHITE);
  lane(k, [[-0.75, -0.62], [0.65, -0.62]], brick);
  lane(k, [[0.72, -0.35], [0.72, 0.32], [0.35, 0.32]], brick);
  lane(k, [[-0.75, -0.3], [-0.75, 0.15], [0.1, 0.15]], brick);
  lane(k, [[-0.75, 0.48], [0.25, 0.48]], brick);
  lane(k, [[0.1, -0.15], [0.45, -0.15]], brick);
  // the windmill astride the second lane: a tapering octagon, the cap, the stage round it, the sails
  const mx = -0.2, mz = 0.15;
  k.band(mx, mz, 0.03, 0.2, 0.42, 0.13, 8, hex(0x5a5048));
  k.cyl(mx, 0.42, mz, 0.13, 0.02, hex(0x4a403a), 8);
  k.cone(mx, 0.44, mz, 0.15, 0.13, hex(0x3a3f45), 8);
  k.box(mx, 0.16, mz, 0.5, 0.012, 0.5, WOOD);
  k.box(mx, 0.03, mz + 0.16, 0.1, 0.12, 0.03, WHITE);
  k.spin(mx, 0.44, mz + 0.16, 'z', 0.9, (s) => {
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU, c = Math.cos(a), sn = Math.sin(a);
      s.bar([0, 0, 0], [c * 0.36, sn * 0.36, 0], 0.008, WOOD);
      s.quad([c * 0.08 - sn * 0.01, sn * 0.08 + c * 0.01, 0.006], [c * 0.36 - sn * 0.01, sn * 0.36 + c * 0.01, 0.006], [c * 0.36 - sn * 0.07, sn * 0.36 + c * 0.07, 0.006], [c * 0.08 - sn * 0.07, sn * 0.08 + c * 0.07, 0.006], hex(0xf4ece0), [0, 0, -0.1]);
    }
  });
  // tulips in rows of colour along the front and down the side
  const TULIPS = [0xe2412f, 0xf2c14e, 0xf49ab5, 0xf4f2ec, 0x8e5cc7];
  for (let i = 0; i < 4; i++) k.box(-0.55 + i * 0.25, 0, D / 2 - 0.2, 0.2, 0.045, 0.1, hex(0x3f8a3a), pick(r, TULIPS));
  for (let i = 0; i < 3; i++) k.box(W / 2 - 0.08, 0, -0.1 + i * 0.25, 0.08, 0.045, 0.2, hex(0x3f8a3a), pick(r, TULIPS));
  kiosk(k, W / 2 - 0.25, D / 2 - 0.2, brick, hex(0x3a3f45));
};

/** The pirate cove: a lagoon with a galleon in it, a skull rock with a fall out of its mouth, a treasure chest, palms and a thatched shack. */
const pirateGolf: Draw = (k, W, D, _b, r) => {
  const wood = hex(0x7a5a3a), sandy = hex(0xe6d29a);
  k.box(0, 0, 0, W - 0.04, 0.004, D - 0.04, sandy);
  fan(k, blob(0.1, -0.15, 0.45, 0.3, r, 12, 0.15), 0.008, hex(0x3fb6d0));
  lane(k, [[-0.8, -0.75], [0.5, -0.75]], wood, FELT);
  lane(k, [[0.78, -0.5], [0.78, 0.55]], wood, FELT);
  lane(k, [[-0.8, -0.5], [-0.8, 0.45], [-0.45, 0.45]], wood, FELT);
  lane(k, [[-0.4, 0.72], [0.45, 0.72]], wood, FELT);
  lane(k, [[0.0, 0.42], [0.5, 0.42]], wood, FELT);
  // the galleon in the lagoon: hull, deck house, two masts, sails, and the black flag
  const sx = 0.18, sz = -0.12, hull = hex(0x5a3a22);
  k.box(sx, 0.0, sz, 0.5, 0.1, 0.16, hull, hex(0xa07a50));
  k.box(sx - 0.2, 0.1, sz, 0.12, 0.08, 0.16, hull, hex(0xa07a50));
  const bow: P3 = [sx + 0.38, 0.1, sz], pl: P3 = [sx + 0.25, 0.1, sz - 0.08], pr: P3 = [sx + 0.25, 0.1, sz + 0.08], In: P3 = [sx + 0.28, 0.05, sz];
  k.tri(pl, pr, bow, hex(0xa07a50), In);
  k.quad([pl[0], 0, pl[2]], [bow[0], 0, bow[2]], bow, pl, hull, In);
  k.quad([bow[0], 0, bow[2]], [pr[0], 0, pr[2]], pr, bow, hull, In);
  for (const [mx, h] of [[sx - 0.05, 0.42], [sx + 0.13, 0.34]] as [number, number][]) {
    k.cyl(mx, 0.1, sz, 0.008, h, WOOD, 4);
    k.box(mx, 0.18, sz, 0.008, h * 0.45, 0.2, hex(0xf4ece0));
  }
  k.box(sx - 0.05, 0.47, sz + 0.04, 0.004, 0.05, 0.08, DARK);
  k.box(sx - 0.05, 0.49, sz + 0.03, 0.006, 0.015, 0.015, WHITE);
  // skull rock with the water falling from its jaw into the lagoon
  const kx = -0.35, kz = -0.32;
  k.dome(kx, 0, kz, 0.2, hex(0xe4e0d4), 8, 3);
  for (const s of [-1, 1]) k.box(kx + s * 0.07, 0.11, kz + 0.17, 0.05, 0.05, 0.02, DARK);
  k.box(kx, 0.03, kz + 0.19, 0.08, 0.04, 0.02, DARK);
  k.quad([kx - 0.03, 0.05, kz + 0.2], [kx + 0.03, 0.05, kz + 0.2], [kx + 0.035, 0.009, kz + 0.3], [kx - 0.035, 0.009, kz + 0.3], hex(0xdaf0f8), [kx, 0.03, kz]);
  // the treasure chest spilling gold, and the palms
  const tx = -0.2, tz = 0.3;
  k.box(tx, 0.03, tz, 0.14, 0.07, 0.09, wood, hex(0xe8c040));
  k.box(tx, 0.1, tz - 0.04, 0.14, 0.06, 0.012, wood);
  k.box(tx + 0.08, 0.03, tz + 0.05, 0.06, 0.012, 0.05, hex(0xf2d24a));
  palm(k, W / 2 - 0.26, -D / 2 + 0.24, 0.48);
  palm(k, -W / 2 + 0.26, D / 2 - 0.26, 0.42);
  kiosk(k, W / 2 - 0.25, D / 2 - 0.2, hex(0xb08858), hex(0xc8a060), true);
};

/** The dinosaur valley: a T. rex roaring over one lane, a long-neck over another, a volcano glowing at dusk, a nest of eggs, ferns. */
const dinoGolf: Draw = (k, W, D, _b, r) => {
  const rock = hex(0xa89a88);
  lane(k, [[-0.8, -0.78], [0.3, -0.78]], rock);
  lane(k, [[0.78, -0.35], [0.78, 0.5]], rock);
  lane(k, [[-0.8, -0.5], [-0.8, 0.6]], rock);
  lane(k, [[-0.55, 0.72], [0.4, 0.72], [0.4, 0.4]], rock);
  lane(k, [[-0.5, 0.25], [0.15, 0.25]], rock);
  lane(k, [[-0.5, -0.45], [0.2, -0.45]], rock);
  // the T. rex between two lanes, roaring over one of them
  const rx = -0.25, rz = 0.0, rex = hex(0x5a8a3a), belly = hex(0x8aaa5a);
  k.bar([rx - 0.06, 0.03, rz], [rx - 0.04, 0.18, rz], 0.022, rex);
  k.bar([rx + 0.06, 0.03, rz], [rx + 0.04, 0.18, rz], 0.022, rex);
  k.bar([rx, 0.2, rz - 0.08], [rx, 0.3, rz + 0.1], 0.06, rex);
  k.bar([rx, 0.2, rz - 0.08], [rx, 0.08, rz - 0.36], 0.035, rex);
  k.box(rx, 0.3, rz + 0.14, 0.09, 0.08, 0.14, rex, belly);
  k.box(rx, 0.28, rz + 0.18, 0.07, 0.02, 0.1, hex(0xc84a3a));
  for (const s of [-1, 1]) k.bar([rx + s * 0.05, 0.27, rz + 0.08], [rx + s * 0.06, 0.24, rz + 0.13], 0.008, rex);
  // the long-neck by the first lane
  const bx = 0.45, bz = -0.15, bron = hex(0x8a9aa8);
  k.box(bx, 0.1, bz, 0.16, 0.12, 0.3, bron);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(bx + sx * 0.05, 0.03, bz + sz * 0.1, 0.04, 0.08, 0.04, bron);
  k.bar([bx, 0.18, bz - 0.12], [bx, 0.48, bz - 0.3], 0.025, bron);
  k.box(bx, 0.48, bz - 0.33, 0.05, 0.04, 0.08, bron);
  k.bar([bx, 0.15, bz + 0.14], [bx, 0.05, bz + 0.38], 0.02, bron);
  // the volcano, lava glowing in its mouth after dark
  const vx = W / 2 - 0.28, vz = -D / 2 + 0.28;
  k.cone(vx, 0, vz, 0.24, 0.32, hex(0x6a5048), 7);
  k.glowBox(vx, 0.27, vz, 0.07, 0.04, 0.07, hex(0xf27a2a), [17, 30, 2.6], hex(0xff6a20));
  k.bar([vx - 0.04, 0.27, vz + 0.02], [vx - 0.12, 0.05, vz + 0.18], 0.015, hex(0xe25a2a));
  // a nest of eggs and ferns
  k.cyl(-0.05, 0.03, 0.48, 0.07, 0.02, hex(0x8a6a44), 6);
  for (let i = 0; i < 3; i++) k.box(-0.08 + i * 0.03, 0.05, 0.48, 0.022, 0.035, 0.022, hex(0xf2ead4));
  for (const [x, z] of [[-0.95, -0.95], [-0.6, -0.2], [0.6, 0.15], [-0.95, 0.85], [0.15, 0.5], [0.58, -0.45]]) k.cone(x, 0, z, 0.06, 0.1 + r() * 0.04, hex(0x3f7a34), 5);
  kiosk(k, W / 2 - 0.25, D / 2 - 0.2, hex(0x8a7a5a), hex(0x5a7a3a), true);
};

/** The castle course: a grey castle with four turrets, the lane through its gate over the drawbridge, a moat, pennants. */
const castleGolf: Draw = (k, W, D, _b, r) => {
  const stone = pick(r, STONE), grey = hex(0x9a968c), roof = pick(r, [0x2f4d7a, 0x8a3a32, 0x3f6a4a]);
  lane(k, [[-0.8, -0.78], [0.8, -0.78]], grey);
  lane(k, [[0.8, -0.5], [0.8, 0.55]], grey);
  lane(k, [[-0.8, -0.5], [-0.8, 0.5], [-0.45, 0.5]], grey);
  lane(k, [[-0.45, 0.75], [0.5, 0.75]], grey);
  // the moat, and the castle in it with the lane through the gate
  const cx = 0, cz = -0.05;
  k.box(cx, 0.003, cz, 1.0, 0.004, 0.74, WATER);
  lane(k, [[cx, 0.38], [cx, -0.35]], grey);
  for (const s of [-1, 1]) {
    k.box(cx + s * 0.24, 0, cz, 0.26, 0.24, 0.44, grey, stone);
    for (let i = 0; i < 3; i++) k.box(cx + s * 0.24 - 0.09 + i * 0.09, 0.24, cz + 0.2, 0.04, 0.04, 0.04, grey);
  }
  k.box(cx, 0.18, cz + 0.08, 0.16, 0.08, 0.28, grey, stone);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const tx = cx + sx * 0.36, tz = cz + sz * 0.22;
    k.cyl(tx, 0, tz, 0.07, 0.34, stone, 6);
    k.cone(tx, 0.34, tz, 0.09, 0.16, roof, 6);
  }
  k.box(cx, 0.031, cz + 0.33, 0.18, 0.012, 0.12, WOOD);
  for (const sx of [-1, 1]) k.box(cx + sx * 0.36 + 0.02, 0.5, cz - 0.22, 0.004, 0.08, 0.004, METAL);
  for (const sx of [-1, 1]) k.box(cx + sx * 0.36 + 0.05, 0.54, cz - 0.22, 0.06, 0.03, 0.003, RED);
  kiosk(k, W / 2 - 0.25, D / 2 - 0.2, stone, roof);
  for (let i = 0; i < 3; i++) k.cone(0.6, 0, -0.2 + i * 0.22, 0.06, 0.18, hex(0x3f7a3a), 6);
};

export const GOLF_VARIANTS: Partial<Record<BuildingKind, Draw[]>> = {
  golfCourse: [links, parkland, desert, mountain, range],
  miniGolf: [windmillGolf, pirateGolf, dinoGolf, castleGolf],
};
