export const propMaterial = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.9, metalness: 0 });

/**
 * Vertex GLSL: crops grow through the year without a rebuild. Grain comes up in spring, stands
 * tallest in summer and is cut to stubble in autumn; maize and sunflowers stand until autumn is
 * out; pumpkins swell until autumn and are gone by winter. Standing crops comb over in the wind.
 */
const CROP_VERT = /* glsl */ `
uniform float uSpring;
uniform float uAutumn;
uniform float uWinter;
uniform float uWxTime;
uniform float uWind;
uniform vec2 uWindDir;
void cropGrow(inout vec3 p, float leaf) {
  if (leaf < 4.5) return;
  float summer = max(0.0, 1.0 - uSpring - uAutumn - uWinter);
  if (leaf > 8.5) { p *= uSpring * 0.3 + summer * 0.75 + uAutumn; return; }
  float grain = uSpring * 0.45 + summer + uAutumn * 0.2 + uWinter * 0.06;
  float stalk = uSpring * 0.3 + summer + uAutumn * 0.85 + uWinter * 0.05;
  p.y *= leaf < 5.5 ? grain : leaf < 7.5 ? stalk : 1.0;
  if (leaf < 7.5 && uWind > 0.001) {
    vec2 at = p.xz;
#ifdef USE_INSTANCING
    at += instanceMatrix[3].xz;
#endif
    float ph = dot(at, vec2(0.61, 0.43)) + uWxTime * (1.5 + 2.5 * uWind);
    p.xz += uWindDir * (uWind * p.y * (0.12 + 0.08 * sin(ph)));
  }
}
`;

/** Fragment GLSL: a crop's own year, from green shoots through ripe to drab winter ground. */
const CROP_FRAG = /* glsl */ `
vec3 cropColour(vec3 c, float leaf, float lum) {
  float summer = max(0.0, 1.0 - uSpring - uAutumn - uWinter);
  vec3 green = vec3(0.42, 0.66, 0.26) * (0.8 + 0.4 * lum);
  if (leaf < 5.5) {
    c = mix(c, green, uSpring * 0.9);
    c = mix(c, vec3(0.84, 0.76, 0.52), uAutumn * 0.75);
  } else if (leaf < 6.5) {
    c = mix(c, vec3(0.74, 0.62, 0.36), uAutumn * 0.8);
  } else if (leaf < 7.5) {
    c = mix(c, green, uSpring * 0.9);
    c = mix(c, vec3(0.34, 0.24, 0.12), uAutumn * 0.75);
  } else if (leaf < 8.5) {
    c = mix(c, vec3(0.64, 0.62, 0.3), uAutumn * 0.6);
  } else {
    c = mix(c, green * 0.9, uSpring * 0.9 + summer * 0.55);
  }
  return mix(c, vec3(0.52, 0.47, 0.36), uWinter * 0.8);
}
`;

/**
 * Each broadleaf keeps its own year, chosen where it grows (treeYear) and packed into its instance
 * colour: the tint stays in the fraction below 2 and whole multiples of 2 carry a code, so a tree
 * costs nothing more to draw. Red holds the autumn hue (0 yellow .. 32 red), green is 1 + how hard
 * it turns (0..30) + 32 if it blossoms in spring, and blue is when in winter it drops its leaves
 * (0..31; 32 never). A green code of 0 is an ordinary prop with no year of its own.
 */
const YEAR_VERT = /* glsl */ `
attribute vec3 aHub;
varying vec3 vYear;
vec3 yearCode() {
#ifdef USE_INSTANCING_COLOR
  return floor(instanceColor.xyz * 0.5);
#else
  return vec3(0.0);
#endif
}
/** A tree dropping its leaves: its crowns shrink into their own middles, baring the boughs. */
void shedLeaves(inout vec3 p, float leaf, vec3 code) {
  if (code.g < 0.5 || leaf < 1.5 || leaf > 4.5 || uWinter <= 0.0) return;
  float bare = smoothstep(0.0, 1.0, clamp((uWinter - code.b / 32.0) * 5.0, 0.0, 1.0));
  p = mix(p, aHub, bare);
}
`;

/** Fragment GLSL: a broadleaf's own year, from blossom or fresh green to its own autumn fire. */
const YEAR_FRAG = /* glsl */ `
varying vec3 vYear;
vec3 treeYear(vec3 c, vec3 code, float lum) {
  float g = floor(code.g + 0.5) - 1.0;
  float blossom = step(31.5, g);
  float turn = clamp((g - blossom * 32.0) / 30.0, 0.0, 1.0);
  float hue = clamp(code.r / 32.0, 0.0, 1.0);
  float drops = step(code.b, 31.5);
  // fresh growth, or blossom, in spring
  c = mix(c, mix(c, vec3(0.60, 0.85, 0.36), 0.35), uSpring);
  float shade = clamp(lum / 0.42, 0.8, 1.2);
  vec3 pink = mix(vec3(1.0, 0.46, 0.68), vec3(1.0, 0.7, 0.84), hue);
  c = mix(c, pink * shade, uSpring * blossom);
  // autumn: yellow through orange to red, held while the leaves fall, gone when new ones come
  vec3 fire = hue < 0.5
    ? mix(vec3(1.0, 0.82, 0.04), vec3(1.0, 0.42, 0.02), hue * 2.0)
    : mix(vec3(1.0, 0.42, 0.02), vec3(0.95, 0.08, 0.06), hue * 2.0 - 1.0);
  float falling = drops * uWinter * (1.0 - step(0.0001, uSpring));
  c = mix(c, fire * shade, turn * clamp(uAutumn * 1.4 + falling, 0.0, 1.0));
  // a tree that keeps its leaves goes dull through the winter instead
  c = mix(c, mix(c, vec3(0.50, 0.50, 0.36), 0.55), uWinter * (1.0 - drops));
  return c;
}
`;

/**
 * Foliage turns with the year and takes a dusting of snow; trunks, rocks and fences do not. Which
 * is which comes from `aLeaf`: 2 for anything deciduous, 1 for needles and fronds, 0 for the rest,
 * 3 for a cherry, 4 for a birch and 5..9 for crops, which keep their own year (CROP_VERT, CROP_FRAG).
 * A tree placed with a year of its own (treeYear) follows that instead: YEAR_VERT, YEAR_FRAG.
 */
propMaterial.onBeforeCompile = (shader) => {
  seasonUniforms(shader);
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', `#include <common>\nattribute float aLeaf;\nvarying float vLeaf;\nvarying float vWorldY;\n${CROP_VERT}\n${YEAR_VERT}`)
    .replace('#include <color_vertex>', `vColor = color;
  vec3 yCode = yearCode();
#ifdef USE_INSTANCING_COLOR
  vColor *= instanceColor.xyz - yCode * 2.0;
#endif
  vYear = yCode;`)
    .replace('#include <begin_vertex>', `#include <begin_vertex>\n  vLeaf = aLeaf;\n  cropGrow(transformed, aLeaf);\n  shedLeaves(transformed, aLeaf, yCode);${WORLD_Y_VERT}`);
  shader.fragmentShader = shader.fragmentShader
    .replace('#include <common>', `#include <common>\nvarying float vLeaf;\nvarying float vWorldY;\n${SEASON_GLSL}\n${CROP_FRAG}\n${YEAR_FRAG}`)
    .replace('#include <color_fragment>', `#include <color_fragment>
  float leaf = step(0.5, vLeaf);
  float deciduous = step(1.5, vLeaf) * step(vLeaf, 4.5);
  float cherry = step(2.5, vLeaf) * step(vLeaf, 3.5);
  float birch = step(3.5, vLeaf) * step(vLeaf, 4.5);
  float lum = dot(diffuseColor.rgb, vec3(0.3, 0.59, 0.11));
  if (vYear.g > 0.5 && deciduous > 0.5) {
    diffuseColor.rgb = treeYear(diffuseColor.rgb, vYear, lum);
  } else {
    vec3 turned = turnSeason(diffuseColor.rgb, deciduous);
    // the cherry: its own year, from blossom to crimson
    vec3 blossom = diffuseColor.rgb;
    blossom = mix(blossom, vec3(1.0, 0.76, 0.86) * (0.8 + 0.5 * lum), uSpring * 0.92);
    blossom = mix(blossom, vec3(0.72, 0.13, 0.15) * (0.85 + 0.4 * lum), uAutumn * 0.88);
    blossom = mix(blossom, vec3(0.50, 0.43, 0.40), uWinter * 0.7);
    turned = mix(turned, vec3(0.96, 0.78, 0.22) * (0.75 + 0.5 * lum), uAutumn * 0.85 * birch);
    diffuseColor.rgb = mix(turned, blossom, cherry);
  }
  if (vLeaf > 4.5) diffuseColor.rgb = cropColour(diffuseColor.rgb, vLeaf, lum);
  diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.95, 0.97, 1.0), snowCover(vWorldY) * (0.35 + 0.45 * leaf));`);
  // whatever stands between the eye and the car is stippled away, as buildings and the ground are
  propXray(shader);
};

/**
 * The same look for the props drawn one mesh each (cabins, barns, lighthouses). A material drawn both
 * instanced and not has its program looked up again (all its parameters, its cache key) each time the
 * renderer passes from one kind of mesh to the other, and the opaque pass sorts by material and then
 * by distance, so they took turns all frame (Oct 2026 playtest). Same shader, so the same program.
 */
const propSoloMaterial = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.9, metalness: 0 });
propSoloMaterial.onBeforeCompile = propMaterial.onBeforeCompile;

/**
 * The shadow pass's depth for every instanced prop that has none of its own: without one, three draws
 * every caster with one shared depth material, and passing between instanced and single meshes in the
 * scene's order made it look the program up again each time (a steady share of the shadow pass).
 */
const propDepthMaterial = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking });

/**
 * The shadow a crop or a broadleaf casts changes with it: without this, winter's stubble would throw
 * summer's shadow, and a bare tree its lost crown's.
 */
const foliageDepthMaterial = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking });
foliageDepthMaterial.onBeforeCompile = (shader) => {
  seasonUniforms(shader);
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', `#include <common>\nattribute float aLeaf;\n${CROP_VERT}\n${YEAR_VERT}`)
    .replace('#include <begin_vertex>', '#include <begin_vertex>\n  cropGrow(transformed, aLeaf);\n  shedLeaves(transformed, aLeaf, yearCode());');
};

function roundTreeGeometry(): THREE.BufferGeometry {
  const trunk = paint(new THREE.CylinderGeometry(0.05, 0.075, 0.32, 6, 1, true).translate(0, 0.16, 0), 0x7a5a3a);
  const blob = paint(new THREE.DodecahedronGeometry(0.34, 0).scale(1, 1.15, 1).translate(0, 0.58, 0), 0x57a850, 2);
  const blob2 = paint(new THREE.DodecahedronGeometry(0.2, 0).translate(0.16, 0.42, 0.1), 0x63b25a, 2);
  return merge([trunk, ...boughs([0, 0.3, 0], 0.84, 0.26, 0, 0x7a5a3a), blob, blob2]);
}

