/** A palm: a leaning trunk of stacked segments under a crown of drooping fronds. */
function palmTreeGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const lean = 0.16;
  const H = 1.05;
  for (let k = 0; k < 5; k++) {
    const t = k / 5;
    const y = t * H;
    const bend = lean * t * t;
    // open-ended: each segment's caps sit inside the next, the ground or the crown
    parts.push(paint(new THREE.CylinderGeometry(0.052 - t * 0.016, 0.062 - t * 0.016, H / 5 + 0.02, 6, 1, true)
      .translate(bend, y + H / 10, 0), 0xa4845c));
  }
  const cx = lean, cy = H;
  parts.push(paint(new THREE.DodecahedronGeometry(0.07, 0).translate(cx, cy + 0.02, 0), 0x8f7048));
  for (let k = 0; k < 7; k++) {
    const a = (k / 7) * Math.PI * 2;
    const frond = new THREE.BoxGeometry(0.42, 0.028, 0.14);
    frond.translate(0.21, 0, 0);
    frond.rotateZ(-0.42);
    frond.rotateY(a);
    frond.translate(cx, cy, 0);
    parts.push(paint(frond, k % 2 ? 0x4f9e52 : 0x5cae59, 1));
  }
  // a couple of coconuts under the crown
  for (const a of [0.7, 2.6]) {
    parts.push(paint(new THREE.OctahedronGeometry(0.05, 0).translate(cx + Math.cos(a) * 0.07, cy - 0.06, Math.sin(a) * 0.07), 0x6b4f2e));
  }
  return merge(parts);
}
