  for (const x of [-0.17, 0.17]) for (const z of [-0.17, 0.17]) parts.push(paint(new THREE.BoxGeometry(0.02, 0.15, 0.02).translate(x, 0.88, z), 0x7a5532));
  for (const x of [-0.05, 0.05]) parts.push(paint(new THREE.BoxGeometry(0.015, 0.82, 0.015).rotateX(0.18).translate(x, 0.4, 0.24), 0x8a6238));
