const REGION_PROPS: (RegionProps | null)[] = [null, ...REGION_KINDS.map((k) => flattenRegion(REGIONS[k]))];
const tileRegion = (w: World, i: number): RegionProps | null => (w.regionW[i] ? REGION_PROPS[w.regionK[i]] ?? null : null);
const mix = (a: number, b: number, t: number) => a + (b - a) * t;

/**
 * Gentle per-tree colour: enough that a wood is not one flat green, not so much that the trunks
 * go strange. Multiplied over the part colours, so needles, leaves and bark all shift together.
 */
const TREE_TINTS: [number, number, number][] = [
  [1.00, 1.00, 1.00], [1.10, 1.01, 0.85], [0.87, 1.06, 0.91], [1.06, 0.95, 0.80],
  [0.91, 1.00, 1.07], [1.15, 0.99, 0.79], [0.85, 0.98, 0.86], [1.00, 1.09, 0.93],
  [1.07, 1.05, 0.88], [0.94, 1.03, 0.98],
];
/** Beach huts in a row, each its own pastel. */
const HUT_TINTS: [number, number, number][] = [
  [1.0, 0.78, 0.8], [0.72, 0.88, 1.0], [1.0, 0.95, 0.66], [0.74, 0.96, 0.8], [0.92, 0.8, 1.0], [1.0, 1.0, 1.0],
];

const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _p = new THREE.Vector3();
const _s = new THREE.Vector3();
const _c = new THREE.Color();
const _up = new THREE.Vector3(0, 1, 0);

const _x = new THREE.Vector3(1, 0, 0);
const _tip = new THREE.Quaternion();

/**
 * One prop's matrix. `fell` lays a fence over by that fraction of a quarter turn about its own
 * length (the sign is the side it falls to); a drystone wall doesn't topple, it slumps into a low
 * spill of stones instead, so it squashes rather than turns.
 */
export function placementMatrix(p: Placement, fell: number, out: THREE.Matrix4, stone = false): THREE.Matrix4 {
  _q.setFromAxisAngle(_up, p.yaw);
  _s.set(p.s, p.s, p.s);
  if (fell && stone) {
    _s.y *= 1 - 0.7 * Math.abs(fell);
    _s.z *= 1 + 0.8 * Math.abs(fell);
  } else if (fell) {
    _q.multiply(_tip.setFromAxisAngle(_x, fell * Math.PI / 2));
  }
  _p.set(p.x, p.y, p.z);
  return out.compose(_p, _q, _s);
}

/**
 * Props too low to throw a shadow worth its pass. Every instanced kind is a draw call of its own in
 * the shadow pass as well as the main one, and a field full of crops would double what it costs.
 */
const NO_SHADOW = new Set<string>(['tuft', 'wheat', 'sunflower', 'pumpkin', 'lavender', 'tulipRed', 'tulipYellow', 'tulipPink', 'tulipWhite', 'tulipPurple', 'rice']);

function makeInstanced(geom: THREE.BufferGeometry, list: Placement[], kind: string): THREE.InstancedMesh {
  propBound(geom);
  const mesh = new THREE.InstancedMesh(geom, propMaterial, list.length);
  for (let k = 0; k < list.length; k++) {
    const p = list[k];
    mesh.setMatrixAt(k, placementMatrix(p, p.fell ?? 0, _m, kind === 'drystoneWall' || kind === 'hedge'));
    const t = p.year ? packYear(p.tint, p.year) : p.tint;
    _c.setRGB(t[0], t[1], t[2]);
    mesh.setColorAt(k, _c);
  }
  mesh.instanceMatrix.needsUpdate = true;
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
  mesh.castShadow = !NO_SHADOW.has(kind);
  mesh.receiveShadow = true;
  mesh.customDepthMaterial = kind === 'maize' || BARE_KINDS.has(kind) ? foliageDepthMaterial : propDepthMaterial;
  mesh.name = kind;
  return mesh;
}

/** A shallow water tile beside dry land, where a Fens cypress may stand. */
function wadable(w: World, x: number, z: number, i: number): boolean {
  if (waterDepth(w, i) > 1) return false;
  for (let d = 0; d < 4; d++) {
    const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
    if (inB(nx, nz) && w.water[idx(nx, nz)] < 0) return true;
  }
  return false;
}

/**
 * How much of the old tree cover grows (3 Oct 2026, a third fewer trees): every scattered tree's
 * chance is cut to TREE_KEEP; in a wood the first tree on a tile keeps FOREST_FIRST of its chance and
 * a second one only FOREST_SECOND, so the densest woods (two trees on most tiles) thin the most —
 * an ordinary forest by about 36%, a region's thickest by about 45%.
 */
const TREE_KEEP = 2 / 3, FOREST_FIRST = 0.8, FOREST_SECOND = 0.35;

/**
 * What grows on a tile. Nothing grows on water, roads, tracks, fields, points of interest, steep
 * ground — or on a tile the bulldozer has cleared. Inside a biome the tree chance per ground class
 * blends toward the biome's own by the tile's region weight, and a Fens cypress may wade.
 */
export function propsOn(w: World, x: number, z: number): { trees: number; rocks: number; cacti: number } {
  const i = idx(x, z);
  const b = w.biome[i];
  let trees = 0, rocks = 0, cacti = 0;
  // nor under a bridge or causeway deck, whose road runs just over a low beach or bank
  if (w.cleared[i] || w.road[i] || w.deckAxis[i] || w.rail[i] & RAIL_KEEP_CLEAR || insideCurve(w, i)) return { trees, rocks, cacti };
  if (w.flags[i] & (Flag.Track | Flag.Field | Flag.Poi | Flag.Ramp)) return { trees, rocks, cacti };
  const rp = tileRegion(w, i);
  const wgt = rp ? w.regionW[i] / 255 : 0;
  if (b === Biome.Ocean || w.water[i] >= 0) {
    if (rp && rp.wading && w.water[i] >= 0 && !w.deckAxis[i] && w.portId[i] < 0 && hash2(x, z, 11) < 0.2 * TREE_KEEP * wgt && wadable(w, x, z, i)) trees = 1;
    return { trees, rocks, cacti };
  }
  const r0 = hash2(x, z, 11), r1 = hash2(x, z, 12);
  // a ski resort's woods between its runs (world/skiFields.ts planResort), close set, up steeper ground than a wood's
  if (w.feature[i] === Feature.Glade) return { trees: steepness(w, i) < 4 && r0 < 0.72 ? (r1 < 0.3 ? 2 : 1) : 0, rocks, cacti };
  if (steepness(w, i) >= 2) return { trees, rocks, cacti };
  // nothing grows on salt, ice, lava, basalt or a cave floor; badland rock carries only rocks
  const surf = w.surface[i];
  if (surf === Surface.Salt || surf === Surface.Ice || surf === Surface.Lava || surf === Surface.Cave || surf === Surface.Basalt || surf === Surface.Marsh) {
    return { trees, rocks, cacti };
  }
  if (surf === Surface.Rock) return { trees, rocks: r1 < 0.05 ? 1 : 0, cacti };
  if (surf === Surface.Sand && b === Biome.Desert) {
    // bare dunes, except for the palms round an oasis
    for (let dz = -2; dz <= 2; dz++) for (let dx = -2; dx <= 2; dx++) {
      if (inB(x + dx, z + dz) && w.water[idx(x + dx, z + dz)] >= 0) return { trees: r0 < 0.5 * TREE_KEEP ? 1 : 0, rocks, cacti };
    }
    return { trees, rocks, cacti };
  }
  const noCacti = rp && !rp.cacti ? 1 - wgt : 1;
  switch (b) {
    case Biome.Forest: {
      // a biome's forest density sets both the chance of a tree and of a second one
      const p = (rp ? mix(0.88, rp.forest, wgt) : 0.88) * FOREST_FIRST;
      const p2 = (rp ? mix(0.45, rp.forest, wgt) : 0.45) * FOREST_SECOND;
      trees = r0 < p ? (r1 < p2 ? 2 : 1) : 0;
      break;
    }
    case Biome.Hills: trees = r0 < (rp ? mix(0.14, rp.hills, wgt) : 0.14) * TREE_KEEP ? 1 : 0; break;
    case Biome.Plains: trees = r0 < (rp ? mix(0.035, rp.plains, wgt) : 0.035) * TREE_KEEP ? 1 : 0; break;
    case Biome.SeaCliff: trees = r0 < (rp ? mix(0.05, rp.hills, wgt) : 0.05) * TREE_KEEP ? 1 : 0; rocks = r1 < 0.03 ? 1 : 0; break;
    // palms line a warm shore; a cold one keeps its bare sand
    case Biome.Beach: {
      const p = w.temp[i] > 0.55 ? 0.09 : 0;
      trees = r0 < (rp ? mix(p, rp.beach, wgt) : p) * TREE_KEEP ? 1 : 0; rocks = r1 < 0.015 ? 1 : 0; break;
    }
    case Biome.Mountain: trees = w.elev[i] < 15 && r0 < (rp ? mix(0.28, rp.mountain, wgt) : 0.28) * TREE_KEEP ? 1 : 0; rocks = r1 < 0.07 ? 1 : 0; break;
    case Biome.Snow: rocks = r1 < 0.05 ? 1 : 0; break;
    case Biome.Desert: cacti = r0 < 0.045 * noCacti ? 1 : 0; rocks = r1 < 0.02 ? 1 : 0; break;
    case Biome.Canyon: rocks = r1 < 0.06 ? 1 : 0; cacti = r0 < 0.02 * noCacti ? 1 : 0; break;
    default: break;
  }
  return { trees, rocks, cacti };
}

/** A lake, river or stream within a tile of (x, z): somewhere a willow would lean over the water. */
function besideFreshWater(w: World, x: number, z: number): boolean {
  for (let dz = -1; dz <= 1; dz++) {
    for (let dx = -1; dx <= 1; dx++) {
      const nx = x + dx, nz = z + dz;
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if (w.flags[j] & (Flag.River | Flag.Stream) || (w.water[j] >= 0 && w.coastDist[j] > 0)) return true;
    }
  }
  return false;
}

/**
 * What grows on a tile outside the biomes: palms on a warm shore and stone pines on a cooler one,
 * spruce high and cold, pine and birch through the north, willows on the riverbanks, stone pine and
 * oak in the warm south, and oak, round and narrow broadleaf everywhere else.
 *
 * Woods grow in stands: a patch of six tiles square favours one or two kinds, so a wood changes as
 * you drive through it and a chunk still draws only two or three kinds (each one a draw call).
 * `r` is the tile's roll and `r2` the tree's.
 */
function treeKind(w: World, x: number, z: number, b: Biome, temp: number, r: number, r2: number): TreeKind {
  const stand = hash2(Math.floor(x / 6), Math.floor(z / 6), 101);
  if (b === Biome.Beach) return temp < 0.62 && stand < 0.55 ? 'stonePine' : 'palm';
  if (b === Biome.Desert) return 'palm';
  if (b === Biome.Snow) return 'spruce';
  if (b === Biome.Mountain) return r < 0.55 ? 'spruce' : 'pine';
  if (temp < 0.3) return stand < 0.3 && r < 0.7 ? 'birch' : r < 0.7 ? 'spruce' : 'pine';
  if (temp < 0.45) return stand < 0.4 ? (r < 0.65 ? 'birch' : 'pine') : r < 0.72 ? 'pine' : 'round';
  if (b !== Biome.Forest && besideFreshWater(w, x, z)) return r < 0.75 ? 'willow' : 'round';
  if (temp > 0.78 && b !== Biome.Forest && r2 < 0.22) return 'palm';
  if (temp > 0.6 && b !== Biome.Forest && stand < 0.45) return r < 0.55 ? 'stonePine' : 'oak';
  if (b === Biome.Forest) {
    if (stand < 0.35) return r < 0.65 ? 'oak' : 'round';
    if (stand < 0.5 && temp < 0.6) return r < 0.6 ? 'birch' : 'pine';
    return r < 0.22 ? 'pine' : r2 < 0.24 ? 'poplar' : 'round';
  }
  return r2 < 0.2 ? 'poplar' : r < 0.45 ? 'oak' : 'round';
}
/** A pick from a biome's tree mix by weight. */
function pickWeighted(kinds: TreeKind[], cum: Float32Array, sum: number, r: number): TreeKind {
  const t = r * sum;
  for (let k = 0; k < cum.length; k++) if (t < cum[k]) return kinds[k];
  return kinds[kinds.length - 1];
}

/** Scale for each tree shape, over the ordinary 0.8..1.3 spread. */
const TREE_SCALE: Partial<Record<Kind, number>> = { palm: 0.95, baobab: 1.1, canopy: 1.05, bamboo: 0.95, oak: 1.1, willow: 1.05 };

/** Wild flowers: gorse yellow most often, then white, purple and pink. */
const TUFT_TINTS: [number, number, number][] = [
  [1.0, 0.86, 0.22], [1.0, 0.86, 0.22], [1.0, 0.98, 0.94], [0.72, 0.52, 0.95], [1.0, 0.6, 0.78],
];

/** Dry, open, unbuilt ground where a biome's clutter may lie. */

/** Where and how a fence stands (or lies, once knocked down). */
export function fencePlacement(w: World, x: number, z: number, f: EdgeFence): Placement {
  const yaw = f.d === 0 || f.d === 2 ? Math.PI / 2 : 0;
  const drop = f.kind === 'fence' ? 0 : 0.02;
  const y = f.kind === 'snowFence' ? heightOnTile(w, x, z, f.px, f.pz) - drop : heightAt(w, f.px, f.pz) - drop;
  const fell = w.knocked.get(fenceKey(idx(x, z), f.d));
  return { x: f.px, y, z: f.pz, yaw, s: 1, tint: [1, 1, 1], fell };
}

/**
 * Trees, rocks, cactus and fences for one chunk as instanced meshes. Built per chunk so laying
 * a road only rebuilds the chunks it touches; road tiles are kept clear and fences open for them.
 * Inside a biome the tree mix, the ground clutter and the field walls come from its table.
 */
export function buildChunkProps(w: World, geos: PropGeometries, cx: number, cz: number): THREE.Group {
  const group = new THREE.Group();
  group.name = 'props';
  const lists = new Map<Kind, Placement[]>();
  const add = (kind: Kind, p: Placement) => {
    let list = lists.get(kind);
    if (!list) { list = []; lists.set(kind, list); }
    list.push(p);
  };
  const x0 = cx * CHUNK, z0 = cz * CHUNK;
  const regionK = w.regionK, regionW = w.regionW;
  // a rare grove's giants, and the tiles under their crowns where ordinary trees give way
  const giants = w.landmarks.length ? chunkGiants(w, x0, z0, CHUNK) : null;
  const shade = giants?.shade;
  // a snack stand now and then up a broad beach (beachStands): nothing else of the tile's grows or stands on it
  const stands = beachStands(w, x0, z0);

  for (let z = z0; z < z0 + CHUNK; z++) {
    for (let x = x0; x < x0 + CHUNK; x++) {
      const i = idx(x, z);
      if (stands?.has(i)) continue;
      const b = w.biome[i];
      const rp = regionW[i] ? REGION_PROPS[regionK[i]] : null;
      const wgt = rp ? regionW[i] / 255 : 0;
      if (rp) regionClutter(w, rp, wgt, x, z, i, add);
      const on = propsOn(w, x, z);
      const trees = shade?.has(i) ? 0 : on.trees, rocks = on.rocks, cacti = on.cacti;
      if (!trees && !rocks && !cacti) {
        // gorse and wild flowers on the open country outside the biomes
        if (wgt < 0.5 && (b === Biome.Plains || b === Biome.Hills) && hash2(x, z, 87) < 0.05 && clutterGround(w, i)) {
          const ra = hash2(x, z, 88), rb = hash2(x, z, 89);
          const px = x + 0.15 + ra * 0.7, pz = z + 0.15 + rb * 0.7;
          add('tuft', {
            x: px, y: heightOnTile(w, x, z, px, pz) - 0.02, z: pz, yaw: ra * 6.28, s: 1.3 + rb * 0.7,
            tint: TUFT_TINTS[Math.floor(hash2(Math.floor(x / 5), Math.floor(z / 5), 86) * TUFT_TINTS.length) % TUFT_TINTS.length],
          });
        }
        continue;
      }
      const r0 = hash2(x, z, 11), r1 = hash2(x, z, 12), r2 = hash2(x, z, 13), r3 = hash2(x, z, 14);
      const temp = w.temp[i];
      const wet = w.water[i] >= 0;
      for (let k = 0; k < trees; k++) {
        const ox = 0.2 + hash2(x, z, 20 + k) * 0.6, oz = 0.2 + hash2(x, z, 30 + k) * 0.6;
        const px = x + ox, pz = z + oz;
        let kind: TreeKind;
        if (wet) kind = 'cypress';
        else if (rp && rp.treeSum > 0 && hash2(x, z, 90 + k) < wgt) {
          const rk = hash2(x, z, 95 + k);
          kind = b === Biome.Beach && rp.palmSum > 0
            ? pickWeighted(rp.palmKinds, rp.palmCum, rp.palmSum, rk)
            : pickWeighted(rp.treeKinds, rp.treeCum, rp.treeSum, rk);
        } else kind = treeKind(w, x, z, b, temp, r2, hash2(x, z, 60 + k));
        const bright = 0.9 + hash2(x, z, 50 + k) * 0.22;
        const t = TREE_TINTS[Math.floor(hash2(x, z, 70 + k) * TREE_TINTS.length) % TREE_TINTS.length];
        add(kind, {
          x: px, y: heightOnTile(w, x, z, px, pz) - 0.02, z: pz,
          // the wind on the Moors blows one way, so its pines all lean together
          yaw: kind === 'windPine' ? 0.4 + r3 * 0.5 : r3 * Math.PI * 2,
          s: (0.8 + hash2(x, z, 40 + k) * 0.5) * (TREE_SCALE[kind] ?? 1),
          tint: [t[0] * bright, t[1] * bright, t[2] * bright],
          year: treeYear(x, z, k, kind, temp),
        });
      }
      if (rocks) {
        const px = x + 0.25 + r2 * 0.5, pz = z + 0.25 + r3 * 0.5;
        const g = 0.85 + r2 * 0.3;
        add('rock', { x: px, y: heightOnTile(w, x, z, px, pz) - 0.03, z: pz, yaw: r0 * 6, s: 0.6 + r1 * 0.9, tint: [g, g, g] });
      }
      if (cacti) {
        const px = x + 0.25 + r2 * 0.5, pz = z + 0.25 + r3 * 0.5;
        const g = 0.9 + r2 * 0.2;
        add('cactus', { x: px, y: heightOnTile(w, x, z, px, pz) - 0.02, z: pz, yaw: r0 * 6, s: 0.8 + r1 * 0.5, tint: [g, g, g] });
      }
    }
  }
  if (giants) {
    for (const t of giants.trees) {
      // seated on the lowest ground under its trunk, so a wide bole never floats off a slope
      const f = GROVE_SPECS[t.kind].foot * t.s;
      let y = heightOnTile(w, t.tx, t.tz, t.x, t.z);
      for (let k = 0; k < 4; k++) y = Math.min(y, heightAt(w, t.x + DIRS[k][0] * f, t.z + DIRS[k][1] * f));
      const bright = 0.94 + hash2(t.tx, t.tz, 7120) * 0.12;
      add(t.kind, {
        x: t.x, y: y - 0.03, z: t.z, yaw: t.yaw, s: t.s, tint: [bright, bright, bright],
        year: t.kind === 'greatOak' ? treeYear(t.tx, t.tz, 0, 'oak', w.temp[idx(t.tx, t.tz)])
          : t.kind === 'giantBaobab' ? treeYear(t.tx, t.tz, 0, 'baobab', w.temp[idx(t.tx, t.tz)]) : undefined,
      });
    }
  }

  // a great park's trees and planting (world/greatParks.ts), instanced with the country's own so they turn with it
  if (w.towns.length) {
    let k = 0;
    for (const p of chunkParkProps(w, x0, z0, CHUNK)) {
      const tx = Math.floor(p.x), tz = Math.floor(p.z);
      const tree = !(p.kind === 'tuft' || p.kind === 'rock' || p.kind === 'shrub' || p.kind === 'reeds' || p.kind === 'fern' || p.kind === 'heather' || p.kind === 'stoneLantern' || p.kind === 'lavender' || p.kind === 'sunflower');
      const bright = 0.92 + hash2(tx, tz, 7300 + (k & 7)) * 0.16;
      const t = p.tint ?? (tree ? TREE_TINTS[Math.floor(hash2(tx, tz, 7310 + (k & 7)) * TREE_TINTS.length) % TREE_TINTS.length] : [1, 1, 1]);
      add(p.kind as Kind, {
        x: p.x, y: heightOnTile(w, tx, tz, p.x, p.z) - (p.kind === 'rock' ? 0.03 : 0.02), z: p.z, yaw: p.yaw,
        s: p.s * (tree ? TREE_SCALE[p.kind as Kind] ?? 1 : 1),
        tint: p.tint ? t : [t[0] * bright, t[1] * bright, t[2] * bright],
        year: tree ? treeYear(tx, tz, k & 3, p.kind, w.temp[idx(tx, tz)]) : undefined,
      });
      k++;
    }
  }

  // the front gardens beside a diagonal road (world/diagonals.ts): shrubs, flowers and a small tree
  if (w.roads.length) {
    for (const y of chunkYards(w, cx, cz)) {
      for (const p of y.plants) {
        const tx = Math.floor(p.x), tz = Math.floor(p.z);
        const tree = p.kind !== 'shrub' && p.kind !== 'tuft';
        const bright = 0.92 + hash2(tx, tz, 7400) * 0.16;
        const t = p.tint ?? (tree ? TREE_TINTS[Math.floor(hash2(tx, tz, 7410) * TREE_TINTS.length) % TREE_TINTS.length] : [1, 1, 1]);
        add(p.kind as Kind, {
          x: p.x, y: heightOnTile(w, tx, tz, p.x, p.z) - 0.02, z: p.z, yaw: p.yaw,
          s: p.s * (tree ? TREE_SCALE[p.kind as Kind] ?? 1 : 1),
          tint: p.tint ? t : [t[0] * bright, t[1] * bright, t[2] * bright],
          year: tree ? treeYear(tx, tz, 0, p.kind, w.temp[idx(tx, tz)]) : undefined,
        });
      }
    }
  }

  // parasols dotted up the broad beaches, back from the waterline (three times as thick where the
  // beach is the point of the place), and the snack stands among them
  if (stands) {
    for (const [i, st] of stands) {
      const x = i % N, z = Math.floor(i / N);
      add(st.kind, { x: x + 0.5, y: heightOnTile(w, x, z, x + 0.5, z + 0.5) - 0.01, z: z + 0.5, yaw: st.yaw, s: 1, tint: [1, 1, 1] });
    }
  }
  for (let z = z0; z < z0 + CHUNK; z++) {
    for (let x = x0; x < x0 + CHUNK; x++) {
      const i = idx(x, z);
      if (stands?.has(i)) continue;
      if (w.feature[i] !== Feature.Beach || w.coastDist[i] < 2 || w.rail[i] & RAIL_KEEP_CLEAR) continue;
      // not on a road over the sand, under a deck, on a lot, or round a road's bend
      if (w.road[i] || w.deckAxis[i] || w.blocked[i] || w.cleared[i] || w.townId[i] >= 0 || w.portId[i] >= 0 || insideCurve(w, i)) continue;
      const rp = regionW[i] ? REGION_PROPS[regionK[i]] : null;
      const chance = rp ? 0.06 * mix(1, rp.parasolMul, regionW[i] / 255) : 0.06;
      if (hash2(x, z, 17) >= chance) continue;
      if (rp && rp.beachHut > 0 && hutAt(w, rp, x, z, i)) continue;
      const r0 = hash2(x, z, 11), r1 = hash2(x, z, 12), r2 = hash2(x, z, 13), r3 = hash2(x, z, 14);
      const px = x + 0.3 + r2 * 0.4, pz = z + 0.3 + r3 * 0.4;
      add('parasol', { x: px, y: heightOnTile(w, x, z, px, pz) - 0.01, z: pz, yaw: r0 * 6, s: 0.9 + r1 * 0.4, tint: [1, 1, 1] });
    }
  }

  // fences around field perimeters, drystone walls on the Moors, snow fences beside Icefield tracks;
  // one a car has knocked down lies where it fell
  for (let z = z0; z < z0 + CHUNK; z++) {
    for (let x = x0; x < x0 + CHUNK; x++) {
      fencesOn(w, x, z, (f) => add(f.kind, fencePlacement(w, x, z, f)));
    }
  }

  // a ranch's cattle grids, where a road crosses its fence line, and round bales dotted about its pasture
  const rf = ranchFences(w), rt = rf && ranchTiles(w);
  if (rf && rt) {
    for (const g of rf.grids) {
      const i = g >> 2, d = g & 3, x = i % N, z = (i - x) / N;
      if (x < x0 || z < z0 || x >= x0 + CHUNK || z >= z0 + CHUNK) continue;
      const px = x + 0.5 + DIRS[d][0] * 0.48, pz = z + 0.5 + DIRS[d][1] * 0.48;
      add('cattleGrid', { x: px, y: heightAt(w, px, pz) + 0.004, z: pz, yaw: d === 0 || d === 2 ? Math.PI / 2 : 0, s: 1, tint: [1, 1, 1] });
    }
    for (let z = z0; z < z0 + CHUNK; z++) {
      for (let x = x0; x < x0 + CHUNK; x++) {
        const i = idx(x, z);
        if (!rt.pasture[i] || w.road[i] || w.blocked[i] || w.water[i] >= 0 || hash2(x, z, 7501) >= 0.008) continue;
        const px = x + 0.3 + hash2(x, z, 7502) * 0.4, pz = z + 0.3 + hash2(x, z, 7503) * 0.4;
        add('hayBale', { x: px, y: heightOnTile(w, x, z, px, pz) - 0.01, z: pz, yaw: hash2(x, z, 7504) * 6.28, s: 1, tint: [1, 1, 1] });
      }
    }
  }

  // a corn maze's farm stand just outside its way in, facing the maze, with hay bales either side (0.7.0)
  for (const p of plansOf(w).values()) {
    if (p.gate === undefined || p.entry === undefined) continue;
    const gx = p.gate % N, gz = (p.gate - gx) / N;
    if (gx < x0 || gz < z0 || gx >= x0 + CHUNK || gz >= z0 + CHUNK) continue;
    if (w.road[p.gate] || w.blocked[p.gate] || w.water[p.gate] >= 0 || w.townId[p.gate] >= 0) continue;
    const ex = p.entry % N, ez = (p.entry - ex) / N, dx = ex - gx, dz = ez - gz;
    // beside the way in rather than across it, its counter turned to the maze
    const px = gx + 0.5 - dz * 0.28, pz = gz + 0.5 + dx * 0.28;
    add('farmStand', { x: px, y: heightAt(w, px, pz) - 0.01, z: pz, yaw: Math.atan2(dx, dz), s: 1, tint: [1, 1, 1] });
    for (const o of [0.3, -0.36]) {
      const hx = gx + 0.5 + dz * o + dx * 0.25, hz = gz + 0.5 - dx * o + dz * 0.25;
      add('hayBale', { x: hx, y: heightAt(w, hx, hz) - 0.01, z: hz, yaw: o * 3, s: 1.2, tint: [1, 1, 1] });
    }
    // 0.7.0: the lookout on the other side of the way in, and scarecrows standing in the maize (docs/models070-audit.md)
    if (NEXT_WORLD) {
      const lx = gx + 0.5 + dz * 0.32, lz = gz + 0.5 - dx * 0.32;
      add('mazeLookout', { x: lx, y: heightAt(w, lx, lz) - 0.01, z: lz, yaw: Math.atan2(dx, dz), s: 1, tint: [1, 1, 1] });
      for (const [f, o] of [[3, 2], [6, -3], [9, 1]] as const) {
        const sx = ex + 0.5 + dx * f + dz * o, sz = ez + 0.5 + dz * f - dx * o;
        if (!inB(Math.floor(sx), Math.floor(sz))) continue;
        add('scarecrow', { x: sx, y: heightAt(w, sx, sz) - 0.01, z: sz, yaw: hash2(gx, gz, f) * 6.28, s: 1, tint: [1, 1, 1] });
      }
    }
  }

  // scenery the player placed (world/scenery.ts), with the country's own: trees take a tint and a year as theirs do
  for (let k = 0; k < w.placed.length; k++) {
    const q = w.placed[k];
    const tx = Math.floor(q.x), tz = Math.floor(q.z);
    if (tx < x0 || tz < z0 || tx >= x0 + CHUNK || tz >= z0 + CHUNK) continue;
    const def = SCENERY_BY_ID.get(q.p);
    if (!def || !(q.p in geos)) continue;
    const yaw = (q.r & 7) * (Math.PI / 4);
    if (def.tree) {
      const bright = 0.92 + hash2(tx, tz, 7400 + (k & 7)) * 0.16;
      const t = TREE_TINTS[Math.floor(hash2(tx, tz, 7410 + (k & 7)) * TREE_TINTS.length) % TREE_TINTS.length];
      add(q.p as Kind, {
        x: q.x, y: heightOnTile(w, tx, tz, q.x, q.z) - 0.02, z: q.z, yaw: yaw + hash2(tx, tz, 7420 + (k & 7)) * 0.6,
        s: def.s * (0.92 + hash2(tx, tz, 7430 + (k & 7)) * 0.16), tint: [t[0] * bright, t[1] * bright, t[2] * bright],
        year: treeYear(tx, tz, k & 3, def.year ?? q.p, w.temp[idx(tx, tz)]),
      });
    } else {
      add(q.p as Kind, { x: q.x, y: heightOnTile(w, tx, tz, q.x, q.z) - (q.p === 'rock' ? 0.03 : 0.01), z: q.z, yaw, s: def.s, tint: [1, 1, 1] });
    }
  }
  for (const [kind, list] of lists) group.add(makeInstanced(geos[kind], list, kind));
  return group;
}

/**
 * The crops standing in one chunk's fields, one instance a tile. They are a group of their own so
 * the stream can hide them beyond a short distance, where the field's ground colour carries it.
 */
export function buildChunkCrops(w: World, geos: PropGeometries, cx: number, cz: number): THREE.Group | null {
  const lists = new Map<CropKind, Placement[]>();
  const x0 = cx * CHUNK, z0 = cz * CHUNK;
  for (let z = z0; z < z0 + CHUNK; z++) {
    for (let x = x0; x < x0 + CHUNK; x++) {
      const kind = cropAt(w, x, z);
      if (!kind) continue;
      const i = idx(x, z);
      let list = lists.get(kind);
      if (!list) { list = []; lists.set(kind, list); }
      // a patch ripens a shade apart from the next, and each tile a touch apart within it
      const g = (0.92 + hash2(Math.floor(x / 4), Math.floor(z / 4), 43) * 0.12) * (0.97 + hash2(x, z, 44) * 0.06);
      list.push({ x: x + 0.5, y: heightOnTile(w, x, z, x + 0.5, z + 0.5) - 0.01, z: z + 0.5, yaw: cropYaw(w.fieldId[i]), s: 1, tint: [g, g, g] });
    }
  }
  if (!lists.size) return null;
  const group = new THREE.Group();
  group.name = 'crops';
  for (const [kind, list] of lists) group.add(makeInstanced(geos[kind], list, kind));
  return group;
}

/**
 * Beach huts stand in rows: a stretch of broad beach is picked whole, and along it every third tile
 * at the same distance back from the sea gets one.
 */
function hutAt(w: World, rp: RegionProps, x: number, z: number, i: number): boolean {
  if (w.feature[i] !== Feature.Beach || w.coastDist[i] !== 2 || (x + 2 * z) % 3 !== 0) return false;
  if (w.road[i] || w.deckAxis[i] || w.cleared[i] || w.rail[i] & RAIL_KEEP_CLEAR || w.townId[i] >= 0 || w.blocked[i] || w.water[i] >= 0) return false;
  return hash2(Math.floor(x / 12), Math.floor(z / 12), 83) < rp.beachHut * 40 * (w.regionW[i] / 255);
}

/** The snack stands a broad beach has: one kind a stretch, a tile apart from the rest of the beach's furniture. */
const BEACH_STANDS = ['beachKiosk', 'beachShack', 'beachCart'] as const;
type BeachStand = typeof BEACH_STANDS[number];
/** A stretch of beach: a coarse cell of this many tiles a side has a stand on its sand or not. */
const STAND_CELL = 12;

/** Sand a stand may take: well up a broad beach, three to five tiles back from the sea, and nothing else on it. */
function standGround(w: World, x: number, z: number): boolean {
  if (!inB(x, z)) return false;
  const i = idx(x, z), d = w.coastDist[i];
  if (w.feature[i] !== Feature.Beach || d < 3 || d > 5 || w.water[i] >= 0 || w.rail[i] & RAIL_KEEP_CLEAR) return false;
  return !(w.road[i] || w.deckAxis[i] || w.blocked[i] || w.cleared[i] || w.townId[i] >= 0 || w.portId[i] >= 0 || insideCurve(w, i));
}

/**
 * The beach stands on a chunk's tiles, by tile: about half the stretches of broad beach have one, on whichever of
 * their sand rolls lowest, facing the sea with its queue in front.
 */
function beachStands(w: World, x0: number, z0: number): Map<number, { kind: BeachStand; yaw: number }> | null {
  let out: Map<number, { kind: BeachStand; yaw: number }> | null = null;
  for (let cz = Math.floor(z0 / STAND_CELL); cz <= Math.floor((z0 + CHUNK - 1) / STAND_CELL); cz++) {
    for (let cx = Math.floor(x0 / STAND_CELL); cx <= Math.floor((x0 + CHUNK - 1) / STAND_CELL); cx++) {
      if (hash2(cx, cz, 96) >= 0.55) continue;
      let bx = -1, bz = -1, br = 2;
      for (let z = cz * STAND_CELL; z < (cz + 1) * STAND_CELL; z++) {
        for (let x = cx * STAND_CELL; x < (cx + 1) * STAND_CELL; x++) {
          if (!standGround(w, x, z)) continue;
          const h = hash2(x, z, 97);
          if (h < br) { br = h; bx = x; bz = z; }
        }
      }
      if (bx < x0 || bz < z0 || bx >= x0 + CHUNK || bz >= z0 + CHUNK) continue;
      const i = idx(bx, bz);
      let yaw = 0;
      for (let d = 0; d < 4; d++) {
        const nx = bx + DIRS[d][0], nz = bz + DIRS[d][1];
        if (inB(nx, nz) && w.coastDist[idx(nx, nz)] < w.coastDist[i]) { yaw = Math.atan2(DIRS[d][0], DIRS[d][1]); break; }
      }
      (out ??= new Map()).set(i, { kind: BEACH_STANDS[Math.floor(hash2(cx, cz, 98) * BEACH_STANDS.length) % BEACH_STANDS.length], yaw });
    }
  }
  return out;
}

/** The biome's ground clutter on one tile: at most one thing, and never where the tile is in use. */
function regionClutter(
  w: World, rp: RegionProps, wgt: number, x: number, z: number, i: number,
  add: (kind: Kind, p: Placement) => void,
): void {
  const r = hash2(x, z, 81);
  const ra = hash2(x, z, 82), rb = hash2(x, z, 84);
  if (w.water[i] >= 0) {
    if (w.road[i] || w.deckAxis[i] || w.portId[i] >= 0 || w.cleared[i] || w.rail[i]) return;
    const surfY = w.water[i] * STEP;
    if (rp.iceberg > 0 && r < rp.iceberg * wgt && waterDepth(w, i) >= 2) {
      // out in open water: no land within three tiles
      for (let dz = -3; dz <= 3; dz += 3) for (let dx = -3; dx <= 3; dx += 3) {
        const nx = x + dx, nz = z + dz;
        if (inB(nx, nz) && w.water[idx(nx, nz)] < 0) return;
      }
      add('iceberg', { x: x + 0.3 + ra * 0.4, y: surfY - 0.06, z: z + 0.3 + rb * 0.4, yaw: ra * 6.28, s: 0.8 + rb, tint: [1, 1, 1] });
    } else if (rp.boat > 0 && r < rp.boat * wgt && waterDepth(w, i) <= 2) {
      // a cove: shallow water with land two tiles off at most
      let shore = false;
      for (let dz = -2; dz <= 2 && !shore; dz += 2) for (let dx = -2; dx <= 2; dx += 2) {
        const nx = x + dx, nz = z + dz;
        if (inB(nx, nz) && w.water[idx(nx, nz)] < 0) { shore = true; break; }
      }
      if (!shore) return;
      const tint: [number, number, number] = rb < 0.33 ? [1, 1, 1] : rb < 0.66 ? [1, 0.86, 0.8] : [0.86, 0.94, 1];
      add('mooredBoat', { x: x + 0.3 + ra * 0.4, y: surfY - 0.02, z: z + 0.3 + rb * 0.4, yaw: ra * 6.28, s: 0.9 + rb * 0.3, tint });
    }
    return;
  }
  if (!clutterGround(w, i)) return;
  // beside a track: stone lanterns in the Terraces, snow fences in the Icefield
  if (rp.lantern > 0 || rp.snowFence > 0) {
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (!inB(nx, nz) || !(w.flags[idx(nx, nz)] & Flag.Track)) continue;
      const px = x + 0.5 + DIRS[d][0] * 0.3, pz = z + 0.5 + DIRS[d][1] * 0.3;
      const along = DIRS[d][0] !== 0 ? Math.PI / 2 : 0;
      if (r < rp.lantern * wgt) add('stoneLantern', { x: px, y: heightOnTile(w, x, z, px, pz) - 0.01, z: pz, yaw: along, s: 1, tint: [1, 1, 1] });
      // a snow fence here is placed with the other fences (world/fences.ts), which cars can knock down
      return;
    }
  }
  if (rp.beachHut > 0 && hutAt(w, rp, x, z, i)) {
    // face the sea: toward whichever neighbour is nearer it
    let yaw = 0;
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (inB(nx, nz) && w.coastDist[idx(nx, nz)] < w.coastDist[i]) { yaw = Math.atan2(DIRS[d][0], DIRS[d][1]); break; }
    }
    const t = HUT_TINTS[Math.floor(hash2(x, z, 85) * HUT_TINTS.length) % HUT_TINTS.length];
    add('beachHut', { x: x + 0.5, y: heightOnTile(w, x, z, x + 0.5, z + 0.5) - 0.01, z: z + 0.5, yaw, s: 1, tint: t });
    return;
  }
  const px = x + 0.15 + ra * 0.7, pz = z + 0.15 + rb * 0.7;
  const g = 0.88 + rb * 0.24;
  if (rp.reeds > 0 && r < rp.reeds * wgt * 3) {
    // reeds only at the water's edge or in the marsh
    let edge = w.surface[i] === Surface.Marsh;
    for (let d = 0; d < 4 && !edge; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (inB(nx, nz) && w.water[idx(nx, nz)] >= 0) edge = true;
    }
    if (edge) add('reeds', { x: px, y: heightOnTile(w, x, z, px, pz) - 0.02, z: pz, yaw: ra * 6.28, s: 0.8 + ra * 0.5, tint: [g, g, g] });
    return;
  }
  if (w.surface[i] === Surface.Marsh || w.surface[i] === Surface.Rock) return;
  if (rp.haystack > 0 && r < rp.haystack * wgt) {
    const b = w.biome[i];
    if (b === Biome.Plains || b === Biome.Hills) add('haystack', { x: px, y: heightOnTile(w, x, z, px, pz) - 0.02, z: pz, yaw: ra * 6.28, s: 0.85 + rb * 0.35, tint: [g, g, g] });
    return;
  }
  const t = r / wgt;
  const cum = rp.scatterCum;
  for (let k = 0; k < cum.length; k++) {
    if (t < cum[k]) {
      const kind = rp.scatter[k];
      add(kind, { x: px, y: heightOnTile(w, x, z, px, pz) - (kind === 'termiteMound' ? 0.04 : 0.02), z: pz, yaw: ra * 6.28, s: 0.75 + rb * 0.6, tint: [g, g, g] });
      return;
    }
  }
}

/** Cabins, barns and the lighthouse as single meshes. */
export function buildBuildings(w: World, geos: PropGeometries): THREE.Group {
  const group = new THREE.Group();
  for (const p of w.pois) {
    const geo = p.type === 'cabin' ? geos.cabin : p.type === 'barn' ? geos.barn : geos.lighthouse;
    const mesh = new THREE.Mesh(geo, propSoloMaterial);
    const cx = p.x + 0.5, cz = p.z + 0.5;
    mesh.position.set(cx, heightAt(w, cx, cz) - 0.01, cz);
    mesh.rotation.y = p.yaw;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    group.add(mesh);
  }
  return group;
}
