import { hex, scale, type RGB } from '../world/biomes';
import { N, CHUNK, SEA, STEP, Biome, DIRS, RailBit, World, heightAt, idx, inB, type Landmark } from '../world/tiles';

/** A railway runs here (on the ground, overhead, or in its margin): no rock column or tree in the way. */
const onRail = (w: World, x: number, z: number): boolean => {
  const tx = Math.floor(x), tz = Math.floor(z);
  return inB(tx, tz) && (w.rail[idx(tx, tz)] & (RailBit.Track | RailBit.Deck | RailBit.Pad | RailBit.Loop | RailBit.Reserved)) !== 0;
};
import { hash2 } from '../world/rng';
import { fallInfo } from '../world/waterfalls';
import { Kit, TAU, WHITE, type P3 } from './buildings/kit';

/**
 * The props that make a landform a place: the glow in a volcano's crater and the ash over it, a
 * geyser's plume, a sea arch and its stacks, basalt columns, hoodoos, erratics, a cairn on a pass,
 * the roof of a cave, a natural bridge's deck, and the stilt-rooted mangroves. Drawn per chunk in
 * the same merged geometry as the buildings, with the same moving-parts group for the plumes.
 */

const ROCK = hex(0x8d8880), ROCK_DARK = hex(0x5e5a55), LICHEN = hex(0x9aa47a), LAVA_GLOW = hex(0xff7a2a), ASH = hex(0x8a8580);
const TRAVERTINE = hex(0xf1ece0), TRAV_ORANGE = hex(0xd99a5a), SPRING = hex(0x6fd8d8), STEAM = hex(0xeef2f4);
const BASALT = hex(0x4a4c50), BASALT_TOP = hex(0x62656a), BAD = [hex(0xc0603f), hex(0xde9a5a), hex(0xeedcb8), hex(0x9a8f86)];
const SPRAY = hex(0xf6fafc), DECK = hex(0x8d6d48), RAIL = hex(0x5a5f63);
const MANGROVE_ROOT = hex(0x6b5a44), MANGROVE_LEAF = hex(0x4f7a3e), MOSS = hex(0x7fe06a);

const inChunk = (x: number, z: number, x0: number, z0: number) => x >= x0 && x < x0 + CHUNK && z >= z0 && z < z0 + CHUNK;

/** A rough boulder: two squashed pyramids and a box, turned and tinted by hash. */
function boulder(k: Kit, x: number, y: number, z: number, s: number, col: RGB, seed: number): void {
  const a = hash2(seed, 3, 71) * 0.6 + 0.7;
  k.box(x, y - 0.05 * s, z, 0.34 * s, 0.22 * s, 0.28 * s * a, col);
  k.hip(x, y + 0.17 * s, z, 0.36 * s, 0.18 * s, 0.3 * s * a, scale(col, 1.06));
  k.hip(x + 0.05 * s, y + 0.1 * s, z - 0.04 * s, 0.26 * s, 0.14 * s, 0.34 * s, col);
  // a lichen cap on the shady side
  k.box(x - 0.08 * s, y + 0.15 * s, z + 0.05 * s, 0.12 * s, 0.03 * s, 0.12 * s, LICHEN);
}

export function drawLandforms(k: Kit, w: World, x0: number, z0: number): void {
  k.place(0, 0, 0, 0);
  for (const l of w.landmarks) {
    if (!inChunk(l.x, l.z, x0, z0) && l.kind !== 'erratics' && l.kind !== 'hoodoos' && l.kind !== 'basaltColumns' && l.kind !== 'seaArch') continue;
    switch (l.kind) {
      case 'volcano': volcano(k, w, l); break;
      case 'lavaField': lavaTube(k, w, l, x0, z0); break;
      case 'mountainPass': cairn(k, w, l); break;
      case 'cascade': mist(k, w, l); break;
      case 'waterfall': greatFall(k, w, l); break;
      case 'hotSprings': springs(k, w, l); break;
      case 'seaArch': arch(k, w, l, x0, z0); break;
      case 'basaltColumns': columns(k, w, l, x0, z0); break;
      case 'hoodoos': hoodoos(k, w, l, x0, z0); break;
      case 'erratics': erratics(k, w, l, x0, z0); break;
      case 'caveTunnel': cave(k, w, l); break;
      case 'naturalBridge': natural(k, w, l); break;
      case 'sinkhole': rail(k, w, l); break;
      default: break;
    }
  }
  // mangroves: stilt roots under a round crown, standing in the shallows
  for (let z = z0; z < z0 + CHUNK; z++) {
    for (let x = x0; x < x0 + CHUNK; x++) {
      const i = idx(x, z);
      if (w.biome[i] !== Biome.Mangrove || hash2(x, z, 811) > 0.8 || onRail(w, x, z)) continue;
      const px = x + 0.3 + hash2(x, z, 812) * 0.4, pz = z + 0.3 + hash2(x, z, 813) * 0.4;
      const y = w.water[i] >= 0 ? w.water[i] * STEP - 0.03 : heightAt(w, px, pz);
      const s = 0.8 + hash2(x, z, 814) * 0.5;
      for (let r = 0; r < 3; r++) {
        const a = (r / 3) * TAU + hash2(x, z, 815) * 2;
        k.bar([px + Math.cos(a) * 0.22 * s, y - 0.08, pz + Math.sin(a) * 0.22 * s], [px, y + 0.22 * s, pz], 0.018, MANGROVE_ROOT);
      }
      k.bar([px, y + 0.2 * s, pz], [px, y + 0.38 * s, pz], 0.025, MANGROVE_ROOT);
      k.dome(px, y + 0.34 * s, pz, 0.32 * s, MANGROVE_LEAF, 7, 2);
    }
  }
}

function volcano(k: Kit, w: World, l: Landmark): void {
  const glow = l.data?.[0] === 1;
  const y = heightAt(w, l.x, l.z);
  if (glow) {
    // the crater's lava, lit through the night
    k.glowBox(l.x, y + 0.02, l.z, 3.4, 0.05, 3.4, hex(0x5a2a18), [16.5, 30, 3.2], LAVA_GLOW);
    for (let v = 0; v < 5; v++) {
      const a = (v / 5) * TAU;
      k.glowBox(l.x + Math.cos(a) * 1.3, y + 0.04, l.z + Math.sin(a) * 1.3, 0.5, 0.06, 0.5, hex(0x7a3a20), [17, 30, 2.6], LAVA_GLOW);
    }
    // an ash plume, turning slowly as it rises
    k.spin(l.x, y + 1.2, l.z, 'y', 0.08, (s) => {
      for (let p = 0; p < 6; p++) s.dome(Math.sin(p) * 0.4, p * 0.7, Math.cos(p * 1.3) * 0.3, 1.1 + p * 0.25, scale(ASH, 1 + p * 0.03), 8, 3);
    });
  } else {
    // steam from the crater lake
    for (let p = 0; p < 3; p++) k.dome(l.x + p * 0.3, y + 0.6 + p * 0.5, l.z, 0.6 - p * 0.12, STEAM, 7, 2);
  }
}

function lavaTube(k: Kit, w: World, l: Landmark, x0: number, z0: number): void {
  if (!l.data || l.data.length < 4) return;
  const [ax, az, bx, bz] = l.data;
  const n = Math.ceil(Math.hypot(bx - ax, bz - az));
  // a rock roof over the first half of the trench
  for (let s = 0; s < n / 2; s++) {
    const px = ax + ((bx - ax) * s) / n + 0.5, pz = az + ((bz - az) * s) / n + 0.5;
    if (!inChunk(px, pz, x0, z0)) continue;
    const y = heightAt(w, px + 1.5, pz + 1.5);
    k.box(px + 0.5, y + 0.05, pz, 1.6, 0.18, 1.1, ROCK_DARK, hex(0x3a3634));
  }
}

function cairn(k: Kit, w: World, l: Landmark): void {
  const y = heightAt(w, l.x, l.z);
  for (let s = 0; s < 5; s++) k.box(l.x, y + s * 0.07, l.z, 0.22 - s * 0.035, 0.07, 0.2 - s * 0.03, scale(ROCK, 1 - s * 0.05));
  k.bar([l.x + 0.3, y, l.z], [l.x + 0.3, y + 0.5, l.z], 0.012, hex(0x5a3a28));
  k.box(l.x + 0.38, y + 0.38, l.z, 0.16, 0.1, 0.01, hex(0xe2412f));
}

function mist(k: Kit, w: World, l: Landmark): void {
  const y = (l.data?.[0] ?? SEA) * STEP + 1.1;
  for (let p = 0; p < 4; p++) k.dome(l.x + 0.5 + Math.sin(p * 2) * 0.4, y + p * 0.18, l.z + 0.5 + Math.cos(p * 2) * 0.4, 0.5 - p * 0.08, STEAM, 7, 2);
}

/**
 * A great waterfall's spray and its lookout (world/waterfalls.ts carves the falls themselves; the sheets
 * are drawn by mesher.buildFallChunk wherever its pools stand apart). Spray boils up off the plunge pool
 * along the whole lip, taller the further the water falls; a curtain throws a plume up over its chasm
 * that turns slowly, the smoke that thunders. A railed lookout stands on the nearest open ground.
 */
function greatFall(k: Kit, w: World, l: Landmark): void {
  const f = fallInfo(l);
  if (!f) return;
  const foot = f.W2 * STEP, h = f.drop * STEP;
  const px = -f.fz, pz = f.fx;
  const puff = (x: number, z: number, s: number, seed: number) => {
    const r = (0.32 + 0.22 * hash2(seed, 1, 31)) * s;
    // boiling up off the pool and hanging in the air part way up the face, where the light reaches it
    const lift = Math.min(h * 0.3, 1.6) * hash2(seed, 4, 31);
    k.dome(x, foot + 0.05, z, r, STEAM, 7, 2);
    k.dome(x + (hash2(seed, 2, 31) - 0.5) * 0.4, foot + r * 0.8 + lift, z + (hash2(seed, 3, 31) - 0.5) * 0.4, r * 0.75, SPRAY, 6, 2);
  };
  const s = Math.min(1.8, 0.7 + h * 0.08);
  if (f.style === 'horseshoe' || f.style === 'punchbowl' || f.style === 'plunge') {
    // round the plunge pool on the side the water comes in from
    const n = Math.max(4, Math.round(f.br * 2.2));
    for (let q = 0; q < n; q++) {
      const a = Math.atan2(-f.fz, -f.fx) + ((q / Math.max(1, n - 1)) - 0.5) * (f.style === 'horseshoe' ? 3.6 : 1.6);
      const rr = Math.max(0.6, f.br - 0.7);
      puff(f.bx + Math.cos(a) * rr, f.bz + Math.sin(a) * rr, s, q + 7);
    }
  } else {
    // along the foot of a straight lip
    const half = f.style === 'tiered' ? 0.8 : f.half;
    for (let c = -half; c <= half + 0.01; c += 1.3) {
      puff(f.lx + f.fx * 0.7 + px * c, f.lz + f.fz * 0.7 + pz * c, s, Math.round(c * 7) + 40);
    }
  }
  if (f.style === 'curtain' || (f.style === 'horseshoe' && f.drop >= 8) || f.style === 'cataract') {
    // the plume: mist rising off the lip above the rim, drifting about as it goes, never a wall in
    // front of the water
    const hs = f.style === 'horseshoe';
    const cx = hs ? f.bx - f.fx * f.br * 0.55 : f.lx + f.fx, cz = hs ? f.bz - f.fz * f.br * 0.55 : f.lz + f.fz;
    const span = hs ? f.br : f.half;
    k.spin(cx, foot, cz, 'y', 0.05, (sp) => {
      for (let p = 0; p < 5; p++) {
        const c = ((p / 4) - 0.5) * span * 1.2;
        sp.dome(px * c, h + 0.3 + (p % 3) * 0.45, pz * c, 0.42 + (p % 2) * 0.22 + h * 0.015, SPRAY, 7, 2);
      }
    });
  }
  lookout(k, w, f.bx, f.bz, f.look);
}

/** The railed lookout the generator kept beside a fall, facing it, unless a road or a building has since taken its tile. */
function lookout(k: Kit, w: World, bx: number, bz: number, best: number): void {
  if (best < 0 || best >= N * N || w.water[best] >= 0 || w.road[best] || w.blocked[best] || w.rail[best]) return;
  const tx = best % N, tz = (best - tx) / N, x = tx + 0.5, z = tz + 0.5;
  const y = heightAt(w, x, z);
  const yaw = Math.atan2(bx - x, bz - z);
  const ox = Math.sin(yaw), oz = Math.cos(yaw), rx = Math.cos(yaw), rz = -Math.sin(yaw);
  // the deck, its rail on the drop side, and a sign
  k.box(x, y, z, 0.8, 0.06, 0.8, DECK);
  for (const t of [-0.36, 0, 0.36]) {
    const qx = x + ox * 0.38 + rx * t, qz = z + oz * 0.38 + rz * t;
    k.bar([qx, y + 0.06, qz], [qx, y + 0.3, qz], 0.015, RAIL);
  }
  k.bar([x + ox * 0.38 - rx * 0.38, y + 0.3, z + oz * 0.38 - rz * 0.38], [x + ox * 0.38 + rx * 0.38, y + 0.3, z + oz * 0.38 + rz * 0.38], 0.016, RAIL);
  k.bar([x - ox * 0.3 + rx * 0.3, y + 0.06, z - oz * 0.3 + rz * 0.3], [x - ox * 0.3 + rx * 0.3, y + 0.42, z - oz * 0.3 + rz * 0.3], 0.018, RAIL);
  k.box(x - ox * 0.3 + rx * 0.3, y + 0.34, z - oz * 0.3 + rz * 0.3, 0.22, 0.12, 0.22, hex(0x3d6b4a));
  // a coin-op telescope at the rail
  k.bar([x + ox * 0.2, y + 0.06, z + oz * 0.2], [x + ox * 0.2, y + 0.24, z + oz * 0.2], 0.02, RAIL);
  k.bar([x + ox * 0.14, y + 0.25, z + oz * 0.14], [x + ox * 0.3, y + 0.29, z + oz * 0.3], 0.035, hex(0x2f3a44));
}

function springs(k: Kit, w: World, l: Landmark): void {
  const d = l.data ?? [];
  const geyser = d[0] === 1, seed = d[1] ?? 1, n = d[2] ?? 0;
  for (let p = 0; p < n; p++) {
    const px = d[3 + p * 3], pz = d[4 + p * 3], r = d[5 + p * 3];
    const y = heightAt(w, px, pz) + p * 0.02;
    // stepped travertine: a white rim, an orange apron, turquoise water
    k.cyl(px, y, pz, r + 0.12, 0.06, TRAV_ORANGE, 10);
    k.cyl(px, y + 0.02, pz, r + 0.05, 0.06, TRAVERTINE, 10);
    k.cyl(px, y + 0.05, pz, r, 0.035, SPRING, 10);
    for (let s = 0; s < 3; s++) k.dome(px + s * 0.08, y + 0.3 + s * 0.28, pz, 0.22 - s * 0.05, STEAM, 6, 2);
  }
  // the boardwalk
  const y0 = heightAt(w, l.x, l.z);
  k.box(l.x, y0 + 0.03, l.z + 1.2, 2.6, 0.04, 0.3, hex(0x8d6d48));
  if (geyser) {
    const y = heightAt(w, l.x, l.z);
    k.cyl(l.x, y, l.z, 0.3, 0.08, TRAVERTINE, 10);
    // the plume: a column that rises and falls on its own timer (see animateParts' geyser mode)
    k.spin(l.x, y + 0.08, l.z, 'y', seed % 1000, (s) => {
      for (let p = 0; p < 6; p++) s.cyl(0, p * 0.5, 0, 0.16 + p * 0.05, 0.5, p < 2 ? hex(0xdff4fb) : STEAM, 8);
      s.dome(0, 3, 0, 0.5, STEAM, 8, 2);
    }, 'geyser');
  }
}

function arch(k: Kit, w: World, l: Landmark, x0: number, z0: number): void {
  const d = l.data ?? [];
  const [ax, az, dir, top] = d;
  const [dx, dz] = DIRS[dir] ?? [1, 0];
  const cx = ax + 0.5 + dx * 1, cz = az + 0.5 + dz * 1;
  if (inChunk(cx, cz, x0, z0)) {
    const sea = SEA * STEP - 0.2, crown = top * STEP + 0.4;
    // two legs, one on the cliff and one out in the water, and the span over the sea between
    const px = -dz, pz = dx;
    for (const t of [-0.4, 1.4]) {
      const lx = ax + 0.5 + dx * t, lz = az + 0.5 + dz * t;
      k.box(lx, sea, lz, 0.55 + Math.abs(px) * 0.2, crown - sea, 0.55 + Math.abs(pz) * 0.2, ROCK);
    }
    const a: P3 = [ax + 0.5 + dx * -0.4, crown - 0.1, az + 0.5 + dz * -0.4], b: P3 = [ax + 0.5 + dx * 1.4, crown - 0.1, az + 0.5 + dz * 1.4];
    k.bar(a, b, 0.32, ROCK);
    k.box(cx, crown + 0.2, cz, 0.6 + Math.abs(dx) * 1.6, 0.14, 0.6 + Math.abs(dz) * 1.6, hex(0x7a9a5a));
  }
  // the stacks standing in the sea
  for (let s = 4; s + 2 < d.length; s += 3) {
    const sx = d[s], sz = d[s + 1], h = d[s + 2];
    if (!inChunk(sx, sz, x0, z0)) continue;
    const base = SEA * STEP - 0.4;
    k.box(sx, base, sz, 0.5, h, 0.45, ROCK);
    k.hip(sx, base + h, sz, 0.5, 0.2, 0.45, scale(ROCK, 1.08));
    k.box(sx - 0.1, base + h * 0.7, sz + 0.2, 0.08, 0.04, 0.08, WHITE);
  }
}

function columns(k: Kit, w: World, l: Landmark, x0: number, z0: number): void {
  const d = l.data ?? [];
  for (let s = 0; s + 2 < d.length; s += 3) {
    const tx = d[s], tz = d[s + 1], cd = d[s + 2];
    if (!inChunk(tx + 0.5, tz + 0.5, x0, z0) || onRail(w, tx + 0.5, tz + 0.5)) continue;
    // hexagonal prisms on a hex grid, stepping down toward the water
    for (let r = 0; r < 3; r++) {
      for (let c = 0; c < 3; c++) {
        const px = tx + 0.17 + c * 0.33 + (r % 2) * 0.16, pz = tz + 0.17 + r * 0.29;
        if (px > tx + 1) continue;
        const ground = heightAt(w, px, pz);
        const h = 0.15 + (2 - cd) * 0.12 + hash2(Math.floor(px * 7), Math.floor(pz * 7), 5) * 0.12;
        k.cyl(px, ground - 0.2, pz, 0.16, h + 0.2, BASALT, 6, BASALT_TOP);
      }
    }
  }
}

function hoodoos(k: Kit, w: World, l: Landmark, x0: number, z0: number): void {
  const d = l.data ?? [];
  for (let s = 0; s + 2 < d.length; s += 3) {
    const px = d[s], pz = d[s + 1], h = d[s + 2];
    if (!inChunk(px, pz, x0, z0) || onRail(w, px, pz)) continue;
    const y = heightAt(w, px, pz);
    const band = Math.floor(hash2(Math.floor(px * 3), Math.floor(pz * 3), 7) * 4);
    // a tapered column in banded rock, and the harder cap stone that keeps it standing
    const n = 4;
    for (let q = 0; q < n; q++) {
      const t0 = q / n, r = 0.16 * (1 - t0 * 0.45);
      k.cyl(px, y + t0 * h, pz, r, h / n + 0.01, BAD[(band + q) % 4], 7);
    }
    k.cyl(px, y + h, pz, 0.2, 0.08, hex(0x6d6259), 7);
  }
}

function erratics(k: Kit, w: World, l: Landmark, x0: number, z0: number): void {
  const d = l.data ?? [];
  for (let s = 0; s + 2 < d.length; s += 3) {
    const px = d[s], pz = d[s + 1], sc = d[s + 2];
    if (!inChunk(px, pz, x0, z0) || !inB(Math.floor(px), Math.floor(pz))) continue;
    if (w.cleared[idx(Math.floor(px), Math.floor(pz))] || onRail(w, px, pz)) continue;
    boulder(k, px, heightAt(w, px, pz), pz, sc * 0.9, scale(ROCK, 0.85 + hash2(Math.floor(px), Math.floor(pz), 9) * 0.25), Math.floor(px * 13 + pz));
  }
}

function cave(k: Kit, w: World, l: Landmark): void {
  const [ax, az, dir, len, roof] = l.data ?? [];
  const [dx, dz] = DIRS[dir] ?? [1, 0];
  const top = roof * STEP;
  for (let s = 1; s < len; s++) {
    const tx = ax + dx * s + 0.5, tz = az + dz * s + 0.5;
    const floor = heightAt(w, tx, tz);
    const ceil = Math.max(floor + 1.6, top - 0.2);
    // the roof over the passage, dark underneath, and stalactites hanging from it
    k.box(tx, ceil, tz, 1, Math.max(0.2, top - ceil + 0.3), 1, ROCK_DARK, ROCK);
    if (hash2(tx, tz, 21) < 0.6) {
      const sx = tx + (hash2(tx, tz, 22) - 0.5) * 0.6, sz = tz + (hash2(tx, tz, 23) - 0.5) * 0.6;
      k.tri([sx - 0.06, ceil, sz - 0.06], [sx + 0.06, ceil, sz - 0.06], [sx, ceil - 0.35, sz], hex(0x9a948a), [sx, ceil + 1, sz]);
      k.tri([sx - 0.06, ceil, sz + 0.06], [sx + 0.06, ceil, sz + 0.06], [sx, ceil - 0.35, sz], hex(0x9a948a), [sx, ceil + 1, sz]);
    }
  }
  // portals at both mouths, and moss glowing faintly at the far end
  for (const s of [0.5, len - 0.5]) {
    const tx = ax + dx * s + 0.5, tz = az + dz * s + 0.5;
    const floor = heightAt(w, tx, tz);
    const px = Math.abs(dz), pz = Math.abs(dx);
    for (const side of [-1, 1]) k.box(tx + px * side * 0.55, floor, tz + pz * side * 0.55, 0.25 + px * 0.1, 1.8, 0.25 + pz * 0.1, ROCK);
    k.box(tx, floor + 1.7, tz, 0.4 + px * 1.1, 0.3, 0.4 + pz * 1.1, ROCK);
  }
  const mx = ax + dx * (len - 1) + 0.5, mz = az + dz * (len - 1) + 0.5;
  k.glowBox(mx, heightAt(w, mx, mz) + 1.3, mz, 0.5, 0.04, 0.5, MOSS, [0, 30, 1.2], MOSS);
}

function natural(k: Kit, w: World, l: Landmark): void {
  const [sx, sz, dir, far, h] = l.data ?? [];
  const [dx, dz] = DIRS[dir] ?? [1, 0];
  for (let s = 1; s < far; s++) {
    const tx = sx + dx * s + 0.5, tz = sz + dz * s + 0.5;
    // a rock deck at rim height with a rough, sagging underside
    k.box(tx, h - 0.3, tz, 1.02, 0.3, 1.02, ROCK_DARK, hex(0xb08a60));
    const sag = Math.sin((s / far) * Math.PI) * 0.4;
    k.hip(tx, h - 0.3, tz, 1.0, -0.25 - sag, 1.0, ROCK_DARK);
  }
}

function rail(k: Kit, w: World, l: Landmark): void {
  const y = heightAt(w, l.x + l.r + 0.6, l.z);
  for (let a = 0; a < 10; a++) {
    const ang = (a / 10) * TAU, ang2 = ((a + 1) / 10) * TAU, r = l.r + 0.6;
    const p: P3 = [l.x + 0.5 + Math.cos(ang) * r, y + 0.22, l.z + 0.5 + Math.sin(ang) * r];
    const q: P3 = [l.x + 0.5 + Math.cos(ang2) * r, y + 0.22, l.z + 0.5 + Math.sin(ang2) * r];
    k.bar(p, q, 0.012, hex(0x6d6259));
    k.box(p[0], y, p[2], 0.03, 0.22, 0.03, hex(0x6d6259));
  }
}
