import * as THREE from 'three';
import { N, STEP, heightAt, idx, type World } from '../world/tiles';
import { ROAD_INFO } from '../world/roads';

/** Tiles of route the arrows run ahead of the vehicle. */
export const TRAIL = 36;

/** How a trail finds its way: a list of tile indices from (x, z) to (tx, tz) on w, local tiles, or null. */
type RouteFn = (w: World, x: number, z: number, tx: number, tz: number) => number[] | null;

/** A bend in the route sharper than this (radians) gets a turn arrow rather than a straight one. */
const TURN = 1.0;
/** Arrows laid closer than this (tiles) along the way are thinned: a 45° run's points come every 0.7. */
const SPACING = 0.8;

/**
 * The route's points to lay arrows at: tile middles, but a staircase (steps alternating between x and z,
 * which is how a route crosses a diagonal road or open ground at 45°) pulled onto the straight line it
 * zigzags along, so the arrows there point along the diagonal instead of turning left and right at every
 * step (the user, 21 Oct 2026). A lone corner keeps its turn.
 */
function smoothPath(path: number[]): { x: number; z: number }[] {
  const cx = (i: number) => (i % N) + 0.5, cz = (i: number) => Math.floor(i / N) + 0.5;
  const pts = path.map((i) => ({ x: cx(i), z: cz(i) }));
  if (path.length < 3) return pts;
  // the step into each tile: 0 along x, 1 along z, -1 for anything else
  const step = (k: number): number => {
    const dx = cx(path[k]) - cx(path[k - 1]), dz = cz(path[k]) - cz(path[k - 1]);
    return Math.abs(dx) === 1 && dz === 0 ? 0 : Math.abs(dz) === 1 && dx === 0 ? 1 : -1;
  };
  const out = pts.slice();
  for (let k = 1; k + 1 < path.length; k++) {
    const a = step(k), b = step(k + 1);
    if (a < 0 || b < 0 || a === b) continue;
    // a corner that is one of a run: the step before or after it turns back the other way
    const before = k >= 2 && step(k - 1) === b, after = k + 2 < path.length && step(k + 2) === a;
    if (!before && !after) continue;
    // onto the staircase's own centre line: the one through the midpoints of its steps (the tile middles
    // lie half a step either side of it), a quarter step on from the midpoint of the step in
    const sx = (pts[k].x - pts[k - 1].x) || (pts[k + 1].x - pts[k].x), sz = (pts[k].z - pts[k - 1].z) || (pts[k + 1].z - pts[k].z);
    out[k] = { x: (pts[k - 1].x + pts[k].x) / 2 + sx / 4, z: (pts[k - 1].z + pts[k].z) / 2 + sz / 4 };
  }
  return out;
}

/**
 * An arrow's outline in the shape's own plane, +y the way the route comes in: a chevron, or an arrow
 * that runs in from behind and bends a right angle to the right (+x) or, mirrored, to the left.
 */
function chevron(): THREE.Shape {
  const s = new THREE.Shape();
  s.moveTo(0, 0.2); s.lineTo(0.2, -0.04); s.lineTo(0.2, -0.16); s.lineTo(0, 0.06); s.lineTo(-0.2, -0.16); s.lineTo(-0.2, -0.04); s.closePath();
  return s;
}
function bend(side: 1 | -1): THREE.Shape {
  // a band t either side of a centreline that runs up x = 0, bends round a quarter circle of radius r
  // about (r, -r), and runs out along y = 0 to the head
  const t = 0.075, r = 0.2, arc = (rad: number, k: number): [number, number] => {
    const a = Math.PI - (k / 6) * (Math.PI / 2);
    return [r + Math.cos(a) * rad, -r + Math.sin(a) * rad];
  };
  const pts: [number, number][] = [[-t, -0.38]];
  for (let k = 0; k <= 6; k++) pts.push(arc(r + t, k));
  pts.push([r, 0.19], [0.4, 0], [r, -0.19]);
  for (let k = 6; k >= 0; k--) pts.push(arc(r - t, k));
  pts.push([t, -0.38]);
  const s = new THREE.Shape();
  pts.forEach(([x, y], k) => (k ? s.lineTo(x * side, y) : s.moveTo(x * side, y)));
  s.closePath();
  return s;
}

/** Lay a flat outline on the ground, pointing along +z (the shape's +y), +x of the shape to world -x. */
function flat(s: THREE.Shape): THREE.BufferGeometry {
  const g = new THREE.ShapeGeometry(s);
  g.rotateX(-Math.PI / 2);
  // the shape's +y has become -z: turn it to point along +z
  g.rotateY(Math.PI);
  return g;
}

/** Seconds between fresh route searches while the vehicle keeps to the way shown (a road laid meanwhile is picked up). */
const REROUTE_S = 2;
/** How far along the way shown the vehicle's tile is looked for: further off than this, it has left the way. */
const ON_PATH_LOOK = 8;

/**
 * Yellow arrows on the ground from the vehicle to where it is going: the way to go, pulsing ahead.
 * Where the route bends, the arrow on the corner tile bends with it, left or right; elsewhere a chevron
 * points on. The first drive's guide lays them along the roads; Auto-Pathing lays them along whatever
 * way suits the vehicle being driven.
 */
export class RouteArrows {
  /** Straight on, a turn to the left, a turn to the right. */
  private meshes: THREE.InstancedMesh[];
  private path: number[] | null = null;
  private key = '';
  private again = 0;
  /** The smoothed points of `path`, kept until the path changes. */
  private pts: { x: number; z: number }[] = [];
  private ptsOf: number[] | null = null;
  private t = 0;
  private m = new THREE.Matrix4();
  private q = new THREE.Quaternion();
  private p = new THREE.Vector3();
  private sc = new THREE.Vector3();
  private up = new THREE.Vector3(0, 1, 0);

  constructor(scene: THREE.Scene, private route: RouteFn, color = 0xffd24a) {
    // Pulled toward the camera harder than the paving and its markings are (render/roadMesh.ts), so the
    // arrows win the depth test on every road surface even from high up, where a few hundredths of a
    // tile is less than the depth buffer can tell apart.
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.92, depthWrite: false, side: THREE.DoubleSide,
      polygonOffset: true, polygonOffsetFactor: -4, polygonOffsetUnits: -8,
    });
    // the shape's +x lands on world -x, which is the right-hand side of +z: a bend to shape -x turns left
    this.meshes = [flat(chevron()), flat(bend(-1)), flat(bend(1))].map((g) => {
      const mesh = new THREE.InstancedMesh(g, mat, TRAIL);
      mesh.frustumCulled = false;
      mesh.renderOrder = 4;
      mesh.visible = false;
      mesh.count = 0;
      scene.add(mesh);
      return mesh;
    });
  }

  /**
   * Where the way runs above the ground's own height (a train's track on its embankment or viaduct, game/railWay.ts):
   * the height of the way at a local tile, or undefined for the ground's.
   */
  heightOf: ((i: number) => number | undefined) | null = null;

  hide(): void { for (const m of this.meshes) m.visible = false; }
  clear(): void { this.hide(); this.path = null; this.key = ''; }

  /** The way the arrows were last laid along (local tiles), or null. */
  get laid(): number[] | null { return this.path; }
  /** Are the arrows up now? */
  get shown(): boolean { return this.meshes.some((m) => m.visible); }

  /**
   * Lay the arrows, routing again only when needed: the goal moved, the vehicle left the way it was shown, or
   * every REROUTE_S to pick up a road laid meanwhile. Along the way, the tiles behind are just trimmed off (a
   * search was up to 90k tiles, and it ran on every tile the vehicle entered). Returns the route.
   */
  update(dt: number, w: World, me: { x: number; z: number }, to: { x: number; z: number }, ok: boolean, extra = ''): number[] | null {
    this.t += dt;
    if (!ok) { this.hide(); return null; }
    const lx = me.x - w.ox, lz = me.z - w.oz;
    const key = `${w.cx},${w.cz}|${Math.floor(to.x)},${Math.floor(to.z)}|${extra}`;
    this.again -= dt;
    const here = idx(Math.min(N - 1, Math.max(0, Math.floor(lx))), Math.min(N - 1, Math.max(0, Math.floor(lz))));
    // still on the way shown, near its start: the tiles passed are dropped
    // (no way found is kept too, until REROUTE_S: searching again every frame for a way that isn't there was the worst case)
    const same = key === this.key && this.again > 0;
    let on = -1;
    if (same && this.path) {
      for (let i = 0; i < Math.min(ON_PATH_LOOK, this.path.length); i++) if (this.path[i] === here) { on = i; break; }
    }
    if (on > 0) this.path = this.path!.slice(on);
    else if (!same || (this.path && on < 0)) {
      this.key = key;
      this.again = REROUTE_S;
      this.path = this.route(w, lx, lz, to.x - w.ox, to.z - w.oz);
    }
    const path = this.path;
    if (!path || path.length < 2) { this.hide(); return path; }
    const n = [0, 0, 0];
    let laid = 0;
    if (this.ptsOf !== path) { this.pts = smoothPath(path); this.ptsOf = path; }
    const pts = this.pts;
    let lastX = NaN, lastZ = NaN;
    for (let k = 1; k < path.length && laid < TRAIL; k++) {
      const ax = pts[k - 1].x, az = pts[k - 1].z, bx = pts[k].x, bz = pts[k].z;
      // one arrow at each point of the way, facing the way in from the last
      if (Math.hypot(bx - lx, bz - lz) < 0.6) continue;
      // a 45° run's points come closer than a tile apart: every other one is enough
      if (Math.hypot(bx - lastX, bz - lastZ) < SPACING) continue;
      const inA = Math.atan2(bx - ax, bz - az);
      // the way on from here: a sharp change is a corner, and the arrow turns with it
      let kind = 0;
      if (k + 1 < path.length) {
        const out = Math.atan2(pts[k + 1].x - bx, pts[k + 1].z - bz);
        const turn = Math.atan2(Math.sin(out - inA), Math.cos(out - inA));
        // a positive swing of the heading is a turn to the left (game/tutorial.ts turnOf)
        if (Math.abs(turn) > TURN && Math.abs(turn) < Math.PI - 0.3) kind = turn > 0 ? 1 : 2;
      }
      // over the paving of whatever road the tile under the point carries, which stands up to 0.05 proud of the ground
      const b = idx(Math.min(N - 1, Math.max(0, Math.floor(bx))), Math.min(N - 1, Math.max(0, Math.floor(bz))));
      const way = this.heightOf?.(b);
      const y = way !== undefined ? way : heightAt(w, bx, bz) + (ROAD_INFO[w.road[b]]?.lift ?? 0) + 0.04;
      lastX = bx; lastZ = bz;
      this.q.setFromAxisAngle(this.up, inA);
      // a pulse runs along the trail away from the vehicle
      const pulse = 0.85 + 0.35 * Math.max(0, Math.sin(this.t * 5 - k * 0.7));
      this.p.set(w.ox + bx, Math.max(y, w.water[b] >= 0 ? w.water[b] * STEP + 0.04 : y), w.oz + bz);
      this.sc.setScalar(kind ? pulse * 1.1 : pulse);
      this.m.compose(this.p, this.q, this.sc);
      this.meshes[kind].setMatrixAt(n[kind]++, this.m);
      laid++;
    }
    this.meshes.forEach((mesh, k) => {
      mesh.count = n[k];
      mesh.instanceMatrix.needsUpdate = true;
      mesh.visible = n[k] > 0;
    });
    return path;
  }
}
