import { ESTATE, priceOf } from './economy';
import { rankOf, type Driver } from './drivers';
import { RESALE, PARTS_RESALE, type Fleet } from './fleet';
import type { Firm, Firms } from './firms';
import type { Estate } from './estate';
import { YOU, type Carriage } from './carriage';
import type { FleetBrand } from './brand';

/**
 * Fleet metrics: the same handful of numbers kept for the player's fleet and for every rival firm the
 * player has met, so the Standings window (I, game/standings.ts) can rank them side by side. Net worth is
 * cash plus what the vehicles and the doors would fetch if sold today, on the same terms for everyone:
 * a vehicle at its resale share of list price and parts, a door at the estate's sale share of what was
 * paid for it. A firm that folds keeps its last numbers, marked as ceased, so the table remembers it.
 *
 * Each fleet's net worth is written down once a game day, for the sparkline; a firm out of memory
 * does nothing (docs/rivals.html), so its worth simply stands still until the player comes back.
 */

export type MetricKey =
  | 'worth' | 'cash' | 'fleetValue' | 'estateValue' | 'week' | 'perUnit' | 'lifetime'
  | 'deliveries' | 'units' | 'hqSlots' | 'drivers' | 'aces' | 'doors' | 'held' | 'contested' | 'strong' | 'gems' | 'towed';

export interface MetricDef {
  key: MetricKey;
  label: string;
  /** What it counts, for the row's tooltip. */
  hint: string;
  money: boolean;
  /** Lower is better. */
  low?: boolean;
}

export const METRICS: MetricDef[] = [
  { key: 'worth', label: 'Net worth', hint: 'Cash, plus what the vehicles and doors would fetch if sold today', money: true },
  { key: 'cash', label: 'Cash', hint: 'Money in the bank', money: true },
  { key: 'fleetValue', label: 'Vehicle value', hint: 'What every vehicle would sell for, with its parts', money: true },
  { key: 'estateValue', label: 'Property value', hint: 'What every door held would sell for', money: true },
  { key: 'week', label: 'Takings, 7 days', hint: 'Money taken in over the last seven game days, today included', money: true },
  { key: 'perUnit', label: 'Per vehicle, 7 days', hint: 'The last seven days’ takings for each vehicle owned', money: true },
  { key: 'lifetime', label: 'Lifetime takings', hint: 'Everything taken in since the fleet was met (for you, since the game began)', money: true },
  { key: 'deliveries', label: 'Deliveries', hint: 'Loads delivered, all time', money: false },
  { key: 'units', label: 'Vehicles', hint: 'Vehicles owned', money: false },
  { key: 'hqSlots', label: 'HQ slots', hint: 'Vehicles the HQ building runs: the grander the address, the more (docs/hq.html)', money: false },
  { key: 'drivers', label: 'Drivers', hint: 'Drivers on the books', money: false },
  { key: 'aces', label: 'Aces', hint: 'Drivers ranked ace', money: false },
  { key: 'doors', label: 'Properties', hint: 'Doors held', money: false },
  { key: 'held', label: 'Territory', hint: 'Towns held as territory: 35% of their trade and 1.25× the next fleet’s (docs/standing.html)', money: false },
  { key: 'strong', label: 'Strong territory', hint: 'Towns held that also own over 5% of the town’s property, and 1.25× the next fleet’s', money: false },
  { key: 'contested', label: 'Contested', hint: 'Towns held where another fleet owns more of the property: they pay no ◆', money: false },
  { key: 'gems', label: '◆ a day', hint: 'Diamonds a game day the towns held would pay', money: false },
  { key: 'towed', label: 'Tow bills', hint: 'Everything spent on tows, all time (lower is better)', money: true, low: true },
];

type Values = Record<MetricKey, number>;

/** One fleet's line in the table: who it is, its numbers now, and its net worth by day, newest first. */
export interface Book {
  id: string;
  you: boolean;
  name: string;
  livery: [number, number];
  logo: string;
  /** The game day it was first counted, and the day it ceased trading (null while it trades). */
  met: number;
  gone: number | null;
  v: Values;
  hist: number[];
  /** The game day `hist[0]` is for. */
  d0: number;
}

/** Rival firms' books an online save keeps beyond those near home: the most valuable still trading. */
const BOOKS_KEPT = 60;

export interface MetricsSave {
  books: Omit<Book, 'you'>[];
  /** The player's takings by day, newest first, from day `tD0`, and the lifetime figure at the start of it. */
  takings: number[]; tD0: number; lifeAt: number;
  /** Loads delivered by the whole fleet, by cargo kind name (the fleet card's "moves most", docs/social.html). Older saves start empty. */
  goods?: Record<string, number>;
  /** Units of culture brought home, by style (the culture boards, docs/social.html phase 4). Older saves start empty. */
  culture?: Record<string, number>;
  /** Loads delivered and dollars earned in each vehicle model, the whole fleet's (the vehicle boards, 5 Nov 2026). Older saves start empty. */
  inModel?: Record<string, number>;
  earnedIn?: Record<string, number>;
}

interface MetricsHost {
  day(): number;
  cash(): number;
  /** Everything the player has ever taken in. */
  lifetime(): number;
  /** Loads the player has delivered themselves. */
  delivered(): number;
  brand(): FleetBrand | null;
}

export const YOU_ID = 'you';
/** Days of net worth kept per fleet. */
const HIST = 30;
/** Seconds between samples while playing: the numbers only matter to the day. */
const EVERY = 1;

const r10 = (v: number): number => Math.round(v / 10) * 10;
const acesOf = (ds: Driver[]): number => ds.filter((d) => rankOf(d) === 'ace').length;
/** A unit's resale, on the player's terms (Fleet.resale): list price and parts. */
const resale = (model: string, spent: number): number => r10(priceOf(model) * RESALE + spent * PARTS_RESALE);
const doorValue = (paid: number): number => r10(paid * ESTATE.sell);

/** Where a fleet stands on one metric among the fleets still trading: 1 is best, ties share a place. */
export function placeOf(books: Book[], b: Book, m: MetricDef): number {
  const x = b.v[m.key];
  return 1 + books.filter((o) => o.gone === null && o !== b && (m.low ? o.v[m.key] < x : o.v[m.key] > x)).length;
}

export class FleetMetrics {
  private books = new Map<string, Book>();
  private takings: number[] = [];
  private tD0 = -1;
  private lifeAt = 0;
  private t = 0;
  /** Loads delivered by the fleet, by cargo kind name; units of culture brought home, by style. */
  private goods: Record<string, number> = {};
  private cultureUnits: Record<string, number> = {};
  /** Loads delivered, and dollars to the fleet, in each vehicle model: yours at the wheel and your drivers' (the vehicle boards). */
  private inModel: Record<string, number> = {};
  private earnedIn: Record<string, number> = {};

  /** Who holds each town as territory (docs/territory.html), set by main. */
  territory: { dailyOf(who: string): { perDay: number; towns: number; strong: number; contested: number } } | null = null;

  constructor(private fleet: Fleet, private firms: Firms, private estate: Estate, private carriage: Carriage, private host: MetricsHost) {}

  private held(who: string): { held: number; strong: number; contested: number; gems: number } {
    const d = this.territory?.dailyOf(who);
    return { held: d?.towns ?? 0, strong: d?.strong ?? 0, contested: d?.contested ?? 0, gems: d?.perDay ?? 0 };
  }

  /** A load delivered, by you or a driver: counted by its kind for the card's "moves most". */
  delivered(kind: string): void { this.goods[kind] = (this.goods[kind] ?? 0) + 1; }

  /** Units of a culture brought home (the culture boards). */
  cultured(style: string, units: number): void { if (units > 0) this.cultureUnits[style] = (this.cultureUnits[style] ?? 0) + units; }

  /** A load delivered in a model, and what it paid the fleet (the vehicle boards: most loads and most earned in each model). */
  deliveredIn(model: string, earned: number): void {
    this.inModel[model] = (this.inModel[model] ?? 0) + 1;
    if (earned > 0) this.earnedIn[model] = (this.earnedIn[model] ?? 0) + earned;
  }
  allInModel(): Record<string, number> { return { ...this.inModel }; }
  allEarnedIn(): Record<string, number> { return Object.fromEntries(Object.entries(this.earnedIn).map(([k, v]) => [k, Math.round(v)])); }

  /** Every kind's loads, and every culture's units, as the save line sends them for the cargo and culture boards. */
  allGoods(): Record<string, number> { return { ...this.goods }; }
  allCulture(): Record<string, number> { return { ...this.cultureUnits }; }

  /** The kinds moved most, [name, loads], most first. */
  topGoods(n = 8): [string, number][] { return Object.entries(this.goods).sort((a, b) => b[1] - a[1]).slice(0, n); }

  /** Called every frame; samples every fleet once a second. */
  update(dt: number): void {
    this.t -= dt;
    if (this.t > 0) return;
    this.t = EVERY;
    this.sample();
  }

  /** Every fleet counted, the player first, then by net worth; ceased firms last. */
  list(): Book[] {
    this.sample();
    return [...this.books.values()].sort((a, b) => Number(b.you) - Number(a.you) || Number(a.gone !== null) - Number(b.gone !== null) || b.v.worth - a.v.worth);
  }

  you(): Book { this.sample(); return this.books.get(YOU_ID)!; }

  // ---- sampling ----

  private sample(): void {
    const day = this.host.day();
    this.rollTakings(day);
    this.stamp(YOU_ID, true, this.brandName(), this.brandLivery(), this.host.brand()?.logo ?? '', this.playerValues(day), day);
    const live = new Set<string>([YOU_ID]);
    for (const f of this.firms.list()) {
      const id = `${f.id}@${f.epoch}`;
      live.add(id);
      this.stamp(id, false, f.name, f.livery, f.logo, this.firmValues(f, day), day);
    }
    // a firm met before that is no longer trading: its last numbers stay, marked with the day it went
    for (const b of this.books.values()) if (!live.has(b.id) && b.gone === null) b.gone = day;
  }

  private brandName(): string { return this.host.brand()?.name ?? 'Your fleet'; }
  private brandLivery(): [number, number] { const b = this.host.brand(); return b ? [b.primary, b.accent] : [0xe2412f, 0xffffff]; }

  private stamp(id: string, you: boolean, name: string, livery: [number, number], logo: string, v: Values, day: number): void {
    let b = this.books.get(id);
    if (!b) {
      b = { id, you, name, livery, logo, met: day, gone: null, v, hist: [v.worth], d0: day };
      this.books.set(id, b);
      return;
    }
    b.name = name; b.livery = livery; b.logo = logo; b.v = v; b.gone = null;
    if (day > b.d0) {
      // the days between stood at yesterday's figure: nothing happens to a firm out of memory
      const last = b.hist[0] ?? v.worth;
      for (let k = 0; k < Math.min(HIST, day - b.d0); k++) b.hist.unshift(last);
      b.hist.length = Math.min(b.hist.length, HIST);
      b.d0 = day;
    }
    b.hist[0] = v.worth;
  }

  /** The player's takings by day: what the lifetime figure has grown by since each day began. */
  private rollTakings(day: number): void {
    const life = this.host.lifetime();
    if (this.tD0 < 0 || !this.takings.length) { this.tD0 = day; this.lifeAt = life; this.takings = [0]; }
    if (day > this.tD0) {
      this.takings[0] = life - this.lifeAt;
      for (let k = 0; k < Math.min(14, day - this.tD0); k++) this.takings.unshift(0);
      this.takings.length = Math.min(this.takings.length, 14);
      this.tD0 = day;
      this.lifeAt = life;
    }
    this.takings[0] = Math.max(0, life - this.lifeAt);
  }

  private playerValues(_day: number): Values {
    const f = this.fleet;
    const cash = this.host.cash();
    const fleetValue = f.units.reduce((s, u) => s + f.resale(u), 0);
    let estateValue = 0;
    for (const d of this.estate.deeds.values()) estateValue += doorValue(d.paid);
    const week = this.takings.slice(0, 7).reduce((s, v) => s + v, 0);
    const units = f.units.length;
    return {
      worth: Math.round(cash + fleetValue + estateValue), cash: Math.round(cash), fleetValue, estateValue,
      week: Math.round(week), perUnit: units ? Math.round(week / units) : 0, lifetime: Math.round(this.host.lifetime()),
      deliveries: this.host.delivered() + f.units.reduce((s, u) => s + u.log.deliveries, 0),
      units, hqSlots: f.slots, drivers: f.drivers.length, aces: acesOf(f.drivers), doors: this.estate.deeds.size,
      ...this.held(YOU), towed: Math.round(f.towed),
    };
  }

  private firmValues(f: Firm, day: number): Values {
    const fleetValue = f.units.reduce((s, u) => s + resale(u.model, u.parts.spent ?? 0), 0);
    let estateValue = 0;
    for (const d of f.deeds.values()) estateValue += doorValue(d.paid);
    // its fourteen days start at day d0, which stands still while it is out of memory
    const shift = Math.max(0, day - f.d0);
    const week = f.days.slice(0, Math.max(0, 7 - shift)).reduce((s, v) => s + v, 0);
    const units = f.units.length;
    return {
      worth: Math.round(f.cash + fleetValue + estateValue), cash: Math.round(f.cash), fleetValue, estateValue,
      week: Math.round(week), perUnit: units ? Math.round(week / units) : 0, lifetime: Math.round(f.earned),
      deliveries: f.deliveries, units, hqSlots: f.hq.slots, drivers: units, aces: acesOf(f.units.map((u) => u.driver)), doors: f.deeds.size,
      ...this.held(f.id), towed: Math.round(f.towed),
    };
  }

  // ---- the save ----

  /**
   * With `near` (an online save): a rival firm's book is kept while its home is near, and otherwise only the
   * BOOKS_KEPT worth most and still trading; a firm met again is counted afresh. One for every firm of every county
   * a wide-roaming career had loaded was most of a 2 MB save (mickle, 28 Oct 2026).
   */
  toSave(near?: (cx: number, cz: number) => boolean): MetricsSave {
    let books = [...this.books.values()];
    if (near) {
      const homeOf = (id: string) => /^(-?\d+),(-?\d+)\//.exec(id);
      const keep = (b: Book) => { const m = homeOf(b.id); return b.you || !m || near(Number(m[1]), Number(m[2])); };
      const rest = books.filter((b) => !keep(b) && b.gone === null).sort((a, b) => b.v.worth - a.v.worth).slice(0, BOOKS_KEPT);
      books = [...books.filter(keep), ...rest];
    }
    return {
      books: books.map(({ you: _y, ...b }) => ({ ...b, hist: b.hist.map(Math.round) })),
      takings: this.takings.map(Math.round), tD0: this.tD0, lifeAt: Math.round(this.lifeAt),
      ...(Object.keys(this.goods).length ? { goods: { ...this.goods } } : {}),
      ...(Object.keys(this.cultureUnits).length ? { culture: { ...this.cultureUnits } } : {}),
      ...(Object.keys(this.inModel).length ? { inModel: { ...this.inModel } } : {}),
      ...(Object.keys(this.earnedIn).length ? { earnedIn: this.allEarnedIn() } : {}),
    };
  }

  fromSave(s: MetricsSave | undefined): void {
    this.books.clear();
    this.takings = s?.takings?.slice() ?? [];
    this.tD0 = s?.tD0 ?? -1;
    this.lifeAt = s?.lifeAt ?? 0;
    this.goods = {};
    for (const [k, v] of Object.entries(s?.goods ?? {})) if (typeof v === 'number' && Number.isFinite(v)) this.goods[k] = v;
    this.cultureUnits = {};
    for (const [k, v] of Object.entries(s?.culture ?? {})) if (typeof v === 'number' && Number.isFinite(v)) this.cultureUnits[k] = v;
    this.inModel = {};
    for (const [k, v] of Object.entries(s?.inModel ?? {})) if (typeof v === 'number' && Number.isFinite(v)) this.inModel[k] = v;
    this.earnedIn = {};
    for (const [k, v] of Object.entries(s?.earnedIn ?? {})) if (typeof v === 'number' && Number.isFinite(v)) this.earnedIn[k] = v;
    for (const b of s?.books ?? []) {
      if (!b || typeof b.id !== 'string' || !b.v) continue;
      this.books.set(b.id, { ...b, you: b.id === YOU_ID, v: { ...blank(), ...b.v }, hist: b.hist?.slice() ?? [] });
    }
    this.t = 0;
  }

  clear(): void { this.fromSave(undefined); }

  /** pr.metrics: the table as text. */
  console() {
    return {
      table: () => this.list().map((b) => `${b.name}${b.gone !== null ? ` (ceased day ${b.gone + 1})` : ''}: ${METRICS.map((m) => `${m.key} ${b.v[m.key]}`).join(' · ')}`),
      hist: () => this.list().map((b) => `${b.name}: ${b.hist.join(', ')}`),
    };
  }
}

function blank(): Values {
  return Object.fromEntries(METRICS.map((m) => [m.key, 0])) as Values;
}
