import { CHAT_CELLS, CHAT_MAX, type BoardRow, type Pid, type Who } from '../../shared/protocol';

/**
 * What playing online adds to the screen: the chat in the corner, a chip saying how many are about,
 * and the card that covers the game while a dropped connection is being mended. Who is signed in and
 * the server's board are shown in the Standings window (game/standings.ts), from `playersHtml` and `rows`.
 */

const esc = (s: string): string => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);
const hex = (c: number): string => `#${(c & 0xffffff).toString(16).padStart(6, '0')}`;

/** How long a chat line stays up once nobody is typing, in seconds. */
const LINE_LIFE = 28;
/** A whisper to you lingers longer still: twice an ordinary line (the user, 28 Oct 2026: 2x and 4x the old 14 s). */
const WHISPER_LIFE = LINE_LIFE * 2;
const KEEP = 120;

export interface Person { who: Who; cell: string; you: boolean }

interface UiHost {
  say(text: string): void;
  askBoard(): void;
  people(): Person[];
  /** The cell the player is in. */
  here(): string;
  /** May the chat take the keyboard now: a game in play, with no menu over it. */
  free(): boolean;
  /** May Enter open the chat: free, and nothing in the game (a race's start, a night op, a tow) is waiting on it. */
  enterFree(): boolean;
}

export class OnlineUi {
  private chat = document.createElement('div');
  private lines = document.createElement('div');
  private form = document.createElement('div');
  private input = document.createElement('input');
  private hint = document.createElement('div');
  private lost = document.createElement('div');
  private chip = document.createElement('div');
  /** The server's board as last heard. */
  rows: BoardRow[] = [];
  /** The board has come in (the Standings window redraws). */
  onBoard: () => void = () => {};
  /** The "Online" line in the corner is clicked: who is signed in. */
  onChip: () => void = () => {};
  private shown = false;
  private t = 0;
  private lastReply = '';
  /**
   * Who you last whispered to: the chat opens already whispering to them (the user, 28 Oct 2026), until Esc is
   * pressed while typing or the `/w name` it opens with is deleted.
   */
  private lastTo = '';

  constructor(private host: UiHost) {
    this.chat.id = 'net-chat';
    this.chat.hidden = true;
    this.lines.className = 'lines';
    this.form.className = 'form';
    this.input.type = 'text';
    this.input.maxLength = CHAT_MAX;
    this.input.spellcheck = false;
    this.input.autocomplete = 'off';
    this.input.placeholder = `Say something · /w name to whisper`;
    this.hint.className = 'hint';
    this.hint.innerHTML = '<kbd>Enter</kbd> chat · <kbd>I</kbd> standings and who’s online';
    this.form.append(this.input);
    this.chat.append(this.lines, this.form, this.hint);
    document.body.append(this.chat);

    this.lost.id = 'net-lost';
    this.lost.hidden = true;
    this.lost.innerHTML = '<div class="card"><h2>Connection lost<span>.</span></h2><p>Trying to reach the server again…</p><p class="sub"></p></div>';
    document.body.append(this.lost);

    this.chip.id = 'net-chip';
    this.chip.hidden = true;
    this.chip.title = 'Who is online (I → Players)';
    this.chip.addEventListener('click', (e) => { e.stopPropagation(); this.onChip(); });
    document.getElementById('tl')?.append(this.chip);

    this.chat.addEventListener('mousedown', (e) => { if (e.target !== this.input && this.shown) { e.preventDefault(); this.focus(); } });
    this.input.addEventListener('blur', () => this.chat.classList.remove('typing'));
    // the whisper it opened with deleted: back to plain chat next time too
    this.input.addEventListener('input', () => { if (this.lastTo && !this.input.value.startsWith(`/w ${this.lastTo}`)) this.lastTo = ''; });

    // before the game's own listeners: while a line is being typed no key reaches the car
    window.addEventListener('keydown', (e) => {
      if (!this.shown) return;
      const typing = document.activeElement === this.input;
      if (typing) {
        e.stopImmediatePropagation();
        if (e.code === 'Enter' || e.code === 'NumpadEnter') {
          const text = this.input.value.trim();
          this.input.value = '';
          if (text) this.host.say(text === '/r' || text.startsWith('/r ') ? (this.lastReply ? `/w ${this.lastReply} ${text.slice(3)}` : text) : text);
          this.input.blur();
          e.preventDefault();
        } else if (e.code === 'Escape') { this.input.value = ''; this.lastTo = ''; this.input.blur(); e.preventDefault(); }
        return;
      }
      const t = e.target as HTMLElement | null;
      if (t instanceof HTMLInputElement || t instanceof HTMLTextAreaElement || e.ctrlKey || e.metaKey || e.altKey || !this.host.free()) return;
      // Enter to talk (unless the game is waiting on it); / starts a command
      const enter = e.code === 'Enter' || e.code === 'NumpadEnter';
      if ((enter && this.host.enterFree()) || e.code === 'Slash') { e.preventDefault(); e.stopImmediatePropagation(); this.focus(e.code === 'Slash' && !e.shiftKey ? '/' : this.lastTo ? `/w ${this.lastTo} ` : ''); }
    }, true);
    window.addEventListener('keyup', (e) => { if (document.activeElement === this.input) e.stopImmediatePropagation(); }, true);
  }

  /** Is a line being typed? The game leaves Enter and the rest alone while it is. */
  get typing(): boolean { return document.activeElement === this.input; }

  /** The online things on screen, or put away (the title screen, a local game). */
  show(on: boolean): void {
    if (this.shown === on) return;
    this.shown = on;
    this.chat.hidden = !on;
    this.chip.hidden = !on;
    if (!on) { this.input.blur(); this.lines.replaceChildren(); this.setLost(false); }
  }

  /** Into the chat to type, by default whispering to whoever you last whispered to. */
  focus(text = this.lastTo ? `/w ${this.lastTo} ` : ''): void {
    if (!this.shown) return;
    this.chat.classList.add('typing');
    this.input.value = text;
    this.input.focus();
    this.input.setSelectionRange(text.length, text.length);
  }

  /** A line in the chat: somebody near, a whisper either way, or a word from the server. */
  line(kind: 'say' | 'w' | 'wto' | 'sys' | 'alert', name: string, text: string, colour?: number, to?: string, from?: Pid): void {
    const el = document.createElement('div');
    el.className = `line ${kind}`;
    const dot = colour !== undefined ? `<i style="background:${hex(colour)}"></i>` : '';
    // a name says who it is, so right-clicking it can add them as a friend (net/friends.ts)
    const pid = from ? ` data-pid="${esc(from)}"` : '';
    if (kind === 'sys') el.innerHTML = `<em>${esc(text)}</em>`;
    else if (kind === 'alert') el.innerHTML = `<strong>${esc(text)}</strong>`;
    else if (kind === 'w') { el.innerHTML = `${dot}<b${pid}>${esc(name)}</b> <span>whispers</span> ${esc(text)}`; this.lastReply = name; }
    else if (kind === 'wto') { el.innerHTML = `<span>to</span> <b>${esc(to ?? '')}</b> ${esc(text)}`; this.lastTo = to ?? ''; }
    else el.innerHTML = `${dot}<b${pid}>${esc(name)}</b> ${esc(text)}`;
    el.dataset.at = String(performance.now());
    el.dataset.life = String((kind === 'w' || kind === 'alert' ? WHISPER_LIFE : LINE_LIFE) * 1000);
    this.lines.append(el);
    while (this.lines.childElementCount > KEEP) this.lines.firstElementChild!.remove();
    this.lines.scrollTop = this.lines.scrollHeight;
  }

  setBoard(rows: BoardRow[]): void {
    this.rows = rows;
    this.onBoard();
  }

  setLost(on: boolean, sub = ''): void {
    this.lost.hidden = !on;
    const p = this.lost.querySelector('.sub');
    if (p) p.textContent = sub;
  }

  /** Every frame: old lines fade, and the chip keeps up. */
  tick(dt: number): void {
    if (!this.shown) return;
    const now = performance.now();
    const typing = this.typing;
    for (const el of Array.from(this.lines.children) as HTMLElement[]) {
      const old = !typing && now - Number(el.dataset.at) > Number(el.dataset.life);
      if (el.classList.contains('old') !== old) el.classList.toggle('old', old);
    }
    this.t -= dt;
    if (this.t > 0) return;
    this.t = 1;
    const n = this.host.people().length;
    const text = `<i></i>Online · ${n} ${n === 1 ? 'fleet' : 'fleets'}`;
    if (this.chip.innerHTML !== text) this.chip.innerHTML = text;
  }

  /** The Players tab of the Standings window: everyone signed in, nearest first, each with a whisper button. */
  playersHtml(): string {
    const here = this.host.here().split(',').map(Number);
    const people = this.host.people().map((p) => {
      const [cx, cz] = p.cell.split(',').map(Number);
      const dx = cx - here[0], dz = cz - here[1];
      return { ...p, far: Math.max(Math.abs(dx), Math.abs(dz)), dx, dz };
    }).sort((a, b) => Number(b.you) - Number(a.you) || a.far - b.far || a.who.name.localeCompare(b.who.name));
    return `<ul class="people">${people.map((p) => {
      const c = p.who.brand ? hex(p.who.brand.primary) : '#e2412f';
      const compass = ['east', 'south-east', 'south', 'south-west', 'west', 'north-west', 'north', 'north-east'][((Math.round(Math.atan2(p.dz, p.dx) / (Math.PI / 4)) % 8) + 8) % 8];
      const where = p.you ? 'you' : p.far === 0 ? 'in this county' : `${p.far} ${p.far === 1 ? 'county' : 'counties'} ${compass}${p.far <= CHAT_CELLS ? ' · hears you' : ''}`;
      // what they have built and how loved it is (docs/community.html), once their game has saved to the board
      const row = this.rows.find((r) => r.id === p.who.id);
      const built = row && (row.works || row.hearts) ? ` · ${row.works ?? 0} work${row.works === 1 ? '' : 's'} · <span class="hrt">♥ ${row.hearts ?? 0}</span>` : '';
      // anyone signed in can be followed, and their HQ looked at (net/friends.ts takes data-pact)
      const act = (a: string, label: string, extra = '') => `<button type="button" class="link" data-pact="${a}" data-id="${esc(p.who.id)}" data-name="${esc(p.who.name)}"${extra}>${label}</button>`;
      return `<li><span class="what"><i class="dot" style="background:${c}"></i><b${p.you ? '' : ` data-pid="${esc(p.who.id)}"`}>${esc(p.who.name)}</b><small>${esc(p.who.brand?.name ?? '')} · ${where}${built}</small></span>`
        + (p.you ? '' : `<span class="acts">${act('follow', 'follow')}${row?.hq ? act('hq', 'HQ', ` data-key="${esc(row.hq.key)}"`) : ''}<button type="button" class="link" data-w="${esc(p.who.name)}">whisper</button></span>`) + '</li>';
    }).join('')}</ul><p class="foot">Plain chat carries ${CHAT_CELLS} counties. <kbd>/w</kbd> name reaches anyone signed in.</p>`;
  }

  /** Ask the server for its board again (it answers through `setBoard`). */
  askBoard(): void { this.host.askBoard(); }

  /** A whisper button was pressed: the chat opens addressed to them. */
  whisper(name: string): void { this.focus(`/w ${name} `); }
}

/** What a name tag or a chat line calls somebody. */
export const nameOf = (people: Map<Pid, Who>, id: Pid): string => people.get(id)?.name ?? 'Somebody';
