/**
 * The annual newspaper (docs/newspaper.html): the shapes every part of it shares. Nothing here touches the
 * page or the world, so the desk, the copy and the layout run headless in the gate (scripts/press.ts).
 */

/** Every kind of event the news desk writes down. */
export type Kind =
  | 'founded' | 'vehicleBought' | 'fleetSize' | 'driverHired' | 'driverAce' | 'driverQuit'
  | 'hq' | 'deedBought' | 'deedSold' | 'deedMended' | 'deedVoid'
  | 'territoryWon' | 'territoryLost' | 'territoryStrong' | 'territoryContested'
  | 'lobbied' | 'annexed' | 'roadsBuilt' | 'worth' | 'deed' | 'missionDone' | 'storyBeat'
  | 'raceResult' | 'nightRun' | 'bust' | 'towed' | 'firmMet' | 'firmCeased'
  | 'graduated' | 'requestDone' | 'culture' | 'bigGame' | 'concert' | 'weather' | 'rumour' | 'find' | 'firstVisit'
  // phase 2: a league's season over, a big building finished, a town's fortunes turning, a march
  | 'season' | 'built' | 'mood' | 'protest'
  // the in-world events (docs/events.html): a parade, a motorcade, a regatta, a midnight's fireworks
  | 'event'
  // phase 3, online: a record taken, guests at the HQ, signs, hearts, a GG, a name, a postcard, the week's picks,
  // works in use, friends' HQs, a partner joining a shared fleet; and the rival firms' board decisions
  | 'record' | 'guest' | 'sign' | 'hearts' | 'gg' | 'named' | 'postcard' | 'pick' | 'crossings' | 'listed' | 'tracks'
  | 'friendHq' | 'crewJoin' | 'board'
  // a Passport page filled to the last stamp, and its treat (game/passportRewards.ts); `v` 'book' for the whole Passport
  | 'sealed'
  // the news wire (server/news.ts): a story off it, `v` whose news it is to this player ('you', 'circle', 'county',
  // 'world'); and the Fleet of the Year the wire made, `v` 'world' or 'county'
  | 'wire' | 'award';

/** An event's own facts: names as written, numbers as counted. Copy is filled from these and nothing else. */
export type Fields = Record<string, string | number>;

/** A picture the window can draw on the hero stage (a HeroSpec, kept opaque here so this stays headless). */
export type Pic = Record<string, unknown>;

/** One thing that happened, as the desk wrote it down. */
export interface PressEvent {
  k: Kind;
  /** A variant of the kind the copy is keyed by beside it (a weather's kind, a race won or lost). */
  v?: string;
  /** The game hour it happened. */
  t: number;
  /** Who did it: 'you', a rival firm's name, or '' for the world (a town, the weather). */
  who: string;
  /** The town it concerns, by key ("cx,cz#id"), when there is one. */
  town?: string;
  /** Tiles between it and the player when it was written down; -1 when nobody knew where it was. */
  d: number;
  /** Its starting weight, 1 small to 5 front page. */
  w: number;
  f: Fields;
  pic?: Pic;
  /** A still of the moment it happened, when the player was there (base64 JPEG, no prefix). */
  jpg?: string;
}

/** A town the player dealt with this year, as it stood when they did. */
export interface TownInfo {
  key: string;
  name: string;
  kind: string;
  style: string;
  /** It has a news station: the Press has a branch there. */
  news: boolean;
  /** Its county or island. */
  county: string;
  /** How much the player dealt with it: deliveries, stops, purchases. */
  n: number;
}

/** What the desk writes down at each press time, so growth reads as a change from one year to the next. */
export interface Snapshot {
  units: number;
  worth: number;
  roads: [number, number, number];
  firms: Record<string, { units: number; town: string; key: string }>;
  /** The Ledger box's numbers: the company's, and the best-placed rival's (phase 2; missing in older saves). */
  book?: LedgerNumbers;
  rival?: { name: string; units: number; worth: number } | null;
}

/** The company's year in the Ledger box. */
export interface LedgerNumbers { deliveries: number; takings: number; units: number; doors: number; held: number; worth: number }

/** A league's last finished season, as the Sport box prints it, and whether it ended in the year reviewed. */
export interface SportNow {
  league: string;
  season: number;
  /** The game hour the season ended. */
  ended: number;
  rows: { name: string; rec: string; pts: number }[];
  /** The nearest stadium's club: its name and place, when not in the top three. */
  home?: { name: string; pos: number; of: number };
  /** The home club won it. */
  homeWon: boolean;
  /** Points between first and second. */
  margin: number;
}

/** The standing boxes (docs/newspaper.html, Picking the stories), each only when the year filled it. */
export interface Boxes {
  sport?: { league: string; season: number; rows: { name: string; rec: string; pts: number }[]; home?: string };
  weather?: { rows: [string, number][]; worst?: string };
  ledger?: { fleet: string; rows: [string, string, string][]; rival?: string };
  inn?: string[];
  /** The world this week (server/worldWeek.ts): every human fleet online together, a line each. */
  world?: string[];
  /** From further afield: the year's biggest stories on the wire from beyond the county, a line each. */
  afield?: string[];
  /** The neighbours' year: the wire's stories about the fleets the player deals with most. */
  circle?: string[];
  /** Honours: last week's titles (server/titles.ts), a line each. */
  honours?: string[];
  /** A year ago in these pages: the last issue's headline, and the year it reviewed. */
  ago?: { head: string; year: number };
}

/** The paper itself: its name, its look and its people. */
export interface Paper {
  name: string;
  slogan: string;
  /** The masthead's face: blackletter, a display serif, or a heavy sans. */
  face: 'black' | 'serif' | 'sans';
  /** The city that publishes it (or the county, for a country weekly) and its key ('' for a county). */
  city: string;
  key: string;
  county: string;
  /** Three reporters the city names once and keeps; the first is the editor. */
  staff: string[];
}

/** One article. */
export interface Article {
  k: Kind;
  /** A story off the news wire: its desk, which is its kind for the paper's "no two of a kind". */
  desk?: string;
  head: string;
  body: string[];
  by: string;
  /** "… continued on page n". */
  page: number;
  pic?: Pic;
  /** A still of the moment (base64 JPEG, no prefix): preferred to the plinth. Kept on the newest issues only. */
  photo?: string;
  /** The headline template used, for variety (copy.ts ids). */
  hid?: string;
  /** The name a wordmark falls back to when there is no picture: the fleet, the firm or the town. */
  mark: string;
  cap?: string;
}

/** A the broadsheet, B the tabloid (a great still), C the classic, D the quiet year. */
export type Layout = 'A' | 'B' | 'C' | 'D';

export interface Issue {
  /** Issue number in this game, from 1. */
  n: number;
  /** The game hour it was printed. */
  t: number;
  /** The year it reviews, from 1 (and the year it was founded, when one issue covers two). */
  year: number;
  from: number;
  layout: Layout;
  paper: Paper;
  /** The year the paper first came to this player. */
  est: number;
  price: number;
  /** The left ear: the year's weather in a line, or the county's edition. */
  ear: string;
  lead: Article;
  minors: Article[];
  briefs: string[];
  boxes?: Boxes;
  /** The year in pictures, the paper's second page: the year's other stills of the moment (kept on the newest issues only). */
  gallery?: { photo: string; cap: string; when: string }[];
  /** The Press's standing with the player when it printed (factions.ts RUNG index), for the tone it took. */
  tone?: number;
  /** Read in the window at least once. */
  read?: boolean;
}

/** The desk's state in a saved game (game/save.ts `press`, from version 25). */
export interface PressSave {
  log: PressEvent[];
  snap: Snapshot | null;
  towns: TownInfo[];
  issues: Issue[];
  next: number;
  /** Kinds that have ever made an issue, for novelty; kinds used in the last three issues, for variety. */
  seen: string[];
  used: string[][];
  /** The year each paper first came, by city key or county. */
  papers: Record<string, number>;
  /** Game hours of each weather seen this year, for the Weather box. */
  wx?: Record<string, number>;
  /** News written down once ever, by key (the week's picks, which the server tells at every sign-in). */
  once?: string[];
}

/** Game hours in a day and in a year (render/season.ts DAYS_PER_YEAR = 4). */
export const DAY_H = 24;
export const YEAR_H = 4 * DAY_H;
export const SEASONS = ['spring', 'summer', 'autumn', 'winter'] as const;
/** The hour of the morning the paper comes out: Channel 6's hour (game/story.ts). */
export const PRESS_HOUR = 7;
