/**
 * The fleet: every vehicle the player has bought, as a thing with a place. A unit is ridden (the one
 * under the player), parked where it was left, working (a hired driver out in it on an island near
 * enough to move), on the road after the player (game/convoy.ts), shadowed while its own island is
 * momentarily quiet, waiting where it cannot follow, or being towed — or in the garage.
 *
 * The garage is off the map: a unit there is nowhere in the world, follows nobody, and can't be towed or
 * crewed. Only as many units as the fleet has slots may be out on the map at once, the ridden one aside:
 * none without a headquarters, and as many as the HQ building's grade opens with one (docs/hq.html): a
 * house one, a bank four, a wonder ten. Anything beyond that waits in the garage.
 *
 * Every one of those is somewhere a vehicle actually is. Nothing here pays money for a vehicle the
 * game cannot draw: a driver earns when they deliver, and travelling earns nothing at all.
 * traffic.ts drives the working units; render/fleetLayer.ts draws the parked ones.
 */

export type Where = 'ridden' | 'parked' | 'working' | 'enroute' | 'shadowed' | 'waiting' | 'towing' | 'garaged';


interface UnitLog { tiles: number; deliveries: number; earned: number; incidents: number; towed: number }

/** One game day of a unit's work: the day, what it paid you, and the game hours it spent at work. */
export type DayLog = [number, number, number];
/** How many game days with work in them a unit's record keeps: the rate a day is over these. */
export const DAY_LOG = 30;

/**
 * One incident: a hired driver who could not get where they were going and had the vehicle towed
 * back to base. The fleet keeps the last of these so the F window can show what a driver is really
 * costing you, and pr.fleet.tows() can say why it keeps happening.
 */
interface TowNote {
  hour: number;
  uid: number; unit: string; model: string;
  driver: string; rank: string; temper: string;
  /** What beat them (traffic.ts), and what they were doing at the time. */
  reason: string; doing: string;
  fee: number;
  place: string; cell: [number, number]; x: number; z: number;
}

export interface Unit {
  uid: number;
  model: string;
  name: string;
  /** The cell it is in, and where in that cell's tiles. */
  cx: number; cz: number;
  x: number; z: number; y: number; heading: number;
  where: Where;
  /** The driver's id, 0 for none. */
  driver: number;
  order: Order;
  log: UnitLog;
  /** What it has paid you while working on screen, and over how many game hours: its measured rate. */
  paid: number; hours: number;
  /** The game hour it last came off the road. */
  since: number;
  /** The journey it is on after the player, or null. Set and advanced by game/convoy.ts. */
  road?: Road | null;
  /** Left here on purpose: a delivery driver never collects it and it is never billed. */
  laidUp?: boolean;
  /** Why it is waiting rather than following, for the garage's line. */
  held?: string;
  /** Work (take loads and earn) or Follow (drive in formation behind the player); missing is Work. */
  mode?: FleetMode;

  /** A freight train remembers the county it was bought in: its wagons are what that county makes. */
  origin?: [number, number];
  /** Seconds left on a tow. */
  tow?: number;
  /** The town or harbour it was last seen near, for the state line. */
  place?: string;
  /** What the workshop has done to it; missing is stock. */
  parts?: Parts;
  /**
   * Its last DAY_LOG game days with anything in them, oldest first: [day, $ to you, hours at work]. The details
   * pane's earnings chart, and its rate a day (Fleet.dayRate). Missing until it first works or earns.
   */
  days?: DayLog[];
  /** What it has delivered by cargo kind (CargoType id): [loads, $ to you], for its details pane. */
  kinds?: Record<string, [number, number]>;
  // ---- in memory only ----
  agent?: Agent | null;
  /** A train crewed out of the garage: it comes out of the sheds at a station, wherever it went in (game/railCrew.ts). */
  sheds?: boolean;
  /** On a far run (docs/crewtrains.html, Long haul): its route, clock and loads, kept by game/railCrew.ts and saved as they are. */
  far?: FarSave;
  /** Winding down in a county about to be let go (docs/farfleet.html): finishing what is aboard, taking nothing more. */
  windDown?: boolean;
  /** Shuttling for the player's rush (game/rushes/crew.ts): it takes no other work until the bell. */
  rushing?: boolean;
  traffic?: Traffic | null;
  /** The manifest it was on when its island went quiet, or what it carried home when it was called away. */
  run?: Run | null;
  /** Sent for a town's loads from its card: its next manifest starts from what waits there, by town key. */
  lure?: string;
  /**
   * A shared fleet's vehicle another member's game is driving (docs/sharedfleets.html): listed with the rest, but
   * this game never runs it (it stands as 'waiting', which nothing launches) and the other game's copy is the one
   * drawn on the map. `where` is what it is doing there.
   */
  away?: { by: string; name: string; where: string };
}

/**
 * A journey across the cell lattice after the player: the cells it drives through, the first being
 * where it set out. Hop k runs from cells[k] to cells[k + 1]. Nothing here is a clock: the vehicle is
 * a real one on the road the whole way (game/convoy.ts drives it), and this is only where it is going.
 */
export interface Road {
  cells: [number, number][];
  /** Whether hop k is a ferry crossing, and what its fare comes to. */
  ferry: boolean[];
  fares: number[];
  /** Which of the cells it is in now. */
  leg: number;
  /** Tiles a second it averages, and roughly how many tiles it has still to go: the ETA. */
  pace: number; tiles: number;
  /** Tiles the move was reckoned at when it set off, which a delivery is billed by. */
  billTiles: number;
  /** Fares it has run up so far, paid when it arrives. */
  owed: number;
  /** Where it is bound, for the state line. */
  to: string;
  /** True for a vehicle with nobody in it, driven over by a delivery driver and billed on arrival. */
  carried?: boolean;
  /** What it is driving for in the cell it is in: the far border, the ferry slip, or its new base. */
  aim?: 'door' | 'slip' | 'base';
  /** Seconds left standing on the slip for the boat, once it is there. */
  slip?: number;
  /** Times it has been sent for the same place in this cell without getting there. */
  tries?: number;
}


/** What the fleet needs from the game. */
export interface FleetHost {
  seed(): string;
  hours(): number;
  worldAt(cx: number, cz: number): World | null;
  trafficOf(w: World): Traffic | null;
  /** The player's cell and place in it. */
  player(): { cx: number; cz: number; x: number; z: number } | null;
  announce(title: string, body: string): void;
  float(text: string, gx: number, gy: number, gz: number, kind: FloatKind): void;
  /** A driver has just earned the player `you`: the fleet window's ticker shows it. */
  earned?(you: number, d: Driver, u: Unit, what: string): void;
  /** A driver's delivery raised the fleet's standing with a faction: the line, and the faction's colour. */
  standing?(u: Unit, rep: { text: string; colour: string }): void;
  /** Why a unit can't be towed to where the player is now (a boat needs water near), or null. */
  towCheck(u: Unit): string | null;
}

/** Tow: a callout, a dollar a tile of straight line, and a crossing fee for every strait on the way. */
export const TOW_BASE = 40, TOW_PER_TILE = 1, TOW_CROSSING = 150;
/** A driver's incident is billed at most this, however far from base it happened (a tow across a strait is the convoy's, not this). */
export const TOW_CAP = 120;
/** Out of the garage within this many tiles of where it went in (and no strait between) is free; further is a tow (Fleet.garageFee). */
export const GARAGE_FREE = 60;
/** Selling gets this share of the price back. */
export const RESALE = 0.6;
/** And this share of what was spent on its parts. */
export const PARTS_RESALE = 0.4;
/** Incidents kept in the fleet's log. */
const TOW_LOG = 60;
/** Most of the player's vehicles out working on one island at once; the rest wait at base for a slot. */
const MAX_WORKING = 16;
/** Tiles round an idle driver that new work has it look again at once (Fleet.fresh). */
const FRESH_NEAR = 90;
/** Tiles an idle driver has moved since its last look past which everything round it counts as new (Fleet.fresh). */
const FRESH_MOVED = 20;
/** A unit shadowed longer than this comes back at its base, not where it was. */
const STALE_HOURS = 4;
/**
 * Seconds a crewed jet may rest in a cell out of memory before it is flown home empty (JetPilots.fetch): long enough
 * for a loading save's islands to come in round it, short enough that nobody finds it parked out of view for good.
 */
const JET_STRANDED = 90;

/**
 * The fleet's headquarters: a lot the player owns (its estate deed key), where it stands, and its grade
 * (docs/hq.html): the grade decides the fleet's slots.
 */
export interface Hq {
  key: string; name: string; town: string; cx: number; cz: number; x: number; z: number; grade: Grade; plus: boolean; slots: number;
  /** The building's kind and the size of its town, so a world begun again can find one like it (game/hqCarry.ts). */
  kind?: string; townKind?: TownKind | null;
}
/** Slots on the map without an HQ: none, only the vehicle you drive. Every slot comes from the HQ. */
export const SLOTS_BARE = 0;

/**
 * The window the rate is measured over, in game hours of work. The fleet scope said four; measured, a
 * Mule on a metro island delivered about every six game hours, so four swung between nothing and double
 * and it went to twelve. A manifest delivers three at once (docs/manifests.html), so eight now holds
 * two or three runs and stays honest.
 */
const RATE_WINDOW = 8;
/** Seconds a tow takes to arrive. */
const TOW_SECONDS = 6;
/** This near the drop (or a quarter of the leg, whichever is more), a recalled driver finishes it first. */
const GRACE = 20;



/** Roughly how many seconds a journey has left: the tiles still to drive at its pace, and any wait for a boat. */
export function roadLeft(r: Road): number {
  return Math.max(0, r.tiles / Math.max(0.2, r.pace) + (r.slip ?? 0));
}

/** Seconds as m:ss, for the fleet window's countdowns. */
export function clock(s: number): string {
  const t = Math.max(0, Math.round(s));
  return `${Math.floor(t / 60)}:${String(t % 60).padStart(2, '0')}`;
}

const numeral = (n: number): string => ['', '', ' II', ' III', ' IV', ' V', ' VI', ' VII', ' VIII', ' IX', ' X'][n] ?? ` ${n}`;

/** The patrol car is kept out of the buyable list, but night ops and mission cards still ask for it by id. */
export const defOf = (model: string): VehicleDef => ALL_VEHICLES.find((d) => d.id === model) ?? (model === PATROL.id ? PATROL : CARRIAGES.find((d) => d.id === model) ?? ALL_VEHICLES[0]);

export interface SavedUnit {
  uid: number; model: string; name: string; cell: [number, number];
  x: number; z: number; y: number; h: number;
  where: 'ridden' | 'parked' | 'shadowed' | 'garaged';
  /** Missing when it is the untouched default: Anything, no base. The fifth log number is tow money, from version 11. */
  driver: number; order?: Order; log: [number, number, number, number] | [number, number, number, number, number];
  paid: number; hours: number; since: number;
  origin?: [number, number]; place?: string;
  parts?: Parts;
  /** Left here on purpose. */
  laidUp?: boolean;
  /** Told to follow the player rather than work. From version 11. */
  follow?: boolean;
  /** A crewed train away on a far run (docs/crewtrains.html): it carries on from here on load. */
  far?: FarSave;
  /** Its last game days of work, and what it has delivered by kind (Unit.days, Unit.kinds). */
  days?: DayLog[];
  kinds?: Record<string, [number, number]>;
}


/** A saved unit's history, checked: its days (oldest first, at most DAY_LOG) and its kinds. */
function readHistory(v: SavedUnit): Pick<Unit, 'days' | 'kinds'> {
  const days = Array.isArray(v.days) ? v.days.filter((r) => Array.isArray(r) && r.length === 3 && r.every((n) => Number.isFinite(n))).slice(-DAY_LOG) : [];
  const kinds: Record<string, [number, number]> = {};
  if (v.kinds && typeof v.kinds === 'object') for (const [k, r] of Object.entries(v.kinds)) if (Array.isArray(r) && r.length === 2 && r.every((n) => Number.isFinite(n))) kinds[k] = [r[0], r[1]];
  return { ...(days.length ? { days: days.map((r) => [r[0], r[1], r[2]] as DayLog) } : {}), ...(Object.keys(kinds).length ? { kinds } : {}) };
}

export interface FleetSave {
  units: SavedUnit[];
  drivers: Driver[];
  hires: { day: number; taken: number[] };
  ride: number;
  next: number;
  nextDriver: number;
  earned: number;
  /** What incidents have cost in tow bills. From version 11. */
  towed?: number;
  /** The cell the fleet musters in, and whether parked vehicles ride over with it. From version 9. */
  muster?: [number, number];
  carry?: boolean;
  /** The HQ (docs/hq.html), and the most diamonds ever paid to charter one. From version 19. */
  hq?: Hq | null;
  charter?: number;
  /** Vehicles bought at a dealer, ever. From version 22: an older save counts everything past the starter car. */
  bought?: number;
  /** Tiles driven by the player at the wheel, and by the hired drivers, all time. Optional: older saves count from load. */
  driven?: [number, number];
  /** The Gilded Fleet's switch (game/passportRewards.ts): 1 gold trim, 2 gold all over. */
  gild?: 1 | 2;
  /** Architect's Eye: the town style the HQ is drawn in (game/treatsTab.ts); none, its own. */
  hqStyle?: string;
  /** The visa emblem round the fleet's badge: a deeds group sealed (game/treats.ts). */
  emblem?: string;
  /** The fleet's dress (game/toppers.ts): a topper per kind of vehicle, worn by new units of that kind. */
  dress?: Partial<Record<DressKind, string>>;
}


/** The kinds of vehicle a topper is dressed by (game/toppers.ts). */
export type DressKind = 'land' | 'water' | 'air' | 'rail';
export const DRESS_KINDS: DressKind[] = ['land', 'water', 'air', 'rail'];

export class Fleet implements FleetBrain {
  units: Unit[] = [];
  /** Hired pilots' jets on the air service (game/jetPilots.ts, 0.7.0): set by main.ts, null with NEXT_WORLD off. */
  jets: JetPilots | null = null;
  /** Hired train drivers running the fleet's trains on their beats (game/railCrew.ts, docs/crewtrains.html): set by main.ts. */
  rail: RailCrew | null = null;
  /** Seconds each crewed jet has rested in a cell out of memory (strandedJet). */
  private stranded = new Map<number, number>();
  drivers: Driver[] = [];
  /** Which of today's candidates have been taken. */
  hires = { day: -1, taken: [] as number[] };
  /** Everything the fleet's drivers have ever paid you. */
  earned = 0;
  /** Tiles driven, all time: by the player at the wheel, and by the hired drivers. */
  driven = { you: 0, hired: 0 };
  /** And everything their incidents have cost you in tow bills. */
  towed = 0;
  /** The last incidents, newest last: why a driver had to be towed (pr.fleet.tows()). */
  tows: TowNote[] = [];
  private ride = 0;
  private nextUid = 1;
  private nextDriver = 1;
  private lastHour = -1;
  private syncT = 0;
  /** Deliveries made on screen: [game hour, dollars to you], for the company line. */
  private recent: [number, number][] = [];
  /** Called whenever anything the garage shows has changed. */
  onChange: () => void = () => {};
  /** Vehicles bought at a dealer, ever: the first one brings the HQ window's tips on what to do with it. Saved. */
  bought = 0;
  /** The Gilded Fleet's switch (every stamp in the Passport): 0 off, 1 gold trim, 2 gold all over; a new unit takes it too. Saved. */
  gild: 0 | 1 | 2 = 0;
  /** Architect's Eye (the Town styles seal): the style the HQ building is drawn in, or null for its own. Saved. */
  hqStyle: string | null = null;
  /** The visa emblem framing the fleet's badge (a visa page sealed), or null. Saved. */
  emblem: string | null = null;
  /** The fleet's dress (docs/toppers.html): the topper each kind of vehicle is given, a new unit of that kind too. Saved. */
  dress: Partial<Record<DressKind, string>> = {};
  /** What a hired driver kept of a delivery: the books' "kept by drivers" (docs/hqwindow.html). */
  onKept: (amount: number) => void = () => {};
  /** Keep one incident in the log. */
  private note(t: TowNote): void {
    this.tows.push(t);
    if (this.tows.length > TOW_LOG) this.tows.shift();
  }
  /** Each unit's own definition, by model and parts: the same object while nothing changes, so it can be compared. */
  private defs = new Map<string, VehicleDef>();
  /** The fleet's name, colours and logo; null for a game from before fleets had one. */
  brand: FleetBrand | null = null;
  /** The headquarters: its grade is the fleet's slots (docs/hq.html). */
  hq: Hq | null = null;
  /**
   * The charter credit: the most diamonds ever paid to make a building the HQ. Moving to an HQ of that
   * charter or less is free, a grander one costs only the difference, and losing the HQ keeps it.
   */
  charter = 0;
  /** The HQ is boarded up: one slot short until it is mended. Set each frame by checkHq. */
  hqDown = false;

  constructor(private wallet: Wallet, private cargo: CargoSystem, private books: Economy, private host: FleetHost) {}

  // ---- the records ----

  get ridden(): Unit | null { return this.units.find((u) => u.uid === this.ride) ?? null; }
  unit(uid: number): Unit | null { return this.units.find((u) => u.uid === uid) ?? null; }
  driver(id: number): Driver | null { return this.drivers.find((d) => d.id === id) ?? null; }
  driverOf(u: Unit): Driver | null { return u.driver ? this.driver(u.driver) : null; }
  /** The game day now: a driver's `since` when they join. */
  today0(): number { return Math.floor(this.host.hours() / 24); }
  get bench(): Driver[] { return this.drivers.filter((d) => !d.unit); }
  owns(model: string): boolean { return this.units.some((u) => u.model === model); }

  // ---- slots, the HQ and the garage ----

  /** How many units may be out on the map at once, besides the one ridden: the HQ's grade, one short while it is boarded up. */
  get slots(): number { return this.hq ? Math.max(0, this.hq.slots - (this.hqDown ? 1 : 0)) : SLOTS_BARE; }

  /** Diamonds still owed to charter an HQ of this charter, after the credit. */
  charterDue(charter: number): number { return Math.max(0, charter - this.charter); }

  /** The units out on the map: every one but the ridden one and those in the garage. */
  get deployed(): Unit[] { return this.units.filter((u) => u.where !== 'ridden' && u.where !== 'garaged' && u.away?.where !== 'ridden' && u.away?.where !== 'garaged'); }
  get garaged(): Unit[] { return this.units.filter((u) => u.where === 'garaged'); }
  /** Slots with nothing in them. */
  get free(): number { return Math.max(0, this.slots - this.deployed.length); }

  /** Make this the HQ (null: none, when its lot is sold or razed). Anything past the slots goes to the garage. */
  setHq(h: Hq | null): void {
    const was = this.hq;
    this.hq = h;
    if (!h) this.hqDown = false;
    if (h && was?.key !== h.key) {
      this.host.announce('Your new HQ', `${h.name}${h.town ? `, ${h.town}` : ''} · ${gradePips(h.grade)} · ${this.slots} fleet slot${this.slots === 1 ? '' : 's'}`);
      // the paper (docs/newspaper.html): a grander address is big news, a first one bigger still
      const g = h.grade ? HQ_GRADES[h.grade] : null;
      press.write({
        k: 'hq', who: 'you', at: { x: h.cx * N + h.x, z: h.cz * N + h.z }, w: !was || (was.grade < h.grade) ? 4 : 3,
        f: { building: plain(h.name), town: h.town, grade: g ? gradeWords(g.name) : '', slots: h.slots },
      });
    }
    else if (!h && was) this.host.announce('No HQ', `${was.name} is gone · no fleet slots until you make another building your HQ`);
    this.settle();
    this.onChange();
  }

  /** Why this unit can't go in the garage, or null. */
  cantStore(u: Unit): string | null {
    if (u.away) return this.lockedWhy(u);
    if (u.where === 'garaged') return 'Already in the garage';
    if (u.where === 'ridden') return 'You are driving it';
    if (u.where === 'towing') return `${u.name} is on a tow truck`;
    return null;
  }

  /**
   * Into the garage, off the map: a driver in it goes to the bench (what they carried back on the market),
   * and it stands nowhere until it is brought out again.
   */
  store(u: Unit): string | null {
    const why = this.cantStore(u);
    if (why) return why;
    if (u.driver || u.agent || u.where !== 'parked') this.benchDriver(u, false);
    u.where = 'garaged';
    u.road = null;
    u.tow = undefined;
    u.place = 'the garage';
    this.onChange();
    return null;
  }

  /** Out of the garage, parked at this spot (the caller has found one it can stand on). */
  unGarage(u: Unit, at: { cx: number; cz: number; x: number; z: number; y: number; heading: number }): void {
    if (u.where !== 'garaged') return;
    u.cx = at.cx; u.cz = at.cz; u.x = at.x; u.z = at.z; u.y = at.y; u.heading = at.heading;
    u.where = 'parked';
    u.place = this.placeName(u);
    this.onChange();
  }

  /**
   * More out on the map than there are slots: into the garage with the extra, `first` before anything
   * else, then parked units nobody is in (the latest left first), then the rest (their drivers benched).
   * The names sent, for a line.
   */
  settle(first?: Unit | null): string[] {
    const sent: string[] = [];
    while (this.deployed.length > this.slots) {
      // a fleet-mate's vehicle is theirs to put away (docs/sharedfleets.html)
      const out = this.deployed.filter((q) => !q.away);
      const rank = (u: Unit) => (u === first ? 0 : u.where === 'parked' && !u.driver ? 1 : u.where === 'towing' ? 9 : 2);
      const u = out.sort((a, b) => rank(a) - rank(b) || b.uid - a.uid)[0];
      if (!u || this.store(u)) break;
      sent.push(u.name);
    }
    if (sent.length) this.host.announce('To the garage', `${sent.join(', ')} · ${this.slots === 0 ? 'no fleet slots' : this.slots === 1 ? 'one fleet slot' : `${this.slots} fleet slots`}${this.hq ? '' : ' · make a building your HQ for slots'}`);
    return sent;
  }

  /** The unit's own definition: its model with its parts fitted. */
  defFor(u: Unit): VehicleDef {
    const b = this.brand;
    // no respray fitted: it wears the fleet's livery, two-tone, as a firm's vehicles wear theirs
    const livery = b && fitted(u.parts, 'paint') === 0;
    // every biome stamped (game/passportRewards.ts): the fleet's land vehicles lose less pace off the road
    const trek = defOf(u.model).kind === 'land' && rewards.has('biome');
    const key = `${u.model}#${partsKey(u.parts)}${livery ? `#${b.primary}/${b.accent}` : ''}${trek ? '#trek' : ''}`;
    let d = this.defs.get(key);
    if (!d) {
      if (livery) {
        const p = u.parts ?? emptyParts();
        const parts: Parts = { ...p, t: { ...p.t, paint: [owned(p, 'paint'), 3] }, c: b.primary, a: b.accent };
        d = { ...applyParts(defOf(u.model), parts), livery: b.accent };
      } else d = applyParts(defOf(u.model), u.parts);
      if (trek) d = { ...d, trek: 0.1 } as VehicleDef;
      this.defs.set(key, d);
    }
    return d;
  }

  /** A new name, livery or logo: every unit out on the road is repainted where it is. */
  setBrand(b: FleetBrand | null): void {
    this.brand = b;
    playerBrand.current = b;
    for (const u of this.units) if (u.agent && u.traffic) u.traffic.remesh(u.agent, this.defFor(u));
    this.onChange();
  }

  // ---- the workshop ----

  /**
   * Fit a tier in a slot, buying the difference if it isn't owned yet. Paint's colour and accent ride
   * along: a colour on a respray already owned is a coat. Returns a message when it can't be done.
   */
  /**
   * Fit a tier (buying it if need be) and, for paint, a colour. `mul` prices the purchase at a Vehicle
   * Shop's rate for the year (game/outlets.ts); what was charged is left in `lastCharge`.
   */
  /**
   * Swap to a tier already owned, from the HQ window's inspector (docs/hqwindow.html): never charges.
   * A tier above the one owned is bought at a Vehicle Shop, not here.
   */
  refit(u: Unit, slot: SlotId, tier: number): string | null {
    const model = defOf(u.model);
    if (!slotOf(slot).names[model.kind]) return `A ${model.name} doesn't take that`;
    if (tier > owned(u.parts, slot)) return 'Buy that at a Vehicle Shop: drive into its striped ring and press Space';
    if (owedFor(model, u.parts, slot, tier) !== 0) return 'Buy that at a Vehicle Shop';
    return this.fit(u, slot, tier);
  }

  fit(u: Unit, slot: SlotId, tier: number, colour?: number, accent?: number, mul = 1): string | null {
    this.lastCharge = 0;
    const model = defOf(u.model);
    if (!slotOf(slot).names[model.kind]) return `A ${model.name} doesn't take that`;
    const p = u.parts ?? emptyParts();
    let cost = owedFor(model, p, slot, tier);
    const newColour = slot === 'paint' && colour !== undefined && colour !== (p.c ?? model.color);
    const newAccent = slot === 'paint' && accent !== undefined && accent !== p.a;
    // the first respray's colour comes with it; after that each change is a coat
    if (slot === 'paint' && owned(p, 'paint') >= 1 && (newColour || newAccent)) cost += coatPrice(model);
    if (cost > 0 && mul !== 1) cost = Math.max(10, Math.round((cost * mul) / 10) * 10);
    if (cost > 0 && !this.wallet.spend(cost, 'parts')) return `That costs ${money(cost)}`;
    const have = owned(p, slot);
    p.t[slot] = [Math.max(have, tier), tier];
    if (slot === 'paint') {
      if (colour !== undefined) p.c = colour;
      if (accent !== undefined) p.a = accent;
    }
    if (slot === 'nitrous') p.nos = [];
    p.spent += cost;
    this.lastCharge = cost;
    u.parts = p;
    if (tier > 0) deeds.mark('tuner', slot);
    if (fullWorks(model, p)) deeds.mark('fullWorks', `${this.host.seed()}#${u.uid}`);
    // a driver out in it drives the new one from now
    if (u.agent && u.traffic) u.traffic.remesh(u.agent, this.defFor(u));
    this.onChange();
    this.onFit(u, slot, tier);
    return null;
  }

  /**
   * Put on (or take off, with null) a faction paintjob the player has earned (docs/factions.html): free,
   * any time, on the model it was made for. Returns why not, or null.
   */
  wearJob(u: Unit, job: string | null): string | null {
    const p = u.parts ?? emptyParts();
    if ((p.j ?? null) === job) return null;
    if (job) p.j = job; else delete p.j;
    u.parts = p;
    if (u.agent && u.traffic) u.traffic.remesh(u.agent, this.defFor(u));
    this.onChange();
    this.onFit(u, 'paint', fitted(p, 'paint'));
    return null;
  }

  /**
   * Put a Passport treat on a unit, or take it off with undefined (game/passportRewards.ts): the Wonder Ball,
   * the lantern, a treat horn, the gold. Free, any time, once earned: the caller checks it was.
   */
  wearTreat(u: Unit, set: Pick<Parts, 'w' | 'tp' | 'tb' | 'l' | 'h' | 'g'>): void {
    const p = u.parts ?? emptyParts();
    const q = p as unknown as Record<string, unknown>;
    let changed = false;
    for (const [k, v] of Object.entries(set)) {
      if ((q[k] ?? undefined) === (v ?? undefined)) continue;
      if (v) q[k] = v; else delete q[k];
      changed = true;
    }
    if (!changed) return;
    u.parts = p;
    if (u.agent && u.traffic) u.traffic.remesh(u.agent, this.defFor(u));
    this.onChange();
    this.onFit(u, 'paint', fitted(p, 'paint'));
  }

  /**
   * Put a topper on a unit (docs/toppers.html), or take it off with null: free, any time, once earned (the caller
   * checks it was). The Wonder Ball is the topper `wonder`; the old `w` goes with it, so an older game still draws it.
   */
  wearTopper(u: Unit, id: string | null): void {
    // a crown remembers what it went on over, to give it back when the crown is lost
    const was = topperOf(u.parts);
    const tb = isCrownId(id ?? undefined) ? (isCrownId(was) ? u.parts?.tb : was) : undefined;
    this.wearTreat(u, { tp: id ?? undefined, w: id === 'wonder' ? 1 : undefined, tb });
  }

  /**
   * The crowns held have changed (server/crowns.ts): a unit wearing one no longer held wears what it had before, and
   * a kind dressed in one goes back to bare. Returns how many vehicles it took a crown off.
   */
  dropCrowns(held: (id: string) => boolean): number {
    let n = 0;
    for (const [k, id] of Object.entries(this.dress)) if (isCrownId(id) && !held(id!)) delete this.dress[k as DressKind];
    for (const u of this.units) {
      const tp = topperOf(u.parts);
      if (!isCrownId(tp) || held(tp!)) continue;
      const back = u.parts?.tb && !isCrownId(u.parts.tb) ? u.parts.tb : undefined;
      this.wearTreat(u, { tp: back, w: back === 'wonder' ? 1 : undefined, tb: undefined });
      n++;
    }
    if (n) this.onChange();
    return n;
  }

  /**
   * Dress the fleet: a topper (or none, with null) on every unit of a kind that is not out with a fleet-mate, and on
   * the kind's new units from now on. Returns how many it was put on.
   */
  dressKind(kind: DressKind, id: string | null): number {
    if (id) this.dress[kind] = id; else delete this.dress[kind];
    let n = 0;
    for (const u of this.units) if (!u.away && defOf(u.model).kind === kind) { this.wearTopper(u, id); n++; }
    this.onChange();
    return n;
  }

  /** The Gilded Fleet's switch, on every unit at once (a fleet-mate's out with them is left as it is). */
  setGild(n: 0 | 1 | 2): void {
    this.gild = n;
    for (const u of this.units) if (!u.away) this.wearTreat(u, { g: n || undefined });
  }

  /** What the last `fit` charged. */
  lastCharge = 0;

  /** A part was fitted (bought or given): missions listen for it (game/missions). */
  onFit: (u: Unit, slot: SlotId, tier: number) => void = () => {};

  /**
   * A part given, not bought (a mission's reward): owned and fitted at this tier, or kept at a better
   * one already owned. Returns a message when the model doesn't take it.
   */
  grant(u: Unit, slot: SlotId, tier: number, colour?: number): string | null {
    const model = defOf(u.model);
    if (!slotOf(slot).names[model.kind]) return `A ${model.name} doesn't take that`;
    const p = u.parts ?? emptyParts();
    const have = owned(p, slot), on = fitted(p, slot);
    p.t[slot] = [Math.max(have, tier), Math.max(on, tier)];
    if (slot === 'paint' && colour !== undefined) p.c = colour;
    if (slot === 'nitrous') p.nos = [];
    u.parts = p;
    if (tier > 0) deeds.mark('tuner', slot);
    if (u.agent && u.traffic) u.traffic.remesh(u.agent, this.defFor(u));
    this.onChange();
    this.onFit(u, slot, tier);
    return null;
  }

  /** What the unit's parts have cost, all told. */
  spentOn(u: Unit): number { return u.parts?.spent ?? 0; }

  /** Seconds each of a unit's nitrous bottles has left to fill, one entry a bottle. */
  bottles(u: Unit): number[] {
    const n = this.defFor(u).nitrous;
    if (!n) return [];
    const p = u.parts!;
    p.nos ??= [];
    while (p.nos.length < n.bottles) p.nos.push(0);
    if (p.nos.length > n.bottles) p.nos.length = n.bottles;
    return p.nos;
  }

  /** A bottle has been fired: the one that was full starts filling again. */
  fireBottle(u: Unit, k: number): void {
    const b = this.bottles(u);
    if (b[k] !== undefined) b[k] = NOS_REFILL;
  }

  /** The one-line account of a unit's parts, for the console. */
  partsList(u: Unit): string {
    const def = defOf(u.model);
    return slotsFor(def).map((s) => `${s.id} ${owned(u.parts, s.id)}/${fitted(u.parts, s.id)} ${tierName(s, def, fitted(u.parts, s.id))}`).join(' · ');
  }

  /** Start empty: a new game, before the free car is handed over. */
  clear(): void {
    this.bought = 0;
    this.gild = 0;
    this.hqStyle = null;
    this.emblem = null;
    this.dress = {};
    for (const u of this.units) this.pullAgent(u);
    this.units = [];
    this.drivers = [];
    this.hires = { day: -1, taken: [] };
    this.earned = 0;
    this.driven = { you: 0, hired: 0 };
    this.towed = 0;
    this.tows = [];
    this.ride = 0;
    this.nextUid = 1;
    this.nextDriver = 1;
    this.recent = [];
    this.lastHour = -1;
    this.hq = null;
    this.charter = 0;
    this.hqDown = false;
  }

  /** A new unit of this model, at this place; it is not ridden until `rideUnit`. */
  make(model: string, cx: number, cz: number, x: number, z: number, heading: number, y = 0): Unit {
    const def = defOf(model);
    const same = this.units.filter((u) => u.model === model).length;
    const u: Unit = {
      uid: this.nextUid++, model, name: `${def.name}${numeral(same + 1)}`,
      cx, cz, x, z, y, heading, where: 'parked', driver: 0,
      order: preset('anything', null),
      log: { tiles: 0, deliveries: 0, earned: 0, incidents: 0, towed: 0 },
      paid: 0, hours: 0, since: 0,
      ...(this.gild || this.dress[def.kind] ? { parts: { ...emptyParts(), ...(this.gild ? { g: this.gild } : {}), ...(this.dress[def.kind] ? { tp: this.dress[def.kind] } : {}) } } : {}),
    };
    this.units.push(u);
    this.onChange();
    return u;
  }

  /** The unit under the player is this one now; the one they were in is parked where they are. */
  setRidden(u: Unit, at: { cx: number; cz: number; x: number; z: number; y: number; heading: number } | null): void {
    if (u.away) return;
    const was = this.ridden;
    if (was && was !== u && at) this.park(was, at);
    if (u.where !== 'parked' && u.where !== 'ridden') this.benchDriver(u, true);

    u.where = 'ridden';
    this.ride = u.uid;
    // the one just left, if that makes one more out than the slots allow, goes to the garage
    if (was && was !== u && at) this.settle(was);
    this.onChange();
  }

  /** Leave a unit standing here. */
  park(u: Unit, at: { cx: number; cz: number; x: number; z: number; y: number; heading: number }): void {
    u.cx = at.cx; u.cz = at.cz; u.x = at.x; u.z = at.z; u.y = at.y; u.heading = at.heading;
    u.where = 'parked';
    u.place = this.placeName(u);
    this.onChange();
  }

  /** Keep the ridden unit's record where the player is. */
  follow(at: { cx: number; cz: number; x: number; z: number; y: number; heading: number }, tiles: number): void {
    const u = this.ridden;
    if (!u) return;
    u.cx = at.cx; u.cz = at.cz; u.x = at.x; u.z = at.z; u.y = at.y; u.heading = at.heading;
    u.log.tiles += tiles;
    this.driven.you += tiles;
  }

  rename(u: Unit, name: string): void {
    const n = name.trim().slice(0, 24);
    if (n) u.name = n;
    this.onChange();
  }

  /** What selling it would bring: part of its price, and part of what its parts cost. */
  resale(u: Unit): number { return Math.round((priceOf(u.model) * RESALE + this.spentOn(u) * PARTS_RESALE) / 10) * 10; }

  sell(u: Unit): boolean {
    if (u.where === 'ridden' || u.away) return false;
    this.benchDriver(u, false);
    this.units = this.units.filter((q) => q !== u);
    this.wallet.earn(this.resale(u), 'vehicleSales');
    this.onChange();
    return true;
  }

  // ---- tows ----

  /** What a tow to the player costs, or why it can't be done. */
  towFee(u: Unit): { fee: number; gaps: number; tiles: number } | null {
    const p = this.host.player();
    if (!p || u.where !== 'parked' || defOf(u.model).kind === 'rail') return null;
    const tiles = Math.round(Math.hypot((u.cx - p.cx) * N + u.x - p.x, (u.cz - p.cz) * N + u.z - p.z));
    const gaps = this.waterGaps(u.cx, u.cz, p.cx, p.cz);
    return { fee: TOW_BASE + TOW_PER_TILE * tiles + TOW_CROSSING * gaps, gaps, tiles };
  }

  /**
   * What bringing a garaged unit out at `to` costs: a tow's fee from where it went into the garage (it keeps that
   * spot while it is in), so the garage is no free way across the map (the user, 4 Nov 2026: players stored their
   * vehicles and brought them out on the far side of the world). Null when it is free: near where it went in
   * (GARAGE_FREE tiles, no strait between), a train (it waits in the sheds), or a fleet-mate's.
   */
  garageFee(u: Unit, to: { cx: number; cz: number; x: number; z: number }): { fee: number; gaps: number; tiles: number } | null {
    if (u.where !== 'garaged' || u.away || defOf(u.model).kind === 'rail') return null;
    const tiles = Math.round(Math.hypot((u.cx - to.cx) * N + u.x - to.x, (u.cz - to.cz) * N + u.z - to.z));
    const gaps = this.waterGaps(u.cx, u.cz, to.cx, to.cz);
    if (tiles <= GARAGE_FREE && !gaps) return null;
    return { fee: TOW_BASE + TOW_PER_TILE * tiles + TOW_CROSSING * gaps, gaps, tiles };
  }

  /** Straits between two cells along an L of cells, counting every border that isn't land or a causeway. */
  private waterGaps(ax: number, az: number, bx: number, bz: number): number {
    const sh = hashString(this.host.seed());
    let gaps = 0, cx = ax, cz = az, wet = false;
    const step = (dx: number, dz: number) => {
      const d = dx === 1 ? 0 : dx === -1 ? 2 : dz === 1 ? 1 : 3;
      const nx = cx + dx, nz = cz + dz;
      const ka = cellKind(sh, cx, cz), kb = cellKind(sh, nx, nz);
      const joined = (ka === 'continent' && kb === 'continent') || straitAt(sh, cx, cz, d) >= 0;
      // a run of open sea cells is one crossing, not one a cell
      if (!joined && !wet) gaps++;
      wet = !joined && kb === 'sea';
      cx = nx; cz = nz;
    };
    while (cx !== bx) step(Math.sign(bx - cx), 0);
    while (cz !== bz) step(0, Math.sign(bz - cz));
    return gaps;
  }

  /** Pay for a tow and start it: the unit turns up beside the player in a few seconds. */
  startTow(u: Unit): string | null {
    const t = this.towFee(u);
    if (!t) return `${u.name} can't be towed from there`;
    const why = this.host.towCheck(u);
    if (why) return why;
    if (!this.wallet.spend(t.fee, 'fines')) return `A tow costs ${money(t.fee)}`;
    u.where = 'towing';
    u.tow = TOW_SECONDS;
    this.onChange();
    return null;
  }

  // ---- drivers ----

  /** Today's candidates, with whether each has been taken. */
  today(day: number): { d: Driver; taken: boolean; k: number }[] {
    if (this.hires.day !== day) this.hires = { day, taken: [] };
    // a rail licence turns up among them once the fleet owns a train (docs/crewtrains.html)
    const trains = this.units.some((u) => defOf(u.model).kind === 'rail');
    return candidates(this.host.seed(), day, trains).map((d, k) => ({ d, taken: this.hires.taken.includes(k), k }));
  }

  /** How many have been signed from the cheats menu's full roster (a new face takes each one's slot). */
  private rosterSigned = 0;
  /** The cheats menu's full roster: every licence at every rank, always there. */
  roster(): Driver[] { return roster(this.host.seed(), this.rosterSigned); }
  /** Sign roster slot k (cheats menu): the fee as usual, and a fresh candidate stands in the slot. */
  hireRoster(k: number, into: Unit | null): string | null {
    const d = this.roster()[k];
    if (!d) return 'Nobody there';
    const why = this.sign(d, into);
    if (!why) this.rosterSigned++;
    return why;
  }

  /** Hire candidate k of the day: pay their fee, and put them in `into` if given, else on the bench. */
  hire(day: number, k: number, into: Unit | null): string | null {
    const c = this.today(day).find((e) => e.k === k);
    if (!c || c.taken) return 'Already hired';
    const why = this.sign(c.d, into);
    if (!why) this.hires.taken.push(k);
    return why;
  }

  /** Pay a candidate's fee and take them on: into `into` if given, else onto the bench. */
  private sign(cand: Driver, into: Unit | null): string | null {
    const c = { d: cand };
    if (into) {
      const why = this.cantPut(c.d, into);
      if (why) return why;
    }
    if (this.drivers.length >= this.slots) {
      return this.hq ? `${this.slots} slot${this.slots === 1 ? '' : 's'}, ${this.drivers.length} drivers: a grander HQ than ${this.hq.name} opens more`
        : 'No drivers without an HQ: buy a building and make it your HQ to hire';
    }
    const fee = feeOf(c.d);
    if (!this.wallet.spend(fee, 'crew')) return `${c.d.name} costs ${money(fee)} to sign`;
    const d: Driver = { ...c.d, id: this.nextDriver++, unit: 0, since: this.today0() };
    this.drivers.push(d);
    deeds.mark('drivers', `${this.host.seed()}#${d.id}`);
    if (rankOf(d) === 'ace') deeds.mark('aces', `${this.host.seed()}#${d.id}`);
    press.write({ k: 'driverHired', who: 'you', w: rankOf(d) === 'ace' ? 2 : 1, f: { driver: d.name, model: into?.name ?? '' } });
    if (into) this.put(d, into);
    this.onChange();
    return null;
  }

  /**
   * A driver given, not hired (a mission's reward): the best of the day's candidates with a road licence,
   * fee waived, put in a parked road vehicle if there is one near, else on the bench. Their name.
   */
  gift(day: number): string {
    const pool = this.today(day).filter((e) => !e.taken && e.d.licences.includes('road'));
    const c = pool.sort((a, b) => b.d.deliveries - a.d.deliveries)[0] ?? this.today(day)[0];
    const d: Driver = { ...c.d, id: this.nextDriver++, unit: 0, since: this.today0() };
    if (!d.licences.includes('road')) d.licences = [...d.licences, 'road'];
    this.drivers.push(d);
    deeds.mark('drivers', `${this.host.seed()}#${d.id}`);
    this.hires.taken.push(c.k);
    const into = this.units.find((u) => u.where === 'parked' && !u.driver && defOf(u.model).kind === 'land' && !this.cantPut(d, u));
    if (into) this.put(d, into);
    this.onChange();
    return d.name;
  }

  /** A driver who comes with a firm bought outright (game/buyout.ts): on the payroll, fee waived, on the bench. */
  enlist(from: Driver): Driver {
    const d: Driver = { ...from, id: this.nextDriver++, unit: 0, warned: false, since: this.today0() };
    this.drivers.push(d);
    deeds.mark('drivers', `${this.host.seed()}#${d.id}`);
    if (rankOf(d) === 'ace') deeds.mark('aces', `${this.host.seed()}#${d.id}`);
    this.onChange();
    return d;
  }

  /**
   * Why this driver can't be put in this unit, or null. `swap`: the driver it has now would step out for them
   * (the depot board's swap), so a crewed unit out working is fine, but not one on a tow truck or out of reach.
   */
  cantPut(d: Driver, u: Unit, swap = false): string | null {
    const def = defOf(u.model);
    if (!licenceFor(def)) return `Nobody can be licensed to drive the ${def.name}`;
    if (!canLoad(def)) return def.kind === 'air' && def.jet ? `Nobody holds a jet rating yet: you fly the ${def.name} yourself` : `The ${def.name} never stops, so it can never load`;
    if (!mayDrive(d, def)) return `${d.name} has no ${licenceFor(def)} licence`;
    if (swap && u.driver && u.away) return this.lockedWhy(u);
    if (swap && u.driver && u.where === 'towing') return `${u.name} is on a tow truck`;
    // a train in the garage is in the sheds: crewed, it comes out at a station (game/railCrew.ts shedsAt), given a slot
    if (def.kind === 'rail' && u.where === 'garaged' && !u.away && !u.driver) return this.free ? null : `Every slot is taken (${this.slots}): put something else away first`;
    if (u.where !== 'parked' && !(swap && u.driver && u.where !== 'ridden' && u.where !== 'garaged')) return u.where === 'ridden' ? 'You are driving it' : `${u.name} already has a driver`;
    const w = this.host.worldAt(u.cx, u.cz);
    // (a train needs only its county in memory: it runs on the railway, not in the island's traffic)
    if (!w || (def.kind !== 'rail' && !this.host.trafficOf(w))) return `${u.name} is too far away to crew: tow it nearer first`;
    return null;
  }

  /** Put a benched driver in a parked unit and send them out. */
  put(d: Driver, u: Unit): string | null {
    const why = this.cantPut(d, u);
    if (why) return why;
    if (d.unit) { const old = this.unit(d.unit); if (old) this.benchDriver(old, false); }
    // out of the sheds: it stands where it went in until it is put on the line at a station
    if (u.where === 'garaged') { this.unGarage(u, { cx: u.cx, cz: u.cz, x: u.x, z: u.z, y: u.y, heading: u.heading }); u.sheds = true; }
    // given a vehicle at last: a bored driver perks up, rather than quitting at the first hour of the job
    d.mood = Math.max(d.mood, PUT_TO_WORK);
    d.warned = false;
    d.unit = u.uid;
    u.driver = d.id;
    if (!u.order.base) u.order.base = this.nearestBase(u);
    // a train works the line within reach of where it is put to work; ends the player chose stay when it is put back there
    if (defOf(u.model).kind === 'rail') {
      const b = u.order.beat;
      const same = !!b && b.home[0] === u.cx && b.home[1] === u.cz;
      u.order.beat = { home: [u.cx, u.cz], ...(same && b?.custom ? { custom: b.custom } : {}) };
    }
    u.where = 'shadowed';
    u.since = this.host.hours();
    u.road = null;
    u.held = undefined;
    this.launch(u);

    this.onChange();
    return null;
  }

  /** Take a driver out of a unit: they go on the bench, the unit parks where it stands (or at base, from the books). */
  dismiss(u: Unit): void {
    this.benchDriver(u, false);
    this.onChange();
  }

  /** Let a driver go for good. */
  fire(d: Driver): void {
    if (d.unit) { const u = this.unit(d.unit); if (u) this.benchDriver(u, false); }
    this.drivers = this.drivers.filter((q) => q !== d);
    this.onChange();
  }

  /**
   * The driver gets out: whatever it was on is dropped (a load aboard stays in the hold for the
   * player when `forPlayer`, which is how taking the wheel mid-job works), and the unit parks.
   */
  private benchDriver(u: Unit, forPlayer: boolean): void {
    const d = this.driverOf(u);
    // a crewed train comes off the line, and stands where it stopped; what it had aboard goes to the player taking the
    // regulator, or is set down where it stands for whoever wants it (as a road driver's is, out of sight)
    const stood = this.rail?.stop(u);
    if (stood) this.standAt(u, stood);
    for (const it of this.rail?.unload(u) ?? []) {
      if (forPlayer) this.cargo.takeAboard(it);
      else this.dropLoad(u, it);
    }
    if (this.jets?.flying(u)) {
      for (const it of this.jets.ground(u, !forPlayer)) {
        if (forPlayer) this.cargo.takeAboard(it);
        else this.lose(it, u.cx * N + u.x, u.y, u.cz * N + u.z);
      }
    }
    const a = u.agent;
    if (a && u.traffic) {
      const at = a.state;
      u.cx = a.w.cx; u.cz = a.w.cz; u.x = at.x; u.z = at.z; u.y = at.y; u.heading = at.heading;
      // everything aboard goes to the player taking the wheel, or is given up
      for (const it of a.run?.aboard ?? []) {
        if (forPlayer) this.cargo.takeAboard(it);
        else this.lose(it, a.w.ox + at.x, at.y, a.w.oz + at.z);
      }
      u.traffic.dropOwned(a);
    } else if (u.where === 'shadowed' || u.where === 'enroute' || u.where === 'waiting') {
      // out of sight, or called away: what it carries goes to the player, or back on the market
      for (const it of u.run?.aboard ?? []) {
        if (forPlayer) this.cargo.takeAboard(it);
        else this.dropLoad(u, it);
      }
      const b = u.order.base;
      if (u.where === 'shadowed' && b && this.host.hours() - u.since > STALE_HOURS && defOf(u.model).kind !== 'rail') { u.cx = b.cx; u.cz = b.cz; u.x = b.x; u.z = b.z; }
    }
    if (u.run) for (const it of pending(u.run)) this.cargo.release(it, -u.uid);
    u.agent = null; u.traffic = null; u.run = null; u.road = null; u.held = undefined;

    if (d) d.unit = 0;
    u.driver = 0;
    if (u.where !== 'ridden') { u.where = 'parked'; u.place = this.placeName(u); }
  }

  /** A load a driver gave up: it's gone, the penalty is yours, and the town books it as undelivered. */
  private lose(it: CargoItem, gx: number, gy: number, gz: number): number {
    const fine = this.cargo.fineFor(it);
    this.cargo.uncarry(it);
    this.wallet.fine(fine, 'fines');
    this.books.expired(it);
    this.host.float(`−${money(fine)} abandoned ${it.type.icon}`, gx, gy, gz, 'fine');
    return fine;
  }

  // ---- orders ----

  setOrder(u: Unit, o: Order): void {
    const base = o.base ?? u.order.base ?? this.nearestBase(u);
    // a base the player chose stays theirs through any other change to the order (a preset, the floor)
    const chosen = o.chosen ?? (base === u.order.base ? u.order.chosen : undefined);
    u.order = { ...o, base };
    if (chosen) u.order.chosen = true; else delete u.order.chosen;
    this.onChange();
  }

  /** The player picks where a unit is based: a base it keeps (Order.chosen), or null to leave it to the fleet again. */
  chooseBase(u: Unit, base: Base | null): void {
    if (base) { this.setOrder(u, { ...u.order, base, chosen: true }); return; }
    this.setOrder(u, { ...u.order, base: this.nearestBase(u), chosen: false });
  }

  /** Every town and harbour a unit could be based at on its island. */
  basesFor(u: Unit): Base[] {
    const w = this.host.worldAt(u.cx, u.cz);
    if (!w) return u.order.base ? [u.order.base] : [];
    // the base it has stays on the list, even from over a border
    const cur = u.order.base;
    const out: Base[] = cur && (cur.cx !== w.cx || cur.cz !== w.cz) ? [cur] : [];
    const def = defOf(u.model);
    if (def.kind !== 'water') {
      for (const t of w.towns) {
        const k = kerbNear(w, t.x0 + t.size / 2, t.z0 + t.size / 2, Math.ceil(t.size / 2));
        if (k) out.push({ cx: w.cx, cz: w.cz, kind: 'town', id: t.id, name: t.name, x: k.x, z: k.z, tkind: t.kind });
      }
    }
    for (const p of w.ports) {
      const t = p.town >= 0 ? w.towns[p.town] : null;
      const at = def.kind === 'water' ? waterNear(w, p) : { x: (p.entry % N) + 0.5, z: Math.floor(p.entry / N) + 0.5 };
      if (!at) continue;
      if (def.kind === 'water' && !p.major && def.halfLen > 1.2) continue;
      out.push({ cx: w.cx, cz: w.cz, kind: 'port', id: p.id, name: p.name, x: at.x, z: at.z, tkind: t?.kind ?? 'rural' });
    }
    return out;
  }

  nearestBase(u: Unit): Base | null {
    const list = this.basesFor(u);
    list.sort((a, b) => Math.hypot(a.x - u.x, a.z - u.z) - Math.hypot(b.x - u.x, b.z - u.z));
    return list[0] ?? null;
  }

  // ---- the frame ----

  /** Tows arriving, working units followed, units launched onto islands in range, and the hour turning. */

  update(dt: number, placeBeside: (u: Unit) => boolean): void {
    const hours = this.host.hours();
    // however a unit came to be out on the map (a prize, the console), never more out than there are slots
    if (this.deployed.length > this.slots) this.settle();
    // nitrous bottles fill on the clock, whoever is driving
    for (const u of this.units) {
      const nos = u.parts?.nos;
      if (nos) for (let k = 0; k < nos.length; k++) if (nos[k] > 0) nos[k] = Math.max(0, nos[k] - dt);
    }
    for (const u of this.units) {
      if (u.where !== 'towing') continue;
      u.tow = (u.tow ?? 0) - dt;
      if (u.tow > 0) continue;
      if (placeBeside(u)) { u.where = 'parked'; u.place = this.placeName(u); this.host.announce(u.name, 'has been towed to you'); }
      else u.tow = 2; // no room beside the player yet: try again in a moment
      this.onChange();
    }
    // the rate is measured over work seen on screen
    const hdt = dt / SECONDS_PER_HOUR;
    for (const u of this.units) {
      if (u.where !== 'working' || (!u.agent && !this.jets?.flying(u) && !this.rail?.running(u))) continue;
      u.hours += hdt;
      if (u.hours > RATE_WINDOW) { u.paid *= RATE_WINDOW / u.hours; u.hours = RATE_WINDOW; }
      this.dayEntry(u)[2] += hdt;
    }
    this.syncT -= dt;
    if (this.syncT <= 0) { this.syncT = 1; this.launchAll(); }
    const h = Math.floor(hours);
    if (this.lastHour < 0) this.lastHour = h;
    if (h > this.lastHour) {
      const n = Math.min(24, h - this.lastHour);
      this.lastHour = h;
      this.tick(n);
    }
  }

  /**
   * The cells crewed units are working in (or were, while out of sight), for the world to keep in memory
   * with traffic running, so a driver a cell over doesn't drop off the road as the player drives away.
   */
  workCells(): [number, number][] {
    const out = new Map<string, [number, number]>();
    for (const u of this.units) {
      if (!u.driver || (u.where !== 'working' && u.where !== 'shadowed')) continue;
      // a crewed train's whole beat, so it never runs off the edge of what is in memory
      if (this.rail && defOf(u.model).kind === 'rail') { for (const [x, z] of this.rail.cells(u)) out.set(`${x},${z}`, [x, z]); continue; }
      const cx = u.agent ? u.agent.w.cx : u.cx, cz = u.agent ? u.agent.w.cz : u.cz;
      out.set(`${cx},${cz}`, [cx, cz]);
      // and the county next door a load aboard is bound for, so a driver crossing the line isn't stopped at it
      // (docs/farfleet.html: a county is never let go under a driver mid-delivery if it can be helped)
      for (const it of u.agent?.run?.aboard ?? []) {
        const tx = Math.floor(it.to.x / N), tz = Math.floor(it.to.z / N);
        if ((tx !== cx || tz !== cz) && Math.max(Math.abs(tx - cx), Math.abs(tz - cz)) <= 1) out.set(`${tx},${tz}`, [tx, tz]);
      }
    }
    return [...out.values()];
  }

  /**
   * A county with fleet vehicles at work in it is about to be let go (docs/farfleet.html, wrap up): each driver there
   * finishes what is aboard and takes nothing more. The units winding down, by uid.
   */
  windDownIn(cx: number, cz: number): number[] {
    const out: number[] = [];
    for (const u of this.units) {
      if (!u.agent || u.where !== 'working' || u.agent.w.cx !== cx || u.agent.w.cz !== cz) continue;
      u.windDown = true;
      out.push(u.uid);
    }
    return out;
  }

  /** How many of these units still carry loads in their county (the wrap-up waits on them). */
  stillCarrying(uids: number[]): number {
    return uids.filter((uid) => { const u = this.unit(uid); return !!u?.agent && u.where === 'working' && !!u.agent.run?.aboard.length; }).length;
  }

  /** A county kept after all (the player came back, or a slot opened): its drivers go back to work. */
  windUp(uids: number[]): void {
    for (const uid of uids) { const u = this.unit(uid); if (u) delete u.windDown; }
  }

  /** Put every crewed unit whose island is alive back on the road. */
  launchAll(): void {
    const perIsland = new Map<Traffic, number>();
    for (const u of this.units) {
      if (u.agent && u.traffic && !u.traffic.agents.includes(u.agent)) { u.agent = null; u.traffic = null; if (u.where === 'working') { u.where = 'shadowed'; u.since = this.host.hours(); } }
      if (u.agent && u.traffic && u.where === 'working') perIsland.set(u.traffic, (perIsland.get(u.traffic) ?? 0) + 1);
      // a crewed train: its record kept where the train is, and one no longer on the line is out of sight again
      if (this.rail && u.where === 'working' && defOf(u.model).kind === 'rail') {
        const tr = this.rail.train(u);
        const at = tr ? this.rail.spotOf(tr) : null;
        if (at) this.standAt(u, at);
        // (away on a far run: working out of memory, on its clock)
        else if (!this.rail.away(u)) { u.where = 'shadowed'; u.since = this.host.hours(); }
      }
    }
    for (const u of this.units) {
      if (u.where !== 'shadowed' || !u.driver) continue;
      if (u.windDown) this.homeWound(u);
      // a train goes back on the line once its county is in memory, whatever the island's traffic is doing
      // (one saved mid far run carries on with it, out of memory)
      if (defOf(u.model).kind === 'rail') {
        if (u.far && this.rail?.resume(u)) { u.where = 'working'; u.held = undefined; this.onChange(); continue; }
        if (this.host.worldAt(u.cx, u.cz) || u.sheds) this.launch(u);
        continue;
      }
      const w = this.host.worldAt(u.cx, u.cz);
      const tr = w ? this.host.trafficOf(w) : null;
      if (!tr) { if (!w) this.strandedJet(u); continue; }
      this.stranded.delete(u.uid);
      // the island is full of your own cars: this one waits at base for a slot, visibly, earning nothing
      if ((perIsland.get(tr) ?? 0) >= MAX_WORKING) { u.where = 'waiting'; u.held = 'waiting for a slot'; continue; }
      if (this.launch(u)) perIsland.set(tr, (perIsland.get(tr) ?? 0) + 1);
    }
    // a slot may have opened since: anything held for one tries again next sweep
    for (const u of this.units) {
      if (u.where === 'waiting' && u.held === 'waiting for a slot') { u.where = 'shadowed'; u.held = undefined; }
    }
  }


  /** Put one crewed unit on the road on its island, where it was (or at base if it's been gone a while), mid-job if it had one. */
  private launch(u: Unit): boolean {
    const w = this.host.worldAt(u.cx, u.cz);
    const tr = w ? this.host.trafficOf(w) : null;
    const def = this.defFor(u);
    // a train runs its beat on the railway (game/railCrew.ts); one out of the sheds needs no county of its own in memory
    if ((w || u.sheds) && def.kind === 'rail') return this.launchRail(u, def);
    if (!w || !tr || def.kind === 'rail') return false;
    // a jet flies the air service, never the roads (game/jetPilots.ts)
    if (isJet(def)) return this.launchJet(u, def as AirDef);
    const stale = this.host.hours() - u.since > STALE_HOURS && u.since > 0;
    let x = u.x, z = u.z;
    // gone a while: it sets out from base again, with whatever it still carries
    if (stale && u.order.base && u.order.base.cx === w.cx && u.order.base.cz === w.cz) { x = u.order.base.x; z = u.order.base.z; }
    tr.fleet = this;
    // a load aboard with no way to its drop from here is set down by traffic (setDown), not binned
    const a = tr.launchOwned(u.uid, def, x, z, u.heading, u.run ?? null);
    if (!a) return false;
    u.agent = a; u.traffic = tr; u.run = null; u.road = null; u.held = undefined;
    u.where = 'working';
    this.onChange();
    return true;
  }

  /** A crewed jet onto the air service from its airfield; held where it stands when it can't fly from there. */
  private launchJet(u: Unit, def: AirDef): boolean {
    if (!this.jets || u.mode === 'follow') return false;
    const why = this.jets.fly(u, def);
    if (why) { this.hold(u, why); return false; }
    u.agent = null; u.traffic = null; u.run = null; u.road = null; u.held = undefined;
    u.where = 'working';
    this.onChange();
    return true;
  }

  /**
   * A crewed jet resting in a cell out of memory (launchAll, once a second): after JET_STRANDED seconds it is flown
   * home empty to an airport in memory (the user, 4 Nov 2026: jets parked out of view for good after long flights).
   * Only the unit's counter runs meanwhile; nothing is simulated where it stands.
   */
  private strandedJet(u: Unit): void {
    const def = this.defFor(u);
    if (!this.jets || !isJet(def) || u.mode === 'follow') return;
    const t = (this.stranded.get(u.uid) ?? 0) + 1;
    if (t < JET_STRANDED || !this.jets.fetch(u, def as AirDef)) { this.stranded.set(u.uid, Math.min(t, JET_STRANDED)); return; }
    this.stranded.delete(u.uid);
    u.agent = null; u.traffic = null; u.run = null; u.road = null; u.held = undefined;
    u.where = 'working';
    this.onChange();
  }

  /**
   * A unit wound down in a county now let go (docs/farfleet.html): out of sight at its base at once, rather than where
   * it stopped, so it sets out from there when its county is back (the stale rule's 4 game hours, without the wait).
   */
  private homeWound(u: Unit): void {
    if (!u.windDown || u.where !== 'shadowed') return;
    delete u.windDown;
    const b = u.order.base;
    if (b && defOf(u.model).kind !== 'rail') { u.cx = b.cx; u.cz = b.cz; u.x = b.x; u.z = b.z; }
  }

  /** A crewed train onto the line where it stands; held out of sight, with why, while it can't go on (and tried again). */
  private launchRail(u: Unit, def: VehicleDef): boolean {
    if (!this.rail) return false;
    const why = this.rail.run(u, def);
    if (why) {
      if (u.held !== why) { u.held = why; this.onChange(); }
      return false;
    }
    u.where = 'working';
    u.held = undefined;
    u.run = null; u.road = null;
    this.onChange();
    return true;
  }

  /** A crewed train's track went from memory: out of sight where it stood, back on the line when its county is in again. */
  railLost(u: Unit, at: Spot): void {
    this.standAt(u, at);
    if (u.where === 'working') { u.where = 'shadowed'; u.since = this.host.hours(); }
    this.onChange();
  }

  /** Keep a unit's record where it stands (a train's engine, as railCrew reads it). */
  private standAt(u: Unit, at: Spot): void {
    u.cx = at.cx; u.cz = at.cz; u.x = at.x; u.z = at.z; u.y = at.y; u.heading = at.heading;
  }

  /** A hired jet's sortie is over for now (its airport out of memory): out of sight where it stands, back up when it's near. */
  restJet(u: Unit): void {
    if (u.where !== 'working') return;
    u.where = 'shadowed';
    u.since = this.host.hours();
    this.onChange();
  }

  /** A crewed train's load handed in at a station on its beat (game/railCrew.ts): paid like any driver's. */
  railDelivered(u: Unit, it: CargoItem, at: { x: number; y: number; z: number }): void {
    const d = this.driverOf(u);
    if (!d) { this.cargo.uncarry(it); return; }
    const def = this.defFor(u);
    const extra = def.bonus?.ids.includes(it.type.id) ? def.bonus.share : 0;
    const r = this.cargo.deliverFleet(it, at, d.cut, d.name, d.nose === it.type.cls, extra);
    this.pay(u, d, r.you, r.kept, true, `${it.type.name} → ${it.to.name.split(' · ')[0]}`, it.type.id);
    if (r.rep) this.host.standing?.(u, r.rep);
    this.onChange();
  }

  /** A hired jet's load delivered, at a world point: paid like any driver's. */
  jetDelivered(u: Unit, it: CargoItem, at: { x: number; y: number; z: number }): void {
    const d = this.driverOf(u);
    if (!d) return;
    const def = this.defFor(u);
    const extra = def.bonus?.ids.includes(it.type.id) ? def.bonus.share : 0;
    const r = this.cargo.deliverFleet(it, at, d.cut, d.name, d.nose === it.type.cls, extra);
    this.pay(u, d, r.you, r.kept, true, `${it.type.name} → ${it.to.name.split(' · ')[0]}`, it.type.id);
    if (r.rep) this.host.standing?.(u, r.rep);
    this.onChange();
  }

  /**
   * Put an arriving unit on the road in `w` at (x, z): the last step of a convoy journey
   * (game/convoy.ts). It takes a base here and looks for work at once, its measured rate intact.
   */
  arriveAt(u: Unit, w: World, x: number, z: number, heading: number): boolean {
    u.cx = w.cx; u.cz = w.cz; u.x = x; u.z = z; u.heading = heading;
    u.road = null; u.held = undefined;
    u.since = this.host.hours();
    const b = u.order.base;
    // a base the player chose is kept, wherever the journey ended (a follower comes back to it at work)
    if (!b || (!u.order.chosen && (b.cx !== w.cx || b.cz !== w.cz))) u.order.base = this.nearestBase(u);
    // what rode along is dropped in the order that pays from here
    const r = u.run;
    if (r && r.aboard.length > 1 && !pending(r).length) {
      const d = this.driverOf(u);
      const order = solveOrder({ x: w.ox + x, z: w.oz + z }, r.aboard.map((it) => this.loadOf(it, true, d)), 1);
      u.run = runOf([...r.aboard].sort((p, q) => (order.get(p.id) ?? 0) - (order.get(q.id) ?? 0)));
    }
    u.where = 'shadowed';
    if (this.launch(u)) return true;
    // no traffic here yet (the island is still waking up): it stands where it landed until there is
    u.place = this.placeName(u);
    this.onChange();
    return false;
  }


  /**
   * Called away after the player (game/convoy.ts). Whatever the driver was on is given up at no cost
   * to anyone: nothing is fined, no mood is docked and no town books a failure. Every load aboard
   * bound for somewhere on the route is kept and delivered at the far end, in an order solved again on
   * arrival; anything else is set down where they were and goes back on the market, and every load
   * still to collect is let go. Returns false when the next call is a drop it is nearly at and would
   * rather finish first, in which case the convoy asks again in a moment.
   */
  recall(u: Unit, road: Road, onRoute: (cx: number, cz: number) => boolean): boolean {
    const a = u.agent;
    if (a && u.traffic) {
      const run = a.run;
      const s = a.state;
      const next = run?.stops[run.k];
      if (next?.kind === 'drop') {
        const it = next.item;
        const gx = a.w.ox + s.x, gz = a.w.oz + s.z;
        const leg = Math.hypot(it.to.x - it.x, it.to.z - it.z);
        // nearly there: let them finish the drop and be asked again after
        if (Math.hypot(it.to.x - gx, it.to.z - gz) <= Math.max(GRACE, leg * 0.25)) return false;
      }
      u.cx = a.w.cx; u.cz = a.w.cz; u.x = s.x; u.z = s.z; u.y = s.y; u.heading = s.heading;
      u.run = this.keepOnRoute(run?.aboard ?? [], onRoute, a.w, s.x, s.z, s.y);
      // it stays on the road: the convoy drives it from here, loads bound on its way still aboard
      u.traffic.stopForConvoy(a);
    } else if (u.where === 'shadowed' && u.run) {
      for (const it of pending(u.run)) this.cargo.release(it, -u.uid);
      u.run = this.keepOnRoute(u.run.aboard, onRoute, this.host.worldAt(u.cx, u.cz), u.x, u.z, u.y);
    }
    u.where = 'enroute';
    u.road = road;
    u.held = undefined;
    u.since = this.host.hours();
    this.onChange();
    return true;
  }

  /** Nothing can be done for it where it stands: it waits at base, crewed, and earns nothing. */
  hold(u: Unit, why: string): void {
    if (u.where === 'working' || u.where === 'ridden') return;
    u.where = 'waiting';
    u.held = why;
    u.road = null;
    this.onChange();
  }

  /** Of the loads aboard, the ones bound somewhere on the route ride along; the rest are set down here. */
  private keepOnRoute(aboard: CargoItem[], onRoute: (cx: number, cz: number) => boolean, w: World | null, x: number, z: number, y: number): Run | null {
    const keep: CargoItem[] = [];
    for (const it of aboard) {
      if (onRoute(it.to.w.cx, it.to.w.cz)) keep.push(it);
      else if (w) this.setDownAt(it, w, x, z, y);
      else this.cargo.uncarry(it);
    }
    return keep.length ? runOf(keep) : null;
  }

  /** A load a called-away driver has set down: it stands where they left it, for whoever wants it. */
  private dropLoad(u: Unit, it: CargoItem): void {
    const w = this.host.worldAt(u.cx, u.cz);
    if (w) this.setDownAt(it, w, u.x, u.z, u.y);
    else this.cargo.release(it, -u.uid);
  }

  /** A driver giving up on loads it can't deliver: each set down at the kerb where it stands, out of its hold. */
  setDownFrom(a: Agent, items: CargoItem[]): void {
    const s = a.state;
    for (const it of items) this.setDownAt(it, a.w, s.x, s.z, s.y);
    if (!a.run) return;
    a.run.aboard = a.run.aboard.filter((q) => !items.includes(q));
    a.run.used = Math.max(0, a.run.used - items.reduce((n, it) => n + it.type.units, 0));
  }

  /** Put a load down on the nearest kerb to (x, z): back on the market, with no penalty to anybody. */
  private setDownAt(it: CargoItem, w: World, x: number, z: number, y: number): void {
    const k = kerbNear(w, x, z, 14) ?? { x: Math.min(N - 0.5, Math.max(0.5, x)), z: Math.min(N - 0.5, Math.max(0.5, z)) };
    this.cargo.setDown(it, w, k.x, k.z, y);
    this.host.float(`${it.type.icon} set down`, w.ox + k.x, y + 0.5, w.oz + k.z, 'info');
  }

  /** Take the agent off the road if there is one, writing nothing back. */
  private pullAgent(u: Unit): void {
    if (this.jets?.flying(u)) for (const it of this.jets.ground(u)) this.cargo.uncarry(it);
    this.rail?.stop(u);
    if (u.agent && u.traffic) u.traffic.dropOwned(u.agent);
    u.agent = null; u.traffic = null;
  }

  /**
   * The hour has turned (n of them): moods drift and drivers who have had enough get out. Nothing is
   * paid here. A driver earns when they deliver, on screen, and a driver on the road earns nothing.
   */
  tick(n: number): void {
    const hours = this.host.hours();
    // a driver out in a fleet-mate's vehicle lives in their game (docs/sharedfleets.html)
    for (const d of this.drivers) if (!this.unit(d.unit)?.away) driftMood(d, n);
    for (const u of this.units) {
      const d = this.driverOf(u);
      if (!d || u.where === 'ridden' || u.where === 'working' || u.away) continue;
      if (d.mood > 0) continue;
      this.host.announce(d.name, `has quit · ${u.name} is parked at ${u.order.base?.name ?? 'its base'}`);
      press.write({ k: 'driverQuit', who: 'you', f: { driver: d.name, model: u.name } });
      this.quit(u, d);
    }
    // the bench: a driver left on it long enough tells you, then goes. They used to sit at nothing for good and
    // walk out the moment they were given a vehicle (the user, 20 Oct 2026)
    for (const d of [...this.bench]) {
      if (d.mood > BENCH_WARN + 0.1) d.warned = false;
      if (d.mood <= 0) {
        this.host.announce(d.name, 'has quit · tired of waiting on the bench');
        press.write({ k: 'driverQuit', who: 'you', f: { driver: d.name, model: 'the bench' } });
        this.drivers = this.drivers.filter((q) => q !== d);
      } else if (d.mood < BENCH_WARN && !d.warned) {
        d.warned = true;
        this.host.announce(d.name, 'is restless on the bench · give them a vehicle soon or they will quit');
      }
    }
    this.recent = this.recent.filter(([h]) => h > hours - 1);
    this.onChange();
  }

  /** Its measured on-screen rate, $ to you a game hour. */


  rate(u: Unit): number { return u.hours >= 0.5 ? u.paid / Math.max(1, u.hours) : 0; }

  private quit(u: Unit, d: Driver): void {
    const b = u.order.base;
    if ((u.where === 'shadowed' || u.where === 'waiting') && b && defOf(u.model).kind !== 'rail') { u.cx = b.cx; u.cz = b.cz; u.x = b.x; u.z = b.z; }
    this.benchDriver(u, false);

    this.drivers = this.drivers.filter((q) => q !== d);
  }

  /** Its record for today, begun if need be; days past the last DAY_LOG with anything in them fall off. */
  private dayEntry(u: Unit): DayLog {
    const day = Math.floor(this.host.hours() / 24);
    const days = (u.days ??= []);
    let last = days[days.length - 1];
    if (!last || last[0] !== day) {
      last = [day, 0, 0];
      days.push(last);
      if (days.length > DAY_LOG) days.splice(0, days.length - DAY_LOG);
    }
    return last;
  }

  /**
   * What it pays you a game day at work: over its last DAY_LOG days with work in them, $ to you for every 24 hours
   * it was at work (a day the game wasn't running, or it stood idle, doesn't count against it). Until it has half
   * an hour in its record, the measured rate an hour, times 24; 0 when there is nothing to go on.
   */
  dayRate(u: Unit): number {
    let earned = 0, hours = 0;
    for (const [, e, h] of u.days ?? []) { earned += e; hours += h; }
    if (hours >= 0.5) return (earned / hours) * 24;
    return this.rate(u) * 24;
  }

  /** How many game days its rate a day is over (those with work in them), for the pane's line. */
  dayRateDays(u: Unit): number { return (u.days ?? []).filter(([, , h]) => h > 0).length; }

  private pay(u: Unit, d: Driver, you: number, kept: number, onScreen: boolean, what: string, kind?: string): void {
    if (you > 0) this.host.earned?.(you, d, u, what);
    const wasAce = rankOf(d) === 'ace';
    d.deliveries++;
    deeds.add('cut', you);
    if (!wasAce && rankOf(d) === 'ace') {
      deeds.mark('aces', `${this.host.seed()}#${d.id}`);
      press.write({ k: 'driverAce', who: 'you', f: { driver: d.name }, pic: vehiclePic(u.model) });
    }
    d.kept += kept;
    d.earned = (d.earned ?? 0) + you;
    this.onKept(kept);
    u.log.deliveries++;
    u.log.earned += you;
    this.dayEntry(u)[1] += you;
    if (kind) { const k = ((u.kinds ??= {})[kind] ??= [0, 0]); k[0]++; k[1] += you; }
    this.earned += you;
    if (onScreen) {
      u.paid += you;
      this.recent.push([this.host.hours(), you]);
    }
  }

  /** The company line: units, drivers, the current rate an hour, and everything the fleet has paid. */
  company(): { units: number; drivers: number; rate: number; day: number; earned: number; towed: number; incidents: number } {
    // the units at work on screen, at their measured rate: a delivery every few game hours would read
    // as nothing most of the time if only the last hour's takings counted. Nothing else earns at all,
    // so a fleet on the road honestly shows nought an hour until it gets here.
    const real = this.units.filter((u) => u.where === 'working').reduce((s, u) => s + this.rate(u), 0);
    return {
      units: this.units.length, drivers: this.drivers.length, rate: Math.round(real),
      // a day: every crewed unit at its rate a day, wherever it is (a day's figure is over its days of work, not this minute)
      day: Math.round(this.units.filter((u) => u.driver).reduce((s, u) => s + this.dayRate(u), 0)),
      earned: Math.round(this.earned),
      towed: Math.round(this.towed), incidents: this.units.reduce((n, u) => n + u.log.incidents, 0),
    };
  }

  /** What a unit is doing, in the garage's words. */

  stateLine(u: Unit): string {
    if (u.away) return `${u.away.where === 'ridden' ? 'driven by' : u.away.where === 'working' || u.away.where === 'shadowed' ? 'working for' : 'out with'} ${u.away.name}`;
    const d = this.driverOf(u);
    switch (u.where) {
      case 'ridden': return 'riding';
      case 'garaged': return 'in the garage · off the map';
      case 'towing': return `towing · ${Math.max(1, Math.ceil(u.tow ?? 0))} s`;
      case 'working': {
        const a = u.agent;
        const r = a?.run;
        // one told to follow is not working at all: game/formation.ts says where in the line it is
        if (u.mode === 'follow') return 'following you';
        const flying = this.jets?.describe(u);
        if (flying) return flying;
        const railing = this.rail?.describe(u);
        if (railing) return railing;
        if (r && r.k < r.stops.length) {
          const next = r.stops[r.k];
          const where = (next.kind === 'pickup' ? next.item.from?.name ?? 'the roadside' : next.item.to.name).split(' · ')[0];
          const left = r.stops.length - r.k;
          return `working · ${r.aboard.length ? `${r.aboard.length} aboard` : 'empty'} · ${left} stop${left === 1 ? '' : 's'} · next: ${where}`;
        }
        if (a?.homing) return `working · heading back to ${u.order.base?.name ?? 'base'}`;
        return u.order.wait ? `waiting at ${u.order.base?.name ?? 'base'}` : 'working · looking for a load';
      }
      case 'enroute': {
        const r = u.road;
        const eta = r ? clock(roadLeft(r)) : '';
        if (!r) return 'on the road';
        if (r.slip !== undefined) return `on the ferry slip · to ${r.to} · ${eta}`;
        // r.to is the cell the player is in (its name, as the corner card has it): the journey is to them
        if (r.carried) return `being brought to you in ${r.to} · ${eta}`;
        return `on the way to you in ${r.to} · ${eta}`;
      }
      case 'waiting': return `waiting at ${u.order.base?.name ?? u.place ?? 'base'} · ${u.held ?? 'held up'}`;
      case 'shadowed':
        // a crewed train that can't go on the line yet says why
        if (d && u.held && defOf(u.model).kind === 'rail') return `waiting · ${u.held}`;
        return `${u.place ?? u.order.base?.name ?? 'away'} · ${d ? 'out of sight for a moment' : 'idle'}`;
      default: {
        // a train left uncrewed waits in the sheds, off the map (nothing draws a parked train): it comes out onto the
        // line when it is driven from beside a railway, or at a station when it is given a driver (game/railCrew.ts)
        if (defOf(u.model).kind === 'rail') return 'in the sheds · drive it from beside a railway, or give it a driver';
        const p = this.host.player();
        const tiles = p ? Math.round(Math.hypot((u.cx - p.cx) * N + u.x - p.x, (u.cz - p.cz) * N + u.z - p.z)) : 0;
        const lay = u.laidUp ? 'laid up' : 'parked';
        return `${lay} · ${u.place ?? 'somewhere'}, ${tiles} tile${tiles === 1 ? '' : 's'}`;
      }
    }
  }


  /** The nearest named place to a unit, if its island is in memory. */
  placeName(u: Unit): string {
    const w = this.host.worldAt(u.cx, u.cz);
    if (!w) return u.place ?? 'somewhere';
    let best = w.continent ? `${w.name}` : w.name, bestD = 60;
    for (const t of w.towns) {
      const d = Math.hypot(t.x0 + t.size / 2 - u.x, t.z0 + t.size / 2 - u.z) - t.size / 2;
      if (d < bestD) { bestD = d; best = t.name; }
    }
    for (const p of w.ports) {
      const d = Math.hypot(p.x - u.x, p.z - u.z) - 6;
      if (d < bestD) { bestD = d; best = p.name; }
    }
    return best;
  }

  // ---- FleetBrain: what traffic asks about a working unit ----

  private ofAgent(a: Agent): { u: Unit; d: Driver } | null {
    const u = this.unit(a.owner);
    const d = u ? this.driverOf(u) : null;
    return u && d ? { u, d } : null;
  }

  /**
   * The manifest (docs/manifests.html): the loads the picker ranks for this order and driver, packed by
   * the solver into the round that pays best, as many as the driver's rank and the cut allow and the
   * hold takes. With a run under way (an ace's top-up) it may add one load, on the end.
   */
  manifest(a: Agent, pace: number, ok: (it: CargoItem) => boolean, run: Run | null): Manifest | null {
    const o = this.ofAgent(a);
    if (!o) return null;
    const { u, d } = o;
    const here = { x: a.w.ox + a.state.x, z: a.w.oz + a.state.z };
    const rest = run ? run.stops.slice(run.k) : [];
    const inRun = new Set(rest.map((s) => s.item)).size;
    // the fleet never corners the board: the first load is always allowed, every one after needs room
    const room = this.cargo.fleetRoom(a.w);
    const maxLoads = Math.min(packOf(d, u.order, a.def.capacity), run ? inRun + (room > 0 ? 1 : 0) : Math.max(1, room));
    if (maxLoads <= inRun) return null;
    // the drive to fresh goods is scored from the last call already planned
    const from = rest.length ? stopAt(rest[rest.length - 1]) : here;
    const home = u.order.base ?? { cx: a.w.cx, cz: a.w.cz };
    // a load a town is holding for another carrier's first refusal waits (docs/rivals.html)
    let jobs = this.cargo.items.filter((it) => !it.claimedBy && !it.type.heli && !it.type.jet && !it.type.sub && it.ttl > 20 && !this.cargo.refused(it, 'you'));
    // a boat works the harbours of its own cell (traffic.ts): the rest would only crowd its short list
    if (a.def.kind === 'water') jobs = jobs.filter((it) => seaLoadIn(a.w, it));
    // what this look was offered: only work beyond it has the driver look again before its next look (fresh)
    if (!run) this.offered.set(u.uid, { x: here.x, z: here.z, ids: new Set(jobs.map((it) => it.id)) });
    // sent for a town's loads from its card: those first, if any of them will do
    if (u.lure && !run) {
      const lure = u.lure;
      u.lure = undefined;
      const there = jobs.filter((it) => { const f = this.books.townFor(it.from); return !!f && townKey(f.w, f.t) === lure; });
      if (pickJobs(u.order, d, a.def, there, from, home, (it) => this.books.taxOf(it), canHaul).length) jobs = there;
    }
    let picked = pickJobs(u.order, d, a.def, jobs, from, home, (it) => this.books.taxOf(it), canHaul);
    if (!picked.length) return null;
    // a big hold also looks where the best pick goes: work waiting there chains onto the run (Oct 2026)
    const roomy = holdLoads(a.def.capacity) > 0;
    if (roomy) {
      const on = pickJobs(u.order, d, a.def, jobs, picked[0].to, home, (it) => this.books.taxOf(it), canHaul);
      picked = [...picked, ...on.filter((it) => !picked.includes(it))];
    }
    const byId = new Map<number, CargoItem>();
    for (const it of [...rest.map((s) => s.item), ...picked]) byId.set(it.id, it);
    const aboard = new Set(run?.aboard ?? []);
    const calls: Call[] = rest.map((s) => ({ kind: s.kind, load: this.loadOf(s.item, aboard.has(s.item), d) }));
    const plan = solveRun(here, calls, picked.map((it) => this.loadOf(it, false, d)),
      { capacity: a.def.capacity, used: run?.used ?? 0, maxLoads, pace, cut: d.cut, roomy },
      { ok: (l) => ok(byId.get(l.id)!), tail: !!run });
    if (!plan || (run && plan.calls.length === rest.length)) return null;
    const stops: Stop[] = plan.calls.map((c, n) => ({ kind: c.kind, item: byId.get(c.load.id)!, held: plan.held[n], pays: Math.round(plan.pays[n]) }));
    // a look that found work passed nothing over for good: when the run is done (or given up) the board is new to it
    if (!run) this.offered.delete(u.uid);
    return { stops, tiles: plan.tiles, seconds: plan.seconds, eta: plan.eta };
  }

  /** A load as the solver sees it: the driver's nose adds a tenth, as it does on delivery. */
  /**
   * What a load aboard one of yours pays at its drop `secs` from now, after the towns' levy and before the driver's
   * cut: a road manifest's figure, for a hired jet's bubble and card (game/jetPilots.ts has no manifest).
   */
  dropPays(u: Unit, it: CargoItem, secs: number): number {
    const l = this.loadOf(it, true, this.driverOf(u));
    return Math.round(valueAfter(l, secs) * (1 - l.tax));
  }

  private loadOf(it: CargoItem, aboard: boolean, d: Driver | null): Load {
    const nose = d && d.nose === it.type.cls ? 1.1 : 1;
    return {
      id: it.id, px: it.x, pz: it.z, dx: it.to.x, dz: it.to.z, units: it.type.units,
      value: it.value * nose, value0: it.value0 * nose, decay: URGENCY[it.urgency].decay,
      tax: this.books.taxOf(it), ttl: it.ttl, aboard,
    };
  }

  /** Each working unit's last look: where it stood and the loads it was offered (by id), for fresh. */
  private offered = new Map<number, { x: number; z: number; ids: Set<number> }>();

  /**
   * Is there a load within FRESH_NEAR this idle driver could take (its hold, its order, nobody's claim or
   * first refusal) that its last look was not offered (or was offered somewhere else, FRESH_MOVED away)? Then it looks again now (traffic.ts peek): the
   * idle-fleet study (Oct 2026) had drivers standing up to ASK_EVERY seconds beside work that turned up for
   * somebody else, was let go by another driver, or came out of a town's first refusal.
   */
  fresh(a: Agent): boolean {
    const o = this.ofAgent(a);
    if (!o) return false;
    const { u, d } = o;
    const x = a.w.ox + a.state.x, z = a.w.oz + a.state.z;
    // somewhere else since (a run, a tow, the drive home): the board round it is new to it, whatever it saw there
    const last = this.offered.get(u.uid);
    const seen = last && Math.hypot(last.x - x, last.z - z) <= FRESH_MOVED ? last.ids : null;
    const home = u.order.base ?? { cx: a.w.cx, cz: a.w.cz };
    for (const it of this.cargo.items) {
      if (it.claimedBy || it.type.heli || it.type.jet || it.type.sub || it.ttl <= 20 || seen?.has(it.id)) continue;
      if (Math.hypot(it.x - x, it.z - z) > FRESH_NEAR) continue;
      if (a.def.kind === 'water' && !seaLoadIn(a.w, it)) continue;
      if (this.cargo.refused(it, 'you') || !canHaul(a.def, it) || !allows(u.order, d, a.def, it, home)) continue;
      return true;
    }
    return false;
  }

  setDown(a: Agent, it: CargoItem): void {
    this.setDownAt(it, a.w, a.state.x, a.state.z, a.state.y);
    this.onChange();
  }

  runDone(a: Agent, r: Run): void {
    if (!this.ofAgent(a)) return;
    // deeds: the most aboard at once, the most dropped in one round, and a round where nothing spoiled
    deeds.best('fullLoad', r.peak);
    if (r.delivered) {
      deeds.best('milkRound', r.delivered);
      if (r.clean) deeds.add('nothingWasted');
    }
    this.onChange();
  }

  tops(a: Agent): boolean {
    const o = this.ofAgent(a);
    return !!o && rankOf(o.d) === 'ace';
  }

  claimed(a: Agent, it: CargoItem): void {
    const o = this.ofAgent(a);
    if (o) it.claimName = `${o.d.name} in ${o.u.name}`;
    this.onChange();
  }

  delivered(a: Agent, it: CargoItem): void {
    const o = this.ofAgent(a);
    if (!o) return;
    const at = { x: a.w.ox + a.state.x, y: a.state.y, z: a.w.oz + a.state.z };
    // a faction model's knack for its own work (docs/factions.html)
    const extra = a.def.bonus?.ids.includes(it.type.id) ? a.def.bonus.share : 0;
    const r = this.cargo.deliverFleet(it, at, o.d.cut, o.d.name, o.d.nose === it.type.cls, extra);
    this.pay(o.u, o.d, r.you, r.kept, true, `${it.type.name} → ${it.to.name.split(' · ')[0]}`, it.type.id);
    if (r.rep) this.host.standing?.(o.u, r.rep);
    this.onChange();
  }

  stuck(a: Agent): 'retry' | 'tow' {
    const o = this.ofAgent(a);
    if (!o) return 'tow';
    if (rankOf(o.d) === 'ace') return 'retry';
    const sortsItOut = o.d.temper === 'careful' ? 0.5 : o.d.temper === 'steady' ? 0.25 : 0;
    return Math.random() < sortsItOut ? 'retry' : 'tow';
  }

  base(a: Agent): { x: number; z: number; cx: number; cz: number } | null {
    const b = this.unit(a.owner)?.order.base;
    const w = b ? this.host.worldAt(b.cx, b.cz) : null;
    return b && w ? { x: w.ox + b.x, z: w.oz + b.z, cx: b.cx, cz: b.cz } : null;
  }

  pace(a: Agent): number {
    const o = this.ofAgent(a);
    if (!o) return 1;
    const own = TEMPER[o.d.temper].pace + MODES[modeOf(o.d.cut)].pace + 0.04 * ['rookie', 'regular', 'veteran', 'ace'].indexOf(rankOf(o.d));
    // catching a line up is not an errand: a driver told to follow you hurries after it
    return o.u.mode === 'follow' ? own * 1.35 : own;
  }

  idleLimit(a: Agent): number {
    const o = this.ofAgent(a);
    if (!o) return Infinity;
    const m = modeOf(o.d.cut);
    return m === 'hustle' ? Infinity : m === 'steady' ? MODES.steady.idle * SECONDS_PER_HOUR : 0;
  }

  // (winding down in a county about to be let go: it finishes what is aboard and takes nothing more)
  waiting(a: Agent): boolean { const u = this.unit(a.owner); return !!u?.order.wait || !!u?.windDown; }

  quits(a: Agent): boolean {
    const o = this.ofAgent(a);
    return !o || o.d.mood <= 0;
  }

  suspend(a: Agent): void {
    const u = this.unit(a.owner);
    if (!u) return;
    const s = a.state;
    u.cx = a.w.cx; u.cz = a.w.cz; u.x = Math.min(N - 0.5, Math.max(0.5, s.x)); u.z = Math.min(N - 0.5, Math.max(0.5, s.z)); u.y = s.y; u.heading = s.heading;
    u.agent = null; u.traffic = null;
    // one on the road after the player is still on it: the convoy puts it back where it was
    if (u.where === 'enroute') { this.onChange(); return; }
    u.where = 'shadowed';
    u.since = this.host.hours();
    u.run = null;
    const run = a.run;
    if (run) {
      // goods still to collect are let go, and claimed again on return if nobody else has them; loads
      // aboard stay in the hold, ticking down, and nobody pays for them until they arrive
      for (const it of pending(run)) this.cargo.release(it, -u.uid);
      run.stops = run.stops.slice(run.k).map((st) => ({ kind: st.kind, item: st.item, held: st.held, pays: st.pays }));
      run.k = 0;
      u.run = run.stops.length ? run : null;
    }
    this.onChange();
  }


  released(a: Agent, why: 'quit' | 'tow', reason = 'gave up'): void {
    const o = this.ofAgent(a);
    const tr = o?.u.traffic;
    if (!o || !tr) return;
    const { u, d } = o;
    const s = a.state, gx = a.w.ox + s.x, gz = a.w.oz + s.z;
    if (why === 'quit') {
      this.host.announce(d.name, `has quit · ${u.name} is parked where they left it`);
      press.write({ k: 'driverQuit', who: 'you', f: { driver: d.name, model: u.name } });
      this.quit(u, d);
      return;
    }
    // an incident: towed to base at the tow's rate; every load aboard is set down where it happened,
    // back on the market and nobody fined — the tow bill is the cost
    const b = u.order.base;
    const bw = b ? this.host.worldAt(b.cx, b.cz) : null;
    const tiles = b && bw ? Math.round(Math.hypot(bw.ox + b.x - gx, bw.oz + b.z - gz)) : 0;
    const fee = rankOf(d) === 'ace' ? 0 : Math.min(TOW_CAP, TOW_BASE + TOW_PER_TILE * tiles);
    if (a.run) {
      for (const it of a.run.aboard) this.setDownAt(it, a.w, s.x, s.z, s.y);
      a.run.aboard = [];
    }
    if (fee) this.wallet.fine(fee, 'fines');
    u.log.incidents++;
    d.incidents = (d.incidents ?? 0) + 1;
    u.log.towed += fee;
    this.towed += fee;
    // what it was doing when it gave up, for the incident log: the fleet window and pr.fleet.tows()
    const run = a.run;
    const stop = run && run.k < run.stops.length ? run.stops[run.k] : null;
    const doing = a.homing ? `heading back to ${u.order.base?.name ?? 'base'}`
      : stop ? `${stop.kind === 'pickup' ? 'going for' : 'delivering'} ${stop.item.type.name}`
        : 'looking for a load';
    this.note({
      hour: this.host.hours(), uid: u.uid, unit: u.name, model: u.model, driver: d.name,
      rank: rankOf(d), temper: d.temper, reason, doing, fee,
      place: this.placeName({ ...u, cx: a.w.cx, cz: a.w.cz, x: s.x, z: s.z }),
      cell: [a.w.cx, a.w.cz], x: Math.round(s.x * 10) / 10, z: Math.round(s.z * 10) / 10,
    });
    this.host.announce(d.name, `towed · ${reason} · ${money(fee)}`);
    if (fee) press.write({ k: 'towed', who: 'you', at: { x: gx, z: gz }, f: { driver: d.name, fee, reason } });
    this.host.float(`−${money(fee)} tow · ${d.name}`, gx, s.y + 0.4, gz, 'fine');
    const nearHome = (w: World) => w === a.w || a.w.nbr.includes(w);
    if (b && bw && nearHome(bw)) tr.relocate(a, bw, b.x, b.z);
    else if (b && bw) {
      tr.dropOwned(a);
      u.agent = null; u.traffic = null;
      u.cx = b.cx; u.cz = b.cz; u.x = b.x; u.z = b.z;
      u.where = 'shadowed';
      u.since = this.host.hours();
    } else tr.relocate(a, a.w, s.x, s.z);

    this.onChange();
  }

  /**
   * A wrecker has hauled one of ours clear and let it go on the road (Traffic's tows): the call-out and
   * the haul at the tow's rate — half that while the fleet owns a tow truck of its own, nothing for an
   * ace — and the incident, logged like any tow. It keeps its loads and carries on.
   */
  towBill(a: Agent, tiles: number, reason: string): void {
    const o = this.ofAgent(a);
    if (!o) return;
    const { u, d } = o;
    const s = a.state, gx = a.w.ox + s.x, gz = a.w.oz + s.z;
    const cut = Math.max(0, ...this.units.map((q) => defOf(q.model).wrecker ?? 0));
    const fee = rankOf(d) === 'ace' ? 0 : Math.round(Math.min(TOW_CAP, TOW_BASE + TOW_PER_TILE * tiles) * (1 - cut));
    if (fee) this.wallet.fine(fee, 'fines');
    u.log.incidents++;
    d.incidents = (d.incidents ?? 0) + 1;
    u.log.towed += fee;
    this.towed += fee;
    const run = a.run;
    const stop = run && run.k < run.stops.length ? run.stops[run.k] : null;
    const doing = a.homing ? `heading back to ${u.order.base?.name ?? 'base'}`
      : stop ? `${stop.kind === 'pickup' ? 'going for' : 'delivering'} ${stop.item.type.name}`
        : 'looking for a load';
    this.note({
      hour: this.host.hours(), uid: u.uid, unit: u.name, model: u.model, driver: d.name,
      rank: rankOf(d), temper: d.temper, reason, doing, fee,
      place: this.placeName({ ...u, cx: a.w.cx, cz: a.w.cz, x: s.x, z: s.z }),
      cell: [a.w.cx, a.w.cz], x: Math.round(s.x * 10) / 10, z: Math.round(s.z * 10) / 10,
    });
    this.host.announce(d.name, `towed clear · ${reason} · ${money(fee)}`);
    if (fee) press.write({ k: 'towed', who: 'you', at: { x: gx, z: gz }, f: { driver: d.name, fee, reason } });
    if (fee) this.host.float(`−${money(fee)} tow · ${d.name}`, gx, s.y + 0.4, gz, 'fine');
    this.onChange();
  }

  /**
   * A vehicle the fleet is driving rather than the driver: on the road after the player, or in
   * formation behind them. Either way it takes no work, never heads for base, and is never towed for
   * failing to get somewhere — the convoy or the formation decides what happens to it.
   */
  convoying(a: Agent): boolean {
    const u = this.unit(a.owner);
    return !!u && (u.where === 'enroute' || u.mode === 'follow' || !!u.rushing);
  }

  /** Set by game/convoy.ts: what happens to one of its vehicles that can find no way on. */
  onConvoyStuck: ((u: Unit) => void) | null = null;

  convoyStuck(a: Agent): void {
    const u = this.unit(a.owner);
    if (u) this.onConvoyStuck?.(u);
  }

  /** A driver past rookie who isn't the careful sort uses the nitrous and the handbrake fitted to their vehicle. */
  tricks(a: Agent): { nitrous: boolean; drift: boolean } {
    const o = this.ofAgent(a);
    return o ? tricksOf(o.d) : { nitrous: false, drift: false };
  }

  /**
   * The unit's own nitrous bottles, for its hired driver to fire: the same bottles the player fires with
   * Shift, filled on the same clock, so twin bottles are two bursts for the driver too (the user, 15 Oct 2026).
   */
  agentBottles(a: Agent): number[] | null {
    const u = this.unit(a.owner);
    return u && this.defFor(u).nitrous ? this.bottles(u) : null;
  }

  odometer(a: Agent, tiles: number): void {
    const u = this.unit(a.owner);
    if (u) u.log.tiles += tiles;
    const d = u ? this.driverOf(u) : null;
    if (d) d.tiles = (d.tiles ?? 0) + tiles;
    this.driven.hired += tiles;
  }

  // ---- saving ----

  toSave(): FleetSave {
    const r1 = (v: number) => Math.round(v * 10) / 10;
    return {
      units: this.units.map((u): SavedUnit => {
        const a = u.agent;
        const at = a ? { cx: a.w.cx, cz: a.w.cz, x: a.state.x, z: a.state.z, y: a.state.y, h: a.state.heading } : { cx: u.cx, cz: u.cz, x: u.x, z: u.z, y: u.y, h: u.heading };
        // a journey is not written down: on load everyone stands where they had got to and the first
        // settle sends them on again, which is cheaper than saving a route and never wrong
        // a fleet-mate's vehicle is kept in this career as garaged: the shared fleet's own record has it as it is
        const where: SavedUnit['where'] = u.away || u.where === 'garaged' ? 'garaged' : u.where === 'ridden' ? 'ridden' : u.driver ? 'shadowed' : 'parked';
        return {

          uid: u.uid, model: u.model, name: u.name, cell: [at.cx, at.cz],
          x: r1(at.x), z: r1(at.z), y: r1(at.y), h: Math.round(at.h * 100) / 100,
          where, driver: u.driver, order: !u.order.base && u.order.preset === 'anything' && !u.order.wait ? undefined : u.order,
          log: [Math.round(u.log.tiles), u.log.deliveries, Math.round(u.log.earned), u.log.incidents, Math.round(u.log.towed)],
          paid: Math.round(u.paid), hours: r1(u.hours), since: u.where === 'working' ? r1(this.host.hours()) : r1(u.since),
          origin: u.origin, place: u.place, parts: packParts(u.parts), laidUp: u.laidUp || undefined,
          follow: u.mode === 'follow' || undefined,
          ...(u.far && u.driver ? { far: u.far } : {}),
          ...(u.days?.length ? { days: u.days.map(([d, e, h]): DayLog => [d, Math.round(e), Math.round(h * 100) / 100]) } : {}),
          ...(u.kinds && Object.keys(u.kinds).length ? { kinds: Object.fromEntries(Object.entries(u.kinds).map(([k, [n, e]]) => [k, [n, Math.round(e)]])) } : {}),
        };
      }),
      drivers: this.drivers.map((d) => ({ ...d, mood: Math.round(d.mood * 1000) / 1000, kept: Math.round(d.kept) })),
      hires: this.hires, ride: this.ride, next: this.nextUid, nextDriver: this.nextDriver,
      earned: Math.round(this.earned), towed: Math.round(this.towed),
      hq: this.hq, charter: this.charter, bought: this.bought,
      driven: [Math.round(this.driven.you), Math.round(this.driven.hired)],
      ...(this.gild ? { gild: this.gild } : {}),
      ...(this.hqStyle ? { hqStyle: this.hqStyle } : {}),
      ...(this.emblem ? { emblem: this.emblem } : {}),
      ...(Object.keys(this.dress).length ? { dress: { ...this.dress } } : {}),
    };
  }


  fromSave(s: FleetSave): void {
    this.clear();
    this.units = s.units.map((v): Unit => ({
      uid: v.uid, model: v.model, name: v.name, cx: v.cell[0], cz: v.cell[1], x: v.x, z: v.z, y: v.y, heading: v.h,
      where: v.where === 'ridden' ? 'ridden' : v.where === 'garaged' ? 'garaged' : v.driver ? 'shadowed' : 'parked',
      // a version 9 order has no packing dial: it packs the hold
      driver: v.driver, order: v.order ? { ...v.order, pack: v.order.pack ?? 'some' } : preset('anything', null),

      log: { tiles: v.log[0], deliveries: v.log[1], earned: v.log[2], incidents: v.log[3], towed: v.log[4] ?? 0 },
      paid: v.paid, hours: v.hours, since: v.since, origin: v.origin, place: v.place,
      parts: unpackParts(v.parts), laidUp: v.laidUp, mode: v.follow ? 'follow' : 'work',
      ...(v.far && v.driver ? { far: v.far } : {}),
      ...readHistory(v),
      // a version 8 save's units were on the books: they stand where they were, drivers still in them
      road: null,
    }));

    this.drivers = s.drivers.map((d) => ({ ...d }));
    // a save from before the bench could be left: anyone already at nothing there is told of first, not gone at once
    for (const d of this.drivers) if (!d.unit && d.mood <= 0 && d.warned === undefined) d.mood = BENCH_WARN - 0.01;
    this.hires = s.hires ?? { day: -1, taken: [] };
    this.ride = s.ride;
    this.nextUid = s.next;
    this.nextDriver = s.nextDriver;
    this.earned = s.earned ?? 0;
    this.towed = s.towed ?? 0;
    this.driven = { you: s.driven?.[0] ?? 0, hired: s.driven?.[1] ?? 0 };
    // an HQ from before grades (version 18 and older) is dropped: make one again (docs/hq.html)
    this.hq = s.hq && typeof s.hq.grade === 'number' ? s.hq : null;
    // an HQ saved as a "+" tier (Establishment+) is the plain tier above now, with at least the slots it had
    if (this.hq?.plus) {
      const g = Math.min(7, this.hq.grade + 1) as Exclude<Grade, 0>;
      this.hq = { ...this.hq, grade: g, plus: false, slots: Math.max(this.hq.slots, HQ_GRADES[g].slots) };
    }
    this.charter = s.charter ?? 0;
    this.gild = s.gild === 1 || s.gild === 2 ? s.gild : 0;
    this.hqStyle = typeof s.hqStyle === 'string' ? s.hqStyle : null;
    this.emblem = typeof s.emblem === 'string' ? s.emblem : null;
    this.dress = {};
    for (const k of DRESS_KINDS) { const v = s.dress?.[k]; if (typeof v === 'string' && /^[A-Za-z0-9:]{1,32}$/.test(v)) this.dress[k] = v; }
    this.hqDown = false;
    // more out than the HQ opens slots for (or any at all, with none): the rest wait in the garage
    this.settle();
    this.onChange();
    this.bought = s.bought ?? Math.max(0, this.units.length - 1);
  }

  // ---- shared fleets (docs/sharedfleets.html, src/net/crew.ts) ----

  /** Why a fleet-mate's vehicle can't be touched here, or null. */
  lockedWhy(u: Unit): string | null { return u.away ? `${u.name} is out with ${u.away.name}: it is theirs to drive until they park it in the garage or sign out` : null; }

  /** The uid of the vehicle ridden, and the ids the next vehicle and driver will take. */
  get rideUid(): number { return this.ride; }
  get ids(): { unit: number; driver: number } { return { unit: this.nextUid, driver: this.nextDriver }; }
  /** Number the next vehicles and drivers from these on (each member of a shared fleet counts in a range of its own). */
  setIds(unit: number, driver: number): void { this.nextUid = unit; this.nextDriver = driver; }

  /**
   * A vehicle as a shared fleet has it, put into this game: in place of the one with its uid (its agent off the
   * road first) or as a new one. `away`: another member's game drives it, so this one only lists it.
   */
  adopt(v: SavedUnit, away: { by: string; name: string } | null): Unit {
    const at = this.units.find((q) => q.uid === v.uid);
    if (at) this.pullAgent(at);
    const fresh: Unit = {
      uid: v.uid, model: v.model, name: v.name, cx: v.cell[0], cz: v.cell[1], x: v.x, z: v.z, y: v.y, heading: v.h,
      where: away ? 'waiting' : v.where === 'garaged' ? 'garaged' : v.where === 'ridden' && this.ride === v.uid ? 'ridden' : v.driver ? 'shadowed' : 'parked',
      driver: v.driver, order: v.order ? { ...v.order, pack: v.order.pack ?? 'some' } : preset('anything', null),
      log: { tiles: v.log[0], deliveries: v.log[1], earned: v.log[2], incidents: v.log[3], towed: v.log[4] ?? 0 },
      paid: v.paid, hours: v.hours, since: v.since, origin: v.origin, place: v.place,
      parts: unpackParts(v.parts), laidUp: v.laidUp, mode: v.follow ? 'follow' : 'work', road: null,
      ...readHistory(v),
      ...(away ? { away: { ...away, where: v.where } } : {}),
    };
    let u: Unit;
    if (at) {
      for (const k of Object.keys(at) as (keyof Unit)[]) if (!(k in fresh)) delete at[k];
      u = Object.assign(at, fresh);
    } else { u = fresh; this.units.push(u); }
    this.onChange();
    return u;
  }

  /** A vehicle the shared fleet no longer has (sold by a fleet-mate): gone from this game too. */
  drop(uid: number): void {
    const u = this.units.find((q) => q.uid === uid);
    if (!u || u.where === 'ridden') return;
    this.pullAgent(u);
    this.units = this.units.filter((q) => q !== u);
    for (const d of this.drivers) if (d.unit === uid) d.unit = 0;
    this.onChange();
  }

  /** Give a vehicle another uid (its driver and the ride follow): one this game made that clashes with the shared fleet's. */
  renumber(u: Unit, uid: number): void {
    const was = u.uid;
    for (const d of this.drivers) if (d.unit === was) d.unit = uid;
    if (this.ride === was) this.ride = uid;
    u.uid = uid;
    this.onChange();
  }

  /** The shared fleet's HQ, terms and hires, laid in without a word (the HQ's own card is for buying one). */
  adoptMeta(m: { hq?: unknown; charter?: number; hires?: { day: number; taken: number[] }; bought?: number }): void {
    if ('hq' in m) { const h = m.hq as Hq | null; this.hq = h && typeof h.grade === 'number' ? h : null; if (!this.hq) this.hqDown = false; }
    if (typeof m.charter === 'number') this.charter = m.charter;
    if (m.hires && Array.isArray(m.hires.taken)) this.hires = { day: m.hires.day, taken: [...m.hires.taken] };
    if (typeof m.bought === 'number') this.bought = m.bought;
    this.onChange();
  }

  /** Console: one line a unit. */
  list(): string[] {
    return this.units.map((u) => {
      const d = this.driverOf(u);
      return `${u.uid} ${u.name} (${u.model}) ${this.stateLine(u)} · cell ${u.cx},${u.cz} @ ${u.x.toFixed(1)},${u.z.toFixed(1)}${d ? ` · ${d.name} ${Math.round(d.cut * 100)}% mood ${d.mood.toFixed(2)} ${rankOf(d)}` : ''} · ${u.log.deliveries} deliveries $${Math.round(u.log.earned)} · rate $${this.rate(u).toFixed(0)}/h`;
    });
  }
}

/** A drivable road tile near (x, z) in w, within r tiles, the nearest to the middle; null when there is none. */
export function kerbNear(w: World, x: number, z: number, r: number, taken: { x: number; z: number }[] = []): { x: number; z: number } | null {
  let best: { x: number; z: number } | null = null, bestD = Infinity;
  const x0 = Math.floor(x), z0 = Math.floor(z);
  for (let tz = z0 - r; tz <= z0 + r; tz++) {
    for (let tx = x0 - r; tx <= x0 + r; tx++) {
      if (!inB(tx, tz)) continue;
      const i = idx(tx, tz);
      if (!w.road[i] || w.blocked[i] || w.water[i] >= 0 || w.deckAxis[i]) continue;
      const px = tx + 0.5, pz = tz + 0.5;
      if (taken.some((t) => Math.hypot(t.x - px, t.z - pz) < 2.5)) continue;
      const d = Math.hypot(px - x, pz - z);
      if (d < bestD) { bestD = d; best = { x: px, z: pz }; }
    }
  }
  return best;
}

/** Open water just off a harbour's pier, where a boat can wait. */
function waterNear(w: World, p: { root: number; dir: number }): { x: number; z: number } | null {
  const rx = p.root % N, rz = (p.root - rx) / N;
  const [dx, dz] = DIRS[p.dir];
  for (let k = 6; k < 20; k++) {
    for (const side of [3, -3, 4, -4]) {
      const x = rx + dx * k + dz * side, z = rz + dz * k + dx * side;
      if (inB(x, z) && w.water[idx(x, z)] >= 0) return { x: x + 0.5, z: z + 0.5 };
    }
  }
  return null;
}

