/** The model a building draws: a kind with alternative models draws one of them, picked by the building's own seed (buildings/variants). */
/**
 * The model a building draws: the 0.7.0 places' own first (render/buildings/models070.ts, only with NEXT_WORLD), then its
 * seed's variant, then the kind's own. The style must be set first (setStyle): the swaps and the variants both read it.
 */
BASE070.draw = DRAW;
export const drawOf = (b: Building, t: Town | null = null, w: World | null = null): Draw => (NEXT_WORLD ? swap070(b, t, w) : null) ?? variantDraw(b) ?? DRAW[b.kind];

/** The game clock in hours (days × 24 + hour), for whether a newly grown building is still going up. */
let townClock = 0;
export function setTownClock(hours: number): void { townClock = hours; }
/** How long a town's new building takes to go up, in game hours: render/construction.ts draws the site meanwhile. */
export const BUILD_HOURS = 2;
/** How far along a grown building is, 0 to 1 (and past 1 once done); 1 for anything that was always there. A fleet's construction runs its own hours (docs/blueprints.html). */
export const builtShare = (b: Building, hours = townClock): number => b.grownAt === undefined ? 1 : Math.max(0, (hours - b.grownAt) / (b.buildHours ?? BUILD_HOURS));

export function drawBuilding(k: Kit, b: Building, town: Town | null): void {
  for (const steps = drawBuildingSteps(k, b, town); !steps.next().done;) { /* all at once */ }
}

/**
 * drawBuilding in three steps, for the chunk streamer (townChunkSteps): the model, then its faces settled, then
 * its pieces split for the x-ray. The big models (a fairground, a drive-in, the Great Wall) took 30–60 ms on a fast
 * machine in one go, the half of it in the two passes after the drawing, and a slow machine's frame paid three to
 * five times that (the 330 ms "chunks" freezes in the play reports, 7 Nov 2026). Between the steps only this kit
 * is touched (its buffers, glow id and mode), so another chunk built meanwhile can't disturb it.
 */
export function* drawBuildingSteps(k: Kit, b: Building, town: Town | null): Generator<void, void> {
  drawing = b.kind;
  const dressed = styleOf(k.world, b);
  // its town as the models read it: in the dressed style, so a model asking its town's style agrees
  const t = dressed && town ? { ...town, style: dressed } : town;
  // a half-timbered building picks its beam colour from its own seed, so a street isn't all one oak
  // (an HQ dressed in another style by its fleet's Architect's Eye, render/buildingStyle.ts, before its own)
  const style = dressed ?? b.style ?? t?.style ?? 'classic';
  setStyle(style, ((b.seed >>> 0) % 997) / 997);
  // in a Las Vegas only what fronts the Strip is lit up: the rest is plain stucco
  if (style === 'vegas') setOffStrip(!frontsStrip(k.world, b));
  // still going up: the construction layer draws the site, and the chunk is drawn again once it is done
  if (builtShare(b) < 1) { setParts(k.world, b.uid, null); return; }
  const alongZ = b.facing % 2 === 1;
  k.mode = b.derelict ? 'derelict' : null;
  k.place(b.x + b.w / 2, b.level * STEP, b.z + b.d / 2, Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]));
  k.glow.id = b.uid * PART_SLOTS; // walls and windows both tagged, so the whole building fades together
  const t0 = k.pos.length / 9, g0 = k.glow.pos.length / 9, d0 = k.detailCount;
  const W = alongZ ? b.w : b.d, D = alongZ ? b.d : b.w;
  drawOf(b, t, k.world)(k, W, D, b, mulberry32(b.seed), t);
  // a style's signs, fire escapes and water tanks go on every street building, whichever model it draws
  if (NEON_KINDS.has(b.kind) && !b.derelict) styleDress(k, mulberry32(b.seed ^ 0x6e656f6e), W, D, Math.max(1, b.floors));
  // a helipad wherever the table says one is, so the paint and the pickup point agree
  const pad = padLocal(b, W, D);
  if (pad) helipadMark(k, pad);
  // a fleet's HQ in the fleet's livery
  // a faction's plain buildings in its colours (docs/factions.html), unless a fleet owns and paints it
  const livery = liveryOf(k.world, b) ?? (b.derelict ? null : BUILDING_PAINT[b.kind] ?? null);
  if (livery) repaint(k.pos, k.col, t0, livery);
  k.mode = null;
  const big = Math.max(b.w, b.d) >= SPLIT_MIN;
  // a small building's passes are quick: done in the same step as its drawing
  if (big) yield;
  // faces drawn flush on one another in different colours would flash as the camera moves: lift the later ones a hair
  k.settle(t0, d0);
  // ...unless it is big enough to be several things (a pyramid and its avenue of obelisks), which fade apart
  if (big) { yield; splitParts(k, k.world, b.uid, b.level * STEP, t0, g0); }
  else setParts(k.world, b.uid, null);
  k.glow.id = -1;
}

/**
 * A building put up as scenery (world/scenery.ts follyLot): the kind's model on its lot, in the style of the town
 * whose ground it is on, nothing else: no deed, no parts to fade apart, no livery, lit windows as any building's.
 */
export function drawFolly(k: Kit, w: World, q: Placed): void {
  const lot = follyLot(q);
  if (!lot) return;
  const ti = idx(Math.min(N - 1, Math.max(0, Math.floor(q.x))), Math.min(N - 1, Math.max(0, Math.floor(q.z))));
  const t = w.townId[ti] >= 0 ? w.towns[w.townId[ti]] ?? null : null;
  const seed = (Math.floor(q.x * 8) * 73856093) ^ (Math.floor(q.z * 8) * 19349663) ^ 0x5eed;
  const level = Math.round(heightAt(w, q.x, q.z) / STEP);
  const b: Building = { kind: lot.kind as BuildingKind, x: lot.x, z: lot.z, w: lot.w, d: lot.d, facing: lot.facing, floors: lot.size.floors, seed: seed >>> 0, solid: lot.size.solid, level, uid: -1 };
  setStyle(t?.style ?? 'classic', ((b.seed >>> 0) % 997) / 997);
  const alongZ = b.facing % 2 === 1;
  k.mode = null;
  k.glow.id = -1;
  k.place(b.x + b.w / 2, level * STEP, b.z + b.d / 2, Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]));
  const t0 = k.pos.length / 9, d0 = k.detailCount;
  const W = alongZ ? b.w : b.d, D = alongZ ? b.d : b.w;
  try { drawOf(b, t, null)(k, W, D, b, mulberry32(b.seed), t); } catch { /* a model that wants its town's own buildings: left out */ }
  const paint = BUILDING_PAINT[b.kind];
  if (paint) repaint(k.pos, k.col, t0, paint);
  k.settle(t0, d0);
}

/** The street buildings a style dresses (StyleSpec neon, fireEscape, waterTank): shops and bars, offices, hotels, flats. */
const NEON_KINDS = new Set<BuildingKind>([
  'apartment', 'office', 'hotel', 'towerBlock', 'condoTower', 'shop', 'townhouse', 'bank', 'pub', 'cafe', 'nightclub',
  'casino', 'mall', 'grocery', 'bakery', 'teaHouse', 'bowlingAlley', 'theatre', 'store', 'diner',
]);

const inChunk = (b: Building, x0: number, z0: number) => {
  const bx = b.x + b.w / 2, bz = b.z + b.d / 2;
  return bx >= x0 && bx < x0 + CHUNK && bz >= z0 && bz < z0 + CHUNK;
};


/**
 * A chairlift or a conveyor. Pylons belong to the chunk their foot is in; each span is drawn by
 * whichever chunk holds its midpoint, so nothing is drawn twice where two chunks meet.
 */
function drawCableway(k: Kit, w: World, g: Work, x0: number, z0: number): void {
  const x1 = x0 + CHUNK, z1 = z0 + CHUNK;
  const belt = g.kind === 'quarry';
  const rope = belt ? hex(0x4a4642) : hex(0x55524e);
  const mast = belt ? hex(0x9a5a3a) : hex(0xb9bdc2);
  k.place(0, 0, 0, 0);
  for (let i = 0; i < g.cable.length; i++) {
    const p = g.cable[i];
    if (p.x >= x0 && p.x < x1 && p.z >= z0 && p.z < z1) {
      const foot = heightAt(w, p.x, p.z);
      const top = p.level * STEP;
      if (top > foot + 0.1) {
        k.bar([p.x, foot, p.z], [p.x, top, p.z], belt ? 0.07 : 0.06, mast);
        // the cross arm the cable rides on
        const [ax, az] = i + 1 < g.cable.length
          ? [g.cable[i + 1].x - p.x, g.cable[i + 1].z - p.z]
          : [p.x - g.cable[i - 1].x, p.z - g.cable[i - 1].z];
        const len = Math.hypot(ax, az) || 1;
        k.bar([p.x - (az / len) * 0.26, top, p.z + (ax / len) * 0.26], [p.x + (az / len) * 0.26, top, p.z - (ax / len) * 0.26], 0.05, mast);
      }
    }
    if (i + 1 >= g.cable.length) continue;
    const q = g.cable[i + 1];
    const mx = (p.x + q.x) / 2, mz = (p.z + q.z) / 2;
    if (mx < x0 || mx >= x1 || mz < z0 || mz >= z1) continue;
    const a: P3 = [p.x, p.level * STEP, p.z], b: P3 = [q.x, q.level * STEP, q.z];
    k.bar(a, b, belt ? 0.11 : 0.035, rope);
    if (!belt) {
      // the return cable below it, and a chair hanging off each
      k.bar([a[0], a[1] - 0.3, a[2]], [b[0], b[1] - 0.3, b[2]], 0.035, rope);
      for (let c = 0; c < 2; c++) {
        const t = 0.28 + c * 0.44;
        const cx = a[0] + (b[0] - a[0]) * t, cy = a[1] + (b[1] - a[1]) * t, cz = a[2] + (b[2] - a[2]) * t;
        k.bar([cx, cy, cz], [cx, cy - 0.22, cz], 0.018, hex(0x8f9aa3));
        k.box(cx, cy - 0.3, cz, 0.22, 0.08, 0.16, hex(0xe2412f));
        k.box(cx, cy - 0.3, cz - 0.07, 0.22, 0.2, 0.03, hex(0xc4351f));
      }
    }
  }
}

const YARD_TREES: Record<TownKind, number> = { rural: 0.07, suburb: 0.2, city: 0.07, metro: 0.03, mega: 0.02 };

/**
 * Every town and harbour building whose centre lies in this chunk, plus yard trees on town lawns:
 * a solid mesh and a mesh of windows and lights that come on after dark.
 */
export function buildTownChunk(w: World, cx: number, cz: number): THREE.Group | null {
  const steps = townChunkSteps(w, cx, cz);
  for (;;) { const r = steps.next(); if (r.done) return r.value; }
}

/**
 * What townChunkSteps last worked on (a building's kind, 'yards', 'landforms', 'merge'): the streamer names a
 * chunk's town steps by it in the play reports' freezes and pr.stream.max (render/stream.ts), 7 Nov 2026.
 */
export let drawing = '';

/**
 * buildTownChunk a building at a time: it pauses after each building, so the streamer (render/stream.ts) can
 * spread a dense city chunk over several frames. Nothing carries from one building to the next (drawBuilding sets
 * the style first), so another chunk built meanwhile can't disturb a paused one.
 */
export function* townChunkSteps(w: World, cx: number, cz: number): Generator<void, THREE.Group | null> {
  const k = new Kit(w);
  const x0 = cx * CHUNK, z0 = cz * CHUNK, x1 = x0 + CHUNK, z1 = z0 + CHUNK;
  for (const t of w.towns) {
    // the square, grown to any ground the town has claimed past it (docs/lobbying.html)
    let bx0 = t.x0, bz0 = t.z0, bx1 = t.x0 + t.size, bz1 = t.z0 + t.size;
    for (const i of t.claims ?? []) {
      const x = i % N, z = (i - x) / N;
      bx0 = Math.min(bx0, x); bz0 = Math.min(bz0, z); bx1 = Math.max(bx1, x + 1); bz1 = Math.max(bz1, z + 1);
    }
    if (bx0 >= x1 || bx1 <= x0 || bz0 >= z1 || bz1 <= z0) continue;
    for (const b of t.buildings) if (inChunk(b, x0, z0)) { yield* drawBuildingSteps(k, b, t); yield; }
    k.place(0, 0, 0, 0);
    drawing = 'yards';
    for (let tz = Math.max(z0, t.z0); tz < Math.min(z1, t.z0 + t.size); tz++) {
      for (let tx = Math.max(x0, t.x0); tx < Math.min(x1, t.x0 + t.size); tx++) {
        const i = idx(tx, tz);
        if (w.townId[i] !== t.id || w.blocked[i] || w.road[i] || (w.flags[i] & Flag.Field)) continue;
        if (w.lot[i] !== Lot.Lawn && w.lot[i] !== Lot.None) continue;
        if (hash2(tx, tz, 91) >= YARD_TREES[t.kind]) continue;
        const px = tx + 0.25 + hash2(tx, tz, 92) * 0.5, pz = tz + 0.25 + hash2(tx, tz, 93) * 0.5;
        tree(k, px, heightOnTile(w, tx, tz, px, pz) - 0.02, pz, 0.75 + hash2(tx, tz, 94) * 0.4, hash2(tx, tz, 95) < 0.2);
      }
    }
    // an onsen town's stream: willows and stone lanterns along its banks, steam off it (render/onsenDress.ts)
    if (t.style === 'onsen') onsenDress(k, w, t, x0, z0, x1, z1);
    // a lake town's walk along the water, and the boats on its lake (render/lakeDress.ts)
    if (t.lake) lakeDress(k, w, t, x0, z0, x1, z1);
  }
  for (const p of w.ports) for (const b of p.buildings) if (inChunk(b, x0, z0)) { yield* drawBuildingSteps(k, b, null); yield; }
  for (const b of w.countryside) if (!b.gone && inChunk(b, x0, z0)) { yield* drawBuildingSteps(k, b, null); yield; }
  // the railway stations, in the style of the town each serves
  for (const st of w.stations) if (st.building && inChunk(st.building, x0, z0)) { yield* drawBuildingSteps(k, st.building, st.town >= 0 ? w.towns[st.town] ?? null : null); yield; }
  k.glow.id = -1;
  drawing = 'landforms';
  drawLandforms(k, w, x0, z0);
  for (const g of w.works) {
    for (const b of g.buildings) if (inChunk(b, x0, z0)) { yield* drawBuildingSteps(k, b, null); yield; }
    if (g.cable.length > 1) { drawing = 'cableway'; drawCableway(k, w, g, x0, z0); }
    if (g.lifts?.length) { drawing = 'ski lifts'; drawSkiLifts(k, w, g, x0, z0, CHUNK); }
  }
  // buildings put up as scenery (the Folly collection, game/follies.ts): only their models
  for (const q of w.placed) {
    if (!isFolly(q.p) || q.x < x0 || q.x >= x1 || q.z < z0 || q.z >= z1) continue;
    drawing = q.p;
    drawFolly(k, w, q);
    yield;
  }
  drawing = 'works';
  yield;
  drawing = 'merge';
  return yield* k.meshSteps();
}
